declare global {
  interface Window {
    codexDesktop: DesktopApi;
  }
}

function loadAppTheme(): AppTheme {
  try {
    return localStorage.getItem(APP_THEME_STORAGE_KEY) === "light" ? "light" : "dark";
  } catch {
    return "dark";
  }
}

function applyAppTheme(theme: AppTheme, persist = false) {
  document.documentElement.dataset.theme = theme;
  document.documentElement.style.colorScheme = theme;
  if (!persist) return;
  try {
    localStorage.setItem(APP_THEME_STORAGE_KEY, theme);
  } catch {
    // Theme switching should still work when persistent storage is unavailable.
  }
}

function syncAppThemePreference(theme: AppTheme) {
  const pending = api.setAppTheme?.({ theme });
  void pending?.catch(() => {
    // Main-process theme sync is best effort; the renderer theme remains active.
  });
}

function isAppFontSize(value: string | undefined | null): value is AppFontSize {
  return (
    value === "small" || value === "default" || value === "medium" || value === "large"
  );
}

function loadAppFontSize(): AppFontSize {
  try {
    const value = localStorage.getItem(APP_FONT_SIZE_STORAGE_KEY);
    return isAppFontSize(value) ? value : "default";
  } catch {
    return "default";
  }
}

function applyAppFontSize(fontSize: AppFontSize, persist = false) {
  document.documentElement.dataset.fontSize = fontSize;
  if (!persist) return;
  try {
    localStorage.setItem(APP_FONT_SIZE_STORAGE_KEY, fontSize);
  } catch {
    // Font size switching should still work when persistent storage is unavailable.
  }
}

const INITIAL_STORED_APP_LANGUAGE = readStoredAppLanguage();
const INITIAL_APP_LANGUAGE = INITIAL_STORED_APP_LANGUAGE || loadAppLanguage();
applyAppLanguage(INITIAL_APP_LANGUAGE);
const INITIAL_APP_THEME = loadAppTheme();
applyAppTheme(INITIAL_APP_THEME);
const INITIAL_APP_FONT_SIZE = loadAppFontSize();
applyAppFontSize(INITIAL_APP_FONT_SIZE);

ensureBrowserDesktopApi();
const api = window.codexDesktop;
const isMacDesktop = api.platform === "darwin";
document.documentElement.classList.toggle("mac-desktop", isMacDesktop);
const appRoot = document.querySelector<HTMLDivElement>("#app");
const windowResizeRoot = document.querySelector<HTMLDivElement>("#windowResizeRoot");
void api.listTradingStrategies?.()
  .then((result) => {
    if (Array.isArray(result?.strategies)) {
      reconcileTradingStrategyCatalog(result.strategies);
      render();
    }
  })
  .catch(() => {
    // Bundled manifests remain the fail-safe catalog when runtime discovery is unavailable.
  });
void api.listPersonalStrategies?.({ includeDrafts: true })
  .then((result) => {
    state.personalStrategies.items = Array.isArray(result?.strategies) ? result.strategies : [];
    state.personalStrategies.loading = false;
    state.personalStrategies.error = result?.ok === false ? String(result?.error?.message || "个人策略加载失败") : null;
    render();
  })
  .catch((error) => {
    state.personalStrategies.loading = false;
    state.personalStrategies.error = String(error?.message || "个人策略加载失败");
    render();
  });
syncAppThemePreference(INITIAL_APP_THEME);

document.addEventListener("visibilitychange", () => {
  if (document.hidden) cancelVoiceInput();
});
window.addEventListener("beforeunload", () => {
  cancelVoiceInput();
  persistSubagentActivityStore();
});

function wechatDebugLog(event: string, payload: Record<string, unknown> = {}) {
  void api.debugLog?.({ event, payload }).catch(() => {
    // Diagnostics must not affect the chat flow.
  });
}


function rendererPerformanceDiagnosticsEnabled() {
  try {
    return /^(1|true|yes|on)$/i.test(String(localStorage.getItem(PERFORMANCE_DIAGNOSTICS_STORAGE_KEY) || "").trim());
  } catch {
    return false;
  }
}

const RENDERER_PERFORMANCE_DIAGNOSTICS_ENABLED = rendererPerformanceDiagnosticsEnabled();

function rendererPerformanceTimingStart() {
  return RENDERER_PERFORMANCE_DIAGNOSTICS_ENABLED ? performance.now() : 0;
}

function reportRendererPerformanceTiming(event: string, startedAt: number, payload: Record<string, unknown> | (() => Record<string, unknown>) = {}) {
  if (!startedAt || !RENDERER_PERFORMANCE_DIAGNOSTICS_ENABLED) return;
  const durationMs = Math.round((performance.now() - startedAt) * 10) / 10;
  if (durationMs < SLOW_RENDER_DIAGNOSTIC_THRESHOLD_MS) return;
  const resolvedPayload = typeof payload === "function" ? payload() : payload;
  void api.debugLog?.({
    event: `perf.${event}`,
    payload: {
      ...resolvedPayload,
      durationMs,
    },
  }).catch(() => {
    // Performance diagnostics are best effort only.
  });
}

function wechatMessageDebugSummary(message: any) {
  const id = firstString(message?.id, message?.message_id, message?.messageId);
  const text = wechatChannelMessageText(message);
  const attachments = wechatChannelMessageFileAttachments(message);
  return {
    id,
    textLength: text.length,
    textPreview: text.slice(0, 80),
    createdAt: firstString(message?.created_at, message?.createdAt),
    attachmentCount: attachments.length,
  };
}

function wechatRawMessageDebugSummary(value: unknown, depth = 0): unknown {
  if (depth > 3) return "[depth]";
  if (Array.isArray(value)) {
    return {
      type: "array",
      length: value.length,
      items: value.slice(0, 3).map((item) => wechatRawMessageDebugSummary(item, depth + 1)),
    };
  }
  if (!value || typeof value !== "object") {
    if (typeof value === "string") {
      if (/^eyJ|^sk-|token|authorization/i.test(value)) return "[redacted]";
      return value.length > 160 ? `${value.slice(0, 160)}...(${value.length})` : value;
    }
    return value;
  }
  const record = value as Record<string, unknown>;
  const out: Record<string, unknown> = { keys: Object.keys(record).slice(0, 40) };
  for (const [key, item] of Object.entries(record)) {
    if (/token|authorization|secret|api.?key/i.test(key)) {
      out[key] = "[redacted]";
    } else if (
      /^(?:id|message_id|messageId|type|msg_type|msgType|text|content|caption|name|file_name|fileName|filename|mime|mime_type|mimeType|content_type|contentType|size|size_bytes|sizeBytes|file_size|fileSize|url|file_url|fileUrl|download_url|downloadUrl|media_url|mediaUrl|path|local_path|localPath|object_key|objectKey|created_at|createdAt)$/i.test(
        key,
      )
    ) {
      out[key] = wechatRawMessageDebugSummary(item, depth + 1);
    } else if (item && typeof item === "object" && /(?:payload|data|body|content|attachment|attachments|file|files|media|medias|document|image|video)/i.test(key)) {
      out[key] = wechatRawMessageDebugSummary(item, depth + 1);
    }
  }
  return out;
}

function wechatAttachmentDebugSummary(attachment: Partial<MessageAttachment>) {
  const record = attachment as unknown as Record<string, unknown>;
  return {
    name: firstString(record.name, record.file_name, record.fileName),
    mime: firstString(record.mime, record.content_type, record.contentType),
    size: numericValue(record.size ?? record.size_bytes ?? record.sizeBytes),
    object_key: firstString(record.object_key, record.objectKey, record.oss_key, record.ossKey),
    url: firstString(record.url),
    local_path: firstString(record.local_path, record.localPath),
    path: firstString(record.path),
    file_path: firstString(record.file_path, record.filePath),
    preview_url: firstString(record.preview_url, record.previewUrl),
    download_url: firstString(record.download_url, record.downloadUrl),
  };
}

