function questionAnswerModelGroups() {
  return providerModelGroups(state.providerModelCatalog);
}

function questionAnswerModelOptions() {
  return questionAnswerModelGroups().flatMap((group) => group.options);
}

function questionAnswerProviderForModel(model: string | null | undefined): ProviderChatProvider | null {
  return providerForCatalogModel(state.providerModelCatalog, model);
}

function defaultProviderChatModelOption(provider: ProviderChatProvider | null | undefined) {
  const options =
    provider && provider !== VIDEO_EXPERT_PROVIDER
      ? providerModelOptions(state.providerModelCatalog, provider)
      : [];
  return options.find((option) => option.isDefault) || options[0] || null;
}

function isQuestionAnswerThreadId(threadId: string | null | undefined) {
  const provider = providerFromThreadId(threadId);
  return Boolean(provider && provider !== VIDEO_EXPERT_PROVIDER);
}
