function rememberInterruptedInteraction(
  tombstones: Set<string>,
  interactionId: string,
) {
  tombstones.delete(interactionId);
  tombstones.add(interactionId);
  while (tombstones.size > MAX_INTERRUPTED_INTERACTION_TOMBSTONES) {
    const oldest = tombstones.values().next().value;
    if (!oldest) break;
    tombstones.delete(oldest);
  }
}
