function createAutoTaskDraft(groupId: string | null | undefined = initialNewThreadGroupId): AutoTaskDraftState {
  const now = new Date();
  now.setMinutes(now.getMinutes() + 10);
  const pad = (value: number) => String(value).padStart(2, "0");
  return {
    id: null,
    name: "",
    description: "",
    groupId: knownThreadGroupId(groupId),
    frequency: "once",
    date: `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`,
    time: `${pad(now.getHours())}:${pad(now.getMinutes())}`,
    error: null,
  };
}

function openAutoTaskEditDialog(taskId: string | null | undefined) {
  const task = state.autoTaskItems.find((item) => item.id === taskId);
  if (!task) return false;
  state.autoTaskMenuTaskId = null;
  state.autoTaskDraft = {
    id: task.id,
    name: task.name,
    description: task.description,
    groupId: knownThreadGroupId(task.groupId),
    frequency: task.frequency,
    date: task.date,
    time: task.time,
    error: null,
  };
  state.autoTaskPicker = null;
  state.autoTaskCalendarMonth = task.date;
  state.autoTaskDialogOpen = true;
  render();
  return true;
}

