type ComposerContextAction = "favorite" | "cut" | "copy" | "paste" | "delete";

type ComposerTextSelection = {
  start: number;
  end: number;
  text: string;
};

const COMPOSER_CONTEXT_MENU_LABELS: Record<ComposerContextAction, string> = {
  favorite: "\u6536\u85cf",
  cut: "剪切",
  copy: "复制",
  paste: "粘贴",
  delete: "删除",
};

function showComposerPasteContextMenu(x: number, y: number, input: HTMLTextAreaElement) {
  closeComposerPasteContextMenu();
  const selection = composerTextSelection(input);
  const actions: ComposerContextAction[] = selection ? ["favorite", "cut", "copy", "paste", "delete"] : ["paste"];
  const menu = document.createElement("div");
  menu.className = "copy-context-menu composer-paste-context-menu";
  menu.setAttribute("role", "menu");
  actions.forEach((action) => {
    if (action === "delete") {
      const separator = document.createElement("div");
      separator.className = "context-menu-separator";
      separator.setAttribute("role", "separator");
      menu.append(separator);
    }
    const button = document.createElement("button");
    button.type = "button";
    button.setAttribute("role", "menuitem");
    button.dataset.contextAction = action;
    button.textContent = COMPOSER_CONTEXT_MENU_LABELS[action];
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      closeComposerPasteContextMenu();
      void handleComposerContextMenuAction(input, action, selection);
    });
    menu.append(button);
  });
  document.body.append(menu);
  composerPasteContextMenu = menu;
  const rect = menu.getBoundingClientRect();
  const left = Math.min(Math.max(8, x), Math.max(8, window.innerWidth - rect.width - 8));
  const top = Math.min(Math.max(8, y), Math.max(8, window.innerHeight - rect.height - 8));
  menu.style.left = `${left}px`;
  menu.style.top = `${top}px`;
}

async function handleComposerContextMenuAction(
  input: HTMLTextAreaElement,
  action: ComposerContextAction,
  selection: ComposerTextSelection | null,
) {
  if (action === "paste") {
    restoreComposerTextSelection(input, selection);
    await pasteIntoComposerFromContextMenu(input);
    return;
  }

  const activeSelection = restoreComposerTextSelection(input, selection) ?? composerTextSelection(input);
  if (!activeSelection) return;

  if (action === "favorite") {
    await savePromptFavorite(activeSelection.text);
    return;
  }

  if (action === "copy") {
    await copyComposerSelection(activeSelection.text);
    return;
  }

  if (action === "cut") {
    await cutComposerSelection(input, activeSelection);
    return;
  }

  deleteComposerSelection(input, activeSelection);
}

function composerTextSelection(input: HTMLTextAreaElement): ComposerTextSelection | null {
  const value = input.value || "";
  const start = input.selectionStart ?? 0;
  const end = input.selectionEnd ?? start;
  if (end <= start) return null;
  return { start, end, text: value.slice(start, end) };
}

function restoreComposerTextSelection(
  input: HTMLTextAreaElement,
  selection: ComposerTextSelection | null,
): ComposerTextSelection | null {
  input.focus({ preventScroll: true });
  if (!selection) return null;
  const value = input.value || "";
  const start = clampNumber(selection.start, 0, value.length);
  const end = clampNumber(selection.end, start, value.length);
  input.setSelectionRange(start, end);
  return end > start ? { start, end, text: value.slice(start, end) } : null;
}

async function copyComposerSelection(text: string) {
  if (!text) return;
  if (copySelectedTextWithNativeCommand()) {
    showToast("复制成功", 1500);
    return;
  }
  await copyTextToClipboard(text);
}

async function cutComposerSelection(input: HTMLTextAreaElement, selection: ComposerTextSelection) {
  if (cutSelectedTextWithNativeCommand()) {
    syncComposerTextAfterProgrammaticEdit(input);
    showToast("已剪切", 1500);
    return;
  }
  if (!(await writeTextToClipboard(selection.text))) {
    showToast("剪切失败，请手动选择文本", 2500);
    return;
  }
  deleteComposerSelection(input, selection);
  showToast("已剪切", 1500);
}

function deleteComposerSelection(input: HTMLTextAreaElement, selection: ComposerTextSelection) {
  const activeSelection = restoreComposerTextSelection(input, selection);
  if (!activeSelection) return;
  if (deleteSelectedTextWithNativeCommand()) {
    syncComposerTextAfterProgrammaticEdit(input);
    return;
  }
  const value = input.value || "";
  const nextValue = `${value.slice(0, activeSelection.start)}${value.slice(activeSelection.end)}`;
  input.value = nextValue;
  input.setSelectionRange(activeSelection.start, activeSelection.start);
  syncComposerTextAfterProgrammaticEdit(input);
  input.dispatchEvent(new Event("input", { bubbles: true }));
}

function copySelectedTextWithNativeCommand() {
  try {
    return Boolean(document.execCommand?.("copy"));
  } catch {
    return false;
  }
}

function cutSelectedTextWithNativeCommand() {
  try {
    return Boolean(document.execCommand?.("cut"));
  } catch {
    return false;
  }
}

function deleteSelectedTextWithNativeCommand() {
  try {
    return Boolean(document.execCommand?.("delete"));
  } catch {
    return false;
  }
}

function closeComposerPasteContextMenu() {
  composerPasteContextMenu?.remove();
  composerPasteContextMenu = null;
}

function closeAllContextMenus() {
  closeCopyContextMenu();
  closeComposerPasteContextMenu();
  closeThreadHistoryPopover();
  if (state.threadMenu || state.threadGroupMenu || state.contactMenu) {
    state.threadMenu = null;
    state.threadGroupMenu = null;
    state.contactMenu = null;
    render();
  }
}

function closeCopyContextMenu() {
  copyContextMenu?.remove();
  copyContextMenu = null;
}

function normalizeCopyText(text: string) {
  return text.replace(/\u00A0/g, " ").replace(/[ \t]+\n/g, "\n").replace(/\n{3,}/g, "\n\n").trim();
}

function isComposerDropAllowed(event: DragEvent) {
  if (shouldShowLoginWindow() || state.marketplace.importDialogOpen) return false;
  if (!state.currentThreadId || !event.dataTransfer) return false;
  if (!isComposerDropTarget(event.target)) return false;
  return (
    dragDataHasFiles(event.dataTransfer) || dragDataMayContainFiles(event.dataTransfer)
  );
}

function isComposerDropTarget(target: EventTarget | null) {
  const element = target instanceof Element ? target : null;
  if (!element || !root.contains(element)) return false;
  const panel = element.closest<HTMLElement>(".chat-panel");
  if (!panel || panel.classList.contains("auto-task-chat-panel")) return false;
  return Boolean(panel.querySelector("#composerForm"));
}

function dragDataMayContainFiles(dataTransfer: DataTransfer) {
  const types = Array.from(dataTransfer.types || []);
  if (!types.length) return true;
  return types.some((type) => type === "text/plain" || type === "text/uri-list" || type === "text/html" || isFileLikeDropType(type));
}

function dragDataHasFiles(dataTransfer: DataTransfer) {
  if (Array.from(dataTransfer.files || []).some((file) => file.size > 0 || file.name)) return true;
  const types = Array.from(dataTransfer.types || []);
  if (types.includes("Files")) return true;
  return types.some((type) => type === "text/uri-list" || type === "text/html" || isFileLikeDropType(type));
}

async function handleComposerDrop(event: DragEvent) {
  const dataTransfer = event.dataTransfer;
  if (!dataTransfer) return;
  const dropped = droppedFileSnapshot(dataTransfer);
  if (!dropped.files.length && !dropped.paths.size) {
    dropped.files.push(...(await filesFromDroppedFileSystemHandles(dataTransfer)));
  }
  const handledFolders = await queueDroppedFolders(dropped.paths);
  const files = await collectDroppedFiles(dropped);
  if (files.length) {
    queueFiles(files);
    focusComposerInputAfterDrop();
    return;
  }
  if (handledFolders) {
    focusComposerInputAfterDrop();
    return;
  }
  showToast("没有识别到可上传文件，请先把微信文件保存到本地后再拖入。", 4000);
}

function focusComposerInputAfterDrop() {
  window.requestAnimationFrame(() => {
    const input = root.querySelector<HTMLTextAreaElement>("#composerInput");
    if (!input) return;
    input.focus({ preventScroll: true });
    const position = input.value.length;
    input.setSelectionRange(position, position);
  });
}

async function pasteIntoComposer(input: HTMLTextAreaElement, options: { fallbackText?: string } = {}) {
  const targetThreadId = firstString(
    input.closest<HTMLFormElement>("#composerForm")?.dataset.threadId,
  );
  if (!targetThreadId) return;
  const targetValue = input.value;
  const targetSelectionStart = input.selectionStart ?? targetValue.length;
  const targetSelectionEnd = input.selectionEnd ?? targetSelectionStart;
  input.focus({ preventScroll: true });
  try {
    const payload = await readComposerClipboardPayload(options.fallbackText || "");
    const currentInput = root.querySelector<HTMLTextAreaElement>("#composerInput");
    const currentThreadId = firstString(
      currentInput?.closest<HTMLFormElement>("#composerForm")?.dataset.threadId,
    );
    if (!currentInput || currentThreadId !== targetThreadId) {
      showToast("输入框已切换，请重新粘贴", 2200);
      return;
    }
    if (currentInput !== input && currentInput.value === targetValue) {
      currentInput.setSelectionRange(
        Math.min(targetSelectionStart, currentInput.value.length),
        Math.min(targetSelectionEnd, currentInput.value.length),
      );
    }
    const folders = composerClipboardFolders(payload);
    const files = composerClipboardFiles(payload);
    const handledFolders = queueComposerFolders(folders);
    if (files.length) queueFiles(files);
    if (handledFolders || files.length) {
      focusComposerInputAfterDrop();
      return;
    }
    const pastedText = typeof payload?.text === "string" ? payload.text : "";
    if (queueLargePastedTextAsAttachment(pastedText)) {
      currentInput.focus({ preventScroll: true });
      return;
    }
    const text = firstString(pastedText);
    if (text) {
      insertTextIntoComposer(currentInput, text);
      return;
    }
    showToast("剪贴板没有可粘贴的内容", 2200);
  } catch (error) {
    showToast(`粘贴失败：${errorMessage(error)}`, 4000);
  }
}

async function pasteIntoComposerFromContextMenu(input: HTMLTextAreaElement) {
  if (!api.pasteFocusedElement) {
    await pasteIntoComposer(input);
    return;
  }
  input.focus({ preventScroll: true });
  const previousPasteEventAt = lastComposerPasteEventAt;
  try {
    await api.pasteFocusedElement();
    await new Promise((resolve) => window.setTimeout(resolve, 120));
    if (lastComposerPasteEventAt <= previousPasteEventAt) {
      await pasteIntoComposer(input);
    }
  } catch {
    await pasteIntoComposer(input);
  }
}

async function readComposerClipboardPayload(fallbackText = ""): Promise<ComposerClipboardPayload> {
  if (api.readClipboardForComposer) {
    try {
      const payload = await api.readClipboardForComposer();
      if (hasComposerClipboardAttachments(payload) || firstString(payload?.text) || !fallbackText) return payload;
      return { type: "text", text: fallbackText };
    } catch (error) {
      if (fallbackText) return { type: "text", text: fallbackText };
      throw error;
    }
  }
  const text = fallbackText || (await navigator.clipboard?.readText?.().catch(() => ""));
  return { type: text ? "text" : "empty", text };
}

function composerClipboardFiles(payload: ComposerClipboardPayload | null | undefined) {
  return Array.from(payload?.files || [])
    .map(fileFromComposerClipboardFile)
    .filter((file): file is File => file !== null);
}

function composerClipboardFolders(payload: ComposerClipboardPayload | null | undefined): ComposerFolderDescriptor[] {
  return Array.from(payload?.folders || []).flatMap((folder) => {
    const folderPath = firstString(folder?.path);
    if (!folderPath) return [];
    return [
      {
        path: folderPath,
        name: firstString(folder?.name, folderNameFromPath(folderPath)) || folderPath,
      },
    ];
  });
}

function hasComposerClipboardAttachments(payload: ComposerClipboardPayload | null | undefined) {
  return (
    Array.from(payload?.files || []).some((file) => Boolean(file?.base64)) ||
    composerClipboardFolders(payload).length > 0
  );
}

function fileFromComposerClipboardFile(file: ComposerClipboardFile) {
  if (!file.base64) return null;
  const bytes = bytesFromBase64(file.base64);
  return attachLocalFileMetadata(
    new File([bytes.buffer as ArrayBuffer], file.name || "clipboard-file", {
      type: file.mime || "application/octet-stream",
      lastModified: Date.now(),
    }),
    {
      path: file.path,
      queueFingerprint: file.fileKey,
    },
  );
}

function insertTextIntoComposer(input: HTMLTextAreaElement, text: string) {
  input.focus({ preventScroll: true });
  // Preserve Chromium's native undo stack for paste/context-menu text insertion.
  if (insertTextIntoComposerWithNativeUndo(text)) {
    syncComposerTextAfterProgrammaticEdit(input);
    return;
  }

  const value = input.value || "";
  const selectionStart = input.selectionStart ?? value.length;
  const selectionEnd = input.selectionEnd ?? selectionStart;
  const nextValue = `${value.slice(0, selectionStart)}${text}${value.slice(selectionEnd)}`;
  const nextCursor = selectionStart + text.length;
  input.value = nextValue;
  input.setSelectionRange(nextCursor, nextCursor);
  syncComposerTextAfterProgrammaticEdit(input);
  input.dispatchEvent(new Event("input", { bubbles: true }));
}

function insertTextIntoComposerWithNativeUndo(text: string) {
  try {
    return Boolean(document.execCommand?.("insertText", false, text));
  } catch {
    return false;
  }
}

function syncComposerTextAfterProgrammaticEdit(input: HTMLTextAreaElement) {
  const triggerInserted = wasComposerMentionTriggerInserted(
    state.composerText,
    input.value,
    input.selectionStart ?? input.value.length,
  );
  state.composerText = input.value;
  applyTradingExpertCustomIndicatorMentions(input.value);
  reconcileComposerThreadReferences(input.value);
  reconcileComposerMediaReferences(input.value);
  rememberActiveComposerDraft();
  syncComposerMentionPopovers(triggerInserted);
  syncComposerMentionHighlights();
  syncComposerSendButton();
}

function hydrateFixedChatModel() {
  const preferred = savedChatModelPreference || state.settings.model;
  const selected = chatModelOptions.find((option) => option.value === preferred);
  state.settings.model = selected?.value || defaultChatModelOption().value;
}

function consumptionVisibleQuestion(text: string, attachments: MessageAttachment[] = []) {
  const visibleText = String(text || "").trim();
  const safeAttachments = dedupeMessageAttachments(attachments);
  const names = [...new Set(safeAttachments
    .map((attachment) => String(attachment.name || "").trim().split(/[\\/]/).filter(Boolean).at(-1) || "")
    .filter(Boolean))];
  const prefix = safeAttachments.some(isImageAttachment) ? "图片" : "附件";
  const attachmentSummary = safeAttachments.length
    ? names.length ? `${prefix}：${names.join("、")}` : prefix
    : "";
  return [visibleText, attachmentSummary].filter(Boolean).join("\n");
}

async function listThreadGroupHistory(cwd: string, allPages = false) {
  const threads: any[] = [];
  const seenCursors = new Set<string>();
  let cursor: string | null = null;
  while (true) {
    const result = await api.listThreads({ cwd, limit: 40, ...(cursor ? { cursor } : {}) });
    if (!Array.isArray(result?.data)) throw new Error("Invalid conversation list response");
    threads.push(...result.data);
    const nextCursor = firstString(result.nextCursor, result.next_cursor);
    if (!allPages || !nextCursor) return threads;
    if (seenCursors.has(nextCursor)) throw new Error("Repeated conversation list cursor");
    seenCursors.add(nextCursor);
    cursor = nextCursor;
  }
}

async function loadThreads(options: { allPages?: boolean } = {}) {
  const workspaceGeneration = authenticatedWorkspaceGeneration;
  const isCurrentWorkspace = () =>
    workspaceGeneration === authenticatedWorkspaceGeneration && state.auth.authenticated;
  if (!isCurrentWorkspace()) return false;
  const blankThread = currentBlankThread();
  await syncThreadGroupWorkspaces({ renderAfter: false });
  if (!isCurrentWorkspace()) return false;
  let groupMappingChanged = false;
  const groupedThreadResults = await Promise.all(
    sortedThreadGroups().map(async (group) => {
      const groupCwd = workspaceForGroupId(group.id);
      try {
        const threads = await listThreadGroupHistory(groupCwd, options.allPages);
        return { group, groupCwd, threads };
      } catch (error) {
        if (options.allPages) throw error;
        console.warn("Failed to list threads for group", group.id, error);
        return { group, groupCwd, threads: [] as any[] };
      }
    }),
  );
  if (!isCurrentWorkspace()) return false;
  const remoteThreads = groupedThreadResults
    .flatMap(({ group, groupCwd, threads }) =>
      threads
        .map((record: any) => {
          const recordThreadId = firstString(record?.id, record?.threadId, record?.thread_id);
          const recordIsInternalSubagent = Boolean(recordThreadId && confirmInternalSubagentThreadRecord(record));
          if (recordThreadId && (recordIsInternalSubagent || internalSubagentThreadIds.has(recordThreadId))) {
            return { record, thread: null };
          }
          return { record, thread: mapThread(record) };
        })
        .filter((entry: { record: any; thread: ConversationSummary | null }): entry is { record: any; thread: ConversationSummary } => {
          const thread = entry.thread;
          if (!thread) return false;
          if (hiddenThreadIds.has(thread.id)) return false;
          if (isSparseBlankThreadListRecord(entry.record, thread)) return false;
          if (isDesktopAgentInternalThread(thread)) {
            hideDesktopAgentInternalThread(thread.id);
            return false;
          }
          if (isAutoTaskOwnedThreadId(thread.id)) return false;
          if (rememberThreadWorkspace(thread.id, groupCwd)) {
            groupMappingChanged = true;
          }
          if (!threadGroupById(threadGroupByThreadId[thread.id])) {
            threadGroupByThreadId[thread.id] = group.id;
            groupMappingChanged = true;
          }
          return true;
        }),
    )
    .map(({ thread }) => thread);
  const channelThreads = Object.values(state.channels).filter(shouldShowChannelInMainThreads).map(mapChannelThread);
  const localThreads = state.threads.filter((thread) =>
    !hiddenThreadIds.has(thread.id) &&
    !internalSubagentThreadIds.has(thread.id) &&
    !isChannelThread(thread) &&
    !isProviderThread(thread),
  );
  const providerThreads = state.threads.filter((thread) => !hiddenThreadIds.has(thread.id) && isProviderThread(thread));
  const loadedThreads = mergeThreads(
    state.threads.length ? mergeThreads(localThreads, remoteThreads) : remoteThreads,
    localGroupChatSummaries(),
  );
  state.threads = sortThreadsForList(mergeThreads(loadedThreads, channelThreads));
  if (blankThread) {
    state.threads = [blankThread, ...state.threads.filter((thread) => thread.id !== blankThread.id)];
  }
  state.threads = sortThreadsForList(mergeThreads(state.threads, providerThreads));
  if (blankThread) {
    state.threads = [blankThread, ...state.threads.filter((thread) => thread.id !== blankThread.id)];
  }
  const defaultGroupMappingChanged = assignThreadsToDefaultGroup(mergeThreads(state.threads, autoTaskThreadSummaries()));
  const autoTaskGroupMappingChanged = syncAutoTaskThreadGroupMappings();
  if (defaultGroupMappingChanged || groupMappingChanged || autoTaskGroupMappingChanged) {
    // Default-group migration also pins connected external channel summaries;
    // refresh the list immediately so the global pinned section reflects the
    // new preference during the first render after startup.
    if (defaultGroupMappingChanged) state.threads = sortThreadsForList(state.threads);
    saveThreadPreferences();
  }
  ensureTopLevelBlankThreadForList({ activateIfMissingSelection: true });
  ensureInitialBlankChatThread();
  pruneThreadAuxiliaryState(new Set(state.threads.map((thread) => thread.id)));
  scheduleMissingAssistantPreviewHydration();
  scheduleRecentThreadDetailPrefetch();
  return true;
}

async function reconcilePersistedThreadContinuations() {
  if (typeof api.listContinuationTransactions !== "function") {
    threadContinuationReconciliationReady = true;
    return true;
  }
  let result: any;
  try {
    result = await api.listContinuationTransactions();
  } catch (error) {
    console.warn("[continuation] failed to reconcile persisted transactions", error);
    threadContinuationReconciliationReady = false;
    return false;
  }
  const transactions = Array.isArray(result?.data) ? result.data : Array.isArray(result) ? result : [];
  let changed = false;
  for (const transaction of transactions) {
    const sourceThreadId = firstString(transaction?.sourceThreadId, transaction?.source_thread_id);
    const targetThreadId = firstString(transaction?.targetThreadId, transaction?.target_thread_id);
    const operationId = firstString(transaction?.operationId, transaction?.operation_id);
    const status = firstString(transaction?.status);
    if (!sourceThreadId || !operationId) continue;
    const existing = threadContinuationByOperationId[operationId];
    const parsed = parseThreadContinuationInjectedItems(Array.isArray(transaction?.items) ? transaction.items : []);
    const copiedMessages = parsed.copiedMessages.length ? parsed.copiedMessages : existing?.copiedMessages || [];
    const olderSummary = parsed.olderSummary || existing?.olderSummary || "";
    const sourceThread = threadById(sourceThreadId);
    const sourceTitle = firstString(
      transaction?.sourceTitle,
      transaction?.source_title,
      existing?.sourceTitle,
      sourceThread ? threadListDisplayName(sourceThread) : null,
    ) || "原任务";
    const continuationTitle = nextThreadContinuationTitle(sourceTitle);
    const transactionUpdatedAt = firstString(transaction?.updatedAt, transaction?.updated_at) || new Date().toISOString();
    if (status === "ready") {
      if (copiedMessages.length !== 2) continue;
      threadContinuationByOperationId[operationId] = {
        version: 1,
        operationId,
        sourceThreadId,
        sourceDeleted: existing?.sourceDeleted === true || hiddenThreadIds.has(sourceThreadId),
        continuationThreadId: null,
        sourceTitle,
        continuationTitle: null,
        status: "ready",
        triggeredAt: existing?.triggeredAt || transactionUpdatedAt,
        completedAt: null,
        answerTurnId: firstString(transaction?.answerTurnId, transaction?.answer_turn_id, existing?.answerTurnId),
        anchorMessageId: firstString(transaction?.anchorMessageId, transaction?.anchor_message_id, existing?.anchorMessageId),
        olderSummary,
        copiedMessages,
        originalTokens: numericValue(transaction?.originalTokens ?? transaction?.original_tokens) ?? existing?.originalTokens ?? null,
        budgetTokens: numericValue(transaction?.budgetTokens ?? transaction?.budget_tokens) ?? existing?.budgetTokens ?? null,
        needsNewOperation: false,
        error: null,
      };
      changed = true;
      continue;
    }
    const interruptedStatuses = new Set(["starting", "started", "injecting", "injected", "naming", "failed", "target_deleted"]);
    if (status && interruptedStatuses.has(status)) {
      const targetWasDeleted = status === "target_deleted";
      threadContinuationByOperationId[operationId] = {
        version: 1,
        operationId,
        sourceThreadId,
        sourceDeleted: existing?.sourceDeleted === true || hiddenThreadIds.has(sourceThreadId),
        continuationThreadId: null,
        sourceTitle,
        continuationTitle: null,
        status: targetWasDeleted && copiedMessages.length === 2 ? "ready" : "failed",
        triggeredAt: existing?.triggeredAt || transactionUpdatedAt,
        completedAt: null,
        answerTurnId: firstString(transaction?.answerTurnId, transaction?.answer_turn_id, existing?.answerTurnId),
        anchorMessageId: firstString(transaction?.anchorMessageId, transaction?.anchor_message_id, existing?.anchorMessageId),
        olderSummary,
        copiedMessages,
        originalTokens: numericValue(transaction?.originalTokens ?? transaction?.original_tokens) ?? existing?.originalTokens ?? null,
        budgetTokens: numericValue(transaction?.budgetTokens ?? transaction?.budget_tokens) ?? existing?.budgetTokens ?? null,
        needsNewOperation: true,
        error: targetWasDeleted
          ? null
          : firstString(transaction?.error) || "上次续接被客户端重启中断，请重试",
      };
      changed = true;
      continue;
    }
    if (status !== "completed" || !targetThreadId || hiddenThreadIds.has(targetThreadId) || !copiedMessages.length) continue;

    threadContinuationByOperationId[operationId] = {
      version: 1,
      operationId,
      sourceThreadId,
      sourceDeleted: existing?.sourceDeleted === true || hiddenThreadIds.has(sourceThreadId),
      continuationThreadId: targetThreadId,
      sourceTitle,
      continuationTitle,
      status: "completed",
      triggeredAt: existing?.triggeredAt || transactionUpdatedAt,
      completedAt: firstString(transaction?.updatedAt, transaction?.updated_at, existing?.completedAt) || transactionUpdatedAt,
      answerTurnId: firstString(transaction?.answerTurnId, transaction?.answer_turn_id, existing?.answerTurnId),
      anchorMessageId: firstString(transaction?.anchorMessageId, transaction?.anchor_message_id, existing?.anchorMessageId),
      olderSummary,
      copiedMessages,
      originalTokens: numericValue(transaction?.originalTokens ?? transaction?.original_tokens) ?? existing?.originalTokens ?? null,
      budgetTokens: numericValue(transaction?.budgetTokens ?? transaction?.budget_tokens) ?? existing?.budgetTokens ?? null,
      needsNewOperation: false,
      error: null,
    };
    const sourceGroupId = firstString(transaction?.sourceGroupId, transaction?.source_group_id);
    const targetGroupId = sourceGroupId && threadGroupById(sourceGroupId)
      ? sourceGroupId
      : groupIdForThreadContext(sourceThreadId);
    threadGroupByThreadId[targetThreadId] = targetGroupId;
    const cwd = firstString(transaction?.cwd);
    if (cwd) rememberThreadWorkspace(targetThreadId, cwd);
    threadNameOverrides[targetThreadId] = continuationTitle;
    changed = true;
  }
  for (const [operationId, record] of Object.entries(threadContinuationByOperationId)) {
    if (latestThreadContinuationRecordForSource(record.sourceThreadId)?.operationId === operationId) continue;
    delete threadContinuationByOperationId[operationId];
    threadContinuationCreationPromises.delete(operationId);
    changed = true;
  }
  for (const record of Object.values(threadContinuationByOperationId)) {
    const sourceThreadId = record.sourceThreadId;
    if (
      record.status !== "awaiting_answer" ||
      !record.answerTurnId ||
      hiddenThreadIds.has(sourceThreadId) ||
      !threadById(sourceThreadId)
    ) continue;
    // Reconcile an answer that may have completed while the renderer was down.
    // Hydration either finds the exact final output and continues, or releases
    // the stale answerTurnId so a later real turn can bind normally.
    scheduleCompletedTurnHydration(sourceThreadId, record.answerTurnId);
  }
  if (changed && !saveThreadPreferences()) {
    console.warn("[continuation] reconciled transaction metadata could not be saved locally");
  }
  threadContinuationReconciliationReady = true;
  return true;
}

function wireComposerSkillMentionPopoverDismissal() {
  document.addEventListener(
    "pointerdown",
    (event) => {
      if (
        event.button !== 0 ||
        (!state.composerSkillMention.open &&
          !state.composerMediaMention.open)
      )
        return;
      const target = event.target instanceof Element ? event.target : null;
      if (
        target?.closest(
          '.composer-skill-popover, .composer-media-mention-popover, [data-action="toggle-trading-expert-mention-menu"]',
        )
      )
        return;
      if (
        target?.closest(
          ".prompt-favorite-dialog, .prompt-favorite-delete-dialog, .prompt-favorite-backdrop, .prompt-favorite-delete-backdrop",
        )
      )
        return;
      dismissComposerSkillMentionPopover();
    },
    true,
  );
}

function wireThreadHistoryPopoverDismissal() {
  document.addEventListener(
    "pointerdown",
    (event) => {
      if (event.button !== 0 || !threadHistoryPopover) return;
      const popover = root.querySelector<HTMLElement>(".thread-history-popover");
      const target = event.target instanceof Element ? event.target : null;
      const rect = popover?.getBoundingClientRect();
      const insidePopoverBounds = Boolean(
        rect &&
          event.clientX >= rect.left &&
          event.clientX <= rect.right &&
          event.clientY >= rect.top &&
          event.clientY <= rect.bottom,
      );
      if (target?.closest(".thread-history-popover") || insidePopoverBounds) return;
      closeThreadHistoryPopover();
    },
    true,
  );
}

function ensureInitialBlankChatThread(options: { allowWithoutServer?: boolean } = {}) {
  if ((!state.serverReady && !options.allowWithoutServer) || state.activeView !== "chat" || state.currentThreadId || currentBlankThread()) return;
  const visibleChatThreads = state.threads.filter((thread) => !isChannelThread(thread) || thread.channel_type === "direct");
  if (visibleChatThreads.length) return;
  void createBlankThreadForList({ activate: true, allowWithoutServer: options.allowWithoutServer, forceLocal: true });
}

async function loadChannels(options: { renderAfter?: boolean } = {}) {
  if (!CHANNELS_ENABLED) return;
  if (!api.listChannels) return;
  try {
    const result = await api.listChannels({ limit: 100 });
    const channels = arrayFromResponse<ChannelSummary>(result);
    state.channels = {};
    for (const channel of channels) {
      const id = channelIdValue(channel);
      if (id) {
        const nextChannel = { ...channel, id };
        rememberLoadedChannelReadOverride(id, nextChannel);
        state.channels[id] = applyChannelReadOverride(nextChannel);
      }
    }
    mergeChannelThreads();
  } catch (error) {
    showToast(`频道加载失败：${errorMessage(error)}`, 5000);
  } finally {
    if (options.renderAfter !== false) render();
  }
}

async function loadExternalChannels(options: { renderAfter?: boolean; force?: boolean; syncRuntime?: boolean } = {}) {
  if (!api.listExternalChannels) return;
  if (state.externalChannels.loading) return;
  if (state.externalChannels.loaded && !options.force) return;
  state.externalChannels.loading = true;
  state.externalChannels.error = null;
  if (options.renderAfter !== false) render();
  try {
    const result = await api.listExternalChannels();
    const items = arrayFromResponse<ExternalChannelSummary>(result)
      .map(normalizeExternalChannel)
      .filter((item): item is ExternalChannelSummary => Boolean(item));
    state.externalChannels.items = items.length ? items : EXTERNAL_CHANNEL_FALLBACKS.map((channel) => ({ ...channel }));
    if (firstBoolean(result?.fallback, result?.raw?.fallback) === true) {
      console.warn("External channels fallback response", firstString(result?.message, result?.raw?.message));
    }
    state.externalChannels.loaded = true;
    if (options.syncRuntime !== false) {
      syncWechatChannelRuntimeFromItems();
      syncFeishuChannelRuntimeFromItems();
      syncTelegramChannelRuntimeFromItems();
    }
  } catch (error) {
    state.externalChannels.error = null;
    console.warn("Failed to load external channels", error);
  } finally {
    state.externalChannels.loading = false;
    if (options.renderAfter !== false) render();
  }
}

async function ensureExternalChannelsBackend(options: { refreshAfter?: boolean } = {}) {
  if (!api.ensureExternalChannelsBackend) return null;
  try {
    const result = await api.ensureExternalChannelsBackend();
    if (options.refreshAfter && api.listExternalChannels) {
      await loadExternalChannels({ force: true, renderAfter: false });
    }
    return result;
  } catch (error) {
    console.warn("Failed to ensure external channels backend", error);
    return null;
  }
}

function normalizeExternalChannel(value: unknown): ExternalChannelSummary | null {
  if (!value || typeof value !== "object") return null;
  const record = value as Record<string, unknown>;
  const id = firstString(record.id, record.channel, record.channel_id, record.channelId);
  if (!isExternalChannelId(id)) return null;
  return {
    id,
    name: firstString(record.name, record.title) || EXTERNAL_CHANNEL_FALLBACKS.find((channel) => channel.id === id)?.name || id,
    description:
      firstString(record.description, record.subtitle, record.detail) ||
      EXTERNAL_CHANNEL_FALLBACKS.find((channel) => channel.id === id)?.description ||
      "",
    status: firstString(record.status),
    connected: Boolean(record.connected),
    account_label: externalChannelAccountLabelFromRecord(record),
    monitor_running: Boolean(record.monitor_running ?? record.monitorRunning),
    conversation_id: firstString(record.conversation_id, record.conversationId),
    desktop_thread_id: firstString(record.desktop_thread_id, record.desktopThreadId),
    bot_username: firstString(record.bot_username, record.botUsername),
    bot_link: firstString(record.bot_link, record.botLink),
    start_group_link: firstString(record.start_group_link, record.startGroupLink),
  };
}

function externalChannelAccountLabelFromRecord(record: Record<string, unknown>) {
  const account = plainRecord(record.account);
  const profile = plainRecord(record.profile);
  const user = plainRecord(record.user);
  const wechatUser =
    plainRecord(record.wechat_user) ||
    plainRecord(record.wechatUser) ||
    plainRecord(record.wechat_profile) ||
    plainRecord(record.wechatProfile);
  const accountProfile = plainRecord(account?.profile);
  const label = firstString(
    record.account_label,
    record.accountLabel,
    record.nickname,
    record.nick_name,
    record.nickName,
    record.display_name,
    record.displayName,
    wechatUser?.nickname,
    wechatUser?.nick_name,
    wechatUser?.nickName,
    wechatUser?.display_name,
    wechatUser?.displayName,
    profile?.nickname,
    profile?.nick_name,
    profile?.nickName,
    profile?.display_name,
    profile?.displayName,
    accountProfile?.nickname,
    accountProfile?.nick_name,
    accountProfile?.nickName,
    accountProfile?.display_name,
    accountProfile?.displayName,
    account?.nickname,
    account?.nick_name,
    account?.nickName,
    account?.display_name,
    account?.displayName,
    user?.nickname,
    user?.nick_name,
    user?.nickName,
    user?.display_name,
    user?.displayName,
  );
  return isInternalExternalChannelAccountLabel(label) ? null : label;
}

async function openExternalChannel(channelId: ExternalChannelId) {
  if (channelId === "telegram") {
    const telegram = externalChannelItems().find((channel) => channel.id === "telegram");
    if (telegram?.connected) {
      await openConnectedTelegramChannel(telegram);
      return;
    }
    startTelegramChannelLogin();
    return;
  }
  if (channelId === "feishu") {
    const feishu = externalChannelItems().find((channel) => channel.id === "feishu");
    if (feishu?.connected) {
      await openConnectedFeishuChannel(feishu);
      return;
    }
    if (openPreparedFeishuChannelLogin()) return;
    await startFeishuChannelLogin();
    return;
  }
  const wechat = externalChannelItems().find((channel) => channel.id === "wechat");
  if (wechat?.connected) {
    await openConnectedWechatChannel(wechat);
    return;
  }
  await startWechatChannelLogin();
}

function prefetchWechatChannelLogin() {
  if (!api.startExternalChannelLogin || wechatChannelIsConnected()) return;
  void startWechatChannelLogin({ openDialog: false, renderAfter: false });
}

function prefetchFeishuChannelLogin() {
  if (!api.startExternalChannelLogin || feishuChannelIsConnected()) return;
  if (canReuseFeishuChannelLogin(prefetchedFeishuChannelLogin)) return;
  void prepareFeishuChannelLogin();
}

function primeExternalChannelMenu() {
  void (async () => {
    await ensureExternalChannelsBackend();
    await loadExternalChannels({ force: false });
    prefetchWechatChannelLogin();
    prefetchFeishuChannelLogin();
  })();
}

function startTelegramChannelLogin() {
  stopExternalChannelLoginPolling();
  stopExternalChannelQrRefreshTimer();
  state.externalChannels.menuOpen = false;
  state.externalChannels.login = createExternalChannelLoginState({
    open: true,
    channelId: "telegram",
    status: "waiting",
    telegramStep: 1,
  });
  render();
}

function setTelegramChannelLoginStep(step: number) {
  const login = state.externalChannels.login;
  if (login.channelId !== "telegram") return;
  state.externalChannels.login = {
    ...login,
    telegramStep: Math.max(1, Math.min(4, step)),
    error: null,
  };
  render();
}

async function submitTelegramChannelToken() {
  const login = state.externalChannels.login;
  if (login.channelId !== "telegram" || login.loading) return;
  const token = login.telegramToken.trim();
  if (!token) {
    state.externalChannels.login = { ...login, error: "请先粘贴 BotFather 返回的 Bot Token。" };
    render();
    return;
  }
  state.externalChannels.login = { ...login, loading: true, status: "waiting", error: null };
  render();
  try {
    await ensureExternalChannelsBackend();
    if (!api.startExternalChannelLogin) throw new Error("当前版本暂不支持连接 Telegram");
    const result = await api.startExternalChannelLogin({ channel: "telegram", botToken: token });
    const status = normalizeExternalChannelLoginStatus(result?.status);
    if (status !== "connected" && firstBoolean(result?.connected) !== true) {
      throw new Error(firstString(result?.message, result?.error) || "Telegram Token 验证失败");
    }
    await finalizeTelegramChannelConnected(result);
    showToast("Telegram 已连接", 1800);
  } catch (error) {
    state.externalChannels.login = {
      ...state.externalChannels.login,
      loading: false,
      status: "error",
      error: `连接失败：${errorMessage(error)}`,
    };
  } finally {
    render();
  }
}

async function startWechatChannelLogin(options: { openDialog?: boolean; renderAfter?: boolean; force?: boolean } = {}) {
  const openDialog = options.openDialog !== false;
  if (!api.startExternalChannelLogin) {
    if (openDialog) showToast("当前版本暂不支持连接微信", 4000);
    return;
  }
  if (wechatChannelIsConnected()) {
    if (openDialog) await openConnectedWechatChannel();
    return;
  }
  if (!options.force && canReuseWechatChannelLogin(state.externalChannels.login)) {
    if (openDialog) openPreparedWechatChannelLogin();
    return;
  }
  const requestId = ++wechatChannelLoginRequestId;
  const startedAt = Date.now();
  stopExternalChannelLoginPolling();
  if (openDialog) {
    state.externalChannels.menuOpen = false;
  }
  state.externalChannels.login = createExternalChannelLoginState({
    open: openDialog,
    channelId: "wechat",
    loading: true,
    status: "waiting",
    startedAt,
  });
  if (openDialog || options.renderAfter !== false) render();
  try {
    const result = await api.startExternalChannelLogin({ channel: "wechat" });
    if (requestId !== wechatChannelLoginRequestId) return;
    const sessionKey = firstString(result?.sessionKey, result?.session_key);
    const qrcodeUrl = firstString(result?.qrcodeUrl, result?.qrcode_url, result?.qrcode_img_content);
    const directOnly = firstBoolean(result?.direct_qr_only, result?.directQrOnly) === true;
    if (!sessionKey) throw new Error("微信登录会话创建失败");
    const shouldPoll = state.externalChannels.login.open;
    state.externalChannels.login = {
      ...state.externalChannels.login,
      loading: false,
      polling: shouldPoll,
      sessionKey,
      qrcodeUrl,
      directOnly,
      notice: firstString(result?.message, result?.notice),
      status: "waiting",
      error: null,
      startedAt,
      expiresAt: externalChannelLoginReusableUntil(result, startedAt),
      qrRefreshAt: qrcodeUrl && shouldPoll ? externalChannelNextQrRefreshAt() : null,
    };
    if (qrcodeUrl) preloadExternalChannelQrImage(qrcodeUrl);
    if (state.externalChannels.login.open || options.renderAfter !== false) render();
    if (shouldPoll) pollExternalChannelLogin();
  } catch (error) {
    if (requestId !== wechatChannelLoginRequestId) return;
    state.externalChannels.login = {
      ...state.externalChannels.login,
      loading: false,
      polling: false,
      status: "error",
      error: errorMessage(error),
    };
    if (state.externalChannels.login.open || options.renderAfter !== false) render();
  }
}

async function prepareFeishuChannelLogin() {
  const startExternalChannelLogin = api.startExternalChannelLogin;
  if (!startExternalChannelLogin || feishuChannelIsConnected()) return;
  const requestId = ++feishuChannelLoginPrefetchRequestId;
  const startedAt = Date.now();
  prefetchedFeishuChannelLogin = createExternalChannelLoginState({
    open: false,
    channelId: "feishu",
    loading: true,
    status: "waiting",
    startedAt,
  });
  try {
    const result = await startExternalChannelLogin({ channel: "feishu", desktopThreadId: currentFeishuChannelDesktopThreadId() });
    if (requestId !== feishuChannelLoginPrefetchRequestId) return;
    const status = normalizeExternalChannelLoginStatus(result?.status);
    if (status === "connected" || firstBoolean(result?.connected) === true) {
      prefetchedFeishuChannelLogin = null;
      return;
    }
    const sessionKey = firstString(result?.sessionKey, result?.session_key);
    const qrcodeUrl = firstString(result?.qrcodeUrl, result?.qrcode_url, result?.qrcode_img_content, result?.verificationUrl, result?.verification_url);
    if (!sessionKey) throw new Error("飞书登录会话创建失败");
    const prepared = createExternalChannelLoginState({
      open: false,
      channelId: "feishu",
      loading: false,
      polling: false,
      sessionKey,
      qrcodeUrl,
      directOnly: false,
      notice: firstString(result?.message, result?.notice),
      status: "waiting",
      error: null,
      startedAt,
      expiresAt: externalChannelLoginReusableUntil(result, startedAt),
      qrRefreshAt: qrcodeUrl && state.externalChannels.login.open ? externalChannelNextQrRefreshAt() : null,
    });
    prefetchedFeishuChannelLogin = prepared;
    if (qrcodeUrl) preloadExternalChannelQrImage(qrcodeUrl);
    if (state.externalChannels.login.open && state.externalChannels.login.channelId === "feishu" && state.externalChannels.login.loading && state.externalChannels.login.startedAt === startedAt) {
      const shouldPoll = Boolean(sessionKey);
      state.externalChannels.login = { ...prepared, open: true, polling: shouldPoll };
      prefetchedFeishuChannelLogin = null;
      render();
      if (shouldPoll) pollExternalChannelLogin();
    }
  } catch (error) {
    if (requestId !== feishuChannelLoginPrefetchRequestId) return;
    const failed = createExternalChannelLoginState({
      open: false,
      channelId: "feishu",
      loading: false,
      polling: false,
      status: "error",
      error: errorMessage(error),
      startedAt,
    });
    prefetchedFeishuChannelLogin = failed;
    if (state.externalChannels.login.open && state.externalChannels.login.channelId === "feishu" && state.externalChannels.login.loading && state.externalChannels.login.startedAt === startedAt) {
      state.externalChannels.login = { ...failed, open: true };
      render();
    }
  }
}

async function startFeishuChannelLogin(options: { openDialog?: boolean; renderAfter?: boolean; force?: boolean } = {}) {
  const openDialog = options.openDialog !== false;
  if (!api.startExternalChannelLogin) {
    if (openDialog) showToast("当前版本暂不支持连接飞书", 4000);
    return;
  }
  if (feishuChannelIsConnected()) {
    if (openDialog) await openConnectedFeishuChannel();
    return;
  }
  if (!options.force && canReuseFeishuChannelLogin(prefetchedFeishuChannelLogin)) {
    if (openDialog) openPreparedFeishuChannelLogin();
    return;
  }
  feishuChannelLoginPrefetchRequestId += 1;
  prefetchedFeishuChannelLogin = null;
  const requestId = ++wechatChannelLoginRequestId;
  const startedAt = Date.now();
  stopExternalChannelLoginPolling();
  if (openDialog) {
    state.externalChannels.menuOpen = false;
  }
  state.externalChannels.login = createExternalChannelLoginState({
    open: openDialog,
    channelId: "feishu",
    loading: true,
    status: "waiting",
    startedAt,
  });
  if (openDialog || options.renderAfter !== false) render();
  try {
    const result = await api.startExternalChannelLogin({ channel: "feishu", desktopThreadId: currentFeishuChannelDesktopThreadId() });
    if (requestId !== wechatChannelLoginRequestId) return;
    const sessionKey = firstString(result?.sessionKey, result?.session_key);
    const qrcodeUrl = firstString(result?.qrcodeUrl, result?.qrcode_url, result?.qrcode_img_content, result?.verificationUrl, result?.verification_url);
    const status = normalizeExternalChannelLoginStatus(result?.status);
    if (status === "connected" || firstBoolean(result?.connected) === true) {
      await finalizeFeishuChannelConnected(result);
      return;
    }
    if (!sessionKey) throw new Error("飞书登录会话创建失败");
    const shouldPoll = state.externalChannels.login.open;
    state.externalChannels.login = {
      ...state.externalChannels.login,
      loading: false,
      polling: shouldPoll,
      sessionKey,
      qrcodeUrl,
      directOnly: false,
      notice: firstString(result?.message, result?.notice),
      status: "waiting",
      error: null,
      startedAt,
      expiresAt: externalChannelLoginReusableUntil(result, startedAt),
      qrRefreshAt: qrcodeUrl && shouldPoll ? externalChannelNextQrRefreshAt() : null,
    };
    if (qrcodeUrl) preloadExternalChannelQrImage(qrcodeUrl);
    if (state.externalChannels.login.open || options.renderAfter !== false) render();
    if (shouldPoll) pollExternalChannelLogin();
  } catch (error) {
    if (requestId !== wechatChannelLoginRequestId) return;
    state.externalChannels.login = {
      ...state.externalChannels.login,
      loading: false,
      polling: false,
      status: "error",
      error: errorMessage(error),
    };
    if (state.externalChannels.login.open || options.renderAfter !== false) render();
  }
}

function canReuseWechatChannelLogin(login: ExternalChannelLoginState) {
  return canReuseExternalChannelLogin(login, "wechat");
}

function canReuseFeishuChannelLogin(login: ExternalChannelLoginState | null) {
  return canReuseExternalChannelLogin(login, "feishu");
}

function canReuseExternalChannelLogin(login: ExternalChannelLoginState | null, channelId: ExternalChannelId) {
  if (!login || login.channelId !== channelId) return false;
  const now = Date.now();
  if (login.startedAt && now - login.startedAt > WECHAT_CHANNEL_LOGIN_PREFETCH_MAX_AGE_MS) return false;
  if (login.expiresAt && now >= login.expiresAt) return false;
  if (login.loading) return true;
  if (!login.sessionKey) return false;
  if (login.status === "expired" || login.status === "error") return false;
  return true;
}

function externalChannelLoginReusableUntil(result: any, startedAt: number) {
  const maxAgeExpiresAt = startedAt + WECHAT_CHANNEL_LOGIN_PREFETCH_MAX_AGE_MS;
  const expiresAtText = firstString(result?.expiresAt, result?.expires_at);
  const expiresAt = expiresAtText ? Date.parse(expiresAtText) : NaN;
  if (!Number.isFinite(expiresAt)) return maxAgeExpiresAt;
  return Math.min(maxAgeExpiresAt, expiresAt - EXTERNAL_CHANNEL_LOGIN_PREFETCH_EXPIRE_SKEW_MS);
}

function externalChannelNextQrRefreshAt() {
  return Date.now() + EXTERNAL_CHANNEL_LOGIN_QR_REFRESH_MS;
}

function isExternalChannelQrAutoRefreshActive(login: ExternalChannelLoginState) {
  return Boolean(
    login.open &&
      (login.channelId === "wechat" || login.channelId === "feishu") &&
      login.qrcodeUrl &&
      !login.loading &&
      !login.polling &&
      login.status === "waiting" &&
      !login.error,
  );
}

function shouldKeepExternalChannelQrWaiting(login: ExternalChannelLoginState, status: ExternalChannelLoginState["status"]) {
  return Boolean(
    (status === "expired" || status === "error") &&
      login.open &&
      login.qrcodeUrl &&
      login.qrRefreshAt &&
      Date.now() < login.qrRefreshAt &&
      login.status !== "scanned" &&
      login.status !== "connected",
  );
}

function openPreparedWechatChannelLogin() {
  stopExternalChannelLoginPolling();
  state.externalChannels.menuOpen = false;
  const shouldPoll = Boolean(
    state.externalChannels.login.sessionKey &&
      state.externalChannels.login.status !== "expired" &&
      state.externalChannels.login.status !== "error" &&
      !state.externalChannels.login.loading,
  );
  state.externalChannels.login = {
    ...state.externalChannels.login,
    open: true,
    channelId: "wechat",
    polling: shouldPoll,
    qrRefreshAt: state.externalChannels.login.qrcodeUrl ? externalChannelNextQrRefreshAt() : null,
  };
  render();
  if (shouldPoll) pollExternalChannelLogin();
}

function openPreparedFeishuChannelLogin() {
  const prepared = prefetchedFeishuChannelLogin;
  if (!prepared || !canReuseFeishuChannelLogin(prepared)) return false;
  stopExternalChannelLoginPolling();
  wechatChannelLoginRequestId += 1;
  state.externalChannels.menuOpen = false;
  const shouldPoll = Boolean(prepared.sessionKey && prepared.status !== "expired" && prepared.status !== "error" && !prepared.loading);
  state.externalChannels.login = {
    ...prepared,
    open: true,
    channelId: "feishu",
    polling: shouldPoll,
    qrRefreshAt: prepared.qrcodeUrl ? externalChannelNextQrRefreshAt() : null,
  };
  if (!prepared.loading) prefetchedFeishuChannelLogin = null;
  render();
  if (shouldPoll) pollExternalChannelLogin();
  return true;
}

function syncExternalChannelQrRefreshTimer() {
  stopExternalChannelQrRefreshTimer();
  const login = state.externalChannels.login;
  if (!isExternalChannelQrAutoRefreshActive(login) || !login.qrRefreshAt) return;
  const remainingMs = login.qrRefreshAt - Date.now();
  if (remainingMs <= 0) {
    void refreshExternalChannelLoginQr(login.channelId);
    return;
  }
  externalChannelQrRefreshTimer = window.setTimeout(() => {
    externalChannelQrRefreshTimer = null;
    render();
  }, Math.min(1000, remainingMs));
}

function stopExternalChannelQrRefreshTimer() {
  if (externalChannelQrRefreshTimer === null) return;
  window.clearTimeout(externalChannelQrRefreshTimer);
  externalChannelQrRefreshTimer = null;
}

async function refreshExternalChannelLoginQr(channelId: ExternalChannelId | null) {
  const login = state.externalChannels.login;
  if (!login.open || login.loading || login.channelId !== channelId || !isExternalChannelQrAutoRefreshActive(login)) return;
  if (channelId === "wechat") {
    await startWechatChannelLogin({ force: true });
  } else if (channelId === "feishu") {
    await startFeishuChannelLogin({ force: true });
  }
}

function preloadExternalChannelQrImage(qrcodeUrl: string) {
  const image = new Image();
  image.decoding = "async";
  image.src = qrcodeUrl;
}

function pollExternalChannelLogin() {
  stopExternalChannelLoginPolling();
  const sessionKey = state.externalChannels.login.sessionKey;
  const getExternalChannelLogin = api.getExternalChannelLogin;
  if (!sessionKey || !getExternalChannelLogin) return;
  externalChannelLoginPollTimer = window.setTimeout(async () => {
    externalChannelLoginPollTimer = null;
    if (!state.externalChannels.login.open || state.externalChannels.login.sessionKey !== sessionKey) return;
    const channelId = state.externalChannels.login.channelId || "wechat";
    try {
      const result = await getExternalChannelLogin({ sessionKey, channel: channelId });
      const status = normalizeExternalChannelLoginStatus(result?.status);
      const nextStatus = shouldKeepExternalChannelQrWaiting(state.externalChannels.login, status) ? "waiting" : status;
      const resultDirectOnly = firstBoolean(result?.direct_qr_only, result?.directQrOnly);
      const directOnly = resultDirectOnly == null ? state.externalChannels.login.directOnly : resultDirectOnly === true;
      state.externalChannels.login = {
        ...state.externalChannels.login,
        polling: nextStatus !== "connected" && nextStatus !== "expired" && nextStatus !== "error",
        status: nextStatus,
        directOnly,
        notice: firstString(result?.message, result?.notice) || state.externalChannels.login.notice,
        error: null,
      };
      if (nextStatus === "connected") {
        state.externalChannels.login.polling = false;
        if (channelId === "wechat" && directOnly) {
          state.externalChannels.login.status = "error";
          state.externalChannels.login.error = firstString(result?.message, result?.notice) || "微信已授权，但后端还没有接管通信；请确认本地后端启动后重新扫码。";
          render();
          return;
        }
        if (channelId === "feishu") {
          void finalizeFeishuChannelConnected(result);
        } else {
          void finalizeWechatChannelConnected(result, { directOnly });
        }
        return;
      }
      if (nextStatus === "expired" || nextStatus === "error") {
        if (channelId === "feishu") {
          if (await finalizeFeishuChannelConnectedFromChannelList()) return;
        } else if (await finalizeWechatChannelConnectedFromChannelList()) {
          return;
        }
        state.externalChannels.login.polling = false;
        render();
        return;
      }
      render();
      pollExternalChannelLogin();
    } catch (error) {
      if (channelId === "feishu") {
        if (await finalizeFeishuChannelConnectedFromChannelList()) return;
      } else if (await finalizeWechatChannelConnectedFromChannelList()) {
        return;
      }
      const startedAt = state.externalChannels.login.startedAt || Date.now();
      if (Date.now() - startedAt < WECHAT_CHANNEL_LOGIN_PREFETCH_MAX_AGE_MS) {
        state.externalChannels.login = {
          ...state.externalChannels.login,
          polling: true,
          status: "waiting",
          notice: "微信连接确认较慢，继续等待",
          error: null,
        };
        render();
        pollExternalChannelLogin();
        return;
      }
      state.externalChannels.login = {
        ...state.externalChannels.login,
        polling: false,
        status: "error",
        error: errorMessage(error),
      };
      render();
    }
  }, 1800);
}

async function openConnectedWechatChannel(channel?: ExternalChannelSummary) {
  stopExternalChannelLoginPolling();
  state.externalChannels.menuOpen = false;
  state.externalChannels.login = createExternalChannelLoginState();
  const wechat = channel || externalChannelItems().find((item) => item.id === "wechat");
  if (!wechat?.connected) {
    render();
    return false;
  }
  await finalizeWechatChannelConnected({
    channel: wechat,
    desktop_thread_id: firstString(wechat.desktop_thread_id, wechat.desktopThreadId),
    desktopThreadId: firstString(wechat.desktop_thread_id, wechat.desktopThreadId),
  });
  return true;
}

async function connectWechatChannelFromThread(threadId: string) {
  const target = threadById(threadId);
  if (!target || !isWechatConnectionThread(target)) return;
  state.threadMenu = null;
  await startWechatChannelLogin();
}

async function disconnectWechatChannelFromThread(threadId: string) {
  const target = threadById(threadId);
  if (!target || !isWechatConnectionThread(target)) return;
  state.threadMenu = null;
  stopExternalChannelLoginPolling();
  state.externalChannels.login = createExternalChannelLoginState();
  render();
  if (!api.disconnectExternalChannel) {
    showToast("当前版本暂不支持断开微信", 4000);
    render();
    return;
  }
  try {
    const messageId = latestWechatChannelExternalMessageId(threadId);
    const result = await api.disconnectExternalChannel({
      channel: "wechat",
      messageId,
      notifyText: WECHAT_CHANNEL_DISCONNECT_REPLY_TEXT,
    });
    appendWechatChannelDisconnectReply(threadId);
    markWechatChannelDisconnected(undefined, { addSystemNotice: false });
    const noticeError = firstString(result?.disconnect_notice_error, result?.disconnectNoticeError);
    if (!messageId) {
      addSystemItem(threadId, "\u5fae\u4fe1\u65ad\u5f00\u63d0\u793a\u672a\u53d1\u9001\u5230\u5fae\u4fe1\uff1a\u6ca1\u6709\u53ef\u56de\u590d\u7684\u5fae\u4fe1\u6d88\u606f\u3002");
    } else if (noticeError) {
      addSystemItem(threadId, `\u5fae\u4fe1\u65ad\u5f00\u63d0\u793a\u53d1\u9001\u5931\u8d25\uff1a${noticeError}`);
    }
    await loadExternalChannels({ force: true, renderAfter: false });
    showToast("\u5fae\u4fe1\u8fde\u63a5\u5df2\u65ad\u5f00", 1800);
  } catch (error) {
    showToast(`断开微信失败：${errorMessage(error)}`, 5000);
    await loadExternalChannels({ force: true, renderAfter: false });
  } finally {
    render();
  }
}

