async function finalizeWechatChannelConnectedFromChannelList() {
  try {
    await loadExternalChannels({ force: true, renderAfter: false, syncRuntime: false });
    const wechat = externalChannelItems().find((channel) => channel.id === "wechat");
    if (!wechat?.connected) return false;
    await finalizeWechatChannelConnected({
      channel: wechat,
      desktop_thread_id: firstString(wechat.desktop_thread_id, wechat.desktopThreadId),
      desktopThreadId: firstString(wechat.desktop_thread_id, wechat.desktopThreadId),
    });
    return true;
  } catch (error) {
    console.warn("Failed to recover connected WeChat channel state", error);
    return false;
  }
}

function normalizeExternalChannelLoginStatus(value: unknown): ExternalChannelLoginState["status"] {
  const status = firstString(value)?.toLowerCase();
  if (status === "connected" || status === "confirmed" || status === "success") return "connected";
  if (status === "scanned" || status === "scaned") return "scanned";
  if (status === "expired" || status === "timeout") return "expired";
  if (status === "error" || status === "failed") return "error";
  return "waiting";
}

function closeExternalChannelLogin() {
  stopExternalChannelLoginPolling();
  stopExternalChannelQrRefreshTimer();
  wechatChannelLoginRequestId += 1;
  state.externalChannels.login = createExternalChannelLoginState();
  render();
}

function stopExternalChannelLoginPolling() {
  if (externalChannelLoginPollTimer === null) return;
  window.clearTimeout(externalChannelLoginPollTimer);
  externalChannelLoginPollTimer = null;
}

async function finalizeWechatChannelConnected(result: any, options: { directOnly?: boolean } = {}) {
  stopExternalChannelLoginPolling();
  state.externalChannels.login = createExternalChannelLoginState();
  let threadId = await ensureWechatChannelThread({ activate: false, loginPayload: result });
  activateWechatChannelThread(threadId, { loadHistory: false });
  state.externalChannels.items = externalChannelItems().map((channel) =>
    channel.id === "wechat"
      ? { ...channel, connected: true, status: "online", desktop_thread_id: threadId, desktopThreadId: threadId }
      : channel,
  );
  const bound = await bindWechatChannelThread(threadId);
  if (!bound) {
    markWechatChannelDisconnected("微信已授权，但后端还没有接管通信；请重新扫码授权。");
    showToast("微信后端未接管通信，请重新扫码授权", 4500);
    render();
    return;
  }
  wechatChannelBackendDisconnectNotified = false;
  const historyLoaded = await loadWechatChannelThreadHistory(threadId, { force: true });
  if (!historyLoaded && !isReusableWechatChannelThreadId(threadId)) {
    threadId = await createFreshWechatChannelThread({ activate: false });
    activateWechatChannelThread(threadId, { loadHistory: false });
    state.externalChannels.items = externalChannelItems().map((channel) =>
      channel.id === "wechat"
        ? { ...channel, connected: true, status: "online", desktop_thread_id: threadId, desktopThreadId: threadId }
        : channel,
    );
    await bindWechatChannelThread(threadId);
  }
  ensureWechatChannelLocalWelcome(threadId);
  startWechatChannelMessagePolling();
  void loadExternalChannels({ force: true, renderAfter: false });
  render();
}

