async function finalizeTelegramChannelConnected(result: any, options: { keepDialog?: boolean } = {}) {
  stopExternalChannelLoginPolling();
  if (!options.keepDialog) state.externalChannels.login = createExternalChannelLoginState();
  const threadId = await ensureTelegramChannelThread({ activate: true, loginPayload: result });
  state.externalChannels.items = externalChannelItems().map((channel) =>
    channel.id === "telegram"
      ? {
          ...channel,
          connected: true,
          status: "online",
          desktop_thread_id: threadId,
          desktopThreadId: threadId,
          bot_username: firstString(result?.bot_username, result?.botUsername, result?.channel?.bot_username, result?.channel?.botUsername),
          botUsername: firstString(result?.bot_username, result?.botUsername, result?.channel?.bot_username, result?.channel?.botUsername),
          bot_link: firstString(result?.bot_link, result?.botLink, result?.channel?.bot_link, result?.channel?.botLink),
          botLink: firstString(result?.bot_link, result?.botLink, result?.channel?.bot_link, result?.channel?.botLink),
          start_group_link: firstString(result?.start_group_link, result?.startGroupLink, result?.channel?.start_group_link, result?.channel?.startGroupLink),
          startGroupLink: firstString(result?.start_group_link, result?.startGroupLink, result?.channel?.start_group_link, result?.channel?.startGroupLink),
        }
      : channel,
  );
  const bound = await bindTelegramChannelThread(threadId);
  if (!bound) {
    markTelegramChannelDisconnected("Telegram 已连接，但后端还没有接管通信；请重新连接。");
    showToast("Telegram 后端未接管通信，请重新连接", 4500);
    render();
    return;
  }
  telegramChannelBackendDisconnectNotified = false;
  ensureTelegramChannelLocalWelcome(threadId);
  startTelegramChannelMessagePolling();
  void loadExternalChannels({ force: true, renderAfter: false, syncRuntime: false });
  render();
}

function syncWechatChannelRuntimeFromItems() {
  const wechat = state.externalChannels.items.find((item) => item.id === "wechat");
  if (!wechat?.connected) {
    stopWechatChannelMessagePolling();
    if (wechatChannelThreadId && !wechatChannelBackendDisconnectNotified) {
      wechatChannelBackendDisconnectNotified = true;
      addSystemItem(wechatChannelThreadId, "微信通信后端未连接，请重新扫码授权后再发消息。");
    }
    return;
  }
  wechatChannelBackendDisconnectNotified = false;
  const remoteThreadId = firstString(wechat.desktop_thread_id, wechat.desktopThreadId);
  if (remoteThreadId && !wechatChannelThreadId) rememberWechatChannelThreadId(remoteThreadId);
  void ensureWechatChannelThread({ activate: false })
    .then(async (threadId) => {
      let activeThreadId = threadId;
      let bound = await bindWechatChannelThread(activeThreadId);
      const historyLoaded = await loadWechatChannelThreadHistory(activeThreadId, { force: true, showSwitching: false });
      if (!historyLoaded && !isReusableWechatChannelThreadId(activeThreadId)) {
        activeThreadId = await createFreshWechatChannelThread({ activate: false });
        bound = await bindWechatChannelThread(activeThreadId);
        state.externalChannels.items = externalChannelItems().map((channel) =>
          channel.id === "wechat"
            ? { ...channel, connected: true, status: "online", desktop_thread_id: activeThreadId, desktopThreadId: activeThreadId }
            : channel,
        );
      }
      ensureWechatChannelLocalWelcome(activeThreadId);
      if (bound !== false) startWechatChannelMessagePolling();
    })
    .catch(() => {
      startWechatChannelMessagePolling();
    });
}

function syncFeishuChannelRuntimeFromItems() {
  const feishu = state.externalChannels.items.find((item) => item.id === "feishu");
  if (!feishu?.connected) {
    stopFeishuChannelMessagePolling();
    if (feishuChannelThreadId && !feishuChannelBackendDisconnectNotified) {
      feishuChannelBackendDisconnectNotified = true;
      addSystemItem(feishuChannelThreadId, "飞书通信后端未连接，请重新扫码授权后再发消息。");
    }
    return;
  }
  feishuChannelBackendDisconnectNotified = false;
  const remoteThreadId = firstString(feishu.desktop_thread_id, feishu.desktopThreadId);
  if (remoteThreadId && remoteThreadId !== feishuChannelThreadId && isReusableFeishuChannelThreadId(remoteThreadId)) {
    rememberFeishuChannelThreadId(remoteThreadId);
  }
  void ensureFeishuChannelThread({ activate: false })
    .then(async (threadId) => {
      const bound = await bindFeishuChannelThread(threadId);
      await loadFeishuChannelThreadHistory(threadId, { force: true, showSwitching: false });
      ensureFeishuChannelLocalWelcome(threadId);
      if (bound !== false) startFeishuChannelMessagePolling();
    })
    .catch(() => {
      startFeishuChannelMessagePolling();
    });
}

function syncTelegramChannelRuntimeFromItems() {
  const telegram = state.externalChannels.items.find((item) => item.id === "telegram");
  if (!telegram?.connected) {
    stopTelegramChannelMessagePolling();
    if (telegramChannelThreadId && !telegramChannelBackendDisconnectNotified) {
      telegramChannelBackendDisconnectNotified = true;
      addSystemItem(telegramChannelThreadId, "Telegram 通信后端未连接，请重新通过 Bot Token 连接后再发消息。");
    }
    return;
  }
  telegramChannelBackendDisconnectNotified = false;
  const remoteThreadId = firstString(telegram.desktop_thread_id, telegram.desktopThreadId);
  if (remoteThreadId && !telegramChannelThreadId) rememberTelegramChannelThreadId(remoteThreadId);
  void ensureTelegramChannelThread({ activate: false })
    .then((threadId) => {
      ensureTelegramChannelLocalWelcome(threadId);
      return bindTelegramChannelThread(threadId);
    })
    .catch(() => {});
  startTelegramChannelMessagePolling();
}

async function ensureWechatChannelThread(options: { activate?: boolean; loginPayload?: any } = {}) {
  let threadId = firstString(
    wechatChannelThreadId,
    options.loginPayload?.desktop_thread_id,
    options.loginPayload?.desktopThreadId,
    options.loginPayload?.channel?.desktop_thread_id,
    options.loginPayload?.channel?.desktopThreadId,
  );
  if (threadId && !isReusableWechatChannelThreadId(threadId)) {
    if (threadId === wechatChannelThreadId) forgetWechatChannelThreadId();
    threadId = null;
  }
  if (!threadId && state.serverReady) {
    try {
      const result = await api.startThread({
        ...threadParams(null, { groupId: DEFAULT_THREAD_GROUP_ID }),
        activate: false,
        personality: "friendly",
      });
      threadId = firstString(result?.thread?.id);
      if (result?.thread && threadId) loadThreadInBackground(result.thread, { preserveListOrder: true });
    } catch (error) {
      console.warn("Failed to create WeChat channel thread", error);
    }
  }
  if (!threadId) {
    threadId = `wechat-channel-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  }
  rememberWechatChannelThreadId(threadId);
  ensureThreadState(threadId);
  const contextChanged = ensureWechatChannelGlobalContext(threadId);
  const visibilityChanged = restoreExternalChannelThreadVisibility(threadId);
  const summary = wechatChannelThreadSummary(threadId);
  state.threads = sortThreadsForList(mergeThreadsWithoutSorting(state.threads, [summary]));
  if (contextChanged || visibilityChanged) saveThreadPreferences();
  if (options.activate) activateWechatChannelThread(threadId);
  return threadId;
}

async function createFreshWechatChannelThread(options: { activate?: boolean } = {}) {
  const previousThreadId = wechatChannelThreadId;
  forgetWechatChannelThreadId();
  if (previousThreadId) {
    threadsAwaitingAgentReply.delete(previousThreadId);
    setCodexThreadBusy(previousThreadId, false);
    setMembersWorking(previousThreadId, false);
  }
  if (!(await ensureServerReadyForComposerSend())) {
    throw new Error("本地 app-server 未启动成功，请先修复启动失败后再发送。");
  }
  const result = await api.startThread({
    ...threadParams(null, { groupId: DEFAULT_THREAD_GROUP_ID }),
    activate: false,
    personality: "friendly",
  });
  const threadId = firstString(result?.thread?.id);
  if (!threadId) throw new Error("创建微信会话失败，请稍后重试。");
  if (result?.thread) loadThreadInBackground(result.thread, { preserveListOrder: true });
  rememberWechatChannelThreadId(threadId);
  ensureThreadState(threadId);
  const contextChanged = ensureWechatChannelGlobalContext(threadId);
  const visibilityChanged = restoreExternalChannelThreadVisibility(threadId);
  state.threads = sortThreadsForList(mergeThreadsWithoutSorting(state.threads, [wechatChannelThreadSummary(threadId)]));
  if (previousThreadId && previousThreadId !== threadId) hiddenThreadIds.add(previousThreadId);
  if (contextChanged || visibilityChanged || previousThreadId) saveThreadPreferences();
  if (options.activate) activateWechatChannelThread(threadId);
  return threadId;
}

function removeWechatChannelWelcomeItems(threadId: string) {
  ensureThreadState(threadId);
  const removedIds = state.itemOrder[threadId].filter((id) => isWechatChannelWelcomeItem(id, state.items[threadId]?.[id]));
  if (!removedIds.length) return;
  state.itemOrder[threadId] = state.itemOrder[threadId].filter((id) => !removedIds.includes(id));
  for (const id of removedIds) {
    delete state.items[threadId][id];
  }
}

function isWechatChannelWelcomeItem(id: string, item: CodexItem | undefined) {
  if (!item) return false;
  return (
    id === WECHAT_CHANNEL_WELCOME_ITEM_ID || id.startsWith("wechat-channel-connected-") || itemText(item).trim() === WECHAT_CHANNEL_WELCOME_TEXT
  );
}

function ensureWechatChannelLocalWelcome(threadId: string) {
  ensureThreadState(threadId);
  if (hasWechatChannelConversationContent(threadId)) return;
  const hasWelcome = state.itemOrder[threadId].some((id) => {
    const item = state.items[threadId]?.[id];
    return (
      item?.type === "agentMessage" && itemText(item).trim() === WECHAT_CHANNEL_WELCOME_TEXT
    );
  });
  if (hasWelcome) return;
  upsertItem(
    threadId,
    {
      id: WECHAT_CHANNEL_WELCOME_ITEM_ID,
      type: "agentMessage",
      role: "ceo_assistant",
      text: WECHAT_CHANNEL_WELCOME_TEXT,
      createdAt: new Date().toISOString(),
      avatar_url: WECHAT_CHANNEL_AVATAR_URL,
    },
    { updateThreadPreview: true },
  );
}

function hasWechatChannelConversationContent(threadId: string) {
  ensureThreadState(threadId);
  return state.itemOrder[threadId].some((id) => {
    const item = state.items[threadId]?.[id];
    return Boolean(item && !isWechatChannelLocalStatusItem(id, item) && !shouldHideChatItem(item) && hasLocalHistoryContent(item));
  });
}

function isWechatChannelLocalStatusItem(id: string, item: CodexItem | undefined) {
  if (!item || item.type !== "agentMessage") return false;
  const text = itemText(item).trim();
  return (
    id === WECHAT_CHANNEL_WELCOME_ITEM_ID ||
    id.startsWith("wechat-channel-connected-") ||
    id.startsWith("wechat-channel-disconnected-") ||
    text === WECHAT_CHANNEL_WELCOME_TEXT ||
    text === WECHAT_CHANNEL_DISCONNECT_REPLY_TEXT
  );
}

function isLocalStatusThreadItem(id: string, item: CodexItem | undefined) {
  if (!item || item.type !== "agentMessage") return false;
  if ((item as Record<string, unknown>).__youleLocalStatus === true) return true;
  if (id.startsWith("agent-notice-")) return true;
  return isExternalChannelLocalStatusThreadItem(id, item);
}

function isExternalChannelLocalStatusThreadItem(id: string, item: CodexItem | undefined) {
  if (isWechatChannelLocalStatusItem(id, item)) return true;
  if (!item || item.type !== "agentMessage") return false;
  const text = itemText(item).trim();
  return (
    id.startsWith("feishu-channel-connected-") ||
    id.startsWith("feishu-channel-disconnected-") ||
    id.startsWith("telegram-channel-connected-") ||
    id.startsWith("telegram-channel-disconnected-") ||
    isFeishuChannelWelcomeText(text) ||
    text === FEISHU_CHANNEL_DISCONNECT_REPLY_TEXT ||
    isTelegramChannelWelcomeText(text) ||
    text === TELEGRAM_CHANNEL_DISCONNECT_REPLY_TEXT
  );
}

function appendWechatChannelDisconnectReply(threadId: string) {
  ensureThreadState(threadId);
  upsertItem(
    threadId,
    {
      id: `wechat-channel-disconnected-${Date.now()}-${Math.random().toString(16).slice(2)}`,
      type: "agentMessage",
      role: "ceo_assistant",
      text: WECHAT_CHANNEL_DISCONNECT_REPLY_TEXT,
      createdAt: new Date().toISOString(),
      avatar_url: WECHAT_CHANNEL_AVATAR_URL,
    },
    { updateThreadPreview: true },
  );
  state.threads = sortThreadsForList(mergeThreadsWithoutSorting(state.threads, [wechatChannelThreadSummary(threadId)]));
}

function latestWechatChannelExternalMessageId(threadId: string) {
  const ids = [...(state.itemOrder[threadId] || [])].reverse();
  for (const id of ids) {
    const item = state.items[threadId]?.[id] as Record<string, unknown> | undefined;
    if (!item) continue;
    const channel = firstString(item.external_channel, item.externalChannel);
    const messageId = firstString(item.external_message_id, item.externalMessageId);
    if (messageId && (!channel || channel === "wechat")) return messageId;
  }
  return null;
}

function wechatChannelThreadSummary(threadId: string): ConversationSummary {
  const latestId = [...(state.itemOrder[threadId] || [])].reverse().find((id) => !isWechatChannelWelcomeItem(id, state.items[threadId]?.[id]));
  const latest = latestId ? state.items[threadId]?.[latestId] : null;
  const timestamp = normalizeTimestamp(firstString(latest?.createdAt, latest?.created_at)) || new Date().toISOString();
  const preview = latest ? threadPreviewTextFromItem(latest) || WECHAT_CHANNEL_WELCOME_TEXT : WECHAT_CHANNEL_WELCOME_TEXT;
  return {
    id: threadId,
    name: WECHAT_CHANNEL_THREAD_NAME,
    kind: "private_chat",
    thread_kind: "local_codex",
    work_mode: "auto",
    preview,
    preview_time: formatThreadTime(timestamp),
    last_message_at: timestamp,
    avatar_image: WECHAT_CHANNEL_AVATAR_URL,
    agents: fallbackMembers("main_session"),
  };
}

function activateWechatChannelThread(threadId: string, options: { loadHistory?: boolean } = {}) {
  rememberActiveComposerDraft();
  clearUnviewedFinalResult(threadId);
  state.chatPreview = null;
  state.closingPreviewSource = null;
  state.newThreadGroupPickerOpen = false;
  state.profileMenuOpen = false;
  state.activeView = "chat";
  state.currentThreadId = threadId;
  prepareExternalTradingWorkspaceLayout();
  restoreComposerDraftForThread(threadId);
  state.activeTurnId = state.activeTurnIds[threadId] ?? null;
  rememberChatThreadSelection(threadId);
  ensureThreadState(threadId);
  if (restoreExternalChannelThreadVisibility(threadId)) saveThreadPreferences();
  state.threads = sortThreadsForList(mergeThreadsWithoutSorting(state.threads, [wechatChannelThreadSummary(threadId)]));
  render();
  if (options.loadHistory !== false) void loadWechatChannelThreadHistory(threadId);
}

async function loadWechatChannelThreadHistory(threadId: string, options: { force?: boolean; showSwitching?: boolean } = {}) {
  if (!state.serverReady || activeWechatChannelHistoryLoads.has(threadId) || (!options.force && loadedWechatChannelHistoryThreadIds.has(threadId))) return false;
  activeWechatChannelHistoryLoads.add(threadId);
  const showSwitching = options.showSwitching !== false;
  if (showSwitching) {
    switchingThreadId = threadId;
    root.classList.add("thread-switching");
    render();
  }
  try {
    const result = await resumeThreadWithModelLock({
      threadId,
      ...threadParams(threadId),
      activate: false,
    });
    if (result?.thread) {
      loadThread(result.thread, { activate: false, preserveListOrder: true });
      loadedWechatChannelHistoryThreadIds.add(threadId);
      if (isWechatChannelThreadId(threadId)) {
        state.threads = sortThreadsForList(mergeThreadsWithoutSorting(state.threads, [wechatChannelThreadSummary(threadId)]));
      }
    }
    return Boolean(result?.thread);
  } catch (error) {
    if (isTransientWechatChannelThreadHistoryError(error)) {
      console.info("WeChat channel history is not ready yet", errorMessage(error));
      return false;
    }
    console.warn("Failed to load WeChat channel history", error);
    if (isUnavailableWechatChannelThreadError(error)) {
      clearThreadHistoryLocally(threadId);
      resetDeletedWechatChannelThread(threadId);
      hideUnavailableThread(threadId, true);
    }
    return false;
  } finally {
    activeWechatChannelHistoryLoads.delete(threadId);
    if (showSwitching) {
      if (switchingThreadId === threadId) switchingThreadId = null;
      render();
      window.requestAnimationFrame(() => root.classList.remove("thread-switching"));
    }
  }
}

function markWechatChannelDisconnected(message?: string, options: { addSystemNotice?: boolean } = {}) {
  stopWechatChannelMessagePolling();
  state.externalChannels.items = externalChannelItems().map((channel) =>
    channel.id === "wechat"
      ? { ...channel, connected: false, status: "disconnected", description: "扫码授权后开始通信" }
      : channel,
  );
  if (wechatChannelThreadId && !wechatChannelBackendDisconnectNotified) {
    wechatChannelBackendDisconnectNotified = true;
    if (options.addSystemNotice !== false) {
      addSystemItem(wechatChannelThreadId, message || "微信通信后端未连接，请重新扫码授权后再发消息。");
    }
  }
}

async function bindWechatChannelThread(threadId: string) {
  if (!api.bindExternalChannelThread) return false;
  try {
    const result = await api.bindExternalChannelThread({
      channel: "wechat",
      threadId,
    });
    const ok = firstBoolean(result?.ok);
    const status = firstString(result?.status)?.toLowerCase();
    if (ok === false || status === "disconnected" || status === "unavailable") return false;
    return true;
  } catch (error) {
    console.warn("Failed to bind WeChat desktop thread", error);
    return false;
  }
}

function startWechatChannelMessagePolling(delayMs = WECHAT_CHANNEL_MESSAGE_POLL_INTERVAL_MS) {
  if (!api.listExternalChannelMessages || externalChannelMessagesPollTimer !== null) return;
  if (delayMs <= WECHAT_CHANNEL_MESSAGE_POLL_INTERVAL_MS) resetExternalChannelPollBackoff("wechat");
  externalChannelMessagesPollTimer = window.setTimeout(() => {
    externalChannelMessagesPollTimer = null;
    void pollWechatChannelMessages();
  }, Math.max(500, delayMs));
}

function stopWechatChannelMessagePolling() {
  if (externalChannelMessagesPollTimer === null) return;
  window.clearTimeout(externalChannelMessagesPollTimer);
  externalChannelMessagesPollTimer = null;
  resetExternalChannelPollBackoff("wechat");
}

function resetExternalChannelPollBackoff(channelId: ExternalChannelId) {
  const pollState = externalChannelPollBackoffState[channelId];
  pollState.failureCount = 0;
}

function markExternalChannelPollFailure(channelId: ExternalChannelId) {
  const pollState = externalChannelPollBackoffState[channelId];
  pollState.failureCount += 1;
  const backoffStep = Math.min(pollState.failureCount - 1, 6);
  const nextPollDelayMs = Math.min(
    EXTERNAL_CHANNEL_MESSAGE_POLL_BACKOFF_MAX_MS,
    WECHAT_CHANNEL_MESSAGE_POLL_TRANSIENT_INTERVAL_MS * 2 ** backoffStep,
  );
  return {
    nextPollDelayMs,
    shouldDisconnect: nextPollDelayMs >= EXTERNAL_CHANNEL_MESSAGE_POLL_BACKOFF_MAX_MS,
  };
}

function disconnectExternalChannelAfterPollBackoffCap(channelId: ExternalChannelId) {
  resetExternalChannelPollBackoff(channelId);
  if (channelId === "wechat") markWechatChannelDisconnected();
  else if (channelId === "feishu") markFeishuChannelDisconnected();
  else markTelegramChannelDisconnected();
  render();
}

function externalChannelPollHasTransientError(result: any) {
  return (
    firstBoolean(
    result?.transient_error,
    result?.transientError,
    result?.raw?.transient_error,
    result?.raw?.transientError,
  ) === true
  );
}

function isExternalChannelAuthFailure(error: unknown) {
  const record = error && typeof error === "object" ? (error as Record<string, unknown>) : {};
  const status = Number(record.statusCode || record.status);
  if (status === 401 || status === 403) return true;
  const message = errorMessage(error);
  return /请先登录|unauthorized|unauthenticated|forbidden|auth(?:entication)? required|login required|token expired|session expired/i.test(message);
}

function shouldLogExternalChannelPollDiagnostic(channelId: ExternalChannelId, event: string, message: string) {
  const pollState = externalChannelPollBackoffState[channelId];
  const key = `${event}:${message}`;
  const now = Date.now();
  const lastLogAt = pollState.lastLogAtByKey[key] || 0;
  if (now - lastLogAt < EXTERNAL_CHANNEL_MESSAGE_POLL_LOG_THROTTLE_MS) return false;
  pollState.lastLogAtByKey[key] = now;
  return true;
}

function logWechatPollDiagnostic(event: string, payload: Record<string, unknown> = {}) {
  const message = firstString(payload.error, payload.message, payload.status, event) || event;
  if (!shouldLogExternalChannelPollDiagnostic("wechat", event, message)) return;
  wechatDebugLog(event, payload);
}

async function pollWechatChannelMessages() {
  if (!api.listExternalChannelMessages) {
    wechatDebugLog("wechat.poll.skip_no_api");
    return;
  }
  let shouldContinuePolling = wechatChannelIsConnected();
  let nextPollDelayMs = WECHAT_CHANNEL_MESSAGE_POLL_INTERVAL_MS;
  try {
    const result = await api.listExternalChannelMessages({ channel: "wechat" });
    const fallback = firstBoolean(result?.fallback, result?.raw?.fallback) === true;
    const status = firstString(result?.status, result?.raw?.status)?.toLowerCase();
    const transientError = externalChannelPollHasTransientError(result);
    const unavailable =
      fallback ||
      status === "unavailable" ||
      transientError;
    const disconnected =
      firstBoolean(result?.connected, result?.raw?.connected) === false &&
      (status === "disconnected" || status === "expired" || status === "unauthorized");
    if (disconnected) {
      logWechatPollDiagnostic("wechat.poll.unavailable", {
        fallback,
        status,
        message: firstString(result?.message, result?.raw?.message),
      });
      resetExternalChannelPollBackoff("wechat");
      markWechatChannelDisconnected("微信通信后端未连接，请重新扫码授权后再发消息。");
      shouldContinuePolling = false;
      render();
      return;
    }
    if (unavailable) {
      const pollFailure = markExternalChannelPollFailure("wechat");
      nextPollDelayMs = pollFailure.nextPollDelayMs;
      logWechatPollDiagnostic("wechat.poll.transient_unavailable", {
        fallback,
        status,
        transientError,
        nextPollDelayMs,
        backoffCapped: pollFailure.shouldDisconnect,
        message: firstString(result?.message, result?.raw?.message),
      });
      if (pollFailure.shouldDisconnect) {
        logWechatPollDiagnostic("wechat.poll.backoff_exhausted", {
          fallback,
          status,
          transientError,
          nextPollDelayMs,
          message: firstString(result?.message, result?.raw?.message),
        });
        shouldContinuePolling = false;
        disconnectExternalChannelAfterPollBackoffCap("wechat");
      }
      return;
    }
    resetExternalChannelPollBackoff("wechat");
    const extracted = arrayFromResponse<any>(result);
    const messages = extracted.length ? extracted : Array.isArray(result?.messages) ? result.messages : [];
    if (messages.length) {
      wechatDebugLog("wechat.poll.messages", {
        count: messages.length,
        messages: messages.map(wechatMessageDebugSummary),
        rawMessages: messages.slice(0, 3).map((message: any) => wechatRawMessageDebugSummary(message)),
      });
    }
    for (const message of messages) queueWechatChannelMessage(message);
    shouldContinuePolling = wechatChannelIsConnected();
  } catch (error) {
    if (isExternalChannelAuthFailure(error)) {
      logWechatPollDiagnostic("wechat.poll.auth_required", { error: errorMessage(error) });
      resetExternalChannelPollBackoff("wechat");
      markWechatChannelDisconnected("微信通信后端未连接，请重新扫码授权后再发消息。");
      shouldContinuePolling = false;
      render();
      return;
    }
    const pollFailure = markExternalChannelPollFailure("wechat");
    nextPollDelayMs = pollFailure.nextPollDelayMs;
    logWechatPollDiagnostic("wechat.poll.error", {
      error: errorMessage(error),
      nextPollDelayMs,
      backoffCapped: pollFailure.shouldDisconnect,
    });
    if (pollFailure.shouldDisconnect) {
      logWechatPollDiagnostic("wechat.poll.backoff_exhausted", { error: errorMessage(error), nextPollDelayMs });
      shouldContinuePolling = false;
      disconnectExternalChannelAfterPollBackoffCap("wechat");
      return;
    }
    if (shouldLogExternalChannelPollDiagnostic("wechat", "wechat.poll.console", errorMessage(error))) {
      console.warn("Failed to poll WeChat channel messages", error);
    }
  } finally {
    if (shouldContinuePolling) startWechatChannelMessagePolling(nextPollDelayMs);
  }
}

function startFeishuChannelMessagePolling(delayMs = WECHAT_CHANNEL_MESSAGE_POLL_INTERVAL_MS) {
  if (!api.listExternalChannelMessages || feishuExternalChannelMessagesPollTimer !== null) return;
  if (delayMs <= WECHAT_CHANNEL_MESSAGE_POLL_INTERVAL_MS) resetExternalChannelPollBackoff("feishu");
  feishuExternalChannelMessagesPollTimer = window.setTimeout(() => {
    feishuExternalChannelMessagesPollTimer = null;
    void pollFeishuChannelMessages();
  }, Math.max(500, delayMs));
}

function stopFeishuChannelMessagePolling() {
  if (feishuExternalChannelMessagesPollTimer === null) return;
  window.clearTimeout(feishuExternalChannelMessagesPollTimer);
  feishuExternalChannelMessagesPollTimer = null;
  resetExternalChannelPollBackoff("feishu");
}

async function pollFeishuChannelMessages() {
  if (!api.listExternalChannelMessages) return;
  let shouldContinuePolling = feishuChannelIsConnected();
  let nextPollDelayMs = WECHAT_CHANNEL_MESSAGE_POLL_INTERVAL_MS;
  try {
    const result = await api.listExternalChannelMessages({ channel: "feishu" });
    const fallback = firstBoolean(result?.fallback, result?.raw?.fallback) === true;
    const status = firstString(result?.status, result?.raw?.status)?.toLowerCase();
    const transientError = externalChannelPollHasTransientError(result);
    const unavailable = fallback || status === "unavailable" || transientError;
    const disconnected =
      firstBoolean(result?.connected, result?.raw?.connected) === false &&
      (status === "disconnected" || status === "expired" || status === "unauthorized");
    if (disconnected) {
      resetExternalChannelPollBackoff("feishu");
      markFeishuChannelDisconnected("飞书通信后端未连接，请重新扫码授权后再发消息。");
      shouldContinuePolling = false;
      render();
      return;
    }
    if (unavailable) {
      const pollFailure = markExternalChannelPollFailure("feishu");
      nextPollDelayMs = pollFailure.nextPollDelayMs;
      if (pollFailure.shouldDisconnect) {
        shouldContinuePolling = false;
        disconnectExternalChannelAfterPollBackoffCap("feishu");
      }
      return;
    }
    resetExternalChannelPollBackoff("feishu");
    const extracted = arrayFromResponse<any>(result);
    const messages = extracted.length ? extracted : Array.isArray(result?.messages) ? result.messages : [];
    for (const message of messages) queueFeishuChannelMessage(message);
    shouldContinuePolling = feishuChannelIsConnected();
  } catch (error) {
    if (isExternalChannelAuthFailure(error)) {
      resetExternalChannelPollBackoff("feishu");
      markFeishuChannelDisconnected("飞书通信后端未连接，请重新扫码授权后再发消息。");
      shouldContinuePolling = false;
      render();
      return;
    }
    const pollFailure = markExternalChannelPollFailure("feishu");
    nextPollDelayMs = pollFailure.nextPollDelayMs;
    if (pollFailure.shouldDisconnect) {
      shouldContinuePolling = false;
      disconnectExternalChannelAfterPollBackoffCap("feishu");
      return;
    }
    if (shouldLogExternalChannelPollDiagnostic("feishu", "feishu.poll.console", errorMessage(error))) {
      console.warn("Failed to poll Feishu channel messages", error);
    }
  } finally {
    if (shouldContinuePolling) startFeishuChannelMessagePolling(nextPollDelayMs);
  }
}

function startTelegramChannelMessagePolling(delayMs = WECHAT_CHANNEL_MESSAGE_POLL_INTERVAL_MS) {
  if (!api.listExternalChannelMessages || telegramExternalChannelMessagesPollTimer !== null) return;
  if (delayMs <= WECHAT_CHANNEL_MESSAGE_POLL_INTERVAL_MS) resetExternalChannelPollBackoff("telegram");
  telegramExternalChannelMessagesPollTimer = window.setTimeout(() => {
    telegramExternalChannelMessagesPollTimer = null;
    void pollTelegramChannelMessages();
  }, Math.max(500, delayMs));
}

function stopTelegramChannelMessagePolling() {
  if (telegramExternalChannelMessagesPollTimer === null) return;
  window.clearTimeout(telegramExternalChannelMessagesPollTimer);
  telegramExternalChannelMessagesPollTimer = null;
  resetExternalChannelPollBackoff("telegram");
}

async function pollTelegramChannelMessages() {
  if (!api.listExternalChannelMessages) return;
  let shouldContinuePolling = telegramChannelIsConnected();
  let nextPollDelayMs = WECHAT_CHANNEL_MESSAGE_POLL_INTERVAL_MS;
  try {
    const result = await api.listExternalChannelMessages({ channel: "telegram" });
    const fallback = firstBoolean(result?.fallback, result?.raw?.fallback) === true;
    const status = firstString(result?.status, result?.raw?.status)?.toLowerCase();
    const transientError = externalChannelPollHasTransientError(result);
    const unavailable = fallback || status === "unavailable" || transientError;
    const disconnected =
      firstBoolean(result?.connected, result?.raw?.connected) === false &&
      (status === "disconnected" || status === "expired" || status === "unauthorized" || status === "requires_reconnect");
    if (disconnected) {
      resetExternalChannelPollBackoff("telegram");
      markTelegramChannelDisconnected("Telegram 通信后端未连接，请重新通过 Bot Token 连接后再发消息。");
      shouldContinuePolling = false;
      render();
      return;
    }
    if (unavailable) {
      const pollFailure = markExternalChannelPollFailure("telegram");
      nextPollDelayMs = pollFailure.nextPollDelayMs;
      if (pollFailure.shouldDisconnect) {
        shouldContinuePolling = false;
        disconnectExternalChannelAfterPollBackoffCap("telegram");
      }
      return;
    }
    resetExternalChannelPollBackoff("telegram");
    const extracted = arrayFromResponse<any>(result);
    const messages = extracted.length ? extracted : Array.isArray(result?.messages) ? result.messages : [];
    for (const message of messages) queueTelegramChannelMessage(message);
    shouldContinuePolling = telegramChannelIsConnected();
  } catch (error) {
    if (isExternalChannelAuthFailure(error)) {
      resetExternalChannelPollBackoff("telegram");
      markTelegramChannelDisconnected("Telegram 通信后端未连接，请重新通过 Bot Token 连接后再发消息。");
      shouldContinuePolling = false;
      render();
      return;
    }
    const pollFailure = markExternalChannelPollFailure("telegram");
    nextPollDelayMs = pollFailure.nextPollDelayMs;
    if (pollFailure.shouldDisconnect) {
      shouldContinuePolling = false;
      disconnectExternalChannelAfterPollBackoffCap("telegram");
      return;
    }
    if (shouldLogExternalChannelPollDiagnostic("telegram", "telegram.poll.console", errorMessage(error))) {
      console.warn("Failed to poll Telegram channel messages", error);
    }
  } finally {
    if (shouldContinuePolling) startTelegramChannelMessagePolling(nextPollDelayMs);
  }
}

function queueFeishuChannelMessage(message: any) {
  const messageId = firstString(message?.id, message?.message_id, message?.messageId);
  const text = wechatChannelMessageText(message);
  const attachments = wechatChannelMessageFileAttachments(message);
  if (!messageId || (!text && !attachments.length)) return;
  if (handledFeishuChannelMessageIds.has(messageId) || inFlightFeishuChannelMessageIds.has(messageId)) return;
  showFeishuChannelMessageAttention(messageId);
  void showQueuedFeishuChannelMessage(message).catch((error) => {
    console.warn("Failed to display Feishu channel message", error);
  });
  if (
    activeFeishuChannelMessageId &&
    activeFeishuChannelMessageId !== messageId &&
    feishuChannelThreadId &&
    hasThreadCodexWork(feishuChannelThreadId) &&
    activeTurnIdForThread(feishuChannelThreadId)
  ) {
    inFlightFeishuChannelMessageIds.add(messageId);
    void steerExternalChannelBusyMessage("feishu", message, feishuChannelThreadId)
      .catch((error) => {
        addSystemItem(feishuChannelThreadId!, `飞书补充消息暂未加入当前任务：${errorMessage(error)}`);
      })
      .finally(() => {
        inFlightFeishuChannelMessageIds.delete(messageId);
        render();
      });
    return;
  }
  inFlightFeishuChannelMessageIds.add(messageId);
  feishuChannelRequestQueue = feishuChannelRequestQueue
    .then(async () => {
      activeFeishuChannelMessageId = messageId;
      try {
        await handleFeishuChannelMessage(message);
      } finally {
        if (activeFeishuChannelMessageId === messageId) activeFeishuChannelMessageId = null;
      }
    })
    .catch((error) => {
      const threadId = feishuChannelThreadId;
      if (threadId) addSystemItem(threadId, `飞书消息处理失败：${errorMessage(error)}`);
    })
    .finally(() => {
      inFlightFeishuChannelMessageIds.delete(messageId);
      render();
    });
}

function showFeishuChannelMessageAttention(messageId: string) {
  const attentionPromise = api.showExternalChannelAttention?.({ channel: "feishu", messageId });
  if (!attentionPromise) return;
  void attentionPromise.catch(() => {});
}

