function wechatChannelExplicitInstructionText(text: string, attachments: MessageAttachment[] = []) {
  const cleanText = cleanVisibleMessageText(String(text || "")).replace(/\s+/g, " ").trim();
  if (!cleanText) return "";
  if (attachments.length && wechatChannelLooksLikeAttachmentOnlyPlaceholder(cleanText)) return "";
  return cleanText;
}

function wechatChannelLooksLikeAttachmentOnlyPlaceholder(text: string) {
  const value = String(text || "").replace(/\s+/g, "").trim();
  if (!value) return true;
  return (
    /^(?:\u9644\u4ef6|\u6587\u4ef6|\u56fe\u7247)[:\uff1a]?$/u.test(value) ||
    /^(?:\u8bf7)?(?:\u5904\u7406)?(?:\u5fae\u4fe1)?(?:\u53d1\u6765\u7684)?(?:\u6587\u4ef6|\u9644\u4ef6|\u56fe\u7247)[\u3002.!\uff01~]*$/u.test(value)
  );
}

async function handleFeishuChannelMessage(message: any) {
  const messageId = firstString(message?.id, message?.message_id, message?.messageId);
  const text = wechatChannelMessageText(message);
  const attachments = wechatChannelMessageFileAttachments(message);
  if (!messageId || (!text && !attachments.length)) return;
  const explicitText = wechatChannelExplicitInstructionText(text, attachments);
  const agentText = wechatChannelAgentTextWithAttachments(explicitText, attachments);
  const threadId = await ensureFeishuChannelThread({ activate: true });
  const createdAt = normalizeTimestamp(firstString(message?.created_at, message?.createdAt)) || new Date().toISOString();
  upsertFeishuChannelUserMessage(threadId, messageId, explicitText, createdAt, attachments);
  state.threads = sortThreadsForList(mergeThreadsWithoutSorting(state.threads, [feishuChannelThreadSummary(threadId)]));
  setMessageStreamFollow(threadId, true);
  render();
  await sendFeishuChannelProcessingAck(threadId, messageId);
  if (await handleExternalTradingChannelMessage({
    channel: "feishu",
    threadId,
    messageId,
    text: explicitText,
  })) return;
  const beforeIds = new Set(state.itemOrder[threadId] || []);
  const reply = await runFeishuChannelAgent(
    threadId,
    agentText,
    beforeIds,
    consumptionVisibleQuestion(explicitText, attachments),
  );
  const replyText = externalChannelAgentReplyText(reply.text.trim(), explicitText, attachments) || "我这边处理超时了，你再发一次试试。";
  const replyScope = {
    startedAtMs: reply.startedAtMs,
    turnId: reply.turnId,
  };
  const replyAttachments = await waitForWechatChannelReplyAttachments(reply.threadId, reply.beforeIds, replyText, replyScope);
  const feishuReplyText = replyAttachments.length ? wechatChannelTextForExternalReply(replyText, replyAttachments) : replyText;
  if (api.replyExternalChannelMessage) {
    try {
      const response = await api.replyExternalChannelMessage({ channel: "feishu", messageId, text: feishuReplyText, attachments: replyAttachments });
      const failure = externalChannelReplyFailureMessage(response);
      if (failure) addSystemItem(reply.threadId, `飞书回复发送失败：${failure}`);
    } catch (error) {
      addSystemItem(reply.threadId, `飞书回复发送失败：${errorMessage(error)}`);
    }
  }
  rememberFeishuChannelHandledMessage(messageId);
}

async function sendFeishuChannelProcessingAck(threadId: string, messageId: string) {
  if (!api.replyExternalChannelMessage) return;
  if (acknowledgedFeishuChannelMessageIds.has(messageId)) return;
  acknowledgedFeishuChannelMessageIds.add(messageId);
  try {
    await api.replyExternalChannelMessage({
      channel: "feishu",
      messageId,
      text: FEISHU_CHANNEL_PROCESSING_ACK_TEXT,
      attachments: [],
      kind: "ack",
    });
  } catch (error) {
    acknowledgedFeishuChannelMessageIds.delete(messageId);
    addSystemItem(threadId, `飞书收到提示发送失败：${errorMessage(error)}`);
  }
}

function upsertFeishuChannelUserMessage(threadId: string, messageId: string, text: string, createdAt: string, attachments: MessageAttachment[] = []) {
  const cleanAttachments = dedupeMessageAttachments(attachments);
  const displayText = cleanVisibleMessageText(text);
  upsertItem(threadId, {
    id: `feishu-user-${messageId}`,
    type: "userMessage",
    createdAt,
    text: displayText,
    content: [{ text: displayText, attachments: cleanAttachments }],
    attachments: cleanAttachments,
    external_channel: "feishu",
    external_message_id: messageId,
  });
}

