function appendFeishuChannelDisconnectReply(threadId: string) {
  ensureThreadState(threadId);
  upsertItem(
    threadId,
    {
      id: `feishu-channel-disconnected-${Date.now()}-${Math.random().toString(16).slice(2)}`,
      type: "agentMessage",
      role: "ceo_assistant",
      text: FEISHU_CHANNEL_DISCONNECT_REPLY_TEXT,
      createdAt: new Date().toISOString(),
      avatar_url: FEISHU_CHANNEL_AVATAR_URL,
    },
    { updateThreadPreview: true },
  );
  state.threads = sortThreadsForList(mergeThreadsWithoutSorting(state.threads, [feishuChannelThreadSummary(threadId)]));
}

function latestFeishuChannelExternalMessageId(threadId: string) {
  const ids = [...(state.itemOrder[threadId] || [])].reverse();
  for (const id of ids) {
    const item = state.items[threadId]?.[id] as Record<string, unknown> | undefined;
    if (!item) continue;
    const channel = firstString(item.external_channel, item.externalChannel);
    const messageId = firstString(item.external_message_id, item.externalMessageId);
    if (messageId && channel === "feishu") return messageId;
  }
  return null;
}

function feishuChannelThreadSummary(threadId: string): ConversationSummary {
  const latestId = [...(state.itemOrder[threadId] || [])].reverse().find((id) => !isFeishuChannelWelcomeItem(id, state.items[threadId]?.[id]));
  const latest = latestId ? state.items[threadId]?.[latestId] : null;
  const timestamp = normalizeTimestamp(firstString(latest?.createdAt, latest?.created_at)) || new Date().toISOString();
  const preview = latest ? threadPreviewTextFromItem(latest) || FEISHU_CHANNEL_WELCOME_TEXT : FEISHU_CHANNEL_WELCOME_TEXT;
  return {
    id: threadId,
    name: FEISHU_CHANNEL_THREAD_NAME,
    kind: "private_chat",
    thread_kind: "local_codex",
    work_mode: "auto",
    preview,
    preview_time: formatThreadTime(timestamp),
    last_message_at: timestamp,
    avatar_image: FEISHU_CHANNEL_AVATAR_URL,
    agents: fallbackMembers("main_session"),
  };
}

function activateFeishuChannelThread(threadId: string, options: { loadHistory?: boolean } = {}) {
  rememberActiveComposerDraft();
  clearUnviewedFinalResult(threadId);
  state.chatPreview = null;
  state.closingPreviewSource = null;
  state.newThreadGroupPickerOpen = false;
  state.profileMenuOpen = false;
  state.activeView = "chat";
  state.currentThreadId = threadId;
  prepareExternalTradingWorkspaceLayout();
  restoreComposerDraftForThread(threadId);
  state.activeTurnId = state.activeTurnIds[threadId] ?? null;
  rememberChatThreadSelection(threadId);
  ensureThreadState(threadId);
  if (restoreExternalChannelThreadVisibility(threadId)) saveThreadPreferences();
  state.threads = sortThreadsForList(mergeThreadsWithoutSorting(state.threads, [feishuChannelThreadSummary(threadId)]));
  render();
  if (options.loadHistory !== false) void loadFeishuChannelThreadHistory(threadId);
}

async function loadFeishuChannelThreadHistory(threadId: string, options: { force?: boolean; showSwitching?: boolean } = {}) {
  if (!state.serverReady || activeFeishuChannelHistoryLoads.has(threadId) || (!options.force && loadedFeishuChannelHistoryThreadIds.has(threadId))) return false;
  activeFeishuChannelHistoryLoads.add(threadId);
  const showSwitching = options.showSwitching !== false;
  if (showSwitching) {
    switchingThreadId = threadId;
    root.classList.add("thread-switching");
    render();
  }
  try {
    const result = await resumeThreadWithModelLock({
      threadId,
      ...threadParams(threadId),
      activate: false,
    });
    if (result?.thread) {
      loadThread(result.thread, { activate: false, preserveListOrder: true });
      loadedFeishuChannelHistoryThreadIds.add(threadId);
      if (isFeishuChannelThreadId(threadId)) {
        state.threads = sortThreadsForList(mergeThreadsWithoutSorting(state.threads, [feishuChannelThreadSummary(threadId)]));
      }
    }
    return Boolean(result?.thread);
  } catch (error) {
    if (isTransientWechatChannelThreadHistoryError(error)) {
      console.info("Feishu channel history is not ready yet", errorMessage(error));
      return false;
    }
    console.warn("Failed to load Feishu channel history", error);
    if (isUnavailableWechatChannelThreadError(error)) {
      clearThreadHistoryLocally(threadId);
      resetDeletedFeishuChannelThread(threadId);
      hideUnavailableThread(threadId, true);
    }
    return false;
  } finally {
    activeFeishuChannelHistoryLoads.delete(threadId);
    if (showSwitching) {
      if (switchingThreadId === threadId) switchingThreadId = null;
      render();
      window.requestAnimationFrame(() => root.classList.remove("thread-switching"));
    }
  }
}

function markFeishuChannelDisconnected(message?: string, options: { addSystemNotice?: boolean } = {}) {
  stopFeishuChannelMessagePolling();
  state.externalChannels.items = externalChannelItems().map((channel) =>
    channel.id === "feishu"
      ? { ...channel, connected: false, status: "disconnected", description: "扫码授权后开始通信" }
      : channel,
  );
  if (feishuChannelThreadId && !feishuChannelBackendDisconnectNotified) {
    feishuChannelBackendDisconnectNotified = true;
    if (options.addSystemNotice !== false) {
      addSystemItem(feishuChannelThreadId, message || "飞书通信后端未连接，请重新扫码授权后再发消息。");
    }
  }
}

async function bindFeishuChannelThread(threadId: string) {
  if (!api.bindExternalChannelThread) return false;
  try {
    const result = await api.bindExternalChannelThread({
      channel: "feishu",
      threadId,
    });
    const ok = firstBoolean(result?.ok);
    const status = firstString(result?.status)?.toLowerCase();
    if (ok === false || status === "disconnected" || status === "unavailable") return false;
    return true;
  } catch (error) {
    console.warn("Failed to bind Feishu desktop thread", error);
    return false;
  }
}

