function updateComposerSkillMentionPopover(candidates = composerSkillMentionCandidates(state.composerSkillMention.query)) {
  const popover = root.querySelector<HTMLElement>(".composer-skill-popover");
  if (!popover) return;
  popover.classList.toggle("hidden", !state.composerSkillMention.open);
  popover.querySelectorAll<HTMLButtonElement>("[data-skill-mention-index]").forEach((button) => {
    const index = Number(button.dataset.skillMentionIndex);
    button.classList.toggle("active", index === state.composerSkillMention.activeIndex);
    button.setAttribute("aria-selected", index === state.composerSkillMention.activeIndex ? "true" : "false");
  });
  popover.querySelectorAll<HTMLButtonElement>("[data-thread-reference-index]").forEach((button) => {
    const index = Number(button.dataset.threadReferenceIndex);
    button.classList.toggle("active", index === state.composerSkillMention.threadActiveIndex);
    button.setAttribute("aria-selected", index === state.composerSkillMention.threadActiveIndex ? "true" : "false");
  });
  popover.querySelectorAll<HTMLButtonElement>("[data-prompt-favorite-index]").forEach((button) => {
    const index = Number(button.dataset.promptFavoriteIndex);
    const active = index === state.composerSkillMention.favoriteActiveIndex;
    const option = button.closest<HTMLElement>(".composer-prompt-favorite-row");
    button.classList.toggle("active", active);
    option?.classList.toggle("active", active);
    option?.setAttribute("aria-selected", active ? "true" : "false");
  });
  popover.querySelector<HTMLButtonElement>("[data-skill-mention-index].active")?.scrollIntoView({ block: "nearest" });
  popover.querySelector<HTMLButtonElement>("[data-thread-reference-index].active")?.scrollIntoView({ block: "nearest" });
  popover.querySelector<HTMLButtonElement>("[data-prompt-favorite-index].active")?.scrollIntoView({ block: "nearest" });
  bindComposerSkillMentionIconFallbacks(popover);
  queueMicrotask(positionComposerThreadReferenceDetail);
  void candidates;
}

function positionComposerThreadReferenceDetail() {
  const submenu = root.querySelector<HTMLElement>(".composer-thread-submenu");
  const detail = submenu?.querySelector<HTMLElement>(".composer-thread-detail-submenu");
  const anchor = submenu?.querySelector<HTMLElement>("[data-thread-reference-index].active");
  if (!submenu || !detail || !anchor) return;

  detail.style.top = "50%";
  detail.style.transform = "translateY(-50%)";

  const submenuRect = submenu.getBoundingClientRect();
  const anchorRect = anchor.getBoundingClientRect();
  const detailRect = detail.getBoundingClientRect();
  const desiredTop = anchorRect.top + anchorRect.height / 2 - submenuRect.top - detailRect.height / 2;
  const viewportPadding = 12;
  const minimumTop = viewportPadding - submenuRect.top;
  const maximumTop = window.innerHeight - viewportPadding - submenuRect.top - detailRect.height;
  const clampedTop = Math.max(minimumTop, Math.min(desiredTop, Math.max(minimumTop, maximumTop)));

  detail.style.top = `${Math.round(clampedTop)}px`;
  detail.style.transform = "none";
}

function renderComposerMentionPreservingThreadListScroll() {
  const previousList = root.querySelector<HTMLElement>(".composer-thread-reference-list");
  const previousScrollTop = previousList?.scrollTop ?? 0;
  render();
  const nextList = root.querySelector<HTMLElement>(".composer-thread-reference-list");
  if (nextList) nextList.scrollTop = previousScrollTop;
  queueMicrotask(positionComposerThreadReferenceDetail);
}

