function bindMediaHoverPreviewEvents(
  trigger: HTMLElement,
  preview: HTMLElement | null,
  leaveTarget: HTMLElement = trigger,
) {
  if (!preview) return;
  const previewVideo = preview.querySelector<HTMLVideoElement>("video");
  const positionPreview = () => {
    const rect = trigger.getBoundingClientRect();
    const composerRect = trigger
      .closest<HTMLElement>(".composer")
      ?.getBoundingClientRect();
    const previewHalfWidth = Math.max(1, preview.offsetWidth || 236) / 2;
    const minimumCenter = composerRect
      ? composerRect.left + previewHalfWidth + 3
      : previewHalfWidth + 8;
    const maximumCenter = composerRect
      ? composerRect.right - previewHalfWidth - 3
      : window.innerWidth - previewHalfWidth - 8;
    const center = Math.max(
      minimumCenter,
      Math.min(maximumCenter, rect.left + rect.width / 2),
    );
    preview.style.left = `${center}px`;
    preview.style.top = `${Math.max(16, rect.top - 12)}px`;
  };
  const startPreview = () => {
    positionPreview();
    if (!previewVideo) return;
    previewVideo.currentTime = 0;
    void previewVideo.play().catch(() => {});
  };
  const stopPreview = () => {
    if (!previewVideo) return;
    previewVideo.pause();
    previewVideo.currentTime = 0;
  };
  previewVideo?.addEventListener("timeupdate", () => {
    if (previewVideo.currentTime >= 3) previewVideo.currentTime = 0;
  });
  trigger.addEventListener("mouseenter", startPreview);
  trigger.addEventListener("focus", startPreview);
  leaveTarget.addEventListener("mouseleave", stopPreview);
  trigger.addEventListener("blur", stopPreview);
}

function syncComposerMediaReferenceInlineLayout() {
  const wrap = root.querySelector<HTMLElement>(".composer-input-wrap");
  const chips = wrap?.querySelector<HTMLElement>(".media-reference-chips");
  if (!wrap || !chips) return;
  const input = wrap.querySelector<HTMLTextAreaElement>("#composerInput");
  const cursor =
    input &&
    document.activeElement === input &&
    input.selectionStart === input.selectionEnd
      ? input.selectionStart
      : null;
  const caretReference =
    cursor === null
      ? null
      : composerMediaReferenceRanges(input?.value || "").find(
          (range) => range.end === cursor,
        ) || null;
  const caretReferenceKey = caretReference
    ? composerMediaReferenceKey(
        caretReference.attachmentId,
        caretReference.occurrenceIndex,
      )
    : null;
  const wrapRect = wrap.getBoundingClientRect();
  const anchorByKey = new Map<string, HTMLElement>();
  wrap
    .querySelectorAll<HTMLElement>("[data-media-reference-key]")
    .forEach((anchor) => {
      const referenceKey = anchor.dataset.mediaReferenceKey;
      if (
        referenceKey &&
        anchor.classList.contains("media-reference-anchor") &&
        !anchorByKey.has(referenceKey)
      ) {
        anchorByKey.set(referenceKey, anchor);
      }
    });
  chips
    .querySelectorAll<HTMLElement>("[data-remove-media-reference]")
    .forEach((chip) => {
      const referenceKey = chip.dataset.mediaReferenceKey || "";
      chip.classList.toggle(
        "show-reference-caret",
        referenceKey === caretReferenceKey,
      );
      const anchor = anchorByKey.get(referenceKey);
      if (!anchor) {
        chip.style.visibility = "hidden";
        return;
      }
      const anchorRect = anchor.getBoundingClientRect();
      const top =
        anchorRect.top -
        wrapRect.top +
        Math.max(0, (anchorRect.height - chip.offsetHeight) / 2);
      chip.style.left = `${Math.max(0, anchorRect.left - wrapRect.left)}px`;
      chip.style.top = `${Math.max(0, top - 2)}px`;
      chip.style.visibility = "visible";
    });
}

