function requestPendingMediaReplacement(attachmentId: string) {
  const threadId = currentComposerThreadId();
  const attachment = composerAttachmentsForThread(threadId).find(
    (item) => item.id === attachmentId,
  );
  const kind = attachment
    ? mediaCreationMentionKind(attachment)
    : null;
  const input = root.querySelector<HTMLInputElement>("#fileInput");
  if (!threadId || !attachment || !kind || !input) return;
  pendingMediaReplacementId = attachmentId;
  input.value = "";
  input.accept =
    kind === "image" || kind === "video" || kind === "audio"
      ? mediaInputAccept(kind)
      : "";
  input.multiple = false;
  input.click();
}

