function renderAutoTaskDetailMessages(task: AutoTaskItem) {
  if (task.threadId && state.itemOrder[task.threadId]?.length) {
    const messages = messagesForThread(task.threadId);
    if (messages.length) {
      return messages.map((message) => renderMessage(message, messages)).join("");
    }
  }
  if (task.runs?.length) {
    return task.runs.map((run) => renderAutoTaskRunMessages(task, run)).join("");
  }
  if (task.runs?.length) {
    return task.runs.map((run) => renderAutoTaskRunMessages(task, run)).join("");
  }
  const failureText = autoTaskFailureText(task);
  const agentText = task.lastResult || (failureText ? `${AUTO_TASK_FAILED_PREFIX}${failureText}` : "");
  const messages = autoTaskFallbackMessages(task, agentText);
  return `
    <div class="auto-task-detail-time">${escapeHtml(formatAutoTaskClockTime(task.lastRunAt || task.nextRunAt))}</div>
    ${messages.map((message) => renderMessage(message, messages)).join("")}
  `;
}

function autoTaskFallbackMessages(task: AutoTaskItem, agentText: string): Message[] {
  const threadId = ensureAutoTaskThreadId(task);
  const messages: Message[] = [
    {
      id: `${task.id}-fallback-user`,
      conversation_id: threadId,
      kind: "user_text",
      role: "user",
      text: task.description,
      time: formatAutoTaskClockTime(task.createdAt),
    },
  ];
  if (agentText) {
    messages.push({
      id: `${task.id}-fallback-agent`,
      conversation_id: threadId,
      kind: "agent_text",
      role: "ceo_assistant",
      sender_label: "HaoLo",
      text: agentText,
      time: formatAutoTaskClockTime(task.lastRunAt || task.updatedAt),
    });
  }
  return messages;
}

function renderAutoTaskRunMessages(task: AutoTaskItem, run: AutoTaskRunSummary) {
  const completedAt = firstString(run.completedAt, run.startedAt, run.createdAt, run.scheduledForUtc);
  const runStatus = run.status || "";
  const failed = ["failed", "timed_out", "needs_attention", "lost", "cancelled"].includes(runStatus) || Boolean(run.errorMessage);
  const running = runStatus === "queued" || runStatus === "running";
  const resultText = firstString(run.summary, run.errorMessage) || (running ? "任务正在执行" : failed ? "执行失败" : "任务已完成");
  const agentText = failed ? `${AUTO_TASK_FAILED_PREFIX}${resultText}` : resultText;
  const messages = autoTaskFallbackMessages(task, agentText);
  return `
    <div class="auto-task-detail-time">${escapeHtml(formatAutoTaskClockTime(completedAt))}</div>
    ${messages.map((message) => renderMessage(message, messages)).join("")}
  `;
}

