function renderSkillsPlazaTabs() {
  const tabs: Array<{ id: SkillsPlazaTab; label: string; hidden?: boolean }> = [
    { id: "skills", label: "技能", hidden: true },
    { id: "mySkills", label: "策略" },
    { id: "indicators", label: "指标" },
    { id: "quant", label: "量化" },
    { id: "plugins", label: "插件", hidden: true },
  ];
  return `
    <nav class="skills-plaza-tabs" aria-label="发现分类">
      ${tabs
        .filter((tab) => !tab.hidden)
        .map((tab) => {
          const active = state.skillsPlazaTab === tab.id;
          return `<button type="button" class="${active ? "active" : ""}" data-skills-plaza-tab="${tab.id}" aria-pressed="${active ? "true" : "false"}">${escapeHtml(tab.label)}</button>`;
        })
        .join("")}
    </nav>
  `;
}

function renderPluginMarketplacePage() {
  const query = state.skillSearch.trim().toLowerCase();
  const currentPluginCwd = threadWorkspaceCwd(state.currentThreadId);
  const currentWorkspaceLoaded = samePluginWorkspace(state.plugins.cwd, currentPluginCwd);
  const currentWorkspaceRequested = samePluginWorkspace(state.plugins.requestCwd, currentPluginCwd);
  const items = (currentWorkspaceLoaded ? state.plugins.items : []).filter((item) => {
    if (!query) return true;
    return `${item.title} ${item.description} ${item.developer || ""} ${item.category || ""}`.toLowerCase().includes(query);
  });
  const emptyMessage = currentWorkspaceLoaded && state.plugins.loaded ? "暂无已安装插件" : "插件加载中...";
  const filteredEmptyMessage = query ? "没有找到匹配的插件" : emptyMessage;
  return `
    <main class="skills-plaza-page plugin-marketplace-page">
      ${renderSkillsPlazaTabs()}
      ${currentWorkspaceLoaded && state.plugins.toast ? `<div class="plugin-top-toast" role="status">${escapeHtml(state.plugins.toast)}</div>` : ""}
      ${currentWorkspaceRequested && state.plugins.error ? `<p class="skills-load-state error">${escapeHtml(state.plugins.error)}</p>` : ""}
      ${currentWorkspaceRequested && state.plugins.loading && !items.length ? `<div class="skills-loading-center"><i class="skill-detail-spinner" aria-label="插件加载中"></i></div>` : ""}
      <section class="plugin-marketplace-list" aria-label="插件">
        ${items.length ? items.map(renderPluginMarketplaceRow).join("") : `<p class="skills-empty">${escapeHtml(filteredEmptyMessage)}</p>`}
      </section>
    </main>
  `;
}

function renderPluginMarketplaceRow(item: PluginMarketplaceItem) {
  const enabled = item.enabled;
  const chromePlugin = item.name.toLowerCase() === "chrome" || item.pluginId.toLowerCase().startsWith("chrome@");
  const togglePending = pluginTogglePendingIds.has(pluginTogglePendingKey(state.plugins.cwd, item.id));
  return `
    <article class="plugin-marketplace-row ${enabled ? "enabled" : ""}">
      <div class="plugin-marketplace-icon plugin-marketplace-icon-${item.icon}">
        ${renderPluginMarketplaceIcon(item.icon)}
      </div>
      <div class="plugin-marketplace-copy">
        <h2>${escapeHtml(item.title)}</h2>
        <p>${escapeHtml(item.description)}</p>
      </div>
      <div class="plugin-marketplace-actions">
        ${chromePlugin ? `<button type="button" class="plugin-chrome-manage" data-chrome-manage>管理</button>` : ""}
        ${
          item.builtin
            ? `<span class="plugin-builtin-label">内置</span>`
            : `<div class="plugin-marketplace-menu-wrap">
                <button type="button" class="plugin-marketplace-menu ${state.plugins.menuPluginId === item.id ? "active" : ""}" data-plugin-menu="${escapeAttr(item.id)}" aria-label="${escapeAttr(item.title)} 更多操作" aria-haspopup="menu" aria-expanded="${state.plugins.menuPluginId === item.id ? "true" : "false"}"><span></span><span></span><span></span></button>
                ${
                  state.plugins.menuPluginId === item.id
                    ? `<div class="plugin-marketplace-action-menu" role="menu">
                        <button type="button" data-plugin-delete="${escapeAttr(item.id)}" role="menuitem">删除</button>
                      </div>`
                    : ""
                }
              </div>`
        }
        <button type="button" class="plugin-toggle ${enabled ? "on" : ""}" data-plugin-toggle="${escapeAttr(item.id)}" role="switch" aria-checked="${enabled ? "true" : "false"}" aria-label="${escapeAttr(enabled ? `禁用 ${item.title}` : `启用 ${item.title}`)}" ${togglePending ? "disabled" : ""}>
          <span></span>
        </button>
      </div>
    </article>
  `;
}

function renderChromeIntegrationDialog() {
  const chrome = state.chromeIntegration;
  const snapshot = chrome.snapshot || {};
  const extension = snapshot.extension || {};
  const host = snapshot.nativeHost || {};
  const broker = snapshot.broker || {};
  const release = snapshot.release || broker.release || {};
  const approvals = Array.isArray(snapshot.pendingApprovals) ? snapshot.pendingApprovals : [];
  const audit = Array.isArray(snapshot.audit) ? snapshot.audit.slice(0, 12) : [];
  const busy = Boolean(chrome.busyAction);
  const connected = Boolean(extension.connected);
  const releaseEnabled = release.enabled !== false;
  const writeEnabled = release.writeEnabled !== false;
  return `
    <div class="modal-backdrop chrome-integration-backdrop" data-action="close-chrome-integration"></div>
    <dialog class="chrome-integration-dialog" open aria-labelledby="chromeIntegrationTitle">
      <header class="chrome-integration-header">
        <div class="chrome-integration-mark" aria-hidden="true">C</div>
        <div>
          <span class="chrome-integration-eyebrow">HAOLO FOR CHROME</span>
          <h2 id="chromeIntegrationTitle">Chrome 集成中心</h2>
          <p>安装、连接、权限审批和故障修复集中在这里。</p>
        </div>
        <button type="button" class="chrome-integration-close" data-action="close-chrome-integration" aria-label="关闭" ${busy ? "disabled" : ""}>×</button>
      </header>
      <div class="chrome-integration-body">
        ${chrome.loading && !chrome.snapshot ? `<div class="chrome-integration-loading"><i class="skill-detail-spinner"></i><span>正在检查 Chrome 集成…</span></div>` : ""}
        <section class="chrome-health-grid" aria-label="Chrome 集成状态">
          ${renderChromeHealthItem("扩展连接", connected ? "已连接" : extension.bundled ? "等待安装或连接" : "扩展文件缺失", connected ? "ready" : "warning", `${Number(broker.profileCount || 0)} 个 Chrome Profile`)}
          ${renderChromeHealthItem("Native Host", host.healthy ? "正常" : "需要修复", host.healthy ? "ready" : "danger", host.healthy ? "注册表与宿主一致" : chromeIssueLabel(host.issues))}
          ${renderChromeHealthItem("桌面 Broker", broker.running ? releaseEnabled ? "运行中" : "策略已暂停" : "未运行", broker.running && releaseEnabled ? "ready" : "danger", broker.running ? releaseEnabled ? writeEnabled ? "本机随机安全会话与浏览器写操作已启用" : "只读可用，写操作已紧急暂停" : `发布策略：${String(release.reason || "disabled")}` : "请重启或执行修复")}
        </section>

        ${releaseEnabled && !writeEnabled ? `<p class="chrome-integration-warning" role="status">紧急保护已开启：当前只允许读取与诊断，点击、输入、上传、下载和提交均会失败关闭。</p>` : ""}
        ${!releaseEnabled ? `<p class="chrome-integration-error" role="alert">Chrome 能力已由发布策略暂停；不会执行页面读取或写操作。请等待 Haolo 发布恢复配置。</p>` : ""}

        <section class="chrome-setup-card">
          <div>
            <span class="chrome-section-kicker">安装与修复</span>
            <h3>${connected ? "Chrome 已可以接收 Haolo 任务" : "完成一次 Chrome 扩展安装"}</h3>
            <p>${connected ? "扩展、Native Host 与桌面端链路均已建立。" : "打开扩展管理页，启用开发者模式后加载 Haolo 扩展目录；商店版发布后这里会切换为一键安装。"}</p>
          </div>
          <div class="chrome-setup-actions">
            <button type="button" data-chrome-action="open-extensions" ${busy ? "disabled" : ""}>打开 Chrome 扩展页</button>
            <button type="button" class="secondary" data-chrome-action="reveal-extension" ${busy || !extension.bundled ? "disabled" : ""}>显示扩展目录</button>
            <button type="button" class="secondary" data-chrome-action="repair" ${busy ? "disabled" : ""}>${chrome.busyAction === "repair" ? "修复中…" : "诊断并修复"}</button>
            <button type="button" class="ghost" data-chrome-action="refresh" ${busy || chrome.loading ? "disabled" : ""}>刷新状态</button>
          </div>
        </section>

        <section class="chrome-approval-section">
          <div class="chrome-section-heading">
            <div><span class="chrome-section-kicker">待你确认</span><h3>敏感动作审批</h3></div>
            <span class="chrome-count-badge">${approvals.length}</span>
          </div>
          ${approvals.length ? `<div class="chrome-approval-list">${approvals.map(renderChromeApprovalCard).join("")}</div>` : `<div class="chrome-empty-state"><strong>没有待审批动作</strong><span>发送、提交、上传、下载和历史记录读取会显示在这里。</span></div>`}
        </section>

        <section class="chrome-audit-section">
          <div class="chrome-section-heading"><div><span class="chrome-section-kicker">仅本机内存</span><h3>最近活动</h3></div></div>
          ${audit.length ? `<ol class="chrome-audit-list">${audit.map(renderChromeAuditRow).join("")}</ol>` : `<div class="chrome-empty-state compact"><span>暂无 Chrome 活动。</span></div>`}
        </section>
        ${chrome.selectedArtifact ? `<p class="chrome-artifact-feedback">已选择：${escapeHtml(chrome.selectedArtifact.name || "文件")} · ${formatChromeBytes(chrome.selectedArtifact.size)}</p>` : ""}
        ${chrome.error ? `<p class="chrome-integration-error" role="alert">${escapeHtml(chrome.error)}</p>` : ""}
      </div>
    </dialog>
  `;
}

function renderChromeHealthItem(label: string, value: string, tone: "ready" | "warning" | "danger", detail: string) {
  return `<article class="chrome-health-item" data-tone="${tone}"><span class="chrome-health-dot"></span><div><small>${escapeHtml(label)}</small><strong>${escapeHtml(value)}</strong><p>${escapeHtml(detail)}</p></div></article>`;
}

function renderChromeApprovalCard(entry: any) {
  const type = entry?.type === "history" ? "history" : "external";
  const item = type === "history" ? entry.request || {} : entry.operation || {};
  const id = String(item.id || "");
  const title = type === "history" ? `搜索历史记录：${entry.request?.query || ""}` : item.summary || chromeToolTitle(item.tool);
  const detail = type === "history"
    ? `最多 ${Number(entry.request?.maxResults || 20)} 条 · 权限使用后自动撤销`
    : `${item.origin || "当前网站"} · ${chromeEffectLabel(item.effectLevel)}`;
  const needsArtifact = Boolean(entry.artifact_required);
  const pending = state.chromeIntegration.busyAction?.endsWith(id);
  return `
    <article class="chrome-approval-card" data-effect="${escapeAttr(item.effectLevel || (type === "history" ? "high_impact" : "external_write"))}">
      <div class="chrome-approval-copy"><strong>${escapeHtml(title)}</strong><span>${escapeHtml(detail)}</span>${needsArtifact ? `<em>批准前请选择本次上传文件；网页无法看到本机路径。</em>` : ""}</div>
      <div class="chrome-approval-actions">
        ${needsArtifact ? `<button type="button" class="secondary" data-chrome-artifact="${escapeAttr(id)}" ${pending ? "disabled" : ""}>选择文件</button>` : ""}
        <button type="button" data-chrome-approval="approve" data-chrome-approval-id="${escapeAttr(id)}" data-chrome-approval-type="${type}" ${pending || needsArtifact ? "disabled" : ""}>${pending ? "处理中…" : "批准一次"}</button>
        <button type="button" class="ghost danger" data-chrome-approval="reject" data-chrome-approval-id="${escapeAttr(id)}" data-chrome-approval-type="${type}" ${pending ? "disabled" : ""}>拒绝</button>
      </div>
    </article>
  `;
}

function renderChromeAuditRow(entry: any) {
  const details = entry?.details && typeof entry.details === "object"
    ? Object.entries(entry.details).filter(([, value]) => value !== undefined).slice(0, 3).map(([key, value]) => `${key}: ${String(value)}`).join(" · ")
    : "";
  const timestamp = entry?.timestamp ? new Date(entry.timestamp).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" }) : "";
  return `<li><time>${escapeHtml(timestamp)}</time><div><strong>${escapeHtml(chromeAuditLabel(entry?.type))}</strong>${details ? `<span>${escapeHtml(details)}</span>` : ""}</div></li>`;
}

function chromeIssueLabel(issues: unknown) {
  const list = Array.isArray(issues) ? issues : [];
  const labels: Record<string, string> = { host_missing: "宿主程序缺失", manifest_missing: "宿主清单缺失", manifest_invalid: "宿主清单不匹配", registry_missing: "注册表项缺失", not_initialized: "尚未初始化" };
  return list.map((issue) => labels[String(issue)] || String(issue)).join("、") || "状态异常";
}

function chromeToolTitle(tool: unknown) {
  const labels: Record<string, string> = { prepare_external_action: "执行外部写入", upload_file: "上传本地文件", download: "下载文件" };
  return labels[String(tool)] || "Chrome 敏感动作";
}

function chromeEffectLabel(level: unknown) {
  return level === "high_impact" ? "高影响" : level === "external_write" ? "外部写入" : "受控操作";
}

function chromeAuditLabel(type: unknown) {
  const labels: Record<string, string> = { connection: "连接状态", tool_started: "开始工具调用", tool_completed: "工具调用完成", tool_failed: "工具调用失败", approval_requested: "请求审批", approval_updated: "审批状态变化", operation_approved: "操作已批准", approval_rejected: "操作已拒绝", task: "任务标签页", site_policy: "站点权限", repair: "集成修复", artifact_selected: "选择上传文件" };
  return labels[String(type)] || String(type || "Chrome 活动");
}

function formatChromeBytes(value: unknown) {
  const bytes = Number(value || 0);
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
}

function renderPluginMarketplaceIcon(icon: PluginMarketplaceIcon) {
  if (icon === "documents") {
    return `
      <svg viewBox="0 0 28 28" aria-hidden="true">
        <rect x="4" y="3" width="20" height="22" rx="4"></rect>
        <path d="M9 9h10M9 14h10M9 19h7"></path>
      </svg>
    `;
  }
  if (icon === "spreadsheets") {
    return `
      <svg viewBox="0 0 28 28" aria-hidden="true">
        <rect x="4" y="4" width="20" height="20" rx="4"></rect>
        <path d="M9 9h10M9 14h10M9 19h10M10 8v12M18 8v12"></path>
      </svg>
    `;
  }
  if (icon === "presentations") {
    return `
      <svg viewBox="0 0 28 28" aria-hidden="true">
        <rect x="5" y="6" width="18" height="15" rx="3"></rect>
        <path d="M10 21l-2 3M18 21l2 3M9 11h10M9 15h7"></path>
      </svg>
    `;
  }
  return `
    <svg viewBox="0 0 28 28" aria-hidden="true">
      <rect x="4" y="5" width="20" height="16" rx="4"></rect>
      <path d="M4 10h20M10 24l4-6 4 6M18 16l5 5"></path>
    </svg>
  `;
}

function renderSkillsPlazaPage() {
  if (state.skillsPlazaTab === "skills" && state.marketplace.selectedSkillId) {
    return renderSkillDetailPage();
  }
  if (state.skillsPlazaTab === "plugins") {
    return renderPluginMarketplacePage();
  }
  const collectionTab = state.skillsPlazaTab === "mySkills"
    || state.skillsPlazaTab === "indicators"
    || state.skillsPlazaTab === "quant"
    ? state.skillsPlazaTab
    : state.marketplace.mySkillsOnly || state.marketplace.subView === "mine"
      ? "mySkills"
      : null;
  const mySkillsView = collectionTab !== null;
  const categories = marketplaceFilterCategories();
  const query = state.skillSearch.trim().toLowerCase();
  const sourceCards = collectionTab === "mySkills"
    ? strategySkillPlazaCards()
    : collectionTab === "indicators"
      ? indicatorSkillPlazaCards()
      : collectionTab === "quant"
        ? []
        : state.marketplace.items.map(mapMarketplaceSkillToCard);
  const cards = sourceCards.filter((card) => {
    if (
      !mySkillsView &&
      state.skillCategory !== "all" &&
      card.category !== state.skillCategory &&
      card.rawCategory !== state.skillCategory
    ) {
      return false;
    }
    if (!query) return true;
    return `${card.title} ${card.subtitle} ${card.detail} ${card.author} ${card.tags.join(" ")}`
      .toLowerCase()
      .includes(query);
  });
  const showInitialLoading =
    !mySkillsView &&
    state.marketplace.loading &&
    !state.marketplace.items.length;
  const emptyMessage = collectionTab === "mySkills"
    ? "暂无策略"
    : collectionTab === "indicators"
      ? "暂无指标"
      : collectionTab === "quant"
        ? "暂无量化"
        : "没有找到匹配的技能";
  return `
    <main class="skills-plaza-page ${mySkillsView ? "my-skills-page" : ""}">
      ${renderSkillsPlazaTabs()}
      ${
        mySkillsView
          ? ""
          : `<section class="skills-filter-row">
              <div class="skills-plaza-categories">
                ${categories
                  .map((category) => {
                    const active = category.id === state.skillCategory;
                    return `
                      <button class="${active ? "active" : ""}" type="button" data-skill-category="${escapeAttr(category.id)}" aria-pressed="${active ? "true" : "false"}">
                        ${escapeHtml(category.label)}
                      </button>
                    `;
                  })
                  .join("")}
              </div>
              <div class="skills-plaza-filter-actions">
                ${renderSkillSortDropdown()}
                <button type="button" class="skills-my-button" data-action="show-my-skills" aria-pressed="false">策略</button>
              </div>
            </section>`
      }
      ${!mySkillsView && state.marketplace.error ? `<p class="skills-load-state error">${escapeHtml(state.marketplace.error)}</p>` : ""}
      ${showInitialLoading ? `<div class="skills-loading-center"><i class="skill-detail-spinner" aria-label="技能加载中"></i></div>` : ""}
      ${
        showInitialLoading
          ? ""
          : `<section class="${mySkillsView ? "my-skills-grid" : "skills-masonry"}${cards.length ? "" : " skills-empty-state"}">
              ${
                cards.length
                  ? cards.map((card) =>
                        mySkillsView ? renderMySkillPlazaCard(card) : renderSkillPlazaCard(card))
                      .join("")
                  : `<p class="skills-empty">${escapeHtml(emptyMessage)}</p>`
              }
            </section>`
      }
      ${!showInitialLoading && !mySkillsView && state.marketplace.loadingMore ? `<div class="skills-loading-more"><i class="skill-detail-spinner" aria-label="技能加载中"></i></div>` : ""}
    </main>
  `;
}

function mySkillsPlazaCards() {
  const localCards = state.skills.items.map(mapLocalSkillToCard);
  const localSkillNames = new Set(
    localCards.flatMap((card) => [card.title, card.subtitle]).map((value) => value.trim().toLowerCase()),
  );
  const tradingCards = tradingStrategyCatalog()
    .filter((strategy) => strategy.enabled !== false)
    .map((strategy): SkillPlazaCard => {
      const title = translateAppText(strategy.skill.displayName, state.settings.language);
      const detail = translateAppText(strategy.skill.shortDescription, state.settings.language);
      return {
        id: `${TRADING_STRATEGY_SKILL_CARD_PREFIX}${strategy.id}`,
        title,
        subtitle: strategy.id,
        detail,
        category: "local",
        rawCategory: "local",
        theme: "local",
        height: strategy.skill.shortDescription.length > 34 ? "medium" : "short",
        tags: ["交易策略", "K线分析"],
        badge: "已装",
        author: "本地",
        likes: "已安装",
        iconUrl: SKILL_DEFAULT_ICON_URL,
        defaultCover: true,
        installed: true,
        installStatus: "installed",
        version: strategy.version,
      };
    })
    .filter(
      (card) =>
        !localSkillNames.has(card.title.trim().toLowerCase()) &&
        !localSkillNames.has(card.subtitle.trim().toLowerCase()),
    );
  const personalCards = state.personalStrategies.items
    .filter((item) => item.status === "active")
    .map((item): SkillPlazaCard => ({
      id: `${PERSONAL_STRATEGY_SKILL_CARD_PREFIX}${item.id}`,
      title: item.name,
      subtitle: `我的策略 · v${item.version}`,
      detail: "按你的自然语言规则分析当前 K 线；可继续反馈优化并保留版本记录",
      category: "personal",
      rawCategory: "personal",
      theme: "local",
      height: "medium",
      tags: ["我的策略", "K线分析", "可优化"],
      badge: "我的策略",
      author: "仅本账号",
      likes: "已启用",
      iconUrl: SKILL_DEFAULT_ICON_URL,
      defaultCover: true,
      installed: true,
      installStatus: "installed",
      version: item.version,
    }));
  return [...localCards, ...tradingCards].concat(personalCards);
}

function strategySkillPlazaCards() {
  return mySkillsPlazaCards().filter((card) => card.id.startsWith(TRADING_STRATEGY_SKILL_CARD_PREFIX) || card.id.startsWith(PERSONAL_STRATEGY_SKILL_CARD_PREFIX));
}

function indicatorSkillPlazaCards(): SkillPlazaCard[] {
  const analysisCards = tradingIndicatorCatalog().map((indicator): SkillPlazaCard => {
    const title = translateAppText(indicator.skill.displayName, state.settings.language);
    const detail = translateAppText(indicator.skill.shortDescription, state.settings.language);
    return {
      id: `${TRADING_INDICATOR_SKILL_CARD_PREFIX}${indicator.id}`,
      title,
      subtitle: indicator.id,
      detail,
      category: "local",
      rawCategory: "local",
      theme: "local",
      height: indicator.skill.shortDescription.length > 34 ? "medium" : "short",
      tags: ["技术指标", "形态与背离"],
      badge: indicator.enabled === false ? "不可用" : "已装",
      author: "本地",
      likes: indicator.enabled === false ? "诊断失败" : "已安装",
      installed: indicator.enabled !== false,
      installStatus: indicator.enabled === false ? "failed" : "installed",
      version: indicator.version,
    };
  });
  return [
    {
      id: TRADING_TREND_BAND_SKILL_CARD_ID,
      title: translateAppText("趋势带", state.settings.language),
      subtitle: "trend-band",
      detail: translateAppText(
        "通过趋势蜡烛与均线带识别行情方向，辅助观察趋势延续与转折",
        state.settings.language,
      ),
      category: "local",
      rawCategory: "local",
      theme: "local",
      height: "short",
      tags: ["技术指标", "趋势分析"],
      badge: "已装",
      author: "本地",
      likes: "已安装",
      installed: true,
      installStatus: "installed",
      version: "1.0.0",
    },
    ...analysisCards,
  ];
}

function renderMySkillsPage() {
  const query = state.skillSearch.trim().toLowerCase();
  const marketplaceItems = state.marketplace.myItems.length
    ? state.marketplace.myItems.map(mapMarketplaceSkillToCompactCard)
    : state.marketplace.items
        .filter(
          (item) =>
            item.installed ||
            item.install_status === "installed" ||
            item.install_status === "installing",
        )
        .map(mapMarketplaceSkillToCompactCard);
  const localItems = state.skills.items.map(mapLocalSkillToCompactCard);
  const cards = (
    marketplaceItems.length || localItems.length
      ? [...marketplaceItems, ...localItems]
      : MY_SKILL_PLACEHOLDER_CARDS
  ).filter((card) => {
    if (!query) return true;
    return `${card.title} ${card.subtitle} ${card.author}`
      .toLowerCase()
      .includes(query);
  });
  const backTitle = `
        <button type="button" class="my-skills-back-title" data-action="back-from-my-skills" aria-label="返回">
          <svg viewBox="0 0 16 16" aria-hidden="true"><path d="M10 3 5 8l5 5"/></svg>
          <span>策略</span>
        </button>`;
  return `
    <main class="skills-plaza-page my-skills-page">
      <header class="skills-plaza-header">
        <span class="skills-plaza-title-spacer" aria-hidden="true"></span>
        <label class="skills-plaza-search">
          <img src="${escapeAttr(HOME_ICON_URL.search)}" alt="" />
          <input id="skillsSearch" value="${escapeAttr(state.skillSearch)}" placeholder="搜索" autocomplete="off" />
        </label>
        <div class="skills-plaza-actions">
          <button type="button" class="skills-import-button" data-action="open-skill-import">
            <img src="${escapeAttr(HOME_ICON_URL.skillImportAdd)}" alt="" />
            导入技能
          </button>
        </div>
      </header>
      <section class="skills-plaza-categories">
        <button class="active" type="button" data-action="show-my-skills">全部</button>
        <button type="button" data-action="show-skill-market">技能市场</button>
        <button type="button" data-action="open-skill-import">手动导入</button>
      </section>
      ${state.marketplace.myError ? `<p class="skills-load-state error">${escapeHtml(state.marketplace.myError)}</p>` : ""}
      ${state.marketplace.myLoading ? `<p class="skills-load-state">策略加载中...</p>` : ""}
      <section class="my-skills-grid">
        ${cards.length ? cards.map(renderMySkillCard).join("") : `<p class="skills-empty">暂无已安装技能</p>`}
      </section>
    </main>
  `.replace(
    '<header class="skills-plaza-header">',
    `<header class="skills-plaza-header">${backTitle}`,
  );
}

