function renderSkillPlazaCard(card: SkillPlazaCard) {
  if (card.defaultCover && !card.imageUrl) {
    card = { ...card, imageUrl: SKILL_DEFAULT_COVER_URL };
  }
  const posterClass = [
    "skill-poster",
    card.imageUrl ? "skill-poster-image" : "skill-poster-generated",
    card.defaultCover ? "skill-poster-default-cover" : "",
  ]
    .filter(Boolean)
    .join(" ");
  return `
    <article class="skill-card skill-card-${escapeAttr(card.theme)} skill-card-${escapeAttr(card.height)}" data-skill-id="${escapeAttr(card.id)}">
      <div class="${posterClass}">
        ${card.imageUrl ? renderSkillCoverImage(card) : renderGeneratedSkillPoster(card)}
      </div>
      <h2>${escapeHtml(card.title)}</h2>
      <footer>
        <span><img src="${escapeAttr(HOME_ICON_URL.messageActive)}" alt="" />${escapeHtml(card.author ?? "Haolo科技集团")}</span>
        <span>${escapeHtml(card.installStatus ? skillInstallStatusLabel(card.installStatus) : (card.likes ?? "532人点赞"))}</span>
      </footer>
    </article>
  `;
}

function renderSkillSortDropdown() {
  const options: Array<{ value: MarketplaceState["sort"]; label: string }> = [
    { value: "popular", label: "热门" },
    { value: "latest", label: "最新" },
  ];
  const current = options.find((item) => item.value === state.marketplace.sort) ?? options[0];
  return `
    <div class="skills-sort-wrap ${state.skillSortMenuOpen ? "open" : ""}">
      <button type="button" class="skills-sort-button" data-action="toggle-skill-sort" aria-haspopup="menu" aria-expanded="${state.skillSortMenuOpen ? "true" : "false"}">
        <img src="${escapeAttr(HOME_ICON_URL.skillSort)}" alt="" />
        ${escapeHtml(current.label)}
        <img class="skills-sort-chevron" src="${escapeAttr(HOME_ICON_URL.skillChevronDown)}" alt="" />
      </button>
      ${
        state.skillSortMenuOpen
          ? `<div class="skills-sort-menu" role="menu">
              ${options
                .map(
                  (item) => `
                    <button type="button" class="${item.value === state.marketplace.sort ? "active" : ""}" data-skill-sort="${item.value}" role="menuitem">
                      ${escapeHtml(item.label)}
                    </button>
                  `,
                )
                .join("")}
            </div>`
          : ""
      }
    </div>
  `;
}

function renderSkillCoverImage(card: SkillPlazaCard) {
  const image = skillCardImageDisplay(card);
  return `
    ${card.badge ? `<span class="skill-badge">${escapeHtml(card.badge)}</span>` : ""}
    ${
      image.display.status === "ready"
        ? `<img class="skill-cover-image ${image.iconFallback ? "skill-cover-icon" : ""}" src="${escapeAttr(image.display.url)}" alt="" loading="lazy" decoding="async" draggable="false" onerror="this.closest('.skill-poster')?.classList.add('skill-poster-failed'); this.remove();" />`
        : ""
    }
  `;
}

function skillCardImageDisplay(card: SkillPlazaCard) {
  const display = skillImageDisplay(card.imageUrl, `${card.title} cover`);
  if (display.status !== "error" || !card.iconUrl || card.iconUrl === card.imageUrl) {
    return {
      display,
      iconFallback: Boolean(card.iconUrl && card.imageUrl === card.iconUrl),
    };
  }
  return {
    display: skillImageDisplay(card.iconUrl, `${card.title} icon`),
    iconFallback: true,
  };
}

function renderGeneratedSkillPoster(card: SkillPlazaCard) {
  return `
    ${card.badge ? `<span class="skill-badge">${escapeHtml(card.badge)}</span>` : ""}
    <div class="skill-poster-mark">${renderSkillPosterMark(card.theme)}</div>
    <strong>${escapeHtml(card.title)}</strong>
  `;
}

function renderMySkillCard(card: MySkillCard) {
  const iconDisplay = skillImageDisplay(card.iconUrl, `${card.title} icon`);
  return `
    <article class="my-skill-card" ${card.placeholder ? "" : `data-skill-id="${escapeAttr(card.id)}"`}>
      <div class="my-skill-icon">
        ${iconDisplay.status === "ready" ? `<img src="${escapeAttr(iconDisplay.url)}" alt="" />` : `<span></span>`}
      </div>
      <div class="my-skill-copy">
        <h2>${escapeHtml(card.title)}</h2>
        <p>${escapeHtml(card.subtitle)}</p>
        <small><img src="${escapeAttr(HOME_ICON_URL.skillLocal)}" alt="" />${escapeHtml(card.author)}</small>
      </div>
    </article>
  `;
}

