function renderLibraryStatus(loadState: LibraryLoadState, loadingText: string) {
  if (loadState.loading) {
    return `<div class="library-status loading" aria-label="${escapeAttr(loadingText)}"><i class="library-spinner" aria-hidden="true"></i></div>`;
  }
  if (loadState.error) {
    return `<div class="library-status error">${escapeHtml(loadState.error)}</div>`;
  }
  return "";
}

type PreviewFile = {
  id: string;
  name: string;
  project: string;
  kind: PreviewKind;
  size?: string;
  sizeBytes?: number | null;
  time?: string;
  url?: string;
  mime?: string | null;
  body?: string;
};

function resultPreviewFile(row: ResultRow): PreviewFile {
  const url = previewUrlFromReferences(row.url, row.body) || row.url;
  const mime = row.mime || generatedFileMimeFromPath(row.title || url || row.body);
  return normalizePreviewFile({
    id: row.id,
    name: row.title,
    project: row.groupName || row.threadName,
    kind: inferPreviewKind(row.title, mime, url),
    size: row.sizeLabel,
    sizeBytes: row.sizeBytes,
    time: row.timeLabel,
    url: url || undefined,
    mime,
    body: row.body,
  });
}

function materialPreviewFile(row: MaterialRow): PreviewFile {
  return normalizePreviewFile({
    id: row.id,
    name: row.name,
    project: row.source,
    kind: inferPreviewKind(row.name, row.mime, row.url),
    size: row.sizeLabel,
    sizeBytes: row.sizeBytes,
    time: row.timeLabel,
    url: row.url,
    mime: row.mime,
  });
}

function normalizePreviewFile(file: PreviewFile): PreviewFile {
  if (!file.url || isRemoteLikeUrlReference(file.url) || /^(blob:|data:)/i.test(file.url)) return file;
  const url = localPathPreviewUrl(file.url);
  if (!isLocalPreviewUrl(url)) {
    return {
      ...file,
      url: undefined,
    };
  }
  return {
    ...file,
    url,
    kind: inferPreviewKind(file.name, file.mime, url),
  };
}

type PreviewSource = "result" | "material" | "chat";
const PREVIEW_COLLAPSE_MS = 240;

function renderPreviewPanel(file: PreviewFile, source: PreviewSource) {
  const zoom = previewZoomForSource(source);
  const canOpen = Boolean(file.url);
  const closing = state.closingPreviewSource === source;
  const edgeToggle =
    source === "chat"
      ? ""
      : `
        <button type="button" class="small-icon-button panel-toggle expanded preview-edge-toggle" data-preview-action="close" data-preview-source="${source}" title="收起预览" aria-label="收起预览" aria-expanded="true">
          ${renderPanelLayoutIcon("right")}
        </button>
      `;
  const chatStyle = source === "chat" ? ` style="--chat-preview-width:${chatPreviewWidthPercent()}%;"` : "";
  return `
    <aside class="library-preview-panel ${source === "chat" ? "chat-preview-panel" : "has-edge-toggle"} ${closing ? "collapsed" : ""}" data-preview-panel="${source}"${chatStyle}>
      ${source === "chat" ? `<div class="chat-preview-resizer" data-chat-preview-resizer aria-label="调整预览宽度" role="separator"></div>` : ""}
      ${edgeToggle}
      <header>
        <strong>${escapeHtml(file.name.replace(/\.[^.]+$/, ""))}</strong>
        <span class="library-preview-actions">
          <button type="button" data-preview-action="zoom-in" data-preview-source="${source}" title="放大" aria-label="放大">
            <img src="${escapeAttr(HOME_ICON_URL.previewZoomIn)}" alt="" />
          </button>
          <button type="button" data-preview-action="zoom-out" data-preview-source="${source}" title="缩小" aria-label="缩小">
            <img src="${escapeAttr(HOME_ICON_URL.previewZoomOut)}" alt="" />
          </button>
          <button type="button" class="preview-open-file-action" data-preview-action="download" data-preview-source="${source}" ${canOpen ? "" : "disabled"} title="打开文件" aria-label="打开文件">
            <img src="${escapeAttr(HOME_ICON_URL.fileOpenExternal)}" alt="" />
          </button>
        </span>
      </header>
      <section class="library-preview-body">
        ${renderPreviewBody(file, zoom, source)}
      </section>
    </aside>
  `;
}

function renderPreviewPlaceholder() {
  return "";
}

function renderPreviewOpenButton(source: Exclude<PreviewSource, "chat">) {
  return `
    <button type="button" class="small-icon-button panel-toggle preview-open-toggle" data-preview-open="${source}" title="展开预览" aria-label="展开预览" aria-expanded="false">
      ${renderPanelLayoutIcon("right")}
    </button>
  `;
}

function renderChatPreviewPanel() {
  if (!state.chatPreview) return "";
  return renderPreviewPanel(state.chatPreview.file, "chat");
}

function previewZoomForSource(source: PreviewSource) {
  if (source === "material") return state.materialPreviewZoom;
  if (source === "chat") return state.chatPreview?.zoom ?? 100;
  return state.resultPreviewZoom;
}

function chatPreviewWidthPercent() {
  return Math.min(Math.max(state.chatPreview?.widthPercent ?? 44, 30), 54);
}

function renderPreviewBody(file: PreviewFile, zoom: number, source: PreviewSource) {
  const scaleStyle = `style="--preview-scale:${zoom / 100}; --preview-width:${10000 / zoom}%;"`;
  const dragAttrs = source === "material" ? "" : fileDragAttributes(file);
  const previewUrl = previewDisplayUrl(file);
  const previewResource = state.previewResources[previewResourceKey(file)];
  const displayKind = previewResource?.status === "ready" && previewResource.convertedKind ? previewResource.convertedKind : file.kind;
  if (file.url && (isRemotePreviewUrl(file.url) || isLocalPreviewUrl(file.url)) && isDirectPreviewKind(file.kind)) {
    const resource = ensurePreviewResource(file);
    if (resource.status === "loading") return renderPreviewLoading("正在生成预览...");
    if (resource.status === "error") return renderPreviewError(file, resource.error || "预览失败");
  }

  if (previewUrl && displayKind === "image") {
    return `<img class="preview-image" ${scaleStyle}${dragAttrs} src="${escapeAttr(previewUrl)}" alt="${escapeAttr(file.name)}" />`;
  }
  if (previewUrl && displayKind === "video") {
    const videoKey = previewVideoKeyFromSrc(previewUrl);
    return `<div class="preview-frame dark" ${scaleStyle}${dragAttrs} data-preview-video-slot="${escapeAttr(videoKey)}"><video src="${escapeAttr(previewUrl)}" controls preload="auto" playsinline></video></div>`;
  }
  if (previewUrl && displayKind === "pdf") {
    return `<iframe class="preview-frame" ${scaleStyle} src="${escapeAttr(previewUrlWithHash(previewUrl, "toolbar=0&navpanes=0&scrollbar=1"))}" title="${escapeAttr(file.name)}"></iframe>`;
  }
  if (previewUrl && displayKind === "html") {
    return `<iframe class="preview-frame" ${scaleStyle} src="${escapeAttr(previewUrl)}" title="${escapeAttr(file.name)}" sandbox="allow-scripts allow-forms allow-popups"></iframe>`;
  }
  if (file.kind === "markdown") {
    const resource = state.previewResources[previewResourceKey(file)];
    if (resource?.text != null) return renderMarkdownPreview(resource.text, scaleStyle, resource);
    if (file.body) return renderMarkdownPreview(file.body, scaleStyle);
  }
  if (file.kind === "text") {
    const resource = state.previewResources[previewResourceKey(file)];
    if (resource?.text != null) return renderTextPreview(resource.text, scaleStyle, resource);
    if (previewUrl) {
      return `<iframe class="preview-frame text-frame" ${scaleStyle} src="${escapeAttr(previewUrl)}" title="${escapeAttr(file.name)}"></iframe>`;
    }
  }
  if (previewUrl && isOfficeKind(displayKind)) {
    return renderOfficePreview(file, previewUrl, scaleStyle);
  }
  if (file.kind === "text" || file.body) {
    return renderTextPreview(file.body || file.url || "文本内容为空", scaleStyle);
  }
  return renderPreviewUnsupported(file, "当前文件类型暂不支持直接预览");
}

function renderTextPreview(text: string, scaleStyle: string, resource?: PreviewResource) {
  const truncated = Boolean(resource?.truncated);
  const previewSize = formatBytes(resource?.previewBytes ?? null);
  const totalSize = formatBytes(resource?.sizeBytes ?? null);
  return `
    <article class="preview-text ${truncated ? "truncated" : ""}" ${scaleStyle}>
      ${
        truncated
          ? `<div class="preview-text-notice">仅预览前 ${escapeHtml(previewSize || "部分")}，完整文件 ${escapeHtml(totalSize || "")} 可通过下载打开。</div>`
          : ""
      }
      <pre>${escapeHtml(text || "文本内容为空")}</pre>
    </article>
  `;
}

function renderMarkdownPreview(text: string, scaleStyle: string, resource?: PreviewResource) {
  const truncated = Boolean(resource?.truncated);
  const previewSize = formatBytes(resource?.previewBytes ?? null);
  const totalSize = formatBytes(resource?.sizeBytes ?? null);
  return `
    <article class="preview-markdown ${truncated ? "truncated" : ""}" ${scaleStyle}>
      ${
        truncated
          ? `<div class="preview-text-notice">仅预览前 ${escapeHtml(previewSize || "部分")}，完整文件 ${escapeHtml(totalSize || "")} 可通过下载打开。</div>`
          : ""
      }
      ${renderPreviewMarkdown(text || "Markdown 内容为空")}
    </article>
  `;
}

function renderPreviewMarkdown(markdown: string) {
  const lines = markdown.replace(/\r\n?/g, "\n").split("\n");
  const output: string[] = [];
  const paragraph: string[] = [];
  const flushParagraph = () => {
    if (!paragraph.length) return;
    output.push(`<p>${formatPreviewMarkdownInline(paragraph.join(" "))}</p>`);
    paragraph.length = 0;
  };

  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    const fence = line.match(/^\s*```([\w+#.-]*)\s*$/);
    if (fence) {
      flushParagraph();
      const codeLines: string[] = [];
      let cursor = index + 1;
      while (cursor < lines.length && !/^\s*```\s*$/.test(lines[cursor])) {
        codeLines.push(lines[cursor]);
        cursor += 1;
      }
      output.push(renderPreviewMarkdownCodeBlock(codeLines.join("\n"), fence[1] || ""));
      index = cursor;
      continue;
    }

    if (!line.trim()) {
      flushParagraph();
      continue;
    }

    if (isMarkdownTableStart(lines, index)) {
      flushParagraph();
      const table = renderPreviewMarkdownTable(lines, index);
      output.push(table.html);
      index = table.nextIndex - 1;
      continue;
    }

    const heading = line.match(/^\s{0,3}(#{1,6})\s+(.+?)\s*#*\s*$/);
    if (heading) {
      flushParagraph();
      const level = heading[1].length;
      output.push(`<h${level}>${formatPreviewMarkdownInline(heading[2])}</h${level}>`);
      continue;
    }

    if (/^\s{0,3}([-*_])(?:\s*\1){2,}\s*$/.test(line)) {
      flushParagraph();
      output.push("<hr />");
      continue;
    }

    const quote = line.match(/^\s{0,3}>\s?(.*)$/);
    if (quote) {
      flushParagraph();
      const quoteLines = [quote[1]];
      let cursor = index + 1;
      while (cursor < lines.length) {
        const nextQuote = lines[cursor].match(/^\s{0,3}>\s?(.*)$/);
        if (!nextQuote) break;
        quoteLines.push(nextQuote[1]);
        cursor += 1;
      }
      output.push(`<blockquote>${quoteLines.map((item) => `<p>${formatPreviewMarkdownInline(item)}</p>`).join("")}</blockquote>`);
      index = cursor - 1;
      continue;
    }

    const unordered = line.match(/^\s{0,3}[-*+]\s+(.+)$/);
    const ordered = line.match(/^\s{0,3}\d+[.)]\s+(.+)$/);
    if (unordered || ordered) {
      flushParagraph();
      const orderedList = Boolean(ordered);
      const items: string[] = [];
      let cursor = index;
      while (cursor < lines.length) {
        const match = orderedList ? lines[cursor].match(/^\s{0,3}\d+[.)]\s+(.+)$/) : lines[cursor].match(/^\s{0,3}[-*+]\s+(.+)$/);
        if (!match) break;
        items.push(`<li>${formatPreviewMarkdownInline(match[1])}</li>`);
        cursor += 1;
      }
      const tag = orderedList ? "ol" : "ul";
      output.push(`<${tag}>${items.join("")}</${tag}>`);
      index = cursor - 1;
      continue;
    }

    paragraph.push(line.trim());
  }

  flushParagraph();
  return output.join("");
}

function renderPreviewMarkdownCodeBlock(code: string, lang: string) {
  return `
    <div class="preview-markdown-code">
      ${lang ? `<div class="preview-markdown-code-lang">${escapeHtml(lang)}</div>` : ""}
      <pre><code>${escapeHtml(code)}</code></pre>
    </div>
  `;
}

function renderPreviewMarkdownTable(lines: string[], startIndex: number) {
  const headers = splitMarkdownTableRow(lines[startIndex]);
  const alignments = splitMarkdownTableRow(lines[startIndex + 1]).map((cell) => {
    const text = cell.trim();
    if (text.startsWith(":") && text.endsWith(":")) return "center";
    if (text.endsWith(":")) return "right";
    return "left";
  });
  const rows: string[][] = [];
  let index = startIndex + 2;
  while (index < lines.length) {
    const cells = splitMarkdownTableRow(lines[index]);
    if (cells.length < 2) break;
    rows.push(cells);
    index += 1;
  }
  const html = `
    <div class="preview-markdown-table-wrap">
      <table>
        <thead>
          <tr>
            ${headers.map((cell, column) => `<th style="text-align:${alignments[column] || "left"}">${formatPreviewMarkdownInline(cell.trim())}</th>`).join("")}
          </tr>
        </thead>
        <tbody>
          ${rows
            .map(
              (row) => `
                <tr>
                  ${headers
                    .map((_, column) => `<td style="text-align:${alignments[column] || "left"}">${formatPreviewMarkdownInline((row[column] || "").trim())}</td>`)
                    .join("")}
                </tr>
              `,
            )
            .join("")}
        </tbody>
      </table>
    </div>
  `;
  return { html, nextIndex: index };
}

function formatPreviewMarkdownInline(text: string) {
  const pattern = /(`[^`\n]+`)|(!?)\[([^\]\n]{1,240})\]\s*\(\s*([^)]+?)\s*\)|(https?:\/\/[^\s`"'“”‘’<>]+)/g;
  let output = "";
  let lastIndex = 0;
  for (const match of text.matchAll(pattern)) {
    const index = match.index ?? 0;
    output += escapeHtml(text.slice(lastIndex, index));
    const inlineCode = match[1];
    const isImage = Boolean(match[2]);
    const label = match[3]?.trim() || "";
    const markdownUrl = match[4];
    const bareUrl = match[5];
    if (inlineCode) {
      output += `<code>${escapeHtml(inlineCode.slice(1, -1))}</code>`;
    } else if (markdownUrl) {
      const url = cleanMarkdownUrl(markdownUrl);
      if (isImage || !isSafeExternalUrl(url)) {
        output += escapeHtml(label || match[0]);
      } else {
        output += renderPreviewMarkdownLink(label || labelForBareUrl(url), url);
      }
    } else if (bareUrl) {
      const url = cleanMarkdownUrl(bareUrl);
      if (isSafeExternalUrl(url)) {
        output += renderPreviewMarkdownLink(labelForBareUrl(url), url);
        output += escapeHtml(bareUrl.slice(url.length));
      } else {
        output += escapeHtml(match[0]);
      }
    } else {
      output += escapeHtml(match[0]);
    }
    lastIndex = index + match[0].length;
  }
  output += escapeHtml(text.slice(lastIndex));
  return applyInlineEmphasis(output);
}

function renderPreviewMarkdownLink(label: string, url: string) {
  return `<button type="button" class="preview-markdown-link" data-message-link="${escapeAttr(url)}" title="${escapeAttr(url)}">${escapeHtml(label || url)}</button>`;
}

function formatBytes(value: number | null | undefined) {
  if (!Number.isFinite(value) || value == null || value < 0) return "";
  if (value < 1024) return `${value} B`;
  const units = ["KB", "MB", "GB"];
  let size = value / 1024;
  let unitIndex = 0;
  while (size >= 1024 && unitIndex < units.length - 1) {
    size /= 1024;
    unitIndex += 1;
  }
  return `${size >= 10 ? size.toFixed(0) : size.toFixed(1)} ${units[unitIndex]}`;
}

function renderOfficePreview(file: PreviewFile, previewUrl: string, scaleStyle: string) {
  const key = officePreviewKey(file, previewUrl);
  const state = ensureOfficePreview(file, previewUrl, key);
  if (state.status === "loading") return renderPreviewLoading("正在生成预览...");
  if (state.status === "error") return renderPreviewUnsupported(file, state.error);
  if (state.preview.type === "document") return renderDocumentPreview(state.preview, scaleStyle);
  if (state.preview.type === "sheet") return renderSpreadsheetPreview(state.preview, key, scaleStyle);
  return renderSlidesPreview(state.preview, scaleStyle);
}

function renderDocumentPreview(preview: Extract<OfficePreviewData, { type: "document" }>, scaleStyle: string) {
  return `
    <article class="preview-document" ${scaleStyle}>
      ${preview.blocks
        .map((block) => {
          if (block.type === "image") {
            return `<img src="${escapeAttr(block.src)}" alt="${escapeAttr(block.alt)}" />`;
          }
          return `
            <p>
              ${block.listLabel ? `<span>${escapeHtml(block.listLabel)}</span>` : ""}
              <span>${escapeHtml(block.text || "\u00A0")}</span>
            </p>
          `;
        })
        .join("")}
    </article>
  `;
}

function renderSpreadsheetPreview(preview: Extract<OfficePreviewData, { type: "sheet" }>, key: string, scaleStyle: string) {
  const activeSheet = state.officeActiveSheets[key] ?? preview.activeSheet;
  const sheet = preview.sheets[activeSheet] ?? preview.sheets[0] ?? { name: "Sheet1", rows: [[""]] };
  const rows = sheet.rows.length ? sheet.rows : [[""]];
  const columnCount = Math.max(10, ...rows.map((row) => row.length));
  return `
    <div class="preview-sheet" ${scaleStyle}>
      <div class="preview-sheet-grid">
        <table>
          <thead>
            <tr>
              <th></th>
              ${Array.from({ length: columnCount }, (_, index) => `<th>${indexToExcelColumn(index)}</th>`).join("")}
            </tr>
          </thead>
          <tbody>
            ${rows
              .map(
                (row, rowIndex) => `
                  <tr>
                    <th>${rowIndex + 1}</th>
                    ${Array.from({ length: columnCount }, (_, cellIndex) => {
                      const cell = row[cellIndex] ?? "";
                      return `<td title="${escapeAttr(cell)}"><div>${escapeHtml(cell)}</div></td>`;
                    }).join("")}
                  </tr>
                `,
              )
              .join("")}
          </tbody>
        </table>
      </div>
      <div class="preview-sheet-tabs">
        ${preview.sheets
          .map(
            (item, index) => `
              <button type="button" class="${index === activeSheet ? "active" : ""}" data-office-sheet-key="${escapeAttr(key)}" data-office-sheet-index="${index}">
                ${escapeHtml(item.name)}
              </button>
            `,
          )
          .join("")}
      </div>
    </div>
  `;
}

function renderSlidesPreview(preview: Extract<OfficePreviewData, { type: "slides" }>, scaleStyle: string) {
  return `
    <div class="preview-slides" ${scaleStyle}>
      ${preview.slides
        .map(
          (slide, index) => `
            <section>
              <div class="preview-slide-label">第 ${index + 1} 页</div>
              <div class="preview-slide-page">
                ${slide
                  .map((block) =>
                    block.type === "image"
                      ? `<img src="${escapeAttr(block.src)}" alt="${escapeAttr(block.alt)}" />`
                      : `<p>${escapeHtml(block.text)}</p>`,
                  )
                  .join("")}
              </div>
            </section>
          `,
        )
        .join("")}
    </div>
  `;
}

function renderPreviewLoading(text: string) {
  return `
    <div class="preview-loading">
      <span></span>
      <strong>${escapeHtml(text)}</strong>
    </div>
  `;
}

function renderPreviewError(file: PreviewFile, message: string, dragAttrs = "") {
  return renderPreviewUnsupported(file, message, dragAttrs);
}

function renderPreviewUnsupported(file: PreviewFile, message: string, dragAttrs = "") {
  return `
    <div class="preview-unsupported"${dragAttrs}>
      <span class="library-file-thumb large">${renderFileThumb(file)}</span>
      <strong>${escapeHtml(file.name)}</strong>
      <small>${escapeHtml([file.size || "未知大小", message].join(" · "))}</small>
    </div>
  `;
}

function previewDisplayUrl(file: PreviewFile) {
  if (!file.url) return null;
  if (/^(blob:|data:)/i.test(file.url)) return file.url;
  if (!isDirectPreviewKind(file.kind)) return null;
  if (isRemotePreviewUrl(file.url) || isLocalPreviewUrl(file.url)) {
    const resource = state.previewResources[previewResourceKey(file)];
    return resource?.status === "ready" ? resource.objectUrl || null : null;
  }
  return file.url;
}

type SkillImageDisplay =
  | { status: "ready"; url: string }
  | { status: "loading" }
  | { status: "error"; error: string };

function imageDisplay(url: string | null | undefined, fallbackName: string, project = "local file"): SkillImageDisplay {
  const imageUrl = firstString(url);
  if (!imageUrl) return { status: "error", error: "missing image" };
  if (/^(blob:|data:)/i.test(imageUrl) || !isLocalPreviewUrl(imageUrl)) {
    return { status: "ready", url: imageUrl };
  }
  const name = fileNameFromReference(imageUrl) || fallbackName;
  const file: PreviewFile = {
    id: imageUrl,
    name,
    project,
    kind: "image",
    url: imageUrl,
    mime: generatedFileMimeFromPath(name || imageUrl),
  };
  const resource = ensurePreviewResource(file);
  if (resource.status === "ready" && resource.objectUrl) return { status: "ready", url: resource.objectUrl };
  if (resource.status === "error") return { status: "error", error: resource.error || "image preview failed" };
  return { status: "loading" };
}

function skillImageDisplay(url: string | null | undefined, fallbackName: string): SkillImageDisplay {
  return imageDisplay(url, fallbackName, "local skill");
}

function ensurePreviewResource(file: PreviewFile) {
  const key = previewResourceKey(file);
  const existing = state.previewResources[key];
  if (existing) return existing;

  state.previewResources[key] = { status: "loading" };
  void loadPreviewResource(file, key);
  return state.previewResources[key];
}

async function loadPreviewResource(file: PreviewFile, key: string) {
  try {
    const response = await api.previewFile({
      url: file.url || "",
      name: file.name,
      mime: file.mime,
      cwd: threadWorkspaceCwd(state.currentThreadId),
    });
    if (response?.missing) {
      revokePreviewResource(key);
      state.previewResources[key] = { status: "error", error: "preview file missing" };
      return;
    }
    const convertedKind = previewConvertedKind(file, response);
    const resourceKind = convertedKind || file.kind;
    const mime = convertedKind ? mimeFromPreviewKind(convertedKind, response?.name || file.name) : previewMime(file, response?.mime);
    const text = resourceKind === "text" || resourceKind === "html" || resourceKind === "markdown" ? textFromBase64(response?.base64 || "") : undefined;
    const objectUrl =
      resourceKind === "text" || resourceKind === "markdown"
        ? undefined
        : objectUrlFromBase64(
            text != null && resourceKind === "html" ? base64FromText(withHtmlBase(text, file.url)) : response?.base64 || "",
            mime,
          );
    revokePreviewResource(key);
    state.previewResources[key] = {
      status: "ready",
      objectUrl,
      mime,
      text: resourceKind === "text" || resourceKind === "markdown" ? text : undefined,
      truncated: Boolean(response?.truncated),
      previewBytes: numericValue(response?.previewBytes) ?? null,
      sizeBytes: numericValue(response?.sizeBytes) ?? null,
      convertedKind,
      convertedName: firstString(response?.convertedName, response?.name) || null,
    };
  } catch (error) {
    revokePreviewResource(key);
    state.previewResources[key] = { status: "error", error: errorMessage(error) };
  }
  render();
}

async function ensureVideoPosterResource(file: PreviewFile, videoUrl: string) {
  const key = previewResourceKey(file);
  const resource = state.previewResources[key];
  if (resource && resource.status !== "ready") return;
  if (resource?.objectUrl && resource.objectUrl !== videoUrl) return;
  const readyResource: PreviewResource = resource || { status: "ready", objectUrl: videoUrl, mime: file.mime || null };
  if (readyResource.posterLoading || readyResource.posterFrameTime === -1 || (readyResource.posterUrl && readyResource.posterFrameTime != null)) return;
  state.previewResources[key] = { ...readyResource, objectUrl: readyResource.objectUrl || videoUrl, posterLoading: true };
  try {
    const poster = await createVideoPosterUrl(videoUrl);
    const latest = state.previewResources[key];
    if (!latest || latest.status !== "ready" || latest.objectUrl !== videoUrl) {
      revokeVideoPosterObjectUrl(poster.url);
      return;
    }
    if (latest.posterUrl && latest.posterUrl !== poster.url) revokeVideoPosterObjectUrl(latest.posterUrl);
    state.previewResources[key] = { ...latest, posterUrl: poster.url, posterFrameTime: poster.time, posterLoading: false };
    render();
  } catch {
    const latest = state.previewResources[key];
    if (!latest || latest.status !== "ready" || latest.objectUrl !== videoUrl) return;
    if (latest.posterUrl && latest.posterFrameTime == null) {
      revokeVideoPosterObjectUrl(latest.posterUrl);
      const nextResource: PreviewResource = { ...latest, posterLoading: false, posterFrameTime: -1 };
      delete nextResource.posterUrl;
      state.previewResources[key] = nextResource;
      render();
      return;
    }
    state.previewResources[key] = { ...latest, posterLoading: false, posterFrameTime: latest.posterFrameTime ?? -1 };
    // First-frame posters are best effort; keep the stable video placeholder on failure.
  }
}

function createVideoPosterUrl(videoUrl: string) {
  return new Promise<{ url: string; time: number }>(async (resolve, reject) => {
    const video = document.createElement("video");
    let settled = false;
    video.preload = "auto";
    video.muted = true;
    video.playsInline = true;
    if (/^https?:\/\//i.test(videoUrl)) video.crossOrigin = "anonymous";
    const timeout = window.setTimeout(() => fail(), 7000);
    const cleanup = () => {
      window.clearTimeout(timeout);
      video.removeAttribute("src");
      video.load();
    };
    const fail = () => {
      if (settled) return;
      settled = true;
      cleanup();
      reject(new Error("video poster failed"));
    };
    const capture = async () => {
      if (settled) return;
      try {
        const duration = Number.isFinite(video.duration) ? video.duration : 0;
        const offsets = [0, 0.05, 0.2, 0.5, 1, 2].filter((offset) => !duration || offset < duration);
        const seekPoints = offsets.length ? offsets : [0];
        const width = video.videoWidth || 640;
        const height = video.videoHeight || 360;
        if (!video.videoWidth || !video.videoHeight) throw new Error("missing video dimensions");
        const canvas = document.createElement("canvas");
        canvas.width = width;
        canvas.height = height;
        const context = canvas.getContext("2d");
        if (!context) throw new Error("video poster canvas failed");
        let bestBlob: Blob | null = null;
        let bestTime = seekPoints[0] ?? 0;
        for (const time of seekPoints) {
          await seekVideoFrame(video, time);
          context.drawImage(video, 0, 0, width, height);
          const blob = await canvasBlob(canvas, "image/jpeg", 0.84);
          if (!blob) continue;
          bestBlob = blob;
          bestTime = time;
          if (!canvasLooksMostlyBlack(context, width, height)) break;
        }
        if (!bestBlob) throw new Error("video poster blob failed");
        settled = true;
        cleanup();
        const posterUrl = URL.createObjectURL(bestBlob);
        liveVideoPosterObjectUrls.add(posterUrl);
        resolve({ url: posterUrl, time: bestTime });
      } catch (error) {
        settled = true;
        cleanup();
        reject(error instanceof Error ? error : new Error(String(error)));
      }
    };
    video.addEventListener("error", fail, { once: true });
    video.addEventListener("loadedmetadata", () => void capture(), { once: true });
    video.src = videoUrl;
    video.load();
  });
}

function seekVideoFrame(video: HTMLVideoElement, time: number) {
  return new Promise<void>((resolve, reject) => {
    let done = false;
    const timeout = window.setTimeout(() => finish(false), 1800);
    const finish = (ok: boolean) => {
      if (done) return;
      done = true;
      window.clearTimeout(timeout);
      video.removeEventListener("seeked", onSeeked);
      if (ok) {
        waitForVideoFrame(video).then(resolve).catch(resolve);
      } else {
        reject(new Error("video seek failed"));
      }
    };
    const onSeeked = () => finish(true);
    const targetTime = Math.max(0, time);
    video.addEventListener("seeked", onSeeked, { once: true });
    if (Math.abs(video.currentTime - targetTime) < 0.001 && video.readyState >= 2) {
      finish(true);
      return;
    }
    try {
      video.currentTime = targetTime;
    } catch {
      finish(false);
    }
  });
}

function waitForVideoFrame(video: HTMLVideoElement) {
  return new Promise<void>((resolve) => {
    let done = false;
    const finish = () => {
      if (done) return;
      done = true;
      window.clearTimeout(timeout);
      resolve();
    };
    const timeout = window.setTimeout(finish, 160);
    const callback = (video as HTMLVideoElement & { requestVideoFrameCallback?: (callback: () => void) => void }).requestVideoFrameCallback;
    if (typeof callback === "function") {
      callback.call(video, finish);
      return;
    }
    window.requestAnimationFrame(finish);
  });
}

function canvasBlob(canvas: HTMLCanvasElement, type: string, quality: number) {
  return new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, type, quality));
}

function canvasLooksMostlyBlack(context: CanvasRenderingContext2D, width: number, height: number) {
  const sampleCanvas = document.createElement("canvas");
  sampleCanvas.width = 24;
  sampleCanvas.height = 24;
  const sampleContext = sampleCanvas.getContext("2d");
  if (!sampleContext) return false;
  sampleContext.drawImage(context.canvas, 0, 0, width, height, 0, 0, sampleCanvas.width, sampleCanvas.height);
  const data = sampleContext.getImageData(0, 0, sampleCanvas.width, sampleCanvas.height).data;
  let brightPixels = 0;
  for (let index = 0; index < data.length; index += 4) {
    if (data[index] + data[index + 1] + data[index + 2] > 48) brightPixels += 1;
  }
  return brightPixels / (sampleCanvas.width * sampleCanvas.height) < 0.03;
}

function isRemotePreviewUrl(url: string) {
  return /^https?:\/\//i.test(url);
}

function isLocalPreviewUrl(url: string) {
  const raw = url.trim();
  if (isRemoteLikeUrlReference(raw)) return false;
  const normalized = raw.replace(/\\/g, "/");
  if (/^file:\/\//i.test(normalized))
    return isAbsoluteFilePreviewUrl(normalized);
  return (
    /^[a-z]:\/(?!\/)/i.test(normalized) ||
    /^\/[a-z]:\/(?!\/)/i.test(normalized) ||
    /^\/\//.test(normalized) ||
    normalized.startsWith("/")
  );
}

function isAbsoluteFilePreviewUrl(url: string) {
  try {
    const parsed = new URL(url);
    if (parsed.protocol !== "file:") return false;
    if (parsed.hostname && parsed.hostname.toLowerCase() !== "localhost") {
      return Boolean(parsed.pathname && parsed.pathname !== "/");
    }
    return Boolean(parsed.pathname && parsed.pathname.startsWith("/"));
  } catch {
    return false;
  }
}

function isDirectPreviewKind(kind: PreviewKind) {
  return (
    kind === "image" || kind === "video" || kind === "pdf" || kind === "html" || kind === "markdown" || kind === "text" || isOfficeKind(kind)
  );
}

function previewResourceKey(file: PreviewFile) {
  return `${file.url || ""}\n${file.name}\n${file.mime || ""}`;
}

function objectUrlFromBase64(base64: string, mime: string) {
  const bytes = bytesFromBase64(base64);
  return URL.createObjectURL(new Blob([bytes.buffer as ArrayBuffer], { type: mime }));
}

function bytesFromBase64(base64: string) {
  const binary = window.atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }
  return bytes;
}

function textFromBase64(base64: string) {
  return new TextDecoder().decode(bytesFromBase64(base64));
}

function base64FromText(text: string) {
  const bytes = new TextEncoder().encode(text);
  let binary = "";
  bytes.forEach((byte) => {
    binary += String.fromCharCode(byte);
  });
  return window.btoa(binary);
}

function previewMime(file: PreviewFile, responseMime?: string | null) {
  const source = firstString(file.mime, responseMime);
  if (file.kind === "image" && source?.startsWith("image/")) return source;
  if (file.kind === "video" && source?.startsWith("video/")) return source;
  return mimeFromPreviewKind(file.kind, file.name);
}

function previewConvertedKind(file: PreviewFile, response: any): PreviewKind | null {
  const explicitKind = firstString(response?.convertedPreviewKind, response?.previewKind, response?.kind);
  if (isPreviewKind(explicitKind)) return explicitKind;
  const responseMime = firstString(response?.mime);
  if (isOfficeKind(file.kind) && responseMime?.toLowerCase() === "application/pdf") return "pdf";
  return null;
}

function isPreviewKind(value: unknown): value is PreviewKind {
  return (
    value === "image" ||
    value === "video" ||
    value === "pdf" ||
    value === "html" ||
    value === "markdown" ||
    value === "text" ||
    value === "word" ||
    value === "excel" ||
    value === "ppt" ||
    value === "unknown"
  );
}

function mimeFromPreviewKind(kind: PreviewKind, name = "") {
  const lower = name.toLowerCase();
  if (kind === "pdf") return "application/pdf";
  if (kind === "html") return "text/html";
  if (kind === "markdown") return "text/markdown";
  if (kind === "text") return "text/plain";
  if (kind === "word") return lower.endsWith(".doc") ? "application/msword" : "application/vnd.openxmlformats-officedocument.wordprocessingml.document";
  if (kind === "excel") return lower.endsWith(".xls") ? "application/vnd.ms-excel" : "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
  if (kind === "ppt") return lower.endsWith(".ppt") ? "application/vnd.ms-powerpoint" : "application/vnd.openxmlformats-officedocument.presentationml.presentation";
  if (kind === "video") {
    if (lower.endsWith(".webm")) return "video/webm";
    if (lower.endsWith(".ogg")) return "video/ogg";
    return "video/mp4";
  }
  if (kind === "image") {
    if (lower.endsWith(".jpg") || lower.endsWith(".jpeg")) return "image/jpeg";
    if (lower.endsWith(".gif")) return "image/gif";
    if (lower.endsWith(".webp")) return "image/webp";
    if (lower.endsWith(".svg")) return "image/svg+xml";
    return "image/png";
  }
  return "application/octet-stream";
}

function revokePreviewResource(key: string) {
  const resource = state.previewResources[key];
  if (resource?.objectUrl) URL.revokeObjectURL(resource.objectUrl);
  if (resource?.posterUrl) revokeVideoPosterObjectUrl(resource.posterUrl);
}

function clearPreviewResources() {
  Object.keys(state.previewResources).forEach(revokePreviewResource);
  state.previewResources = {};
  state.officePreviews = {};
  state.officeActiveSheets = {};
}

function isOfficeKind(kind: PreviewKind): kind is "word" | "excel" | "ppt" {
  return kind === "word" || kind === "excel" || kind === "ppt";
}

function officePreviewKey(file: PreviewFile, previewUrl: string) {
  return `${previewResourceKey(file)}\n${previewUrl}`;
}

function ensureOfficePreview(file: PreviewFile, previewUrl: string, key: string) {
  const existing = state.officePreviews[key];
  if (existing) return existing;
  state.officePreviews[key] = { status: "loading" };
  void loadOfficePreview(file, previewUrl, key);
  return state.officePreviews[key];
}

async function loadOfficePreview(file: PreviewFile, previewUrl: string, key: string) {
  try {
    const response = await fetch(previewUrl);
    if (!response.ok) throw new Error("预览文件读取失败");
    const preview = await parseOfficeBuffer(await response.arrayBuffer(), file.kind);
    state.officePreviews[key] = { status: "ready", preview };
  } catch (error) {
    state.officePreviews[key] = { status: "error", error: errorMessage(error) };
  }
  render();
}

async function parseOfficeBuffer(buffer: ArrayBuffer, kind: PreviewKind): Promise<OfficePreviewData> {
  if (!isZipBuffer(buffer)) {
    if (kind === "word") return parseWordFallbackBuffer(buffer);
    if (kind === "excel") return parseLegacySpreadsheetFallbackBuffer(buffer);
    if (kind === "ppt") return parseLegacyPresentationFallbackBuffer(buffer);
    throw new Error("旧版 .doc/.xls/.ppt 需要先转换成 PDF 才能完整预览");
  }
  const zip = await readZipEntries(buffer);

  if (kind === "word") {
    const documentXml = zip.get("word/document.xml") ?? findZipEntry(zip, /(^|\/)word\/document\.xml$/i) ?? findZipEntry(zip, /(^|\/)document\.xml$/i);
    if (!documentXml) return parseWordFallbackBuffer(buffer);
    const xml = await entryToText(documentXml);
    const relationships = await readWordRelationships(zip);
    const listCounters = new Map<string, number>();
    const blocks: OfficeBlock[] = [];

    for (const paragraphXml of extractXmlBlocks(xml, "w:p")) {
      const text = wordParagraphText(paragraphXml);
      const imageRelIds = extractImageRelationshipIds(paragraphXml);
      const listLabel = paragraphXml.includes("<w:numPr") ? nextListLabel(paragraphXml, listCounters) : undefined;

      if (text || (listLabel && imageRelIds.length)) {
        blocks.push({ type: "paragraph", text, listLabel });
      }

      for (const relId of imageRelIds) {
        const target = relationships.get(relId);
        if (!target) continue;
        const entry = zip.get(target);
        if (!entry) continue;
        const bytes = await entryToBytes(entry);
        blocks.push({ type: "image", src: bytesToDataUrl(bytes, imageMimeFromPath(target)), alt: target.split("/").pop() ?? "image" });
      }
    }

    return { type: "document", blocks: blocks.length ? blocks : wordTextFallback(xml) };
  }

  if (kind === "excel") {
    const workbookXmlEntry = zip.get("xl/workbook.xml");
    if (!workbookXmlEntry) throw new Error("没有找到 Excel 工作簿内容");
    const sharedStringsXml = zip.get("xl/sharedStrings.xml");
    const sharedStrings = sharedStringsXml
      ? extractXmlBlocks(await entryToText(sharedStringsXml), "si").map((item) => extractXmlBlocks(item, "t").map(xmlTextContent).join(""))
      : [];
    const workbookXml = await entryToText(workbookXmlEntry);
    const workbookRelationships = await readWorkbookRelationships(zip);
    const workbookSheets = readWorkbookSheets(workbookXml);
    const sheets = await Promise.all(
      workbookSheets.map(async (sheet) => {
        const target = workbookRelationships.get(sheet.relId) ?? `xl/worksheets/sheet${sheet.sheetId}.xml`;
        const sheetEntry = zip.get(target);
        return {
          name: sheet.name,
          rows: sheetEntry ? buildSheetRows(await entryToText(sheetEntry), sharedStrings) : [["未找到工作表内容"]],
        };
      }),
    );
    return { type: "sheet", sheets: sheets.length ? sheets : [{ name: "Sheet1", rows: [["未解析到表格内容"]] }], activeSheet: readActiveSheetIndex(workbookXml, sheets.length) };
  }

  if (kind === "ppt") {
    const slideNames = [...zip.keys()]
      .filter((name) => /^ppt\/slides\/slide\d+\.xml$/.test(name))
      .sort((a, b) => Number(a.match(/\d+/)?.[0] ?? 0) - Number(b.match(/\d+/)?.[0] ?? 0));
    if (!slideNames.length) throw new Error("没有找到 PPT 页面内容");
    const slides = await Promise.all(
      slideNames.slice(0, 20).map(async (name) => {
        const xml = await entryToText(zip.get(name)!);
        const relationships = await readSlideRelationships(zip, name);
        const blocks: SlideBlock[] = extractXmlBlocks(xml, "a:t")
          .map(xmlTextContent)
          .map((text) => text.trim())
          .filter(Boolean)
          .map((text) => ({ type: "text", text }));
        for (const relId of extractImageRelationshipIds(xml)) {
          const target = relationships.get(relId);
          if (!target) continue;
          const entry = zip.get(target);
          if (!entry) continue;
          const bytes = await entryToBytes(entry);
          blocks.push({ type: "image", src: bytesToDataUrl(bytes, imageMimeFromPath(target)), alt: target.split("/").pop() ?? "image" });
        }
        const fallback: SlideBlock[] = [{ type: "text", text: "本页未解析到内容" }];
        return blocks.length ? blocks : fallback;
      }),
    );
    return { type: "slides", slides };
  }

  throw new Error("当前文件类型暂不支持预览");
}

function findZipEntry(zip: Map<string, ZipEntry>, pattern: RegExp) {
  for (const [name, entry] of zip) {
    if (pattern.test(name)) return entry;
  }
  return null;
}

function wordParagraphText(paragraphXml: string) {
  const withBreaks = paragraphXml.replace(/<w:tab\b[^>]*\/>/g, "\t").replace(/<w:br\b[^>]*\/>/g, "\n");
  return extractXmlBlocks(withBreaks, "w:t").map(xmlTextContent).join("").trim();
}

function wordTextFallback(xml: string): OfficeBlock[] {
  const text = extractXmlBlocks(xml, "w:t").map(xmlTextContent).join("\n").trim();
  return textToDocumentBlocks(text || "未解析到文字内容");
}

function parseWordFallbackBuffer(buffer: ArrayBuffer): OfficePreviewData {
  const text = decodeOfficeTextBuffer(buffer);
  const plainText = looksLikeRtf(text) ? rtfToPlainText(text) : htmlOrPlainTextToPreviewText(text);
  return { type: "document", blocks: textToDocumentBlocks(plainText || "未解析到文字内容") };
}

function parseLegacySpreadsheetFallbackBuffer(buffer: ArrayBuffer): OfficePreviewData {
  const text = decodeOfficeTextBuffer(buffer);
  const xmlSheets = parseSpreadsheetXmlPreview(text);
  if (xmlSheets.length) return { type: "sheet", sheets: xmlSheets, activeSheet: 0 };

  const plainText = htmlOrPlainTextToPreviewText(text) || extractPrintableOfficeText(buffer);
  const rows = parseDelimitedPreviewRows(plainText);
  return {
    type: "sheet",
    sheets: [{ name: "Sheet1", rows: rows.length ? rows : [["未解析到表格内容"]] }],
    activeSheet: 0,
  };
}

function parseLegacyPresentationFallbackBuffer(buffer: ArrayBuffer): OfficePreviewData {
  const text = htmlOrPlainTextToPreviewText(decodeOfficeTextBuffer(buffer)) || extractPrintableOfficeText(buffer);
  const lines = text
    .replace(/\r\n?/g, "\n")
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length >= 2 && !/^<\?xml|^mso-application/i.test(line))
    .slice(0, 240);
  const pageSize = 12;
  const slides: SlideBlock[][] = [];
  for (let index = 0; index < lines.length; index += pageSize) {
    slides.push(lines.slice(index, index + pageSize).map((line): SlideBlock => ({ type: "text", text: line })));
  }
  return { type: "slides", slides: slides.length ? slides : [[{ type: "text", text: "未解析到 PPT 文本内容" }]] };
}

function parseSpreadsheetXmlPreview(text: string): { name: string; rows: string[][] }[] {
  if (!/<(?:\w+:)?Workbook\b/i.test(text) && !/<(?:\w+:)?Worksheet\b/i.test(text)) return [];
  const sheets: { name: string; rows: string[][] }[] = [];
  const worksheetPattern = /<([\w:]+:)?Worksheet\b([^>]*)>([\s\S]*?)<\/(?:[\w:]+:)?Worksheet>/gi;
  let match: RegExpExecArray | null;
  while ((match = worksheetPattern.exec(text))) {
    const rows = parseSpreadsheetXmlRows(match[3]);
    if (!rows.length) continue;
    sheets.push({
      name: spreadsheetXmlAttribute(match[2], "Name") || `Sheet${sheets.length + 1}`,
      rows,
    });
  }
  if (sheets.length) return sheets.slice(0, 12);
  const rows = parseSpreadsheetXmlRows(text);
  return rows.length ? [{ name: "Sheet1", rows }] : [];
}

function parseSpreadsheetXmlRows(xml: string) {
  const rows: string[][] = [];
  const rowPattern = /<([\w:]+:)?Row\b[^>]*>([\s\S]*?)<\/(?:[\w:]+:)?Row>/gi;
  let rowMatch: RegExpExecArray | null;
  while ((rowMatch = rowPattern.exec(xml)) && rows.length < 300) {
    const row: string[] = [];
    const cellPattern = /<([\w:]+:)?Cell\b([^>]*)>([\s\S]*?)<\/(?:[\w:]+:)?Cell>/gi;
    let cellMatch: RegExpExecArray | null;
    while ((cellMatch = cellPattern.exec(rowMatch[2])) && row.length < 120) {
      const index = Number(spreadsheetXmlAttribute(cellMatch[2], "Index"));
      if (Number.isFinite(index) && index > row.length + 1) {
        while (row.length < index - 1 && row.length < 120) row.push("");
      }
      const data = cellMatch[3].match(/<([\w:]+:)?Data\b[^>]*>([\s\S]*?)<\/(?:[\w:]+:)?Data>/i)?.[2] ?? xmlTextContent(cellMatch[3]);
      row.push(decodeXmlEntities(data.replace(/<[^>]+>/g, "")).trim());
    }
    if (row.some(Boolean)) rows.push(row);
  }
  return rows;
}

function spreadsheetXmlAttribute(attributes: string, name: string) {
  const pattern = new RegExp(`(?:\\b|:)${name}\\s*=\\s*["']([^"']+)["']`, "i");
  return decodeXmlEntities(attributes.match(pattern)?.[1] || "").trim();
}

function parseDelimitedPreviewRows(text: string) {
  const lines = text
    .replace(/\r\n?/g, "\n")
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean)
    .slice(0, 300);
  if (!lines.length) return [];
  const delimiter = lines.some((line) => line.includes("\t")) ? "\t" : lines.some((line) => line.includes(",")) ? "," : "";
  if (!delimiter) return lines.map((line) => [line]).slice(0, 80);
  return lines.map((line) => line.split(delimiter).map((cell) => cell.trim()).slice(0, 120));
}

function extractPrintableOfficeText(buffer: ArrayBuffer) {
  const bytes = new Uint8Array(buffer);
  const fragments = [...extractAsciiFragments(bytes), ...extractUtf16LeFragments(bytes)];
  const seen = new Set<string>();
  return fragments
    .map((item) => item.replace(/\s+/g, " ").trim())
    .filter((item) => item.length >= 2 && !seen.has(item) && !/^[\W_]+$/.test(item))
    .filter((item) => {
      seen.add(item);
      return true;
    })
    .slice(0, 260)
    .join("\n");
}

function extractAsciiFragments(bytes: Uint8Array) {
  const fragments: string[] = [];
  let text = "";
  const flush = () => {
    if (text.length >= 4) fragments.push(text);
    text = "";
  };
  for (const byte of bytes) {
    if (byte === 9 || byte === 10 || byte === 13 || (byte >= 32 && byte <= 126)) {
      text += String.fromCharCode(byte);
    } else {
      flush();
    }
  }
  flush();
  return fragments;
}

function extractUtf16LeFragments(bytes: Uint8Array) {
  const fragments: string[] = [];
  let text = "";
  const flush = () => {
    if (text.length >= 3) fragments.push(text);
    text = "";
  };
  for (let index = 0; index + 1 < bytes.length; index += 2) {
    const code = bytes[index] | (bytes[index + 1] << 8);
    if (code === 9 || code === 10 || code === 13 || (code >= 32 && code <= 0xfffd)) {
      text += String.fromCharCode(code);
    } else {
      flush();
    }
  }
  flush();
  return fragments;
}

function textToDocumentBlocks(text: string): OfficeBlock[] {
  const lines = text
    .replace(/\r\n?/g, "\n")
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean)
    .slice(0, 260);
  return lines.length ? lines.map((line): OfficeBlock => ({ type: "paragraph", text: line })) : [{ type: "paragraph" as const, text: "未解析到文字内容" }];
}

function decodeOfficeTextBuffer(buffer: ArrayBuffer) {
  const bytes = new Uint8Array(buffer);
  const utf8Text = new TextDecoder("utf-8").decode(bytes);
  if (!utf8Text.includes("\uFFFD")) return utf8Text;
  try {
    return new TextDecoder("gb18030").decode(bytes);
  } catch {
    return utf8Text;
  }
}

function looksLikeRtf(text: string) {
  return text.trimStart().startsWith("{\\rtf");
}

function rtfToPlainText(rtf: string) {
  let output = "";
  for (let index = 0; index < rtf.length; index += 1) {
    const char = rtf[index];
    if (char === "{" || char === "}") continue;
    if (char !== "\\") {
      output += char;
      continue;
    }

    const next = rtf[index + 1];
    if (next === "\\" || next === "{" || next === "}") {
      output += next;
      index += 1;
      continue;
    }
    if (next === "'") {
      const hex = rtf.slice(index + 2, index + 4);
      const code = Number.parseInt(hex, 16);
      if (Number.isFinite(code)) output += String.fromCharCode(code);
      index += 3;
      continue;
    }

    const control = rtf.slice(index + 1).match(/^([a-zA-Z]+)(-?\d+)? ?/);
    if (!control) continue;
    const [, word, value] = control;
    if (word === "par" || word === "line") output += "\n";
    if (word === "tab") output += "\t";
    if (word === "u" && value) {
      const code = Number(value);
      output += String.fromCharCode(code < 0 ? code + 65536 : code);
    }
    index += control[0].length;
  }
  return output
    .replace(/\n{3,}/g, "\n\n")
    .replace(/[ \t]{2,}/g, " ")
    .trim();
}

function htmlOrPlainTextToPreviewText(text: string) {
  if (!/<[a-z][\s\S]*>/i.test(text)) return text.trim();
  return decodeXmlEntities(text.replace(/<br\s*\/?>/gi, "\n").replace(/<\/p>/gi, "\n").replace(/<[^>]+>/g, "")).trim();
}

type ZipEntry = {
  method: number;
  compressed: Uint8Array;
};

function isZipBuffer(buffer: ArrayBuffer) {
  const view = new DataView(buffer);
  return buffer.byteLength >= 4 && view.getUint32(0, true) === 0x04034b50;
}

async function readZipEntries(buffer: ArrayBuffer) {
  const view = new DataView(buffer);
  const bytes = new Uint8Array(buffer);
  const entries = new Map<string, ZipEntry>();
  let eocdOffset = -1;

  for (let offset = bytes.length - 22; offset >= 0; offset -= 1) {
    if (view.getUint32(offset, true) === 0x06054b50) {
      eocdOffset = offset;
      break;
    }
  }

  if (eocdOffset < 0) throw new Error("文件格式不正确，无法读取压缩包");

  const totalEntries = view.getUint16(eocdOffset + 10, true);
  let centralOffset = view.getUint32(eocdOffset + 16, true);
  const decoder = new TextDecoder();

  for (let index = 0; index < totalEntries; index += 1) {
    if (view.getUint32(centralOffset, true) !== 0x02014b50) break;
    const method = view.getUint16(centralOffset + 10, true);
    const compressedSize = view.getUint32(centralOffset + 20, true);
    const fileNameLength = view.getUint16(centralOffset + 28, true);
    const extraLength = view.getUint16(centralOffset + 30, true);
    const commentLength = view.getUint16(centralOffset + 32, true);
    const localHeaderOffset = view.getUint32(centralOffset + 42, true);
    const nameStart = centralOffset + 46;
    const name = decoder.decode(bytes.slice(nameStart, nameStart + fileNameLength)).replace(/\\/g, "/");
    const localNameLength = view.getUint16(localHeaderOffset + 26, true);
    const localExtraLength = view.getUint16(localHeaderOffset + 28, true);
    const dataStart = localHeaderOffset + 30 + localNameLength + localExtraLength;
    entries.set(name, { method, compressed: bytes.slice(dataStart, dataStart + compressedSize) });
    centralOffset += 46 + fileNameLength + extraLength + commentLength;
  }

  return entries;
}

async function entryToText(entry: ZipEntry) {
  return new TextDecoder().decode(await entryToBytes(entry));
}

async function entryToBytes(entry: ZipEntry) {
  if (entry.method === 0) return entry.compressed;
  if (entry.method !== 8) throw new Error("暂不支持这个压缩方式");
  if (!("DecompressionStream" in window)) throw new Error("当前环境不支持本地解压预览");
  const stream = new Blob([uint8ToArrayBuffer(entry.compressed)]).stream().pipeThrough(new DecompressionStream("deflate-raw"));
  return new Uint8Array(await new Response(stream).arrayBuffer());
}

async function readWordRelationships(zip: Map<string, ZipEntry>) {
  const relationships = new Map<string, string>();
  const relsEntry = zip.get("word/_rels/document.xml.rels");
  if (!relsEntry) return relationships;
  const relsXml = await entryToText(relsEntry);
  for (const match of relsXml.matchAll(/<Relationship\b[^>]*\bId="([^"]+)"[^>]*\bTarget="([^"]+)"[^>]*>/g)) {
    const [, id, target] = match;
    if (target && /\.(png|jpe?g|gif|bmp|webp|svg)$/i.test(target)) {
      relationships.set(id, target.startsWith("/") ? target.slice(1) : `word/${target.replace(/^\.\.\//, "")}`,
      );
    }
  }
  return relationships;
}

async function readSlideRelationships(zip: Map<string, ZipEntry>, slidePath: string) {
  const relationships = new Map<string, string>();
  const slideFile = slidePath.split("/").pop();
  if (!slideFile) return relationships;
  const relsEntry = zip.get(`ppt/slides/_rels/${slideFile}.rels`);
  if (!relsEntry) return relationships;
  const relsXml = await entryToText(relsEntry);
  for (const match of relsXml.matchAll(
    /<Relationship\b[^>]*\bId="([^"]+)"[^>]*\bTarget="([^"]+)"[^>]*>/g,
  )) {
    const [, id, target] = match;
    if (target && /\.(png|jpe?g|gif|bmp|webp|svg)$/i.test(target)) {
      relationships.set(
        id,
        target.startsWith("/")
          ? target.slice(1)
          : `ppt/${target.replace(/^\.\.\//, "")}`,
      );
    }
  }
  return relationships;
}

async function readWorkbookRelationships(zip: Map<string, ZipEntry>) {
  const relationships = new Map<string, string>();
  const relsEntry = zip.get("xl/_rels/workbook.xml.rels");
  if (!relsEntry) return relationships;
  const relsXml = await entryToText(relsEntry);
  for (const match of relsXml.matchAll(/<Relationship\b[^>]*\bId="([^"]+)"[^>]*\bTarget="([^"]+)"[^>]*>/g)) {
    const [, id, target] = match;
    if (target?.includes("worksheets/")) relationships.set(id, target.startsWith("/") ? target.slice(1) : `xl/${target.replace(/^\.\//, "")}`,
      );
  }
  return relationships;
}

function readWorkbookSheets(workbookXml: string) {
  return [...workbookXml.matchAll(/<sheet\b([^>]*)\/?>/g)].map((match, index) => {
    const attrs = match[1] || "";
    return {
      name: decodeXmlEntities(attrs.match(/\bname="([^"]+)"/)?.[1] ?? `Sheet${index + 1}`),
      sheetId: attrs.match(/\bsheetId="([^"]+)"/)?.[1] ?? `${index + 1}`,
      relId: attrs.match(/\br:id="([^"]+)"/)?.[1] ?? "",
    };
  });
}

function readActiveSheetIndex(workbookXml: string, sheetCount: number) {
  const active = Number(workbookXml.match(/\bactiveTab="(\d+)"/)?.[1] ?? 0);
  if (!Number.isFinite(active)) return 0;
  return Math.min(Math.max(active, 0), Math.max(sheetCount - 1, 0));
}

function buildSheetRows(sheetXml: string, sharedStrings: string[]) {
  const rowMap = new Map<number, Map<number, string>>();
  let maxColumn = 0;
  for (const match of sheetXml.matchAll(/<c\b([^>]*)>([\s\S]*?)<\/c>/g)) {
    const [, attrs, cellXml] = match;
    const reference = attrs.match(/\br="([A-Z]+)(\d+)"/)?.slice(1);
    if (!reference) continue;
    const [columnName, rowNumberText] = reference;
    const rowIndex = Number(rowNumberText) - 1;
    const columnIndex = excelColumnToIndex(columnName);
    const type = attrs.match(/\bt="([^"]+)"/)?.[1];
    const value = readCellValue(cellXml, type, sharedStrings);
    if (!value) continue;
    if (!rowMap.has(rowIndex)) rowMap.set(rowIndex, new Map());
    rowMap.get(rowIndex)!.set(columnIndex, value);
    maxColumn = Math.max(maxColumn, columnIndex);
  }
  return [...rowMap.entries()]
    .sort(([a], [b]) => a - b)
    .slice(0, 80)
    .map(([, cells]) => Array.from({ length: Math.min(maxColumn + 1, 24) }, (_, columnIndex) => cells.get(columnIndex) ?? ""))
    .filter((row) => row.some(Boolean));
}

function readCellValue(cellXml: string, type: string | undefined, sharedStrings: string[]) {
  if (type === "s") return (
      sharedStrings[Number(xmlTextContent(extractXmlBlocks(cellXml, "v")[0] ?? ""))] ?? ""
    );
  if (type === "inlineStr") return extractXmlBlocks(cellXml, "t").map(xmlTextContent).join("");
  return xmlTextContent(extractXmlBlocks(cellXml, "v")[0] ?? "");
}

function excelColumnToIndex(column: string) {
  return (
    column.split("").reduce((total, char) => total * 26 + char.charCodeAt(0) - 64, 0) - 1
  );
}

function indexToExcelColumn(index: number) {
  let value = index + 1;
  let label = "";
  while (value > 0) {
    const remainder = (value - 1) % 26;
    label = String.fromCharCode(65 + remainder) + label;
    value = Math.floor((value - 1) / 26);
  }
  return label;
}

function extractImageRelationshipIds(xml: string) {
  return [...new Set([...xml.matchAll(/r:embed="([^"]+)"/g), ...xml.matchAll(/r:link="([^"]+)"/g)].map((match) => match[1]))];
}

function nextListLabel(paragraphXml: string, counters: Map<string, number>) {
  const numId = paragraphXml.match(/<w:numId\b[^>]*w:val="([^"]+)"/)?.[1] ?? "default";
  const level = paragraphXml.match(/<w:ilvl\b[^>]*w:val="([^"]+)"/)?.[1] ?? "0";
  const key = `${numId}:${level}`;
  const next = (counters.get(key) ?? 0) + 1;
  counters.set(key, next);
  return `${next}.`;
}

function imageMimeFromPath(path: string) {
  const lower = path.toLowerCase();
  if (lower.endsWith(".png")) return "image/png";
  if (lower.endsWith(".jpg") || lower.endsWith(".jpeg")) return "image/jpeg";
  if (lower.endsWith(".gif")) return "image/gif";
  if (lower.endsWith(".bmp")) return "image/bmp";
  if (lower.endsWith(".webp")) return "image/webp";
  if (lower.endsWith(".svg")) return "image/svg+xml";
  return "application/octet-stream";
}

function bytesToDataUrl(bytes: Uint8Array, mime: string) {
  let binary = "";
  bytes.forEach((byte) => {
    binary += String.fromCharCode(byte);
  });
  return `data:${mime};base64,${window.btoa(binary)}`;
}

function uint8ToArrayBuffer(bytes: Uint8Array) {
  return bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength) as ArrayBuffer;
}

function extractXmlBlocks(xml: string, tagName: string) {
  const escaped = tagName.replace(":", "\\:");
  const pattern = new RegExp(`<${escaped}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/${escaped}>`, "g");
  return [...xml.matchAll(pattern)].map((match) => match[1]);
}

function xmlTextContent(xml: string) {
  return decodeXmlEntities(xml.replace(/<[^>]+>/g, ""));
}

function decodeXmlEntities(text: string) {
  return text.replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&amp;/g, "&").replace(/&quot;/g, '"').replace(/&apos;/g, "'");
}

function withHtmlBase(html: string, fileUrl?: string | null) {
  if (!fileUrl) return html;
  let baseHref = "";
  try {
    baseHref = new URL(".", fileUrl).href;
  } catch {
    return html;
  }
  const baseTag = `<base href="${escapeAttr(baseHref)}">`;
  if (/<head\b[^>]*>/i.test(html)) return html.replace(/<head\b([^>]*)>/i, `<head$1>${baseTag}`);
  if (/<html\b[^>]*>/i.test(html)) return html.replace(/<html\b([^>]*)>/i, `<html$1><head>${baseTag}</head>`);
  return `<!doctype html><html><head>${baseTag}</head><body>${html}</body></html>`;
}

function renderFileThumb(file: PreviewFile) {
  if (file.kind === "image" && file.url) {
    const image = imageDisplay(file.url, file.name, "library file");
    if (image.status === "ready") return `<img class="thumb-image" src="${escapeAttr(image.url)}" alt="" />`;
  }
  if (file.kind === "video") return renderVideoFileThumb(file);
  if (file.kind === "html") return "链";
  if (file.kind === "text") return "TXT";
  return `<img src="${escapeAttr(attachmentIcon({ name: file.name, mime: file.mime || undefined }))}" alt="" />`;
}

function renderVideoFileThumb(file: PreviewFile) {
  const key = previewResourceKey(file);
  let resource = state.previewResources[key];
  let videoUrl = /^(blob:|data:)/i.test(file.url || "") ? file.url || "" : "";
  if (!videoUrl && file.url && (isRemotePreviewUrl(file.url) || isLocalPreviewUrl(file.url))) {
    resource = resource || ensurePreviewResource(file);
    if (resource.status === "ready") videoUrl = resource.objectUrl || "";
  }
  if (videoUrl && !resource?.posterUrl && resource?.posterFrameTime !== -1) {
    void ensureVideoPosterResource(file, videoUrl);
  }
  const posterUrl = resource?.status === "ready" ? resource.posterUrl : null;
  return `
    <span class="library-video-thumb ${posterUrl ? "has-poster" : ""}">
      ${posterUrl ? `<img class="thumb-image" src="${escapeAttr(posterUrl)}" alt="" />` : ""}
      <span class="library-video-thumb-play" aria-hidden="true"></span>
    </span>
  `;
}

function previewUrlWithHash(url: string, hash: string) {
  return url.includes("#") ? url : `${url}#${hash}`;
}

function renderLibraryEmpty(title: string, detail?: string) {
  return `
    <div class="library-empty">
      <strong>${escapeHtml(title)}</strong>
      ${detail ? `<span>${escapeHtml(detail)}</span>` : ""}
    </div>
  `;
}

