function renderThreadGroupContextMenu() {
  const menu = state.threadGroupMenu;
  if (!menu) return "";
  const group = threadGroupById(menu.groupId);
  if (!group) return "";
  const defaultGroup = isDefaultThreadGroup(group.id);
  const singleItem = false;
  const pinLabel = group.pinned ? "取消置顶" : "置顶分组";
  const deleting = pendingThreadGroupDeletions.has(group.id);
  const canDeleteConversations = !deleting;
  return `
    <div class="thread-menu-scrim" data-action="close-thread-group-menu"></div>
    <div class="thread-group-context-menu ${singleItem ? "single-item" : ""}" style="${threadGroupMenuStyle(menu)}" role="menu">
      ${
        defaultGroup
          ? `<button type="button" data-thread-group-action="pin" data-group-id="${escapeAttr(group.id)}" role="menuitem">
              ${pinLabel}
            </button>
            <button type="button" data-thread-group-action="open-folder" data-group-id="${escapeAttr(group.id)}" role="menuitem">
              打开文件夹
            </button>`
          : `
            <button type="button" data-thread-group-action="pin" data-group-id="${escapeAttr(group.id)}" role="menuitem">
              ${pinLabel}
            </button>
            <button type="button" data-thread-group-action="open-folder" data-group-id="${escapeAttr(group.id)}" role="menuitem">
              打开文件夹
            </button>
            <button type="button" data-thread-group-action="rename" data-group-id="${escapeAttr(group.id)}" role="menuitem">
              重命名分组
            </button>
            <button type="button" class="danger" data-thread-group-action="delete" data-group-id="${escapeAttr(group.id)}" role="menuitem">
              删除分组
            </button>`
      }
      <button type="button" class="danger" data-thread-group-action="delete-conversations" data-group-id="${escapeAttr(group.id)}" role="menuitem" aria-busy="${deleting}" ${canDeleteConversations ? "" : "disabled"}>
        ${deleting ? "处理中…" : "删除指定会话"}
      </button>
    </div>
  `;
}

