function renderThreadDeleteDialog() {
  const threadId = state.threadDelete?.threadId;
  const target = threadById(threadId);
  if (!target) return "";
  const autoTask = isAutoTaskThread(target) || autoTaskIdFromThreadId(target.id);
  const title = autoTask ? "删除自动任务" : "删除会话";
  const body = autoTask
    ? `确定删除「${escapeHtml(target.name || "自动任务")}」吗？删除后此自动任务将停止执行，且不可恢复。`
    : `确定删除「${escapeHtml(target.name || "主会话")}」吗？删除后不可恢复。`;
  return `
    <div class="modal-backdrop" data-action="cancel-thread-delete"></div>
    <dialog class="thread-delete-dialog" open>
      <section>
        <h2>${title}</h2>
        <p>${body}</p>
        <footer>
          <button type="button" class="thread-dialog-secondary" data-action="cancel-thread-delete">取消</button>
          <button type="button" class="thread-dialog-danger" data-action="confirm-thread-delete" data-thread-id="${escapeAttr(target.id)}">删除</button>
        </footer>
      </section>
    </dialog>
  `;
}

