function renderThreadGroupAddMenuIcon(icon: "plus" | "folder" | "chevron") {
  const paths =
    icon === "plus"
      ? `<path d="M10 4.2V15.8" /><path d="M4.2 10H15.8" />`
      : icon === "folder"
        ? `<path d="M3.2 6.3C3.2 5.8 3.6 5.4 4.1 5.4H7.4L9.1 7H15.9C16.4 7 16.8 7.4 16.8 7.9V14.6C16.8 15.1 16.4 15.5 15.9 15.5H4.1C3.6 15.5 3.2 15.1 3.2 14.6V6.3Z" />`
        : `<path d="M7 4.5L12.5 10L7 15.5" />`;
  return `<svg class="thread-group-add-icon thread-group-add-icon-${icon}" viewBox="0 0 20 20" aria-hidden="true" focusable="false">${paths}</svg>`;
}

