function isThreadSwitchLoadingState(threadId: string) {
  const transition = threadSwitchTransition;
  if (transition?.threadId === threadId) {
    return transition.phase === "loading" && !isBlankNewThread(threadId);
  }
  return switchingThreadId === threadId && !isBlankNewThread(threadId);
}

function isThreadSwitchTransitionActive(threadId: string | null | undefined) {
  return Boolean(threadId && threadSwitchTransition?.threadId === threadId);
}

function renderThreadSwitchLoadingPlaceholder() {
  return `<div class="center-note" data-thread-loading-placeholder="true" role="status" aria-live="polite">&#27491;&#22312;&#21152;&#36733;&#20250;&#35805;...</div>`;
}

function shouldHideEmptyChatStateDuringSwitch(threadId: string) {
  return isThreadSwitchTransitionActive(threadId);
}

function renderDeferredThreadResumeEmptyState(threadId: string) {
  if (isThreadSwitchLoadingState(threadId)) return renderThreadSwitchLoadingPlaceholder();
  if (deferredThreadResumeThreadId !== threadId) return "";
  return `<div class="center-note">&#27491;&#22312;&#21152;&#36733;&#20250;&#35805;&#35760;&#24405;...</div>`;
}

function threadContinuationDecorationSignature(threadId: string) {
  const sourceRecord = latestThreadContinuationRecordForSource(threadId);
  const targetRecord = continuationRecordForTarget(threadId);
  return stableUiHash(JSON.stringify({
    source: sourceRecord ? [
      sourceRecord.operationId,
      sourceRecord.status,
      sourceRecord.anchorMessageId,
      sourceRecord.continuationThreadId,
      sourceRecord.continuationTitle,
      sourceRecord.error,
      threadContinuationOpeningSourceThreadIds.has(threadId),
    ] : null,
    target: targetRecord
      ? [
          targetRecord.sourceThreadId,
          targetRecord.sourceDeleted,
          targetRecord.sourceTitle,
          targetRecord.completedAt,
          targetRecord.copiedMessages.map((message) => [message.role, message.text.length, message.summarized]),
        ]
      : null,
  }));
}

function renderThreadContinuationPrelude(threadId: string) {
  const record = continuationRecordForTarget(threadId);
  if (!record) return "";
  const signature = threadContinuationDecorationSignature(threadId);
  const sourceThread = threadById(record.sourceThreadId);
  const sourceTitle = (sourceThread ? threadListDisplayName(sourceThread) : "") || record.sourceTitle || NEW_THREAD_TITLE;
  const quotedSourceTitle = `“${sourceTitle}”`;
  const copiedMessages = record.copiedMessages.map((message, index) => {
    const role: RoleKey = message.role === "user" ? "user" : "ceo_assistant";
    const synthetic: Message = {
      id: `continuation-copy-${record.sourceThreadId}-${index}`,
      conversation_id: threadId,
      kind: message.role === "user" ? "user_text" : "agent_text",
      role,
      text: message.text,
    };
    const fromUser = message.role === "user";
    return `
      <article class="message-row continuation-copy-row ${fromUser ? "from-user" : "from-agent"}">
        ${fromUser ? "" : renderMessageAvatar(synthetic, role)}
        <div class="message-stack">
          <div class="message-meta">${escapeHtml(messageRoleDisplayName(role))}</div>
          ${renderTextBubble(synthetic, message.text, fromUser, { hideHoverBar: true })}
        </div>
        ${fromUser ? renderMessageAvatar(synthetic, role) : ""}
      </article>
    `;
  }).join("");
  const welcomeMessage: Message = {
    id: `continuation-welcome-${record.sourceThreadId}`,
    conversation_id: threadId,
    kind: "agent_text",
    role: "ceo_assistant",
    text: THREAD_CONTINUATION_WELCOME_TEXT,
  };
  return `
    <section class="thread-continuation-prelude" data-thread-continuation-decoration="prelude" data-thread-continuation-signature="${escapeAttr(signature)}">
      <article class="message-row continuation-welcome-row from-agent">
        ${renderMessageAvatar(welcomeMessage, "ceo_assistant")}
        <div class="message-stack">
          <div class="message-meta">${escapeHtml(messageRoleDisplayName("ceo_assistant"))}</div>
          ${renderTextBubble(welcomeMessage, THREAD_CONTINUATION_WELCOME_TEXT, false, { hideHoverBar: true })}
        </div>
      </article>
      <div class="thread-continuation-history-heading">来自${escapeHtml(quotedSourceTitle)} · 最近2条消息</div>
      <div class="thread-continuation-copied-messages">${copiedMessages}</div>
    </section>
  `;
}

function shouldRenderThreadContinuationStatus(record: ThreadContinuationRecord) {
  return (
    record.status === "ready" || record.status === "creating" || record.status === "completed" || record.status === "failed"
  );
}

function renderThreadContinuationStatus(threadId: string, record: ThreadContinuationRecord) {
  if (!shouldRenderThreadContinuationStatus(record)) return "";
  const signature = threadContinuationDecorationSignature(threadId);
  const active = record.status === "creating" || threadContinuationOpeningSourceThreadIds.has(record.sourceThreadId);
  const label = active ? "正在打开续接任务…" : "点击打开续接任务，会更快更省Token";
  return `
    <button
      type="button"
      class="thread-continuation-status-card ${escapeAttr(record.status)}"
      data-thread-continuation-decoration="status"
      data-thread-continuation-signature="${escapeAttr(signature)}"
      data-action="open-thread-continuation"
      data-operation-id="${escapeAttr(record.operationId)}"
      ${active ? "disabled" : ""}
      aria-live="polite"
    >
      <span class="thread-continuation-status-copy">
        <span class="thread-continuation-status-label">${escapeHtml(label)}</span>
        ${active ? `<span class="thinking-dots" aria-hidden="true"><i></i><i></i><i></i></span>` : ""}
        ${record.status === "failed" && record.error ? `<span class="thread-continuation-error">${escapeHtml(record.error)}</span>` : ""}
      </span>
    </button>
  `;
}

function resolvedThreadContinuationAnchorMessageId(threadId: string, messageIds: ReadonlySet<string>) {
  const record = latestThreadContinuationRecordForSource(threadId);
  if (!record) return null;
  if (record.anchorMessageId && messageIds.has(record.anchorMessageId)) return record.anchorMessageId;
  const answerMessageId = threadContinuationAnswerMessageId(threadId, record.answerTurnId);
  return answerMessageId && messageIds.has(answerMessageId) ? answerMessageId : null;
}

function renderThreadContinuationStatusesAfterMessage(
  threadId: string,
  messageId: string,
  resolvedAnchorMessageId: string | null,
) {
  const record = latestThreadContinuationRecordForSource(threadId);
  return record && resolvedAnchorMessageId === messageId ? renderThreadContinuationStatus(threadId, record) : "";
}

function renderUnanchoredThreadContinuationStatuses(
  _threadId: string,
  _messageIds: ReadonlySet<string>,
  _resolvedAnchorMessageId: string | null,
) {
  // A continuation control is a historical decoration, never a live footer.
  // If hydration cannot recover its exact anchor, hide it instead of allowing
  // later user messages or the thinking row to move it to the bottom.
  return "";
}

function firstMultiModelClusterUserMessageId(threadId: string, messages: Message[]) {
  if (!isMultiModelClusterThread(threadId)) return null;
  return messages.find((message) => message.role === "user" || message.kind === "user_text")?.id || null;
}

function multiModelClusterMembers(threadId: string) {
  const members = (workflowRunsByThreadId.get(threadId)?.nodes || [])
    .filter((node) => node.kind === "model" || node.kind === "agent")
    .map((node) => {
      const isExecutableAgent = node.kind === "agent";
      const provider = providerFromValue(node.provider);
      const meta = provider ? PROVIDER_CHAT_META[provider] : null;
      const name = isExecutableAgent
        ? workflowDisplayText(node.title || "Haolo 子 Agent").trim()
        : meta?.name || String(node.model || node.title || "").trim();
      if (!name) return null;
      return {
        key: isExecutableAgent ? `haolo-agent:${node.id}` : provider || name.toLowerCase(),
        provider,
        name,
        avatarUrl: isExecutableAgent ? APP_AVATAR_URL : meta?.avatarUrl || "",
      };
    })
    .filter((member): member is NonNullable<typeof member> => Boolean(member));
  return members.filter((member, index) => members.findIndex((candidate) => candidate.key === member.key) === index);
}

function multiModelClusterPlanningProgressPresentation(threadId: string) {
  const run = workflowRunsByThreadId.get(threadId);
  const active = run ? multiModelClusterPlanningActive(run) : isThreadBusy(threadId);
  const completed = multiModelClusterPlanningCompleted(run);
  const visible = active || completed;
  const updates = visible ? multiModelClusterPlanningProgress(run) : [];
  const signature = updates.map((update) => `${update.id}:${update.text}`).join("|");
  const text = updates.map((update) => update.text).join(" ");
  const markup = updates.map((update) => {
    const progressMessage: Message = {
      id: `multi-model-cluster-planning-${update.id}-${threadId}`,
      conversation_id: threadId,
      kind: "agent_text",
      role: "ceo_assistant",
      text: update.text,
    };
    return `
    <article
      class="message-row from-agent multi-model-cluster-planning-row${update.completed ? " completed" : ""}"
      data-multi-model-cluster-planning-update="${escapeAttr(update.id)}"
    >
      ${renderMessageAvatar(progressMessage, "ceo_assistant")}
      <div class="message-stack">
        <div class="message-meta">${escapeHtml(messageRoleDisplayName("ceo_assistant"))}</div>
        <div class="message-bubble agent-bubble multi-model-cluster-planning-bubble">
          <div class="message-text" data-i18n-owned>${escapeHtml(update.text)}</div>
        </div>
      </div>
    </article>
  `;
  }).join("");
  return { active, markup, signature, text, visible };
}

function multiModelClusterPresencePresentation(threadId: string) {
  if (!multiModelClusterPlanningCompleted(workflowRunsByThreadId.get(threadId))) {
    return { markup: "", signature: "planning", text: "", visible: false };
  }
  const members = multiModelClusterMembers(threadId);
  const text = multiModelClusterMemberStatus(members.map((member) => member.name));
  const signature = members.map((member) => `${member.key}:${member.avatarUrl}`).join("|");
  const markup = members.length
    ? `${members.map((member, index) => `
        ${index ? '<span class="multi-model-cluster-presence-separator" aria-hidden="true">、</span>' : ""}
        <span class="multi-model-cluster-presence-member" data-model-provider="${escapeAttr(member.provider || "")}">
          ${member.avatarUrl
            ? `<img class="multi-model-cluster-presence-avatar" src="${escapeAttr(member.avatarUrl)}" alt="" aria-hidden="true" />`
            : `<span class="multi-model-cluster-presence-avatar fallback" aria-hidden="true">${escapeHtml(member.name.slice(0, 1))}</span>`}
          <span>${escapeHtml(member.name)}</span>
        </span>
      `).join("")}<span class="multi-model-cluster-presence-suffix">加入画布</span>`
    : escapeHtml(text);
  return { markup, signature, text, visible: true };
}

function multiModelClusterPreludeCollapsed(messages: Message[]) {
  let latestUserIndex = -1;
  for (let index = messages.length - 1; index >= 0; index -= 1) {
    if (!isRenderedUserSideMessage(messages[index])) continue;
    latestUserIndex = index;
    break;
  }
  let turnResult: TurnResultMeta | undefined;
  for (let index = messages.length - 1; index > latestUserIndex; index -= 1) {
    const candidate = (messages[index] as MessageUiMeta).turnResult;
    if (!candidate) continue;
    turnResult = candidate;
    break;
  }
  return Boolean(turnResult && !turnResult.expanded);
}

function renderMultiModelClusterPrelude(threadId: string, messages: Message[]) {
  if (!isMultiModelClusterThread(threadId)) return "";
  const planningStatus = multiModelClusterPlanningProgressPresentation(threadId);
  const memberStatus = multiModelClusterPresencePresentation(threadId);
  const collapsed = multiModelClusterPreludeCollapsed(messages);
  return `
    <section
      class="multi-model-cluster-prelude${collapsed ? " collapsed" : ""}"
      data-multi-model-cluster-prelude="${escapeAttr(threadId)}"
      aria-hidden="${collapsed ? "true" : "false"}"
    >
      <div
        class="multi-model-cluster-planning-progress${planningStatus.visible ? "" : " hidden"}"
        data-multi-model-cluster-planning-progress
        data-planning-signature="${escapeAttr(planningStatus.signature)}"
        role="status"
        aria-live="polite"
        aria-hidden="${planningStatus.visible ? "false" : "true"}"
        aria-label="${escapeAttr(planningStatus.text)}"
      >${planningStatus.markup}</div>
      <div
        class="multi-model-cluster-presence${memberStatus.visible ? "" : " hidden"}"
        data-multi-model-cluster-presence
        role="status"
        aria-live="polite"
        aria-hidden="${memberStatus.visible ? "false" : "true"}"
      >
        <span class="multi-model-cluster-presence-text" data-multi-model-cluster-presence-text data-member-signature="${escapeAttr(memberStatus.signature)}" aria-label="${escapeAttr(memberStatus.text)}">${memberStatus.markup}</span>
      </div>
    </section>
  `;
}

function renderMultiModelClusterPreludeAfterMessage(
  threadId: string,
  messageId: string,
  firstUserMessageId: string | null,
  messages: Message[],
) {
  return firstUserMessageId === messageId ? renderMultiModelClusterPrelude(threadId, messages) : "";
}

function patchMultiModelClusterPreludeCollapsedState(
  threadId: string,
  messages: Message[],
) {
  if (!isMultiModelClusterThread(threadId)) return false;
  const prelude = Array.from(
    root.querySelectorAll<HTMLElement>("[data-multi-model-cluster-prelude]"),
  ).find((element) => element.dataset.multiModelClusterPrelude === threadId);
  if (!prelude) return false;
  const collapsed = multiModelClusterPreludeCollapsed(messages);
  prelude.classList.toggle("collapsed", collapsed);
  prelude.setAttribute("aria-hidden", collapsed ? "true" : "false");
  return true;
}

function patchMultiModelClusterPlanningProgress(threadId: string) {
  if (!isMultiModelClusterThread(threadId)) return false;
  const prelude = Array.from(
    root.querySelectorAll<HTMLElement>("[data-multi-model-cluster-prelude]"),
  ).find((element) => element.dataset.multiModelClusterPrelude === threadId);
  const progress = prelude?.querySelector<HTMLElement>("[data-multi-model-cluster-planning-progress]");
  if (!progress) return false;
  const nextStatus = multiModelClusterPlanningProgressPresentation(threadId);
  const contentChanged = progress.dataset.planningSignature !== nextStatus.signature;
  if (contentChanged) {
    progress.innerHTML = nextStatus.markup;
    progress.dataset.planningSignature = nextStatus.signature;
  }
  progress.classList.toggle("hidden", !nextStatus.visible);
  progress.setAttribute("aria-hidden", nextStatus.visible ? "false" : "true");
  if (progress.getAttribute("aria-label") !== nextStatus.text) {
    progress.setAttribute("aria-label", nextStatus.text);
  }
  if (contentChanged && isFollowingMessageStream(threadId)) scheduleScrollMessagesToBottom();
  return nextStatus.active;
}

function patchMultiModelClusterPresence(threadId: string) {
  if (!isMultiModelClusterThread(threadId)) return false;
  patchMultiModelClusterPlanningProgress(threadId);
  const prelude = Array.from(
    root.querySelectorAll<HTMLElement>("[data-multi-model-cluster-prelude]"),
  ).find((element) => element.dataset.multiModelClusterPrelude === threadId);
  const presence = prelude?.querySelector<HTMLElement>("[data-multi-model-cluster-presence]");
  const label = prelude?.querySelector<HTMLElement>("[data-multi-model-cluster-presence-text]");
  if (!presence || !label) return false;
  const nextStatus = multiModelClusterPresencePresentation(threadId);
  if (label.dataset.memberSignature !== nextStatus.signature) {
    label.innerHTML = nextStatus.markup;
    label.dataset.memberSignature = nextStatus.signature;
  }
  if (label.getAttribute("aria-label") !== nextStatus.text) label.setAttribute("aria-label", nextStatus.text);
  presence.classList.toggle("hidden", !nextStatus.visible);
  presence.setAttribute("aria-hidden", nextStatus.visible ? "false" : "true");
  return true;
}

function renderLocalGroupChatJoinNotice(record: LocalGroupChatRecord) {
  const members = localGroupChatUniqueMembers(record);
  return `
    <div class="local-group-chat-join-notice" role="status" aria-label="${escapeAttr(`${members.map((member) => member.name).join("、")}加入群聊`)}">
      ${members
        .map(
          (member) => `
            <span class="local-group-chat-join-member">
              ${renderLocalGroupChatAvatarContent(member, "local-group-chat-join-avatar")}
              <span>${escapeHtml(localGroupChatMemberPresentation(member).name)}</span>
            </span>
          `,
        )
        .join('<span class="local-group-chat-join-separator" aria-hidden="true">、</span>')}
      <span class="local-group-chat-join-copy">加入群聊</span>
    </div>
  `;
}

function renderLocalGroupChatMemberEvent(
  message: Message,
  event: LocalGroupChatMemberEvent,
) {
  const suffix = localGroupChatMemberEventSuffix(event.action);
  const accessibleText = `${event.member.name} ${suffix}`;
  return `
    <article
      class="local-group-chat-member-event"
      role="status"
      aria-label="${escapeAttr(accessibleText)}"
      data-message-id="${escapeAttr(message.id)}"
      data-message-signature="${escapeAttr(messageRenderSignature(message))}"
    >
      <span class="local-group-chat-member-event-content">
        ${renderLocalGroupChatAvatarContent(event.member, "local-group-chat-join-avatar")}
        <span class="local-group-chat-member-event-copy">
          <span class="local-group-chat-member-event-name">${escapeHtml(event.member.name)}</span>
          ${escapeHtml(suffix)}
        </span>
      </span>
    </article>
  `;
}

function renderLocalGroupChatPanel(
  thread: ConversationSummary,
  record: LocalGroupChatRecord,
) {
  const messages = messagesForThread(record.id);
  return `
    <main class="chat-panel local-group-chat-conversation">
      ${renderChatHeader(thread)}
      <div class="message-area local-group-chat-message-area">
        <section id="messageScroller" class="message-scroller local-group-chat-scroller" data-thread-id="${escapeAttr(thread.id)}">
          ${renderLocalGroupChatJoinNotice(record)}
          ${messages.map((message) => renderMessage(message, messages)).join("")}
        </section>
        ${renderMessageScrollBottomButton()}
      </div>
      ${renderComposer(thread)}
    </main>
  `;
}

function renderLocalGroupChatMemberCell(
  member: LocalGroupChatMember,
  occurrence: number,
  duplicateCount: number,
) {
  const presentation = localGroupChatMemberPresentation(member);
  const accessibleName =
    duplicateCount > 1
      ? `${presentation.name}，第${occurrence}个`
      : presentation.name;
  return `
    <button
      type="button"
      class="local-group-chat-member-cell ${member.muted ? "muted" : ""}"
      data-local-group-chat-member="${escapeAttr(member.selectionId)}"
      role="listitem"
      aria-label="${escapeAttr(`${accessibleName}${member.muted ? "，已禁言" : ""}`)}"
      title="${escapeAttr(accessibleName)}"
      aria-haspopup="menu"
    >
      ${renderLocalGroupChatAvatarContent(member, "local-group-chat-member-avatar")}
      <span class="local-group-chat-member-name">${escapeHtml(presentation.name)}</span>
    </button>
  `;
}

function renderLocalGroupChatAddMemberButton(record: LocalGroupChatRecord) {
  return `
    <button
      type="button"
      class="local-group-chat-member-cell local-group-chat-add-member"
      data-action="open-add-group-members-dialog"
      data-local-group-chat-id="${escapeAttr(record.id)}"
      role="listitem"
      aria-label="添加群成员"
      title="添加群成员"
      aria-haspopup="dialog"
    >
      <span class="local-group-chat-add-member-icon" aria-hidden="true">
        <svg viewBox="0 0 24 24"><path d="M12 5v14M5 12h14" /></svg>
      </span>
      <span class="local-group-chat-member-name">添加</span>
    </button>
  `;
}

function renderLocalGroupChatRemoveMemberButton(
  record: LocalGroupChatRecord,
) {
  return `
    <button
      type="button"
      class="local-group-chat-member-cell local-group-chat-remove-member"
      data-action="open-remove-group-members-dialog"
      data-local-group-chat-id="${escapeAttr(record.id)}"
      role="listitem"
      aria-label="移出群成员"
      title="移出群成员"
      aria-haspopup="dialog"
      ${record.members.length ? "" : "disabled"}
    >
      <span class="local-group-chat-add-member-icon" aria-hidden="true">
        <svg viewBox="0 0 24 24"><path d="M5 12h14" /></svg>
      </span>
      <span class="local-group-chat-member-name">移出</span>
    </button>
  `;
}

function localGroupChatProfileNickname(record: LocalGroupChatRecord) {
  return record.nickname.trim() || currentProfileName();
}

function localGroupChatInfoValue(
  record: LocalGroupChatRecord,
  field: LocalGroupChatInfoField,
) {
  if (field === "nickname") return localGroupChatProfileNickname(record);
  return record[field];
}

function localGroupChatInfoMaxLength(field: LocalGroupChatInfoField) {
  if (field === "name") return 64;
  if (field === "nickname") return 32;
  if (field === "note") return 200;
  return 500;
}

function renderLocalGroupChatInfoEditIcon() {
  return `
    <span class="local-group-chat-info-edit-icon" aria-hidden="true">
      <svg viewBox="0 0 24 24">
        <path d="m15.5 5.5 3 3M5 19l3.7-.8L18.5 8.4a1.4 1.4 0 0 0 0-2l-.9-.9a1.4 1.4 0 0 0-2 0L5.8 15.3 5 19Z" />
      </svg>
    </span>
  `;
}

function renderLocalGroupChatInfoEditor(
  field: LocalGroupChatInfoField,
  label: string,
  editor: LocalGroupChatInfoEditorState,
) {
  const inputId = `localGroupChatInfo-${field}`;
  const errorId = `${inputId}-error`;
  const multiline = field === "announcement" || field === "note";
  const inputMarkup = multiline
    ? `<textarea
        id="${inputId}"
        data-local-group-info-input="${field}"
        maxlength="${localGroupChatInfoMaxLength(field)}"
        rows="${field === "announcement" ? "4" : "3"}"
        aria-label="${escapeAttr(label)}"
        ${editor.error ? `aria-invalid="true" aria-describedby="${errorId}"` : ""}
      >${escapeHtml(editor.value)}</textarea>`
    : `<input
        id="${inputId}"
        data-local-group-info-input="${field}"
        type="text"
        value="${escapeAttr(editor.value)}"
        maxlength="${localGroupChatInfoMaxLength(field)}"
        autocomplete="off"
        aria-label="${escapeAttr(label)}"
        ${editor.error ? `aria-invalid="true" aria-describedby="${errorId}"` : ""}
      />`;
  return `
    <div class="local-group-chat-info-item editing" data-local-group-info-field="${field}">
      <h3 id="${inputId}-label">${escapeHtml(label)}</h3>
      <form class="local-group-chat-info-editor ${editor.error ? "has-error" : ""}" data-local-group-info-form="${field}" aria-labelledby="${inputId}-label">
        ${inputMarkup}
        <div class="local-group-chat-info-editor-actions">
          <button type="button" data-action="cancel-local-group-info-edit" aria-label="取消编辑${escapeAttr(label)}" title="取消">
            <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18" /></svg>
          </button>
          <button type="submit" class="save" aria-label="保存${escapeAttr(label)}" title="保存">
            <svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4.2 4.2L19 6.5" /></svg>
          </button>
        </div>
        ${editor.error ? `<span id="${errorId}" class="local-group-chat-info-editor-error" role="alert">${escapeHtml(editor.error)}</span>` : ""}
      </form>
    </div>
  `;
}

function renderLocalGroupChatInfoItem(
  record: LocalGroupChatRecord,
  field: LocalGroupChatInfoField,
  label: string,
) {
  const editor =
    localGroupChatInfoEditor?.threadId === record.id
    && localGroupChatInfoEditor.field === field
      ? localGroupChatInfoEditor
      : null;
  if (editor) {
    return renderLocalGroupChatInfoEditor(field, label, editor);
  }
  const value = localGroupChatInfoValue(record, field);
  const displayValue = value || "未设置";
  return `
    <div class="local-group-chat-info-item" data-local-group-info-field="${field}">
      <h3>${escapeHtml(label)}</h3>
      <button
        type="button"
        class="local-group-chat-info-value ${value ? "" : "empty"}"
        data-local-group-info-edit="${field}"
        aria-label="编辑${escapeAttr(label)}，当前内容：${escapeAttr(displayValue)}"
        title="编辑${escapeAttr(label)}"
      >
        <span class="local-group-chat-info-value-text">${escapeHtml(displayValue)}</span>${renderLocalGroupChatInfoEditIcon()}
      </button>
    </div>
  `;
}

function renderLocalGroupChatMembersPanel(record: LocalGroupChatRecord) {
  const collapsed = state.rightCollapsed;
  const query = localGroupChatMemberQueries.get(record.id)?.trim() || "";
  const normalizedQuery = query.toLowerCase();
  const visibleMembers = normalizedQuery
    ? record.members.filter((member) =>
        localGroupChatMemberPresentation(member).name.toLowerCase().includes(normalizedQuery),
      )
    : record.members;
  const duplicateCounts = new Map<string, number>();
  const occurrenceCounts = new Map<string, number>();
  record.members.forEach((member) => {
    duplicateCounts.set(
      member.selectionId,
      (duplicateCounts.get(member.selectionId) || 0) + 1,
    );
  });
  return `
    <aside class="agent-panel local-group-chat-members-panel ${collapsed ? "collapsed" : "expanded"}" aria-hidden="${collapsed ? "true" : "false"}" aria-label="群聊成员信息">
      <div class="agent-panel-inner local-group-chat-members-inner">
        <div class="local-group-chat-members-scroll">
          <label class="local-group-chat-member-search">
            <img src="${escapeAttr(HOME_ICON_URL.search)}" alt="" />
            <input
              id="localGroupChatMemberSearch"
              type="search"
              value="${escapeAttr(query)}"
              placeholder="搜索群成员"
              autocomplete="off"
              aria-label="搜索群成员"
            />
          </label>
          <section class="local-group-chat-members-section" aria-label="群聊成员列表">
            <div class="local-group-chat-member-grid" role="list">
              ${visibleMembers
                .map((member) => {
                  const occurrence =
                    (occurrenceCounts.get(member.selectionId) || 0) + 1;
                  occurrenceCounts.set(member.selectionId, occurrence);
                  return renderLocalGroupChatMemberCell(
                    member,
                    occurrence,
                    duplicateCounts.get(member.selectionId) || 1,
                  );
                })
                .join("")}
              ${renderLocalGroupChatAddMemberButton(record)}
              ${renderLocalGroupChatRemoveMemberButton(record)}
            </div>
            ${
              visibleMembers.length
                ? ""
                : `<div class="local-group-chat-member-empty">没有找到匹配的群成员</div>`
            }
          </section>
          <section class="local-group-chat-info" aria-label="群聊资料">
            ${renderLocalGroupChatInfoItem(record, "name", "群聊名称")}
            ${renderLocalGroupChatInfoItem(record, "announcement", "群公告")}
            ${renderLocalGroupChatInfoItem(record, "note", "备注")}
            ${renderLocalGroupChatInfoItem(record, "nickname", "我在本群的昵称")}
          </section>
        </div>
      </div>
    </aside>
  `;
}

function isLocalGroupChatInfoField(
  value: string | null | undefined,
): value is LocalGroupChatInfoField {
  return (
    value === "name"
    || value === "announcement"
    || value === "note"
    || value === "nickname"
  );
}

function openLocalGroupChatInfoEditor(
  threadId: string,
  field: LocalGroupChatInfoField,
) {
  const record = localGroupChatRecord(threadId);
  if (!record) return;
  localGroupChatInfoEditor = {
    threadId,
    field,
    value: localGroupChatInfoValue(record, field),
    error: null,
  };
  render();
  queueMicrotask(() => {
    const input = root.querySelector<HTMLInputElement | HTMLTextAreaElement>(
      `[data-local-group-info-input="${field}"]`,
    );
    input?.focus({ preventScroll: true });
    if (input instanceof HTMLInputElement) input.select();
    else input?.setSelectionRange(input.value.length, input.value.length);
  });
}

function cancelLocalGroupChatInfoEditor() {
  if (!localGroupChatInfoEditor) return;
  localGroupChatInfoEditor = null;
  render();
}

function submitLocalGroupChatInfoEditor() {
  const editor = localGroupChatInfoEditor;
  if (!editor) return;
  const record = localGroupChatRecord(editor.threadId);
  if (!record) {
    localGroupChatInfoEditor = null;
    render();
    return;
  }
  const value = editor.value.trim();
  if ((editor.field === "name" || editor.field === "nickname") && !value) {
    localGroupChatInfoEditor = {
      ...editor,
      error: editor.field === "name" ? "群聊名称不能为空" : "群昵称不能为空",
    };
    render();
    queueMicrotask(() => {
      root
        .querySelector<HTMLInputElement>(
          `[data-local-group-info-input="${editor.field}"]`,
        )
        ?.focus({ preventScroll: true });
    });
    return;
  }
  record[editor.field] = value;
  if (editor.field === "name") {
    threadNameOverrides[record.id] = value;
    state.threads = sortThreadsForList(
      state.threads.map((thread) =>
        thread.id === record.id ? { ...thread, name: value } : thread,
      ),
    );
    saveThreadPreferences();
  }
  localGroupChatInfoEditor = null;
  saveLocalGroupChatRecords();
  render();
}

function renderLocalGroupChatMemberMenu() {
  const menu = localGroupChatMemberMenu;
  if (!menu) return "";
  const record = localGroupChatRecord(menu.threadId);
  const member = localGroupChatMember(record, menu.selectionId);
  if (!record || !member) return "";
  return `
    <div class="local-group-chat-member-menu-scrim" data-action="close-local-group-member-menu"></div>
    <div
      class="local-group-chat-member-menu"
      style="left:${Math.max(8, menu.left)}px;top:${Math.max(8, menu.top)}px"
      role="menu"
      aria-label="${escapeAttr(`${localGroupChatMemberPresentation(member).name} 的群内操作`)}"
    >
      <button type="button" data-local-group-member-action="message" role="menuitem">发送消息</button>
      <button type="button" data-local-group-member-action="mention" role="menuitem">@ TA</button>
      <button type="button" data-local-group-member-action="profile" role="menuitem">查看资料</button>
      <button type="button" data-local-group-member-action="rename" role="menuitem">修改群昵称</button>
      <button type="button" data-local-group-member-action="mute" role="menuitem">${member.muted ? "取消群内禁言" : "设置群内禁言"}</button>
      <button type="button" class="danger" data-local-group-member-action="remove" role="menuitem">移出本群</button>
    </div>
  `;
}

function renderLocalGroupChatMemberDialog() {
  const dialog = localGroupChatMemberDialog;
  if (!dialog) return "";
  const record = localGroupChatRecord(dialog.threadId);
  const member = localGroupChatMember(record, dialog.selectionId);
  if (!record || !member) return "";
  const presentation = localGroupChatMemberPresentation(member);
  if (dialog.kind === "profile") {
    const profile = localGroupChatMemberProfile(member);
    const summary = profile?.summary || "暂无简介";
    const developer = profile?.developer || profile?.agent || "暂无开发者信息";
    const features = profile?.features || [];
    return `
      <div class="modal-backdrop local-group-chat-member-dialog-backdrop" data-action="close-local-group-member-dialog"></div>
      <dialog class="local-group-chat-member-dialog profile" open aria-modal="true" aria-labelledby="localGroupMemberProfileTitle">
        <section>
          <header class="local-group-chat-member-profile-header">
            ${renderLocalGroupChatAvatarContent(member, "local-group-chat-member-profile-avatar")}
            <h2 id="localGroupMemberProfileTitle">${escapeHtml(presentation.name)}</h2>
          </header>
          <dl class="local-group-chat-member-profile-details">
            <div><dt>简介</dt><dd>${escapeHtml(summary)}</dd></div>
            <div><dt>开发者</dt><dd>${escapeHtml(developer)}</dd></div>
            <div>
              <dt>功能介绍</dt>
              <dd>${
                features.length
                  ? `<ol>${features.map((feature) => `<li>${escapeHtml(feature)}</li>`).join("")}</ol>`
                  : "暂无功能介绍"
              }</dd>
            </div>
          </dl>
          <footer>
            <button type="button" class="primary" data-action="close-local-group-member-dialog">关闭</button>
          </footer>
        </section>
      </dialog>
    `;
  }
  if (dialog.kind === "rename") {
    return `
      <div class="modal-backdrop local-group-chat-member-dialog-backdrop" data-action="close-local-group-member-dialog"></div>
      <dialog class="local-group-chat-member-dialog" open aria-modal="true" aria-labelledby="localGroupMemberRenameTitle">
        <form id="localGroupMemberRenameForm">
          <h2 id="localGroupMemberRenameTitle">修改群昵称</h2>
          <p>仅修改此成员在当前群聊中的名称。</p>
          <input id="localGroupMemberRenameInput" value="${escapeAttr(dialog.name)}" maxlength="32" autocomplete="off" aria-label="群昵称" />
          ${dialog.error ? `<div class="local-group-chat-member-dialog-error" role="alert">${escapeHtml(dialog.error)}</div>` : ""}
          <footer>
            <button type="button" class="secondary" data-action="close-local-group-member-dialog">取消</button>
            <button type="submit" class="primary">保存</button>
          </footer>
        </form>
      </dialog>
    `;
  }
  return `
    <div class="modal-backdrop local-group-chat-member-dialog-backdrop" data-action="close-local-group-member-dialog"></div>
    <dialog class="local-group-chat-member-dialog" open aria-modal="true" aria-labelledby="localGroupMemberRemoveTitle">
      <section>
        <h2 id="localGroupMemberRemoveTitle">移出本群</h2>
        <p>确定将“${escapeHtml(presentation.name)}”移出本群吗？移出后将不再接收群消息或参与回应。</p>
        <footer>
          <button type="button" class="secondary" data-action="close-local-group-member-dialog">取消</button>
          <button type="button" class="danger" data-action="confirm-remove-local-group-member">移出</button>
        </footer>
      </section>
    </dialog>
  `;
}

function openLocalGroupChatMemberMenu(
  threadId: string,
  selectionId: string,
  clientX: number,
  clientY: number,
) {
  const record = localGroupChatRecord(threadId);
  if (!localGroupChatMember(record, selectionId)) return;
  const input = root.querySelector<HTMLTextAreaElement>("#composerInput");
  const menuWidth = 184;
  const menuHeight = 276;
  localGroupChatMemberDialog = null;
  localGroupChatMemberMenu = {
    threadId,
    selectionId,
    left: Math.max(
      8,
      Math.min(clientX, Math.max(8, window.innerWidth - menuWidth - 8)),
    ),
    top: Math.max(
      8,
      Math.min(clientY, Math.max(8, window.innerHeight - menuHeight - 8)),
    ),
    composerCursor: input?.selectionStart ?? state.composerText.length,
  };
  state.threadMenu = null;
  state.threadGroupMenu = null;
  state.contactMenu = null;
  render();
}

function closeLocalGroupChatMemberMenu(options: { renderAfter?: boolean } = {}) {
  if (!localGroupChatMemberMenu) return;
  localGroupChatMemberMenu = null;
  if (options.renderAfter !== false) render();
}

function insertLocalGroupChatMemberMention(
  member: LocalGroupChatMember,
  cursor: number,
) {
  const presentation = localGroupChatMemberPresentation(member);
  const input = root.querySelector<HTMLTextAreaElement>("#composerInput");
  const value = input?.value ?? state.composerText;
  const insertionPoint = Math.max(0, Math.min(cursor, value.length));
  const before = value.slice(0, insertionPoint);
  const after = value.slice(insertionPoint);
  const leadingSpacer = before && !/\s$/u.test(before) ? " " : "";
  const trailingSpacer = after.startsWith(" ") || !after ? " " : "";
  const token = `@${presentation.name}`;
  const nextValue = `${before}${leadingSpacer}${token}${trailingSpacer}${after}`;
  const nextCursor =
    insertionPoint + leadingSpacer.length + token.length + trailingSpacer.length;
  state.composerText = nextValue;
  state.composerSkillMention = {
    ...state.composerSkillMention,
    open: false,
    query: "",
    activeIndex: 0,
    submenu: null,
    start: -1,
    end: -1,
  };
  if (input) {
    input.value = nextValue;
    input.focus({ preventScroll: true });
    input.setSelectionRange(nextCursor, nextCursor);
  }
  rememberActiveComposerDraft();
  syncComposerMentionHighlights();
  syncComposerSendButton();
}

async function openLocalGroupChatMemberTask(member: LocalGroupChatMember) {
  const profile = localGroupChatMemberProfile(member);
  localGroupChatMemberMenu = null;
  if (isHaoloContact(profile)) {
    await openHaoloContactNewThread();
    return;
  }
  const provider = localGroupChatMemberProvider(member);
  if (provider && provider !== VIDEO_EXPERT_PROVIDER) {
    openProviderQuestionDraft(
      provider,
      profile?.id || member.selectionId,
      null,
      defaultProviderChatModelOption(provider),
    );
    return;
  }
  await messageContact(profile?.id || member.selectionId);
}

function toggleLocalGroupChatMemberMuted(
  record: LocalGroupChatRecord,
  selectionId: string,
) {
  const member = localGroupChatMember(record, selectionId);
  if (!member) return;
  const muted = !member.muted;
  record.members = record.members.map((candidate) =>
    candidate.selectionId === selectionId
      ? { ...candidate, muted }
      : candidate,
  );
  localGroupChatMemberMenu = null;
  appendLocalGroupChatMemberEvent(
    record,
    { ...member, muted },
    muted ? "muted" : "unmuted",
  );
}

function openLocalGroupChatMemberDialog(
  kind: LocalGroupChatMemberDialogState["kind"],
  record: LocalGroupChatRecord,
  member: LocalGroupChatMember,
) {
  localGroupChatMemberMenu = null;
  localGroupChatMemberDialog =
    kind === "rename"
      ? {
          kind,
          threadId: record.id,
          selectionId: member.selectionId,
          name: localGroupChatMemberPresentation(member).name,
          error: null,
        }
      : {
          kind,
          threadId: record.id,
          selectionId: member.selectionId,
        };
  render();
  if (kind === "rename") {
    queueMicrotask(() => {
      const input = root.querySelector<HTMLInputElement>(
        "#localGroupMemberRenameInput",
      );
      input?.focus({ preventScroll: true });
      input?.select();
    });
  }
}

function submitLocalGroupChatMemberRename() {
  const dialog = localGroupChatMemberDialog;
  if (!dialog || dialog.kind !== "rename") return;
  const record = localGroupChatRecord(dialog.threadId);
  const name = dialog.name.trim();
  if (!record) {
    localGroupChatMemberDialog = null;
    render();
    return;
  }
  if (!name) {
    localGroupChatMemberDialog = {
      ...dialog,
      error: "群昵称不能为空",
    };
    render();
    return;
  }
  record.members = record.members.map((member) =>
    member.selectionId === dialog.selectionId
      ? { ...member, name }
      : member,
  );
  for (const itemId of state.itemOrder[record.id] || []) {
    const item = state.items[record.id]?.[itemId] as
      | (CodexItem & { __youleLocalGroupMemberId?: string })
      | undefined;
    if (item?.__youleLocalGroupMemberId !== dialog.selectionId) continue;
    upsertItem(
      record.id,
      { ...item, sender_label: name },
      { updateThreadPreview: false },
    );
  }
  localGroupChatMemberDialog = null;
  persistLocalGroupChatMessages(record);
  render();
}

function confirmRemoveLocalGroupChatMember() {
  const dialog = localGroupChatMemberDialog;
  if (!dialog || dialog.kind !== "remove") return;
  const record = localGroupChatRecord(dialog.threadId);
  if (!record) {
    localGroupChatMemberDialog = null;
    render();
    return;
  }
  const member = localGroupChatMember(record, dialog.selectionId);
  if (!member) {
    localGroupChatMemberDialog = null;
    render();
    return;
  }
  forgetLocalGroupChatHaoloThread(record, member);
  record.members = record.members.filter(
    (member) => member.selectionId !== dialog.selectionId,
  );
  localGroupChatMemberDialog = null;
  appendLocalGroupChatMemberEvent(record, member, "removed");
}

function handleLocalGroupChatMemberAction(action: string) {
  const menu = localGroupChatMemberMenu;
  if (!menu) return;
  const record = localGroupChatRecord(menu.threadId);
  const member = localGroupChatMember(record, menu.selectionId);
  if (!record || !member) {
    closeLocalGroupChatMemberMenu();
    return;
  }
  if (action === "message") {
    void openLocalGroupChatMemberTask(member);
    return;
  }
  if (action === "mention") {
    const cursor = menu.composerCursor;
    localGroupChatMemberMenu = null;
    render();
    queueMicrotask(() => insertLocalGroupChatMemberMention(member, cursor));
    return;
  }
  if (action === "mute") {
    toggleLocalGroupChatMemberMuted(record, member.selectionId);
    return;
  }
  if (action === "profile" || action === "rename" || action === "remove") {
    openLocalGroupChatMemberDialog(action, record, member);
  }
}

function renderChatPanel(thread: ConversationSummary | null) {
  if (!thread) {
    return `
      <main class="chat-panel blank-panel">
        <div class="center-note">${state.loading ? "正在加载..." : "暂无会话"}</div>
      </main>
    `;
  }
  const autoTask = taskFromThreadId(thread.id);
  if (autoTask) return renderAutoTaskChatPanel(thread, autoTask);
  const localGroupChat = localGroupChatRecord(thread.id);
  if (localGroupChat) return renderLocalGroupChatPanel(thread, localGroupChat);
  if (isTradingExpertThreadId(thread.id)) {
    if (state.tradingExpertWorkspaceView !== "chart") {
      return `
        <main class="chat-panel trading-expert-chat-panel" aria-label="交易专家行情工作区">
          ${renderTradingExpertWorkspacePlaceholder(state.tradingExpertWorkspaceView)}
        </main>
      `;
    }
    return `
      <main class="chat-panel trading-expert-chat-panel" aria-label="交易专家行情工作区">
        ${renderTradingExpertMarketWorkspace()}
      </main>
    `;
  }
  if (isExternalTradingWorkspaceThreadId(thread.id)) {
    if (state.tradingExpertWorkspaceView !== "chart") {
      return `
        <main class="chat-panel trading-expert-chat-panel" aria-label="交易专家行情工作区">
          ${renderTradingExpertWorkspacePlaceholder(state.tradingExpertWorkspaceView)}
        </main>
      `;
    }
    return `
      <main class="chat-panel trading-expert-chat-panel" aria-label="交易专家行情工作区">
        ${renderTradingExpertMarketWorkspace()}
      </main>
    `;
  }
  if (isThreadSwitchLoadingState(thread.id)) {
    return `
      <main class="chat-panel">
        ${renderChatHeader(thread)}
        <div class="message-area">
          <section id="messageScroller" class="message-scroller" data-thread-id="${escapeAttr(thread.id)}" data-thread-loading="true" aria-busy="true">
            ${renderThreadSwitchLoadingPlaceholder()}
          </section>
          ${renderMessageScrollBottomButton()}
        </div>
        ${renderComposer(thread)}
      </main>
    `;
  }
  const messages = currentMessages();
  const blankNewThread = !isThreadBusy(thread.id) && isBlankNewThread(thread.id);
  const blankThreadHero = blankNewThread &&
    !isTradingExpertThreadId(thread.id) &&
    shouldRenderBlankThreadHero(thread.id)
    ? renderBlankThreadHero(thread.id)
    : "";
  const emptyContent = shouldHideEmptyChatStateDuringSwitch(thread.id)
    ? ""
    : blankThreadHero
      ? blankThreadHero
      : `<div class="center-note">还没有消息</div>`;
  const deferredEmptyState = renderDeferredThreadResumeEmptyState(thread.id);
  const displayedEmptyContent = deferredEmptyState || emptyContent;
  const scrollerClass = !messages.length && blankThreadHero ? "message-scroller new-thread-scroller" : "message-scroller";
  const messageSearchHighlight = threadHistoryJumpHighlightTargetForMessages(thread.id);
  const continuationPrelude = renderThreadContinuationPrelude(thread.id);
  const messageIds = new Set(messages.map((message) => message.id));
  const continuationAnchorMessageId = resolvedThreadContinuationAnchorMessageId(thread.id, messageIds);
  const continuationStatus = renderUnanchoredThreadContinuationStatuses(thread.id, messageIds, continuationAnchorMessageId);
  const firstClusterUserMessageId = firstMultiModelClusterUserMessageId(thread.id, messages);
  const renderedMessages = messages.map((message) =>
    `${renderMessage(message, messages, { messageSearchHighlight })}${renderMultiModelClusterPreludeAfterMessage(thread.id, message.id, firstClusterUserMessageId, messages)}${renderThreadContinuationStatusesAfterMessage(thread.id, message.id, continuationAnchorMessageId)}`
  ).join("");
  const hasConversationContent = Boolean(messages.length || continuationPrelude || continuationStatus);
  return `
    <main class="chat-panel">
      ${renderChatHeader(thread)}
      <div class="message-area">
        <section id="messageScroller" class="${scrollerClass}" data-thread-id="${escapeAttr(thread.id)}">
          ${
            hasConversationContent
              ? `${continuationPrelude}${renderedMessages}${continuationStatus}${blankThreadHero}`
              : displayedEmptyContent
          }
        </section>
        ${renderMessageScrollBottomButton()}
      </div>
      ${renderComposer(thread)}
    </main>
  `;
}

