const TRADING_PREFERENCE_BINANCE_INVITATION = [
  "为了让后续交易分析更贴合你的真实账户情况，是否愿意连接币安账户的只读权限？",
  "",
  "连接后，Haolo 可以结合你的账户余额、持仓和风险敞口提供更有针对性的分析。只读权限不能下单、转账或修改账户设置。",
].join("\n");

const TRADING_PREFERENCE_BINANCE_CONNECTED = [
  "币安已经连接成功。",
  "",
  "Haolo 会结合你的账户余额、持仓和风险敞口提供更有针对性的分析。",
].join("\n");

const TRADING_PREFERENCE_REQUIRED_SECTIONS =
  "仓位健康度、风险校验、关键价位、入场条件、止损、止盈、仓位大小和失效条件";

type TradingPreferenceAnswers = {
  maxLossPerTradePercent?: number;
  moveStopToBreakEven?: boolean;
  breakEvenTriggerR?: number;
  minimumRiskRewardRatio?: number;
  analysisStyle?: "concise" | "detailed";
  requiredSections?: "fixed" | "adaptive";
  customRules?: string;
};

type TradingPreferenceOnboardingFlow = {
  stage: 1 | 2 | 3 | "saving" | "save-error";
  answers: TradingPreferenceAnswers;
  itemIds: string[];
  userStatements: string[];
};

let tradingPreferenceProfileLoadStatus: "idle" | "loading" | "loaded" | "error" = "idle";
let tradingPreferenceProfileCompleted = false;
let tradingPreferenceProfileLoadGeneration = 0;
const tradingPreferenceOnboardingByThreadId = new Map<string, TradingPreferenceOnboardingFlow>();

function resetTradingPreferenceProfileState() {
  tradingPreferenceProfileLoadGeneration += 1;
  tradingPreferenceProfileLoadStatus = "idle";
  tradingPreferenceProfileCompleted = false;
  tradingPreferenceOnboardingByThreadId.clear();
}

async function tradingPreferenceBinanceIsConnected() {
  if (state.binanceAccount.status?.bound === true) return true;
  if (binanceAccountLoadPromise) {
    try {
      await binanceAccountLoadPromise;
    } catch {
      // The onboarding completion can still fall back to the safe connection invitation.
    }
    if (state.binanceAccount.status) return Boolean(state.binanceAccount.status.bound);
  }
  if (typeof api.getBinanceAccountStatus !== "function") return false;
  try {
    const status = await api.getBinanceAccountStatus();
    if (Boolean(state.binanceAccount.status?.bound)) return true;
    state.binanceAccount.status = status;
    return status?.bound === true;
  } catch {
    return false;
  }
}

async function loadTradingPreferenceProfile(options: { renderAfter?: boolean } = {}) {
  if (!state.auth.authenticated || typeof api.getTradingPreferenceProfile !== "function") {
    tradingPreferenceProfileLoadStatus = "loaded";
    tradingPreferenceProfileCompleted = false;
    if (options.renderAfter !== false) render();
    return false;
  }
  const generation = ++tradingPreferenceProfileLoadGeneration;
  tradingPreferenceProfileLoadStatus = "loading";
  try {
    const result = await api.getTradingPreferenceProfile();
    if (generation !== tradingPreferenceProfileLoadGeneration) return false;
    tradingPreferenceProfileCompleted = result?.completed === true
      || result?.profile?.onboardingCompleted === true;
    tradingPreferenceProfileLoadStatus = "loaded";
    return true;
  } catch {
    if (generation !== tradingPreferenceProfileLoadGeneration) return false;
    tradingPreferenceProfileCompleted = false;
    tradingPreferenceProfileLoadStatus = "error";
    return false;
  } finally {
    if (generation === tradingPreferenceProfileLoadGeneration && options.renderAfter !== false) render();
  }
}

function renderTradingPreferenceOnboardingEntry(thread: ConversationSummary) {
  if (
    !isTradingExpertThreadId(thread.id)
    || tradingPreferenceProfileCompleted
    || !["loaded", "error"].includes(tradingPreferenceProfileLoadStatus)
    || messagesForThread(thread.id).length
    || isThreadBusy(thread.id)
  ) {
    return "";
  }
  return `
    <article class="message-row from-agent trading-preference-onboarding-message">
      <div class="message-stack">
        <div class="message-meta">Haolo</div>
        <div class="message-bubble agent-bubble trading-preference-onboarding-bubble">
          <div class="message-text" data-i18n-owned>${escapeHtml(TRADING_PREFERENCE_ONBOARDING_GREETING)}</div>
        </div>
        <div class="trading-preference-onboarding-actions">
          <button
            type="button"
            class="trading-preference-onboarding-start"
            data-action="start-trading-preference-onboarding"
          >开始</button>
        </div>
      </div>
    </article>
  `;
}

function startTradingPreferenceOnboarding() {
  const threadId = state.currentThreadId;
  const thread = threadById(threadId);
  if (
    !threadId
    || !thread
    || !isTradingExpertThreadId(threadId)
    || tradingPreferenceProfileCompleted
    || messagesForThread(threadId).length
    || isThreadBusy(threadId)
  ) {
    return;
  }
  const greetingItemId = `trading-preference-onboarding-greeting-${Date.now()}`;
  const questionItemId = `trading-preference-onboarding-question-1-${Date.now()}`;
  const greetingItem: CodexItem = {
    id: greetingItemId,
    type: "agentMessage",
    text: TRADING_PREFERENCE_ONBOARDING_GREETING,
    sender_label: "Haolo",
    createdAt: new Date().toISOString(),
    __youleLocalStatus: true,
  };
  const questionItem: CodexItem = {
    id: questionItemId,
    type: "agentMessage",
    text: TRADING_PREFERENCE_QUESTION_ONE,
    sender_label: "Haolo",
    createdAt: new Date().toISOString(),
    __youleLocalStatus: true,
  };
  upsertItem(threadId, greetingItem);
  upsertItem(threadId, questionItem);
  threadNameOverrides[threadId] = TRADING_PREFERENCE_THREAD_TITLE;
  state.threads = sortThreadsForList(state.threads.map((candidate) => (
    candidate.id === threadId
      ? { ...candidate, name: TRADING_PREFERENCE_THREAD_TITLE }
      : candidate
  )));
  tradingPreferenceOnboardingByThreadId.set(threadId, {
    stage: 1,
    answers: {},
    itemIds: [greetingItemId, questionItemId],
    userStatements: [],
  });
  render();
  scheduleScrollMessagesToBottom();
}

function tradingPreferenceReplyUsesCurrentRecommendation(text: string) {
  return /^同意[。！!]?$/.test(text.trim());
}

function tradingPreferenceNumber(value: unknown) {
  const number = Number(value);
  return Number.isFinite(number) && number > 0 ? Number(number.toFixed(4)) : null;
}

function tradingPreferencePercentFromReply(text: string) {
  const match = text.match(/(?:百分之\s*)?(\d+(?:\.\d+)?)\s*(?:%|％|百分比)?/);
  return tradingPreferenceNumber(match?.[1]);
}

function applyTradingPreferenceRecommendedRemaining(flow: TradingPreferenceOnboardingFlow) {
  flow.answers.maxLossPerTradePercent ??= 2;
  flow.answers.moveStopToBreakEven ??= true;
  flow.answers.breakEvenTriggerR ??= 1;
  flow.answers.minimumRiskRewardRatio ??= 0.4;
  flow.answers.analysisStyle ??= "concise";
  flow.answers.requiredSections ??= "fixed";
}

function tradingPreferenceQuestionTwoAnswers(text: string) {
  const noBreakEven = /(?:不|无需|不用|取消).{0,6}(?:移动)?保本|不移动(?:止损|保本)/.test(text);
  const triggerMatch = text.match(/(\d+(?:\.\d+)?)\s*[rR]\b/);
  // Parse both complete numbers before interpreting current 1:x or legacy x:1.
  // A word boundary also matches a decimal point, so it cannot delimit "1".
  const ratioMatch = text.match(/(?:^|[^\d.])(\d+(?:\.\d+)?)\s*[:：比]\s*(\d+(?:\.\d+)?)(?![\d.])/);
  const leftRatio = tradingPreferenceNumber(ratioMatch?.[1]);
  const rightRatio = tradingPreferenceNumber(ratioMatch?.[2]);
  const triggerR = tradingPreferenceNumber(triggerMatch?.[1]);
  const minimumRiskRewardRatio = leftRatio === 1 ? rightRatio : rightRatio === 1 ? leftRatio : null;
  if (!noBreakEven && triggerR === null && minimumRiskRewardRatio === null) return null;
  return {
    moveStopToBreakEven: !noBreakEven,
    breakEvenTriggerR: noBreakEven ? 1 : triggerR ?? 1,
    minimumRiskRewardRatio: minimumRiskRewardRatio ?? 0.4,
  };
}

function tradingPreferenceQuestionThreeAnswers(text: string) {
  const analysisStyle: "concise" | "detailed" = /详细|展开|完整说明/.test(text)
    ? "detailed"
    : "concise";
  const requiredSections: "fixed" | "adaptive" = /不固定|无需固定|不用固定|按需|自动决定/.test(text)
    ? "adaptive"
    : "fixed";
  const customRules = /必须|禁止|不允许|不能|只做|不做|禁忌|不得/.test(text)
    ? text.replace(/\u0000/g, "").trim().slice(0, 1_800)
    : "";
  return { analysisStyle, requiredSections, customRules };
}

function appendTradingPreferenceMessage(
  threadId: string,
  role: "user" | "assistant",
  text: string,
  flow: TradingPreferenceOnboardingFlow,
  actions: MessageAction[] = [],
) {
  const id = `trading-preference-${role}-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  const item: CodexItem = role === "user"
    ? {
        id,
        type: "userMessage",
        role: "user",
        text,
        content: [{ text, attachments: [] }],
        createdAt: new Date().toISOString(),
        __youleLocalStatus: true,
      }
    : {
        id,
        type: "agentMessage",
        text,
        sender_label: "Haolo",
        createdAt: new Date().toISOString(),
        __youleLocalStatus: true,
        ...(actions.length ? { actions } : {}),
      };
  upsertItem(threadId, item);
  flow.itemIds.push(id);
  return item;
}

function tradingPreferenceMemoryEntries(answers: TradingPreferenceAnswers) {
  const entries: Array<{
    scope: string;
    kind: "preference" | "constraint" | "fact" | "goal";
    key: string;
    value: string | number | boolean;
    strength: "normal" | "hard";
  }> = [
    { scope: "trading.profile", kind: "fact", key: "onboarding_completed", value: true, strength: "normal" },
    { scope: "trading.risk", kind: "constraint", key: "max_loss_per_trade_percent", value: answers.maxLossPerTradePercent ?? 2, strength: "hard" },
    { scope: "trading.risk", kind: "constraint", key: "loss_calculation_basis", value: "按当前账户净值计算止损触发后的实际亏损，包含手续费和预估滑点，不按保证金比例计算", strength: "hard" },
    { scope: "trading.risk", kind: "constraint", key: "minimum_risk_reward_ratio", value: answers.minimumRiskRewardRatio ?? 0.4, strength: "hard" },
    { scope: "trading.exit", kind: "preference", key: "move_stop_to_break_even", value: answers.moveStopToBreakEven !== false, strength: "normal" },
    { scope: "trading.exit", kind: "preference", key: "break_even_trigger_r", value: answers.breakEvenTriggerR ?? 1, strength: "normal" },
    { scope: "communication", kind: "preference", key: "trading_analysis_style", value: answers.analysisStyle ?? "concise", strength: "normal" },
    { scope: "trading.analysis", kind: "preference", key: "required_analysis_sections", value: answers.requiredSections === "adaptive" ? "根据问题按需选择栏目" : TRADING_PREFERENCE_REQUIRED_SECTIONS, strength: "normal" },
    { scope: "trading.discipline", kind: "constraint", key: "default_execution_discipline", value: "先确定止损和失效条件再计算仓位；不得通过随意缩小止损距离放大仓位；不默认使用马丁格尔或亏损加仓；亏损后可以继续寻找新机会，但不得为了回本提高风险或降低交易标准", strength: "hard" },
    { scope: "trading.behavior", kind: "preference", key: "risk_conflict_handling", value: "明确提示规则冲突和风险，并提供符合已保存风险规则的备选方案", strength: "normal" },
  ];
  if (answers.customRules) {
    entries.push({
      scope: "trading.discipline",
      kind: "constraint",
      key: "user_custom_rules",
      value: answers.customRules,
      strength: "hard",
    });
  }
  return entries;
}

function tradingPreferenceCompletionText(answers: TradingPreferenceAnswers) {
  const breakEven = answers.moveStopToBreakEven === false
    ? "不自动移动保本"
    : `浮盈达到 ${answers.breakEvenTriggerR ?? 1}R 后移动至覆盖交易成本的保本位置`;
  const style = answers.analysisStyle === "detailed" ? "详细" : "简洁";
  const sections = answers.requiredSections === "adaptive"
    ? "持仓分析和交易计划按问题选择必要栏目"
    : `持仓分析和交易计划固定包含${TRADING_PREFERENCE_REQUIRED_SECTIONS}`;
  const lines = [
    "配置完成，我已经将你的交易偏好安全保存到长期记忆：",
    "",
    `- 单笔最大风险：当前账户净值的 ${answers.maxLossPerTradePercent ?? 2}%；`,
    `- 浮盈保护：${breakEven}；`,
    `- 最低净盈亏比：1:${answers.minimumRiskRewardRatio ?? 0.4}；`,
    `- 回答风格：默认${style}；`,
    `- 分析结构：${sections}；`,
    ...(answers.customRules ? [`- 你的补充纪律：${answers.customRules}；`] : []),
    "- 规则冲突时：提示具体风险并提供符合规则的备选方案。",
    "",
    "以后无论使用普通分析、技能还是交易策略，我都会参考这份配置。你也可以随时告诉我修改交易偏好。",
  ];
  return lines.join("\n");
}

async function saveTradingPreferenceOnboarding(
  threadId: string,
  flow: TradingPreferenceOnboardingFlow,
) {
  applyTradingPreferenceRecommendedRemaining(flow);
  flow.stage = "saving";
  render();
  try {
    if (typeof api.saveTradingPreferenceProfile !== "function") {
      throw new Error("当前客户端不支持交易偏好长期记忆，请升级后重试");
    }
    const result = await api.saveTradingPreferenceProfile({
      userStatement: flow.userStatements.join("；").slice(0, 2_000)
        || "我同意采用 Haolo 推荐的交易配置，并要求长期保存。",
      entries: tradingPreferenceMemoryEntries(flow.answers),
    });
    if (result?.ok !== true || result?.completed !== true) {
      throw new Error("交易偏好没有完整写入长期记忆");
    }
    tradingPreferenceProfileCompleted = true;
    tradingPreferenceProfileLoadStatus = "loaded";
    const binanceConnected = await tradingPreferenceBinanceIsConnected();
    const completionItem = appendTradingPreferenceMessage(
      threadId,
      "assistant",
      tradingPreferenceCompletionText(flow.answers),
      flow,
    );
    const binanceStatusItem = appendTradingPreferenceMessage(
      threadId,
      "assistant",
      binanceConnected
        ? TRADING_PREFERENCE_BINANCE_CONNECTED
        : TRADING_PREFERENCE_BINANCE_INVITATION,
      flow,
      binanceConnected
        ? []
        : [{
            id: "connect-binance-account",
            kind: "navigate",
            label: "连接币安",
            destination: "binance-account",
          }],
    );
    const transcriptItems = flow.itemIds
      .map((id) => state.items[threadId]?.[id])
      .filter((item): item is CodexItem => Boolean(item));
    tradingPreferenceOnboardingByThreadId.delete(threadId);
    setMessageStreamFollow(threadId, true);
    render();
    scheduleScrollMessagesToBottom();
    void persistCompletedTradingExpertTranscript(
      threadId,
      transcriptItems.length ? transcriptItems : [completionItem, binanceStatusItem],
      { title: TRADING_PREFERENCE_THREAD_TITLE },
    );
  } catch (error) {
    flow.stage = "save-error";
    appendTradingPreferenceMessage(
      threadId,
      "assistant",
      `偏好暂时没有保存成功：${errorMessage(error)}\n\n请回复“重试保存”，我会保留你刚才的答案并再次保存。`,
      flow,
    );
    render();
    scheduleScrollMessagesToBottom();
  }
}

async function handleTradingPreferenceOnboardingReply(
  threadId: string,
  text: string,
  input: HTMLTextAreaElement | null,
) {
  const flow = tradingPreferenceOnboardingByThreadId.get(threadId);
  if (!flow) return false;
  if (state.attachments.length) {
    showToast("交易偏好问答只需要文字，请先移除附件", 3200);
    return true;
  }
  if (flow.stage === "saving") return true;
  const reply = text.replace(/\u0000/g, "").trim();
  if (!reply) return true;
  if (flow.stage === "save-error" && /^(?:重试保存|重试)[。！!]?$/i.test(reply)) {
    appendTradingPreferenceMessage(threadId, "user", reply, flow);
    clearTradingExpertComposerAfterSend(threadId);
    void saveTradingPreferenceOnboarding(threadId, flow);
    return true;
  }
  appendTradingPreferenceMessage(threadId, "user", reply, flow);
  flow.userStatements.push(reply);
  clearTradingExpertComposerAfterSend(threadId);

  if (flow.stage === 1) {
    const percent = tradingPreferenceReplyUsesCurrentRecommendation(reply)
      ? 2
      : tradingPreferencePercentFromReply(reply);
    if (percent === null) {
      appendTradingPreferenceMessage(
        threadId,
        "assistant",
        "我还没有识别到单笔风险比例。你可以回复“2%”“1.5%”“10%”或“同意”。完成本题后我们会继续下一题。",
        flow,
      );
    } else if (percent > 100) {
      appendTradingPreferenceMessage(
        threadId,
        "assistant",
        `单笔亏损比例不能超过账户净值的 100%。请填写 0.01%–100% 之间的比例，例如“2%”或“10%”。`,
        flow,
      );
    } else {
      flow.answers.maxLossPerTradePercent = percent;
      flow.stage = 2;
      appendTradingPreferenceMessage(threadId, "assistant", TRADING_PREFERENCE_QUESTION_TWO, flow);
    }
  } else if (flow.stage === 2) {
    const answer = tradingPreferenceReplyUsesCurrentRecommendation(reply)
      ? { moveStopToBreakEven: true, breakEvenTriggerR: 1, minimumRiskRewardRatio: 0.4 }
      : tradingPreferenceQuestionTwoAnswers(reply);
    if (!answer) {
      appendTradingPreferenceMessage(
        threadId,
        "assistant",
        "我还没有识别到保本或盈亏比设置。你可以回复“同意”“1.5R后保本，最低盈亏比1:1.5”或“不移动保本”。",
        flow,
      );
    } else {
      Object.assign(flow.answers, answer);
      flow.stage = 3;
      appendTradingPreferenceMessage(threadId, "assistant", TRADING_PREFERENCE_QUESTION_THREE, flow);
    }
  } else if (flow.stage === 3 || flow.stage === "save-error") {
    const answer = tradingPreferenceReplyUsesCurrentRecommendation(reply)
      ? { analysisStyle: "concise" as const, requiredSections: "fixed" as const, customRules: "" }
      : tradingPreferenceQuestionThreeAnswers(reply);
    Object.assign(flow.answers, answer);
    await saveTradingPreferenceOnboarding(threadId, flow);
    return true;
  }
  setMessageStreamFollow(threadId, true);
  render();
  scheduleScrollMessagesToBottom();
  return true;
}

function workflowRevisionNodePayload(node: WorkflowCanvasNode) {
  return {
    id: node.id,
    displayCode: node.displayCode || null,
    kind: node.workflowRef ? "workflow" : node.kind,
    executorType: node.executorType || (node.workflowRef ? "nested_workflow" : undefined),
    title: node.title,
    purpose: node.purpose || "",
    provider: node.provider || null,
    model: node.model || null,
    executorCandidates: node.executorCandidates || [],
    prompt: String(node.prompt || "").trim(),
    dependsOn: node.dependsOn || [],
    inputBindings: node.inputBindings || [],
    joinPolicy: { mode: "all_required" },
    nodeContract: node.nodeContract || null,
    skillBindings: node.skillBindings || [],
    contextSelection: node.contextSelection || null,
    capabilityRequest: node.capabilityRequest || null,
    risk: node.risk || "low",
    acceptance: [],
    coordination: node.coordination || {
      mode: "solo",
      parallelGroup: null,
      reviewTargets: [],
    },
    workflowRef: node.workflowRef || null,
    attachmentRefs: node.attachmentRefs || [],
  };
}

function workflowRevisionDefinitionNodes(run: WorkflowCanvasRun) {
  return (run.nodes || [])
    .filter((node) => !isWorkflowSystemNode(node))
    .map(workflowRevisionNodePayload);
}

function workflowRevisionEntryBindings(
  run: WorkflowCanvasRun,
  layoutSnapshot: WorkflowCanvasLayoutSnapshot,
) {
  const nodeIds = new Set(workflowRevisionDefinitionNodes(run).map((node) => node.id));
  return [...new Set((layoutSnapshot.entryNodeIds || []).map((displayNodeId) => (
    String(displayNodeId || "").split("::executor:")[0]
  )).filter((nodeId) => nodeIds.has(nodeId)))]
    .map((targetNodeId) => ({ source: "workflow_input" as const, targetNodeId }));
}

function workflowRevisionResources(run: WorkflowCanvasRun) {
  return {
    attachments: run.metadata?.attachments || [],
    uploadManifest: run.metadata?.uploadManifest || [],
  };
}

function workflowRevisionStableJson(value: unknown): string {
  const sortValue = (candidate: unknown): unknown => {
    if (Array.isArray(candidate)) return candidate.map(sortValue);
    if (!candidate || typeof candidate !== "object") return candidate;
    return Object.fromEntries(
      Object.keys(candidate as Record<string, unknown>)
        .sort()
        .map((key) => [key, sortValue((candidate as Record<string, unknown>)[key])]),
    );
  };
  return JSON.stringify(sortValue(value));
}

function applyWorkflowRevisionEnvelope(
  threadId: string,
  envelope: WorkflowRevisionDraftEnvelope,
) {
  const currentRun = workflowRunsByThreadId.get(threadId)
    || workflowCanvasDraftsByThreadId.get(threadId);
  if (!currentRun || envelope.draft.threadId !== threadId) return null;
  const originalNodes = new Map(currentRun.nodes.map((node) => [node.id, node]));
  const definitionNodes = envelope.draft.nodes.map((definition) => {
    const existing = originalNodes.get(String(definition.id || ""));
    return {
      ...(existing || {}),
      ...definition,
      status: existing?.status || "pending",
      result: existing?.result || null,
      startedAt: existing?.startedAt || null,
      completedAt: existing?.completedAt || null,
    } as WorkflowCanvasNode;
  });
  const systemNodes = currentRun.nodes.filter(isWorkflowSystemNode);
  const finalNode = systemNodes.find((node) => node.id === "root-acceptance") || null;
  const leadingSystemNodes = systemNodes.filter((node) => node !== finalNode);
  const nextRun: WorkflowCanvasRun = {
    ...currentRun,
    rationale: (envelope.draft as WorkflowRevisionDraftSnapshot & { rationale?: string }).rationale
      || currentRun.rationale,
    metadata: {
      ...(currentRun.metadata || {}),
      attachments: envelope.draft.resources?.attachments || currentRun.metadata?.attachments || [],
      uploadManifest: envelope.draft.resources?.uploadManifest || currentRun.metadata?.uploadManifest || [],
      workflowRevisionDraftId: envelope.draft.id,
      workflowRevision: envelope.draft.revision,
    },
    nodes: [...leadingSystemNodes, ...definitionNodes, ...(finalNode ? [finalNode] : [])],
  };
  workflowRevisionDraftEnvelopesByThreadId.set(threadId, envelope);
  workflowCanvasDraftsByThreadId.set(threadId, nextRun);
  // A persisted revision envelope owns both the node definition and its layout.
  // Keep them selected as one structural draft; otherwise an empty persisted
  // node list can be rendered with the original run's cards and the draft's
  // empty entry bindings, leaving a visible but undeletable ghost node.
  workflowCanvasStructuralDraftThreadIds.add(threadId);
  if (envelope.layout && typeof envelope.layout === "object") {
    workflowCanvasLayoutSnapshotsByThreadId.set(threadId, {
      runId: nextRun.id,
      snapshot: envelope.layout as unknown as WorkflowCanvasLayoutSnapshot,
    });
  }
  return nextRun;
}

async function ensurePersistedWorkflowRevisionDraft(threadId: string) {
  const currentRun = workflowRunsByThreadId.get(threadId);
  if (!currentRun || !isTerminalWorkflowRun(currentRun) || !api.createWorkflowRevisionDraft) return null;
  const existing = workflowRevisionDraftEnvelopesByThreadId.get(threadId);
  if (existing?.draft.sourceRunId === currentRun.id) return existing;
  const pending = workflowRevisionDraftRequestsByThreadId.get(threadId);
  if (pending) return pending;
  const request = (async () => {
    const localDraft = createWorkflowCanvasRevisionDraft(currentRun, { persist: false });
    const layout = freezeWorkflowCanvasLayout(localDraft);
    const envelope = await api.createWorkflowRevisionDraft!({
      runId: currentRun.id,
      threadId,
      entryBindings: workflowRevisionEntryBindings(localDraft, layout),
      layout: layout as unknown as Record<string, unknown>,
    });
    applyWorkflowRevisionEnvelope(threadId, envelope);
    return envelope;
  })().finally(() => {
    workflowRevisionDraftRequestsByThreadId.delete(threadId);
  });
  workflowRevisionDraftRequestsByThreadId.set(threadId, request);
  return request;
}

async function synchronizeWorkflowRevisionDraft(
  threadId: string,
  desiredRun: WorkflowCanvasRun,
  desiredLayout: WorkflowCanvasLayoutSnapshot,
) {
  if (!api.applyWorkflowRevisionCommand) return;
  let envelope = await ensurePersistedWorkflowRevisionDraft(threadId);
  if (!envelope) return;
  const send = async (
    type: WorkflowRevisionCommand["type"],
    payload: Record<string, any>,
    layout?: WorkflowCanvasLayoutSnapshot,
  ) => {
    const command: WorkflowRevisionCommand = {
      commandId: globalThis.crypto?.randomUUID?.() || `workflow-command-${Date.now()}-${Math.random()}`,
      baseRevision: envelope!.draft.revision,
      type,
      payload,
    };
    envelope = await api.applyWorkflowRevisionCommand!({
      draftId: envelope!.draft.id,
      command,
      layout: layout as unknown as Record<string, unknown> | undefined,
    });
  };
  const desiredNodes = workflowRevisionDefinitionNodes(desiredRun);
  const resources = workflowRevisionResources(desiredRun);
  const entryBindings = workflowRevisionEntryBindings(desiredRun, desiredLayout);
  const definitionChanged = workflowRevisionStableJson({
    nodes: envelope.draft.nodes,
    resources: envelope.draft.resources || {},
    entryBindings: envelope.draft.entryBindings,
  }) !== workflowRevisionStableJson({ nodes: desiredNodes, resources, entryBindings });
  if (definitionChanged) {
    await send(
      "replace_definition",
      { nodes: desiredNodes, resources, entryBindings },
      desiredLayout,
    );
  }
  if (!definitionChanged && api.saveWorkflowRevisionLayout) {
    await api.saveWorkflowRevisionLayout({
      draftId: envelope.draft.id,
      layout: desiredLayout as unknown as Record<string, unknown>,
    });
    envelope = { ...envelope, layout: desiredLayout as unknown as Record<string, unknown> };
  }
  applyWorkflowRevisionEnvelope(threadId, envelope);
}

async function persistWorkflowRevisionDraftForExecution(threadId: string) {
  while (true) {
    const pending = workflowRevisionPersistenceByThreadId.get(threadId);
    if (pending) {
      await pending;
      continue;
    }
    const desiredRun = workflowCanvasDraftsByThreadId.get(threadId)
      || workflowRunsByThreadId.get(threadId)
      || null;
    if (!desiredRun || !isTerminalWorkflowRun(desiredRun)) return null;
    const desiredLayout = freezeWorkflowCanvasLayout(desiredRun);
    const desiredSignature = workflowRevisionStableJson({
      nodes: workflowRevisionDefinitionNodes(desiredRun),
      resources: workflowRevisionResources(desiredRun),
      entryBindings: workflowRevisionEntryBindings(desiredRun, desiredLayout),
      layout: desiredLayout,
    });
    await queueWorkflowRevisionPersistence(threadId, desiredRun, desiredLayout);
    if (workflowRevisionPersistenceByThreadId.get(threadId)) continue;
    const latestRun = workflowCanvasDraftsByThreadId.get(threadId)
      || workflowRunsByThreadId.get(threadId)
      || null;
    if (!latestRun || !isTerminalWorkflowRun(latestRun)) return null;
    const latestLayout = freezeWorkflowCanvasLayout(latestRun);
    const latestSignature = workflowRevisionStableJson({
      nodes: workflowRevisionDefinitionNodes(latestRun),
      resources: workflowRevisionResources(latestRun),
      entryBindings: workflowRevisionEntryBindings(latestRun, latestLayout),
      layout: latestLayout,
    });
    if (desiredSignature === latestSignature) {
      return workflowRevisionDraftEnvelopesByThreadId.get(threadId) || null;
    }
  }
}

function queueWorkflowRevisionPersistence(
  threadId: string,
  run: WorkflowCanvasRun,
  layoutSnapshot: WorkflowCanvasLayoutSnapshot,
) {
  if (!api.createWorkflowRevisionDraft || !api.applyWorkflowRevisionCommand) return Promise.resolve();
  const desiredRun = typeof structuredClone === "function"
    ? structuredClone(run)
    : JSON.parse(JSON.stringify(run)) as WorkflowCanvasRun;
  const desiredLayout = typeof structuredClone === "function"
    ? structuredClone(layoutSnapshot)
    : JSON.parse(JSON.stringify(layoutSnapshot)) as WorkflowCanvasLayoutSnapshot;
  const previous = workflowRevisionPersistenceByThreadId.get(threadId) || Promise.resolve();
  const operation = previous
    .catch(() => undefined)
    .then(() => synchronizeWorkflowRevisionDraft(threadId, desiredRun, desiredLayout))
    .catch(async (error) => {
      console.error("[workflow] failed to persist revision draft", error);
      showToast(`画布保存失败：${error instanceof Error ? error.message : String(error)}`, 3600);
      const draftId = workflowRevisionDraftEnvelopesByThreadId.get(threadId)?.draft.id;
      const restored = draftId && api.getWorkflowRevisionDraft
        ? await api.getWorkflowRevisionDraft({ draftId }).catch(() => null)
        : null;
      if (restored) {
        applyWorkflowRevisionEnvelope(threadId, restored);
        render();
      }
    })
    .finally(() => {
      if (workflowRevisionPersistenceByThreadId.get(threadId) === operation) {
        workflowRevisionPersistenceByThreadId.delete(threadId);
      }
    });
  workflowRevisionPersistenceByThreadId.set(threadId, operation);
  return operation;
}

function createWorkflowCanvasRevisionDraft(
  run: WorkflowCanvasRun,
  options: { persist?: boolean } = {},
) {
  const existingDraft = workflowCanvasDraftsByThreadId.get(run.threadId);
  if (existingDraft?.id === run.id) return existingDraft;
  workflowCanvasLayoutSnapshotsByThreadId.delete(run.threadId);
  const draft = typeof structuredClone === "function"
    ? structuredClone(run)
    : JSON.parse(JSON.stringify(run)) as WorkflowCanvasRun;
  workflowCanvasDraftsByThreadId.set(run.threadId, draft);
  workflowCanvasDirtyNodeIdsByThreadId.set(run.threadId, new Set());
  workflowCanvasStructuralDraftThreadIds.delete(run.threadId);
  if (options.persist !== false) void ensurePersistedWorkflowRevisionDraft(run.threadId);
  return draft;
}

function workflowCanvasLayoutSnapshotForRun(
  threadId: string,
  runId: string,
) {
  const entry = workflowCanvasLayoutSnapshotsByThreadId.get(threadId);
  if (entry?.runId !== runId) return null;
  const run = workflowCanvasRunWithDraft(threadId);
  if (!run || run.id !== runId) return entry.snapshot;
  const snappedSnapshot = snapWorkflowCanvasLayoutToGrid(
    run,
    entry.snapshot,
    entry.snapshot.width,
  );
  entry.snapshot = snappedSnapshot;
  return snappedSnapshot;
}

function freezeWorkflowCanvasLayout(run: WorkflowCanvasRun) {
  const existing = workflowCanvasLayoutSnapshotForRun(run.threadId, run.id);
  if (existing) return existing;
  const snapshot = captureWorkflowCanvasLayout(run);
  workflowCanvasLayoutSnapshotsByThreadId.set(run.threadId, {
    runId: run.id,
    snapshot,
  });
  return snapshot;
}

function commitWorkflowCanvasStructuralMutation(
  run: WorkflowCanvasRun,
  layoutSnapshot: WorkflowCanvasLayoutSnapshot,
) {
  const previousLayoutSnapshot = workflowCanvasLayoutSnapshotForRun(run.threadId, run.id);
  const widthGrowth = previousLayoutSnapshot
    ? Math.max(0, layoutSnapshot.width - previousLayoutSnapshot.width)
    : 0;
  const storedChatPanelWidth = workflowChatPanelWidthsByThreadId.get(run.threadId);
  if (widthGrowth > 0 && storedChatPanelWidth !== undefined) {
    workflowChatPanelWidthsByThreadId.set(
      run.threadId,
      Math.max(
        WORKFLOW_CHAT_PANEL_MIN_WIDTH,
        storedChatPanelWidth - widthGrowth,
      ),
    );
  }
  workflowCanvasLayoutSnapshotsByThreadId.set(run.threadId, {
    runId: run.id,
    snapshot: layoutSnapshot,
  });
  workflowCanvasDraftsByThreadId.set(run.threadId, run);
  workflowCanvasStructuralDraftThreadIds.add(run.threadId);
  void queueWorkflowRevisionPersistence(run.threadId, run, layoutSnapshot);
}

function workflowCanvasRunWithDraft(threadId: string | null | undefined) {
  if (!threadId) return null;
  const currentRun = workflowRunsByThreadId.get(threadId) || null;
  const draft = workflowCanvasDraftsByThreadId.get(threadId) || null;
  const dirtyNodeIds = workflowCanvasDirtyNodeIdsByThreadId.get(threadId);
  if (
    currentRun
    && draft
    && currentRun.id === draft.id
    && workflowCanvasStructuralDraftThreadIds.has(threadId)
  ) {
    return draft;
  }
  if (
    !currentRun ||
    !draft ||
    currentRun.id !== draft.id ||
    !dirtyNodeIds?.size
  ) {
    return currentRun || draft;
  }
  const draftNodes = new Map(draft.nodes.map((node) => [node.id, node]));
  return {
    ...currentRun,
    metadata: draft.metadata,
    nodes: currentRun.nodes.map((currentNode) => {
      if (!dirtyNodeIds.has(currentNode.id)) return currentNode;
      const draftNode = draftNodes.get(currentNode.id);
      if (!draftNode) return currentNode;
      return {
        ...currentNode,
        kind: draftNode.kind,
        executorType: draftNode.executorType,
        provider: draftNode.provider,
        model: draftNode.model,
        executorCandidates: draftNode.executorCandidates,
        prompt: draftNode.prompt,
        joinPolicy: draftNode.joinPolicy,
        outputContract: draftNode.outputContract,
        acceptance: draftNode.acceptance,
        skillBindings: draftNode.skillBindings,
        contextSelection: draftNode.contextSelection,
      };
    }),
  };
}

function ensureWorkflowCanvasRevisionDraft(threadId: string) {
  const currentRun = workflowRunsByThreadId.get(threadId);
  if (!currentRun) return null;
  return createWorkflowCanvasRevisionDraft(currentRun);
}

function workflowCanvasInsertionTargetAtPoint(
  viewport: HTMLElement,
  clientX: number,
  clientY: number,
  excludedDisplayNodeId = "",
): { target: WorkflowCanvasInsertTarget; zoneLabel: string } | null {
  const rowBoundsByLayer = new Map<number, {
    top: number;
    bottom: number;
    nodes: Array<{
      rect: DOMRect;
      sourceNodeId: string;
      displayNodeId: string;
    }>;
  }>();
  viewport.querySelectorAll<HTMLElement>("[data-workflow-node-layer]").forEach((node) => {
    const layer = Number(node.dataset.workflowNodeLayer);
    if (!Number.isFinite(layer)) return;
    const sourceNodeId = String(node.dataset.workflowSourceNodeId || "").trim();
    const displayNodeId = String(node.dataset.workflowNodeId || "").trim();
    if (excludedDisplayNodeId && displayNodeId === excludedDisplayNodeId) return;
    const rect = node.getBoundingClientRect();
    const existing = rowBoundsByLayer.get(layer);
    rowBoundsByLayer.set(layer, {
      top: existing ? Math.min(existing.top, rect.top) : rect.top,
      bottom: existing ? Math.max(existing.bottom, rect.bottom) : rect.bottom,
      nodes: [
        ...(existing?.nodes || []),
        { rect, sourceNodeId, displayNodeId },
      ],
    });
  });
  const rows = [...rowBoundsByLayer.entries()]
    .map(([layer, bounds]) => ({ layer, ...bounds }))
    .sort((left, right) => left.top - right.top || left.layer - right.layer);
  if (!rows.length) {
    return {
      target: {
        placement: "between",
        previousLayer: null,
        nextLayer: null,
      },
      zoneLabel: "作为第 1 行插入",
    };
  }

  for (let index = 0; index < rows.length; index += 1) {
    const row = rows[index];
    if (clientY < row.top) {
      const previousLayer = index > 0 ? rows[index - 1].layer : null;
      return {
        target: {
          placement: "between",
          previousLayer,
          nextLayer: row.layer,
        },
        zoneLabel: previousLayer == null
          ? "在第 1 行之前插入"
          : `在第 ${index}、${index + 1} 行之间插入`,
      };
    }
    if (clientY <= row.bottom) {
      const nearestNode = row.nodes.reduce((nearest, node) => {
        const distance = Math.abs(clientX - (node.rect.left + node.rect.width / 2));
        const nearestDistance = nearest
          ? Math.abs(clientX - (nearest.rect.left + nearest.rect.width / 2))
          : Number.POSITIVE_INFINITY;
        return distance < nearestDistance ? node : nearest;
      }, null as (typeof row.nodes)[number] | null);
      const nearestCenterX = nearestNode
        ? nearestNode.rect.left + nearestNode.rect.width / 2
        : clientX;
      return {
        target: {
          placement: "parallel",
          layer: row.layer,
          anchorNodeId: nearestNode?.sourceNodeId || undefined,
          anchorDisplayNodeId: nearestNode?.displayNodeId || undefined,
          side: clientX < nearestCenterX ? "left" : "right",
        },
        zoneLabel: `与第 ${index + 1} 行并行`,
      };
    }
  }
  return {
    target: {
      placement: "between",
      previousLayer: rows.at(-1)?.layer ?? null,
      nextLayer: null,
    },
    zoneLabel: `在第 ${rows.length} 行之后插入`,
  };
}

function openWorkflowCanvasContextMenu(
  viewport: HTMLElement,
  event: MouseEvent,
) {
  const shell = viewport.closest<HTMLElement>(".cluster-workflow-shell");
  const graph = viewport.querySelector<HTMLElement>(".workflow-graph");
  const threadId = String(shell?.dataset.workflowThreadId || "").trim();
  const run = workflowCanvasRunWithDraft(threadId);
  const insertion = workflowCanvasInsertionTargetAtPoint(
    viewport,
    event.clientX,
    event.clientY,
  );
  if (!shell || !graph || !threadId || !run || !insertion) return;
  if (!isTerminalWorkflowRun(run)) {
    showToast("工作流结束后才可以调整节点结构", 2200);
    return;
  }
  const menuWidth = 204;
  const menuHeight = 190;
  const submenuGap = 8;
  const historyThreadCount = workflowReusableSpecsLoaded
    ? workflowReusableSpecs.length
    : workflowCanvasHistoryThreads(threadId).length;
  const submenuMaxHeight = Math.max(
    48,
    Math.min(360, window.innerHeight - menuHeight - submenuGap - 20),
  );
  const submenuHeight = Math.min(
    submenuMaxHeight,
    historyThreadCount ? historyThreadCount * 62 + 12 : 60,
  );
  const menuLeft = clampNumber(
    event.clientX,
    10,
    Math.max(10, window.innerWidth - menuWidth - 10),
  );
  const menuTop = clampNumber(
    event.clientY,
    10,
    Math.max(
      10,
      window.innerHeight - menuHeight - submenuGap - submenuHeight - 10,
    ),
  );
  const canvasPoint = workflowCanvasPointInGraph(
    graph,
    event.clientX,
    event.clientY,
  );
  workflowCanvasContextMenu = {
    threadId,
    runId: run.id,
    left: menuLeft,
    top: menuTop,
    submenuMaxHeight,
    canvasWidth: graph.offsetWidth,
    point: {
      x: Math.max(0, canvasPoint.x),
      y: Math.max(0, canvasPoint.y),
    },
    target: insertion.target,
    zoneLabel: insertion.zoneLabel,
  };
  void loadWorkflowReusableSpecs();
  render();
  window.requestAnimationFrame(() => {
    root
      .querySelector<HTMLButtonElement>("[data-workflow-canvas-context-menu] button")
      ?.focus({ preventScroll: true });
  });
}

function workflowCanvasDraftNodeTitle(
  run: WorkflowCanvasRun,
  baseTitle: string,
) {
  return workflowCanvasNextDraftNodeTitle(
    run.nodes.map((node) => node.title),
    baseTitle,
  );
}

function workflowCanvasDraftNode(
  run: WorkflowCanvasRun,
  kind: "model" | "agent",
  target: WorkflowCanvasInsertTarget,
) : WorkflowCanvasNode {
  const modelTemplate = run.nodes.find((node) => (
    node.kind === "model" && node.executorType !== "codex_subagent"
  ));
  const agentTemplate = run.nodes.find((node) => (
    node.kind === "agent" || node.executorType === "codex_subagent"
  ));
  const template = kind === "agent"
    ? agentTemplate || modelTemplate
    : modelTemplate || agentTemplate;
  const agentExecutors = kind === "agent"
    ? workflowCanvasExecutionAgentExecutorOptions(run.threadId)
    : [];
  const preferredAgentExecutor = agentExecutors.find((candidate) => (
    String(candidate.model || "").toLowerCase()
    === String(template?.model || "").toLowerCase()
  )) || agentExecutors.find((candidate) => (
    String(candidate.model || "").toLowerCase()
    === String(state.settings.model || "").toLowerCase()
  )) || agentExecutors[0] || null;
  const catalogDefault = kind === "model"
    ? defaultProviderModelSelection(state.providerModelCatalog)
    : null;
  const defaultProvider = kind === "agent"
    ? preferredAgentExecutor?.provider || null
    : template?.provider || catalogDefault?.provider || null;
  const defaultModel = kind === "agent"
    ? preferredAgentExecutor?.model || null
    : template?.model || catalogDefault?.option.value || null;
  const executorType = kind === "agent" ? "codex_subagent" : "external_model";
  const title = workflowCanvasDraftNodeTitle(
    run,
    kind === "agent" ? "新增智能体" : "新增模型",
  );
  const parallelCoordination = target.placement === "parallel"
    ? {
        mode: "parallel_candidate",
        parallelGroup: `draft-layer-${target.layer}`,
        reviewTargets: [],
      }
    : undefined;
  return {
    id: `draft-${kind}-${crypto.randomUUID()}`,
    kind,
    title,
    status: "pending",
    statusLabel: "待配置",
    purpose: kind === "agent"
      ? "由智能体独立完成任务，并将可执行结果交给下游节点。"
      : "独立处理当前任务，并输出可供下游节点使用的结果。",
    provider: defaultProvider,
    model: defaultModel,
    executorType,
    executorCandidates: kind === "agent"
      ? (preferredAgentExecutor
          ? [{
              executorType,
              provider: preferredAgentExecutor.provider || null,
              model: preferredAgentExecutor.model || null,
            }]
          : [])
      : (template?.executorCandidates?.length
          ? template.executorCandidates.map((candidate) => ({ ...candidate }))
          : [{
              executorType,
              provider: defaultProvider,
              model: defaultModel,
            }]),
    prompt: "",
    dependsOn: [],
    inputBindings: [],
    joinPolicy: null,
    outputContract: {
      format: "auto",
      requirements: [],
      requiredArtifactTypes: [],
    },
    acceptance: [],
    skillBindings: [],
    coordination: parallelCoordination,
    result: null,
  };
}

async function openWorkflowCanvasPendingNodeEditor(
  menu: WorkflowCanvasContextMenuState,
  kind: "model" | "agent",
) {
  if (kind === "model") {
    await refreshProviderModelCatalog({ renderAfter: false });
    if (workflowCanvasContextMenu !== menu) return false;
  } else {
    await Promise.all([
      refreshBusinessModelPools({ renderAfter: false }),
      preloadMediaCreationModelCatalogs({ renderAfter: false }),
    ]);
    if (workflowCanvasContextMenu !== menu) return false;
  }
  const draft = ensureWorkflowCanvasRevisionDraft(menu.threadId);
  if (!draft || draft.id !== menu.runId) {
    workflowCanvasContextMenu = null;
    showToast("画布已经更新，请重新选择插入位置", 2400);
    return false;
  }
  const node = workflowCanvasDraftNode(draft, kind, menu.target);
  const layoutSnapshot = workflowCanvasLayoutSnapshotForRun(menu.threadId, draft.id);
  const previewRun = insertWorkflowCanvasNode(draft, node, menu.target, layoutSnapshot);
  const preparedNode = previewRun.nodes.find((candidate) => candidate.id === node.id);
  if (!preparedNode) return false;
  workflowCanvasPendingNodeInsertion = {
    threadId: menu.threadId,
    runId: menu.runId,
    canvasWidth: menu.canvasWidth,
    point: menu.point,
    target: menu.target,
    zoneLabel: menu.zoneLabel,
    node: preparedNode,
  };
  workflowCanvasContextMenu = null;
  state.workflowNodeDialog = {
    threadId: menu.threadId,
    nodeId: node.id,
    sourceNodeId: node.id,
  };
  void loadPromptFavorites();
  render();
  window.requestAnimationFrame(() => {
    root
      .querySelector<HTMLButtonElement>('button[data-action="close-workflow-node-dialog"]')
      ?.focus({ preventScroll: true });
  });
  return true;
}

function insertWorkflowCanvasNestedSpec(
  menu: WorkflowCanvasContextMenuState,
  spec: WorkflowSpecSnapshot,
) {
  const draft = ensureWorkflowCanvasRevisionDraft(menu.threadId);
  if (!draft || draft.id !== menu.runId) {
    workflowCanvasContextMenu = null;
    showToast("画布已经更新，请重新选择插入位置", 2400);
    return false;
  }
  const boundary = spec.boundaryContract;
  if (boundary?.valid !== true || !boundary.nodeContract) {
    workflowCanvasContextMenu = null;
    showToast(boundary?.message || "该历史画布尚未定义固定输入输出，不能添加", 3000);
    render();
    return false;
  }
  const baseNode = workflowCanvasDraftNode(draft, "model", menu.target);
  const title = String(spec.goalContract?.deliverable || spec.workflowKey || "历史工作流");
  const purpose = `完整执行“${title}”冻结工作流并返回其最终节点输出`;
  const boundaryNodeContract = typeof structuredClone === "function"
    ? structuredClone(boundary.nodeContract)
    : JSON.parse(JSON.stringify(boundary.nodeContract)) as WorkflowNodeContract;
  boundaryNodeContract.taskDefinition = { text: purpose };
  const node: WorkflowCanvasNode = {
    ...baseNode,
    kind: "workflow",
    executorType: "nested_workflow",
    title: title.length > 18 ? `${title.slice(0, 18)}…` : title,
    purpose,
    provider: "haolo",
    model: `${spec.id}@${spec.version}`,
    prompt: "",
    nodeContract: boundaryNodeContract,
    acceptance: [],
    outputContract: {
      format: "auto",
      requirements: [],
      requiredArtifactTypes: [],
    },
    executorCandidates: [],
    workflowRef: {
      specId: spec.id,
      version: spec.version,
      graphHash: spec.graphHash,
    },
  };
  const currentLayout = workflowCanvasLayoutSnapshotForRun(menu.threadId, draft.id)
    || captureWorkflowCanvasLayout(draft);
  const nextDraft = insertWorkflowCanvasNode(
    draft,
    node,
    menu.target,
    currentLayout,
  );
  const boundaryIssue = workflowCanvasNestedConnectionIssue(nextDraft, [node.id]);
  if (boundaryIssue) {
    workflowCanvasContextMenu = null;
    showToast(boundaryIssue, 3600);
    render();
    return false;
  }
  const nextLayout = insertWorkflowCanvasNodeIntoLayoutSnapshot(
    currentLayout,
    nextDraft,
    node.id,
    menu.target,
    menu.point,
    false,
    menu.canvasWidth,
  );
  commitWorkflowCanvasStructuralMutation(nextDraft, nextLayout);
  workflowCanvasContextMenu = null;
  showToast(`已增加历史画布“${node.title}”`, 2000);
  render();
  return true;
}

function clearWorkflowCanvasPendingNodeInsertion(
  threadId: string,
  nodeId: string,
) {
  if (
    workflowCanvasPendingNodeInsertion?.threadId !== threadId
    || workflowCanvasPendingNodeInsertion.node.id !== nodeId
  ) return false;
  workflowCanvasPendingNodeInsertion = null;
  return true;
}

function openWorkflowNodeDeleteDialog(
  threadId: string,
  nodeId: string,
) {
  const draft = ensureWorkflowCanvasRevisionDraft(threadId);
  if (!draft || !isTerminalWorkflowRun(draft)) return;
  const node = draft?.nodes.find((candidate) => candidate.id === nodeId);
  if (!node) {
    showToast("该节点已经删除，画布已刷新", 1800);
    return;
  }
  if (isWorkflowSystemNode(node)) return;
  workflowCanvasContextMenu = null;
  workflowCanvasDeleteDialog = {
    threadId,
    runId: draft.id,
    nodeId,
    nodeTitle: node.title || "未命名节点",
  };
  render();
  window.requestAnimationFrame(() => {
    root
      .querySelector<HTMLButtonElement>('button[data-action="cancel-workflow-node-delete"]')
      ?.focus({ preventScroll: true });
  });
}

function cancelWorkflowNodeDelete() {
  const selection = workflowCanvasDeleteDialog;
  workflowCanvasDeleteDialog = null;
  render();
  if (!selection) return;
  window.requestAnimationFrame(() => {
    root
      .querySelectorAll<HTMLButtonElement>('[data-action="open-workflow-node-delete"]')
      .forEach((button) => {
        if (
          button.dataset.workflowThreadId === selection.threadId
          && button.dataset.workflowNodeId === selection.nodeId
        ) {
          button.focus({ preventScroll: true });
        }
      });
  });
}

function confirmWorkflowNodeDelete() {
  const selection = workflowCanvasDeleteDialog;
  if (!selection) return;
  const draft = ensureWorkflowCanvasRevisionDraft(selection.threadId);
  const deletedNode = draft?.nodes.find((node) => node.id === selection.nodeId);
  if (!draft || draft.id !== selection.runId || !deletedNode) {
    workflowCanvasDeleteDialog = null;
    showToast("画布已经更新，请重新选择要删除的节点", 2400);
    return;
  }
  const layoutSnapshot = freezeWorkflowCanvasLayout(draft);
  const nextDraft = deleteWorkflowCanvasNode(draft, selection.nodeId);
  if (nextDraft === draft) {
    workflowCanvasDeleteDialog = null;
    showToast("该节点不能删除", 2200);
    return;
  }
  const nextLayoutSnapshot = deleteWorkflowCanvasNodeFromLayoutSnapshot(
    layoutSnapshot,
    draft,
    nextDraft,
    selection.nodeId,
  );
  commitWorkflowCanvasStructuralMutation(nextDraft, nextLayoutSnapshot);
  if (
    state.activeView === "chat"
    && state.currentThreadId === selection.threadId
  ) {
    maybeAutoCollapseLeftPanelForWorkflow(nextDraft);
  }
  const dirtyNodeIds = workflowCanvasDirtyNodeIdsByThreadId.get(selection.threadId) || new Set<string>();
  dirtyNodeIds.delete(selection.nodeId);
  for (const nextNode of nextDraft.nodes) {
    const previousNode = draft.nodes.find((node) => node.id === nextNode.id);
    if (
      previousNode
      && JSON.stringify(previousNode.dependsOn || []) !== JSON.stringify(nextNode.dependsOn || [])
    ) {
      dirtyNodeIds.add(nextNode.id);
    }
  }
  workflowCanvasDirtyNodeIdsByThreadId.set(selection.threadId, dirtyNodeIds);
  if (
    state.workflowNodeDialog?.threadId === selection.threadId
    && state.workflowNodeDialog.sourceNodeId === selection.nodeId
  ) {
    state.workflowNodeDialog = null;
  }
  workflowCanvasDeleteDialog = null;
  showToast(`已删除节点“${selection.nodeTitle}”`, 1800);
}

function deleteWorkflowEdge(
  threadId: string,
  sourceNodeId: string,
  targetNodeId: string,
  displaySourceId: string,
  displayTargetId: string,
) {
  const draft = ensureWorkflowCanvasRevisionDraft(threadId);
  if (!draft || !isTerminalWorkflowRun(draft)) return;
  const nextDraft = deleteWorkflowCanvasEdge(draft, sourceNodeId, targetNodeId);
  if (nextDraft === draft) {
    showToast("该连接已经不存在", 1800);
    return;
  }
  const nodeCardsPreserved = (
    nextDraft.nodes.length === draft.nodes.length
    && nextDraft.nodes.every((node, index) => node.id === draft.nodes[index]?.id)
  );
  if (!nodeCardsPreserved) {
    showToast("删除连接失败，为避免节点丢失已取消操作", 2400);
    return;
  }
  const layoutSnapshot = freezeWorkflowCanvasLayout(draft);
  const nextLayoutSnapshot = removeWorkflowCanvasEdgeFromLayoutSnapshot(
    layoutSnapshot,
    displaySourceId,
    displayTargetId,
  );
  if (nextLayoutSnapshot.edges.length === layoutSnapshot.edges.length) {
    showToast("未找到选中的连接，已取消删除", 2200);
    return;
  }
  commitWorkflowCanvasStructuralMutation(nextDraft, nextLayoutSnapshot);
  const dirtyNodeIds = workflowCanvasDirtyNodeIdsByThreadId.get(threadId) || new Set<string>();
  dirtyNodeIds.add(targetNodeId);
  workflowCanvasDirtyNodeIdsByThreadId.set(threadId, dirtyNodeIds);
  showToast("已删除连接", 1800);
}

function deleteWorkflowComposerEdge(
  threadId: string,
  displayTargetId: string,
) {
  const draft = ensureWorkflowCanvasRevisionDraft(threadId);
  if (!draft || !isTerminalWorkflowRun(draft)) return;
  const layoutSnapshot = freezeWorkflowCanvasLayout(draft);
  const nextLayoutSnapshot = removeWorkflowCanvasComposerEdgeFromLayoutSnapshot(
    layoutSnapshot,
    displayTargetId,
  );
  if (nextLayoutSnapshot === layoutSnapshot) {
    showToast("该入口连接已经不存在", 1800);
    return;
  }
  commitWorkflowCanvasStructuralMutation(draft, nextLayoutSnapshot);
  showToast("已删除输入框入口连接", 1800);
}

function workflowCanvasConnectionShell(
  connection: Pick<WorkflowCanvasConnectionDraft, "threadId" | "runId">,
) {
  return [...root.querySelectorAll<HTMLElement>(".cluster-workflow-shell")].find((shell) => (
    shell.dataset.workflowThreadId === connection.threadId
    && shell.dataset.workflowRunId === connection.runId
  )) || null;
}

function workflowCanvasConnectionPortElement(
  connection: WorkflowCanvasConnectionDraft,
) {
  return [...root.querySelectorAll<HTMLElement>("[data-workflow-node-port]")].find((port) => (
    (port.dataset.workflowConnectionOrigin === "composer" ? "composer" : "node") === connection.origin
    && port.dataset.workflowThreadId === connection.threadId
    && port.dataset.workflowNodeId === connection.nodeId
    && port.dataset.workflowDisplayNodeId === connection.displayNodeId
    && port.dataset.workflowNodePort === connection.port
  )) || null;
}

function cancelWorkflowCanvasConnection() {
  workflowCanvasConnectionDraft = null;
  const graph = root.querySelector<HTMLElement>(".workflow-graph");
  graph?.classList.remove(
    "is-connecting",
    "is-connecting-from-input",
    "is-connecting-from-output",
  );
  root.querySelectorAll<HTMLElement>("[data-workflow-node-port].is-connection-start").forEach((port) => {
    port.classList.remove("is-connection-start");
  });
  const preview = root.querySelector<SVGSVGElement>("[data-workflow-edge-preview]");
  preview?.setAttribute("hidden", "");
  preview
    ?.querySelector<SVGPathElement>("[data-workflow-edge-preview-path]")
    ?.removeAttribute("d");
  scheduleWorkflowComposerConnector();
}

function workflowCanvasConnectionPreviewPath(
  sourceX: number,
  sourceY: number,
  targetX: number,
  targetY: number,
) {
  const control = Math.max(28, Math.abs(targetY - sourceY) * 0.48);
  return `M ${sourceX} ${sourceY} C ${sourceX} ${sourceY + control}, ${targetX} ${targetY - control}, ${targetX} ${targetY}`;
}

function updateWorkflowCanvasConnectionPreview(
  clientX: number,
  clientY: number,
) {
  const connection = workflowCanvasConnectionDraft;
  if (!connection) return;
  const graph = workflowCanvasConnectionShell(connection)
    ?.querySelector<HTMLElement>(".workflow-graph");
  const preview = graph?.querySelector<SVGSVGElement>("[data-workflow-edge-preview]");
  const path = preview?.querySelector<SVGPathElement>("[data-workflow-edge-preview-path]");
  const startPort = workflowCanvasConnectionPortElement(connection);
  if (!graph || !preview || !path || !startPort) {
    cancelWorkflowCanvasConnection();
    return;
  }
  const graphRect = graph.getBoundingClientRect();
  const shellRect = workflowCanvasConnectionShell(connection)?.getBoundingClientRect();
  const portRect = startPort.getBoundingClientRect();
  const zoom = workflowCanvasZoomForElement(graph);
  const fixedX = connection.origin === "composer"
    ? ((shellRect ? shellRect.left : graphRect.left) - graphRect.left) / zoom
    : (portRect.left + portRect.width / 2 - graphRect.left) / zoom;
  const fixedY = (portRect.top + portRect.height / 2 - graphRect.top) / zoom;
  const pointerX = clampNumber(
    (clientX - graphRect.left) / zoom,
    0,
    graph.offsetWidth,
  );
  const pointerY = clampNumber(
    (clientY - graphRect.top) / zoom,
    0,
    graph.offsetHeight,
  );
  connection.pointerX = pointerX;
  connection.pointerY = pointerY;
  const pathData = connection.port === "output"
    ? workflowCanvasConnectionPreviewPath(fixedX, fixedY, pointerX, pointerY)
    : workflowCanvasConnectionPreviewPath(pointerX, pointerY, fixedX, fixedY);
  path.setAttribute("d", pathData);
  preview.removeAttribute("hidden");
}

function beginWorkflowCanvasConnection(port: HTMLElement) {
  const threadId = String(port.dataset.workflowThreadId || "").trim();
  const origin = port.dataset.workflowConnectionOrigin === "composer"
    ? "composer"
    : "node";
  const nodeId = origin === "composer"
    ? WORKFLOW_COMPOSER_CONNECTION_NODE_ID
    : String(port.dataset.workflowNodeId || "").trim();
  const displayNodeId = origin === "composer"
    ? WORKFLOW_COMPOSER_CONNECTION_NODE_ID
    : String(port.dataset.workflowDisplayNodeId || "").trim();
  const portType = port.dataset.workflowNodePort;
  const shell = port.closest<HTMLElement>(".cluster-workflow-shell")
    || [...root.querySelectorAll<HTMLElement>(".cluster-workflow-shell")].find((candidate) => (
      candidate.dataset.workflowThreadId === threadId
    ))
    || null;
  const runId = String(shell?.dataset.workflowRunId || "").trim();
  const draft = ensureWorkflowCanvasRevisionDraft(threadId);
  const graph = port.closest<HTMLElement>(".workflow-graph")
    || shell?.querySelector<HTMLElement>(".workflow-graph")
    || null;
  if (
    !threadId
    || !nodeId
    || !displayNodeId
    || !runId
    || (portType !== "input" && portType !== "output")
    || !draft
    || draft.id !== runId
    || !isTerminalWorkflowRun(draft)
    || !graph
  ) return;
  cancelWorkflowCanvasConnection();
  const graphRect = graph.getBoundingClientRect();
  const portRect = port.getBoundingClientRect();
  const zoom = workflowCanvasZoomForElement(graph);
  const pointerClientX = portRect.left + portRect.width / 2;
  const pointerClientY = portRect.top + portRect.height / 2;
  workflowCanvasConnectionDraft = {
    origin,
    threadId,
    runId,
    nodeId,
    displayNodeId,
    port: portType,
    pointerX: clampNumber(
      (pointerClientX - graphRect.left) / zoom,
      0,
      graph.offsetWidth,
    ),
    pointerY: clampNumber(
      (pointerClientY - graphRect.top) / zoom,
      0,
      graph.offsetHeight,
    ),
  };
  graph?.classList.add(
    "is-connecting",
    `is-connecting-from-${portType}`,
  );
  port.classList.add("is-connection-start");
  scheduleWorkflowComposerConnector();
  updateWorkflowCanvasConnectionPreview(
    pointerClientX,
    pointerClientY,
  );
}

function restoreWorkflowCanvasConnection() {
  const connection = workflowCanvasConnectionDraft;
  if (!connection) return;
  const startPort = workflowCanvasConnectionPortElement(connection);
  const shell = workflowCanvasConnectionShell(connection);
  const graph = shell?.querySelector<HTMLElement>(".workflow-graph");
  if (
    !startPort
    || !graph
    || shell?.dataset.workflowRunId !== connection.runId
  ) {
    cancelWorkflowCanvasConnection();
    return;
  }
  graph.classList.add(
    "is-connecting",
    `is-connecting-from-${connection.port}`,
  );
  startPort.classList.add("is-connection-start");
  const graphRect = graph.getBoundingClientRect();
  const zoom = workflowCanvasZoomForElement(graph);
  updateWorkflowCanvasConnectionPreview(
    graphRect.left + connection.pointerX * zoom,
    graphRect.top + connection.pointerY * zoom,
  );
}

function completeWorkflowCanvasConnection(port: HTMLElement) {
  const start = workflowCanvasConnectionDraft;
  if (!start) return;
  const endPort = port.dataset.workflowNodePort;
  const end: WorkflowCanvasConnectionDraft = {
    origin: port.dataset.workflowConnectionOrigin === "composer" ? "composer" : "node",
    threadId: String(port.dataset.workflowThreadId || "").trim(),
    runId: String(
      port.closest<HTMLElement>(".cluster-workflow-shell")?.dataset.workflowRunId
      || workflowCanvasConnectionShell(start)?.dataset.workflowRunId
      || "",
    ).trim(),
    nodeId: port.dataset.workflowConnectionOrigin === "composer"
      ? WORKFLOW_COMPOSER_CONNECTION_NODE_ID
      : String(port.dataset.workflowNodeId || "").trim(),
    displayNodeId: port.dataset.workflowConnectionOrigin === "composer"
      ? WORKFLOW_COMPOSER_CONNECTION_NODE_ID
      : String(port.dataset.workflowDisplayNodeId || "").trim(),
    port: endPort === "input" ? "input" : "output",
    pointerX: start.pointerX,
    pointerY: start.pointerY,
  };
  const source = start.port === "output" ? start : end;
  const target = start.port === "input" ? start : end;
  if (
    start.threadId !== end.threadId
    || start.runId !== end.runId
    || source.nodeId === target.nodeId
  ) {
    cancelWorkflowCanvasConnection();
    showToast("不能连接同一个节点", 1800);
    return;
  }
  const draft = ensureWorkflowCanvasRevisionDraft(start.threadId);
  if (!draft || draft.id !== start.runId || !isTerminalWorkflowRun(draft)) {
    cancelWorkflowCanvasConnection();
    showToast("画布已经更新，请重新连接", 2200);
    return;
  }
  const layoutSnapshot = freezeWorkflowCanvasLayout(draft);
  if (source.origin === "composer") {
    if (target.origin !== "node" || target.port !== "input") {
      cancelWorkflowCanvasConnection();
      showToast("输入框只能连接到节点的输入连接点", 2200);
      return;
    }
    const nextLayoutSnapshot = addWorkflowCanvasComposerEdgeToLayoutSnapshot(
      layoutSnapshot,
      target.displayNodeId,
    );
    if (nextLayoutSnapshot === layoutSnapshot) {
      cancelWorkflowCanvasConnection();
      showToast("该输入框入口连接已经存在", 2200);
      return;
    }
    commitWorkflowCanvasStructuralMutation(draft, nextLayoutSnapshot);
    cancelWorkflowCanvasConnection();
    showToast("已连接输入框到节点", 1800);
    return;
  }
  const connectionResult = reconcileWorkflowCanvasEdgeConnection(
    draft,
    layoutSnapshot,
    source.nodeId,
    target.nodeId,
    source.displayNodeId,
    target.displayNodeId,
  );
  if (!connectionResult) {
    cancelWorkflowCanvasConnection();
    showToast("该连接无效、已经存在或会形成循环", 2200);
    return;
  }
  const nestedNodeIds = [source.nodeId, target.nodeId].filter((nodeId) => (
    draft.nodes.some((node) => node.id === nodeId && Boolean(node.workflowRef))
  ));
  const boundaryIssue = nestedNodeIds.length
    ? workflowCanvasNestedConnectionIssue(connectionResult.run, nestedNodeIds)
    : null;
  if (boundaryIssue) {
    cancelWorkflowCanvasConnection();
    showToast(boundaryIssue, 3600);
    return;
  }
  commitWorkflowCanvasStructuralMutation(
    connectionResult.run,
    connectionResult.layoutSnapshot,
  );
  const dirtyNodeIds = workflowCanvasDirtyNodeIdsByThreadId.get(start.threadId) || new Set<string>();
  dirtyNodeIds.add(target.nodeId);
  workflowCanvasDirtyNodeIdsByThreadId.set(start.threadId, dirtyNodeIds);
  cancelWorkflowCanvasConnection();
  showToast("已连接节点", 1800);
}

function bindWorkflowCanvasConnectionEvents(container: ParentNode = root) {
  container.querySelectorAll<HTMLElement>("[data-workflow-node-port]").forEach((port) => {
    port.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const connection = workflowCanvasConnectionDraft;
      const portType = port.dataset.workflowNodePort;
      if (!connection) {
        beginWorkflowCanvasConnection(port);
        return;
      }
      const samePort = (
        connection.origin === (port.dataset.workflowConnectionOrigin === "composer" ? "composer" : "node")
        &&
        connection.threadId === port.dataset.workflowThreadId
        && connection.displayNodeId === port.dataset.workflowDisplayNodeId
        && connection.port === portType
      );
      if (samePort) {
        cancelWorkflowCanvasConnection();
        return;
      }
      if (connection.port === portType) {
        beginWorkflowCanvasConnection(port);
        return;
      }
      completeWorkflowCanvasConnection(port);
    });
  });
  restoreWorkflowCanvasConnection();
  if (workflowCanvasConnectionWindowBound) return;
  workflowCanvasConnectionWindowBound = true;
  window.addEventListener("pointermove", (event) => {
    if (!workflowCanvasConnectionDraft) return;
    updateWorkflowCanvasConnectionPreview(event.clientX, event.clientY);
  }, { passive: true });
  window.addEventListener("keydown", (event) => {
    if (event.key !== "Escape" || !workflowCanvasConnectionDraft) return;
    event.preventDefault();
    cancelWorkflowCanvasConnection();
  });
  window.addEventListener("click", (event) => {
    if (!workflowCanvasConnectionDraft) return;
    if (
      event.target instanceof Element
      && event.target.closest("[data-workflow-node-port]")
    ) return;
    event.preventDefault();
    event.stopPropagation();
    cancelWorkflowCanvasConnection();
  }, true);
  window.addEventListener("contextmenu", (event) => {
    if (!workflowCanvasConnectionDraft) return;
    event.preventDefault();
    event.stopPropagation();
    cancelWorkflowCanvasConnection();
  }, true);
  window.addEventListener("blur", cancelWorkflowCanvasConnection);
}

const WORKFLOW_CANVAS_POINTER_DRAG_THRESHOLD = 5;
const WORKFLOW_CANVAS_DRAG_EDGE_ZONE = 48;
const WORKFLOW_CANVAS_DRAG_EDGE_MAX_SPEED = 18;

function defaultWorkflowCanvasViewportTransform(viewport: HTMLElement): WorkflowCanvasViewportTransform {
  const graph = viewport.querySelector<HTMLElement>(".workflow-graph");
  const zoom = 1;
  return {
    x: graph ? (viewport.clientWidth - graph.offsetWidth * zoom) / 2 : 0,
    y: 0,
    zoom,
  };
}

function workflowCanvasViewportTransformForViewport(
  viewport: HTMLElement,
): WorkflowCanvasViewportTransform {
  const shell = viewport.closest<HTMLElement>(".cluster-workflow-shell");
  const threadId = String(shell?.dataset.workflowThreadId || "").trim();
  const storedTransform = threadId
    ? workflowCanvasViewportTransformsByThreadId.get(threadId)
    : undefined;
  if (storedTransform) {
    return {
      x: storedTransform.x,
      y: storedTransform.y,
      zoom: normalizeWorkflowCanvasZoom(storedTransform.zoom),
    };
  }
  const renderedX = Number(viewport.dataset.workflowCanvasPanX);
  const renderedY = Number(viewport.dataset.workflowCanvasPanY);
  const renderedZoom = Number(viewport.dataset.workflowCanvasZoom);
  if (
    Number.isFinite(renderedX)
    && Number.isFinite(renderedY)
    && Number.isFinite(renderedZoom)
  ) {
    return {
      x: renderedX,
      y: renderedY,
      zoom: normalizeWorkflowCanvasZoom(renderedZoom),
    };
  }
  return defaultWorkflowCanvasViewportTransform(viewport);
}

function workflowCanvasZoomForViewport(viewport: HTMLElement) {
  return workflowCanvasViewportTransformForViewport(viewport).zoom;
}

function workflowCanvasZoomForElement(element: Element | null) {
  const viewport = element?.closest<HTMLElement>(".cluster-workflow-viewport");
  return viewport ? workflowCanvasZoomForViewport(viewport) : 1;
}

function applyWorkflowCanvasViewportTransform(
  viewport: HTMLElement,
  requestedTransform: WorkflowCanvasViewportTransform,
) {
  const canvas = viewport.querySelector<HTMLElement>(".cluster-workflow-canvas");
  const graph = viewport.querySelector<HTMLElement>(".workflow-graph");
  const transform = {
    x: Number.isFinite(requestedTransform.x) ? requestedTransform.x : 0,
    y: Number.isFinite(requestedTransform.y) ? requestedTransform.y : 0,
    zoom: normalizeWorkflowCanvasZoom(requestedTransform.zoom),
  };
  if (!canvas || !graph) return transform;
  const shell = viewport.closest<HTMLElement>(".cluster-workflow-shell");
  const threadId = String(shell?.dataset.workflowThreadId || "").trim();
  viewport.dataset.workflowCanvasPanX = String(transform.x);
  viewport.dataset.workflowCanvasPanY = String(transform.y);
  viewport.dataset.workflowCanvasZoom = String(transform.zoom);
  canvas.style.setProperty("--workflow-canvas-pan-x", `${transform.x}px`);
  canvas.style.setProperty("--workflow-canvas-pan-y", `${transform.y}px`);
  canvas.style.setProperty("--workflow-canvas-zoom", String(transform.zoom));
  canvas.style.setProperty("--workflow-grid-size", `${18 * transform.zoom}px`);
  canvas.style.setProperty("--workflow-grid-dot-size", `${0.8 * transform.zoom}px`);
  if (threadId) workflowCanvasViewportTransformsByThreadId.set(threadId, transform);
  scheduleWorkflowComposerConnector();
  return transform;
}

function workflowCanvasPointInGraph(
  graph: HTMLElement,
  clientX: number,
  clientY: number,
) {
  const graphRect = graph.getBoundingClientRect();
  const zoom = workflowCanvasZoomForElement(graph);
  return {
    x: (clientX - graphRect.left) / zoom,
    y: (clientY - graphRect.top) / zoom,
  };
}

function expandWorkflowCanvasDragSurface(
  viewport: HTMLElement,
  growWidth: number,
  growHeight: number,
) {
  const canvas = viewport.querySelector<HTMLElement>(".cluster-workflow-canvas");
  const graph = viewport.querySelector<HTMLElement>(".workflow-graph");
  if (!canvas || !graph || (growWidth <= 0 && growHeight <= 0)) return;
  const width = Math.ceil(graph.offsetWidth + Math.max(0, growWidth));
  const height = Math.ceil(graph.offsetHeight + Math.max(0, growHeight));
  graph.style.width = `${width}px`;
  graph.style.height = `${height}px`;
  applyWorkflowCanvasViewportTransform(
    viewport,
    workflowCanvasViewportTransformForViewport(viewport),
  );
  graph.querySelectorAll<SVGSVGElement>(".workflow-edges, .workflow-edge-preview")
    .forEach((svg) => {
      svg.setAttribute("width", String(width));
      svg.setAttribute("height", String(height));
      svg.setAttribute("viewBox", `0 0 ${width} ${height}`);
    });
}

function workflowCanvasDragEdgeVelocity(
  pointer: number,
  start: number,
  end: number,
) {
  if (pointer < start + WORKFLOW_CANVAS_DRAG_EDGE_ZONE) {
    return -WORKFLOW_CANVAS_DRAG_EDGE_MAX_SPEED * clampNumber(
      (start + WORKFLOW_CANVAS_DRAG_EDGE_ZONE - pointer) / WORKFLOW_CANVAS_DRAG_EDGE_ZONE,
      0,
      1,
    );
  }
  if (pointer > end - WORKFLOW_CANVAS_DRAG_EDGE_ZONE) {
    return WORKFLOW_CANVAS_DRAG_EDGE_MAX_SPEED * clampNumber(
      (pointer - (end - WORKFLOW_CANVAS_DRAG_EDGE_ZONE)) / WORKFLOW_CANVAS_DRAG_EDGE_ZONE,
      0,
      1,
    );
  }
  return 0;
}

function workflowCanvasPointerIsOverScrollbar(
  viewport: HTMLElement,
  event: PointerEvent,
) {
  const rect = viewport.getBoundingClientRect();
  return (
    event.clientX >= rect.left + viewport.clientWidth
    || event.clientY >= rect.top + viewport.clientHeight
  );
}

function workflowCanvasBlankPanTarget(
  viewport: HTMLElement,
  event: PointerEvent,
) {
  if (!(event.target instanceof Element)) return false;
  if (workflowCanvasPointerIsOverScrollbar(viewport, event)) return false;
  return !event.target.closest([
    ".workflow-node",
    ".workflow-node-delete",
    "[data-workflow-node-port]",
    "[data-workflow-canvas-context-menu]",
  ].join(", "));
}

function workflowCanvasDropPreviewRect(
  viewport: HTMLElement,
  draggedNode: HTMLElement,
  target: WorkflowCanvasInsertTarget,
  clientX: number,
  _clientY: number,
) {
  const graph = viewport.querySelector<HTMLElement>(".workflow-graph");
  if (!graph) return null;
  const draggedRect = draggedNode.getBoundingClientRect();
  const width = draggedNode.offsetWidth || draggedRect.width;
  const height = draggedNode.offsetHeight || draggedRect.height;
  const draggedDisplayNodeId = String(draggedNode.dataset.workflowNodeId || "").trim();
  const rows = [...viewport.querySelectorAll<HTMLElement>(".workflow-node[data-workflow-node-layer]")]
    .filter((node) => node.dataset.workflowNodeId !== draggedDisplayNodeId)
    .reduce((rowsByLayer, node) => {
      const layer = Number(node.dataset.workflowNodeLayer);
      if (!Number.isFinite(layer)) return rowsByLayer;
      const row = rowsByLayer.get(layer) || [];
      row.push({ node, rect: node.getBoundingClientRect() });
      rowsByLayer.set(layer, row);
      return rowsByLayer;
    }, new Map<number, Array<{ node: HTMLElement; rect: DOMRect }>>());
  const orderedRows = [...rows.entries()]
    .map(([layer, nodes]) => ({
      layer,
      nodes: nodes.sort((left, right) => left.rect.left - right.rect.left),
      top: Math.min(...nodes.map(({ rect }) => rect.top)),
    }))
    .sort((left, right) => left.top - right.top || left.layer - right.layer);
  let left: number;
  let top: number;

  if (target.placement === "parallel") {
    const rowIndex = Math.max(0, orderedRows.findIndex((row) => row.layer === target.layer));
    const rowNodes = orderedRows[rowIndex]?.nodes || [];
    const anchorIndex = target.anchorDisplayNodeId
      ? rowNodes.findIndex(({ node }) => (
          node.dataset.workflowNodeId === target.anchorDisplayNodeId
        ))
      : -1;
    const nearestIndex = anchorIndex >= 0
      ? anchorIndex
      : rowNodes.reduce((bestIndex, { rect }, index) => {
          const distance = Math.abs(clientX - (rect.left + rect.width / 2));
          const bestRect = rowNodes[bestIndex]?.rect;
          const bestDistance = bestRect
            ? Math.abs(clientX - (bestRect.left + bestRect.width / 2))
            : Number.POSITIVE_INFINITY;
          return distance < bestDistance ? index : bestIndex;
        }, 0);
    const insertBefore = anchorIndex >= 0 && target.side
      ? target.side === "left"
      : clientX < ((rowNodes[nearestIndex]?.rect.left || clientX) + width / 2);
    const insertionIndex = clampNumber(
      nearestIndex + (insertBefore ? 0 : 1),
      0,
      rowNodes.length,
    );
    const requiredWidth = workflowCanvasGridMinimumWidth(rowNodes.length + 1);
    if (requiredWidth > graph.offsetWidth) {
      expandWorkflowCanvasDragSurface(
        viewport,
        requiredWidth - graph.offsetWidth,
        0,
      );
    }
    left = workflowCanvasGridRowXPositions(
      graph.offsetWidth,
      rowNodes.length + 1,
    )[insertionIndex] || 0;
    top = workflowCanvasGridLayerY(rowIndex);
  } else {
    const previousRowIndex = target.previousLayer == null
      ? -1
      : orderedRows.findIndex((row) => row.layer === target.previousLayer);
    const nextRowIndex = target.nextLayer == null
      ? -1
      : orderedRows.findIndex((row) => row.layer === target.nextLayer);
    const insertionRowIndex = previousRowIndex >= 0
      ? previousRowIndex + 1
      : nextRowIndex >= 0
        ? nextRowIndex
        : orderedRows.length;
    left = workflowCanvasGridRowXPositions(graph.offsetWidth, 1)[0] || 0;
    top = workflowCanvasGridLayerY(insertionRowIndex);
  }

  return {
    left: clampNumber(left, 0, Math.max(0, graph.offsetWidth - width)),
    top: clampNumber(top, 0, Math.max(0, graph.offsetHeight - height)),
    width,
    height,
  };
}

function updateWorkflowCanvasNodeDropPreview(
  viewport: HTMLElement,
  draggedNode: HTMLElement,
  target: WorkflowCanvasInsertTarget | null,
  clientX: number,
  clientY: number,
) {
  const graph = viewport.querySelector<HTMLElement>(".workflow-graph");
  if (!graph) return;
  let preview = graph.querySelector<HTMLElement>("[data-workflow-node-drop-preview]");
  if (!target) {
    preview?.remove();
    return;
  }
  const rect = workflowCanvasDropPreviewRect(
    viewport,
    draggedNode,
    target,
    clientX,
    clientY,
  );
  if (!rect) return;
  if (!preview) {
    preview = document.createElement("div");
    preview.className = "workflow-node-drop-preview";
    preview.dataset.workflowNodeDropPreview = "true";
    preview.setAttribute("aria-hidden", "true");
    graph.append(preview);
  }
  preview.style.left = `${rect.left}px`;
  preview.style.top = `${rect.top}px`;
  preview.style.width = `${rect.width}px`;
  preview.style.height = `${rect.height}px`;
}

function workflowCanvasCubicPoint(
  start: number,
  controlStart: number,
  controlEnd: number,
  end: number,
  progress: number,
) {
  const remaining = 1 - progress;
  return (
    remaining ** 3 * start
    + 3 * remaining ** 2 * progress * controlStart
    + 3 * remaining * progress ** 2 * controlEnd
    + progress ** 3 * end
  );
}

function updateWorkflowCanvasDraggedNodeEdges(
  graph: HTMLElement,
  draggedDisplayNodeIds: Set<string>,
) {
  const graphRect = graph.getBoundingClientRect();
  const zoom = workflowCanvasZoomForElement(graph);
  const nodeByDisplayId = new Map(
    [...graph.querySelectorAll<HTMLElement>(".workflow-node[data-workflow-node-id]")]
      .map((node) => [String(node.dataset.workflowNodeId || "").trim(), node] as const),
  );
  graph.querySelectorAll<SVGPathElement>(".workflow-edge[data-workflow-edge-source][data-workflow-edge-target]")
    .forEach((edge) => {
      const sourceId = String(edge.dataset.workflowEdgeSource || "").trim();
      const targetId = String(edge.dataset.workflowEdgeTarget || "").trim();
      if (!draggedDisplayNodeIds.has(sourceId) && !draggedDisplayNodeIds.has(targetId)) return;
      const sourcePort = nodeByDisplayId.get(sourceId)?.querySelector<HTMLElement>(".workflow-node-output");
      const targetPort = nodeByDisplayId.get(targetId)?.querySelector<HTMLElement>(".workflow-node-input");
      if (!sourcePort || !targetPort) return;
      const sourceRect = sourcePort.getBoundingClientRect();
      const targetRect = targetPort.getBoundingClientRect();
      const sourceX = (sourceRect.left + sourceRect.width / 2 - graphRect.left) / zoom;
      const sourceY = (sourceRect.top + sourceRect.height / 2 - graphRect.top) / zoom;
      const targetX = (targetRect.left + targetRect.width / 2 - graphRect.left) / zoom;
      const targetY = (targetRect.top + targetRect.height / 2 - graphRect.top) / zoom;
      const control = Math.max(28, Math.abs(targetY - sourceY) * 0.48);
      const path = workflowCanvasConnectionPreviewPath(
        sourceX,
        sourceY,
        targetX,
        targetY,
      );
      edge.setAttribute("d", path);
      const group = edge.closest<SVGGElement>(".workflow-edge-group");
      group?.querySelector<SVGPathElement>(".workflow-edge-hit")?.setAttribute("d", path);
      const deleteWrap = group?.querySelector<SVGForeignObjectElement>(".workflow-edge-delete-wrap");
      if (deleteWrap) {
        const progress = 1 / 3;
        const deleteX = workflowCanvasCubicPoint(
          sourceX,
          sourceX,
          targetX,
          targetX,
          progress,
        );
        const deleteY = workflowCanvasCubicPoint(
          sourceY,
          sourceY + control,
          targetY - control,
          targetY,
          progress,
        );
        deleteWrap.setAttribute("x", String(deleteX - 14));
        deleteWrap.setAttribute("y", String(deleteY - 14));
      }
    });
  scheduleWorkflowComposerConnector();
}

function markWorkflowCanvasMovedNodesDirty(
  threadId: string,
  previousRun: WorkflowCanvasRun,
  nextRun: WorkflowCanvasRun,
  movedNodeId: string,
) {
  const dirtyNodeIds = workflowCanvasDirtyNodeIdsByThreadId.get(threadId) || new Set<string>();
  dirtyNodeIds.add(movedNodeId);
  const previousNodeById = new Map(previousRun.nodes.map((node) => [node.id, node]));
  for (const node of nextRun.nodes) {
    const previousNode = previousNodeById.get(node.id);
    if (!previousNode || JSON.stringify(previousNode.dependsOn || []) !== JSON.stringify(node.dependsOn || [])) {
      dirtyNodeIds.add(node.id);
    }
  }
  workflowCanvasDirtyNodeIdsByThreadId.set(threadId, dirtyNodeIds);
}

function bindWorkflowCanvasPointerGestures(container: ParentNode = root) {
  container.querySelectorAll<HTMLElement>(".cluster-workflow-viewport").forEach((viewport) => {
    if (viewport.dataset.pointerGesturesBound === "1") return;
    viewport.dataset.pointerGesturesBound = "1";
    applyWorkflowCanvasViewportTransform(
      viewport,
      workflowCanvasViewportTransformForViewport(viewport),
    );
    let panGesture: {
      pointerId: number;
      startX: number;
      startY: number;
      panX: number;
      panY: number;
      dragging: boolean;
    } | null = null;
    let nodeGesture: {
      pointerId: number;
      node: HTMLButtonElement;
      threadId: string;
      runId: string;
      sourceNodeId: string;
      displayNodeId: string;
      startX: number;
      startY: number;
      startPanX: number;
      startPanY: number;
      dragging: boolean;
      cards: HTMLElement[];
      deleteButtons: HTMLElement[];
      displayNodeIds: Set<string>;
      insertion: ReturnType<typeof workflowCanvasInsertionTargetAtPoint>;
    } | null = null;
    const suppressedNodeClicks = new WeakSet<HTMLButtonElement>();
    let latestNodeDragPointer: { clientX: number; clientY: number } | null = null;
    let nodeDragAutoPanFrame = 0;

    const stopNodeDragAutoPan = () => {
      if (nodeDragAutoPanFrame) window.cancelAnimationFrame(nodeDragAutoPanFrame);
      nodeDragAutoPanFrame = 0;
      latestNodeDragPointer = null;
    };

    const applyNodeDragPosition = () => {
      const gesture = nodeGesture;
      const pointer = latestNodeDragPointer;
      if (!gesture?.dragging || !pointer) return;
      const viewportTransform = workflowCanvasViewportTransformForViewport(viewport);
      const zoom = viewportTransform.zoom;
      const deltaX = (
        pointer.clientX
        - gesture.startX
        - viewportTransform.x
        + gesture.startPanX
      ) / zoom;
      const deltaY = (
        pointer.clientY
        - gesture.startY
        - viewportTransform.y
        + gesture.startPanY
      ) / zoom;
      gesture.cards.forEach((card) => {
        card.style.transform = `translate3d(${deltaX}px, ${deltaY}px, 0)`;
      });
      gesture.deleteButtons.forEach((button) => {
        button.style.transform = `translate3d(${deltaX}px, ${deltaY}px, 0)`;
      });
      gesture.insertion = workflowCanvasInsertionTargetAtPoint(
        viewport,
        pointer.clientX,
        pointer.clientY,
        gesture.displayNodeId,
      );
      updateWorkflowCanvasNodeDropPreview(
        viewport,
        gesture.node,
        gesture.insertion?.target || null,
        pointer.clientX,
        pointer.clientY,
      );
      const graph = viewport.querySelector<HTMLElement>(".workflow-graph");
      if (graph) updateWorkflowCanvasDraggedNodeEdges(graph, gesture.displayNodeIds);
    };

    const runNodeDragAutoPan = () => {
      nodeDragAutoPanFrame = 0;
      const gesture = nodeGesture;
      const pointer = latestNodeDragPointer;
      if (!gesture?.dragging || !pointer) return;
      const rect = viewport.getBoundingClientRect();
      const horizontalVelocity = workflowCanvasDragEdgeVelocity(
        pointer.clientX,
        rect.left,
        rect.left + viewport.clientWidth,
      );
      const verticalVelocity = workflowCanvasDragEdgeVelocity(
        pointer.clientY,
        rect.top,
        rect.top + viewport.clientHeight,
      );
      if (horizontalVelocity || verticalVelocity) {
        const viewportTransform = workflowCanvasViewportTransformForViewport(viewport);
        applyWorkflowCanvasViewportTransform(viewport, {
          ...viewportTransform,
          x: viewportTransform.x - horizontalVelocity,
          y: viewportTransform.y - verticalVelocity,
        });
        applyNodeDragPosition();
        scheduleWorkflowComposerConnector();
      }
      nodeDragAutoPanFrame = window.requestAnimationFrame(runNodeDragAutoPan);
    };

    const finishPan = (event: PointerEvent) => {
      if (!panGesture || event.pointerId !== panGesture.pointerId) return;
      const wasDragging = panGesture.dragging;
      panGesture = null;
      viewport.classList.remove("is-panning");
      if (viewport.hasPointerCapture(event.pointerId)) {
        viewport.releasePointerCapture(event.pointerId);
      }
      if (wasDragging) {
        event.preventDefault();
        event.stopPropagation();
      }
    };

    const startPan = (event: PointerEvent) => {
      if (
        event.button !== 0
        || !event.isPrimary
        || !workflowCanvasBlankPanTarget(viewport, event)
      ) return;
      event.preventDefault();
      panGesture = {
        pointerId: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        panX: workflowCanvasViewportTransformForViewport(viewport).x,
        panY: workflowCanvasViewportTransformForViewport(viewport).y,
        dragging: false,
      };
      viewport.setPointerCapture(event.pointerId);
    };
    const composerConnector = viewport
      .closest<HTMLElement>(".cluster-workflow-shell")
      ?.querySelector<SVGSVGElement>(".workflow-composer-connector") || null;
    const preventNativeCanvasDrag = (event: DragEvent) => {
      event.preventDefault();
    };
    viewport.addEventListener("pointerdown", startPan);
    composerConnector?.addEventListener("pointerdown", startPan);
    viewport.addEventListener("dragstart", preventNativeCanvasDrag);
    composerConnector?.addEventListener("dragstart", preventNativeCanvasDrag);
    viewport.addEventListener("pointermove", (event) => {
      if (!panGesture || event.pointerId !== panGesture.pointerId) return;
      const deltaX = event.clientX - panGesture.startX;
      const deltaY = event.clientY - panGesture.startY;
      if (
        !panGesture.dragging
        && Math.hypot(deltaX, deltaY) < WORKFLOW_CANVAS_POINTER_DRAG_THRESHOLD
      ) return;
      panGesture.dragging = true;
      viewport.classList.add("is-panning");
      const currentTransform = workflowCanvasViewportTransformForViewport(viewport);
      applyWorkflowCanvasViewportTransform(viewport, {
        ...currentTransform,
        x: panGesture.panX + deltaX,
        y: panGesture.panY + deltaY,
      });
      scheduleWorkflowComposerConnector();
      event.preventDefault();
    });
    viewport.addEventListener("pointerup", finishPan);
    viewport.addEventListener("pointercancel", finishPan);
    viewport.addEventListener("lostpointercapture", finishPan);
    viewport.addEventListener("wheel", (event) => {
      if (!Number.isFinite(event.deltaY) || event.deltaY === 0) return;
      event.preventDefault();
      const graph = viewport.querySelector<HTMLElement>(".workflow-graph");
      if (!graph || panGesture || nodeGesture) return;
      const currentTransform = workflowCanvasViewportTransformForViewport(viewport);
      const currentZoom = currentTransform.zoom;
      const nextZoom = workflowCanvasZoomFromWheel(
        currentZoom,
        event.deltaY,
        event.deltaMode,
        viewport.clientHeight,
      );
      if (nextZoom === currentZoom) return;
      const viewportRect = viewport.getBoundingClientRect();
      const pointerX = event.clientX - viewportRect.left;
      const pointerY = event.clientY - viewportRect.top;
      const anchorX = (pointerX - currentTransform.x) / currentZoom;
      const anchorY = (pointerY - currentTransform.y) / currentZoom;
      applyWorkflowCanvasViewportTransform(viewport, {
        x: pointerX - anchorX * nextZoom,
        y: pointerY - anchorY * nextZoom,
        zoom: nextZoom,
      });
      restoreWorkflowCanvasConnection();
      scheduleWorkflowComposerConnector();
    }, { passive: false });

    const finishNodeDrag = (event: PointerEvent) => {
      const gesture = nodeGesture;
      if (!gesture || event.pointerId !== gesture.pointerId) return;
      nodeGesture = null;
      stopNodeDragAutoPan();
      const graph = viewport.querySelector<HTMLElement>(".workflow-graph");
      if (gesture.node.hasPointerCapture(event.pointerId)) {
        gesture.node.releasePointerCapture(event.pointerId);
      }
      gesture.cards.forEach((card) => {
        card.classList.remove("is-dragging");
        card.style.removeProperty("transform");
        card.removeAttribute("aria-grabbed");
      });
      gesture.deleteButtons.forEach((button) => {
        button.classList.remove("is-dragging");
        button.style.removeProperty("transform");
      });
      graph?.classList.remove("is-node-dragging");
      graph?.querySelector("[data-workflow-node-drop-preview]")?.remove();
      if (!gesture.dragging) return;
      suppressedNodeClicks.add(gesture.node);
      event.preventDefault();
      event.stopPropagation();
      const draft = ensureWorkflowCanvasRevisionDraft(gesture.threadId);
      const insertion = workflowCanvasInsertionTargetAtPoint(
        viewport,
        event.clientX,
        event.clientY,
        gesture.displayNodeId,
      ) || gesture.insertion;
      if (
        !graph
        || !draft
        || draft.id !== gesture.runId
        || !insertion
        || !isTerminalWorkflowRun(draft)
      ) {
        render();
        return;
      }
      const canvasPoint = workflowCanvasPointInGraph(
        graph,
        event.clientX,
        event.clientY,
      );
      const currentLayout = freezeWorkflowCanvasLayout(draft);
      const moved = moveWorkflowCanvasNodeToTarget(
        draft,
        currentLayout,
        gesture.sourceNodeId,
        insertion.target,
        {
          x: Math.max(0, canvasPoint.x),
          y: Math.max(0, canvasPoint.y),
        },
        gesture.displayNodeId,
        graph.offsetWidth,
      );
      if (!moved.moved) {
        render();
        return;
      }
      commitWorkflowCanvasStructuralMutation(moved.run, moved.layoutSnapshot);
      markWorkflowCanvasMovedNodesDirty(
        gesture.threadId,
        draft,
        moved.run,
        gesture.sourceNodeId,
      );
      showToast(`已移动节点“${gesture.node.querySelector(".workflow-node-title")?.textContent?.trim() || "未命名节点"}”`, 1600);
      render();
    };

    viewport.querySelectorAll<HTMLButtonElement>('.workflow-node[data-action="open-workflow-node-dialog"][data-workflow-node-draggable="true"]')
      .forEach((node) => {
        node.addEventListener("click", (event) => {
          if (!suppressedNodeClicks.has(node)) return;
          suppressedNodeClicks.delete(node);
          event.preventDefault();
          event.stopImmediatePropagation();
        }, true);
        node.addEventListener("pointerdown", (event) => {
          if (
            event.button !== 0
            || !event.isPrimary
            || !(event.target instanceof Element)
            || event.target.closest("[data-workflow-node-port]")
          ) return;
          const shell = viewport.closest<HTMLElement>(".cluster-workflow-shell");
          const threadId = String(node.dataset.workflowThreadId || "").trim();
          const runId = String(shell?.dataset.workflowRunId || "").trim();
          const sourceNodeId = String(node.dataset.workflowSourceNodeId || "").trim();
          const displayNodeId = String(node.dataset.workflowNodeId || "").trim();
          const run = workflowCanvasRunWithDraft(threadId);
          if (
            !threadId
            || !runId
            || !sourceNodeId
            || !displayNodeId
            || run?.id !== runId
            || !isTerminalWorkflowRun(run)
          ) return;
          const cards = [node];
          const displayNodeIds = new Set([displayNodeId]);
          const adjacentDeleteButton = node.nextElementSibling instanceof HTMLElement
            && node.nextElementSibling.matches('[data-action="open-workflow-node-delete"]')
            ? node.nextElementSibling
            : null;
          const deleteButtons = adjacentDeleteButton ? [adjacentDeleteButton] : [];
          const viewportTransform = workflowCanvasViewportTransformForViewport(viewport);
          nodeGesture = {
            pointerId: event.pointerId,
            node,
            threadId,
            runId,
            sourceNodeId,
            displayNodeId,
            startX: event.clientX,
            startY: event.clientY,
            startPanX: viewportTransform.x,
            startPanY: viewportTransform.y,
            dragging: false,
            cards,
            deleteButtons,
            displayNodeIds,
            insertion: null,
          };
          node.setPointerCapture(event.pointerId);
        });
        node.addEventListener("pointermove", (event) => {
          const gesture = nodeGesture;
          if (!gesture || gesture.node !== node || event.pointerId !== gesture.pointerId) return;
          const deltaX = event.clientX - gesture.startX;
          const deltaY = event.clientY - gesture.startY;
          if (
            !gesture.dragging
            && Math.hypot(deltaX, deltaY) < WORKFLOW_CANVAS_POINTER_DRAG_THRESHOLD
          ) return;
          if (!gesture.dragging) {
            gesture.dragging = true;
            workflowCanvasContextMenu = null;
            root.querySelector("[data-workflow-canvas-context-menu]")?.remove();
            cancelWorkflowCanvasConnection();
            gesture.cards.forEach((card) => {
              card.classList.add("is-dragging");
              card.setAttribute("aria-grabbed", "true");
            });
            gesture.deleteButtons.forEach((button) => button.classList.add("is-dragging"));
            viewport.querySelector(".workflow-graph")?.classList.add("is-node-dragging");
          }
          latestNodeDragPointer = {
            clientX: event.clientX,
            clientY: event.clientY,
          };
          applyNodeDragPosition();
          if (!nodeDragAutoPanFrame) {
            nodeDragAutoPanFrame = window.requestAnimationFrame(runNodeDragAutoPan);
          }
          event.preventDefault();
          event.stopPropagation();
        });
        node.addEventListener("pointerup", finishNodeDrag);
        node.addEventListener("pointercancel", finishNodeDrag);
        node.addEventListener("lostpointercapture", finishNodeDrag);
      });
  });
}

function bindWorkflowCanvasSurfaceEvents(container: ParentNode = root) {
  bindWorkflowCanvasPointerGestures(container);
  bindWorkflowCanvasConnectionEvents(container);
  container.querySelectorAll<HTMLButtonElement>('[data-action="open-workflow-node-delete"]').forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const threadId = String(button.dataset.workflowThreadId || "").trim();
      const nodeId = String(button.dataset.workflowNodeId || "").trim();
      if (!threadId || !nodeId) return;
      openWorkflowNodeDeleteDialog(threadId, nodeId);
    });
  });
  container.querySelectorAll<HTMLButtonElement>('[data-action="delete-workflow-edge"]').forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const threadId = String(button.dataset.workflowThreadId || "").trim();
      const sourceNodeId = String(button.dataset.workflowEdgeSource || "").trim();
      const targetNodeId = String(button.dataset.workflowEdgeTarget || "").trim();
      const displaySourceId = String(button.dataset.workflowEdgeDisplaySource || "").trim();
      const displayTargetId = String(button.dataset.workflowEdgeDisplayTarget || "").trim();
      if (
        !threadId
        || !sourceNodeId
        || !targetNodeId
        || !displaySourceId
        || !displayTargetId
      ) return;
      deleteWorkflowEdge(
        threadId,
        sourceNodeId,
        targetNodeId,
        displaySourceId,
        displayTargetId,
      );
    });
  });
  container.querySelectorAll<HTMLButtonElement>('[data-action="delete-workflow-composer-edge"]').forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const threadId = String(button.dataset.workflowThreadId || "").trim();
      const displayTargetId = String(button.dataset.workflowComposerEdgeTarget || "").trim();
      if (!threadId || !displayTargetId) return;
      deleteWorkflowComposerEdge(threadId, displayTargetId);
    });
  });
  container.querySelectorAll<HTMLButtonElement>('[data-action="open-workflow-node-dialog"]').forEach((button) => {
    button.addEventListener("click", () => {
      const threadId = String(button.dataset.workflowThreadId || "").trim();
      const nodeId = String(button.dataset.workflowNodeId || "").trim();
      const sourceNodeId = String(button.dataset.workflowSourceNodeId || nodeId).trim();
      const run = ensureWorkflowCanvasRevisionDraft(threadId);
      if (!threadId || !nodeId || !run?.nodes.some((node) => node.id === sourceNodeId)) return;
      workflowCanvasPendingNodeInsertion = null;
      state.workflowNodeDialog = { threadId, nodeId, sourceNodeId };
      void loadPromptFavorites();
      render();
      window.requestAnimationFrame(() => {
        root.querySelector<HTMLButtonElement>('button[data-action="close-workflow-node-dialog"]')?.focus({ preventScroll: true });
      });
    });
  });
}

function workflowCanvasDialogSkills(): WorkflowNodeDialogSkill[] {
  return state.skills.items
    .filter((skill) => skill.enabled !== false)
    .flatMap((skill): WorkflowNodeDialogSkill[] => {
      const id = firstString(skill.name, skill.path);
      if (!id) return [];
      const description = firstString(
        skill.interface?.shortDescription,
        skill.description,
      );
      return [{
        id,
        label: firstString(skill.interface?.displayName, skill.name, skill.path) || id,
        ...(description ? { description } : {}),
      }];
    });
}

function workflowNodeDialogAttachmentKind(
  attachment: Pick<LocalAttachment, "name" | "mime">,
) {
  const mime = String(attachment.mime || "").toLowerCase();
  const name = String(attachment.name || "").toLowerCase();
  if (mime === "inode/directory") return "folder";
  if (mime.startsWith("image/") || /\.(png|jpe?g|gif|webp|bmp|tiff?)$/i.test(name)) {
    return "image";
  }
  if (mime.startsWith("video/") || /\.(mp4|mpeg|mpg|mov|webm|avi|mkv|m4v|wmv|flv)$/i.test(name)) {
    return "video";
  }
  return "file";
}

function ensureWorkflowNodeDialogAttachmentDraft(
  run: WorkflowCanvasRun,
  nodeId: string,
) {
  const existing = workflowNodeDialogAttachmentDraft;
  if (
    existing?.threadId === run.threadId
    && existing.nodeId === nodeId
  ) {
    return existing;
  }
  existing?.attachments.forEach(revokeQueuedAttachmentUrls);
  workflowNodeDialogAttachmentDraft = {
    threadId: run.threadId,
    nodeId,
    // Existing workflow inputs and upstream outputs belong to the immutable
    // execution history. Only files explicitly added in this editor are shown.
    attachments: [],
  };
  return workflowNodeDialogAttachmentDraft;
}

function clearWorkflowNodeDialogAttachmentDraft() {
  workflowNodeDialogAttachmentDraft?.attachments.forEach(revokeQueuedAttachmentUrls);
  workflowNodeDialogAttachmentDraft = null;
}

function workflowNodeDialogAttachmentDraftForForm(
  form: HTMLFormElement | null | undefined,
) {
  const threadId = String(form?.dataset.workflowThreadId || "").trim();
  const nodeId = String(form?.dataset.workflowNodeId || "").trim();
  const draft = workflowNodeDialogAttachmentDraft;
  return (
    draft
    && draft.threadId === threadId
    && draft.nodeId === nodeId
  ) ? draft : null;
}

function workflowNodeDialogAttachmentView(
  attachment: LocalAttachment,
): WorkflowNodeDialogAttachment {
  return {
    id: attachment.id,
    name: attachment.name,
    mime: attachment.mime,
    size: attachment.size,
    iconUrl: attachmentIcon(attachment),
    closeIconUrl: HOME_ICON_URL.close,
    previewUrl: attachment.previewUrl || attachment.url || null,
    uploadStatus: attachment.uploadStatus || "uploaded",
    uploadError: attachment.uploadError || null,
  };
}

function patchWorkflowNodeDialogAttachments(form: HTMLFormElement) {
  const draft = workflowNodeDialogAttachmentDraftForForm(form);
  const currentRail = form.querySelector<HTMLElement>(
    "[data-workflow-node-attachments]",
  );
  const current = currentRail?.closest<HTMLElement>(
    "[data-workflow-node-attachments-wrap]",
  );
  if (!draft || !current || !currentRail) return;
  const previousScrollLeft = currentRail.scrollLeft;
  const template = document.createElement("template");
  template.innerHTML = renderWorkflowNodeDialogAttachments(
    draft.attachments.map(workflowNodeDialogAttachmentView),
  ).trim();
  const next = template.content.firstElementChild as HTMLElement | null;
  if (!next) return;
  current.replaceWith(next);
  const nextRail = next.querySelector<HTMLElement>(
    "[data-workflow-node-attachments]",
  );
  if (nextRail) nextRail.scrollLeft = previousScrollLeft;
  bindWorkflowNodeDialogAttachmentEvents(form);
}

function queueWorkflowNodeDialogFiles(
  form: HTMLFormElement,
  files: File[],
) {
  const draft = workflowNodeDialogAttachmentDraftForForm(form);
  if (!draft) return;
  const uniqueFiles = dedupeQueuedFiles(files, draft.attachments);
  if (!uniqueFiles.length) return;
  const queued = uniqueFiles.map(localAttachmentFromFile);
  draft.attachments.push(...queued);
  patchWorkflowNodeDialogAttachments(form);
  queued.forEach((attachment, index) => {
    void uploadWorkflowNodeDialogFile(
      draft.threadId,
      draft.nodeId,
      attachment.id,
      uniqueFiles[index],
    );
  });
}

async function uploadWorkflowNodeDialogFile(
  threadId: string,
  nodeId: string,
  id: string,
  file: File,
) {
  const uploadFingerprint = queuedFileFingerprint(file);
  const updateAttachment = (
    update: (attachment: LocalAttachment) => LocalAttachment,
  ) => {
    const draft = workflowNodeDialogAttachmentDraft;
    if (draft?.threadId !== threadId || draft.nodeId !== nodeId) return false;
    let updated = false;
    draft.attachments = draft.attachments.map((attachment) => {
      if (!isQueuedUploadTarget(attachment, id, uploadFingerprint)) return attachment;
      updated = true;
      return update(attachment);
    });
    const form = root.querySelector<HTMLFormElement>("[data-workflow-node-edit-form]");
    if (updated && workflowNodeDialogAttachmentDraftForForm(form)) {
      patchWorkflowNodeDialogAttachments(form!);
    }
    return updated;
  };

  try {
    const bytes = await file.arrayBuffer();
    const uploaded = await api.uploadMaterialFile({
      name: file.name || "本地文件",
      mime: file.type || null,
      size: file.size,
      bytes,
      folder: "默认",
      purpose: "material",
    });
    const uploadedAttachment = uploaded?.attachment || {};
    const updated = updateAttachment((attachment) => ({
      ...attachment,
      uploadStatus: "uploaded",
      uploadError: null,
      name: uploadedAttachment.name || attachment.name,
      mime: uploadedAttachment.mime ?? attachment.mime,
      size: uploadedAttachment.size ?? uploaded?.size_bytes ?? attachment.size,
      object_key: uploadedAttachment.object_key ?? uploaded?.object_key ?? attachment.object_key,
      url: uploadedAttachment.url ?? uploaded?.url ?? attachment.url,
      material_id: uploadedAttachment.material_id ?? uploaded?.material?.id ?? attachment.material_id,
      url_expires_at: uploaded?.url_expires_at ?? attachment.url_expires_at,
    }));
    if (updated) mergeUploadedMaterial(uploaded?.material);
  } catch (error) {
    updateAttachment((attachment) => ({
      ...attachment,
      uploadStatus: "error",
      uploadError: uploadErrorMessage(error),
    }));
  }
}

function removeWorkflowNodeDialogAttachment(
  form: HTMLFormElement,
  attachmentId: string,
) {
  const draft = workflowNodeDialogAttachmentDraftForForm(form);
  if (!draft || !attachmentId) return;
  const target = draft.attachments.find((attachment) => attachment.id === attachmentId);
  if (target) revokeQueuedAttachmentUrls(target);
  draft.attachments = draft.attachments.filter(
    (attachment) => attachment.id !== attachmentId,
  );
  patchWorkflowNodeDialogAttachments(form);
}

async function openWorkflowNodeDialogAttachment(
  form: HTMLFormElement,
  attachmentId: string,
) {
  const draft = workflowNodeDialogAttachmentDraftForForm(form);
  const attachment = draft?.attachments.find((candidate) => candidate.id === attachmentId);
  if (!draft || !attachment) return;
  const localPath = attachmentLocalPath(attachment);
  if (!localPath) {
    showToast("这个附件没有本地路径，暂时无法直接打开。", 3200);
    return;
  }
  try {
    if (!api.openLocalFile) return;
    await api.openLocalFile({
      path: localPath,
      cwd: threadWorkspaceCwd(draft.threadId),
    });
  } catch (error) {
    showToast(`打开文件失败：${errorMessage(error)}`, 4200);
  }
}

function scrollWorkflowNodeAttachmentRail(
  form: HTMLFormElement,
  direction: "left" | "right",
) {
  const rail = form.querySelector<HTMLElement>(
    "[data-workflow-node-attachments]",
  );
  if (!rail) return;
  const distance = Math.max(rail.clientWidth * 0.72, 180);
  rail.scrollBy({
    left: direction === "left" ? -distance : distance,
    behavior: "smooth",
  });
  window.setTimeout(
    () => updateWorkflowNodeAttachmentScrollControls(form),
    220,
  );
}

function updateWorkflowNodeAttachmentScrollControls(form: HTMLFormElement) {
  const rail = form.querySelector<HTMLElement>(
    "[data-workflow-node-attachments]",
  );
  const leftButton = form.querySelector<HTMLButtonElement>(
    '[data-workflow-node-attachment-scroll="left"]',
  );
  const rightButton = form.querySelector<HTMLButtonElement>(
    '[data-workflow-node-attachment-scroll="right"]',
  );
  if (!rail || !leftButton || !rightButton) return;
  const maxScrollLeft = Math.max(0, rail.scrollWidth - rail.clientWidth);
  leftButton.hidden = rail.scrollLeft <= 1;
  rightButton.hidden = rail.scrollLeft >= maxScrollLeft - 1;
}

function bindWorkflowNodeDialogAttachmentEvents(form: HTMLFormElement) {
  const input = form.querySelector<HTMLInputElement>("[data-workflow-node-file-input]");
  const attachmentScroller = form.querySelector<HTMLElement>(
    "[data-workflow-node-attachments]",
  );
  const trigger = form.querySelector<HTMLButtonElement>(
    '[data-action="pick-workflow-node-files"]',
  );
  form
    .querySelectorAll<HTMLButtonElement>(
      "[data-workflow-node-attachment-scroll]",
    )
    .forEach((button) => {
      if (button.dataset.workflowNodeAttachmentScrollBound === "true") return;
      button.dataset.workflowNodeAttachmentScrollBound = "true";
      button.addEventListener("click", () => {
        scrollWorkflowNodeAttachmentRail(
          form,
          button.dataset.workflowNodeAttachmentScroll === "left"
            ? "left"
            : "right",
        );
      });
    });
  if (
    attachmentScroller
    && attachmentScroller.dataset.workflowNodeAttachmentScrollerBound !== "true"
  ) {
    attachmentScroller.dataset.workflowNodeAttachmentScrollerBound = "true";
    attachmentScroller.addEventListener(
      "scroll",
      () => updateWorkflowNodeAttachmentScrollControls(form),
    );
    attachmentScroller.addEventListener("wheel", (event) => {
      if (
        Math.abs(event.deltaY) <= Math.abs(event.deltaX)
        || attachmentScroller.scrollWidth <= attachmentScroller.clientWidth
      ) {
        return;
      }
      const maxScrollLeft = Math.max(
        0,
        attachmentScroller.scrollWidth - attachmentScroller.clientWidth,
      );
      const nextScrollLeft = Math.min(
        maxScrollLeft,
        Math.max(0, attachmentScroller.scrollLeft + event.deltaY),
      );
      if (nextScrollLeft === attachmentScroller.scrollLeft) return;
      event.preventDefault();
      attachmentScroller.scrollLeft = nextScrollLeft;
      updateWorkflowNodeAttachmentScrollControls(form);
    }, { passive: false });
    attachmentScroller.addEventListener("keydown", (event) => {
      if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
      event.preventDefault();
      scrollWorkflowNodeAttachmentRail(
        form,
        event.key === "ArrowRight" ? "right" : "left",
      );
    });
  }
  window.requestAnimationFrame(
    () => updateWorkflowNodeAttachmentScrollControls(form),
  );
  if (trigger && trigger.dataset.workflowNodeAttachmentBound !== "true") {
    trigger.dataset.workflowNodeAttachmentBound = "true";
    trigger.addEventListener("click", (event) => {
      event.preventDefault();
      input?.click();
    });
  }
  if (input && input.dataset.workflowNodeAttachmentBound !== "true") {
    input.dataset.workflowNodeAttachmentBound = "true";
    input.addEventListener("change", () => {
      const files = Array.from(input.files || []);
      input.value = "";
      queueWorkflowNodeDialogFiles(form, files);
    });
  }
  form
    .querySelectorAll<HTMLButtonElement>("[data-remove-workflow-node-attachment]")
    .forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        removeWorkflowNodeDialogAttachment(
          form,
          String(button.dataset.removeWorkflowNodeAttachment || ""),
        );
      });
    });
  form
    .querySelectorAll<HTMLButtonElement>("[data-open-workflow-node-attachment]")
    .forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        void openWorkflowNodeDialogAttachment(
          form,
          String(button.dataset.openWorkflowNodeAttachment || ""),
        );
      });
    });
}

function persistWorkflowNodeDialogAttachments(
  run: WorkflowCanvasRun,
  node: WorkflowCanvasNode,
  attachments: LocalAttachment[],
) {
  const previousSelection = node.contextSelection || {};
  const selectedUploadIds = [...new Set([
    ...(previousSelection.selectedUploadIds || []),
    ...attachments.map((attachment) => attachment.id),
  ])];
  const metadata = run.metadata || {};
  const attachmentRecords = new Map(
    (metadata.attachments || [])
      .filter((attachment) => attachment?.id)
      .map((attachment) => [String(attachment.id), attachment]),
  );
  const manifestRecords = new Map(
    (metadata.uploadManifest || [])
      .filter((attachment) => attachment?.id)
      .map((attachment) => [String(attachment.id), attachment]),
  );

  for (const attachment of attachments) {
    const kind = workflowNodeDialogAttachmentKind(attachment);
    const delivery = kind === "image" || kind === "video"
      ? "native_media"
      : "host_read_through";
    const localPath = attachmentLocalPath(attachment);
    attachmentRecords.set(attachment.id, {
      id: attachment.id,
      name: attachment.name,
      mime: attachment.mime || null,
      size: Math.max(0, Number(attachment.size) || 0),
      local_path: localPath || null,
      path: localPath || null,
      url: attachment.url || null,
      object_key: attachment.object_key || null,
      material_id: attachment.material_id || null,
      kind,
      delivery,
    });
    manifestRecords.set(attachment.id, {
      id: attachment.id,
      name: attachment.name,
      mime: attachment.mime || null,
      kind,
      delivery,
      path: localPath || null,
    });
  }

  run.metadata = {
    ...metadata,
    attachments: [...attachmentRecords.values()],
    uploadManifest: [...manifestRecords.values()],
  };

  const scope = new Set(previousSelection.scope || []);
  const hasHostReadAttachment = attachments.some((attachment) => (
    workflowNodeDialogAttachmentKind(attachment) !== "image"
    && workflowNodeDialogAttachmentKind(attachment) !== "video"
  ));
  if (hasHostReadAttachment) scope.add("uploads");
  node.contextSelection = {
    ...previousSelection,
    protocolVersion: 1,
    needsLocalFiles: previousSelection.needsLocalFiles === true
      || scope.has("current_group")
      || hasHostReadAttachment,
    scope: [...scope],
    selectedUploadIds,
    source: "user_node_editor",
    rationale: previousSelection.rationale
      || (selectedUploadIds.length ? "用户在节点编辑器中显式添加资料" : ""),
  };
  node.attachmentRefs = [...new Map([
    ...(node.attachmentRefs || []),
    ...attachments.map((attachment) => ({
      id: attachment.id,
      name: attachment.name,
      mime: attachment.mime || null,
    })),
  ].map((reference) => [String(reference?.id || reference || ""), reference])).values()]
    .filter((reference) => String(reference?.id || reference || ""));
}

function workflowNodeEditString(formData: FormData, name: string) {
  return String(formData.get(name) || "").trim();
}

function composeWorkflowControlledPrompt({
  input,
  task,
  output,
}: {
  input: string;
  task: string;
  output: string;
}) {
  return [
    "输入：",
    input.trim(),
    "",
    "任务：",
    task.trim(),
    "",
    "输出：",
    output.trim(),
  ].join("\n").trimEnd();
}

function workflowNodeEditLines(formData: FormData, name: string) {
  return workflowNodeEditString(formData, name)
    .split(/\r?\n/)
    .map((value) => value.trim())
    .filter(Boolean);
}

function workflowNodePromptSkillBindings(
  prompt: string,
  node: WorkflowCanvasNode,
) {
  const availableSkills = new Map<string, WorkflowNodeDialogSkill>();
  for (const skill of workflowCanvasDialogSkills()) {
    availableSkills.set(skill.id, skill);
  }
  for (const binding of node.skillBindings || []) {
    const id = firstString(binding.id, binding.name);
    if (!id || availableSkills.has(id)) continue;
    availableSkills.set(id, {
      id,
      label: firstString(binding.name, binding.id) || id,
    });
  }
  const previousBindings = new Map(
    (node.skillBindings || [])
      .map((binding) => [firstString(binding.id, binding.name), binding] as const)
      .filter(([id]) => Boolean(id)),
  );
  const normalizedPrompt = prompt.toLocaleLowerCase("zh-CN");
  return [...availableSkills.values()].flatMap((skill) => {
    const mentioned = [skill.label, skill.id]
      .map((value) => String(value || "").trim())
      .filter(Boolean)
      .some((value) => normalizedPrompt.includes(`@${value.toLocaleLowerCase("zh-CN")}`));
    if (!mentioned) return [];
    const previous = previousBindings.get(skill.id);
    return [{
      id: skill.id,
      name: skill.label,
      version: previous?.version || null,
      required: true,
    }];
  });
}

type WorkflowNodeMentionSubmenu = "favorites" | "skills";

function workflowNodeMentionPopover(
  form: HTMLFormElement | null | undefined,
) {
  return form?.querySelector<HTMLElement>(
    "[data-workflow-node-mention-popover]",
  ) || null;
}

function workflowNodeMentionRootOptions(
  form: HTMLFormElement | null | undefined,
) {
  if (!form) return [];
  return [
    ...form.querySelectorAll<HTMLButtonElement>(
      "[data-workflow-node-mention-root]",
    ),
  ];
}

function workflowNodeMentionOptions(
  form: HTMLFormElement | null | undefined,
  submenu?: WorkflowNodeMentionSubmenu | null,
) {
  if (!form) return [];
  const activeSubmenu =
    submenu
    || (workflowNodeMentionPopover(form)?.dataset
      .workflowNodeActiveSubmenu as WorkflowNodeMentionSubmenu | undefined);
  if (!activeSubmenu) return [];
  return [
    ...form.querySelectorAll<HTMLElement>(
      `[data-workflow-node-mention-submenu="${activeSubmenu}"] [role="option"]`,
    ),
  ];
}

function workflowNodeMentionTokens(form: HTMLFormElement) {
  const tokens = new Set<string>();
  for (const option of workflowNodeMentionOptions(form, "skills")) {
    const label = String(option.dataset.workflowNodeSkillLabel || "").trim();
    const id = String(option.dataset.workflowNodeSkillId || "").trim();
    if (label) tokens.add(`@${label}`);
    if (id) tokens.add(`@${id}`);
  }
  return sortComposerMentionTokens([...tokens]);
}

function workflowNodeMentionInputs(form: HTMLFormElement) {
  return [
    ...form.querySelectorAll<HTMLTextAreaElement>(
      "[data-workflow-node-mention-input]",
    ),
  ];
}

function activeWorkflowNodeMentionInput(form: HTMLFormElement) {
  const popover = workflowNodeMentionPopover(form);
  const fieldName = String(
    popover?.dataset.workflowNodeMentionField || "",
  );
  return workflowNodeMentionInputs(form).find(
    (input) => input.name === fieldName,
  ) || null;
}

function workflowNodeMentionCaretAnchor(
  input: HTMLTextAreaElement,
  triggerIndex: number,
) {
  const inputRect = input.getBoundingClientRect();
  const computed = window.getComputedStyle(input);
  const mirror = document.createElement("div");
  const copiedProperties = [
    "box-sizing",
    "padding-top",
    "padding-right",
    "padding-bottom",
    "padding-left",
    "border-top-width",
    "border-right-width",
    "border-bottom-width",
    "border-left-width",
    "font-family",
    "font-size",
    "font-style",
    "font-variant",
    "font-weight",
    "letter-spacing",
    "line-height",
    "text-align",
    "text-indent",
    "text-transform",
    "tab-size",
    "word-spacing",
    "white-space",
    "overflow-wrap",
    "word-break",
  ];
  mirror.style.position = "fixed";
  mirror.style.left = "0";
  mirror.style.top = "0";
  mirror.style.width = `${inputRect.width}px`;
  mirror.style.height = "auto";
  mirror.style.overflow = "hidden";
  mirror.style.visibility = "hidden";
  mirror.style.pointerEvents = "none";
  mirror.style.zIndex = "-1";
  for (const property of copiedProperties) {
    mirror.style.setProperty(property, computed.getPropertyValue(property));
  }
  mirror.style.width = `${inputRect.width}px`;
  mirror.append(document.createTextNode(
    input.value.slice(0, Math.max(0, triggerIndex)),
  ));
  const marker = document.createElement("span");
  marker.textContent = input.value.slice(triggerIndex, triggerIndex + 1) || "@";
  mirror.append(marker);
  document.body.append(mirror);
  const mirrorRect = mirror.getBoundingClientRect();
  const markerRect = marker.getBoundingClientRect();
  mirror.remove();
  return {
    left:
      inputRect.left + markerRect.left - mirrorRect.left - input.scrollLeft,
    top:
      inputRect.top + markerRect.bottom - mirrorRect.top - input.scrollTop,
  };
}

function placeWorkflowNodeMentionMenu(
  form: HTMLFormElement,
  input: HTMLTextAreaElement,
  triggerIndex: number,
) {
  const popover = workflowNodeMentionPopover(form);
  const control = input.closest<HTMLElement>(".workflow-node-prompt-control");
  if (!popover || !control) return;
  const anchor = workflowNodeMentionCaretAnchor(input, triggerIndex);
  const controlRect = control.getBoundingClientRect();
  const desiredLeft =
    anchor.left - controlRect.left - control.clientLeft;
  const maxLeft = Math.max(0, control.clientWidth - popover.offsetWidth);
  popover.style.left = `${Math.round(
    Math.min(Math.max(0, desiredLeft), maxLeft),
  )}px`;
  popover.style.top = `${Math.round(
    anchor.top - controlRect.top - control.clientTop + 4,
  )}px`;
  popover.style.bottom = "auto";
}

function placeWorkflowNodeMentionSubmenu(
  form: HTMLFormElement,
  submenu: HTMLElement,
) {
  const popover = workflowNodeMentionPopover(form);
  const control = popover?.closest<HTMLElement>(
    ".workflow-node-prompt-control",
  );
  const dialog = form.closest<HTMLElement>(".workflow-node-edit-dialog");
  if (!popover || !control || !dialog) return;

  const gap = 3;
  const boundaryPadding = 8;
  const dialogRect = dialog.getBoundingClientRect();
  const popoverRect = popover.getBoundingClientRect();
  const maximumSubmenuWidth = Math.max(
    140,
    Math.floor(
      dialogRect.width
      - boundaryPadding * 2
      - popoverRect.width
      - gap,
    ),
  );
  submenu.style.maxWidth = `${maximumSubmenuWidth}px`;

  const submenuWidth = submenu.getBoundingClientRect().width;
  const rightOverflow = Math.max(
    0,
    popoverRect.right
      + gap
      + submenuWidth
      - (dialogRect.right - boundaryPadding),
  );
  if (!rightOverflow) return;

  const controlRect = control.getBoundingClientRect();
  const minimumLeft = dialogRect.left + boundaryPadding;
  const nextViewportLeft = Math.max(
    minimumLeft,
    popoverRect.left - rightOverflow,
  );
  popover.style.left = `${Math.round(
    nextViewportLeft - controlRect.left - control.clientLeft,
  )}px`;
}

function renderWorkflowNodeMentionHighlights(
  text: string,
  tokens: string[],
) {
  if (!text || !tokens.length) return escapeHtml(text);
  const mentionRanges = composerMentionTokenRanges(text, tokens);
  const boundaries = [
    ...new Set([
      0,
      text.length,
      ...mentionRanges.flatMap((range) => [range.start, range.end]),
    ]),
  ].sort((left, right) => left - right);
  let html = "";
  for (let index = 0; index < boundaries.length - 1; index += 1) {
    const start = boundaries[index];
    const end = boundaries[index + 1];
    if (end <= start) continue;
    const segment = escapeHtml(text.slice(start, end));
    const isMention = mentionRanges.some(
      (range) => range.start <= start && range.end >= end,
    );
    html += isMention ? `<mark>${segment}</mark>` : segment;
  }
  return text.endsWith("\n") ? `${html} ` : html;
}

function syncWorkflowNodeMentionHighlights(form: HTMLFormElement) {
  const input = form.querySelector<HTMLTextAreaElement>(
    "[data-workflow-node-prompt]",
  );
  const highlight = form.querySelector<HTMLElement>(
    "[data-workflow-node-prompt-highlight]",
  );
  if (!input || !highlight) return;
  highlight.innerHTML = renderWorkflowNodeMentionHighlights(
    input.value,
    workflowNodeMentionTokens(form),
  );
  highlight.scrollTop = input.scrollTop;
  highlight.scrollLeft = input.scrollLeft;
}

function handleWorkflowNodeSkillTokenDeleteKeydown(
  form: HTMLFormElement,
  event: KeyboardEvent,
) {
  if (event.key !== "Backspace" && event.key !== "Delete") return false;
  const input =
    event.currentTarget instanceof HTMLTextAreaElement
      ? event.currentTarget
      : null;
  if (!input || input.disabled || input.readOnly || event.isComposing) {
    return false;
  }
  const range = composerSkillTokenDeleteRange(
    input.value,
    input.selectionStart ?? 0,
    input.selectionEnd ?? input.selectionStart ?? 0,
    event.key,
    workflowNodeMentionTokens(form),
  );
  if (!range) return false;
  event.preventDefault();
  input.value =
    `${input.value.slice(0, range.start)}${input.value.slice(range.end)}`;
  input.setSelectionRange(range.start, range.start);
  input.dispatchEvent(new Event("input", { bubbles: true }));
  return true;
}

function closeWorkflowNodeMentionMenu(form: HTMLFormElement) {
  const popover = workflowNodeMentionPopover(form);
  if (!popover) return;
  popover.classList.add("hidden");
  delete popover.dataset.workflowNodeActiveSubmenu;
  popover
    .querySelectorAll<HTMLElement>(".active")
    .forEach((element) => element.classList.remove("active"));
  popover
    .querySelectorAll<HTMLElement>("[data-workflow-node-mention-submenu]")
    .forEach((submenu) => submenu.classList.add("hidden"));
  workflowNodeMentionRootOptions(form).forEach((option, index) => {
    option.classList.toggle("active", index === 0);
    option.setAttribute("aria-expanded", "false");
  });
}

function filterWorkflowNodeMentionSubmenu(
  form: HTMLFormElement,
  submenu: WorkflowNodeMentionSubmenu,
  query: string,
) {
  const normalizedQuery = query.trim().toLocaleLowerCase("zh-CN");
  const options = workflowNodeMentionOptions(form, submenu);
  let visibleCount = 0;
  for (const option of options) {
    const searchText = String(
      option.dataset.workflowNodeMentionSearch || "",
    );
    const visible = !normalizedQuery || searchText.includes(normalizedQuery);
    option.hidden = !visible;
    option.classList.remove("active");
    if (visible) visibleCount += 1;
  }
  const empty = form.querySelector<HTMLElement>(
    `[data-workflow-node-mention-empty="${submenu}"]`,
  );
  empty?.classList.toggle("hidden", options.length === 0 || visibleCount > 0);
  options.find((option) => !option.hidden)?.classList.add("active");
}

function activateWorkflowNodeMentionRoot(
  form: HTMLFormElement,
  option: HTMLButtonElement,
) {
  for (const candidate of workflowNodeMentionRootOptions(form)) {
    candidate.classList.toggle("active", candidate === option);
  }
}

function openWorkflowNodeMentionSubmenu(
  form: HTMLFormElement,
  submenu: WorkflowNodeMentionSubmenu,
  options: { focusSearch?: boolean } = {},
) {
  const popover = workflowNodeMentionPopover(form);
  if (!popover) return;
  popover.dataset.workflowNodeActiveSubmenu = submenu;
  workflowNodeMentionRootOptions(form).forEach((option) => {
    const active = option.dataset.workflowNodeMentionRoot === submenu;
    option.classList.toggle("active", active);
    option.setAttribute("aria-expanded", active ? "true" : "false");
  });
  popover
    .querySelectorAll<HTMLElement>("[data-workflow-node-mention-submenu]")
    .forEach((panel) => {
      panel.classList.toggle(
        "hidden",
        panel.dataset.workflowNodeMentionSubmenu !== submenu,
      );
    });
  const activePanel = form.querySelector<HTMLElement>(
    `[data-workflow-node-mention-submenu="${submenu}"]`,
  );
  if (activePanel) placeWorkflowNodeMentionSubmenu(form, activePanel);
  const search = form.querySelector<HTMLInputElement>(
    `[data-workflow-node-mention-search-input="${submenu}"]`,
  );
  filterWorkflowNodeMentionSubmenu(form, submenu, search?.value || "");
  if (options.focusSearch) {
    search?.focus({ preventScroll: true });
    search?.select();
  }
}

function syncWorkflowNodeMentionMenu(
  form: HTMLFormElement,
  input: HTMLTextAreaElement,
) {
  const popover = workflowNodeMentionPopover(form);
  if (!input || !popover) return;
  syncWorkflowNodeMentionHighlights(form);
  const selectionStart = input.selectionStart ?? input.value.length;
  const match = findComposerMentionMatch(input.value, selectionStart);
  if (!match) {
    closeWorkflowNodeMentionMenu(form);
    return;
  }

  const wasHidden = popover.classList.contains("hidden");
  popover.dataset.workflowNodeMentionField = input.name;
  popover.dataset.workflowNodeMentionStart = String(match.start);
  popover.dataset.workflowNodeMentionEnd = String(match.end);
  popover.classList.remove("hidden");
  placeWorkflowNodeMentionMenu(form, input, match.start);
  if (wasHidden) {
    delete popover.dataset.workflowNodeActiveSubmenu;
    workflowNodeMentionRootOptions(form).forEach((option, index) => {
      option.classList.toggle("active", index === 0);
      option.setAttribute("aria-expanded", "false");
    });
  }
  const activeSubmenu = popover.dataset
    .workflowNodeActiveSubmenu as WorkflowNodeMentionSubmenu | undefined;
  const activePanel = activeSubmenu
    ? form.querySelector<HTMLElement>(
        `[data-workflow-node-mention-submenu="${activeSubmenu}"]`,
      )
    : null;
  if (activePanel && !activePanel.classList.contains("hidden")) {
    placeWorkflowNodeMentionSubmenu(form, activePanel);
  }

  const normalizedPrompt = workflowNodeMentionInputs(form)
    .map((candidate) => candidate.value)
    .join("\n")
    .toLocaleLowerCase("zh-CN");
  for (const option of workflowNodeMentionOptions(form, "skills")) {
    const label = String(option.dataset.workflowNodeSkillLabel || "");
    const id = String(option.dataset.workflowNodeSkillId || "");
    const selected = [label, id]
      .filter(Boolean)
      .some((value) =>
        normalizedPrompt.includes(`@${value.toLocaleLowerCase("zh-CN")}`)
      );
    option.classList.toggle("selected", selected);
    option.setAttribute("aria-selected", selected ? "true" : "false");
    option.querySelector<HTMLElement>("i")?.remove();
    if (selected) {
      option.insertAdjacentHTML(
        "beforeend",
        '<i aria-hidden="true">已使用</i>',
      );
    }
  }
}

function replaceWorkflowNodeMention(
  form: HTMLFormElement,
  insertedText: string,
) {
  const input = activeWorkflowNodeMentionInput(form);
  const popover = workflowNodeMentionPopover(form);
  if (!input || !popover || !insertedText) return;
  const selectionStart = input.selectionStart ?? input.value.length;
  const match = findComposerMentionMatch(input.value, selectionStart);
  const start = match?.start
    ?? Number(popover.dataset.workflowNodeMentionStart || selectionStart);
  const end = match?.end
    ?? Number(popover.dataset.workflowNodeMentionEnd || selectionStart);
  const afterSelection = input.value.slice(end);
  const leadingSpacer = composerMentionLeadingSpacer(input.value, start);
  const trailingSpacer = composerMentionTrailingSpacer(afterSelection);
  const nextValue =
    `${input.value.slice(0, start)}${leadingSpacer}${insertedText}`
    + `${trailingSpacer}${afterSelection}`;
  const nextCursor =
    start + leadingSpacer.length + insertedText.length + trailingSpacer.length;

  input.value = nextValue;
  input.focus({ preventScroll: true });
  input.setSelectionRange(nextCursor, nextCursor);
  input.dispatchEvent(new Event("input", { bubbles: true }));
  closeWorkflowNodeMentionMenu(form);
}

function applyWorkflowNodeMentionOption(
  form: HTMLFormElement,
  option: HTMLElement,
) {
  const favoriteContent = String(
    option.dataset.workflowNodeFavoriteContent || "",
  ).trim();
  if (favoriteContent) {
    replaceWorkflowNodeMention(form, favoriteContent);
    return;
  }
  const skillLabel = String(
    option.dataset.workflowNodeSkillLabel || "",
  ).trim();
  if (skillLabel) replaceWorkflowNodeMention(form, `@${skillLabel}`);
}

function moveWorkflowNodeMentionSelection(
  form: HTMLFormElement,
  direction: 1 | -1,
) {
  const popover = workflowNodeMentionPopover(form);
  const submenu = popover?.dataset
    .workflowNodeActiveSubmenu as WorkflowNodeMentionSubmenu | undefined;
  const options = submenu
    ? workflowNodeMentionOptions(form, submenu).filter(
        (option) => !option.hidden,
      )
    : workflowNodeMentionRootOptions(form);
  if (!options.length) return;
  const currentIndex = options.findIndex((option) =>
    option.classList.contains("active")
  );
  const nextIndex = currentIndex < 0
    ? 0
    : (currentIndex + direction + options.length) % options.length;
  options.forEach((option, index) => {
    option.classList.toggle("active", index === nextIndex);
  });
  options[nextIndex]?.scrollIntoView({ block: "nearest" });
}

function handleWorkflowNodeMentionKeydown(
  form: HTMLFormElement,
  event: KeyboardEvent,
) {
  const popover = workflowNodeMentionPopover(form);
  if (!popover || popover.classList.contains("hidden")) return false;
  const submenu = popover.dataset
    .workflowNodeActiveSubmenu as WorkflowNodeMentionSubmenu | undefined;
  if (event.key === "Escape") {
    event.preventDefault();
    closeWorkflowNodeMentionMenu(form);
    return true;
  }
  if (event.key === "ArrowDown" || event.key === "ArrowUp") {
    event.preventDefault();
    moveWorkflowNodeMentionSelection(
      form,
      event.key === "ArrowDown" ? 1 : -1,
    );
    return true;
  }
  if (!submenu && ["ArrowRight", "Enter", "Tab"].includes(event.key)) {
    const activeRoot = workflowNodeMentionRootOptions(form).find((option) =>
      option.classList.contains("active")
    );
    const nextSubmenu = activeRoot?.dataset
      .workflowNodeMentionRoot as WorkflowNodeMentionSubmenu | undefined;
    if (!nextSubmenu) return false;
    event.preventDefault();
    openWorkflowNodeMentionSubmenu(form, nextSubmenu, { focusSearch: true });
    return true;
  }
  if (submenu && ["Enter", "Tab"].includes(event.key)) {
    const activeOption = workflowNodeMentionOptions(form, submenu).find(
      (option) => !option.hidden && option.classList.contains("active"),
    );
    if (!activeOption) return false;
    event.preventDefault();
    applyWorkflowNodeMentionOption(form, activeOption);
    return true;
  }
  if (submenu && event.key === "ArrowLeft") {
    event.preventDefault();
    delete popover.dataset.workflowNodeActiveSubmenu;
    popover
      .querySelectorAll<HTMLElement>("[data-workflow-node-mention-submenu]")
      .forEach((panel) => panel.classList.add("hidden"));
    workflowNodeMentionRootOptions(form).forEach((option) => {
      option.setAttribute("aria-expanded", "false");
    });
    activeWorkflowNodeMentionInput(form)?.focus({ preventScroll: true });
    return true;
  }
  return false;
}

function placeWorkflowNodePickerMenu(
  picker: HTMLElement,
  menu: HTMLElement,
  trigger: HTMLElement,
  gap: number,
) {
  picker.classList.remove("open-upward");
  menu.style.removeProperty("--workflow-node-menu-available-height");
  const dialog = picker.closest<HTMLElement>(".workflow-node-edit-dialog");
  const dialogRect = dialog?.getBoundingClientRect();
  const triggerRect = trigger.getBoundingClientRect();
  const boundaryTop = Math.max(0, dialogRect?.top ?? 0);
  const boundaryBottom = Math.min(
    window.innerHeight,
    dialogRect?.bottom ?? window.innerHeight,
  );
  const availableAbove = Math.max(0, triggerRect.top - boundaryTop - gap);
  const availableBelow = Math.max(0, boundaryBottom - triggerRect.bottom - gap);
  const openUpward =
    menu.scrollHeight > availableBelow && availableAbove > availableBelow;
  const availableHeight = openUpward ? availableAbove : availableBelow;
  picker.classList.toggle("open-upward", openUpward);
  menu.style.setProperty(
    "--workflow-node-menu-available-height",
    `${Math.floor(availableHeight)}px`,
  );
}

function closeWorkflowNodeExecutorMenu(form: HTMLFormElement) {
  const picker = form.querySelector<HTMLElement>(
    ".workflow-node-executor-picker",
  );
  const menu = form.querySelector<HTMLElement>(
    "[data-workflow-node-executor-menu]",
  );
  const trigger = form.querySelector<HTMLButtonElement>(
    '[data-action="toggle-workflow-node-executor-menu"]',
  );
  picker?.classList.remove("open", "open-upward");
  menu?.classList.add("hidden");
  menu?.style.removeProperty("--workflow-node-menu-available-height");
  trigger?.setAttribute("aria-expanded", "false");
}

function toggleWorkflowNodeExecutorMenu(form: HTMLFormElement) {
  const picker = form.querySelector<HTMLElement>(
    ".workflow-node-executor-picker",
  );
  const menu = form.querySelector<HTMLElement>(
    "[data-workflow-node-executor-menu]",
  );
  const trigger = form.querySelector<HTMLButtonElement>(
    '[data-action="toggle-workflow-node-executor-menu"]',
  );
  if (!picker || !menu || !trigger) return;
  const nextOpen = menu.classList.contains("hidden");
  picker.classList.toggle("open", nextOpen);
  menu.classList.toggle("hidden", !nextOpen);
  trigger.setAttribute("aria-expanded", nextOpen ? "true" : "false");
  if (nextOpen) {
    placeWorkflowNodePickerMenu(picker, menu, trigger, 8);
    menu
      .querySelector<HTMLButtonElement>(
        "[data-workflow-node-executor-value].active",
      )
      ?.focus({ preventScroll: true });
  }
}

function syncWorkflowNodeEditorAvatar(
  form: HTMLFormElement,
  option: HTMLOptionElement | HTMLButtonElement,
) {
  const requestedLogoKey = String(
    option.dataset.workflowModelLogo || "",
  ).trim() as keyof typeof WORKFLOW_NODE_LOGO_URLS;
  const logoKey = Object.prototype.hasOwnProperty.call(
    WORKFLOW_NODE_LOGO_URLS,
    requestedLogoKey,
  )
    ? requestedLogoKey
    : "haolo";
  const avatar = form.querySelector<HTMLElement>(
    "[data-workflow-node-edit-avatar]",
  );
  const image = avatar?.querySelector<HTMLImageElement>("img");
  if (!avatar || !image) return;
  [...avatar.classList]
    .filter((className) => className.startsWith("provider-"))
    .forEach((className) => avatar.classList.remove(className));
  avatar.classList.add(`provider-${logoKey}`);
  avatar.dataset.workflowModelLogo = logoKey;
  image.src = WORKFLOW_NODE_LOGO_URLS[logoKey];
  image.classList.toggle(
    "dark-theme-white-agent-icon",
    logoKey === "codex",
  );
}

function selectWorkflowNodeExecutor(
  form: HTMLFormElement,
  option: HTMLButtonElement,
) {
  const value = String(
    option.dataset.workflowNodeExecutorValue || "",
  ).trim();
  const select = form.querySelector<HTMLSelectElement>(
    'select[name="executor"]',
  );
  const trigger = form.querySelector<HTMLButtonElement>(
    '[data-action="toggle-workflow-node-executor-menu"]',
  );
  if (!select || !trigger || !value) return;
  select.value = value;
  select.dispatchEvent(new Event("change", { bubbles: true }));
  form
    .querySelectorAll<HTMLButtonElement>(
      "[data-workflow-node-executor-value]",
    )
    .forEach((candidate) => {
      const active = candidate === option;
      candidate.classList.toggle("active", active);
      candidate.setAttribute("aria-checked", active ? "true" : "false");
    });
  const label = trigger.querySelector<HTMLElement>("span");
  const optionLabel = option.querySelector<HTMLElement>(
    ".composer-model-option-name",
  );
  if (label && optionLabel) label.textContent = optionLabel.textContent || "";
  syncWorkflowNodeEditorAvatar(form, option);
  closeWorkflowNodeExecutorMenu(form);
  trigger.focus({ preventScroll: true });
}

async function updateWorkflowNodeRevisionDraft(form: HTMLFormElement) {
  const threadId = String(form.dataset.workflowThreadId || "").trim();
  const nodeId = String(form.dataset.workflowNodeId || "").trim();
  const storedDraft = workflowCanvasDraftsByThreadId.get(threadId);
  const draft = storedDraft
    ? (typeof structuredClone === "function"
        ? structuredClone(storedDraft)
        : JSON.parse(JSON.stringify(storedDraft)) as WorkflowCanvasRun)
    : null;
  const pendingInsertion = workflowCanvasPendingNodeInsertion?.threadId === threadId
    && workflowCanvasPendingNodeInsertion.node.id === nodeId
    ? workflowCanvasPendingNodeInsertion
    : null;
  const pendingNode = pendingInsertion?.node
    ? (typeof structuredClone === "function"
        ? structuredClone(pendingInsertion.node)
        : JSON.parse(JSON.stringify(pendingInsertion.node)) as WorkflowCanvasNode)
    : null;
  const node = pendingNode || draft?.nodes.find((candidate) => candidate.id === nodeId);
  if (
    !draft
    || !node
    || (pendingInsertion && pendingInsertion.runId !== draft.id)
  ) {
    showToast("节点草稿已失效，请关闭后重新打开节点编辑器", 2800);
    return false;
  }
  const attachmentDraft = workflowNodeDialogAttachmentDraftForForm(form);
  if (attachmentDraft?.attachments.some((attachment) => attachment.uploadStatus === "uploading")) {
    showToast("请等待附件上传完成后再保存", 2400);
    return false;
  }
  if (attachmentDraft?.attachments.some((attachment) => attachment.uploadStatus === "error")) {
    showToast("有附件上传失败，请移除后重新添加", 2800);
    return false;
  }
  const formData = new FormData(form);
  const inputDefinition = workflowNodeEditString(formData, "inputDefinition");
  const taskDefinition = workflowNodeEditString(formData, "taskDefinition");
  const outputDefinition = workflowNodeEditString(formData, "outputDefinition");
  const prompt = composeWorkflowControlledPrompt({
    input: inputDefinition,
    task: taskDefinition,
    output: outputDefinition,
  });
  if ((node.kind === "model" || node.kind === "agent") && !taskDefinition) {
    showToast("请完整填写节点的任务", 2400);
    return false;
  }
  if (!outputDefinition || (!(node.dependsOn || []).length && !inputDefinition)) {
    showToast("请完整说明节点的输入、任务和输出", 2800);
    return false;
  }

  const skillBindings = workflowNodePromptSkillBindings(prompt, node);
  const selectedExecutor = workflowNodeEditString(formData, "executor");
  if ((node.kind === "model" || node.kind === "agent") && !selectedExecutor) {
    showToast("当前没有可用的执行模型", 2800);
    return false;
  }
  const [selectedExecutorType = "external_model"] = selectedExecutor.split("|");
  if (skillBindings.length && selectedExecutorType !== "codex_subagent") {
    showToast("@Skill 需要由 Haolo 子 Agent 执行，请先把执行者切换为 Haolo Agent", 3600);
    return false;
  }

  node.prompt = prompt;
  node.joinPolicy = { mode: "all_required" };
  node.outputContract = null;
  node.acceptance = [];
  node.skillBindings = skillBindings;
  if (attachmentDraft) {
    persistWorkflowNodeDialogAttachments(
      draft,
      node,
      attachmentDraft.attachments,
    );
  }

  if (node.kind === "model" || node.kind === "agent") {
    const [executorType = "external_model", provider = "", model = ""] =
      selectedExecutor.split("|");
    node.executorType = executorType;
    node.kind = executorType === "codex_subagent" ? "agent" : "model";
    node.provider = provider || null;
    node.model = model || null;
    const nextPrimary = { executorType, provider: provider || null, model: model || null };
    const remainingCandidates = (node.executorCandidates || []).filter((candidate) => (
      `${candidate.executorType || node.executorType}|${candidate.provider || ""}|${candidate.model || ""}`
      !== `${executorType}|${provider}|${model}`
    ));
    node.executorCandidates = executorType === "codex_subagent"
      ? [nextPrimary]
      : [nextPrimary, ...remainingCandidates.filter((candidate) => (
          (candidate.executorType || "external_model") === "external_model"
        ))];
  }

  let desiredDraft = draft;
  let desiredLayout = workflowCanvasLayoutSnapshotForRun(threadId, draft.id)
    || captureWorkflowCanvasLayout(draft);
  if (pendingInsertion) {
    desiredDraft = insertWorkflowCanvasNode(
      draft,
      node,
      pendingInsertion.target,
      desiredLayout,
    );
    desiredLayout = insertWorkflowCanvasNodeIntoLayoutSnapshot(
      desiredLayout,
      desiredDraft,
      node.id,
      pendingInsertion.target,
      pendingInsertion.point,
      false,
      pendingInsertion.canvasWidth,
    );
  }
  if (!api.compileWorkflowRevisionNode) {
    showToast("当前桌面运行时不支持节点语义编译，请更新客户端后重试", 3200);
    return false;
  }
  try {
    const envelope = await ensurePersistedWorkflowRevisionDraft(threadId);
    if (!envelope) throw new Error("工作流修订草稿尚未准备好");
    const compiled = await api.compileWorkflowRevisionNode({
      draftId: envelope.draft.id,
      baseRevision: envelope.draft.revision,
      nodeId,
      prompt,
      patch: workflowRevisionNodePayload(node),
      definition: {
        nodes: workflowRevisionDefinitionNodes(desiredDraft),
        resources: workflowRevisionResources(desiredDraft),
        entryBindings: workflowRevisionEntryBindings(desiredDraft, desiredLayout),
      },
      layout: desiredLayout as unknown as Record<string, unknown>,
      cwd: threadWorkspaceCwd(threadId),
      commandId: globalThis.crypto?.randomUUID?.()
        || `workflow-node-contract-${Date.now()}-${Math.random()}`,
    });
    const applied = applyWorkflowRevisionEnvelope(threadId, compiled);
    const dirtyNodes = workflowCanvasDirtyNodeIdsByThreadId.get(threadId) || new Set<string>();
    dirtyNodes.add(nodeId);
    workflowCanvasDirtyNodeIdsByThreadId.set(threadId, dirtyNodes);
    if (pendingInsertion) {
      workflowCanvasPendingNodeInsertion = null;
      if (applied && state.activeView === "chat" && state.currentThreadId === threadId) {
        maybeAutoCollapseLeftPanelForWorkflow(applied);
      }
      return `${pendingInsertion.zoneLabel}：已增加${node.kind === "agent" ? "智能体" : "模型"}节点`;
    }
    return "节点契约已由 Haolo 编译并保存";
  } catch (error) {
    showToast(errorMessage(error), 4800);
    return false;
  }
}

