function composerQuotePreviewText(quote: ComposerQuotePayload) {
  return (quote.text || composerQuoteAttachmentSummary(quote.attachments) || "")
    .replace(/\s+/g, " ")
    .trim();
}

function renderComposerSubmitButton(thread: ConversationSummary) {
  const threadBusy = isComposerThreadBusy(thread.id);
  const submitAction = threadBusy
    ? composerSubmitActionForThread(thread.id)
    : "send";
  const voiceInputIdle = state.voiceInput.status === "idle";
  if (
    threadBusy &&
    submitAction === "supplement" &&
    shouldRenderConversationSupplementButton(thread.id)
  ) {
    const title = "\u8865\u5145\u4f1a\u8bdd";
    return `<button class="send-button conversation-supplement-button" type="submit" data-action="send-conversation-supplement" ${canSendConversationSupplement(thread.id) && voiceInputIdle ? "" : "disabled"} title="${title}" aria-label="${title}"><img src="${escapeAttr(INSERT_CONVERSATION_QUOTE_ICON_URL)}" alt="" draggable="false" /></button>`;
  }
  if (threadBusy && submitAction === "interrupt") {
    const title = localGroupChatBusyThreadIds.has(thread.id)
      ? "停止全部回应"
      : "\u505c\u6b62";
    return `<button class="send-button stop-button" type="submit" data-action="interrupt-turn" ${canInterruptThread(thread.id) ? "" : "disabled"} title="${title}" aria-label="${title}"><span class="stop-button-square" aria-hidden="true"></span></button>`;
  }
  if (submitAction === "send") {
    const title = "\u53d1\u9001";
    return `<button class="send-button" type="submit" ${canSendComposer(thread.id) && voiceInputIdle ? "" : "disabled"} title="${title}" aria-label="${title}"><svg viewBox="0 0 24 24" aria-hidden="true">
          <path d="M12 19V5"></path>
          <path d="m5 12 7-7 7 7"></path>
        </svg></button>`;
  }
  const interruptDisabled = threadBusy && !canInterruptThread(thread.id);
  const sendingDisabled = threadBusy
    ? interruptDisabled
    : !canSendComposer(thread.id) || !voiceInputIdle;
  const buttonAction = threadBusy ? ` data-action="interrupt-turn"` : "";
  const buttonClass = threadBusy ? "send-button stop-button" : "send-button";
  const buttonTitle = threadBusy ? "停止" : "发送";
  const buttonIcon = threadBusy
    ? `<span class="stop-button-square" aria-hidden="true"></span>`
    : `<svg viewBox="0 0 24 24" aria-hidden="true">
          <path d="M12 19V5"></path>
          <path d="m5 12 7-7 7 7"></path>
        </svg>`;
  return `<button class="${buttonClass}" type="submit"${buttonAction} ${sendingDisabled ? "disabled" : ""} title="${buttonTitle}" aria-label="${buttonTitle}">${buttonIcon}</button>`;
}

function renderVoiceInputButton() {
  const status = state.voiceInput.status;
  const title =
    status === "recording"
      ? "\u505c\u6b62\u5f55\u97f3"
      : status === "transcribing"
        ? "\u53d6\u6d88\u6700\u7ec8\u8bc6\u522b"
        : status === "requesting"
          ? "\u53d6\u6d88\u542f\u52a8\u8bed\u97f3\u8f93\u5165"
          : "\u8bed\u97f3\u8f93\u5165";
  const icon =
    status === "requesting" || status === "transcribing"
      ? `<span class="voice-input-spinner" aria-hidden="true"></span>`
      : `<svg viewBox="0 0 24 24" aria-hidden="true" draggable="false">
          <path d="M12 2a3 3 0 0 0-3 3v7a3 3 0 0 0 6 0V5a3 3 0 0 0-3-3Z"></path>
          <path d="M19 10v2a7 7 0 0 1-14 0v-2"></path>
          <path d="M12 19v3"></path>
        </svg>`;
  return `<button type="button" class="voice-input-button ${status}" data-action="toggle-voice-input" title="${title}" aria-label="${title}" aria-pressed="${status === "recording" ? "true" : "false"}">${icon}</button>`;
}

async function toggleVoiceInput() {
  if (state.voiceInput.status === "requesting") {
    cancelVoiceInput();
    return;
  }
  if (state.voiceInput.status === "recording") {
    await finishVoiceInput();
    return;
  }
  if (state.voiceInput.status === "transcribing") {
    cancelVoiceInput({ notify: true });
    return;
  }
  await startVoiceInput();
}

async function startVoiceInput() {
  const targetThreadId = currentComposerThreadId();
  if (!targetThreadId) return;
  if (
    !api.getVoiceTranscriptionAvailability ||
    !api.startVoiceTranscription ||
    !api.sendVoiceAudioChunk ||
    !api.finishVoiceTranscription
  ) {
    showToast("当前客户端缺少实时语音识别组件", 3500);
    return;
  }

  const token = ++voiceInputOperationToken;
  const requestId = `voice-${Date.now().toString(36)}-${Math.random().toString(16).slice(2)}`;
  const input = root.querySelector<HTMLTextAreaElement>("#composerInput");
  const currentText = input?.value ?? state.composerText;
  const selectionStart = input?.selectionStart ?? currentText.length;
  const selectionEnd = input?.selectionEnd ?? selectionStart;
  voiceTranscriptInsertion = {
    threadId: targetThreadId,
    start: Math.max(0, Math.min(currentText.length, selectionStart)),
    appliedText: currentText.slice(selectionStart, selectionEnd),
    detached: false,
  };
  voiceLiveTranscript = {
    latestText: "",
  };
  voiceAudioSendChain = Promise.resolve();
  voiceAudioSendFailure = null;
  voiceAudioStreamingEnabled = false;
  state.voiceInput = { status: "requesting", targetThreadId, requestId };
  render();
  let recorder: VoiceRecorder | null = null;
  try {
    const availability = await api.getVoiceTranscriptionAvailability();
    if (token !== voiceInputOperationToken) return;
    if (!availability?.ok) throw new Error(availability?.message || "腾讯云实时语音识别尚未配置");
    recorder = await createVoiceRecorder({
      onAudioChunk(audioBytes) {
        queueVoiceAudioChunk(requestId, token, audioBytes);
      },
    });
    if (token !== voiceInputOperationToken) {
      recorder.cancel();
      return;
    }
    activeVoiceRecorder = recorder;
    const started = await api.startVoiceTranscription({ requestId });
    if (token !== voiceInputOperationToken) {
      recorder.cancel();
      void api.cancelVoiceTranscription?.({ requestId }).catch(() => {});
      return;
    }
    if (!started?.ok) throw new Error(started?.message || "腾讯云实时语音识别启动失败");
    voiceAudioStreamingEnabled = true;
    state.voiceInput = { status: "recording", targetThreadId, requestId };
    clearVoiceInputMaxTimer();
    voiceInputMaxTimer = window.setTimeout(() => {
      if (state.voiceInput.status !== "recording") return;
      showToast("录音已达 2 分钟，正在获取最终文字", 2600);
      void finishVoiceInput();
    }, VOICE_INPUT_MAX_DURATION_MS);
    render();
  } catch (error) {
    if (token !== voiceInputOperationToken) return;
    voiceAudioStreamingEnabled = false;
    recorder?.cancel();
    void api.cancelVoiceTranscription?.({ requestId }).catch(() => {});
    resetVoiceInputState();
    render();
    showToast(voiceInputCaptureErrorMessage(error), 4500);
  }
}

async function finishVoiceInput() {
  if (state.voiceInput.status !== "recording" || !activeVoiceRecorder) return;
  const recorder = activeVoiceRecorder;
  const targetThreadId = state.voiceInput.targetThreadId;
  const requestId = state.voiceInput.requestId;
  if (!requestId) return;
  const token = voiceInputOperationToken;
  activeVoiceRecorder = null;
  clearVoiceInputMaxTimer();
  state.voiceInput = { status: "transcribing", targetThreadId, requestId };
  render();

  let transcript = "";
  let failure = "";
  try {
    const recording = await recorder.stop();
    voiceAudioStreamingEnabled = false;
    if (token !== voiceInputOperationToken) return;
    await voiceAudioSendChain;
    if (token !== voiceInputOperationToken) return;
    if (recording.durationMs < VOICE_INPUT_MIN_DURATION_MS) {
      failure = "录音时间太短，请重新说一次";
      await api.cancelVoiceTranscription?.({ requestId }).catch(() => {});
    } else if (voiceAudioSendFailure) {
      failure = voiceAudioSendFailure;
      await api.cancelVoiceTranscription?.({ requestId }).catch(() => {});
    } else {
      const result = await api.finishVoiceTranscription?.({ requestId });
      if (token !== voiceInputOperationToken) return;
      if (!result?.ok) {
        failure = result?.message || "获取最终识别文字失败";
      } else {
        transcript = String(result.text || voiceLiveTranscript?.latestText || "").trim();
      }
    }
  } catch (error) {
    if (token !== voiceInputOperationToken) return;
    await api.cancelVoiceTranscription?.({ requestId }).catch(() => {});
    failure = voiceInputCaptureErrorMessage(error);
  }

  if (token !== voiceInputOperationToken) return;
  const hadLiveTranscript = Boolean(voiceLiveTranscript?.latestText);
  if (transcript) replaceVoiceTranscriptInsertion(targetThreadId, transcript);
  const movedToDraft = Boolean(transcript && targetThreadId && targetThreadId !== currentComposerThreadId());
  resetVoiceInputState();
  render();
  if (failure) {
    showToast(hadLiveTranscript ? `${failure}，已保留实时识别文字` : failure, 4500);
    return;
  }
  if (!transcript) {
    if (!hadLiveTranscript) showToast("没有识别到清晰语音", 3000);
    return;
  }
  if (movedToDraft) showToast("语音整理结果已写入原会话草稿", 2800);
}

function cancelVoiceInput(options: { notify?: boolean } = {}) {
  const previousStatus = state.voiceInput.status;
  if (previousStatus === "idle") return;
  const requestId = state.voiceInput.requestId;
  voiceInputOperationToken += 1;
  clearVoiceInputMaxTimer();
  voiceAudioStreamingEnabled = false;
  activeVoiceRecorder?.cancel();
  activeVoiceRecorder = null;
  resetVoiceInputState();
  render();
  if (requestId) {
    void api.cancelVoiceTranscription?.({ requestId }).catch(() => {});
  }
  if (options.notify && previousStatus === "transcribing") {
    showToast("已取消文字整理，已保留实时识别文字", 2600);
  }
}

function resetVoiceInputState() {
  clearVoiceInputMaxTimer();
  activeVoiceRecorder = null;
  voiceAudioStreamingEnabled = false;
  voiceAudioSendChain = Promise.resolve();
  voiceAudioSendFailure = null;
  voiceTranscriptInsertion = null;
  voiceLiveTranscript = null;
  state.voiceInput = { status: "idle", targetThreadId: null, requestId: null };
}

function clearVoiceInputMaxTimer() {
  if (voiceInputMaxTimer === null) return;
  window.clearTimeout(voiceInputMaxTimer);
  voiceInputMaxTimer = null;
}

function queueVoiceAudioChunk(requestId: string, token: number, audioBytes: ArrayBuffer) {
  if (
    !voiceAudioStreamingEnabled ||
    token !== voiceInputOperationToken ||
    (state.voiceInput.status !== "recording" && state.voiceInput.status !== "transcribing") ||
    state.voiceInput.requestId !== requestId ||
    !api.sendVoiceAudioChunk
  ) {
    return;
  }
  const chunk = audioBytes.slice(0);
  voiceAudioSendChain = voiceAudioSendChain
    .then(async () => {
      if (voiceAudioSendFailure || token !== voiceInputOperationToken) return;
      const result = await api.sendVoiceAudioChunk?.({ requestId, audioBytes: chunk });
      if (!result?.ok) throw new Error(result?.message || "发送语音数据失败");
    })
    .catch((error) => {
      if (token !== voiceInputOperationToken) return;
      voiceAudioSendFailure = errorMessage(error) || "发送语音数据失败";
      voiceAudioStreamingEnabled = false;
      window.setTimeout(() => {
        if (token !== voiceInputOperationToken || state.voiceInput.status !== "recording") return;
        const hadLiveTranscript = Boolean(voiceLiveTranscript?.latestText);
        const message = voiceAudioSendFailure || "发送语音数据失败";
        cancelVoiceInput();
        showToast(hadLiveTranscript ? `${message}，已保留实时识别文字` : message, 4500);
      }, 0);
    });
}

function handleVoiceTranscriptionResult(result: VoiceTranscriptionResponse) {
  const requestId = state.voiceInput.requestId;
  if (!requestId || result?.requestId !== requestId || state.voiceInput.status === "idle") return;
  if (!result.ok) {
    const hadLiveTranscript = Boolean(voiceLiveTranscript?.latestText);
    const message = result.message || "腾讯云语音识别失败";
    cancelVoiceInput();
    showToast(hadLiveTranscript ? `${message}，已保留实时识别文字` : message, 4500);
    return;
  }
  const transcript = String(result.text || "").trim();
  if (!transcript || transcript === voiceLiveTranscript?.latestText) return;
  if (voiceLiveTranscript) voiceLiveTranscript.latestText = transcript;
  replaceVoiceTranscriptInsertion(state.voiceInput.targetThreadId, transcript);
}

function voiceTranscriptBoundary(left: string, right: string) {
  if (!left || !right || /\s$/.test(left) || /^\s/.test(right)) return "";
  return /[a-zA-Z0-9]$/.test(left) && /^[a-zA-Z0-9]/.test(right) ? " " : "";
}

function replaceVoiceTranscriptInsertion(targetThreadId: string | null, transcript: string) {
  const insertion = voiceTranscriptInsertion;
  if (!targetThreadId || !transcript || !insertion || insertion.threadId !== targetThreadId || insertion.detached) return false;
  const active = targetThreadId === currentComposerThreadId();
  const input = active ? root.querySelector<HTMLTextAreaElement>("#composerInput") : null;
  const draft = state.composerDrafts[targetThreadId] || { text: "", attachments: [], quote: null };
  const currentText = active ? (input?.value ?? state.composerText)
    : draft.text;
  let start = Math.max(0, Math.min(currentText.length, insertion.start));
  const expected = insertion.appliedText;
  if (currentText.slice(start, start + expected.length) !== expected) {
    const first = expected ? currentText.indexOf(expected) : start;
    const unique = expected && first >= 0 && first === currentText.lastIndexOf(expected);
    if (!unique) {
      insertion.detached = true;
      return false;
    }
    start = first;
  }
  const before = currentText.slice(0, start);
  const after = currentText.slice(start + expected.length);
  const replacement = `${voiceTranscriptBoundary(before, transcript)}${transcript}${voiceTranscriptBoundary(transcript, after)}`;
  const nextText = `${before}${replacement}${after}`;
  insertion.start = start;
  insertion.appliedText = replacement;

  if (!active) {
    setComposerDraft(targetThreadId, { ...draft, text: nextText });
    return true;
  }
  state.composerText = nextText;
  reconcileComposerThreadReferences(nextText);
  reconcileComposerMediaReferences(nextText);
  if (input) {
    input.value = nextText;
    const cursor = start + replacement.length;
    input.setSelectionRange(cursor, cursor);
  }
  rememberActiveComposerDraft();
  syncComposerMentionPopovers();
  syncComposerMentionHighlights();
  syncComposerSendButton();
  return true;
}

function trackVoiceTranscriptInsertionAfterComposerEdit(input: HTMLTextAreaElement) {
  const insertion = voiceTranscriptInsertion;
  if (!insertion || insertion.detached || insertion.threadId !== currentComposerThreadId()) return;
  const text = input.value;
  if (!insertion.appliedText) {
    insertion.start = input.selectionStart ?? text.length;
    return;
  }
  const first = text.indexOf(insertion.appliedText);
  if (first >= 0 && first === text.lastIndexOf(insertion.appliedText)) {
    insertion.start = first;
    return;
  }
  insertion.detached = true;
}

function voiceInputCaptureErrorMessage(error: unknown) {
  const name = error instanceof DOMException ? error.name : "";
  if (name === "NotAllowedError" || name === "SecurityError") {
    return "未获得麦克风权限，请在系统设置中允许HaoLo使用麦克风";
  }
  if (name === "NotFoundError" || name === "DevicesNotFoundError") {
    return "没有检测到可用麦克风";
  }
  if (name === "NotReadableError" || name === "TrackStartError") {
    return "麦克风正被其他应用占用";
  }
  return errorMessage(error) || "录音失败";
}

function patchComposerSubmitButton(threadId: string | null | undefined = state.currentThreadId) {
  if (!threadId || threadId !== state.currentThreadId || state.activeView !== "chat") return false;
  const thread = currentThread();
  const form = root.querySelector<HTMLFormElement>("#composerForm");
  const button = form?.querySelector<HTMLButtonElement>(".send-button");
  if (!thread || !form || !button || form.dataset.threadId !== thread.id) return false;
  const template = document.createElement("template");
  template.innerHTML = renderComposerSubmitButton(thread).trim();
  const nextButton = template.content.firstElementChild as HTMLButtonElement | null;
  if (!nextButton) return false;
  if (button.outerHTML === nextButton.outerHTML) return true;
  button.replaceWith(nextButton);
  return true;
}

function patchComposerPendingAttachments(form: HTMLFormElement) {
  const wrap = form.querySelector<HTMLElement>(".pending-attachments-wrap");
  if (!wrap) return state.attachments.length === 0;

  const retainedAttachmentIds = new Set(state.attachments.map((attachment) => attachment.id));
  let removed = false;
  wrap.querySelectorAll<HTMLElement>("[data-pending-attachment-id]").forEach((card) => {
    if (retainedAttachmentIds.has(card.dataset.pendingAttachmentId || "")) return;
    card.remove();
    removed = true;
  });

  if (
    !state.attachments.length &&
    !wrap.querySelector("[data-media-input-kind], [data-workflow-input-slot]")
  ) {
    wrap.remove();
    return true;
  }
  if (removed) window.requestAnimationFrame(updateAttachmentScrollControls);
  return true;
}

function patchComposerDynamicState(threadId: string | null | undefined = state.currentThreadId) {
  if (!threadId || threadId !== state.currentThreadId || state.activeView !== "chat") return false;
  const thread = currentThread();
  const form = root.querySelector<HTMLFormElement>("#composerForm");
  if (!thread || !form || form.dataset.threadId !== thread.id) return false;
  let patched = patchComposerSubmitButton(threadId);
  if (patchComposerPendingAttachments(form)) patched = true;
  const modelSelectionDisabled = isComposerModelSelectionDisabled(threadId);
  form.querySelectorAll<HTMLButtonElement>(".composer-model-button, [data-composer-model]").forEach((button) => {
    if (button.disabled !== modelSelectionDisabled) {
      button.disabled = modelSelectionDisabled;
      patched = true;
    }
  });
  const input = form.querySelector<HTMLTextAreaElement>("#composerInput");
  if (input) {
    const placeholder = composerPlaceholderForThread(thread);
    if (input.placeholder !== placeholder) {
      input.placeholder = placeholder;
      patched = true;
    }
  }
  return patched;
}

