function rechargePaymentQrDataUrl(order: Web3PaymentOrder) {
  const cacheKey = `${order.network}:${order.recipient_address}`;
  const cached = rechargePaymentQrDataUrlCache.get(cacheKey);
  if (cached) return cached;
  const pending = QRCode.toDataURL(order.recipient_address, {
    errorCorrectionLevel: "H",
    margin: 1,
    width: 360,
    color: { dark: "#000000", light: "#ffffff" },
  }).catch((error) => {
    rechargePaymentQrDataUrlCache.delete(cacheKey);
    throw error;
  });
  rechargePaymentQrDataUrlCache.set(cacheKey, pending);
  return pending;
}

function formatRechargePaymentCountdown(milliseconds: number) {
  const totalSeconds = Math.max(0, Math.ceil(milliseconds / 1000));
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
}

function stopRechargePaymentCountdown() {
  if (rechargePaymentCountdownTimer != null) window.clearInterval(rechargePaymentCountdownTimer);
  rechargePaymentCountdownTimer = null;
  rechargePaymentCountdownEndsAt = null;
}

function updateRechargePaymentCountdown() {
  const countdown = root.querySelector<HTMLElement>("[data-recharge-payment-countdown]");
  if (!countdown || rechargePaymentCountdownEndsAt == null) {
    stopRechargePaymentCountdown();
    return;
  }
  const remaining = Math.max(0, rechargePaymentCountdownEndsAt - Date.now());
  countdown.textContent = `${formatRechargePaymentCountdown(remaining)} 剩余`;
  if (remaining === 0) {
    stopRechargePaymentCountdown();
    void updateRechargePaymentDetails();
  }
}

function startRechargePaymentCountdown(order: Web3PaymentOrder) {
  const endsAt = Date.parse(order.expires_at);
  stopRechargePaymentCountdown();
  rechargePaymentCountdownEndsAt = Number.isFinite(endsAt) ? endsAt : null;
  updateRechargePaymentCountdown();
  if (rechargePaymentCountdownEndsAt != null && rechargePaymentCountdownEndsAt > Date.now()) {
    rechargePaymentCountdownTimer = window.setInterval(updateRechargePaymentCountdown, 1000);
  }
}

function stopRechargePaymentPolling() {
  if (rechargePaymentPollTimer != null) window.clearInterval(rechargePaymentPollTimer);
  rechargePaymentPollTimer = null;
  rechargePaymentPollingOrderNo = null;
  rechargePaymentPollingSelectionKey = null;
  rechargePaymentPollInFlight = false;
  rechargePaymentPollGeneration += 1;
}

function stopRechargePaymentRuntime() {
  stopRechargePaymentCountdown();
  stopRechargePaymentPolling();
}

function syncRechargePaymentSelectionControls() {
  root.querySelectorAll<HTMLElement>("[data-recharge-product-id]").forEach((card) => {
    const selected = card.dataset.rechargeProductId === selectedRechargeProductId;
    const product = RECHARGE_SUBSCRIPTION_PRODUCTS.find(
      (candidate) => candidate.id === card.dataset.rechargeProductId,
    );
    const unavailable = Boolean(product && rechargeProductIsUnavailable(product));
    card.classList.toggle("selected", selected);
    card.classList.toggle("unavailable", unavailable);
    card.setAttribute("aria-checked", selected ? "true" : "false");
    card.setAttribute("aria-disabled", unavailable ? "true" : "false");
    card.setAttribute("tabindex", unavailable ? "-1" : "0");
  });
  root.querySelectorAll<HTMLInputElement>('input[name="recharge-payment-network"]').forEach((input) => {
    input.checked = input.value === selectedRechargePaymentNetwork;
  });
}

function activateRechargePaymentSelection() {
  ensureRechargePaymentOrderScope();
  stopRechargePaymentRuntime();
  const selectionKey = currentRechargePaymentSelectionKey();
  rechargePaymentOrder = selectionKey
    ? rechargePaymentOrdersBySelection.get(selectionKey) || null
    : null;
  syncRechargePaymentSelectionControls();
  if (!selectionKey) {
    void updateRechargePaymentDetails();
    return;
  }
  void updateRechargePaymentDetails();
}

async function refreshRechargeProfileAfterPayment(order: Web3PaymentOrder) {
  if (rechargePaymentProfileRefreshOrderNo === order.order_no) return;
  rechargePaymentProfileRefreshOrderNo = order.order_no;
  const refreshed = await refreshProfileFromApi({ renderAfter: false, reportError: false, showRefreshing: false });
  if (refreshed && state.activeView === "recharge") render();
}

async function applyRechargePaymentOrder(
  value: any,
  expectedSelectionKey: string,
  expectedScope: string,
) {
  if (expectedScope !== rechargePaymentOrderScope) return;
  const order = normalizeWeb3PaymentOrder(value);
  const orderSelectionKey = rechargePaymentOrderSelectionKey(order);
  if (orderSelectionKey !== expectedSelectionKey) {
    throw new Error("支付接口返回的套餐或支付方式与当前请求不一致");
  }
  rechargePaymentOrdersBySelection.set(orderSelectionKey, order);
  rechargePaymentOrderErrorsBySelection.delete(orderSelectionKey);
  rechargePaymentReplacementPreviousOrderNos.delete(orderSelectionKey);
  if (currentRechargePaymentSelectionKey() !== orderSelectionKey) {
    if (order.status === "paid") void refreshRechargeProfileAfterPayment(order);
    return;
  }
  rechargePaymentOrder = order;
  syncRechargePaymentSelectionControls();
  const panel = root.querySelector<HTMLElement>("[data-recharge-payment-details]");
  const visualFingerprint = rechargePaymentOrderVisualFingerprint(order);
  if (panel?.dataset.rechargePaymentFingerprint !== visualFingerprint) {
    await updateRechargePaymentDetails();
  }
  if (order.status === "paid") {
    stopRechargePaymentRuntime();
    void refreshRechargeProfileAfterPayment(order);
  }
}

async function pollRechargePaymentOrder() {
  if (
    rechargePaymentPollInFlight
    || !rechargePaymentPollingOrderNo
    || !rechargePaymentPollingSelectionKey
    || state.activeView !== "recharge"
    || typeof api.getWeb3PaymentOrder !== "function"
  ) return;
  rechargePaymentPollInFlight = true;
  const orderNo = rechargePaymentPollingOrderNo;
  const selectionKey = rechargePaymentPollingSelectionKey;
  const orderScope = rechargePaymentOrderScope;
  const pollGeneration = rechargePaymentPollGeneration;
  try {
    const result = await api.getWeb3PaymentOrder({ orderNo });
    await applyRechargePaymentOrder(result, selectionKey, orderScope);
  } catch (error) {
    if (!isAuthSessionExpiredError(error)) console.warn("[web3-payment] order poll failed", error);
  } finally {
    if (pollGeneration === rechargePaymentPollGeneration) rechargePaymentPollInFlight = false;
  }
}

function startRechargePaymentPolling(orderNo: string, selectionKey: string) {
  if (
    rechargePaymentPollingOrderNo === orderNo
    && rechargePaymentPollingSelectionKey === selectionKey
    && rechargePaymentPollTimer != null
  ) return;
  stopRechargePaymentPolling();
  rechargePaymentPollingOrderNo = orderNo;
  rechargePaymentPollingSelectionKey = selectionKey;
  rechargePaymentPollTimer = window.setInterval(() => void pollRechargePaymentOrder(), RECHARGE_PAYMENT_POLL_INTERVAL_MS);
}

function isRechargeTrialIneligibleError(value: unknown) {
  return /(?:trial_membership_ineligible|体验版仅限每个账户开通一次|trial[^\n]*once|not eligible[^\n]*trial)/i
    .test(insufficientQuotaSignalText(value));
}

async function createRechargePaymentOrder(options: {
  force?: boolean;
  preserveExisting?: boolean;
  previousOrderNo?: string;
} = {}) {
  ensureRechargePaymentOrderScope();
  const selection = rechargePaymentSelection();
  if (!selection) return;
  const selectionKey = rechargePaymentSelectionKey(selection.product.id, selection.network.id);
  const previousOrderNo = options.previousOrderNo
    || rechargePaymentReplacementPreviousOrderNos.get(selectionKey);
  const orderScope = rechargePaymentOrderScope;
  if (rechargePaymentOrderLoadingSelections.has(selectionKey)) {
    await updateRechargePaymentDetails();
    return;
  }
  const existingOrder = rechargePaymentOrdersBySelection.get(selectionKey) || null;
  const canRetainExistingOrder = canRetainRechargePaymentOrder(existingOrder);
  if (
    !options.force
    && canRetainExistingOrder
  ) {
    rechargePaymentOrder = existingOrder;
    await updateRechargePaymentDetails();
    return;
  }
  if (typeof api.createWeb3PaymentOrder !== "function") {
    rechargePaymentOrderErrorsBySelection.set(selectionKey, "当前客户端版本不支持 USDT 支付，请更新后重试。");
    await updateRechargePaymentDetails();
    return;
  }
  rechargePaymentOrderLoadingSelections.add(selectionKey);
  rechargePaymentOrderErrorsBySelection.delete(selectionKey);
  if (!options.preserveExisting || !canRetainExistingOrder) {
    rechargePaymentOrdersBySelection.delete(selectionKey);
  }
  if (currentRechargePaymentSelectionKey() === selectionKey) {
    rechargePaymentOrder = options.preserveExisting && canRetainExistingOrder ? existingOrder : null;
    stopRechargePaymentRuntime();
  }
  await updateRechargePaymentDetails();
  try {
    const result = await api.createWeb3PaymentOrder({
      productId: selection.product.id,
      network: selection.network.id,
      paymentChannel: "web3",
      previousOrderNo,
    });
    if (orderScope !== rechargePaymentOrderScope) return;
    rechargePaymentOrderLoadingSelections.delete(selectionKey);
    await applyRechargePaymentOrder(result, selectionKey, orderScope);
  } catch (error) {
    if (orderScope !== rechargePaymentOrderScope) return;
    rechargePaymentOrderLoadingSelections.delete(selectionKey);
    const authExpired = isAuthSessionExpiredError(error);
    if (selection.product.requiresTrialEligibility && isRechargeTrialIneligibleError(error)) {
      if (state.auth.profile) {
        state.auth.profile = { ...state.auth.profile, trial_eligible: false };
      }
      rechargePaymentOrderErrorsBySelection.set(selectionKey, "体验版仅限每个账户开通一次");
      selectedRechargeProductId = "subscription_basic";
      showToast("体验版仅限每个账户开通一次");
      render();
      return;
    }
    const fallbackOrder = rechargePaymentOrdersBySelection.get(selectionKey) || null;
    const canUseFallbackOrder = canRetainRechargePaymentOrder(fallbackOrder);
    if (canUseFallbackOrder) {
      rechargePaymentOrderErrorsBySelection.delete(selectionKey);
    } else {
      rechargePaymentOrderErrorsBySelection.set(selectionKey, authExpired
        ? "登录状态已过期，请重新登录后再支付。"
        : errorMessage(error) || "支付订单创建失败，请稍后重试。");
    }
    if (currentRechargePaymentSelectionKey() === selectionKey) await updateRechargePaymentDetails();
  }
}

async function reconcileExpiredRechargePaymentOrder(
  order: Web3PaymentOrder,
  selectionKey: string,
  expectedScope: string,
) {
  const checkKey = `${selectionKey}:${order.order_no}`;
  if (rechargePaymentExpiryChecksInFlight.has(checkKey)) return;
  rechargePaymentExpiryChecksInFlight.add(checkKey);
  stopRechargePaymentRuntime();
  try {
    if (typeof api.getWeb3PaymentOrder !== "function") {
      throw new Error("当前客户端版本无法确认订单最终状态");
    }
    const result = await api.getWeb3PaymentOrder({ orderNo: order.order_no });
    if (expectedScope !== rechargePaymentOrderScope) return;
    const refreshedOrder = normalizeWeb3PaymentOrder(result);
    if (rechargePaymentOrderSelectionKey(refreshedOrder) !== selectionKey) {
      throw new Error("支付接口返回的套餐或支付方式与当前请求不一致");
    }
    const serverConfirmedExpired = shouldReplaceRechargePaymentOrderAfterFinalCheck(refreshedOrder);
    if (!serverConfirmedExpired) {
      await applyRechargePaymentOrder(refreshedOrder, selectionKey, expectedScope);
      return;
    }
    rechargePaymentOrdersBySelection.delete(selectionKey);
    rechargePaymentReplacementPreviousOrderNos.set(selectionKey, order.order_no);
    if (currentRechargePaymentSelectionKey() === selectionKey) rechargePaymentOrder = null;
    await updateRechargePaymentDetails();
  } catch (error) {
    if (expectedScope !== rechargePaymentOrderScope || currentRechargePaymentSelectionKey() !== selectionKey) return;
    const panel = root.querySelector<HTMLElement>("[data-recharge-payment-details]");
    if (!panel) return;
    delete panel.dataset.rechargePaymentKey;
    delete panel.dataset.rechargePaymentFingerprint;
    panel.innerHTML = renderRechargePaymentState(
      "error",
      "订单最终状态确认失败",
      "暂时无法确认最后一次到账结果，请勿重复支付。",
      "重新确认",
    );
    panel.querySelector("[data-recharge-payment-retry]")?.addEventListener("click", () => {
      void reconcileExpiredRechargePaymentOrder(order, selectionKey, expectedScope);
    });
    if (!isAuthSessionExpiredError(error)) console.warn("[web3-payment] final order reconciliation failed", error);
  } finally {
    rechargePaymentExpiryChecksInFlight.delete(checkKey);
  }
}

async function updateRechargePaymentDetails() {
  ensureRechargePaymentOrderScope();
  const panel = root.querySelector<HTMLElement>("[data-recharge-payment-details]");
  if (!panel) return;
  const selectionKey = currentRechargePaymentSelectionKey();
  if (!selectionKey) return;
  rechargePaymentOrder = rechargePaymentOrdersBySelection.get(selectionKey) || null;
  const order = rechargePaymentOrder;
  panel.hidden = false;
  if (rechargePaymentOrderLoadingSelections.has(selectionKey) && !order) {
    delete panel.dataset.rechargePaymentKey;
    delete panel.dataset.rechargePaymentFingerprint;
    panel.innerHTML = renderRechargePaymentState("loading", "正在创建支付订单", "正在向后端申请本订单的专属收款信息。");
    return;
  }
  const paymentError = rechargePaymentOrderErrorsBySelection.get(selectionKey) || null;
  if (paymentError && !order) {
    delete panel.dataset.rechargePaymentKey;
    delete panel.dataset.rechargePaymentFingerprint;
    panel.innerHTML = renderRechargePaymentState("error", "支付订单获取失败", paymentError, "重试");
    panel.querySelector("[data-recharge-payment-retry]")?.addEventListener("click", () => void createRechargePaymentOrder({ force: true }));
    return;
  }
  if (!order) {
    delete panel.dataset.rechargePaymentKey;
    delete panel.dataset.rechargePaymentFingerprint;
    panel.innerHTML = renderRechargePaymentState(
      "idle",
      "确认支付信息",
      "确认套餐和支付方式后，再生成本次支付订单。",
      "生成支付信息",
    );
    panel.querySelector("[data-recharge-payment-retry]")?.addEventListener("click", () => {
      void createRechargePaymentOrder({ force: true });
    });
    return;
  }
  const uniqueAddressUnderpaid = order.address_type === "unique_temporary"
    && order.payment_state === "underpaid"
    && order.status === "pending"
    && Date.parse(order.expires_at) > Date.now();
  if (!uniqueAddressUnderpaid && (order.status === "expired" || (order.status === "pending" && Date.parse(order.expires_at) <= Date.now()))) {
    delete panel.dataset.rechargePaymentKey;
    delete panel.dataset.rechargePaymentFingerprint;
    panel.innerHTML = renderRechargePaymentState(
      "confirming",
      "正在确认订单最终状态",
      "正在向服务器核对最后一次到账结果，请勿重复支付。",
    );
    void reconcileExpiredRechargePaymentOrder(order, selectionKey, rechargePaymentOrderScope);
    return;
  }
  panel.dataset.rechargePaymentKey = order.order_no;
  panel.dataset.rechargePaymentFingerprint = rechargePaymentOrderVisualFingerprint(order);
  panel.innerHTML = renderRechargePaymentDetailsContent(order);
  hydrateRechargeMarketLogos(panel);
  syncRechargePaymentSelectionControls();
  const retryButton = panel.querySelector<HTMLElement>("[data-recharge-payment-retry]");
  retryButton?.addEventListener("click", () => void createRechargePaymentOrder({ force: true }));
  const tutorialButton = panel.querySelector<HTMLButtonElement>("[data-recharge-payment-tutorial-url]");
  tutorialButton?.addEventListener("click", () => {
    const tutorialUrl = tutorialButton.dataset.rechargePaymentTutorialUrl;
    if (!tutorialUrl) return;
    void api.openExternal(tutorialUrl).catch(() => {
      showToast("暂时无法打开支付教程，请稍后重试。", 3200);
    });
  });
  if (isActiveRechargePaymentOrder(order)) startRechargePaymentPolling(order.order_no, selectionKey);
  else stopRechargePaymentRuntime();
  if (order.status !== "pending" && !uniqueAddressUnderpaid) {
    stopRechargePaymentCountdown();
    return;
  }
  if (order.status === "pending") startRechargePaymentCountdown(order);
  const copyButton = panel.querySelector<HTMLButtonElement>("[data-copy-recharge-address]");
  copyButton?.addEventListener("click", () => {
    copyButton.classList.add("copied");
    void copyTextToClipboard(order.recipient_address);
    window.setTimeout(() => copyButton.classList.remove("copied"), 1200);
  });
  const copyAmountButton = panel.querySelector<HTMLButtonElement>("[data-copy-recharge-amount]");
  copyAmountButton?.addEventListener("click", () => {
    copyAmountButton.classList.add("copied");
    void copyTextToClipboard(copyAmountButton.dataset.copyRechargeAmount || order.payable_amount);
    window.setTimeout(() => copyAmountButton.classList.remove("copied"), 1200);
  });
  const network = rechargePaymentOrderNetwork(order);
  if (network?.kind === "internal") return;
  const frame = panel.querySelector<HTMLElement>("[data-recharge-payment-qr-frame]");
  const image = panel.querySelector<HTMLImageElement>("[data-recharge-payment-qr-image]");
  if (!frame || !image) return;
  try {
    const dataUrl = await rechargePaymentQrDataUrl(order);
    if (panel.dataset.rechargePaymentKey !== order.order_no) return;
    image.addEventListener("load", () => {
      image.hidden = false;
      frame.classList.remove("loading", "error");
      frame.classList.add("loaded");
    }, { once: true });
    image.addEventListener("error", () => {
      frame.classList.remove("loading", "loaded");
      frame.classList.add("error");
    }, { once: true });
    image.src = dataUrl;
  } catch {
    if (panel.dataset.rechargePaymentKey !== order.order_no) return;
    frame.classList.remove("loading", "loaded");
    frame.classList.add("error");
  }
}

function consumptionPayload(value: any): any {
  if (value && typeof value === "object" && value.data && typeof value.data === "object") return value.data;
  return value && typeof value === "object" ? value : {};
}

function formatConsumptionToken(value: unknown): string {
  const amount = Math.max(Number(value) || 0, 0);
  if (state.settings.language === "en") {
    return new Intl.NumberFormat("en-US", {
      notation: "compact",
      minimumFractionDigits: 0,
      maximumFractionDigits: 2,
    }).format(amount);
  }
  if (amount >= 100_000_000) return `${(amount / 100_000_000).toFixed(amount >= 1_000_000_000 ? 1 : 2).replace(/\.0+$/, "")}亿`;
  if (amount >= 10_000) return `${(amount / 10_000).toFixed(amount >= 1_000_000 ? 1 : 2).replace(/\.0+$/, "")}万`;
  return amount.toLocaleString(appLanguageLocale(state.settings.language), { minimumFractionDigits: 0, maximumFractionDigits: 4 });
}

function formatConsumptionPoints(value: unknown): string {
  const amount = Math.max(Number(value) || 0, 0);
  const fractionDigits = Math.trunc(amount) === 0 ? 6 : 4;
  const scale = 10 ** fractionDigits;
  const truncatedAmount = Math.trunc(amount * scale) / scale;
  return truncatedAmount.toFixed(fractionDigits);
}

function formatConsumptionAmount(tokens: unknown, points: unknown, unit = state.consumption.unit): string {
  return unit === "points" ? formatConsumptionPoints(points) : formatConsumptionToken(tokens);
}

function formatConsumptionRecordPoints(value: unknown): string {
  return formatConsumptionPoints(value);
}

function formatConsumptionRecordAmount(tokens: unknown, points: unknown, unit: ConsumptionUnit): string {
  return unit === "points" ? formatConsumptionRecordPoints(points) : formatConsumptionToken(tokens);
}

function formatConsumptionCalendarPoints(value: unknown): string {
  const amount = Math.max(Number(value) || 0, 0);
  const fractionDigits = Math.trunc(amount) === 0 ? 5 : 3;
  const scale = 10 ** fractionDigits;
  const truncatedAmount = Math.trunc(amount * scale) / scale;
  return truncatedAmount.toFixed(fractionDigits);
}

function formatConsumptionCalendarAmount(tokens: unknown, points: unknown): string {
  if (state.consumption.unit === "points") {
    const amount = Math.max(Number(points) || 0, 0);
    return amount === 0 ? "--" : formatConsumptionCalendarPoints(amount);
  }
  const amount = Math.max(Number(tokens) || 0, 0);
  if (amount === 0) return "--";
  if (state.settings.language === "en") {
    return new Intl.NumberFormat("en-US", {
      notation: "compact",
      minimumFractionDigits: 0,
      maximumFractionDigits: 1,
    }).format(amount);
  }
  if (amount >= 100_000_000) return `${Math.round(amount / 100_000_000)}亿`;
  if (amount >= 10_000) return `${Math.round(amount / 10_000)}万`;
  return amount.toLocaleString(appLanguageLocale(state.settings.language), { minimumFractionDigits: 0, maximumFractionDigits: 2 });
}

function consumptionRecordDisplayUnit(item: any): ConsumptionUnit {
  void item;
  return state.consumption.unit;
}

function formatConsumptionDuration(value: unknown): string {
  const totalMinutes = Math.max(Math.floor((Number(value) || 0) / 60_000), 0);
  const days = Math.floor(totalMinutes / 1440);
  const hours = Math.floor((totalMinutes % 1440) / 60);
  const minutes = totalMinutes % 60;
  if (state.settings.language === "en") {
    return [days ? `${days}d` : "", hours ? `${hours}h` : "", `${minutes}m`].filter(Boolean).join(" ");
  }
  return [days ? `${days}天` : "", hours ? `${hours}小时` : "", `${minutes}分`].filter(Boolean).join(" ");
}

function formatConsumptionExecutionDuration(value: unknown): string {
  const milliseconds = Math.max(Number(value) || 0, 0);
  if (!milliseconds) return "时长未完整上报";
  if (milliseconds < 1_000) return "不足1秒";
  let remaining = Math.max(Math.ceil(milliseconds / 1_000), 1);
  const days = Math.floor(remaining / 86_400);
  remaining %= 86_400;
  const hours = Math.floor(remaining / 3_600);
  remaining %= 3_600;
  const minutes = Math.floor(remaining / 60);
  const seconds = remaining % 60;
  return [days ? `${days}天` : "", hours ? `${hours}小时` : "", minutes ? `${minutes}分` : "", seconds || (!days && !hours && !minutes) ? `${seconds}秒` : ""].filter(Boolean).join("");
}

function formatEnglishConsumptionExecutionDuration(value: unknown): string {
  const milliseconds = Math.max(Number(value) || 0, 0);
  if (!milliseconds) return "Duration unavailable";
  if (milliseconds < 1_000) return "<1s";
  let remaining = Math.max(Math.ceil(milliseconds / 1_000), 1);
  const days = Math.floor(remaining / 86_400);
  remaining %= 86_400;
  const hours = Math.floor(remaining / 3_600);
  remaining %= 3_600;
  const minutes = Math.floor(remaining / 60);
  const seconds = remaining % 60;
  return [
    days ? `${days}d` : "",
    hours ? `${hours}h` : "",
    minutes ? `${minutes}m` : "",
    seconds || (!days && !hours && !minutes) ? `${seconds}s` : "",
  ].filter(Boolean).join(" ");
}

function consumptionDurationDisplay(item: any): string {
  if (state.settings.language === "en") {
    return formatEnglishConsumptionExecutionDuration(item?.duration_ms ?? item?.durationMs);
  }
  return (
    firstString(item?.duration_display, item?.durationDisplay) ||
    formatConsumptionExecutionDuration(item?.duration_ms ?? item?.durationMs)
  );
}

function consumptionMonthLabel(month: string): string {
  const [year, monthNumber] = month.split("-").map(Number);
  if (!Number.isFinite(year) || !Number.isFinite(monthNumber)) return month;
  return new Intl.DateTimeFormat(appLanguageLocale(state.settings.language), {
    timeZone: "UTC",
    year: "numeric",
    month: state.settings.language === "en" ? "long" : "numeric",
  }).format(new Date(Date.UTC(year, monthNumber - 1, 1)));
}

function consumptionDateLabel(value: string): string {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!match) return value;
  return new Intl.DateTimeFormat(appLanguageLocale(state.settings.language), {
    timeZone: "UTC",
    year: "numeric",
    month: state.settings.language === "en" ? "short" : "numeric",
    day: "numeric",
  }).format(new Date(Date.UTC(Number(match[1]), Number(match[2]) - 1, Number(match[3]))));
}

function consumptionWeekdayLabels(): string[] {
  return state.settings.language === "en"
    ? ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
    : ["一", "二", "三", "四", "五", "六", "日"];
}

function formatConsumptionLoginDays(value: unknown): string {
  const days = Math.max(Number(value) || 0, 0);
  if (state.settings.language === "en") return `${days} ${days === 1 ? "day" : "days"}`;
  return `${days} 天`;
}

function shiftConsumptionMonth(month: string, offset: number): string {
  const [year, monthNumber] = month.split("-").map(Number);
  const next = new Date(year, monthNumber - 1 + offset, 1);
  return `${next.getFullYear()}-${String(next.getMonth() + 1).padStart(2, "0")}`;
}

function currentConsumptionMonth(): string {
  const parts = new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Shanghai", year: "numeric", month: "2-digit" }).formatToParts(new Date());
  const year = parts.find((part) => part.type === "year")?.value || String(new Date().getFullYear());
  const month = parts.find((part) => part.type === "month")?.value || String(new Date().getMonth() + 1).padStart(2, "0");
  return `${year}-${month}`;
}

function renderConsumptionLevelIcons(value: unknown): string {
  const summary = value && typeof value === "object"
    ? (value as LevelSummary)
      : currentProfileLevelSummary();
  if (summary && summary.enabled !== false && summary.locked !== true) {
    const icons = normalizeLevelIcons(summary.icons, summary.level);
    if (icons.length) {
      return `<span class="profile-level-icons" aria-label="${escapeAttr(profileLevelAriaLabel(summary, icons))}">${icons.map(renderProfileLevelIcon).join("")}</span>`;
    }
  }
  return renderProfileLevelIcons();
}

function renderConsumptionSkeleton(className: string): string {
  return `<span class="consumption-skeleton ${className}" aria-hidden="true"></span>`;
}

function renderConsumptionProfileSkeleton(unit: ConsumptionUnit): string {
  const labels = [
    `累计${unit === "points" ? "积分" : "Token"}数`,
    "最高单日消耗",
    "最长任务时长",
    "登录天数",
  ];
  return `
    <div class="consumption-profile-person" aria-hidden="true">
      ${renderConsumptionSkeleton("consumption-skeleton-avatar")}
      <div class="consumption-skeleton-profile-copy">
        ${renderConsumptionSkeleton("consumption-skeleton-profile-name")}
        ${renderConsumptionSkeleton("consumption-skeleton-profile-id")}
        ${renderConsumptionSkeleton("consumption-skeleton-profile-level")}
      </div>
    </div>
    ${labels.map((label) => `<div class="consumption-metric"><strong>${renderConsumptionSkeleton("consumption-skeleton-metric")}</strong><span>${label}</span></div>`).join("")}
  `;
}

function renderConsumptionCalendarSkeleton(): string {
  const [year, month] = state.consumption.month.split("-").map(Number);
  const offset = new Date(year, month - 1, 1).getDay();
  const mondayOffset = (offset + 6) % 7;
  const dayCount = new Date(year, month, 0).getDate();
  return `
    <div class="consumption-weekdays">${consumptionWeekdayLabels().map((day) => `<span>${day}</span>`).join("")}</div>
    <div class="consumption-calendar-grid consumption-calendar-skeleton" aria-hidden="true">
      ${Array.from({ length: mondayOffset }, () => `<span class="consumption-calendar-empty"></span>`).join("")}
      ${Array.from({ length: dayCount }, () => renderConsumptionSkeleton("consumption-skeleton-calendar-day")).join("")}
    </div>
  `;
}

function renderConsumptionRecordsSkeleton(): string {
  const rows = Array.from({ length: state.consumption.pageSize }, () => `
    <tr>
      <td>${renderConsumptionSkeleton("consumption-skeleton-record-token")}</td>
      <td>${renderConsumptionSkeleton("consumption-skeleton-record-type")}</td>
      <td>${renderConsumptionSkeleton("consumption-skeleton-record-model")}</td>
      <td><div class="consumption-skeleton-record-detail"><div>${renderConsumptionSkeleton("consumption-skeleton-record-title")}${renderConsumptionSkeleton("consumption-skeleton-record-status")}</div>${renderConsumptionSkeleton("consumption-skeleton-record-excerpt")}</div></td>
    </tr>
  `).join("");
  return `
    <div class="consumption-table-wrap consumption-skeleton-table" aria-hidden="true"><table class="consumption-table"><thead><tr><th>实扣${state.consumption.unit === "points" ? "积分" : "Token"}</th><th>计费项目</th><th>实际调用</th><th>任务与计费说明</th></tr></thead><tbody>${rows}</tbody></table></div>
    <nav class="consumption-pagination consumption-skeleton-pagination" aria-hidden="true">
      ${renderConsumptionSkeleton("consumption-skeleton-page-button")}
      ${renderConsumptionSkeleton("consumption-skeleton-page-label")}
      ${renderConsumptionSkeleton("consumption-skeleton-page-button")}
    </nav>
  `;
}

function syncConsumptionPageScrollability() {
  const scroller = root.querySelector<HTMLElement>(".consumption-page-scroll");
  if (!scroller || state.activeView !== "consumption") return;
  const trailingPadding = Number.parseFloat(window.getComputedStyle(scroller).paddingBottom) || 0;
  const scrollable = scroller.scrollHeight - trailingPadding > scroller.clientHeight + 1;
  scroller.classList.toggle("is-scrollable", scrollable);
  if (!scrollable && scroller.scrollTop !== 0) scroller.scrollTop = 0;
}

function scheduleConsumptionPageScrollabilitySync() {
  if (consumptionPageScrollabilityFrame !== null) {
    window.cancelAnimationFrame(consumptionPageScrollabilityFrame);
  }
  consumptionPageScrollabilityFrame = window.requestAnimationFrame(() => {
    consumptionPageScrollabilityFrame = null;
    syncConsumptionPageScrollability();
  });
}

function renderConsumptionPage(): string {
  const overview = consumptionPayload(state.consumption.overview);
  const calendarData = consumptionPayload(state.consumption.calendar);
  const recordsData = consumptionPayload(state.consumption.records);
  const unit = state.consumption.unit;
  const membership = currentMembershipPlan();
  const profile = overview.profile || state.auth.profile || {};
  const avatar = firstString(profile.avatar_url, profile.avatarUrl) || currentProfileAvatar();
  const name = firstString(profile.nickname, profile.name) || currentProfileName();
  const citizenId = firstString(profile.citizen_id, profile.citizenId) || currentProfileShortId();
  const showSkeleton = state.consumption.loading && !state.consumption.loaded;
  const showOverviewSkeleton = state.consumption.loading && !state.consumption.overview;
  const showCalendarSkeleton = state.consumption.loading && !state.consumption.calendar;
  const showRecordsSkeleton = state.consumption.loading && !state.consumption.records;
  return `
    <main class="consumption-page${showSkeleton ? " is-loading" : ""}" aria-busy="${showSkeleton}">
      <div class="consumption-page-scroll">
        <header class="consumption-header">
          <div class="consumption-header-balances">
            ${renderPageHomeButton()}
            <div class="recharge-page-balance" title="当前积分余额">
              <span>积分余额</span>
              <strong>${escapeHtml(currentProfileBalance())}</strong>
            </div>
            ${membership.subscribed ? renderRechargeSubscriptionBalance() : ""}
          </div>
          <div class="consumption-header-actions">
            <div class="consumption-unit-toggle" role="group" aria-label="计费单位">
              <button type="button" class="${unit === "points" ? "active" : ""}" data-consumption-unit="points">积分消耗</button>
              <button type="button" class="${unit === "token" ? "active" : ""}" data-consumption-unit="token">Token消耗</button>
            </div>
            <button type="button" class="consumption-export" data-action="export-consumption" ${state.consumption.exporting || !api.exportConsumptionReport ? "disabled" : ""}>⇩&nbsp; ${state.consumption.exporting ? "导出中…" : "导出"}</button>
          </div>
        </header>
        <section class="consumption-profile-card" aria-busy="${showOverviewSkeleton}">
          ${showOverviewSkeleton ? renderConsumptionProfileSkeleton(unit) : `<div class="consumption-profile-person">
            <img${builtInAvatarEdgeCropClassAttribute(avatar)} src="${escapeAttr(avatar)}" alt="" />
            <div><div class="consumption-profile-name-row"><strong>${escapeHtml(name)}</strong>${renderMembershipBadge("consumption")}</div><span>HaoLo号：${escapeHtml(citizenId)}</span>${renderConsumptionLevelIcons(overview.level)}</div>
          </div>
          <div class="consumption-metric"><strong>${formatConsumptionAmount(overview.cumulative_tokens, overview.cumulative_points ?? overview.cumulative_usd)}</strong><span>累计${unit === "points" ? "积分" : "Token"}数</span></div>
          <div class="consumption-metric"><strong>${formatConsumptionAmount(overview.peak_daily_tokens, overview.peak_daily_points ?? overview.peak_daily_usd)}</strong><span>最高单日消耗</span></div>
          <div class="consumption-metric"><strong>${formatConsumptionDuration(overview.longest_task_ms)}</strong><span>最长任务时长</span></div>
          <div class="consumption-metric"><strong>${formatConsumptionLoginDays(overview.login_days)}</strong><span>登录天数</span></div>`}
        </section>
        <div class="consumption-detail-grid">
          <section class="consumption-calendar-card" aria-busy="${showCalendarSkeleton}">
            <header><h2>${unit === "points" ? "每日积分消耗" : "每日 Token 消耗"}</h2><div class="consumption-color-key"><span>低</span>${[1,2,3,4,5].map((level) => `<i class="level-${level}"></i>`).join("")}<span>高</span></div></header>
            <div class="consumption-calendar-toolbar">
              <button type="button" data-consumption-month="prev" aria-label="上个月" ${state.consumption.loading ? "disabled" : ""}><span aria-hidden="true">‹</span></button>
              <strong>${escapeHtml(consumptionMonthLabel(state.consumption.month))}</strong>
              <button type="button" data-consumption-month="next" aria-label="下个月" ${state.consumption.loading || state.consumption.month >= currentConsumptionMonth() ? "disabled" : ""}><span aria-hidden="true">›</span></button>
            </div>
            ${showCalendarSkeleton ? renderConsumptionCalendarSkeleton() : renderConsumptionCalendar(calendarData.days)}
          </section>
          <section class="consumption-records-card" aria-busy="${showRecordsSkeleton}">
            <header><h2 class="consumption-records-heading"><span>使用明细</span>${state.consumption.selectedDate ? `<small>${escapeHtml(consumptionDateLabel(state.consumption.selectedDate))}</small>` : ""}</h2><div class="consumption-range-toggle">${(["30d","7d","today"] as ConsumptionRange[]).map((range) => `<button type="button" class="${!state.consumption.selectedDate && state.consumption.range === range ? "active" : ""}" data-consumption-range="${range}">${range === "30d" ? "30天" : range === "7d" ? "7天" : "今天"}</button>`).join("")}</div></header>
            ${showRecordsSkeleton ? renderConsumptionRecordsSkeleton() : renderConsumptionRecords(recordsData)}
            ${(state.consumption.loading || state.consumption.historySyncing) && !showRecordsSkeleton ? `<div class="consumption-loading" role="status">正在同步实际账单…</div>` : ""}
          </section>
        </div>
      </div>
    </main>
  `;
}

function renderConsumptionCalendar(rawDays: unknown): string {
  const days = Array.isArray(rawDays) ? rawDays : [];
  const [year, month] = state.consumption.month.split("-").map(Number);
  const offset = new Date(year, month - 1, 1).getDay();
  const mondayOffset = (offset + 6) % 7;
  return `
    <div class="consumption-weekdays">${consumptionWeekdayLabels().map((day) => `<span>${day}</span>`).join("")}</div>
    <div class="consumption-calendar-grid">
      ${Array.from({ length: mondayOffset }, () => `<span class="consumption-calendar-empty"></span>`).join("")}
      ${days.map((item: any) => {
        const dateValue = String(item?.date || "");
        const day = dateValue.slice(-2);
        const tokens = Number(item?.tokens) || 0;
        const points = Number(item?.points ?? item?.usd) || 0;
        const level = Math.min(Math.max(Number(item?.color_level) || 0, 0), 5);
        const selected = state.consumption.selectedDate === dateValue;
        return `<button type="button" class="consumption-day level-${level}${selected ? " selected" : ""}" data-consumption-date="${escapeAttr(dateValue)}" aria-pressed="${selected}" aria-label="查看${escapeAttr(consumptionDateLabel(dateValue))}的使用明细"><strong>${escapeHtml(day)}</strong><span>${escapeHtml(formatConsumptionCalendarAmount(tokens, points))}</span></button>`;
      }).join("")}
    </div>
  `;
}

function consumptionRecordJumpTarget(item: any) {
  return {
    threadId: firstString(
      item?.conversation_id,
      item?.conversationId,
      item?.thread_id,
      item?.threadId,
      item?.desktop_thread_id,
      item?.desktopThreadId,
    ) || "",
    turnId: firstString(item?.interaction_id, item?.interactionId, item?.turn_id, item?.turnId) || "",
    messageId: firstString(item?.user_message_id, item?.userMessageId, item?.message_id, item?.messageId) || "",
    question: firstString(item?.question) || "",
    startedAt: firstString(item?.started_at, item?.startedAt) || "",
  };
}

function openConsumptionRecord(item: any) {
  const target = consumptionRecordJumpTarget(item);
  if (!target.threadId) {
    showToast("该条消费记录缺少原会话定位信息", 2600);
    return;
  }
  requestThreadHistoryJump(
    target.threadId,
    target.messageId || `consumption-record-${target.turnId || stableUiHash(`${target.question}\n${target.startedAt}`)}`,
    "",
    null,
    {
      turnId: target.turnId,
      question: target.question,
      startedAt: target.startedAt,
    },
  );
}

function consumptionStatusFallbackLabel(status: string): string {
  const normalized = status.trim().toLowerCase();
  return (
    (
      {
        complete: "已完成",
        completed: "已完成",
        succeeded: "已完成",
        success: "已完成",
        running: "执行中",
        pending: "待完成",
        waiting: "等待中",
        failed: "失败",
        error: "失败",
        errored: "失败",
        canceled: "已取消",
        cancelled: "已取消",
      } as Record<string, string>
    )[normalized] || "状态未知"
  );
}

function renderConsumptionRecords(data: any): string {
  const items = Array.isArray(data?.items) ? data.items : [];
  if (!items.length) return `<div class="consumption-records-empty">当前时间范围内暂无实际消费记录</div>`;
  const pages = Math.max(Number(data?.pages) || 1, 1);
  const page = Math.min(Math.max(Number(data?.page) || state.consumption.page, 1), pages);
  return `
    <div class="consumption-table-wrap"><table class="consumption-table"><thead><tr><th>实扣${state.consumption.unit === "points" ? "积分" : "Token"}</th><th>计费项目</th><th>实际调用</th><th>任务与计费说明</th></tr></thead><tbody>
      ${items.map((item: any, index: number) => {
        const status = firstString(item?.status) || "unknown";
        const statusLabel =
          firstString(item?.status_label, item?.statusLabel) ||
          consumptionStatusFallbackLabel(status);
        const displayUnit = consumptionRecordDisplayUnit(item);
        const models = Array.isArray(item?.models)
          ? item.models
              .filter((model: unknown) => typeof model === "string" && model.trim())
              .map((model: string) =>
                businessModelDisplayName(businessModelPoolsState, model),
              )
              .join("、")
          : "";
        const startedAt = firstString(item?.started_at);
        const durationMs = Math.max(Number(item?.duration_ms) || 0, 0);
        const question = firstString(item?.question) || "未命名任务";
        const answerExcerpt = firstString(item?.answer_excerpt, item?.answerExcerpt) || "";
        const type = firstString(item?.type) || "-";
        const taskKind = firstString(item?.task_kind, item?.taskKind) || "task";
        const taskKindLabel = firstString(item?.task_kind_label, item?.taskKindLabel) || "主任务";
        const usageEventCount = Math.max(Number(item?.usage_event_count ?? item?.usageEventCount) || 1, 1);
        const durationDisplay = consumptionDurationDisplay(item);
        const durationLabel = firstString(item?.duration_label, item?.durationLabel) || "用时";
        const durationNote = firstString(item?.duration_note, item?.durationNote) || durationDisplay;
        const callSummary = firstString(item?.call_summary, item?.callSummary) || (
          durationDisplay === "时长未完整上报"
            ? `${usageEventCount}次调用 · 时长未完整上报`
            : `${usageEventCount}次调用 · ${durationLabel}${durationDisplay}`
        );
        const billingExplanation =
          firstString(item?.billing_explanation, item?.billingExplanation) ||
          (answerExcerpt ? `实际模型调用已记账 · ${answerExcerpt}` : "实际模型调用已记账");
        const amount = formatConsumptionRecordAmount(item?.tokens, item?.points ?? item?.usd, displayUnit);
        const amountUnit = displayUnit === "points" ? "积分" : "Token";
        return `<tr data-consumption-record-index="${index}" data-started-at="${escapeAttr(startedAt)}" data-duration-ms="${escapeAttr(String(durationMs))}" tabindex="0" role="link" aria-label="${escapeAttr(`${taskKindLabel}：${question}；实扣 ${amount} ${amountUnit}；${callSummary}`)}">
          <td><strong>${escapeHtml(amount)}</strong><small>${escapeHtml(amountUnit)}</small></td>
          <td><span class="consumption-task-kind kind-${escapeAttr(taskKind)}" data-i18n-skip>${escapeHtml(taskKindLabel)}</span><small data-i18n-skip>${escapeHtml(type)}</small></td>
          <td><strong class="consumption-call-model" data-i18n-skip>${escapeHtml(models || "-")}</strong><small data-i18n-skip title="${escapeAttr(durationNote)}">${escapeHtml(callSummary)}</small></td>
          <td><div class="consumption-detail-title"><strong data-i18n-skip>${escapeHtml(question)}</strong><span class="status-${escapeAttr(status)}" data-i18n-skip>${escapeHtml(statusLabel)}</span></div><small data-i18n-skip title="${escapeAttr(billingExplanation)}">${escapeHtml(billingExplanation)}</small></td>
        </tr>`;
      }).join("")}
    </tbody></table></div>
    <nav class="consumption-pagination" aria-label="使用明细分页">
      <button type="button" data-consumption-page="${page - 1}" aria-label="上一页" ${page <= 1 ? "disabled" : ""}><span aria-hidden="true">‹</span></button>
      <span>${page} / ${pages}</span>
      <button type="button" data-consumption-page="${page + 1}" aria-label="下一页" ${page >= pages ? "disabled" : ""}><span aria-hidden="true">›</span></button>
    </nav>
  `;
}

function consumptionRuntimeStateQuery() {
  const activeInteractionIds = new Set<string>();
  const activeConversationIds = new Set<string>();
  const rememberBusyThread = (threadId: string | null | undefined) => {
    const normalizedThreadId = firstString(threadId);
    if (!normalizedThreadId) return;
    const activeTurnId = firstString(activeTurnIdForThread(normalizedThreadId));
    if (activeTurnId) activeInteractionIds.add(activeTurnId);
    else activeConversationIds.add(normalizedThreadId);
  };
  for (const threadId of activeCodexThreadIds) rememberBusyThread(threadId);
  for (const [threadId, busy] of Object.entries(state.providerBusy)) {
    if (busy) rememberBusyThread(threadId);
  }
  for (const [childThreadId, activity] of subagentActivityByThreadId.entries()) {
    if (!activity.busy) continue;
    activeConversationIds.add(childThreadId);
    for (const itemId of activity.itemOrder) {
      const activityItem = activity.items[itemId] as any;
      const turnId = firstString(activityItem?.turnId, activityItem?.turn_id);
      if (turnId) activeInteractionIds.add(turnId);
    }
  }
  return {
    activeInteractionIds: [...activeInteractionIds],
    activeConversationIds: [...activeConversationIds],
  };
}

async function loadConsumptionData(options: { quiet?: boolean; month?: string; suppressError?: boolean; force?: boolean } = {}) {
  if (!state.auth.authenticated) return;
  if (!api.getConsumptionOverview || !api.getConsumptionCalendar || !api.getConsumptionRecords) {
    state.consumption.loading = false;
    if (state.activeView === "consumption") render();
    if (!options.suppressError) showToast("当前客户端版本暂不支持消耗明细接口", 5000);
    return;
  }
  const requestedMonth = options.month ?? consumptionPendingMonth ?? state.consumption.month;
  const requestedUnit = state.consumption.unit;
  const authSnapshot = authProfileRefreshSnapshot();
  const runtimeState = consumptionRuntimeStateQuery();
  const recordsParams = {
    range: state.consumption.range,
    date: state.consumption.selectedDate,
    unit: requestedUnit,
    language: state.settings.language,
    page: state.consumption.page,
    pageSize: state.consumption.pageSize,
    runtimeStateProvided: true,
    activeInteractionIds: runtimeState.activeInteractionIds,
    activeConversationIds: runtimeState.activeConversationIds,
  };
  const requestKey = JSON.stringify({ authSnapshot, requestedMonth, recordsParams });
  if (!options.force && consumptionLoadPromise && consumptionLoadKey === requestKey) return consumptionLoadPromise;
  const requestSeq = ++consumptionRequestSeq;
  consumptionLoadKey = requestKey;
  consumptionPendingMonth = requestedMonth;
  state.consumption.loading = true;
  if (!options.quiet) render();
  const isCurrent = () => requestSeq === consumptionRequestSeq && canApplyProfileRefreshResult(authSnapshot);
  let reportedError = false;
  const loadSection = async (section: "overview" | "calendar" | "records", fetchResult: () => Promise<any>) => {
    try {
      const result = await fetchResult();
      if (!isCurrent()) return;
      state.consumption[section] = consumptionPayload(result);
      // Commit the month together with its days, never with a pending request.
      if (section === "calendar") state.consumption.month = requestedMonth;
      if (state.consumption.overview && state.consumption.calendar && state.consumption.records) {
        state.consumption.loaded = true;
      }
    } catch (error) {
      if (isCurrent() && !options.suppressError && !reportedError) {
        reportedError = true;
        showToast(`消耗明细加载失败：${errorMessage(error)}`, 6000);
      }
    } finally {
      if (isCurrent() && state.activeView === "consumption") render();
    }
  };
  // Only login-day statistics depend on app-enter. Each panel paints as soon as
  // its own request resolves; neither records nor the calendar waits for it.
  const request = Promise.all([
    loadSection("overview", async () => {
      await reportConsumptionAppEntryOnce();
      if (!isCurrent()) return null;
      return api.getConsumptionOverview!({ unit: requestedUnit });
    }),
    loadSection("calendar", () => api.getConsumptionCalendar!({ month: requestedMonth, unit: requestedUnit })),
    loadSection("records", () => api.getConsumptionRecords!(recordsParams)),
  ]).then(() => {
    if (consumptionLoadPromise === request) {
      consumptionLoadPromise = null;
      consumptionLoadKey = "";
      consumptionPendingMonth = null;
    }
    if (!isCurrent()) return;
    state.consumption.loading = false;
    if (state.activeView === "consumption") render();
    if (state.consumption.loaded) void syncConsumptionHistoryInBackground();
  });
  consumptionLoadPromise = request;
  return request;
}

function resetConsumptionData() {
  consumptionRequestSeq += 1;
  consumptionLoadPromise = null;
  consumptionLoadKey = "";
  consumptionPendingMonth = null;
  consumptionPrefetchPromise = null;
  if (consumptionRefreshTimer !== null) window.clearTimeout(consumptionRefreshTimer);
  consumptionRefreshTimer = null;
  state.consumption = {
    ...state.consumption,
    range: "30d", selectedDate: null, month: currentConsumptionMonth(), page: 1,
    loading: false, loaded: false, exporting: false,
    historySyncing: false, historySyncAttempted: false,
    overview: null, calendar: null, records: null,
  };
}

async function syncConsumptionHistoryInBackground() {
  if (!api.syncConsumptionHistory || !state.auth.authenticated || state.consumption.historySyncAttempted) return;
  const consumption = state.consumption;
  const authSnapshot = authProfileRefreshSnapshot();
  consumption.historySyncAttempted = true;
  consumption.historySyncing = true;
  if (state.activeView === "consumption") render();
  try {
    const result = await api.syncConsumptionHistory({ unit: consumption.unit });
    if (consumption !== state.consumption || !canApplyProfileRefreshResult(authSnapshot)) return;
    if (result.synced) {
      // Query the current filters after backfill, even if an older poll is still
      // running. Its pre-backfill response must not replace the refreshed data.
      await loadConsumptionData({ quiet: true, suppressError: true, force: true });
    }
  } catch (error) {
    if (consumption === state.consumption && canApplyProfileRefreshResult(authSnapshot)) {
      console.warn("[consumption] background history sync failed", error);
    }
  } finally {
    if (consumption === state.consumption) {
      consumption.historySyncing = false;
      if (state.activeView === "consumption") render();
    }
  }
}

async function exportConsumptionReport() {
  if (!api.exportConsumptionReport || state.consumption.exporting) return;
  state.consumption.exporting = true;
  render();
  try {
    const result = await api.exportConsumptionReport({ unit: state.consumption.unit });
    if (result?.canceled) return;
    if (!result?.ok) throw new Error("导出未完成");
    showToast(`使用数据已保存：${result.path || "已完成"}`, 7000);
  } catch (error) {
    showToast(`使用数据导出失败：${errorMessage(error)}`, 6000);
  } finally {
    state.consumption.exporting = false;
    if (state.activeView === "consumption") render();
  }
}

function prefetchConsumptionData(): Promise<void> | null {
  if (!state.auth.authenticated || consumptionPrefetchPromise) return consumptionPrefetchPromise;
  if (state.activeView !== "consumption") state.consumption.page = 1;
  const request = loadConsumptionData({ quiet: true, suppressError: true });
  consumptionPrefetchPromise = request;
  void request.finally(() => {
    if (consumptionPrefetchPromise === request) consumptionPrefetchPromise = null;
  });
  return request;
}

function openConsumptionPage() {
  if (state.activeView === "chat") rememberCurrentChatThreadSelection();
  state.settingsOpen = false;
  state.profileMenuOpen = false;
  state.error = null;
  state.activeView = "consumption";
  state.consumption.page = 1;
  const pendingPrefetch = consumptionPrefetchPromise;
  if (!state.consumption.loaded) state.consumption.loading = true;
  else state.consumption.loading = Boolean(consumptionLoadPromise || pendingPrefetch);
  render();
  if (state.consumption.loaded) return;
  if (pendingPrefetch) {
    void pendingPrefetch.then(() => {
      if (state.activeView === "consumption" && !state.consumption.loaded && !state.consumption.loading) {
        void loadConsumptionData();
      }
    });
    return;
  }
  void loadConsumptionData();
}

function syncConsumptionRefreshTimer() {
  if (state.activeView !== "consumption" || !state.auth.authenticated) {
    if (consumptionRefreshTimer !== null) window.clearTimeout(consumptionRefreshTimer);
    consumptionRefreshTimer = null;
    return;
  }
  if (consumptionRefreshTimer !== null) return;
  consumptionRefreshTimer = window.setTimeout(() => {
    consumptionRefreshTimer = null;
    // A slow request (including a month change) must finish before a poll can
    // start another request with the currently displayed filters.
    if (consumptionLoadPromise) {
      syncConsumptionRefreshTimer();
      return;
    }
    if (state.activeView === "consumption") void loadConsumptionData({ quiet: true });
  }, 30_000);
}

