  conversationRows?.addEventListener("click", (event) => {
    const target = event.target instanceof Element ? event.target : null;
    if (!target) return;
    if (
      target.closest(
        "[data-thread-more], [data-thread-group-toggle], [data-thread-group-more]",
      )
    )
      return;
    const row = target.closest<HTMLElement>("[data-thread-row]");
    const id = row?.dataset.threadRow;
    if (id) {
      closeThreadHistoryPopover();
      cancelThreadHistoryJumpNavigation();
      if (isBlankNewThread(id)) {
        state.rightCollapsed = true;
        syncAgentPanelState();
      }
      void selectThread(id);
    }
  });
  conversationRows?.addEventListener("pointerover", (event) => {
    if (event.pointerType && event.pointerType !== "mouse") return;
    const target = event.target instanceof Element ? event.target : null;
    const row = target?.closest<HTMLElement>("[data-thread-row]");
    if (!row || !conversationRows.contains(row)) return;
    if (
      event.relatedTarget instanceof Node &&
      row.contains(event.relatedTarget)
    )
      return;
    beginThreadHistoryHover(row);
  });
  conversationRows?.addEventListener("pointerout", (event) => {
    if (event.pointerType && event.pointerType !== "mouse") return;
    const target = event.target instanceof Element ? event.target : null;
    const row = target?.closest<HTMLElement>("[data-thread-row]");
    const threadId = row?.dataset.threadRow;
    if (!row || !threadId || !conversationRows.contains(row)) return;
    if (
      event.relatedTarget instanceof Node &&
      row.contains(event.relatedTarget)
    )
      return;
    endThreadHistoryHover(threadId, event.relatedTarget);
  });
  conversationRows?.addEventListener("focusin", (event) => {
    const target = event.target instanceof Element ? event.target : null;
    const row = target?.closest<HTMLElement>("[data-thread-row]");
    if (row && conversationRows.contains(row)) beginThreadHistoryHover(row);
  });
  conversationRows?.addEventListener("focusout", (event) => {
    const target = event.target instanceof Element ? event.target : null;
    const row = target?.closest<HTMLElement>("[data-thread-row]");
    const threadId = row?.dataset.threadRow;
    if (!row || !threadId || !conversationRows.contains(row)) return;
    if (
      event.relatedTarget instanceof Node &&
      row.contains(event.relatedTarget)
    )
      return;
    endThreadHistoryHover(threadId, event.relatedTarget);
  });
