function dismissAutoTaskPicker(target: Element | null = null) {
  const activePicker = state.autoTaskPicker;
  if (!activePicker) return false;
  const trigger = root.querySelector<HTMLButtonElement>(`[data-auto-task-picker="${activePicker}"]`);
  const pickerSurface =
    activePicker === "group"
      ? trigger?.closest<HTMLElement>(".auto-task-group-picker")
      : trigger?.closest<HTMLElement>(".auto-task-picker-wrap");
  if (target && pickerSurface?.contains(target)) return false;
  state.autoTaskPicker = null;
  pickerSurface?.classList.remove("open");
  pickerSurface?.querySelector<HTMLElement>(".auto-task-popover")?.remove();
  trigger?.classList.remove("active");
  trigger?.setAttribute("aria-expanded", "false");
  return true;
}

function bindAutoTaskPickerEvents() {
  root.querySelector<HTMLDialogElement>(".auto-task-dialog")?.addEventListener("click", (event) => {
    const target = event.target instanceof Element ? event.target : null;
    dismissAutoTaskPicker(target);
  });
  root.querySelectorAll<HTMLButtonElement>("[data-auto-task-picker]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.stopPropagation();
      updateAutoTaskDraftFromForm();
      const picker = button.dataset.autoTaskPicker as AutoTaskPickerState;
      if (button.disabled || !picker) return;
      state.autoTaskPicker = state.autoTaskPicker === picker ? null : picker;
      if (picker === "date") {
        state.autoTaskCalendarMonth = state.autoTaskDraft.date || dateToInputValue(new Date());
      }
      render();
    });
  });
  root.querySelectorAll<HTMLButtonElement>("[data-auto-task-frequency]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.stopPropagation();
      const value = button.dataset.autoTaskFrequency;
      if (value === "once" || value === "daily" || value === "weekly" || value === "monthly") {
        state.autoTaskDraft.frequency = value;
        state.autoTaskPicker = null;
        state.autoTaskDraft.error = null;
        render();
      }
    });
  });
  root.querySelectorAll<HTMLButtonElement>("[data-auto-task-group]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.stopPropagation();
      const groupId = button.dataset.autoTaskGroup;
      if (!groupId || !threadGroupById(groupId)) return;
      state.autoTaskDraft = {
        ...state.autoTaskDraft,
        groupId,
        importFolderPath: null,
        importFolderName: null,
        error: null,
      };
      state.autoTaskPicker = null;
      void syncThreadGroupWorkspaces({ renderAfter: false });
      render();
    });
  });
  root.querySelectorAll<HTMLButtonElement>("[data-auto-task-month]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.stopPropagation();
      const current = autoTaskCalendarMonthDate();
      current.setMonth(current.getMonth() + (button.dataset.autoTaskMonth === "next" ? 1 : -1));
      state.autoTaskCalendarMonth = dateToInputValue(current);
      state.autoTaskPicker = "date";
      render();
    });
  });
  root.querySelectorAll<HTMLButtonElement>("[data-auto-task-date]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.stopPropagation();
      const value = button.dataset.autoTaskDate || "";
      if (!parseInputDate(value)) return;
      state.autoTaskDraft.date = value;
      state.autoTaskCalendarMonth = value;
      closeAutoTaskPickerAfterSelection();
      render();
    });
  });
  root.querySelectorAll<HTMLButtonElement>("[data-auto-task-hour], [data-auto-task-minute]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.stopPropagation();
      const current = parseAutoTaskTimeValue(state.autoTaskDraft.time);
      const hour = button.dataset.autoTaskHour === undefined ? current.hour : Number(button.dataset.autoTaskHour);
      const minute = button.dataset.autoTaskMinute === undefined ? current.minute : Number(button.dataset.autoTaskMinute);
      const shouldClosePicker = button.dataset.autoTaskMinute !== undefined;
      state.autoTaskDraft.time = autoTaskTimeValue(hour, minute);
      if (shouldClosePicker) {
        closeAutoTaskPickerAfterSelection();
        render();
        return;
      }
      state.autoTaskDraft.error = null;
      state.autoTaskPicker = "time";
      syncAutoTaskTimePickerUi(false);
    });
  });
}

function closeAutoTaskPickerAfterSelection() {
  state.autoTaskPicker = null;
  state.autoTaskDraft.error = null;
}

function syncAutoTaskTimePickerUi(closePicker: boolean) {
  const { hour, minute } = parseAutoTaskTimeValue(state.autoTaskDraft.time);
  const trigger = root.querySelector<HTMLButtonElement>('[data-auto-task-picker="time"]');
  const triggerText = trigger?.querySelector<HTMLElement>("span");
  if (triggerText) triggerText.textContent = state.autoTaskDraft.time || "请选择时间";
  trigger?.classList.toggle("active", !closePicker);
  trigger?.setAttribute("aria-expanded", closePicker ? "false" : "true");
  root.querySelectorAll<HTMLButtonElement>("[data-auto-task-hour]").forEach((option) => {
    option.classList.toggle("selected", Number(option.dataset.autoTaskHour) === hour);
  });
  root.querySelectorAll<HTMLButtonElement>("[data-auto-task-minute]").forEach((option) => {
    option.classList.toggle("selected", Number(option.dataset.autoTaskMinute) === minute);
  });
  if (!state.autoTaskDraft.error) {
    root.querySelector<HTMLElement>(".auto-task-form-error")?.remove();
  }
  if (closePicker) {
    root.querySelector<HTMLElement>(".auto-task-time-panel")?.remove();
  }
}

function handleSkillsPlazaScroll(event: Event) {
  if (!canLoadMoreMarketplaceSkills()) return;
  const page = event.currentTarget as HTMLElement;
  const remaining = page.scrollHeight - page.scrollTop - page.clientHeight;
  if (remaining <= 480) void loadMarketplaceSkills({ append: true, renderAfter: false });
}

function bindLoginEvents() {
  bindWindowControls();
  bindWebsiteSupportEvents();
  bindLoginWechatQrFrameEvents();
  root.querySelector<HTMLFormElement>("#loginForm")?.addEventListener("submit", (event) => {
    event.preventDefault();
    if (state.login.step === "identifier" || state.login.step === "secondary" || state.login.step === "wechatEmail") {
      void sendLoginCode();
    } else if (state.login.step === "code") {
      void verifyLoginCode();
    } else if (state.login.step === "activate") {
      void activateRegisteredUser();
    } else if (state.login.step === "success") {
      void enterAuthenticatedApp();
    }
  });
  root.querySelector<HTMLElement>('[data-action="send-login-code"]')?.addEventListener("click", () => {
    void sendLoginCode();
  });
  root.querySelector<HTMLElement>('[data-action="switch-login-wechat"]')?.addEventListener("click", () => {
    void startLoginWechatFlow("login");
  });
  root.querySelector<HTMLElement>('[data-action="switch-login-otp"]')?.addEventListener("click", () => {
    resetLoginWechatFlow();
    state.login.authMethod = "otp";
    state.login.step = "identifier";
    state.login.error = null;
    render();
  });
  root.querySelector<HTMLElement>('[data-action="back-login-wechat"]')?.addEventListener("click", () => {
    const registrationFlow = state.login.wechatIntent === "register";
    resetLoginWechatFlow();
    state.login.authMethod = "otp";
    state.login.step = registrationFlow ? "activate" : "identifier";
    state.login.error = null;
    render();
  });
  root.querySelector<HTMLElement>('[data-action="open-login-wechat-external"]')?.addEventListener("click", () => {
    const authorizeUrl = state.login.wechatFlow?.authorize_url;
    if (authorizeUrl) void api.openExternal(authorizeUrl);
  });
  root.querySelector<HTMLElement>('[data-action="retry-login-wechat"]')?.addEventListener("click", () => {
    const flowReady = state.login.wechatIntent === "login"
      ? loginWechatFlowExchangeReady(state.login.wechatStatus)
      : loginWechatFlowReady(state.login.wechatStatus);
    if (state.login.wechatFlow && flowReady) {
      if (state.login.wechatIntent === "register") void completeLoginWechatRegistration(state.login.wechatFlow);
      else void exchangeLoginWechatFlow(state.login.wechatFlow);
      return;
    }
    void startLoginWechatFlow(
      state.login.wechatIntent,
      state.login.wechatIntent === "register" ? state.login.registrationToken : undefined,
    );
  });
  root.querySelector<HTMLElement>('[data-action="cancel-login-restore"]')?.addEventListener("click", () => {
    void cancelLoginRestore();
  });
  root.querySelector<HTMLElement>('[data-action="cancel-login-wechat-loading"]')?.addEventListener("click", () => {
    const registrationFlow = state.login.wechatIntent === "register";
    resetLoginWechatFlow();
    state.login.authMethod = "otp";
    state.login.step = registrationFlow ? "activate" : "identifier";
    state.login.error = null;
    state.loading = false;
    render();
  });
  root.querySelectorAll<HTMLElement>('[data-action="focus-login-code"]').forEach((element) => {
    element.addEventListener("click", focusLoginCodeInput);
  });
  root.querySelector<HTMLElement>('[data-action="back-login-email"]')?.addEventListener("click", () => {
    state.login.step = state.login.wechatEmailVerification
      ? "wechatEmail"
      : state.login.verificationStage === "secondary"
        ? "secondary"
        : "identifier";
    state.login.code = "";
    state.login.challenge = null;
    state.login.counter = 0;
    state.login.error = null;
    state.login.busy = null;
    loginModeCheckSeq += 1;
    stopLoginCounter();
    render();
  });
  root.querySelector<HTMLElement>('[data-action="restart-login"]')?.addEventListener("click", () => {
    resetLoginRegistrationFlow();
    render();
  });
  root.querySelector<HTMLElement>('[data-action="choose-login-avatar"]')?.addEventListener("click", () => {
    root.querySelector<HTMLInputElement>("#loginAvatarInput")?.click();
  });
  root.querySelector<HTMLInputElement>("#loginAvatarInput")?.addEventListener("change", (event) => {
    const input = event.currentTarget as HTMLInputElement;
    const file = input.files?.[0];
    if (file) handleLoginAvatarFile(file);
    input.value = "";
  });
  root.querySelector<HTMLElement>('[data-action="open-haolo-home"]')?.addEventListener("click", () => {
    void api.openExternal(HAOLO_HOME_URL);
  });
  root.querySelectorAll<HTMLButtonElement>("[data-legal-url]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const url = button.dataset.legalUrl;
      if (url) void api.openExternal(url);
    });
  });
  root.querySelector<HTMLElement>('[data-action="copy-citizen-id"]')?.addEventListener("click", () => {
    const id = state.login.citizenId || currentProfileShortId();
    if (id) void copyTextToClipboard(id);
  });
  root.querySelector<HTMLInputElement>("#loginIdentifier")?.addEventListener("input", (event) => {
    state.login.identifier = (event.target as HTMLInputElement).value;
    state.login.challenge = null;
    state.login.code = "";
    state.login.nickname = "";
    state.login.inviteCode = "";
    if (state.login.step === "identifier") {
      state.login.channel = "";
      state.login.primaryIdentifier = "";
      state.login.primaryChannel = "";
      state.login.secondaryRequiredChannel = "";
      state.login.verificationStage = "primary";
      state.login.mode = "unknown";
      state.login.inviteRequired = false;
      state.login.nicknameRequired = true;
      state.login.registrationToken = "";
    }
    state.login.error = null;
    loginModeCheckSeq += 1;
    syncLoginSubmitState();
  });
  root.querySelector<HTMLInputElement>("#loginAgreement")?.addEventListener("change", (event) => {
    state.login.agreed = (event.target as HTMLInputElement).checked;
    state.login.error = null;
    syncLoginSubmitState();
  });
  root.querySelector<HTMLInputElement>("#loginNickname")?.addEventListener("input", (event) => {
    state.login.nickname = (event.target as HTMLInputElement).value;
    state.login.error = null;
    syncLoginActivateSubmitState();
  });
  root.querySelector<HTMLInputElement>("#loginInviteCode")?.addEventListener("input", (event) => {
    state.login.inviteCode = (event.target as HTMLInputElement).value.trim();
    state.login.error = null;
    syncLoginActivateSubmitState();
  });
  const loginCodeInput = root.querySelector<HTMLInputElement>("#loginCode");
  loginCodeInput?.addEventListener("keydown", handleLoginCodeKeydown);
  loginCodeInput?.addEventListener("input", handleLoginCodeInput);
  if (state.login.step !== "code") {
    loginCodeFocusToken += 1;
  } else {
    scheduleLoginCodeFocus();
  }
}

function normalizeLoginCode(value: string) {
  return value.replace(/\D/g, "").slice(0, 6);
}

function focusLoginCodeInput() {
  const input = root.querySelector<HTMLInputElement>("#loginCode");
  if (!input || input.disabled) return;
  input.focus({ preventScroll: true });
  const end = input.value.length;
  input.setSelectionRange(end, end);
}

function scheduleLoginCodeFocus() {
  if (state.login.step !== "code") return;
  const token = ++loginCodeFocusToken;
  const focus = () => {
    if (token !== loginCodeFocusToken || state.login.step !== "code") return;
    focusLoginCodeInput();
  };
  window.requestAnimationFrame(focus);
  window.setTimeout(focus, 80);
  window.setTimeout(focus, 220);
}

function handleLoginCodeKeydown(event: KeyboardEvent) {
  if (event.key !== "Backspace" && event.key !== "Delete") return;
  event.preventDefault();
  if (!state.login.code) return;
  state.login.code = state.login.code.slice(0, -1);
  state.login.error = null;
  syncLoginCodeView();
}

function handleLoginCodeInput(event: Event) {
  const input = event.currentTarget as HTMLInputElement;
  state.login.code = normalizeLoginCode(input.value);
  state.login.error = null;
  syncLoginCodeView();
  if (state.login.code.length === 6) {
    void verifyLoginCode();
  }
}

function syncLoginCodeView() {
  const input = root.querySelector<HTMLInputElement>("#loginCode");
  if (input && input.value !== state.login.code) input.value = state.login.code;
  root.querySelectorAll<HTMLElement>(".login-otp-box").forEach((box, index) => {
    box.textContent = state.login.code[index] || "";
    box.classList.toggle("error", Boolean(state.login.error));
    box.classList.toggle("active", index === Math.min(state.login.code.length, 5));
  });
  const error = root.querySelector<HTMLElement>(".login-code-error");
  if (error && !state.login.error) error.remove();
  window.requestAnimationFrame(focusLoginCodeInput);
}

function syncLoginSubmitState() {
  if (state.login.step !== "identifier" && state.login.step !== "secondary" && state.login.step !== "wechatEmail") return;
  const submit = root.querySelector<HTMLButtonElement>(".login-submit");
  if (!submit) return;
  submit.disabled = state.login.busy !== null;
  const error = root.querySelector<HTMLElement>(".login-error");
  if (error && !state.login.error) error.textContent = "";
}

function syncLoginActivateSubmitState() {
  if (state.login.step !== "activate") return;
  const submit = root.querySelector<HTMLButtonElement>(".login-submit");
  if (!submit) return;
  submit.disabled =
    state.login.busy !== null ||
    (state.login.nicknameRequired && !state.login.nickname.trim()) ||
    (state.login.inviteRequired && !state.login.inviteCode.trim());
  const error = root.querySelector<HTMLElement>(".login-code-error");
  if (error && !state.login.error) error.textContent = "";
}

function loginActivationErrorMessage(error: unknown) {
  const message = errorMessage(error);
  if (/INVITE_REQUIRED/i.test(message)) return "请输入邀请码";
  if (/NICKNAME_REQUIRED/i.test(message)) return "请输入昵称";
  if (/NICKNAME_TOO_LONG/i.test(message)) return "昵称不能超过 50 字";
  if (/INVALID_INVITE|INVITE_INVALID|invite code invalid/i.test(message)) return "邀请码不存在";
  if (/CODE_MISMATCH|HTTP\s*401/i.test(message)) return "验证码不正确";
  if (/verification code invalid or expired|CHALLENGE_NOT_FOUND|CHALLENGE_EXPIRED|OTP_EXPIRED/i.test(message)) return "验证码已失效，请重新发送";
  if (/AVATAR_ONLY_FOR_REGISTRATION/i.test(message)) return "头像只能在注册时上传";
  return loginAuthErrorMessage(error);
}

function loginOtpErrorMessage(error: unknown) {
  const message = errorMessage(error);
  if (/CODE_MISMATCH|OTP_MISMATCH|INVALID_CODE|CODE_INVALID|HTTP\s*401/i.test(message)) return "验证码不正确";
  if (/CHALLENGE_NOT_FOUND|CHALLENGE_EXPIRED|OTP_EXPIRED/i.test(message)) return "验证码已失效，请重新发送";
  return message;
}

function loginAuthErrorMessage(error: unknown) {
  const message = loginOtpErrorMessage(error);
  if (/PHONE_IDENTIFIER_REQUIRED|valid phone|phone identifier required/i.test(message)) return "请输入正确的手机号";
  if (/EMAIL_IDENTIFIER_REQUIRED|valid email|email identifier required/i.test(message)) return "请输入正确的邮箱地址";
  if (/OTP_CHANNEL_DISABLED|OTP_CHANNEL_UNSUPPORTED/i.test(message)) return "当前验证码登录方式不可用，请稍后重试";
  if (/SMS_DELIVERY_FAILED|sms delivery failed/i.test(message)) return "短信验证码发送失败，请稍后重试";
  if (/EMAIL_DELIVERY_FAILED|email delivery failed/i.test(message)) return "邮箱验证码发送失败，请稍后重试";
  if (/PHONE_ALREADY_BOUND|phone already bound to another account/i.test(message)) return "该手机号已绑定其他账号，请使用该账号登录";
  if (/EMAIL_ALREADY_BOUND|email already bound to another account/i.test(message)) return "该邮箱已绑定其他账号，请使用该账号登录";
  if (/SECONDARY_IDENTIFIER_CHANNEL_MISMATCH|secondary identifier channel mismatch/i.test(message)) {
    return `请输入要求绑定的${authChannelLabel(secondaryLoginChannel())}`;
  }
  if (/SECONDARY_IDENTIFIER_VERIFICATION_REQUIRED|secondary identifier verification required/i.test(message)) {
    return "请先验证另一个联系方式";
  }
  if (/REGISTRATION_REQUIRES_BOTH|registration requires both email and phone channels/i.test(message)) {
    return "注册需要同时验证手机号和邮箱";
  }
  if (loginWechatBindingConflict(error)) {
    return "该微信或账号已绑定其他账号，请使用原账号登录或联系客服处理";
  }
  if (/wechat client login is not enabled yet/i.test(message)) {
    return "当前服务端版本尚未支持桌面端微信登录，请更新服务端后重试";
  }
  if (/wechat flow invalid|wechat authorization.*expired/i.test(message)) return "微信授权已失效，请重新扫码";
  if (/WECHAT_REGISTRATION_FLOW/i.test(message)) return "该微信二维码用于注册，请重新开始登录";
  if (/REGISTRATION_TOKEN|registration token/i.test(message)) return "注册凭证已失效，请重新开始";
  if (/CAPTCHA_REQUIRED|captcha verification/i.test(message)) return "安全验证暂时不可用，请稍后重试";
  return message;
}

function loginWechatBindingConflict(error: unknown) {
  return /WECHAT_BINDING_CONFLICT|wechat (?:or account )?is already bound/i.test(errorMessage(error));
}

const LOGIN_WECHAT_BINDING_CONFLICT_MESSAGE = "该微信已绑定其他账号，请更换微信扫码";

function syncAgentPanelState() {
  const collapsed = state.rightCollapsed;
  root.querySelector<HTMLElement>(".desktop-body")?.classList.toggle("right-panel-collapsed", collapsed);
  const panel = root.querySelector<HTMLElement>(".agent-panel");
  panel?.classList.toggle("collapsed", collapsed);
  panel?.classList.toggle("expanded", !collapsed);
  panel?.setAttribute("aria-hidden", collapsed ? "true" : "false");

  if (isTradingExpertThreadId(state.currentThreadId) || isExternalTradingWorkspaceThreadId(state.currentThreadId)) {
    const restoreButton = root.querySelector<HTMLButtonElement>(".trading-market-split-panel-restore");
    const label = tradingExpertChartToggleLabel(collapsed);
    restoreButton?.classList.toggle("collapsed", !collapsed);
    restoreButton?.classList.toggle("expanded", collapsed);
    restoreButton?.setAttribute("aria-expanded", String(collapsed));
    restoreButton?.setAttribute("title", label);
    restoreButton?.setAttribute("aria-label", label);
  } else {
    const button = root.querySelector<HTMLButtonElement>('[data-action="toggle-right-panel"]');
    const label = collapsed ? "展开协作看板" : "收起协作看板";
    button?.classList.toggle("expanded", !collapsed);
    button?.setAttribute("aria-expanded", collapsed ? "false" : "true");
    button?.setAttribute("title", label);
    button?.setAttribute("aria-label", label);
  }
  syncTradingExpertCollapseControlsState();
  scheduleWorkflowComposerConnector();
}

function scheduleWorkflowComposerConnector() {
  if (workflowComposerConnectorFrame !== null) return;
  workflowComposerConnectorFrame = window.requestAnimationFrame(() => {
    workflowComposerConnectorFrame = null;
    updateWorkflowComposerConnector();
  });
}

function updateWorkflowComposerConnector() {
  const shell = root.querySelector<HTMLElement>(".cluster-workflow-shell");
  const connector = shell?.querySelector<SVGSVGElement>("[data-workflow-composer-connector]");
  const composer = root.querySelector<HTMLFormElement>("#composerForm");
  const composerPort = composer?.querySelector<HTMLElement>("[data-composer-workflow-port]");
  const viewport = shell?.querySelector<HTMLElement>(".cluster-workflow-viewport");
  const entryNodes = shell
    ? [...shell.querySelectorAll<HTMLElement>('[data-workflow-entry-node="true"]')]
    : [];
  const hideConnectorLines = () => {
    connector?.classList.remove("ready");
    connector?.setAttribute("hidden", "");
  };
  const hideConnector = () => {
    hideConnectorLines();
    composerPort?.setAttribute("hidden", "");
    composerPort?.style.removeProperty("--workflow-port-bridge-width");
  };
  if (
    !shell
    || !connector
    || !composer
    || !composerPort
    || !viewport
    || state.activeView !== "chat"
    || state.rightCollapsed
    || state.chatPreview
    || composer.dataset.threadId !== shell.dataset.workflowThreadId
  ) {
    hideConnector();
    return;
  }

  const shellRect = shell.getBoundingClientRect();
  const composerRect = composer.getBoundingClientRect();
  if (shellRect.width <= 0 || shellRect.height <= 0 || composerRect.width <= 0 || composerRect.height <= 0) {
    hideConnector();
    return;
  }
  composerPort.removeAttribute("hidden");
  const composerPortRect = composerPort.getBoundingClientRect();
  const composerPortCenterX = composerPortRect.left + composerPortRect.width / 2;
  const composerPortCenterY = composerPortRect.top + composerPortRect.height / 2;
  const bridgeWidth = Math.max(0, shellRect.left - composerPortCenterX) + 2;
  const composerConnectionActive = (
    workflowCanvasConnectionDraft?.origin === "composer"
    && workflowCanvasConnectionDraft.threadId === shell.dataset.workflowThreadId
    && workflowCanvasConnectionDraft.runId === shell.dataset.workflowRunId
  );
  composerPort.style.setProperty(
    "--workflow-port-bridge-width",
    entryNodes.length || composerConnectionActive ? `${bridgeWidth}px` : "0px",
  );

  const targetPoints = entryNodes.flatMap((node) => {
    const port = node.querySelector<HTMLElement>(".workflow-node-input");
    const portRect = (port || node).getBoundingClientRect();
    const x = portRect.left + portRect.width / 2 - shellRect.left;
    const y = portRect.top + portRect.height / 2 - shellRect.top;
    const id = String(node.dataset.workflowNodeId || "").trim();
    return id && Number.isFinite(x) && Number.isFinite(y) ? [{ id, x, y }] : [];
  });
  if (!targetPoints.length) {
    hideConnectorLines();
    return;
  }

  const width = shellRect.width;
  const height = shellRect.height;
  const startY = clampNumber(
    composerPortCenterY - shellRect.top,
    18,
    Math.max(18, height - 18),
  );
  const wallTop = 8;
  connector.setAttribute("viewBox", `0 0 ${width} ${height}`);
  connector.setAttribute("width", String(width));
  connector.setAttribute("height", String(height));
  const edgeGroups = [
    ...connector.querySelectorAll<SVGGElement>("[data-workflow-composer-entry-target]"),
  ];
  const canvasNodeRects = [
    ...shell.querySelectorAll<HTMLElement>(".workflow-node[data-workflow-node-id]"),
  ].map((node) => {
    const rect = node.getBoundingClientRect();
    return {
      id: String(node.dataset.workflowNodeId || "").trim(),
      left: rect.left - shellRect.left,
      top: rect.top - shellRect.top,
      right: rect.right - shellRect.left,
      bottom: rect.bottom - shellRect.top,
    };
  });
  for (const point of targetPoints) {
    const group = edgeGroups.find((candidate) => (
      candidate.dataset.workflowComposerEntryTarget === point.id
    ));
    if (!group) continue;
    const route = workflowCanvasComposerBranchRoute({
      entry: { x: 0, y: startY },
      target: point,
      wallTop,
      canvasWidth: width,
      obstacles: canvasNodeRects.filter((rect) => rect.id !== point.id),
    });
    group
      .querySelectorAll<SVGPathElement>(
        "[data-workflow-composer-edge-path], [data-workflow-composer-edge-hit]",
      )
      .forEach((path) => path.setAttribute("d", route.path));
    const deleteWrap = group.querySelector<SVGForeignObjectElement>(
      ".workflow-composer-edge-delete-wrap",
    );
    deleteWrap?.setAttribute("x", String(route.deletePoint.x - 14));
    deleteWrap?.setAttribute("y", String(route.deletePoint.y - 14));
  }
  connector.removeAttribute("hidden");
  connector.classList.add("ready");
}

function bindWorkflowComposerConnector() {
  const shell = root.querySelector<HTMLElement>(".cluster-workflow-shell");
  const composer = root.querySelector<HTMLElement>("#composerForm");
  const viewport = shell?.querySelector<HTMLElement>(".cluster-workflow-viewport");
  if (!workflowComposerConnectorWindowBound) {
    workflowComposerConnectorWindowBound = true;
    window.addEventListener("resize", scheduleWorkflowComposerConnector, { passive: true });
  }
  workflowComposerConnectorResizeObserver?.disconnect();
  workflowComposerConnectorResizeObserver = null;
  if (typeof ResizeObserver === "function" && shell && composer) {
    workflowComposerConnectorResizeObserver = new ResizeObserver(scheduleWorkflowComposerConnector);
    workflowComposerConnectorResizeObserver.observe(shell);
    workflowComposerConnectorResizeObserver.observe(composer);
    if (viewport) workflowComposerConnectorResizeObserver.observe(viewport);
  }
  scheduleWorkflowComposerConnector();
}

function bindWorkflowChatPanelResize(container: ParentNode = root) {
  const handle = container.querySelector<HTMLElement>("[data-workflow-chat-resize]");
  if (!handle || handle.dataset.workflowChatResizeBound === "1") return;
  const desktopBody = handle.closest<HTMLElement>(".desktop-body.multi-model-cluster-layout");
  const chatPanel = desktopBody?.querySelector<HTMLElement>(":scope > .chat-panel");
  const agentPanel = handle.closest<HTMLElement>(".agent-panel");
  const threadId = handle.dataset.workflowThreadId;
  if (!desktopBody || !chatPanel || !agentPanel || !threadId) return;
  handle.dataset.workflowChatResizeBound = "1";

  const resizeBounds = () => {
    const chatRect = chatPanel.getBoundingClientRect();
    const agentRect = agentPanel.getBoundingClientRect();
    const availableWidth = Math.max(0, chatRect.width + agentRect.width);
    return {
      min: WORKFLOW_CHAT_PANEL_MIN_WIDTH,
      max: Math.max(
        WORKFLOW_CHAT_PANEL_MIN_WIDTH,
        availableWidth - WORKFLOW_CANVAS_PANEL_MIN_WIDTH,
      ),
    };
  };
  const applyWidth = (requestedWidth: number) => {
    const { min, max } = resizeBounds();
    const width = Math.round(clampNumber(requestedWidth, min, max));
    workflowChatPanelWidthsByThreadId.set(threadId, width);
    desktopBody.classList.add("workflow-chat-panel-resized");
    desktopBody.style.setProperty("--workflow-chat-panel-width", `${width}px`);
    handle.setAttribute("aria-valuemin", String(Math.round(min)));
    handle.setAttribute("aria-valuemax", String(Math.round(max)));
    handle.setAttribute("aria-valuenow", String(width));
    scheduleWorkflowComposerConnector();
    return width;
  };
  const syncAccessibilityValues = () => {
    const { min, max } = resizeBounds();
    const currentWidth = workflowChatPanelWidthsByThreadId.get(threadId) ?? chatPanel.getBoundingClientRect().width;
    handle.setAttribute("aria-valuemin", String(Math.round(min)));
    handle.setAttribute("aria-valuemax", String(Math.round(max)));
    handle.setAttribute("aria-valuenow", String(Math.round(clampNumber(currentWidth, min, max))));
  };

  const storedWidth = workflowChatPanelWidthsByThreadId.get(threadId);
  if (storedWidth !== undefined) applyWidth(storedWidth);
  else syncAccessibilityValues();

  handle.addEventListener("pointerdown", (event) => {
    if (event.button !== 0 || !event.isPrimary) return;
    event.preventDefault();
    const pointerId = event.pointerId;
    const startX = event.clientX;
    const startWidth = chatPanel.getBoundingClientRect().width;
    desktopBody.classList.add("workflow-chat-panel-resizing");
    handle.classList.add("active");
    handle.setPointerCapture(pointerId);

    const finishResize = () => {
      desktopBody.classList.remove("workflow-chat-panel-resizing");
      handle.classList.remove("active");
      handle.removeEventListener("pointermove", moveResize);
      handle.removeEventListener("pointerup", finishResize);
      handle.removeEventListener("pointercancel", finishResize);
      handle.removeEventListener("lostpointercapture", finishResize);
      if (handle.hasPointerCapture(pointerId)) handle.releasePointerCapture(pointerId);
    };
    const moveResize = (moveEvent: PointerEvent) => {
      if (moveEvent.pointerId !== pointerId) return;
      applyWidth(startWidth + moveEvent.clientX - startX);
    };

    handle.addEventListener("pointermove", moveResize);
    handle.addEventListener("pointerup", finishResize);
    handle.addEventListener("pointercancel", finishResize);
    handle.addEventListener("lostpointercapture", finishResize);
  });

  handle.addEventListener("keydown", (event) => {
    const { min, max } = resizeBounds();
    const currentWidth = workflowChatPanelWidthsByThreadId.get(threadId)
      ?? chatPanel.getBoundingClientRect().width;
    const step = event.shiftKey ? 40 : 16;
    let nextWidth: number | null = null;
    if (event.key === "ArrowLeft") nextWidth = currentWidth - step;
    if (event.key === "ArrowRight") nextWidth = currentWidth + step;
    if (event.key === "Home") nextWidth = min;
    if (event.key === "End") nextWidth = max;
    if (nextWidth === null) return;
    event.preventDefault();
    applyWidth(nextWidth);
  });
}

function bindWorkflowCanvasContextMenu() {
  const viewport = root.querySelector<HTMLElement>(".cluster-workflow-viewport");
  viewport?.addEventListener("contextmenu", (event) => {
    event.preventDefault();
    event.stopPropagation();
    openWorkflowCanvasContextMenu(viewport, event);
  });

  const menu = root.querySelector<HTMLElement>("[data-workflow-canvas-context-menu]");
  menu
    ?.querySelector<HTMLButtonElement>('[data-action="close-workflow-canvas-context-menu"]')
    ?.addEventListener("click", (event) => {
      event.stopPropagation();
      workflowCanvasContextMenu = null;
      render();
    });
  menu?.addEventListener("keydown", (event) => {
    const buttons = [...menu.querySelectorAll<HTMLButtonElement>("button[role='menuitem']")];
    if (event.key === "Escape") {
      event.preventDefault();
      workflowCanvasContextMenu = null;
      render();
      viewport?.focus({ preventScroll: true });
      return;
    }
    if (event.key !== "ArrowDown" && event.key !== "ArrowUp") return;
    event.preventDefault();
    const currentIndex = buttons.findIndex((button) => button === document.activeElement);
    const direction = event.key === "ArrowDown" ? 1 : -1;
    const nextIndex = currentIndex < 0
      ? 0
      : (currentIndex + direction + buttons.length) % buttons.length;
    buttons[nextIndex]?.focus({ preventScroll: true });
  });
  menu?.querySelectorAll<HTMLButtonElement>("[data-workflow-canvas-add]").forEach((button) => {
    button.addEventListener("click", () => {
      const menuState = workflowCanvasContextMenu;
      const kind = button.dataset.workflowCanvasAdd;
      if (!menuState || (kind !== "model" && kind !== "agent")) return;
      const run = workflowCanvasRunWithDraft(menuState.threadId);
      if (!run || run.id !== menuState.runId) {
        workflowCanvasContextMenu = null;
        showToast("画布已经更新，请重新选择插入位置", 2400);
        return;
      }
      button.disabled = true;
      void openWorkflowCanvasPendingNodeEditor(menuState, kind).finally(() => {
        if (button.isConnected) button.disabled = false;
      });
    });
  });
  menu?.querySelectorAll<HTMLButtonElement>("[data-workflow-canvas-history-spec-id]").forEach((button) => {
    button.addEventListener("click", () => {
      const menuState = workflowCanvasContextMenu;
      const specId = String(button.dataset.workflowCanvasHistorySpecId || "").trim();
      const version = Number(button.dataset.workflowCanvasHistorySpecVersion) || 0;
      const spec = workflowReusableSpecs.find((candidate) => (
        candidate.id === specId && candidate.version === version
      ));
      if (!menuState || !spec) {
        showToast("历史画布版本已经变化，请重新选择", 2200);
        return;
      }
      insertWorkflowCanvasNestedSpec(menuState, spec);
    });
  });
}

function bindWebsiteSupportEvents() {
  root.querySelectorAll<HTMLElement>('[data-action="open-website-support"]').forEach((element) => {
    element.addEventListener("click", async () => {
      if (element.getAttribute("aria-busy") === "true") return;
      element.setAttribute("aria-busy", "true");
      if (element instanceof HTMLButtonElement) element.disabled = true;
      try {
        if (api.openWebsiteSupport) {
          await api.openWebsiteSupport();
        } else {
          await api.openExternal(`${HAOLO_HOME_URL}/#support=open`);
        }
      } catch {
        showToast("暂时无法打开网页版客服，请稍后重试。", 3200);
      } finally {
        element.removeAttribute("aria-busy");
        if (element instanceof HTMLButtonElement && element.isConnected) element.disabled = false;
      }
    });
  });
}

function bindAgentStepToggle(details: HTMLDetailsElement | null | undefined) {
  if (!details || details.dataset.agentStepToggleBound === "1") return;
  details.dataset.agentStepToggleBound = "1";
  details.addEventListener("toggle", () => {
    const key = details.dataset.agentStep;
    if (!key) return;
    state.agentStepExpanded[key] = details.open;
  });
}

function bindAgentPanelEvents(container: ParentNode = root) {
  bindWorkflowCanvasSurfaceEvents(container);
  bindWorkflowComposerConnector();
  bindWorkflowChatPanelResize(container);
  bindWorkflowCanvasContextMenu();
  container.querySelectorAll<HTMLDetailsElement>("[data-agent-step]").forEach((details) => {
    bindAgentStepToggle(details);
  });
  container.querySelectorAll<HTMLButtonElement>("[data-subagent-panel-tab]").forEach((button) => {
    button.addEventListener("click", () => selectSubagentPanelTab(button));
    button.addEventListener("keydown", (event) => {
      if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
      const tabs = Array.from(button.closest("[role='tablist']")?.querySelectorAll<HTMLButtonElement>("[data-subagent-panel-tab]") || []);
      const index = tabs.indexOf(button);
      if (index < 0 || tabs.length < 2) return;
      event.preventDefault();
      const offset = event.key === "ArrowRight" ? 1 : -1;
      const next = tabs[(index + offset + tabs.length) % tabs.length];
      selectSubagentPanelTab(next);
      next.focus();
    });
  });
  const workflowScroller = container.querySelector<HTMLElement>(".workflow-scroll-area > .workflow");
  if (workflowScroller && workflowScroller.dataset.scrollBottomBound !== "1") {
    workflowScroller.dataset.scrollBottomBound = "1";
    workflowScroller.addEventListener(
      "scroll",
      () => updateWorkflowScrollBottomButton(workflowScroller),
      { passive: true },
    );
  }
  const workflowScrollBottomButton = container.querySelector<HTMLButtonElement>('[data-action="scroll-workflow-bottom"]');
  if (workflowScrollBottomButton && workflowScrollBottomButton.dataset.scrollBottomBound !== "1") {
    workflowScrollBottomButton.dataset.scrollBottomBound = "1";
    workflowScrollBottomButton.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const area = workflowScrollBottomButton.closest<HTMLElement>(".workflow-scroll-area");
      const scroller = area?.querySelector<HTMLElement>(":scope > .workflow");
      if (scroller) scrollWorkflowToBottom(scroller, { smooth: true });
    });
  }
  if (workflowScroller) scheduleUpdateWorkflowScrollBottomButton(workflowScroller);
}

function selectSubagentPanelTab(button: HTMLButtonElement) {
  const agentThreadId = button.dataset.subagentPanelTab;
  const parentThreadId = state.currentThreadId;
  const board = button.closest<HTMLElement>(".subagent-panel-board");
  if (!agentThreadId || !parentThreadId || !board) return;
  state.subagentPanelSelection[parentThreadId] = agentThreadId;
  board.querySelectorAll<HTMLButtonElement>("[data-subagent-panel-tab]").forEach((tab) => {
    const selected = tab.dataset.subagentPanelTab === agentThreadId;
    tab.classList.toggle("active", selected);
    tab.setAttribute("aria-selected", selected ? "true" : "false");
    tab.tabIndex = selected ? 0 : -1;
  });
  board.querySelectorAll<HTMLElement>("[data-subagent-output-panel]").forEach((panel) => {
    panel.hidden = panel.dataset.subagentOutputPanel !== agentThreadId;
  });
  const selectedAgent = activeSubagentUiEntries(parentThreadId).find((agent) => agent.threadId === agentThreadId);
  if (selectedAgent) scheduleMissingSubagentProcessHistoryHydration(selectedAgent);
  const workflow = board.querySelector<HTMLElement>(".workflow");
  if (workflow) {
    workflow.scrollTop = 0;
    scheduleUpdateWorkflowScrollBottomButton(workflow);
  }
}

function openSubagentInSystemDashboard(agentThreadId: string) {
  const parentThreadId = state.currentThreadId;
  if (!parentThreadId || !agentThreadId) return;
  state.subagentPanelSelection[parentThreadId] = agentThreadId;
  state.rightCollapsed = false;
  syncAgentPanelState();

  const panelTabs = root.querySelectorAll<HTMLButtonElement>("[data-subagent-panel-tab]");
  const matchingTab = Array.from(panelTabs).find((tab) => tab.dataset.subagentPanelTab === agentThreadId);
  if (matchingTab) {
    selectSubagentPanelTab(matchingTab);
    return;
  }
  patchActiveAgentPanel(parentThreadId) || render();
}

function workflowScrollBottomButtonFor(scroller: HTMLElement) {
  return (
    scroller
    .closest<HTMLElement>(".workflow-scroll-area")
    ?.querySelector<HTMLButtonElement>('[data-action="scroll-workflow-bottom"]') ?? null
  );
}

function syncSubagentOutputScrollbarInset(scroller: HTMLElement) {
  if (!scroller.classList.contains("subagent-output-workflow")) return;
  const scrollbarWidth = Math.max(0, scroller.offsetWidth - scroller.clientWidth);
  scroller.style.setProperty("--subagent-output-scrollbar-width", `${scrollbarWidth}px`);
}

function updateWorkflowScrollBottomButton(scroller: HTMLElement) {
  syncSubagentOutputScrollbarInset(scroller);
  const button = workflowScrollBottomButtonFor(scroller);
  if (!button) return;
  const show = messageScrollerDistanceToBottom(scroller) > MESSAGE_SCROLL_BOTTOM_THRESHOLD_PX;
  button.classList.toggle("hidden", !show);
  button.setAttribute("aria-hidden", show ? "false" : "true");
  button.tabIndex = show ? 0 : -1;
}

function scheduleUpdateWorkflowScrollBottomButton(container: ParentNode | HTMLElement = root) {
  const scroller = container instanceof HTMLElement && container.matches(".workflow-scroll-area > .workflow")
    ? container
    : container.querySelector<HTMLElement>(".workflow-scroll-area > .workflow");
  if (!scroller) return;
  updateWorkflowScrollBottomButton(scroller);
  window.requestAnimationFrame(() => updateWorkflowScrollBottomButton(scroller));
  window.setTimeout(() => updateWorkflowScrollBottomButton(scroller), 120);
}

function scrollWorkflowToBottom(scroller: HTMLElement, options: { smooth?: boolean } = {}) {
  scroller.scrollTo({ top: scroller.scrollHeight, behavior: options.smooth ? "smooth" : "auto" });
  updateWorkflowScrollBottomButton(scroller);
  window.requestAnimationFrame(() => updateWorkflowScrollBottomButton(scroller));
  if (options.smooth) window.setTimeout(() => updateWorkflowScrollBottomButton(scroller), 520);
}

function applyWindowState(payload: WindowState | null | undefined) {
  if (!payload) return;
  state.windowMaximized = Boolean(payload.maximized);
  state.windowNativeMaximized = Boolean(payload.nativeMaximized ?? payload.maximized);
  state.windowPinned = Boolean(payload.pinned);
  document.documentElement.classList.toggle("window-maximized", state.windowMaximized);
  document.documentElement.classList.toggle("window-native-maximized", state.windowNativeMaximized);
  syncWindowControlState();
  if (!windowResizeDragActive) {
    syncWindowResizeHandles();
  }
}

function syncWindowControlState() {
  const pinButton = root.querySelector<HTMLButtonElement>('[data-window-action="pin"]');
  const maximizeButton = root.querySelector<HTMLButtonElement>('[data-window-action="maximize"], [data-window-action="restore"]');
  const pinned = state.windowPinned;
  pinButton?.classList.toggle("active", pinned);
  pinButton?.setAttribute("title", pinned ? "取消固定" : "固定");
  pinButton?.setAttribute("aria-label", pinned ? "取消固定" : "固定");
  if (!maximizeButton) return;
  const maximized = state.windowMaximized;
  maximizeButton.classList.toggle("maximized", maximized);
  maximizeButton.innerHTML = renderMaximizeIcon(maximized);
  maximizeButton.dataset.windowAction = maximized ? "restore" : "maximize";
  maximizeButton.setAttribute("title", maximized ? "还原" : "最大化");
  maximizeButton.setAttribute("aria-label", maximized ? "还原窗口" : "最大化");
}

function runWindowCloseAction() {
  if (!runWindowControlAction("hide")) window.close();
}

function runWindowControlAction(action: WindowControlAction) {
  if (typeof api.windowControl !== "function") return false;
  const result = api.windowControl(action);
  if (result && typeof result.then === "function") {
    void result.then(applyWindowState).catch(() => {});
  }
  return true;
}

function bindWindowControls() {
  bindTitlebarWindowDrag();
  root.querySelectorAll<HTMLButtonElement>("[data-window-action]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const action = button.dataset.windowAction as WindowControlAction | undefined;
      if (action === "close") {
        runWindowCloseAction();
        return;
      }
      if (action === "pin" || action === "minimize" || action === "maximize" || action === "restore" || action === "hide") {
        runWindowControlAction(action);
      }
    });
  });
  root.querySelector<HTMLFormElement>("#autoTaskForm")?.addEventListener("submit", (event) => {
    event.preventDefault();
    void submitAutoTaskForm();
  });
}

function bindTitlebarWindowDrag() {
  const titlebar = root.querySelector<HTMLElement>(".app-titlebar");
  if (!titlebar) return;
  titlebar.addEventListener("dblclick", (event) => {
    const target = event.target instanceof Element ? event.target : null;
    if (!isTitlebarDragTarget(target)) return;
    event.preventDefault();
    event.stopPropagation();
    toggleWindowMaximizedFromTitlebar();
  });
  titlebar.addEventListener("pointerdown", (event) => {
    const target = event.target instanceof Element ? event.target : null;
    if (event.button !== 0 || !isTitlebarDragTarget(target)) return;
    event.preventDefault();
    event.stopPropagation();
    if (event.detail >= 2) return;
    if (state.windowNativeMaximized || typeof api.windowMove !== "function") return;
    const pointerId = event.pointerId;
    titlebar.setPointerCapture(pointerId);
    const startPoint = { x: event.screenX, y: event.screenY };
    const startBounds = {
      x: window.screenX,
      y: window.screenY,
      width: window.outerWidth,
      height: window.outerHeight,
    };
    let latestPoint = startPoint;
    let moveFrame: number | null = null;
    const movePayload = (point: { x: number; y: number }): WindowMovePayload => ({
      point,
      startPoint,
      startBounds,
    });
    const flushMove = () => {
      moveFrame = null;
      if (typeof api.windowMoveLive === "function") {
        api.windowMoveLive(movePayload(latestPoint));
        return;
      }
      const result = api.windowMove?.(movePayload(latestPoint));
      if (result && typeof result.then === "function") {
        void result.catch(() => {});
      }
    };
    const move = (nextEvent: PointerEvent) => {
      latestPoint = { x: nextEvent.screenX, y: nextEvent.screenY };
      if (moveFrame === null) {
        moveFrame = window.requestAnimationFrame(flushMove);
      }
    };
    const finish = () => {
      titlebar.removeEventListener("pointermove", move);
      titlebar.removeEventListener("pointerup", finish);
      titlebar.removeEventListener("pointercancel", finish);
      if (moveFrame !== null) {
        window.cancelAnimationFrame(moveFrame);
        moveFrame = null;
        flushMove();
      }
      const result = api.windowMove?.(movePayload(latestPoint));
      if (result && typeof result.then === "function") {
        void result.catch(() => {});
      }
      if (titlebar.hasPointerCapture(pointerId)) {
        titlebar.releasePointerCapture(pointerId);
      }
    };
    titlebar.addEventListener("pointermove", move);
    titlebar.addEventListener("pointerup", finish);
    titlebar.addEventListener("pointercancel", finish);
  });
}

function isTitlebarDragTarget(target: Element | null) {
  return (
    Boolean(target?.closest(".app-titlebar")) && !target?.closest(".window-controls, .titlebar-profile, button, a, input, textarea, select")
  );
}

function attachmentForMediaDisplay(attachment: MessageAttachment) {
  const localPreviewUrl = cachedUploadedAttachmentPreviewUrl(attachment);
  const localPosterUrl = cachedUploadedAttachmentVideoPosterUrl(attachment);
  if (!localPreviewUrl && !localPosterUrl) return attachment;
  const nextAttachment: MessageAttachment & Record<string, unknown> = { ...attachment };
  if (localPreviewUrl) nextAttachment.url = localPreviewUrl;
  if (localPosterUrl) {
    nextAttachment.posterUrl = localPosterUrl;
    nextAttachment.poster_url = localPosterUrl;
  }
  return nextAttachment;
}

function cachedUploadedAttachmentPreviewUrl(attachment: MessageAttachment) {
  if (!isImageAttachment(attachment) && !isVideoAttachment(attachment)) return null;
  const currentUrl = attachment.url || "";
  if (/^(blob:|data:)/i.test(currentUrl)) return null;
  for (const key of attachmentPreviewKeys(attachment)) {
    const previewUrl = uploadedAttachmentPreviewUrls.get(key);
    if (previewUrl) return previewUrl;
  }
  return null;
}

function cachedUploadedAttachmentVideoPosterUrl(attachment: MessageAttachment) {
  if (!isVideoAttachment(attachment)) return null;
  const inlinePosterUrl = videoPosterUrlFromAttachment(attachment);
  if (inlinePosterUrl) return inlinePosterUrl;
  for (const key of attachmentPreviewKeys(attachment)) {
    const posterUrl = uploadedAttachmentVideoPosterUrls.get(key);
    if (posterUrl) return posterUrl;
  }
  return null;
}

function videoPosterUrlFromAttachment(...attachments: Array<Partial<MessageAttachment> | null | undefined>) {
  for (const attachment of attachments) {
    if (!attachment) continue;
    const record = attachment as Record<string, unknown>;
    const posterUrl = firstString(
      record.videoPosterUrl,
      record.video_poster_url,
      record.posterUrl,
      record.poster_url,
      record.coverUrl,
      record.cover_url,
      record.thumbnailUrl,
      record.thumbnail_url,
      record.preview_image_url,
      record.previewImageUrl,
    );
    if (posterUrl) return posterUrl;
  }
  return null;
}

function isEphemeralPreviewUrl(url: string | null | undefined) {
  return /^blob:/i.test(firstString(url) || "");
}

function usableVideoPosterUrl(url: string | null | undefined) {
  const posterUrl = firstString(url);
  if (!posterUrl || failedVideoPosterUrls.has(posterUrl)) return null;
  if (isEphemeralPreviewUrl(posterUrl) && !liveVideoPosterObjectUrls.has(posterUrl)) return null;
  return posterUrl;
}

function revokeVideoPosterObjectUrl(url: string | null | undefined) {
  const posterUrl = firstString(url);
  if (!posterUrl || !isEphemeralPreviewUrl(posterUrl)) return;
  liveVideoPosterObjectUrls.delete(posterUrl);
  failedVideoPosterUrls.delete(posterUrl);
  for (const [key, cachedUrl] of uploadedAttachmentVideoPosterUrls) {
    if (cachedUrl === posterUrl) uploadedAttachmentVideoPosterUrls.delete(key);
  }
  URL.revokeObjectURL(posterUrl);
}

function toggleWindowMaximizedFromTitlebar() {
  if (typeof api.windowControl !== "function") return;
  const action: WindowControlAction = state.windowMaximized ? "restore" : "maximize";
  const result = api.windowControl(action);
  if (result && typeof result.then === "function") {
    void result.then(applyWindowState).catch(() => {});
  }
}

async function addExecutionPlanFromMessageAction(button: HTMLButtonElement) {
  const sourceThreadId = button.dataset.executionPlanThreadId || "";
  const sourceMessageId = button.dataset.executionPlanMessageId || "";
  const sourcePlanKey = button.dataset.executionPlanIndex || "0";
  if (!sourceThreadId || !sourceMessageId) return;
  syncExecutionPlansForCurrentAccount();
  if (state.executionPlans.some((plan) => (
    plan.sourceThreadId === sourceThreadId
    && plan.sourceMessageId === sourceMessageId
    && String(plan.sourcePlanKey || "0") === sourcePlanKey
  ))) {
    button.disabled = true;
    button.setAttribute("aria-disabled", "true");
    button.textContent = "已添加到计划";
    showToast("该计划已经添加");
    return;
  }
  const candidate = executionPlanCandidatesBySource.get(
    executionPlanCandidateKey(sourceThreadId, sourceMessageId, Number(sourcePlanKey) || 0),
  );
  if (!candidate) {
    showToast("暂时无法读取这条执行计划，请刷新后重试");
    return;
  }
  const sourceThread = state.threads.find((thread) => thread.id === sourceThreadId);
  let plan = createSavedExecutionPlan({
    candidate,
    sourceThreadId,
    sourceMessageId,
    sourcePlanKey,
    sourceTitle: sourceThread ? threadListDisplayName(sourceThread) : "来自智能体",
    analysisLabel: tradingLastAnalysisLabelForThread(sourceThreadId),
    language: state.settings.language,
  });
  button.disabled = true;
  button.setAttribute("aria-disabled", "true");
  button.textContent = "正在创建计划与预警…";
  try {
    const alertResult = await syncExecutionPlanLinkedAlert(plan);
    plan = { ...plan, linkedAlertId: alertResult.alertId };
    const nextPlans = [plan, ...state.executionPlans];
    if (!saveExecutionPlans(state.executionPlansScope, nextPlans)) {
      void api.tradingAlertsDelete?.({ alertId: alertResult.alertId })?.catch(() => {});
      throw new Error("计划保存失败，已撤销对应预警");
    }
    state.executionPlans = nextPlans;
    state.executionPlanFilter = "pending";
    state.executionPlanEndMenuId = null;
    button.textContent = `已添加到计划${candidate.content.includes("偏多") ? "（多头）" : candidate.content.includes("偏空") ? "（空头）" : ""}`;
    openExecutionPlansPage();
    if (alertResult.warning) showToast("已添加到计划，入场预警正在等待行情重连", 5000);
    else showToast("已添加到计划");
  } catch (error) {
    button.disabled = false;
    button.removeAttribute("aria-disabled");
    const sideSuffix = candidate.content.includes("偏多") ? "（多头）" : candidate.content.includes("偏空") ? "（空头）" : "";
    button.textContent = `添加到计划${sideSuffix}`;
    showToast(`添加计划失败：${errorMessage(error)}`, 5000);
  }
}

function messageExecutionPlanCardKey(card: HTMLElement) {
  const sourceThreadId = card.dataset.executionPlanThreadId || "";
  const sourceMessageId = card.dataset.executionPlanMessageId || "";
  const candidateIndex = Number(card.dataset.executionPlanIndex) || 0;
  if (!sourceThreadId || !sourceMessageId) return null;
  return {
    sourceThreadId,
    sourceMessageId,
    candidateIndex,
    key: executionPlanCandidateKey(sourceThreadId, sourceMessageId, candidateIndex),
  };
}

function messageExecutionPlanGroupCards(card: HTMLElement) {
  const group = card.closest<HTMLElement>(".message-execution-plan-list");
  if (!group) return [card];
  const cards = Array.from(group.querySelectorAll<HTMLElement>(".message-execution-plan"));
  return cards.length ? cards : [card];
}

function applyMessageExecutionPlanFontSize(card: HTMLElement, fontSize: number) {
  const normalized = saveMessageExecutionPlanFontSize(
    messageExecutionPlanCardKey(card)?.key || "",
    fontSize,
  );
  card.style.setProperty("--message-execution-plan-font-size", `${normalized}px`);
  const min = MESSAGE_EXECUTION_PLAN_FONT_SIZES[0];
  const max = MESSAGE_EXECUTION_PLAN_FONT_SIZES[MESSAGE_EXECUTION_PLAN_FONT_SIZES.length - 1];
  const increase = card.querySelector<HTMLButtonElement>('[data-message-execution-plan-action="increase"]');
  const decrease = card.querySelector<HTMLButtonElement>('[data-message-execution-plan-action="decrease"]');
  if (increase) {
    increase.disabled = normalized >= max;
    increase.setAttribute("aria-disabled", String(increase.disabled));
  }
  if (decrease) {
    decrease.disabled = normalized <= min;
    decrease.setAttribute("aria-disabled", String(decrease.disabled));
  }
  return normalized;
}

function applyMessageExecutionPlanGroupFontSize(card: HTMLElement, delta: number) {
  const source = messageExecutionPlanCardKey(card);
  if (!source) return;
  const current = loadMessageExecutionPlanFontSize(source.key);
  const next = stepMessageExecutionPlanFontSize(current, delta);
  messageExecutionPlanGroupCards(card).forEach((groupCard) => {
    applyMessageExecutionPlanFontSize(groupCard, next);
  });
}

async function createExecutionPlanStickyFromMessageCard(card: HTMLElement) {
  const source = messageExecutionPlanCardKey(card);
  if (!source) throw new Error("暂时无法读取这张执行卡片，请刷新后重试");
  const candidate = executionPlanCandidatesBySource.get(source.key);
  if (!candidate) {
    throw new Error("暂时无法读取这张执行卡片，请刷新后重试");
  }
  if (!api.createExecutionPlanSticky) {
    throw new Error("当前版本暂不支持桌面便利贴");
  }
  const sourceThread = state.threads.find((thread) => thread.id === source.sourceThreadId);
  const title = executionPlanCardTitle({
    fallbackTitle: candidate.title,
    analysisLabel: tradingLastAnalysisLabelForThread(source.sourceThreadId),
    sourceTitle: sourceThread?.name,
    sourceText: candidate.content,
    language: state.settings.language,
  });
  const fontSize = loadMessageExecutionPlanFontSize(source.key);
  const result = await api.createExecutionPlanSticky({
    groupId: `${source.sourceThreadId}\u0000${source.sourceMessageId}`,
    title,
    theme: document.documentElement.dataset.theme === "light" ? "light" : "dark",
    language: state.settings.language,
    fontSize,
    lines: executionPlanDisplayLines(candidate.content).map((line) => ({
      label: line.label,
      text: line.text,
      directionTone: executionPlanDirectionTone(line.label, line.text),
      segments: executionPlanSignedNumberSegments(line.text),
    })),
  });
  if (!result?.created) throw new Error("便利贴窗口未创建");
}

async function createExecutionPlanStickyFromMessageGroup(card: HTMLElement) {
  const cards = messageExecutionPlanGroupCards(card);
  const buttons = cards.flatMap((groupCard) => Array.from(
    groupCard.querySelectorAll<HTMLButtonElement>('[data-message-execution-plan-action="sticky"]'),
  ));
  if (buttons.some((groupButton) => groupButton.getAttribute("aria-busy") === "true")) return;
  buttons.forEach((groupButton) => {
    groupButton.disabled = true;
    groupButton.setAttribute("aria-disabled", "true");
    groupButton.setAttribute("aria-busy", "true");
  });
  try {
    const results = await Promise.allSettled(cards.map((groupCard) => (
      createExecutionPlanStickyFromMessageCard(groupCard)
    )));
    const rejected = results.find((result) => result.status === "rejected");
    if (rejected?.status === "rejected") throw rejected.reason;
    showToast("执行卡片便利贴已固定到桌面");
  } catch (error) {
    showToast(`创建便利贴失败：${errorMessage(error)}`, 5000);
  } finally {
    buttons.forEach((groupButton) => {
      groupButton.disabled = false;
      groupButton.removeAttribute("aria-disabled");
      groupButton.removeAttribute("aria-busy");
    });
  }
}

function bindMessageContentEvents(container: ParentNode = root) {
  container.querySelectorAll<HTMLElement>("[data-open-subagent-thread]").forEach((card) => {
    const openSubagent = () => {
      const agentThreadId = card.dataset.openSubagentThread;
      if (agentThreadId) openSubagentInSystemDashboard(agentThreadId);
    };
    card.addEventListener("click", openSubagent);
    card.addEventListener("keydown", (event) => {
      if (event.key !== "Enter" && event.key !== " ") return;
      event.preventDefault();
      openSubagent();
    });
  });
  container.querySelectorAll<HTMLButtonElement>("[data-message-execution-plan-action]").forEach((button) => {
    if (button.dataset.messageExecutionPlanActionBound === "true") return;
    button.dataset.messageExecutionPlanActionBound = "true";
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const card = button.closest<HTMLElement>(".message-execution-plan");
      const source = card ? messageExecutionPlanCardKey(card) : null;
      if (!card || !source) return;
      const action = button.dataset.messageExecutionPlanAction;
      if (action === "sticky") {
        void createExecutionPlanStickyFromMessageGroup(card);
        return;
      }
      applyMessageExecutionPlanGroupFontSize(card, action === "increase" ? 1 : -1);
    });
  });
  container.querySelectorAll<HTMLButtonElement>("[data-message-action]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const kind = button.dataset.messageActionKind || "";
      if (button.dataset.messageAction === RECHARGE_TOKEN_ACTION_ID || kind === RECHARGE_TOKEN_ACTION_KIND) {
        openRechargePage();
        return;
      }
      if (button.dataset.messageActionDestination === "execution-plans") {
        void addExecutionPlanFromMessageAction(button);
        return;
      }
      if (button.dataset.messageActionDestination === "trading-alerts") {
        openTradingAlertsPage();
        return;
      }
      if (button.dataset.messageActionDestination === "strategies") {
        openMyConfigPage();
        return;
      }
      if (button.dataset.messageActionDestination === "binance-account") {
        openBinanceAccountPage();
        return;
      }
      const conversationId = button.dataset.messageActionConversation;
      if (conversationId) {
        void selectThread(conversationId);
        return;
      }
      const text = button.dataset.messageActionText;
      if (text) {
        state.composerText = text;
        state.composerThreadReferences = [];
        rememberActiveComposerDraft();
        render();
      }
    });
  });
  container.querySelectorAll<HTMLButtonElement>("[data-action='toggle-turn-result']").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const key = button.dataset.turnResultKey;
      if (!key) return;
      state.resultProcessExpanded[key] = !state.resultProcessExpanded[key];
      const subagentPanel = button.closest<HTMLElement>("[data-subagent-output-panel]");
      const childThreadId = subagentPanel?.dataset.subagentOutputPanel;
      const parentThreadId = state.currentThreadId;
      if (childThreadId && parentThreadId) {
        patchActiveSubagentOutputPanel(parentThreadId, childThreadId) || render();
        return;
      }
      updateActiveMessageScroller() || render();
    });
  });
  container.querySelectorAll<HTMLButtonElement>("[data-action='toggle-conversation-supplement-reason']").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      toggleConversationSupplementReason(button.dataset.messageId);
    });
  });
  container.querySelectorAll<HTMLButtonElement>("[data-action='open-thread-continuation']").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const operationId = button.dataset.operationId;
      if (operationId) void openThreadContinuation(operationId);
    });
  });
  container.querySelectorAll<HTMLButtonElement>("[data-message-link]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const url = button.dataset.messageLink || "";
      if (url && isSafeExternalUrl(url)) {
        void api.openExternal(url).catch(() => {
          window.open(url, "_blank", "noopener,noreferrer");
        });
      }
    });
  });
  container.querySelectorAll<HTMLButtonElement>("[data-message-local-path]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const localPath = button.dataset.messageLocalPath;
      if (!localPath || !api.revealLocalFile) return;
      void api.revealLocalFile({ path: localPath, cwd: threadWorkspaceCwd(state.currentThreadId) }).catch((error) => {
        showToast(`打开文件夹失败：${errorMessage(error)}`, 5000);
        });
      });
    });
  container
    .querySelectorAll<HTMLButtonElement>("[data-action='copy-message']")
    .forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const subagentQuote = composerQuoteFromSubagentOutputMessage(
          button.closest<HTMLElement>(".subagent-output-message"),
        );
        if (subagentQuote) {
          void copyPayloadToClipboard({
            kind: "text",
            text: subagentQuote.text,
          });
          return;
        }
        const row = button.closest<HTMLElement>(".message-row");
        const payload = row
          ? messageContextActions(row, { attachmentFallback: true }).copyPayload
          : null;
        if (payload) void copyPayloadToClipboard(payload);
      });
    });
  container
    .querySelectorAll<HTMLButtonElement>("[data-action='favorite-message']")
    .forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const row = button.closest<HTMLElement>(".message-row.from-user");
        const text = row ? favoriteTextFromMessageRow(row) : "";
        if (text) void savePromptFavorite(text);
      });
    });
  container
    .querySelectorAll<HTMLButtonElement>("[data-action='quote-message']")
    .forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const subagentQuote = composerQuoteFromSubagentOutputMessage(
          button.closest<HTMLElement>(".subagent-output-message"),
        );
        applyComposerQuotePayload(
          subagentQuote ||
            composerQuoteFromMessageRow(
              button.closest<HTMLElement>(".message-row"),
            ),
        );
      });
    });
  container
    .querySelectorAll<HTMLButtonElement>("[data-action='edit-message']")
    .forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const autoTaskId = button.closest<HTMLElement>("[data-auto-task-id]")
          ?.dataset.autoTaskId;
        if (
          openAutoTaskEditDialog(
            autoTaskId || taskFromThreadId(state.currentThreadId)?.id,
          )
        )
          return;
        const payload = editPayloadFromMessageRow(
          button.closest<HTMLElement>(".message-row"),
        );
        if (!payload) return;
        applyComposerEditPayload(payload);
        scheduleScrollMessagesToBottom();
      });
    });
  container
    .querySelectorAll<HTMLButtonElement>("[data-action='copy-code']")
    .forEach((button) => {
      button.addEventListener("click", (event) => {
        event.stopPropagation();
        const code =
          button
            .closest(".message-code-block, .message-prompt-text")
            ?.querySelector("code")?.textContent || "";
        if (code) void copyTextToClipboard(code);
      });
    });
  bindAttachmentPreviewEvents(container);
  bindLocalFileDragEvents(container);
}

async function writeTextToClipboard(text: string) {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch {
    return false;
  }
}

async function copyTextToClipboard(text: string) {
  if (!text) return;
  const copyPromise = writeTextToClipboard(text);
  showToast("复制成功", 1500);
  if (await copyPromise) {
    return;
  }
  showToast("复制失败，请手动选择文本", 2500);
}

async function copyPayloadToClipboard(payload: MessageCopyPayload) {
  if (payload.kind === "text") {
    await copyTextToClipboard(payload.text);
    return;
  }
  await copyAttachmentFileToClipboard(payload.file, payload.kind);
}

async function copyAttachmentFileToClipboard(file: PreviewFile, kind: "image" | "file") {
  const normalized = normalizePreviewFile(file);
  const url = normalized.url || "";
  if (!url) {
    showToast(kind === "image" ? "图片没有可复制地址" : "文件没有可复制地址", 2200);
    return;
  }
  try {
    if (!api.copyAttachmentToClipboard) {
      if (kind === "image") {
        await copyImageUrlWithBrowserClipboard(url, normalized.mime);
        showToast("复制成功", 1500);
        return;
      }
      throw new Error("当前环境不支持复制文件");
    }
    const source = await attachmentClipboardSource(url);
    await api.copyAttachmentToClipboard({
      kind,
      name: normalized.name || (kind === "image" ? "image.png" : "attachment"),
      mime: normalized.mime || generatedFileMimeFromPath(normalized.name || url),
      ...source,
    });
    showToast("复制成功", 1500);
  } catch (error) {
    showToast(`${kind === "image" ? "复制图片" : "复制文件"}失败：${errorMessage(error)}`, 3500);
  }
}

async function attachmentClipboardSource(url: string) {
  if (isLocalPreviewUrl(url)) return { path: url };
  if (isRemotePreviewUrl(url)) return { url };
  if (/^(blob:|data:)/i.test(url)) return { base64: await base64FromPreviewUrl(url) };
  throw new Error("附件地址不可用");
}

async function copyImageUrlWithBrowserClipboard(url: string, mime?: string | null) {
  if (typeof ClipboardItem === "undefined") throw new Error("ClipboardItem unavailable");
  const response = await fetch(url);
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  const sourceBlob = await response.blob();
  const imageMime = sourceBlob.type || mime || "image/png";
  const blob = sourceBlob.type ? sourceBlob : sourceBlob.slice(0, sourceBlob.size, imageMime);
  await navigator.clipboard.write([new ClipboardItem({ [imageMime]: blob })]);
}

function bindAttachmentPreviewEvents(container: ParentNode = root) {
  container.querySelectorAll<HTMLImageElement>("[data-video-poster-url]").forEach((image) => {
    const handlePosterError = () => {
      const posterUrl = firstString(image.dataset.videoPosterUrl, image.currentSrc, image.src);
      if (posterUrl) failedVideoPosterUrls.add(posterUrl);
      const file = decodeChatPreviewFile(image.dataset.videoPosterFile || "");
      const videoUrl = firstString(image.dataset.videoSourceUrl);
      image.remove();
      if (file && videoUrl) void ensureVideoPosterResource(file, videoUrl);
    };
    if (image.complete && image.naturalWidth === 0) handlePosterError();
    else image.addEventListener("error", handlePosterError, { once: true });
  });
  container.querySelectorAll<HTMLButtonElement>("[data-chat-preview]").forEach((button) => {
    button.addEventListener("click", () => {
      const file = decodeChatPreviewFile(button.dataset.chatPreview || "");
      if (!file) return;
      if (shouldOpenImageInStandaloneWindow(file)) {
        void openImagePreviewFile(file);
        return;
      }
      pendingMessageScrollAnchor = currentMessageScrollState(button);
      state.chatPreview = { file, zoom: 100, widthPercent: state.chatPreview?.widthPercent };
      state.closingPreviewSource = null;
      state.rightCollapsed = false;
      render();
    });
  });
  container.querySelectorAll<HTMLButtonElement>("[data-attachment-reveal]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.stopPropagation();
      const file = decodePreviewFile(button.dataset.attachmentReveal || "");
      if (file) void revealResultFile(file);
    });
  });
}

function bindLocalFileDragEvents(container: ParentNode = root) {
  container.querySelectorAll<HTMLElement>("[data-file-drag]").forEach((element) => {
    if (element.dataset.fileDragBound === "true") return;
    element.dataset.fileDragBound = "true";
    element.addEventListener("dragstart", (event) => {
      event.stopPropagation();
      if (event.target instanceof Element && event.target.closest(".library-row-actions button, .attachment-hover-actions button")) {
        event.preventDefault();
        return;
      }
      const file = decodePreviewFile(element.dataset.fileDrag || "");
      if (!file?.url || !isLocalPreviewUrl(file.url) || typeof api.startFileDrag !== "function") {
        event.preventDefault();
        return;
      }
      event.preventDefault();
      if (event.dataTransfer) {
        event.dataTransfer.effectAllowed = "copy";
        event.dataTransfer.dropEffect = "copy";
        event.dataTransfer.setData("text/plain", file.url);
      }
      api.startFileDrag({ path: file.url, name: file.name, mime: file.mime || null });
    });
  });
}

function bindWindowResizeHandles() {
  bindWindowResizeScrollbarPassthrough();
  if (windowResizeDragActive) return;
  syncWindowResizeHandles();
}

function supportsVisibleWindowScrollbar(overflow: string) {
  return overflow === "auto" || overflow === "scroll" || overflow === "overlay";
}

function activeWindowScrollbarCandidates() {
  if (!windowScrollbarCandidatesDirty) {
    return windowScrollbarCandidates;
  }
  windowScrollbarCandidatesDirty = false;
  windowScrollbarCandidates = [];
  root.querySelectorAll<HTMLElement>("*").forEach((element) => {
    const style = getComputedStyle(element);
    if (style.getPropertyValue("scrollbar-width").trim() === "none") return;
    const horizontal = supportsVisibleWindowScrollbar(style.overflowX);
    const vertical = supportsVisibleWindowScrollbar(style.overflowY);
    if (!horizontal && !vertical) return;
    windowScrollbarCandidates.push({
      element,
      horizontal,
      vertical,
      direction: style.direction === "rtl" ? "rtl" : "ltr",
    });
  });
  return windowScrollbarCandidates;
}

function configuredWindowScrollbarSize() {
  return (
    Number.parseFloat(
      getComputedStyle(document.documentElement).getPropertyValue("--scrollbar-size"),
    ) || 0
  );
}

function rightEdgeScrollbarAtPoint(clientX: number, clientY: number) {
  if (clientX < window.innerWidth - WINDOW_RESIZE_EDGE_HOT_ZONE) return false;
  const configuredWidth = configuredWindowScrollbarSize();
  return activeWindowScrollbarCandidates().some((candidate) => {
    const scroller = candidate.element;
    if (
      !candidate.vertical ||
      !scroller.isConnected ||
      scroller.scrollHeight <= scroller.clientHeight + 1
    ) {
      return false;
    }
    const rect = scroller.getBoundingClientRect();
    if (
      rect.width <= 0 ||
      rect.height <= 0 ||
      clientY < rect.top ||
      clientY > rect.bottom
    ) {
      return false;
    }
    const scrollbarWidth = Math.max(
      1,
      configuredWidth,
      scroller.offsetWidth - scroller.clientWidth,
    );
    const trackLeft =
      candidate.direction === "rtl" ? rect.left : rect.right - scrollbarWidth;
    const trackRight =
      candidate.direction === "rtl" ? rect.left + scrollbarWidth : rect.right;
    return clientX >= trackLeft && clientX <= trackRight + 1;
  });
}

function bottomEdgeScrollbarAtPoint(clientX: number, clientY: number) {
  if (clientY < window.innerHeight - WINDOW_RESIZE_EDGE_HOT_ZONE) return false;
  const configuredHeight = configuredWindowScrollbarSize();
  return activeWindowScrollbarCandidates().some((candidate) => {
    const scroller = candidate.element;
    if (
      !candidate.horizontal ||
      !scroller.isConnected ||
      scroller.scrollWidth <= scroller.clientWidth + 1
    ) {
      return false;
    }
    const rect = scroller.getBoundingClientRect();
    if (
      rect.width <= 0 ||
      rect.height <= 0 ||
      clientX < rect.left ||
      clientX > rect.right
    ) {
      return false;
    }
    const scrollbarHeight = Math.max(
      1,
      configuredHeight,
      scroller.offsetHeight - scroller.clientHeight,
    );
    return clientY >= rect.bottom - scrollbarHeight && clientY <= rect.bottom + 1;
  });
}

function syncWindowResizeScrollbarInteraction(clientX: number, clientY: number) {
  const right = rightEdgeScrollbarAtPoint(clientX, clientY);
  const bottom = bottomEdgeScrollbarAtPoint(clientX, clientY);
  resizeRoot.classList.toggle("right-scrollbar-interaction", right);
  resizeRoot.classList.toggle("bottom-scrollbar-interaction", bottom);
  return { right, bottom };
}

function windowResizeEdgeOverlapsScrollbar(
  edge: WindowResizeEdge,
  clientX: number,
  clientY: number,
) {
  const interaction = syncWindowResizeScrollbarInteraction(clientX, clientY);
  const usesRightEdge = edge === "e" || edge === "ne" || edge === "se";
  const usesBottomEdge = edge === "s" || edge === "sw" || edge === "se";
  return (
    (usesRightEdge && interaction.right) ||
    (usesBottomEdge && interaction.bottom)
  );
}

function bindWindowResizeScrollbarPassthrough() {
  windowScrollbarCandidatesDirty = true;
  if (!windowScrollbarCandidateObserver) {
    windowScrollbarCandidateObserver = new MutationObserver(() => {
      windowScrollbarCandidatesDirty = true;
    });
    windowScrollbarCandidateObserver.observe(root, {
      attributes: true,
      attributeFilter: ["class", "hidden", "style"],
      childList: true,
      subtree: true,
    });
  }
  if (resizeRoot.dataset.scrollbarPassthroughBound === "1") return;
  resizeRoot.dataset.scrollbarPassthroughBound = "1";
  const clear = () =>
    resizeRoot.classList.remove(
      "right-scrollbar-interaction",
      "bottom-scrollbar-interaction",
    );
  window.addEventListener(
    "pointermove",
    (event) => {
      if (windowResizeDragActive) return;
      syncWindowResizeScrollbarInteraction(event.clientX, event.clientY);
    },
    true,
  );
  window.addEventListener("blur", clear);
}

function windowResizeEdgeFromPoint(clientX: number, clientY: number): WindowResizeEdge | null {
  if (clientX < 0 || clientY < 0 || clientX > window.innerWidth || clientY > window.innerHeight) return null;
  const nearLeft = clientX <= WINDOW_RESIZE_EDGE_HOT_ZONE;
  const nearRight = clientX >= window.innerWidth - WINDOW_RESIZE_EDGE_HOT_ZONE;
  const nearTop = clientY <= WINDOW_RESIZE_TOP_EDGE_HOT_ZONE;
  const nearBottom = clientY >= window.innerHeight - WINDOW_RESIZE_EDGE_HOT_ZONE;
  const cornerLeft = clientX <= WINDOW_RESIZE_CORNER_HOT_ZONE;
  const cornerRight = clientX >= window.innerWidth - WINDOW_RESIZE_CORNER_HOT_ZONE;
  const cornerTop = clientY <= WINDOW_RESIZE_TOP_EDGE_HOT_ZONE;
  const cornerBottom = clientY >= window.innerHeight - WINDOW_RESIZE_CORNER_HOT_ZONE;
  if (cornerTop && cornerLeft) return "nw";
  if (cornerTop && cornerRight) return "ne";
  if (cornerBottom && cornerLeft) return "sw";
  if (cornerBottom && cornerRight) return "se";
  if (nearTop) return "n";
  if (nearBottom) return "s";
  if (nearLeft) return "w";
  if (nearRight) return "e";
  return null;
}

function syncWindowResizeHandles() {
  if (state.windowNativeMaximized || shouldShowLoginWindow()) {
    resizeRoot.innerHTML = "";
    return;
  }
  resizeRoot.innerHTML = renderWindowResizeHandles();
  resizeRoot.querySelectorAll<HTMLElement>("[data-window-resize-edge]").forEach((handle) => {
    const edge = handle.dataset.windowResizeEdge as WindowResizeEdge | undefined;
    if (!edge) return;
    handle.addEventListener("pointerdown", (event) => {
      const activeEdge = windowResizeEdgeFromPoint(event.clientX, event.clientY);
      if (activeEdge !== edge) {
        return;
      }
      if (windowResizeEdgeOverlapsScrollbar(edge, event.clientX, event.clientY)) {
        return;
      }
      event.preventDefault();
      event.stopPropagation();
      if (state.windowNativeMaximized || typeof api.windowResize !== "function") {
        return;
      }
      handle.setPointerCapture(event.pointerId);
      windowResizeDragActive = true;
      const sessionId = `resize-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
      const startPoint = { x: event.screenX, y: event.screenY };
      const startBounds = {
        x: window.screenX,
        y: window.screenY,
        width: window.outerWidth,
        height: window.outerHeight,
      };
      let latestPoint = startPoint;
      let resizeStarted = false;
      let resizeFrame: number | null = null;
      let finished = false;
      const resizePayload = (point: { x: number; y: number }): WindowResizePayload => ({
        edge,
        sessionId,
        point,
        startPoint,
        startBounds,
      });
      const flushResize = () => {
        resizeFrame = null;
        if (typeof api.windowResizeLive === "function") {
          api.windowResizeLive(resizePayload(latestPoint));
          return;
        }
        if (typeof api.windowResize !== "function") return;
        const result = api.windowResize(resizePayload(latestPoint));
        if (result && typeof result.then === "function") {
          void result.catch(() => {});
        }
      };
      const resize = (nextEvent: PointerEvent) => {
        latestPoint = { x: nextEvent.screenX, y: nextEvent.screenY };
        if (!resizeStarted) {
          const distance = Math.hypot(latestPoint.x - startPoint.x, latestPoint.y - startPoint.y);
          if (distance < WINDOW_RESIZE_START_THRESHOLD) return;
          resizeStarted = true;
        }
        if (resizeFrame === null) {
          resizeFrame = window.requestAnimationFrame(flushResize);
        }
      };
      const commitResize = () => {
        if (!resizeStarted) return;
        if (typeof api.windowResize !== "function") return;
        const result = api.windowResize({
          edge,
          sessionId,
          point: latestPoint,
          startPoint,
          startBounds,
        });
        if (result && typeof result.then === "function") {
          void result.catch(() => {});
        }
      };
      const finish = () => {
        if (finished) return;
        finished = true;
        handle.removeEventListener("pointermove", resize);
        handle.removeEventListener("pointerup", finish);
        handle.removeEventListener("pointercancel", finish);
        handle.removeEventListener("lostpointercapture", finish);
        window.removeEventListener("pointerup", finish, true);
        window.removeEventListener("pointercancel", finish, true);
        window.removeEventListener("blur", finish);
        if (resizeFrame !== null) {
          window.cancelAnimationFrame(resizeFrame);
          resizeFrame = null;
          flushResize();
        }
        commitResize();
        if (handle.hasPointerCapture(event.pointerId)) {
          handle.releasePointerCapture(event.pointerId);
        }
        windowResizeDragActive = false;
        window.requestAnimationFrame(() => {
          if (!windowResizeDragActive) {
            syncWindowResizeHandles();
          }
        });
      };
      handle.addEventListener("pointermove", resize);
      handle.addEventListener("pointerup", finish);
      handle.addEventListener("pointercancel", finish);
      handle.addEventListener("lostpointercapture", finish);
      window.addEventListener("pointerup", finish, true);
      window.addEventListener("pointercancel", finish, true);
      window.addEventListener("blur", finish);
    });
  });
}

function updateAutoTaskDraftFromForm() {
  const description = root.querySelector<HTMLTextAreaElement>("#autoTaskDescription")?.value ?? state.autoTaskDraft.description;
  state.autoTaskDraft = {
    ...state.autoTaskDraft,
    description,
    error: null,
  };
}

async function submitAutoTaskForm() {
  updateAutoTaskDraftFromForm();
  const draft = state.autoTaskDraft;
  if (!draft.description.trim()) {
    state.autoTaskDraft.error = "请输入任务说明";
    render();
    return;
  }
  if (draft.frequency !== "daily" && !draft.date) {
    state.autoTaskDraft.error = "请选择日期";
    render();
    return;
  }
  if (!draft.time) {
    state.autoTaskDraft.error = "请选择时间";
    render();
    return;
  }

  const existing = draft.id ? state.autoTaskItems.find((item) => item.id === draft.id) : null;
  const taskId = existing?.id ?? `auto-task-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const importedFolderPath = firstString(draft.importFolderPath);
  const importedGroup = importedFolderPath
    ? upsertExternalThreadGroup(firstString(draft.importFolderName) || folderNameFromPath(importedFolderPath), importedFolderPath)
    : null;
  if (importedGroup) {
    state.autoTaskDraft = {
      ...state.autoTaskDraft,
      groupId: importedGroup.id,
      importFolderPath: null,
      importFolderName: null,
    };
    saveThreadPreferences();
  }
  await syncThreadGroupWorkspaces({ renderAfter: false });
  const groupMeta = autoTaskGroupMetadata(importedGroup?.id || draft.groupId);
  const groupChanged = Boolean(existing && knownThreadGroupId(existing.groupId) !== groupMeta.groupId);
  const threadId = !groupChanged && existing?.threadId && !autoTaskIdFromThreadId(existing.threadId) ? existing.threadId : null;
  const description = draft.description.trim();
  if (existing && groupChanged) {
    delete threadGroupByThreadId[autoTaskThreadId(existing.id)];
    forgetThreadWorkspace(autoTaskThreadId(existing.id));
    if (existing.threadId) {
      delete threadGroupByThreadId[existing.threadId];
      forgetThreadWorkspace(existing.threadId);
    }
  }
  const task: AutoTaskItem = {
    ...existing,
    id: taskId,
    name: autoTaskNameFromDescription(description),
    description,
    ...groupMeta,
    frequency: draft.frequency,
    date: draft.date,
    time: draft.time,
    createdAt: existing?.createdAt ?? new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    enabled: existing?.enabled ?? true,
    status: existing?.enabled === false ? "paused" : "scheduled",
    lastRunAt: existing?.lastRunAt ?? null,
    nextRunAt: null,
    lastError: null,
    lastResult: existing?.lastResult ?? null,
    runCount: existing?.runCount ?? 0,
    threadId,
    executionProfile: "trading-agent-v1",
    tradingContext: currentAutoTaskTradingContext() || existing?.tradingContext || null,
  };
  state.autoTaskItems = existing
    ? state.autoTaskItems.map((item) => (item.id === task.id ? task : item))
    : [task, ...state.autoTaskItems];
  await persistAutoTaskItems();
  const savedTask = state.autoTaskItems.find((item) => item.id === task.id) ?? task;
  const savedThreadId = ensureAutoTaskThreadId(savedTask);
  hiddenThreadIds.delete(savedThreadId);
  focusThreadGroupInConversationList(savedTask.groupId);
  saveThreadPreferences();
  state.autoTaskDialogOpen = false;
  rememberActiveComposerDraft();
  state.activeView = "chat";
  state.currentThreadId = savedThreadId;
  restoreComposerDraftForThread(savedThreadId);
  state.activeTurnId = null;
  rememberChatThreadSelection(savedThreadId);
  state.contactChat.open = false;
  state.selectedAutoTaskId = savedTask.id;
  state.autoTaskMenuTaskId = null;
  syncAutoTaskThreadSummaries();
  ensureThreadState(savedThreadId);
  initializeTradingExpertTaskThread(savedThreadId, { expandPanel: true });
  showToast(`自动任务「${task.name}」已${existing ? "修改" : "创建"}：${formatAutoTaskSchedule(task)}`, 2600);
  state.autoTaskDraft = createAutoTaskDraft(state.activeNewThreadGroupId);
  render();
}

function startChatPreviewResize(event: PointerEvent) {
  if (!state.chatPreview) return;
  event.preventDefault();
  const body = root.querySelector<HTMLElement>(".desktop-body");
  const panel = root.querySelector<HTMLElement>(".chat-preview-panel");
  if (!body || !panel) return;
  document.body.classList.add("resizing-chat-preview");
  const minWidth = 380;
  const maxPercent = 68;
  const minPercent = 32;
  const move = (moveEvent: PointerEvent) => {
    const rect = body.getBoundingClientRect();
    const fixedLeftWidth = 60 + 240;
    const availableWidth = Math.max(1, rect.width - fixedLeftWidth);
    const pointerFromRight = rect.right - moveEvent.clientX;
    const minChatWidth = Math.min(760, Math.max(420, availableWidth * 0.48));
    const maxWidth = Math.max(minWidth, availableWidth - minChatWidth);
    const width = Math.min(Math.max(pointerFromRight, minWidth), maxWidth);
    const percent = Math.min(Math.max((width / rect.width) * 100, minPercent), maxPercent);
    state.chatPreview = { ...state.chatPreview!, widthPercent: percent };
    panel.style.setProperty("--chat-preview-width", `${percent}%`);
  };
  const stop = () => {
    document.body.classList.remove("resizing-chat-preview");
    window.removeEventListener("pointermove", move);
    window.removeEventListener("pointerup", stop);
    window.removeEventListener("pointercancel", stop);
  };
  window.addEventListener("pointermove", move);
  window.addEventListener("pointerup", stop);
  window.addEventListener("pointercancel", stop);
}

