function closeGroupChatDialog() {
  state.groupChatDialog = emptyGroupChatDialogState();
  render();
}

function completeGroupChatDialog() {
  const selected = groupChatSelectedProfiles();
  if (!selected.length) return;
  if (state.groupChatDialog.mode === "remove-members") {
    const record = groupChatDialogTargetRecord();
    if (!record) {
      closeGroupChatDialog();
      return;
    }
    const selectedIds = new Set(
      selected.map((contact) => contactStableId(contact)),
    );
    const removedMembers = localGroupChatUniqueMembers(record).filter(
      (member) => selectedIds.has(member.selectionId),
    );
    if (!removedMembers.length) return;
    removedMembers.forEach((member) => {
      forgetLocalGroupChatHaoloThread(record, member);
    });
    record.members = record.members.filter(
      (member) => !selectedIds.has(member.selectionId),
    );
    state.members[record.id] = record.members.map((member) => ({
      id: "ceo_assistant",
      status: "idle",
      name: member.name,
      avatar_url: member.avatarUrl,
      avatar_text: member.avatarLabel,
    }));
    state.groupChatDialog = emptyGroupChatDialogState();
    removedMembers.forEach((member, index) => {
      appendLocalGroupChatMemberEvent(record, member, "removed", {
        finalize: index === removedMembers.length - 1,
      });
    });
    return;
  }
  const record = groupChatDialogTargetRecord();
  if (!record) {
    closeGroupChatDialog();
    return;
  }
  const members = selected.flatMap((contact) => {
    const member = localGroupChatMemberFromProfile(contact);
    return Array.from(
      { length: groupChatQuantity(contactStableId(contact)) },
      () => ({ ...member }),
    );
  });
  const uniqueMembers = selected.map(localGroupChatMemberFromProfile);
  const existingSelectionIds = new Set(
    record.members.map((member) => member.selectionId),
  );
  const addedMembers = members.filter(
    (member) => !existingSelectionIds.has(member.selectionId),
  );
  const addedUniqueMembers = uniqueMembers.filter(
    (member) => !existingSelectionIds.has(member.selectionId),
  );
  if (!addedMembers.length) return;
  record.members = [...record.members, ...addedMembers];
  state.members[record.id] = record.members.map((member) => ({
    id: "ceo_assistant",
    status: "idle",
    name: member.name,
    avatar_url: member.avatarUrl,
    avatar_text: member.avatarLabel,
  }));
  state.groupChatDialog = emptyGroupChatDialogState();
  addedUniqueMembers.forEach((member, index) => {
    appendLocalGroupChatMemberEvent(record, member, "added", {
      finalize: index === addedUniqueMembers.length - 1,
    });
  });
}

function toggleLocalGroupChatMembersPanel() {
  const record = localGroupChatRecord(state.currentThreadId);
  if (!record) return;
  if (state.chatPreview) {
    record.panelExpanded = false;
    record.updatedAt = record.updatedAt || record.createdAt;
    saveLocalGroupChatRecords();
    closePreviewPanel("chat");
    return;
  }
  state.rightCollapsed = !state.rightCollapsed;
  record.panelExpanded = !state.rightCollapsed;
  record.updatedAt = record.updatedAt || record.createdAt;
  saveLocalGroupChatRecords();
  render();
}

function toggleGroupChatSection(section: string) {
  if (section !== "agents" && section !== "models" && section !== "contacts") return;
  state.groupChatDialog.collapsedSections = {
    ...state.groupChatDialog.collapsedSections,
    [section]: !state.groupChatDialog.collapsedSections[section],
  };
  render();
}

function captureGroupChatDialogScroll() {
  if (!state.groupChatDialog.open) return null;
  return {
    options: root.querySelector<HTMLElement>(".group-chat-options")?.scrollTop ?? 0,
    selected: root.querySelector<HTMLElement>(".group-chat-selected-list")?.scrollTop ?? 0,
  };
}

function restoreGroupChatDialogScroll(snapshot: { options: number; selected: number } | null) {
  if (!snapshot || !state.groupChatDialog.open) return;
  const restore = () => {
    const options = root.querySelector<HTMLElement>(".group-chat-options");
    const selected = root.querySelector<HTMLElement>(".group-chat-selected-list");
    if (options) {
      options.scrollTop = Math.min(
        snapshot.options,
        Math.max(0, options.scrollHeight - options.clientHeight),
      );
    }
    if (selected) {
      selected.scrollTop = Math.min(
        snapshot.selected,
        Math.max(0, selected.scrollHeight - selected.clientHeight),
      );
    }
  };
  restore();
  window.requestAnimationFrame(restore);
}

function toggleGroupChatSelection(selectionId: string) {
  const contact = groupChatSelectableProfiles().find(
    (profile) => contactStableId(profile) === selectionId,
  );
  if (
    !selectionId ||
    !contact ||
    groupChatOptionAlreadyInGroup(selectionId) ||
    groupChatContactCannotJoin(contact)
  ) {
    return;
  }
  const scrollSnapshot = captureGroupChatDialogScroll();
  const selectedIds = state.groupChatDialog.selectedIds;
  state.groupChatDialog.selectedIds = selectedIds.includes(selectionId)
    ? selectedIds.filter((id) => id !== selectionId)
    : [...selectedIds, selectionId];
  render();
  restoreGroupChatDialogScroll(scrollSnapshot);
}

function setGroupChatQuantity(selectionId: string, quantity: number) {
  const contact = groupChatSelectableProfiles().find(
    (profile) => contactStableId(profile) === selectionId,
  );
  if (
    !contact ||
    groupChatOptionAlreadyInGroup(selectionId) ||
    groupChatContactCannotJoin(contact) ||
    !groupChatSupportsQuantity(contact)
  ) {
    return;
  }
  const normalizedQuantity = Math.min(
    GROUP_CHAT_QUANTITY_MAX,
    Math.max(
      GROUP_CHAT_QUANTITY_MIN,
      Math.round(numberValue(quantity) ?? GROUP_CHAT_QUANTITY_MIN),
    ),
  );
  const scrollSnapshot = captureGroupChatDialogScroll();
  state.groupChatDialog.quantities = {
    ...state.groupChatDialog.quantities,
    [selectionId]: normalizedQuantity,
  };
  if (!state.groupChatDialog.selectedIds.includes(selectionId)) {
    state.groupChatDialog.selectedIds = [
      ...state.groupChatDialog.selectedIds,
      selectionId,
    ];
  }
  render();
  restoreGroupChatDialogScroll(scrollSnapshot);
  window.requestAnimationFrame(() => {
    const quantityToggle = Array.from(
      root.querySelectorAll<HTMLElement>("[data-group-chat-quantity-toggle]"),
    ).find((toggle) => toggle.dataset.groupChatQuantityToggle === selectionId);
    quantityToggle?.focus();
  });
}

