function handleChannelAgentNotification(threadId: string | null | undefined, message: JsonRpcMessage) {
  if (!threadId) return false;
  const capture = channelAgentJobs[`capture-${threadId}`] as any;
  if (!capture) return false;
  if (
    message.method === "item/started" &&
    message.params?.item?.type === "agentMessage"
  ) {
    capture.startItem?.(message.params.item);
    return true;
  }
  if (message.method === "item/agentMessage/delta") {
    capture.append?.(
      String(message.params?.delta || ""),
      firstString(message.params?.itemId, message.params?.item_id),
    );
    return true;
  }
  if (
    message.method === "item/completed" &&
    message.params?.item?.type === "agentMessage"
  ) {
    capture.completeItem?.(message.params.item);
    return true;
  }
  if (
    message.method === "turn/completed" ||
    message.method === "turn/failed"
  ) {
    capture.complete?.();
    return true;
  }
  return (
    message.method === "turn/started" ||
    message.method === "thread/status/changed" ||
    message.method === "item/started"
  );
}

async function searchChannelUsers() {
  syncChannelSearchQueryFromInput();
  const query = state.channelDialog.query.trim();
  if (!CHANNELS_ENABLED || !query || !api.searchChannelUsers) {
    channelSearchSeq += 1;
    state.channelDialog.searching = false;
    state.channelDialog.results = [];
    state.channelDialog.searchedQuery = "";
    render();
    return;
  }
  const seq = ++channelSearchSeq;
  state.channelDialog.searching = true;
  state.channelDialog.error = null;
  state.channelDialog.searchedQuery = query;
  render();
  try {
    const result = await api.searchChannelUsers?.({
      q: query,
      channelId: state.channelDialog.channelId || undefined,
      limit: 20,
    });
    if (seq !== channelSearchSeq || !state.channelDialog.open) return;
    state.channelDialog.results = arrayFromResponse<ChannelUserSearchItem>(result).filter((item) => item?.id);
  } catch (error) {
    if (seq !== channelSearchSeq || !state.channelDialog.open) return;
    state.channelDialog.error = `搜索失败：${errorMessage(error)}`;
    state.channelDialog.results = [];
  } finally {
    if (seq === channelSearchSeq && state.channelDialog.open) {
      state.channelDialog.searching = false;
      render();
    }
  }
}

async function searchContactsUsers(queryValue?: string) {
  const query = (queryValue ?? state.contactsSearch).trim().toLowerCase();
  if (!query) {
    contactsSearchSeq += 1;
    state.contactsSearchState = {
      query,
      searchedQuery: "",
      searching: false,
      results: [],
      error: null,
    };
    render();
    return;
  }
  if (!api.searchContacts || !isValidContactSearchQuery(query)) {
    contactsSearchSeq += 1;
    state.contactsSearchState = {
      query,
      searchedQuery: query,
      searching: false,
      results: [],
      error: null,
    };
    state.contactsPanel = "directory";
    state.selectedContactId = null;
    render();
    return;
  }

  const seq = ++contactsSearchSeq;
  state.contactsPanel = "directory";
  state.contactsSearchState = {
    query,
    searchedQuery: query,
    searching: true,
    results: [],
    error: null,
  };
  render();

  try {
    const result = await api.searchContacts({ q: query, limit: 20 });
    if (seq !== contactsSearchSeq || state.contactsSearch.trim().toLowerCase() !== query) return;
    const results = arrayFromResponse<ContactApiUser>(result)
      .map(contactProfileFromApiUser)
      .filter((item): item is ContactProfile => Boolean(item));
    state.contactsSearchState = {
      query,
      searchedQuery: query,
      searching: false,
      results,
      error: null,
    };
    state.contactsPanel = "directory";
    state.selectedContactId = results[0]?.id ?? null;
  } catch (error) {
    if (seq !== contactsSearchSeq || state.contactsSearch.trim().toLowerCase() !== query) return;
    state.contactsSearchState = {
      query,
      searchedQuery: query,
      searching: false,
      results: [],
      error: `搜索失败：${errorMessage(error)}`,
    };
  } finally {
    if (seq === contactsSearchSeq && state.contactsSearch.trim().toLowerCase() === query) {
      render();
      const input = root.querySelector<HTMLInputElement>("#contactsSearch");
      input?.focus();
      input?.setSelectionRange(input.value.length, input.value.length);
    }
  }
}

