function revokeAttachmentPreviews() {
  const previewUrls = new Set<string>();
  const posterUrls = new Set<string>();
  const collect = (attachment: LocalAttachment) => {
    if (attachment.previewUrl?.startsWith("blob:")) previewUrls.add(attachment.previewUrl);
    if (attachment.videoPosterUrl?.startsWith("blob:")) posterUrls.add(attachment.videoPosterUrl);
  };
  state.attachments.forEach(collect);
  Object.values(state.composerDrafts).forEach((draft) => draft.attachments.forEach(collect));
  uploadedAttachmentPreviewUrls.forEach((url) => {
    if (url.startsWith("blob:")) previewUrls.add(url);
  });
  uploadedAttachmentVideoPosterUrls.forEach((url) => {
    if (url.startsWith("blob:")) posterUrls.add(url);
  });
  previewUrls.forEach((url) => URL.revokeObjectURL(url));
  posterUrls.forEach(revokeVideoPosterObjectUrl);
  uploadedAttachmentPreviewUrls.clear();
  uploadedAttachmentVideoPosterUrls.clear();
  failedVideoPosterUrls.clear();
}

