type ProfileActivationRefreshOptions = {
  force?: boolean;
};

function refreshProfileOnAppActivation(options: ProfileActivationRefreshOptions = {}) {
  if (!state.auth.authenticated || document.visibilityState !== "visible") return;
  if (profileActivationRefreshInFlight) return;
  const now = Date.now();
  if (!options.force && now - profileActivationRefreshLastAt < PROFILE_ACTIVATION_REFRESH_MIN_INTERVAL_MS) return;

  profileActivationRefreshLastAt = now;
  profileActivationRefreshInFlight = true;
  void refreshProfileFromApi({
    renderAfter: false,
    reportError: false,
    showRefreshing: false,
  })
    .then((refreshed) => {
      if (refreshed) scheduleRender({ protectComposer: true });
    })
    .catch(() => {
      // Activation refresh is best-effort and must not interrupt the active workspace.
    })
    .finally(() => {
      profileActivationRefreshInFlight = false;
    });
}

async function refreshProfileFromApi(options: { renderAfter?: boolean; reportError?: boolean; showRefreshing?: boolean } = {}) {
  if (!state.auth.authenticated) return false;
  const refreshSnapshot = authProfileRefreshSnapshot();
  const showRefreshing = options.showRefreshing !== false;
  if (showRefreshing) {
    state.profileRefreshing = true;
  }
  if (options.renderAfter) render();
  try {
    const session = await api.refreshProfile();
    if (!canApplyProfileRefreshResult(refreshSnapshot)) return false;
    applyAuthSession(session, state.auth.baseUrl);
    if (!state.auth.authenticated) return false;
    if (typeof api.refreshMemberLevel === "function") {
      const levelRefreshSnapshot = authProfileRefreshSnapshot();
      try {
        const levelResult = await api.refreshMemberLevel();
        if (!canApplyProfileRefreshResult(levelRefreshSnapshot)) return false;
        const levelSession = levelResult?.session || levelResult;
        if (levelSession) {
          applyAuthSession(levelSession, state.auth.baseUrl);
        }
      } catch (error) {
        if (isAuthSessionExpiredError(error)) {
          state.error = null;
        } else if (canApplyProfileRefreshResult(levelRefreshSnapshot)) {
          console.warn("[member-level] profile refresh failed", error);
        }
      }
    }
    return true;
  } catch (error) {
    if (isAuthSessionExpiredError(error)) {
      state.error = null;
    } else if (options.reportError && canApplyProfileRefreshResult(refreshSnapshot)) {
      console.warn("[profile] refresh failed", error);
    }
    return false;
  } finally {
    if (showRefreshing) {
      state.profileRefreshing = false;
    }
    if (options.renderAfter) render();
  }
}

