async function saveProfileEdit() {
  const nickname = state.profileEdit.nickname.trim();
  if (!nickname || state.profileEdit.saving) return;
  const avatarFile = state.profileEdit.avatarFile;
  if (!avatarFile && nickname === currentProfileName()) {
    showToast("个人资料没有变化");
    return;
  }
  state.profileEdit.saving = true;
  state.profileEdit.error = null;
  render();
  try {
    const session = await api.patchProfile({
      nickname,
      avatarStyle: state.auth.profile?.avatar_style ?? "nft-rose",
      avatarFile: avatarFile
        ? {
            name: avatarFile.name || "avatar.png",
            mime: avatarFile.type || "image/png",
            size: avatarFile.size,
            bytes: await avatarFile.arrayBuffer(),
          }
        : null,
    });
    applyAuthSession(session, state.auth.baseUrl);
    syncUserAvatars();
    prepareProfileEditDraft();
    showToast("个人资料已保存");
  } catch (error) {
    state.profileEdit.saving = false;
    state.profileEdit.error = errorMessage(error);
    render();
  }
}

