function handlePreviewAction(action: string, source?: PreviewSource) {
  if (action === "close") {
    closePreviewPanel(source);
    return;
  }

  if (source === "chat") {
    if (state.chatPreview && action === "zoom-in") state.chatPreview.zoom = Math.min(state.chatPreview.zoom + 10, 160);
    if (state.chatPreview && action === "zoom-out") state.chatPreview.zoom = Math.max(state.chatPreview.zoom - 10, 70);
    if (action === "download") void openPreviewFile(state.chatPreview?.file ?? null);
    render();
    return;
  }

  if (source === "material") {
    if (action === "zoom-in") state.materialPreviewZoom = Math.min(state.materialPreviewZoom + 10, 160);
    if (action === "zoom-out") state.materialPreviewZoom = Math.max(state.materialPreviewZoom - 10, 70);
    if (action === "download") void openPreviewFile(currentMaterialPreviewFile());
    render();
    return;
  }

  if (action === "zoom-in") state.resultPreviewZoom = Math.min(state.resultPreviewZoom + 10, 160);
  if (action === "zoom-out") state.resultPreviewZoom = Math.max(state.resultPreviewZoom - 10, 70);
  if (action === "download") void openPreviewFile(currentResultPreviewFile());
  render();
}

function closePreviewPanel(source?: PreviewSource) {
  const target = source ?? "result";
  const chatScrollAnchor = target === "chat" ? currentMessageScrollState() : null;
  if (chatScrollAnchor) pendingMessageScrollAnchor = chatScrollAnchor;
  state.closingPreviewSource = target;
  const panel = root.querySelector<HTMLElement>(`.library-preview-panel[data-preview-panel="${target}"]`);
  panel?.classList.add("collapsed");
  panel?.setAttribute("aria-hidden", "true");
  if (chatScrollAnchor) restoreMessageScrollState(chatScrollAnchor);
  if (previewCloseTimer !== null) {
    window.clearTimeout(previewCloseTimer);
  }
  previewCloseTimer = window.setTimeout(() => {
    previewCloseTimer = null;
    if (state.closingPreviewSource !== target) return;
    if (target === "chat") {
      state.chatPreview = null;
      state.rightCollapsed = true;
    } else if (target === "material") {
      state.materialPreviewClosed = true;
      state.selectedMaterialId = null;
    } else {
      state.resultPreviewClosed = true;
      state.selectedResultId = null;
    }
    state.closingPreviewSource = null;
    render();
  }, PREVIEW_COLLAPSE_MS);
}

function resetLibraryImagePreviewState(source: "result" | "material") {
  if (source === "material") {
    state.selectedMaterialId = null;
    state.materialPreviewClosed = true;
    state.materialPreviewZoom = 100;
    return;
  }
  state.selectedResultId = null;
  state.resultPreviewClosed = true;
  state.resultPreviewZoom = 100;
}

function currentResultPreviewCandidateId() {
  return visibleResultRows()[0]?.id ?? null;
}

function currentMaterialPreviewCandidateId() {
  const localActive =
    state.materialsState.loading || state.materialsState.loaded || Boolean(state.materialsState.error) || state.materials.length > 0;
  const allRows = localActive
    ? state.materials.map(mapMaterialRow).filter((row): row is MaterialRow => Boolean(row))
    : collectMaterialRows();
  return (
    filterMaterialRows(allRows, state.materialsCategory, state.materialsSearch)[0]?.id ?? null
  );
}

function currentResultPreviewFile() {
  const rows = visibleResultRows();
  const row = state.selectedResultId ? (rows.find((item) => item.id === state.selectedResultId) ?? null)
    : null;
  return row ? resultPreviewFile(row) : null;
}

function currentMaterialPreviewFile() {
  if (state.materialPreviewClosed) return null;
  const localActive =
    state.materialsState.loading || state.materialsState.loaded || Boolean(state.materialsState.error) || state.materials.length > 0;
  const allRows = localActive
    ? state.materials.map(mapMaterialRow).filter((row): row is MaterialRow => Boolean(row))
    : collectMaterialRows();
  const rows = filterMaterialRows(allRows, state.materialsCategory, state.materialsSearch);
  const row = state.selectedMaterialId ? (rows.find((item) => item.id === state.selectedMaterialId) ?? null)
    : null;
  return row ? materialPreviewFile(row) : null;
}

function standaloneImagePreviewMime(file: PreviewFile, responseMime?: string | null) {
  return (
    [responseMime, file.mime, generatedFileMimeFromPath(file.name || file.url || "")]
      .map((value) => firstString(value) || "")
      .find((value) => value.toLowerCase().startsWith("image/")) || "image/png"
  );
}

async function openImagePreviewFile(file: PreviewFile | null) {
  file = file ? normalizePreviewFile(file) : null;
  if (!file?.url || file.kind !== "image") return;
  try {
    if (isLocalPreviewUrl(file.url) && api.previewImageFile) {
      await api.previewImageFile({
        path: file.url,
        name: file.name,
        mime: standaloneImagePreviewMime(file),
        theme: state.settings.theme,
        cwd: threadWorkspaceCwd(state.currentThreadId),
      });
      return;
    }

    if (!api.annotateImage) {
      await openPreviewFile(file);
      return;
    }

    if (isLocalPreviewUrl(file.url) && api.readLocalFile) {
      const localFile = await api.readLocalFile({ path: file.url, cwd: threadWorkspaceCwd(state.currentThreadId) });
      await api.annotateImage({
        name: localFile.name || file.name || "image.png",
        mime: standaloneImagePreviewMime(file, localFile.mime),
        base64: localFile.base64,
        theme: state.settings.theme,
      });
      return;
    }

    const remotePreview = isRemotePreviewUrl(file.url)
      ? await api.previewFile({ url: file.url, name: file.name, mime: file.mime || null })
      : null;
    const previewUrl = previewDisplayUrl(file) || file.url;
    const base64 = firstString(remotePreview?.base64) || (await base64FromPreviewUrl(previewUrl));
    await api.annotateImage({
      name: firstString(remotePreview?.name, file.name) || "image.png",
      mime: standaloneImagePreviewMime(file, remotePreview?.mime),
      base64,
      theme: state.settings.theme,
    });
  } catch (error) {
    showToast(`图片预览失败：${errorMessage(error)}`, 5000);
  }
}

async function openPreviewFile(file: PreviewFile | null) {
  file = file ? normalizePreviewFile(file) : null;
  if (!file?.url) return;
  if (isLocalPreviewUrl(file.url)) {
    try {
      if (api.openLocalFile) {
        await api.openLocalFile({ path: file.url, cwd: threadWorkspaceCwd(state.currentThreadId) });
      } else {
        await api.openExternal(file.url);
      }
    } catch (error) {
      showToast(`打开文件失败：${errorMessage(error)}`, 5000);
    }
    return;
  }
  const link = document.createElement("a");
  link.href = file.url;
  link.download = file.name;
  link.rel = "noreferrer";
  link.click();
}

async function revealResultFile(file: PreviewFile) {
  file = normalizePreviewFile(file);
  if (!file.url || !api.revealLocalFile) return;
  try {
    await api.revealLocalFile({ path: file.url, cwd: threadWorkspaceCwd(state.currentThreadId) });
  } catch (error) {
    showToast(`定位文件失败：${errorMessage(error)}`, 5000);
  }
}

async function startThreadWithResultFile(file: PreviewFile, groupId?: string | null) {
  if (!file.url || !api.readLocalFile) return;
  try {
    const sourceCwd = threadWorkspaceCwd(state.currentThreadId);
    const targetGroupId = groupId && threadGroupById(groupId) ? groupId : null;
    const selectedThreadId = targetGroupId ? selectActiveNewThreadGroup(targetGroupId) : null;
    rememberActiveComposerDraft();
    state.activeView = "chat";
    state.chatPreview = null;
    state.closingPreviewSource = null;
    const threadId = selectedThreadId && isBlankNewThread(selectedThreadId) ? selectedThreadId : await startNewThread();
    if (!threadId) return;
    if (threadId !== state.currentThreadId && isBlankNewThread(threadId)) activateBlankThread(threadId);
    clearQueuedAttachments();
    state.composerText = "";
    state.composerQuote = null;
    state.composerThreadReferences = [];
    state.attachments = [];
    resetComposerMentionState();
    setComposerDraft(threadId, { text: "", attachments: [], quote: null, threadReferences: [] });
    const localFile = await api.readLocalFile({ path: file.url, cwd: sourceCwd });
    queueFiles([fileFromLocalRead(localFile)]);
  } catch (error) {
    showToast(`上传成果文件失败：${errorMessage(error)}`, 5000);
  }
}

async function uploadAttachmentToResults(file: PreviewFile) {
  if (!file.url || !api.readLocalFile) return;
  try {
    const localFile = await api.readLocalFile({ path: file.url, cwd: threadWorkspaceCwd(state.currentThreadId) });
    const bytes = bytesFromBase64(localFile.base64);
    await api.uploadMaterialFile({
      name: localFile.name || file.name || "成果文件",
      mime: localFile.mime || file.mime || null,
      size: localFile.size,
      bytes: bytes.buffer as ArrayBuffer,
      folder: "成果库",
      purpose: "artifact",
    });
    mergeUploadedArtifact({
      id: localFile.path,
      path: localFile.path,
      local_path: localFile.path,
      name: localFile.name || file.name,
      title: localFile.name || file.name,
      mime: localFile.mime || file.mime || null,
      size: localFile.size,
      created_at: new Date().toISOString(),
      project: currentThread()?.name || "会话成果",
      conversation_name: currentThread()?.name || "会话成果",
    });
    showToast("已上传到成果库", 2600);
  } catch (error) {
    showToast(`上传到成果库失败：${errorMessage(error)}`, 5000);
  }
}

function fileFromLocalRead(file: { path?: string | null; fileKey?: string | null; name: string; mime?: string | null; size?: number | null; base64: string }) {
  const bytes = bytesFromBase64(file.base64);
  return attachLocalFileMetadata(
    new File([bytes.buffer as ArrayBuffer], file.name || "成果文件", {
      type: file.mime || "application/octet-stream",
      lastModified: Date.now(),
    }),
    {
      path: file.path,
      queueFingerprint: file.fileKey,
    },
  );
}

function attachLocalFileMetadata<T extends File>(file: T, metadata: { path?: string | null; queueFingerprint?: string | null }) {
  attachFileProperty(file, "path", metadata.path);
  attachFileProperty(file, "queueFingerprint", metadata.queueFingerprint);
  return file;
}

function attachFileProperty<T extends File>(file: T, key: string, value?: string | null) {
  if (!value) return;
  try {
    Object.defineProperty(file, key, {
      value,
      configurable: true,
    });
  } catch {
    // Some File objects expose non-configurable platform fields; upload still works.
  }
}

function shouldAvoidFullRenderDuringStream() {
  return hasOpenTransientUi() || isPointerOverStreamSensitiveUi();
}

