function currentBinanceAccountProfitCalendarMonth() {
  const now = new Date();
  return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
}

function navigateBinanceAccountProfitCalendar(offset: -1 | 1) {
  const accountState = state.binanceAccount;
  if (accountState.profitCalendarLoading) return;
  const nextMonth = shiftBinanceAccountProfitCalendarMonth(accountState.profitCalendarMonth, offset);
  if (nextMonth > currentBinanceAccountProfitCalendarMonth()) return;
  accountState.profitCalendarMonth = nextMonth;
  accountState.profitCalendar = null;
  accountState.profitCalendarError = null;
  renderBinanceAccountLiveUpdate();
  void loadBinanceAccountProfitCalendar();
}

async function loadBinanceAccountProfitCalendar({ force = false } = {}) {
  const accountState = state.binanceAccount;
  const getProfitCalendar = api.getBinanceAccountProfitCalendar;
  if (!accountState.status?.bound || accountState.profitCalendarLoading) return;
  if (accountState.profitCalendar?.month === accountState.profitCalendarMonth && !force) return;
  if (!getProfitCalendar) {
    accountState.profitCalendarError = "当前客户端版本不支持收益日历。";
    renderBinanceAccountLiveUpdate();
    return;
  }
  const month = accountState.profitCalendarMonth;
  const loadSequence = ++binanceAccountProfitCalendarLoadSequence;
  accountState.profitCalendarLoading = true;
  accountState.profitCalendarError = null;
  renderBinanceAccountLiveUpdate();
  try {
    const calendar = await getProfitCalendar({ month, force });
    if (
      loadSequence !== binanceAccountProfitCalendarLoadSequence
      || state.binanceAccount !== accountState
      || accountState.profitCalendarMonth !== month
    ) return;
    accountState.profitCalendar = calendar;
  } catch (error) {
    if (
      loadSequence !== binanceAccountProfitCalendarLoadSequence
      || state.binanceAccount !== accountState
      || accountState.profitCalendarMonth !== month
    ) return;
    accountState.profitCalendarError = errorMessage(error);
  } finally {
    if (
      loadSequence !== binanceAccountProfitCalendarLoadSequence
      || state.binanceAccount !== accountState
      || accountState.profitCalendarMonth !== month
    ) return;
    accountState.profitCalendarLoading = false;
    renderBinanceAccountLiveUpdate();
  }
}

async function loadBinanceAccountPage() {
  const accountState = state.binanceAccount;
  const getAccountStatus = api.getBinanceAccountStatus;
  const getAccountSnapshot = api.getBinanceAccountSnapshot;
  const hasCachedView = Boolean(
    accountState.loaded
    && accountState.status
    && (!accountState.status.bound || accountState.snapshot),
  );
  if (!getAccountStatus) {
    accountState.loading = false;
    if (!hasCachedView) accountState.loaded = false;
    accountState.error = "当前客户端版本不支持 Binance 账户连接。";
    if (state.activeView === "account") render();
    return;
  }
  if (
    Date.now() < accountState.autoRefreshAfter
    && (hasCachedView || Boolean(accountState.error))
  ) return;
  if (binanceAccountLoadPromise) return binanceAccountLoadPromise;

  const loadSequence = ++binanceAccountLoadSequence;
  const request = (async () => {
    accountState.loading = !hasCachedView;
    if (!hasCachedView) accountState.error = null;
    if (accountState.loading && state.activeView === "account") render();
    try {
      const status = await getAccountStatus();
      if (loadSequence !== binanceAccountLoadSequence) return;
      accountState.status = status;
      let snapshot: BinanceAccountSnapshot | null = null;
      if (status.bound) {
        if (!getAccountSnapshot) throw new Error("当前客户端无法读取 Binance 账户数据。");
        snapshot = await getAccountSnapshot();
      }
      if (loadSequence !== binanceAccountLoadSequence) return;
      accountState.snapshot = snapshot;
      syncTradingExpertOrderLineSnapshot(snapshot);
      await reconcileExecutionPlansWithBinanceSnapshot(snapshot);
      accountState.loaded = true;
      accountState.error = null;
      accountState.autoRefreshAfter = Date.now() + BINANCE_ACCOUNT_AUTO_REFRESH_INTERVAL_MS;
      binanceAccountFullRefreshAfter = Date.now() + BINANCE_ACCOUNT_AUTO_REFRESH_INTERVAL_MS;
      binanceAccountLiveRefreshFailures = 0;
      binanceAccountLiveRetryAfter = 0;
      if (status.bound && accountState.activeSection === "profit-calendar") {
        void loadBinanceAccountProfitCalendar();
      }
    } catch (error) {
      if (loadSequence !== binanceAccountLoadSequence) return;
      binanceAccountLiveRefreshFailures += 1;
      const retryDelay = binanceAccountRetryDelay(error, binanceAccountLiveRefreshFailures);
      if (hasCachedView) {
        accountState.loaded = true;
        accountState.error = `账户数据暂时未更新，仍显示上次成功数据：${errorMessage(error)}`;
        accountState.autoRefreshAfter = Date.now() + Math.max(BINANCE_ACCOUNT_AUTO_RETRY_INTERVAL_MS, retryDelay);
      } else {
        accountState.loaded = false;
        accountState.error = errorMessage(error);
        accountState.autoRefreshAfter = Date.now() + Math.max(BINANCE_ACCOUNT_AUTO_RETRY_INTERVAL_MS, retryDelay);
      }
      binanceAccountLiveRetryAfter = Date.now() + retryDelay;
    } finally {
      if (loadSequence !== binanceAccountLoadSequence) return;
      accountState.loading = false;
      if (state.activeView === "account") render();
    }
  })();
  binanceAccountLoadPromise = request;
  try {
    await request;
  } finally {
    if (binanceAccountLoadPromise === request) binanceAccountLoadPromise = null;
  }
}

async function refreshBinanceAccountSnapshot() {
  if (
    !api.getBinanceAccountSnapshot
    || state.binanceAccount.refreshing
    || state.binanceAccount.profitCalendarLoading
    || binanceAccountProgressiveRefreshPromise
  ) return;
  const accountState = state.binanceAccount;
  const loadSequence = binanceAccountLoadSequence;
  const snapshotApplySequence = ++binanceAccountSnapshotApplySequence;
  const refreshSlowData = Date.now() >= binanceAccountFullRefreshAfter
    && accountState.activeSection !== "profit-calendar"
    && !accountState.profitCalendarLoading;
  const refreshProfitCalendar = accountState.activeSection === "profit-calendar";
  accountState.refreshing = true;
  accountState.error = null;
  if (state.activeView === "account") render();
  try {
    const snapshot = await api.getBinanceAccountSnapshot({
      force: true,
      live: true,
      summary: true,
    });
    if (
      loadSequence !== binanceAccountLoadSequence
      || snapshotApplySequence !== binanceAccountSnapshotApplySequence
      || state.binanceAccount !== accountState
      || !accountState.status?.bound
    ) return;
    accountState.snapshot = snapshot;
    syncTradingExpertOrderLineSnapshot(snapshot);
    accountState.loaded = true;
    accountState.autoRefreshAfter = Date.now() + BINANCE_ACCOUNT_AUTO_REFRESH_INTERVAL_MS;
    binanceAccountLiveRefreshFailures = 0;
    binanceAccountLiveRetryAfter = 0;
    accountState.refreshing = false;
    renderBinanceAccountLiveUpdate();
    void progressivelyRefreshBinanceAccountSnapshot(
      accountState,
      loadSequence,
      snapshotApplySequence,
      refreshSlowData,
    );
    if (refreshProfitCalendar) void loadBinanceAccountProfitCalendar({ force: true });
  } catch (error) {
    if (
      loadSequence !== binanceAccountLoadSequence
      || snapshotApplySequence !== binanceAccountSnapshotApplySequence
      || state.binanceAccount !== accountState
    ) return;
    accountState.error = errorMessage(error);
    binanceAccountLiveRefreshFailures += 1;
    const retryDelay = binanceAccountRetryDelay(error, binanceAccountLiveRefreshFailures);
    accountState.autoRefreshAfter = Date.now() + Math.max(BINANCE_ACCOUNT_AUTO_RETRY_INTERVAL_MS, retryDelay);
    binanceAccountLiveRetryAfter = Date.now() + retryDelay;
    showToast(`Binance 账户刷新失败：${accountState.error}`, 5000);
  } finally {
    if (state.binanceAccount === accountState) accountState.refreshing = false;
    if (state.activeView === "account") render();
    scheduleBinanceAccountLiveRefresh();
  }
}

async function progressivelyRefreshBinanceAccountSnapshot(
  accountState: BinanceAccountUiState,
  loadSequence: number,
  snapshotApplySequence: number,
  refreshSlowData: boolean,
) {
  if (!api.getBinanceAccountSnapshot || binanceAccountProgressiveRefreshPromise) return;
  const isCurrentAccount = () => (
    loadSequence === binanceAccountLoadSequence
    && snapshotApplySequence === binanceAccountSnapshotApplySequence
    && state.binanceAccount === accountState
    && accountState.status?.bound === true
  );
  const request = (async () => {
    try {
      const liveSnapshot = await api.getBinanceAccountSnapshot!({ force: true, live: true });
      if (!isCurrentAccount()) return;
      accountState.snapshot = liveSnapshot;
      syncTradingExpertOrderLineSnapshot(liveSnapshot);
      accountState.loaded = true;
      accountState.error = null;
      accountState.autoRefreshAfter = Date.now() + BINANCE_ACCOUNT_AUTO_REFRESH_INTERVAL_MS;
      binanceAccountLiveRefreshFailures = 0;
      binanceAccountLiveRetryAfter = 0;
      renderBinanceAccountLiveUpdate();
      await reconcileExecutionPlansWithBinanceSnapshot(liveSnapshot);
      if (!isCurrentAccount()) return;
      if (
        !refreshSlowData
        || accountState.activeSection === "profit-calendar"
        || accountState.profitCalendarLoading
      ) return;

      const fullSnapshot = await api.getBinanceAccountSnapshot!({ force: true, live: false });
      if (!isCurrentAccount()) return;
      accountState.snapshot = fullSnapshot;
      syncTradingExpertOrderLineSnapshot(fullSnapshot);
      accountState.loaded = true;
      accountState.error = null;
      accountState.autoRefreshAfter = Date.now() + BINANCE_ACCOUNT_AUTO_REFRESH_INTERVAL_MS;
      binanceAccountFullRefreshAfter = Date.now() + BINANCE_ACCOUNT_AUTO_REFRESH_INTERVAL_MS;
      binanceAccountLiveRefreshFailures = 0;
      binanceAccountLiveRetryAfter = 0;
      renderBinanceAccountLiveUpdate();
      await reconcileExecutionPlansWithBinanceSnapshot(fullSnapshot);
    } catch (error) {
      if (!isCurrentAccount()) return;
      binanceAccountLiveRefreshFailures += 1;
      binanceAccountLiveRetryAfter = Date.now()
        + binanceAccountRetryDelay(error, binanceAccountLiveRefreshFailures);
      binanceAccountFullRefreshAfter = 0;
      console.warn("[binance-account] progressive refresh deferred", errorMessage(error));
    }
  })();
  binanceAccountProgressiveRefreshPromise = request;
  try {
    await request;
  } finally {
    if (binanceAccountProgressiveRefreshPromise === request) {
      binanceAccountProgressiveRefreshPromise = null;
    }
    scheduleBinanceAccountLiveRefresh();
  }
}

function stopBinanceAccountLiveRefresh() {
  if (binanceAccountLiveRefreshTimer === null) return;
  window.clearTimeout(binanceAccountLiveRefreshTimer);
  binanceAccountLiveRefreshTimer = null;
}

function binanceAccountReadOnlyDataVisible() {
  return executionPlanBinanceMonitoringNeeded()
    || state.activeView === "account"
    || (
      state.activeView === "chat"
      && !state.chatPreview
      && isTradingExpertThreadId(state.currentThreadId)
    );
}

function binanceAccountLiveRefreshInterval() {
  if (executionPlanBinanceMonitoringNeeded()) {
    return BINANCE_ACCOUNT_EXECUTION_PLAN_LIVE_REFRESH_INTERVAL_MS;
  }
  return state.activeView === "account"
    ? BINANCE_ACCOUNT_LIVE_REFRESH_INTERVAL_MS
    : BINANCE_ACCOUNT_TRADING_LIVE_REFRESH_INTERVAL_MS;
}

function binanceAccountRetryDelay(error: unknown, failureCount: number) {
  const exponentialDelay = Math.min(
    BINANCE_ACCOUNT_LIVE_RETRY_MAX_INTERVAL_MS,
    BINANCE_ACCOUNT_LIVE_RETRY_BASE_INTERVAL_MS * (2 ** Math.max(0, failureCount - 1)),
  );
  const retryAfterMs = Number((error as { retryAfterMs?: unknown } | null)?.retryAfterMs);
  if (!Number.isFinite(retryAfterMs) || retryAfterMs <= 0) return exponentialDelay;
  return Math.max(exponentialDelay, Math.min(24 * 60 * 60_000, retryAfterMs + 500));
}

function scheduleBinanceAccountLiveRefresh(delayMs = binanceAccountLiveRefreshInterval()) {
  stopBinanceAccountLiveRefresh();
  if (
    !binanceAccountReadOnlyDataVisible()
    || (document.hidden && !executionPlanBinanceMonitoringNeeded())
  ) return;
  if (!state.binanceAccount.status?.bound || !state.binanceAccount.snapshot) {
    const bootstrapDelay = state.binanceAccount.autoRefreshAfter - Date.now();
    if (!state.binanceAccount.loaded && state.binanceAccount.error && bootstrapDelay > 0) {
      binanceAccountLiveRefreshTimer = window.setTimeout(() => {
        binanceAccountLiveRefreshTimer = null;
        resumeBinanceAccountLiveRefresh();
      }, Math.max(1_000, bootstrapDelay));
    }
    return;
  }
  const retryDelay = Math.max(0, binanceAccountLiveRetryAfter - Date.now());
  binanceAccountLiveRefreshTimer = window.setTimeout(() => {
    binanceAccountLiveRefreshTimer = null;
    void silentlyRefreshBinanceAccountSnapshot();
  }, Math.max(0, delayMs, retryDelay));
}

function resumeBinanceAccountLiveRefresh() {
  if (
    !binanceAccountReadOnlyDataVisible()
    || (document.hidden && !executionPlanBinanceMonitoringNeeded())
  ) return;
  if (state.binanceAccount.status?.bound && state.binanceAccount.snapshot) {
    scheduleBinanceAccountLiveRefresh(
      Math.max(0, binanceAccountLiveRetryAfter - Date.now()),
    );
    return;
  }
  void loadBinanceAccountPage().finally(() => scheduleBinanceAccountLiveRefresh());
}

function ensureBinanceAccountLiveRefresh() {
  if (
    !binanceAccountReadOnlyDataVisible()
    || (document.hidden && !executionPlanBinanceMonitoringNeeded())
  ) return;
  if (
    binanceAccountLiveRefreshTimer !== null
    || binanceAccountLiveRefreshPromise
    || binanceAccountProgressiveRefreshPromise
    || binanceAccountLoadPromise
    || state.binanceAccount.loading
    || state.binanceAccount.profitCalendarLoading
  ) return;
  if (
    state.binanceAccount.loaded
    && state.binanceAccount.status
    && !state.binanceAccount.status.bound
    && Date.now() < state.binanceAccount.autoRefreshAfter
  ) return;
  resumeBinanceAccountLiveRefresh();
}

async function silentlyRefreshBinanceAccountSnapshot() {
  if (
    !binanceAccountReadOnlyDataVisible()
    || (document.hidden && !executionPlanBinanceMonitoringNeeded())
    || !api.getBinanceAccountSnapshot
    || !state.binanceAccount.status?.bound
    || !state.binanceAccount.snapshot
  ) {
    stopBinanceAccountLiveRefresh();
    return;
  }
  if (
    binanceAccountLiveRefreshPromise
    || binanceAccountProgressiveRefreshPromise
    || binanceAccountLoadPromise
    || state.binanceAccount.refreshing
    || state.binanceAccount.profitCalendarLoading
    || state.binanceAccount.dialog.open
  ) {
    scheduleBinanceAccountLiveRefresh(1_000);
    return binanceAccountLiveRefreshPromise || binanceAccountProgressiveRefreshPromise;
  }

  const accountState = state.binanceAccount;
  const loadSequence = binanceAccountLoadSequence;
  const snapshotApplySequence = ++binanceAccountSnapshotApplySequence;
  const request = (async () => {
    try {
      const previousFetchedAt = accountState.snapshot?.fetchedAt;
      const calendarVisible = accountState.activeSection === "profit-calendar"
        || accountState.profitCalendarLoading;
      const liveOnly = calendarVisible || Date.now() < binanceAccountFullRefreshAfter;
      const snapshot = await api.getBinanceAccountSnapshot!({ force: true, live: liveOnly });
      if (
        loadSequence !== binanceAccountLoadSequence
        || snapshotApplySequence !== binanceAccountSnapshotApplySequence
        || state.binanceAccount !== accountState
        || !accountState.status?.bound
      ) return;
      const reusedStaleSnapshot = snapshot.fetchedAt === previousFetchedAt
        && snapshot.warnings?.some((warning) => warning.includes("上次成功读取的数据"));
      accountState.snapshot = snapshot;
      syncTradingExpertOrderLineSnapshot(snapshot);
      await reconcileExecutionPlansWithBinanceSnapshot(snapshot);
      accountState.loaded = true;
      accountState.error = null;
      accountState.autoRefreshAfter = Date.now() + BINANCE_ACCOUNT_AUTO_REFRESH_INTERVAL_MS;
      if (!liveOnly && !reusedStaleSnapshot) {
        binanceAccountFullRefreshAfter = Date.now() + BINANCE_ACCOUNT_AUTO_REFRESH_INTERVAL_MS;
      }
      binanceAccountLiveRefreshFailures = reusedStaleSnapshot
        ? binanceAccountLiveRefreshFailures + 1
        : 0;
      binanceAccountLiveRetryAfter = reusedStaleSnapshot
        ? Date.now() + Math.min(
            BINANCE_ACCOUNT_LIVE_RETRY_MAX_INTERVAL_MS,
            BINANCE_ACCOUNT_LIVE_RETRY_BASE_INTERVAL_MS * (2 ** Math.max(0, binanceAccountLiveRefreshFailures - 1)),
          )
        : 0;
      renderBinanceAccountLiveUpdate();
    } catch (error) {
      if (
        loadSequence !== binanceAccountLoadSequence
        || snapshotApplySequence !== binanceAccountSnapshotApplySequence
        || state.binanceAccount !== accountState
      ) return;
      binanceAccountLiveRefreshFailures += 1;
      binanceAccountLiveRetryAfter = Date.now()
        + binanceAccountRetryDelay(error, binanceAccountLiveRefreshFailures);
      accountState.error = `账户数据暂时未更新，仍显示上次成功数据：${errorMessage(error)}`;
      renderBinanceAccountLiveUpdate();
    }
  })();
  binanceAccountLiveRefreshPromise = request;
  try {
    await request;
  } finally {
    if (binanceAccountLiveRefreshPromise === request) binanceAccountLiveRefreshPromise = null;
    const retryDelay = Math.min(
      BINANCE_ACCOUNT_LIVE_RETRY_MAX_INTERVAL_MS,
      BINANCE_ACCOUNT_LIVE_RETRY_BASE_INTERVAL_MS * (2 ** Math.max(0, binanceAccountLiveRefreshFailures - 1)),
    );
    scheduleBinanceAccountLiveRefresh(
      binanceAccountLiveRefreshFailures > 0 ? retryDelay : binanceAccountLiveRefreshInterval(),
    );
  }
}

function renderBinanceAccountLiveUpdate() {
  if (state.activeView !== "account") return;
  const currentPage = root.querySelector<HTMLElement>(".binance-account-page");
  if (!currentPage) {
    render();
    return;
  }
  const currentScroll = currentPage.querySelector<HTMLElement>(".binance-account-scroll");
  const scrollTop = currentScroll?.scrollTop ?? 0;
  const scrollLeft = currentScroll?.scrollLeft ?? 0;
  const focusedElement = document.activeElement instanceof HTMLElement && currentPage.contains(document.activeElement)
    ? document.activeElement
    : null;
  const focusedAction = focusedElement?.dataset.binanceAccountAction || null;
  const focusedSection = focusedElement?.dataset.binanceAccountSection || null;
  const scrollWasFocused = focusedElement === currentScroll;
  const template = document.createElement("template");
  template.innerHTML = renderBinanceAccountPage(state.binanceAccount).trim();
  const nextPage = template.content.firstElementChild;
  if (!(nextPage instanceof HTMLElement)) {
    render();
    return;
  }
  currentPage.replaceWith(nextPage);
  bindBinanceAccountEvents(nextPage);
  const nextScroll = nextPage.querySelector<HTMLElement>(".binance-account-scroll");
  if (!nextScroll) return;
  nextScroll.scrollTop = scrollTop;
  nextScroll.scrollLeft = scrollLeft;
  if (scrollWasFocused) {
    nextScroll.focus({ preventScroll: true });
    return;
  }
  const focusSelector = focusedSection
    ? `[data-binance-account-section="${focusedSection}"]`
    : focusedAction
      ? `[data-binance-account-action="${focusedAction}"]`
      : null;
  if (focusSelector) nextPage.querySelector<HTMLElement>(focusSelector)?.focus({ preventScroll: true });
}

function stopBinanceAccountOtpCountdown() {
  if (binanceAccountOtpCountdownTimer === null) return;
  window.clearInterval(binanceAccountOtpCountdownTimer);
  binanceAccountOtpCountdownTimer = null;
}

function syncBinanceAccountDialogControls() {
  const dialog = state.binanceAccount.dialog;
  const countdown = binanceAccountResendCountdown(dialog.resendReadyAt);
  const resend = root.querySelector<HTMLButtonElement>("[data-binance-account-resend]");
  if (resend) {
    resend.disabled = Boolean(dialog.busy) || countdown > 0;
    resend.textContent = countdown > 0 ? `${countdown}s 后重试` : "重新发送";
  }
  const submit = root.querySelector<HTMLButtonElement>("[data-binance-account-dialog-form] button[type=submit]");
  if (submit) {
    submit.disabled = Boolean(dialog.busy)
      || !dialog.challengeId
      || (dialog.mode === "bind" && (!dialog.apiKey.trim() || !dialog.apiSecret.trim()))
      || !/^\d{6}$/.test(dialog.code.trim());
  }
  if (countdown <= 0) stopBinanceAccountOtpCountdown();
}

function startBinanceAccountOtpCountdown() {
  stopBinanceAccountOtpCountdown();
  syncBinanceAccountDialogControls();
  if (binanceAccountResendCountdown(state.binanceAccount.dialog.resendReadyAt) <= 0) return;
  binanceAccountOtpCountdownTimer = window.setInterval(syncBinanceAccountDialogControls, 1_000);
}

function closeBinanceAccountDialog() {
  if (state.binanceAccount.dialog.busy) return;
  stopBinanceAccountOtpCountdown();
  resetBinanceAccountDialog(state.binanceAccount);
  render();
}

async function sendBinanceAccountOtp() {
  if (!api.sendBinanceAccountOtp || state.binanceAccount.dialog.busy) return;
  state.binanceAccount.dialog.busy = "send";
  state.binanceAccount.dialog.error = null;
  render();
  try {
    const challenge = await api.sendBinanceAccountOtp();
    state.binanceAccount.dialog.challengeId = String(challenge?.challengeId || "").trim();
    state.binanceAccount.dialog.emailMasked = String(challenge?.emailMasked || state.binanceAccount.status?.emailMasked || "");
    state.binanceAccount.dialog.resendReadyAt = Date.now() + Math.max(0, Number(challenge?.resendAfter) || 60) * 1_000;
    if (!state.binanceAccount.dialog.challengeId) throw new Error("验证码发送失败，请重试。");
  } catch (error) {
    state.binanceAccount.dialog.error = errorMessage(error);
  } finally {
    state.binanceAccount.dialog.busy = null;
    if (state.binanceAccount.dialog.open) {
      render();
      startBinanceAccountOtpCountdown();
      window.requestAnimationFrame(() => {
        const inputName = state.binanceAccount.dialog.mode === "remove" ? "code" : "apiKey";
        root.querySelector<HTMLInputElement>(`[data-binance-account-dialog-form] input[name="${inputName}"]`)?.focus();
      });
    }
  }
}

function openBinanceAccountDialog() {
  resetBinanceAccountDialog(state.binanceAccount, "bind");
  state.binanceAccount.dialog.open = true;
  state.binanceAccount.dialog.emailMasked = state.binanceAccount.status?.emailMasked || "";
  render();
  void sendBinanceAccountOtp();
}

async function submitBinanceAccountBinding() {
  const dialog = state.binanceAccount.dialog;
  if (!api.bindBinanceAccount || dialog.busy) return;
  if (!dialog.challengeId) {
    dialog.error = "请先发送邮箱验证码。";
    render();
    return;
  }
  if (!dialog.apiKey.trim() || !dialog.apiSecret.trim() || !/^\d{6}$/.test(dialog.code.trim())) {
    dialog.error = "请完整填写 API 密钥、密钥和 6 位邮箱验证码。";
    render();
    return;
  }
  dialog.busy = "bind";
  dialog.error = null;
  render();
  try {
    const result = await api.bindBinanceAccount({
      apiKey: dialog.apiKey.trim(),
      apiSecret: dialog.apiSecret.trim(),
      challengeId: dialog.challengeId,
      code: dialog.code.trim(),
    });
    binanceAccountLoadSequence += 1;
    binanceAccountSnapshotApplySequence += 1;
    state.binanceAccount.status = {
      ...result.status,
      emailMasked: state.binanceAccount.status?.emailMasked || dialog.emailMasked,
    };
    state.binanceAccount.snapshot = result.snapshot;
    syncTradingExpertOrderLineSnapshot(result.snapshot);
    await reconcileExecutionPlansWithBinanceSnapshot(result.snapshot);
    state.binanceAccount.loaded = true;
    state.binanceAccount.loading = false;
    state.binanceAccount.error = null;
    state.binanceAccount.autoRefreshAfter = Date.now() + BINANCE_ACCOUNT_AUTO_REFRESH_INTERVAL_MS;
    binanceAccountFullRefreshAfter = Date.now() + BINANCE_ACCOUNT_AUTO_REFRESH_INTERVAL_MS;
    binanceAccountLiveRefreshFailures = 0;
    stopBinanceAccountOtpCountdown();
    resetBinanceAccountDialog(state.binanceAccount);
    render();
    if (state.binanceAccount.activeSection === "profit-calendar") {
      void loadBinanceAccountProfitCalendar({ force: true });
    }
    scheduleBinanceAccountLiveRefresh();
    showToast("Binance API 已完成只读绑定。", 3600);
  } catch (error) {
    dialog.busy = null;
    dialog.error = errorMessage(error);
    render();
    startBinanceAccountOtpCountdown();
  }
}

async function confirmBinanceAccountRemoval() {
  if (!api.removeBinanceAccount || state.binanceAccount.refreshing || state.binanceAccount.dialog.open) return;
  const confirmed = await confirmInApp({
    title: "解除 Binance API 绑定",
    message: "解除后会从本机安全存储中删除 API Key 和 Secret Key，账户资产与持仓将停止显示。",
    confirmLabel: "解除绑定",
    tone: "danger",
  });
  if (!confirmed) return;
  resetBinanceAccountDialog(state.binanceAccount, "remove");
  state.binanceAccount.dialog.open = true;
  state.binanceAccount.dialog.emailMasked = state.binanceAccount.status?.emailMasked || "";
  render();
  void sendBinanceAccountOtp();
}

async function removeBinanceAccountBinding() {
  const dialog = state.binanceAccount.dialog;
  if (!api.removeBinanceAccount || dialog.busy || dialog.mode !== "remove") return;
  if (!dialog.challengeId) {
    dialog.error = "请先发送邮箱验证码。";
    render();
    return;
  }
  if (!/^\d{6}$/.test(dialog.code.trim())) {
    dialog.error = "请输入 6 位邮箱验证码。";
    render();
    return;
  }
  dialog.busy = "remove";
  dialog.error = null;
  binanceAccountLoadSequence += 1;
  binanceAccountSnapshotApplySequence += 1;
  state.binanceAccount.loading = false;
  render();
  try {
    state.binanceAccount.status = await api.removeBinanceAccount({
      challengeId: dialog.challengeId,
      code: dialog.code.trim(),
    });
    state.binanceAccount.snapshot = null;
    binanceAccountProfitCalendarLoadSequence += 1;
    state.binanceAccount.profitCalendar = null;
    state.binanceAccount.profitCalendarMonth = currentBinanceAccountProfitCalendarMonth();
    state.binanceAccount.profitCalendarLoading = false;
    state.binanceAccount.profitCalendarError = null;
    syncTradingExpertOrderLineSnapshot(null);
    state.binanceAccount.loaded = true;
    state.binanceAccount.error = null;
    state.binanceAccount.autoRefreshAfter = Date.now() + BINANCE_ACCOUNT_AUTO_REFRESH_INTERVAL_MS;
    stopBinanceAccountLiveRefresh();
    binanceAccountLiveRefreshFailures = 0;
    binanceAccountFullRefreshAfter = 0;
    stopBinanceAccountOtpCountdown();
    resetBinanceAccountDialog(state.binanceAccount);
    render();
    showToast("Binance API 绑定已解除。", 3200);
  } catch (error) {
    dialog.busy = null;
    dialog.error = errorMessage(error);
    render();
    startBinanceAccountOtpCountdown();
  }
}

async function refreshTradingAlerts() {
  if (!api.tradingAlertsSnapshot) return;
  state.tradingAlerts.loading = true;
  state.tradingAlerts.error = null;
  if (state.activeView === "alerts") render();
  try {
    applyTradingAlertsSnapshot(state.tradingAlerts, await api.tradingAlertsSnapshot());
  } catch (error) {
    state.tradingAlerts.loading = false;
    state.tradingAlerts.error = errorMessage(error);
  }
  if (state.activeView === "alerts") render();
}

function openTradingAlertComposer() {
  const tradingThread = state.threads.find((thread) => isTradingExpertThreadId(thread.id));
  state.activeView = "chat";
  if (tradingThread) {
    state.currentThreadId = tradingThread.id;
    rememberChatThreadSelection(tradingThread.id);
    restoreComposerDraftForThread(tradingThread.id);
  } else if (!restoreRememberedChatThreadSelection()) {
    ensureTopLevelBlankThreadForList({ activateIfMissingSelection: true });
  }
  if (!state.composerText.trim()) state.composerText = "@预警 ";
  render();
  showToast("请描述任意组合条件；智能体会持续追问并先模拟，再请你确认。", 3600);
}

async function mutateTradingAlert(action: "pause" | "resume" | "delete", alertId: string) {
  if (action === "delete" && !(await confirmInApp({
    title: "删除预警",
    message: "确定删除这个预警吗？历史触发证据将保留在审计记录中。",
    confirmLabel: "删除",
    tone: "danger",
  }))) return;
  const call = action === "pause" ? api.tradingAlertsPause : action === "resume" ? api.tradingAlertsResume : api.tradingAlertsDelete;
  if (!call) return;
  state.tradingAlerts.busyAlertId = alertId;
  render();
  try {
    const response = await call({ alertId });
    if (response?.ok === false) throw new Error(response.error?.message || "预警操作失败");
    await refreshTradingAlerts();
  } catch (error) {
    state.tradingAlerts.error = errorMessage(error);
    showToast(state.tradingAlerts.error, 5000);
  } finally {
    state.tradingAlerts.busyAlertId = null;
    if (state.activeView === "alerts") render();
  }
}

const tradingAlertRevisionSubmissions = new Set<string>();

function allowTradingAlertRevisionBusyStateToPaint() {
  return new Promise<void>((resolve) => {
    window.requestAnimationFrame(() => window.setTimeout(resolve, 0));
  });
}

async function submitTradingAlertRevision(form: HTMLFormElement) {
  if (!api.tradingAlertsRevise) return;
  const alertId = form.dataset.alertId || "";
  if (!alertId || tradingAlertRevisionSubmissions.has(alertId)) return;
  const requested = state.tradingAlerts.editorSelection?.alertId === alertId
    ? { ...state.tradingAlerts.editorSelection }
    : null;
  if (!requested?.marketId || !requested.interval) {
    showToast("编辑设置尚未就绪，请重新选择交易对和周期。", 5000);
    return;
  }
  const submitButton = form.querySelector<HTMLButtonElement>('button[type="submit"]');
  const submitLabel = submitButton?.textContent || "生成新预警";
  tradingAlertRevisionSubmissions.add(alertId);
  state.tradingAlerts.busyAlertId = alertId;
  form.setAttribute("aria-busy", "true");
  if (submitButton) {
    submitButton.disabled = true;
    submitButton.textContent = "正在生成…";
  }
  try {
    await allowTradingAlertRevisionBusyStateToPaint();
    const response = await api.tradingAlertsRevise({
      alertId,
      contextId: form.dataset.contextId,
      marketIds: requested.marketId,
      intervals: requested.interval,
      selectorKind: requested.selectorKind,
      clock: requested.clock,
      mode: requested.mode,
    });
    if (response?.ok === false) throw new Error(response.error?.message || "生成新预警失败");
    const draft = response?.data?.draft;
    const revisedAnchor = draft?.rule?.contexts?.find((context: any) => (
      context.contextId === draft?.rule?.evaluationPolicy?.anchorContextId
    )) || draft?.rule?.contexts?.[0];
    const revisedMarketId = String((revisedAnchor?.marketSelector?.marketIds || revisedAnchor?.marketSelector?.frozenMarketIds || [])[0] || "").toUpperCase();
    const revisedInterval = String(revisedAnchor?.intervals?.[0] || "").toLowerCase();
    if (revisedMarketId !== requested.marketId || revisedInterval !== requested.interval) {
      throw new Error(`新预警设置校验失败：选择的是 ${requested.marketId} / ${requested.interval}，生成的规则却是 ${revisedMarketId || "未知交易对"} / ${revisedInterval || "未知周期"}`);
    }
    state.tradingAlerts.editorAlertId = null;
    state.tradingAlerts.editorSelection = null;
    await refreshTradingAlerts();
    if (!draft?.rule || !api.tradingAlertsSimulate) throw new Error("新 Revision 尚未形成可模拟规则");
    openTradingAlertComposer();
    await Promise.resolve();
    const threadId = state.currentThreadId;
    if (!threadId || !isTradingExpertThreadId(threadId)) throw new Error("请先打开交易专家会话以确认新 Revision");
    const anchor = draft.rule.contexts.find((context: any) => context.contextId === draft.rule.evaluationPolicy.anchorContextId)
      || draft.rule.contexts[0];
    const marketId = anchor?.marketSelector?.kind === "fixed" ? anchor.marketSelector.marketIds?.[0] : null;
    showToast("正在后台模拟新预警，客户端可继续操作…", 2600);
    const preparedContext = await prepareTradingExpertAlertContext(marketId, anchor?.intervals?.[0]);
    if (
      String(preparedContext?.marketId || "").toUpperCase() !== requested.marketId
      || String(preparedContext?.interval || "").toLowerCase() !== requested.interval
    ) throw new Error("行情图未切换到本次编辑选择的交易对和周期，已停止模拟");
    const frames = await tradingExpertAlertSimulationFrames(draft.rule);
    const anchorFrame = frames?.[String(anchor?.contextId || "")];
    if (
      String(anchorFrame?.marketId || "").toUpperCase() !== requested.marketId
      || String(anchorFrame?.interval || "").toLowerCase() !== requested.interval
    ) throw new Error("模拟行情与本次编辑设置不一致，已停止模拟");
    const simulated = tradingAlertResponseData(await api.tradingAlertsSimulate({ draftId: draft.draftId, frames, replacesAlertId: alertId }));
    await prepareTradingExpertAlertContext(requested.marketId, requested.interval);
    showTradingExpertAlertSimulation(simulated.simulation, draft.rule.evaluationPolicy.anchorContextId, draft.rule);
    const question = `${String(simulated.question || "新 Revision 已完成模拟，是否按这种情况更新预警？")}\n\n原 Revision 在你确认前继续监控；确认后才会切换规则。`;
    tradingAlertConversationByThreadId.set(threadId, {
      draftId: draft.draftId,
      sourceText: draft.sourceText,
      stage: "confirmation",
      conversation: [{ role: "assistant", text: question }],
      simulationId: simulated.simulation.simulationId,
      confirmationId: simulated.simulation.confirmation.confirmationId,
    });
    await persistTradingAlertAssistantItem(threadId, question);
    showToast(response?.data?.message || "新 Revision 已模拟，请在交易会话中确认。", 5000);
  } catch (error) {
    state.tradingAlerts.error = errorMessage(error);
    showToast(state.tradingAlerts.error, 5000);
  } finally {
    tradingAlertRevisionSubmissions.delete(alertId);
    state.tradingAlerts.busyAlertId = null;
    if (form.isConnected) {
      form.removeAttribute("aria-busy");
      if (submitButton) {
        submitButton.disabled = false;
        submitButton.textContent = submitLabel;
      }
    }
    if (state.activeView === "alerts") render();
  }
}

function tradingAlertForOpen(alertId: string | null | undefined) {
  const id = firstString(alertId);
  return id ? state.tradingAlerts.alerts.find((entry) => entry?.alertId === id) || null : null;
}

function tradingAlertEvidenceForOpen(alert: any, evidenceId?: string | null) {
  const candidates = state.tradingAlerts.evidence
    .filter((entry) => entry?.alertId === alert?.alertId)
    .sort((left, right) => Number(right?.triggeredAt || 0) - Number(left?.triggeredAt || 0));
  const requestedId = firstString(evidenceId, alert?.latestEvidenceId);
  return (requestedId ? candidates.find((entry) => entry?.evidenceId === requestedId) : null)
    || candidates[0]
    || null;
}

function tradingAlertAnchorContext(alert: any) {
  const contexts = Array.isArray(alert?.rule?.contexts) ? alert.rule.contexts : [];
  return contexts.find((context: any) => context?.contextId === alert?.rule?.evaluationPolicy?.anchorContextId)
    || contexts[0]
    || null;
}

async function openTradingAlertSourceConversation(alertId?: string | null, evidenceId?: string | null) {
  try {
    let alert = tradingAlertForOpen(alertId);
    if (!alert && api.tradingAlertsSnapshot) {
      await refreshTradingAlerts();
      alert = tradingAlertForOpen(alertId);
    }
    if (!alert) throw new Error("预警不存在或已经删除");
    const originThreadId = firstString(alert.originThreadId);
    if (!originThreadId) throw new Error("这条预警没有可返回的来源会话");
    const resolvedThreadId = resolvedTradingAlertThreadId(originThreadId);
    const threadId = threadById(resolvedThreadId)
      ? resolvedThreadId
      : threadById(originThreadId) ? originThreadId : resolvedThreadId || originThreadId;
    initializeTradingExpertTaskThread(threadId, { expandPanel: true });
    await selectThread(threadId);
    if (state.activeView !== "chat" || !tradingAlertThreadMatches(state.currentThreadId, threadId)) {
      throw new Error("来源会话暂时无法打开");
    }

    const anchor = tradingAlertAnchorContext(alert);
    const selector = anchor?.marketSelector || {};
    const evidence = tradingAlertEvidenceForOpen(alert, evidenceId);
    const anchorMarketId = selector.kind === "fixed"
      ? firstString(selector.marketIds?.[0])
      : firstString(selector.frozenMarketIds?.[0]);
    const evidenceContext = (Array.isArray(evidence?.contexts) ? evidence.contexts : []).find((context: any) => (
      (!anchorMarketId || firstString(context?.marketId) === anchorMarketId)
      && (!anchor?.intervals?.[0] || firstString(context?.interval) === firstString(anchor.intervals[0]))
    )) || evidence?.contexts?.[0] || null;
    const marketId = firstString(anchorMarketId, evidenceContext?.marketId);
    const interval = firstString(anchor?.intervals?.[0], evidenceContext?.interval);
    if (!marketId || !interval) throw new Error("预警缺少可恢复的市场或周期");
    await prepareTradingExpertAlertContext(marketId, interval);

    const visualizationWarnings: string[] = [];
    if (alert.simulationId && api.tradingAlertsGetSimulation) {
      try {
        const simulation = tradingAlertResponseData(await api.tradingAlertsGetSimulation({ simulationId: String(alert.simulationId) }));
        showTradingExpertAlertSimulation(
          simulation,
          String(alert.rule?.evaluationPolicy?.anchorContextId || anchor?.contextId || "primary"),
          alert.rule,
          { allowHistorical: true, animate: false, focus: !evidence },
        );
      } catch (error) {
        visualizationWarnings.push(`模拟图恢复失败：${errorMessage(error)}`);
      }
    } else {
      visualizationWarnings.push("没有找到该预警保存的模拟图");
    }

    if (evidence) {
      try {
        focusTradingExpertAlertEvidence(evidence, alert.rule);
      } catch (error) {
        visualizationWarnings.push(`真实触发定位失败：${errorMessage(error)}`);
      }
    }
    showToast(
      visualizationWarnings.length
        ? `已打开来源会话；${visualizationWarnings.join("；")}`
        : evidence ? "已打开来源会话，并定位真实触发位置。" : "已打开来源会话，并恢复创建时的模拟图。",
      visualizationWarnings.length ? 6000 : 3600,
    );
  } catch (error) {
    showToast(errorMessage(error), 5000);
  }
}

function returnToHomePage() {
  state.activeView = "chat";
  if (!restoreRememberedChatThreadSelection()) {
    ensureTopLevelBlankThreadForList({ activateIfMissingSelection: true });
  }
  state.selectedAutoTaskId = null;
  state.autoTaskMenuTaskId = null;
  state.externalChannels.menuOpen = false;
  state.profileMenuOpen = false;
  state.skillSortMenuOpen = false;
  state.resultsGroupMenuOpen = false;
  render();
}

function threadGroupById(groupId: string | null | undefined) {
  if (!groupId) return null;
  return threadGroups.find((group) => group.id === groupId) ?? null;
}

function selectableThreadGroupById(groupId: string | null | undefined) {
  return threadGroupById(groupId);
}

function selectableThreadGroupId(groupId: string | null | undefined) {
  return selectableThreadGroupById(groupId)?.id ?? DEFAULT_THREAD_GROUP_ID;
}

function knownThreadGroupId(groupId: string | null | undefined) {
  return threadGroupById(groupId)?.id ?? DEFAULT_THREAD_GROUP_ID;
}

function threadGroupWorkspaceSlug(group: ThreadGroup | null | undefined) {
  if (!group || isDefaultThreadGroup(group.id)) return DEFAULT_THREAD_GROUP_WORKSPACE_SLUG;
  return firstString(group.workspaceSlug) || group.id;
}

function threadGroupWorkspaceRequest(group: ThreadGroup): ThreadGroupWorkspaceRequest {
  return {
    groupId: group.id,
    groupName: group.name,
    workspaceSlug: threadGroupWorkspaceSlug(group),
    externalPath: group.externalPath || null,
    artifactSince: group.externalPath ? group.createdAt : null,
  };
}

function questionAnswerCurrentGroupContext(
  groupId: string | null | undefined,
  requestId: string,
) {
  const group = threadGroupById(groupId);
  if (!group || isDefaultThreadGroup(group.id)) return undefined;
  return {
    protocolVersion: 1 as const,
    source: "group_picker" as const,
    groupId: group.id,
    groupName: group.name,
    workspaceSlug: threadGroupWorkspaceSlug(group),
    externalPath: group.externalPath || null,
    requestId,
  };
}

function autoTaskGroupMetadata(groupId: string | null | undefined, fallbackWorkspacePath?: string | null) {
  const group = threadGroupById(knownThreadGroupId(groupId)) || ensureDefaultThreadGroup();
  const workspacePath = group.externalPath || threadGroupWorkspaceById[group.id] || firstString(fallbackWorkspacePath) || null;
  return {
    groupId: group.id,
    groupName: group.name,
    workspaceSlug: threadGroupWorkspaceSlug(group),
    workspacePath,
    externalPath: group.externalPath || null,
  };
}

function autoTaskWithGroupMetadata(task: AutoTaskItem): AutoTaskItem {
  return {
    ...task,
    ...autoTaskGroupMetadata(task.groupId, task.workspacePath || task.externalPath),
  };
}

function syncAutoTaskThreadGroupMappings() {
  ensureDefaultThreadGroup();
  let changed = false;
  state.autoTaskItems = state.autoTaskItems.map((task) => {
    const nextTask = autoTaskWithGroupMetadata(task);
    if (
      nextTask.groupId !== task.groupId ||
      nextTask.groupName !== task.groupName ||
      nextTask.workspaceSlug !== task.workspaceSlug ||
      nextTask.workspacePath !== task.workspacePath ||
      nextTask.externalPath !== task.externalPath
    ) {
      changed = true;
    }
    for (const threadId of [autoTaskThreadId(nextTask.id), nextTask.threadId].filter((id): id is string => Boolean(id))) {
      if (threadGroupByThreadId[threadId] !== nextTask.groupId) {
        threadGroupByThreadId[threadId] = nextTask.groupId;
        changed = true;
      }
      if (rememberThreadWorkspace(threadId, nextTask.workspacePath || nextTask.externalPath || workspaceForGroupId(nextTask.groupId))) {
        changed = true;
      }
    }
    return nextTask;
  });
  return changed;
}

function allThreadGroupWorkspaceRequests() {
  ensureDefaultThreadGroup();
  return sortedThreadGroups().map(threadGroupWorkspaceRequest);
}

function threadGroupWorkspaceDescriptors() {
  return sortedThreadGroups().map((group) => ({
    ...threadGroupWorkspaceRequest(group),
    cwd: workspaceForGroupId(group.id),
  }));
}

function workspaceArrayFromPayload(payload: any): ThreadGroupWorkspace[] {
  if (Array.isArray(payload)) return payload;
  const data = payload?.data || payload?.items;
  return Array.isArray(data) ? data : [];
}

async function syncThreadGroupWorkspaces(options: { renderAfter?: boolean } = {}) {
  ensureDefaultThreadGroup();
  if (!api.listThreadGroupWorkspaces) {
    threadGroupWorkspaceById[DEFAULT_THREAD_GROUP_ID] = state.settings.cwd;
    return;
  }
  try {
    const payload = await api.listThreadGroupWorkspaces({ groups: allThreadGroupWorkspaceRequests() });
    const workspaces = workspaceArrayFromPayload(payload);
    for (const workspace of workspaces) {
      const groupId = knownThreadGroupId(firstString(workspace.groupId, (workspace as any).group_id));
      const cwd = firstString(workspace.cwd, workspace.path);
      if (cwd) threadGroupWorkspaceById[groupId] = cwd;
    }
    const defaultCwd = threadGroupWorkspaceById[DEFAULT_THREAD_GROUP_ID];
    if (defaultCwd) state.settings.cwd = defaultCwd;
  } catch (error) {
    console.warn("Failed to sync thread group workspaces", error);
    if (!threadGroupWorkspaceById[DEFAULT_THREAD_GROUP_ID]) threadGroupWorkspaceById[DEFAULT_THREAD_GROUP_ID] = state.settings.cwd;
  } finally {
    if (options.renderAfter !== false) render();
  }
}

function groupIdForThreadContext(threadId?: string | null, explicitGroupId?: string | null) {
  if (explicitGroupId) return selectableThreadGroupId(explicitGroupId);
  if (!threadId) return selectableThreadGroupId(state.activeNewThreadGroupId);
  if (isBlankNewThread(threadId)) {
    const mappedGroupId = selectableThreadGroupId(threadGroupByThreadId[threadId]);
    if (threadId === state.blankThreadId && isDefaultThreadGroup(mappedGroupId)) {
      return selectableThreadGroupId(state.activeNewThreadGroupId);
    }
    return selectableThreadGroupId(mappedGroupId || state.activeNewThreadGroupId);
  }
  return knownThreadGroupId(threadGroupByThreadId[threadId] || DEFAULT_THREAD_GROUP_ID);
}

function workspaceForGroupId(groupId: string | null | undefined) {
  const knownGroupId = knownThreadGroupId(groupId);
  return (
    threadGroupWorkspaceById[knownGroupId] || threadGroupWorkspaceById[DEFAULT_THREAD_GROUP_ID] || state.settings.cwd
  );
}

function rememberThreadWorkspace(threadId: string | null | undefined, cwd: string | null | undefined) {
  const id = firstString(threadId);
  const workspace = firstString(cwd);
  if (!id || !workspace) return false;
  if (threadWorkspaceByThreadId[id] === workspace) return false;
  threadWorkspaceByThreadId[id] = workspace;
  return true;
}

function forgetThreadWorkspace(threadId: string | null | undefined) {
  const id = firstString(threadId);
  if (!id || !(id in threadWorkspaceByThreadId)) return false;
  delete threadWorkspaceByThreadId[id];
  return true;
}

function threadWorkspaceCwd(threadId?: string | null, options: { groupId?: string | null } = {}) {
  const id = firstString(threadId);
  if (!options.groupId && id && !isBlankNewThread(id)) {
    const rememberedWorkspace = firstString(threadWorkspaceByThreadId[id]);
    if (rememberedWorkspace) return rememberedWorkspace;
  }
  return workspaceForGroupId(groupIdForThreadContext(threadId, options.groupId));
}

function ensureDefaultThreadGroup(): ThreadGroup {
  const existingIndex = threadGroups.findIndex((group) => group.id === DEFAULT_THREAD_GROUP_ID);
  if (existingIndex >= 0) {
    const [existing] = threadGroups.splice(existingIndex, 1);
    threadGroups.unshift({ ...existing, name: DEFAULT_THREAD_GROUP_NAME, workspaceSlug: DEFAULT_THREAD_GROUP_WORKSPACE_SLUG, externalPath: null });
    return threadGroups[0];
  }
  const now = new Date().toISOString();
  const group = {
    id: DEFAULT_THREAD_GROUP_ID,
    name: DEFAULT_THREAD_GROUP_NAME,
    createdAt: now,
    updatedAt: now,
    workspaceSlug: DEFAULT_THREAD_GROUP_WORKSPACE_SLUG,
    externalPath: null,
  };
  threadGroups.unshift(group);
  return group;
}

function isDefaultThreadGroup(groupId: string | null | undefined) {
  return groupId === DEFAULT_THREAD_GROUP_ID;
}

function isDefaultAssignableThread(thread: ConversationSummary | null | undefined) {
  if (!thread || hiddenThreadIds.has(thread.id)) return false;
  if (isBlankNewThread(thread.id)) return false;
  if (isProviderThread(thread) || providerFromThreadId(thread.id)) return true;
  if (isAutoTaskThread(thread) || autoTaskIdFromThreadId(thread.id) || isAutoTaskOwnedThreadId(thread.id)) return true;
  if (isChannelThread(thread) || channelIdFromThreadId(thread.id)) return isDirectChannelThread(thread);
  return true;
}

function isDirectChannelThread(thread: ConversationSummary) {
  if (normalizeChannelType(firstString(thread.channel_type, (thread as { channelType?: unknown }).channelType)) === "direct") return true;
  const channelId = channelIdFromThreadId(thread.id);
  if (!channelId) return false;
  const channel = state.channels[channelId];
  return (
    normalizeChannelType(channel?.channel_type || channel?.channelType) === "direct"
  );
}

function assignThreadToDefaultGroup(threadOrId: ConversationSummary | string | null | undefined) {
  const thread = typeof threadOrId === "string" ? threadById(threadOrId) || ({ id: threadOrId } as ConversationSummary) : threadOrId;
  if (!thread || internalSubagentThreadIds.has(thread.id) || !isDefaultAssignableThread(thread)) return false;
  if (isExternalChannelConnectionThread(thread)) {
    const channelId = externalChannelConnectionThreadId(thread);
    return channelId ? ensureExternalChannelThreadPlacement(thread.id, channelId) : false;
  }
  ensureDefaultThreadGroup();
  if (threadGroupByThreadId[thread.id]) return false;
  threadGroupByThreadId[thread.id] = DEFAULT_THREAD_GROUP_ID;
  return true;
}

function assignThreadsToDefaultGroup(threads: ConversationSummary[]) {
  let changed = false;
  for (const thread of threads) {
    if (assignThreadToDefaultGroup(thread)) changed = true;
  }
  return changed;
}

function openThreadRenameDialog(threadId: string) {
  const target = threadById(threadId);
  if (!target || !canRenameThread(target)) return;
  state.threadRenameDialog = {
    threadId,
    name: threadNameOverride(threadId) || threadListDisplayName(target) || target.name || "",
    error: null,
  };
  state.threadDelete = null;
  state.threadGroupSetDialog = null;
  state.threadGroupEditor = null;
  state.threadGroupDelete = null;
  state.threadMenu = null;
  state.threadGroupMenu = null;
  render();
}

function cancelThreadRenameDialog() {
  state.threadRenameDialog = null;
  render();
}

function submitThreadRenameDialog() {
  const dialog = state.threadRenameDialog;
  if (!dialog) return;
  const target = threadById(dialog.threadId);
  if (!target || !canRenameThread(target)) {
    state.threadRenameDialog = null;
    render();
    return;
  }
  const labels = threadRenameDialogLabels(target);
  const name = dialog.name.trim();
  if (!name) {
    state.threadRenameDialog = { ...dialog, error: labels.emptyError };
    render();
    return;
  }
  threadNameOverrides[dialog.threadId] = name;
  const localGroup = localGroupChatRecord(dialog.threadId);
  if (localGroup) {
    localGroup.name = name;
    saveLocalGroupChatRecords();
  }
  state.threads = sortThreadsForList(state.threads.map((thread) =>
      thread.id === dialog.threadId ? { ...thread, name } : thread));
  state.threadRenameDialog = null;
  saveThreadPreferences();
  showToast(labels.toast, 1800);
  render();
}

function openThreadGroupSetDialog(threadId: string) {
  const thread = threadById(threadId);
  const currentGroupId = threadGroupByThreadId[threadId] || (isDefaultAssignableThread(thread) ? DEFAULT_THREAD_GROUP_ID : null);
  state.threadGroupSetDialog = {
    threadId,
    selectedGroupId: currentGroupId,
    dropdownOpen: false,
    error: null,
  };
  state.threadGroupEditor = null;
  state.threadGroupDelete = null;
  state.threadMenu = null;
  state.threadGroupMenu = null;
  render();
}

function assignThreadToGroup(threadId: string, groupId: string | null | undefined) {
  const thread = threadById(threadId);
  const group = threadGroupById(groupId);
  if (!thread || !group) return null;
  const currentGroupId =
    threadGroupByThreadId[threadId] ||
    (isDefaultAssignableThread(thread) ? DEFAULT_THREAD_GROUP_ID : null);
  if (currentGroupId === group.id) return group;
  rememberThreadWorkspace(threadId, threadWorkspaceCwd(threadId));
  if (isDefaultThreadGroup(group.id)) {
    delete threadGroupByThreadId[threadId];
    assignThreadToDefaultGroup(threadId);
  } else {
    threadGroupByThreadId[threadId] = group.id;
  }
  saveThreadPreferences();
  return group;
}

function moveThreadToGroup(threadId: string, groupId: string | null | undefined) {
  const group = assignThreadToGroup(threadId, groupId);
  state.threadGroupSetDialog = null;
  state.threadMenu = null;
  if (group) showToast(`已移动到${threadGroupDisplayLabel(group)}`, 1800);
  render();
}

function openThreadGroupEditor(
  mode: ThreadGroupEditorState["mode"],
  options: {
    groupId?: string | null;
    threadId?: string | null;
    returnToSetDialog?: ThreadGroupSetDialogState | null;
  } = {},
) {
  const group = options.groupId ? threadGroupById(options.groupId) : null;
  const returnToSetDialog = options.returnToSetDialog ? { ...options.returnToSetDialog, dropdownOpen: false, error: null } : null;
  state.threadGroupEditor = {
    mode,
    groupId: group?.id ?? null,
    threadId: options.threadId ?? returnToSetDialog?.threadId ?? state.threadGroupSetDialog?.threadId ?? null,
    name: group?.name || "",
    error: null,
    returnToSetDialog,
  };
  if (returnToSetDialog) state.threadGroupSetDialog = null;
  state.threadGroupMenu = null;
  render();
}

function cancelThreadGroupEditor() {
  const returnToSetDialog = state.threadGroupEditor?.returnToSetDialog ?? null;
  state.threadGroupEditor = null;
  if (returnToSetDialog) state.threadGroupSetDialog = returnToSetDialog;
  render();
}

function submitThreadGroupSetDialog() {
  const dialog = state.threadGroupSetDialog;
  if (!dialog) return;
  if (!threadById(dialog.threadId)) {
    state.threadGroupSetDialog = null;
    render();
    return;
  }
  if (!dialog.selectedGroupId || !threadGroupById(dialog.selectedGroupId)) {
    state.threadGroupSetDialog = { ...dialog, error: "请选择分组" };
    render();
    return;
  }
  assignThreadToGroup(dialog.threadId, dialog.selectedGroupId);
  state.threadGroupSetDialog = null;
  showToast(
    dialog.selectedGroupId === DEFAULT_THREAD_GROUP_ID
      ? `已移动到${DEFAULT_THREAD_GROUP_CONVERSATION_LABEL}`
      : "已设置分组",
    1800,
  );
  render();
}

async function submitThreadGroupEditor() {
  const dialog = state.threadGroupEditor;
  if (!dialog) return;
  const name = dialog.name.trim();
  if (!name) {
    state.threadGroupEditor = { ...dialog, error: "请填写分组" };
    render();
    return;
  }
  if (threadGroups.some((group) => group.name === name && group.id !== dialog.groupId)) {
    state.threadGroupEditor = { ...dialog, error: "分组名称已存在" };
    render();
    return;
  }
  if (!dialog.groupId || isDefaultThreadGroup(dialog.groupId)) {
    state.threadGroupEditor = null;
    ensureDefaultThreadGroup();
    saveThreadPreferences();
    render();
    return;
  }
  const now = new Date().toISOString();
  const index = threadGroups.findIndex((group) => group.id === dialog.groupId);
  if (index >= 0) threadGroups[index] = { ...threadGroups[index], name, updatedAt: now };
  saveThreadPreferences();
  void syncThreadGroupWorkspaces({ renderAfter: false });
  state.threadGroupEditor = null;
  if (dialog.returnToSetDialog) state.threadGroupSetDialog = { ...dialog.returnToSetDialog, dropdownOpen: true, error: null };
  showToast("已重命名分组", 1800);
  render();
}

function threadGroupConversations(groupId: string): ConversationSummary[] {
  if (!threadGroupById(groupId)) return [];
  const grouped = groupedThreadsForList(filteredThreads().filter((thread) => !hiddenThreadIds.has(thread.id)));
  return isDefaultThreadGroup(groupId)
    ? grouped.defaultThreads
    : grouped.groups.find((item) => item.group.id === groupId)?.threads ?? [];
}

function isThreadGroupConversationDeletionBlocked(threadId: string) {
  return isConversationThreadWorking(threadId)
    || submittingComposerThreadIds.has(threadId)
    || isThreadContinuationCreationActive(threadId);
}

async function deleteThreadGroupConversations(groupId: string) {
  if (pendingThreadGroupDeletions.has(groupId)) return;
  const group = threadGroupById(groupId);
  if (!group) return;
  const workspaceGeneration = authenticatedWorkspaceGeneration;
  state.threadGroupMenu = null;
  pendingThreadGroupDeletions.add(groupId);
  render();
  try {
    try {
      // A normal sidebar load only fetches 40 records per workspace. Read all pages
      // before confirmation, including older conversations moved from other folders.
      if (!(await loadThreads({ allPages: true }))) return;
    } catch {
      showToast("无法读取完整会话列表，请稍后重试", 3200);
      return;
    }
    if (workspaceGeneration !== authenticatedWorkspaceGeneration || !threadGroupById(groupId)) return;
    const threads = threadGroupConversations(groupId);
    if (!threads.length) {
      showToast("本组暂无可删除的会话", 1800);
      return;
    }
    // Keep the confirmed scope stable, including pinned and collapsed conversations.
    const threadIds = threads.map((thread) => thread.id);
    const includesAutoTasks = threads.some((thread) => isAutoTaskThread(thread) || autoTaskIdFromThreadId(thread.id));
    const selectedIds = await confirmSelectionInApp({
      title: "删除指定会话",
      message: `分组：${threadGroupDisplayLabel(group)}\n会话数量：${threadIds.length}\n请选择要删除的会话，可多选。`,
      detail: `仅删除勾选的会话，删除后不可恢复。未勾选的会话、分组及文件夹将保留。${includesAutoTasks ? "\n如勾选自动任务，对应任务也将停止执行。" : ""}`,
      confirmLabel: "删除",
      cancelLabel: "取消",
      tone: "danger",
    }, threads.map((thread) => ({
      id: thread.id,
      label: [
        tradingLastAnalysisLabelForThread(thread.id),
        threadListDisplayName(thread).trim() || threadListPreviewText(thread).trim() || NEW_THREAD_TITLE,
      ].filter(Boolean).join(" "),
    })));
    if (!selectedIds?.length || workspaceGeneration !== authenticatedWorkspaceGeneration || !threadGroupById(groupId)) return;
    const selection = new Set(selectedIds);
    const selectedThreadIds = threadIds.filter((threadId) => selection.has(threadId));
    if (!selectedThreadIds.length) return;
    const currentIds = new Set(threadGroupConversations(groupId).map((thread) => thread.id));
    const targets = selectedThreadIds.filter((threadId) => currentIds.has(threadId));
    if (targets.some(isThreadGroupConversationDeletionBlocked)) {
      showToast("所选会话中有会话正在运行，请等待完成或停止后再删除", 3200);
      return;
    }
    // Delete the open conversation last so the existing fallback navigation runs once.
    const currentThreadId = state.currentThreadId;
    targets.sort((a, b) => Number(a === currentThreadId) - Number(b === currentThreadId));
    let failed = targets.length !== selectedThreadIds.length;
    for (const threadId of targets) {
      if (workspaceGeneration !== authenticatedWorkspaceGeneration) return;
      // Membership and busy state can change while a preceding archive request is pending.
      if (!threadGroupConversations(groupId).some((thread) => thread.id === threadId)) {
        failed = true;
        continue;
      }
      if (isThreadGroupConversationDeletionBlocked(threadId)) {
        failed = true;
        continue;
      }
      try {
        await deleteThread(threadId);
      } catch {
        failed = true;
      }
    }
    if (workspaceGeneration !== authenticatedWorkspaceGeneration) return;
    const remainingIds = new Set(threadGroupConversations(groupId).map((thread) => thread.id));
    const remaining = selectedThreadIds.some((threadId) => remainingIds.has(threadId));
    showToast(failed || remaining ? "部分所选会话未删除，请稍后重试" : "所选会话已删除", 2600);
  } finally {
    pendingThreadGroupDeletions.delete(groupId);
    render();
  }
}

function deleteThreadGroup(groupId: string) {
  const returnToSetDialog = state.threadGroupDelete?.returnToSetDialog ?? null;
  const group = threadGroupById(groupId);
  if (!group) return;
  if (isDefaultThreadGroup(groupId)) {
    state.threadGroupDelete = null;
    state.threadGroupMenu = null;
    if (returnToSetDialog) state.threadGroupSetDialog = returnToSetDialog;
    showToast(`${DEFAULT_THREAD_GROUP_CONVERSATION_LABEL}不能删除`, 1800);
    render();
    return;
  }
  const deletedGroupWorkspace = firstString(threadGroupWorkspaceById[groupId], workspaceForGroupId(groupId));
  const index = threadGroups.findIndex((item) => item.id === groupId);
  if (index >= 0) threadGroups.splice(index, 1);
  delete threadGroupWorkspaceById[groupId];
  collapsedThreadGroupIds.delete(groupId);
  expandedConversationProjectIds.delete(groupId);
  if (state.activeNewThreadGroupId === groupId) state.activeNewThreadGroupId = DEFAULT_THREAD_GROUP_ID;
  if (state.autoTaskDraft.groupId === groupId) {
    state.autoTaskDraft = {
      ...state.autoTaskDraft,
      groupId: DEFAULT_THREAD_GROUP_ID,
      importFolderPath: null,
      importFolderName: null,
      error: null,
    };
  }
  for (const [threadId, existingGroupId] of Object.entries(threadGroupByThreadId)) {
    if (existingGroupId === groupId) {
      if (
        shouldDiscardDeletedThreadGroupBlankThread(
          {
            groupId: existingGroupId,
            localBlank: isLocalBlankThreadId(threadId),
            groupBlank: groupBlankThreadIds.has(threadId),
            empty: threadIsEmpty(threadId),
          },
          groupId,
        )
      ) {
        discardDeletedThreadGroupBlankThread(threadId);
        continue;
      }
      rememberThreadWorkspace(threadId, firstString(threadWorkspaceByThreadId[threadId], deletedGroupWorkspace));
      delete threadGroupByThreadId[threadId];
      assignThreadToDefaultGroup(threadId);
    }
  }
  let autoTaskGroupChanged = false;
  state.autoTaskItems = state.autoTaskItems.map((task) => {
    if (task.groupId !== groupId) return task;
    autoTaskGroupChanged = true;
    if (task.threadId) {
      delete threadGroupByThreadId[task.threadId];
      forgetThreadWorkspace(task.threadId);
      forgetThreadModelSettings(task.threadId);
    }
    delete threadGroupByThreadId[autoTaskThreadId(task.id)];
    forgetThreadWorkspace(autoTaskThreadId(task.id));
    forgetThreadModelSettings(autoTaskThreadId(task.id));
    return {
      ...task,
      ...autoTaskGroupMetadata(DEFAULT_THREAD_GROUP_ID),
      threadId: null,
    };
  });
  state.threadGroupDelete = null;
  state.threadGroupMenu = null;
  const nextSetDialog = returnToSetDialog || state.threadGroupSetDialog;
  if (nextSetDialog) {
    state.threadGroupSetDialog = {
      ...nextSetDialog,
      selectedGroupId: nextSetDialog.selectedGroupId === groupId ? DEFAULT_THREAD_GROUP_ID : nextSetDialog.selectedGroupId,
      dropdownOpen: true,
      error: null,
    };
  }
  if (autoTaskGroupChanged) {
    syncAutoTaskThreadSummaries();
    void persistAutoTaskItems();
  }
  saveThreadPreferences();
  showToast(`已删除分组「${group.name}」`, 1800);
  render();
}

function discardDeletedThreadGroupBlankThread(threadId: string) {
  dropThreadAuxiliaryState(threadId);
  const shouldActivateTopLevelBlank = shouldActivateTopLevelBlankAfterDiscard(threadId, state.currentThreadId);
  groupBlankThreadIds.delete(threadId);
  if (state.blankThreadId === threadId) state.blankThreadId = null;
  delete threadGroupByThreadId[threadId];
  forgetThreadWorkspace(threadId);
  forgetThreadTaskAnchor(threadId);
  forgetThreadModelSettings(threadId);
  state.threads = state.threads.filter((thread) => thread.id !== threadId);
  delete state.itemOrder[threadId];
  delete state.items[threadId];
  delete state.threadRoles[threadId];
  delete state.members[threadId];
  delete state.tasks[threadId];
  forgetComposerDraft(threadId);
  clearRememberedChatThreadSelection(threadId);
  if (shouldActivateTopLevelBlank) activateTopLevelBlankThreadAfterDiscard();
}

function activateTopLevelBlankThreadAfterDiscard() {
  const nextThreadId = ensureTopLevelBlankThreadForList();
  state.activeView = "chat";
  state.currentThreadId = nextThreadId;
  state.activeTurnId = state.activeTurnIds[nextThreadId] ?? null;
  ensureThreadState(nextThreadId);
  restoreComposerDraftForThread(nextThreadId);
  rememberChatThreadSelection(nextThreadId);
}

function normalizeExternalFolderPath(value: string | null | undefined) {
  return String(value || "")
    .trim()
    .replace(/\\/g, "/")
    .replace(/\/+$/g, "")
    .toLowerCase();
}

function folderNameFromPath(value: string) {
  const normalized = String(value || "").trim().replace(/\\/g, "/").replace(/\/+$/g, "");
  return normalized.split("/").filter(Boolean).pop() || normalized || "文件夹";
}

function collapseOtherThreadGroupsAfterCreate(createdGroupId: string) {
  collapsedThreadGroupIds.clear();
  for (const group of threadGroups) {
    if (group.id !== createdGroupId) collapsedThreadGroupIds.add(group.id);
    if (group.id !== createdGroupId) expandedConversationProjectIds.delete(group.id);
  }
}

function focusThreadGroupInConversationList(groupId: string | null | undefined) {
  const knownGroupId = knownThreadGroupId(groupId);
  if (!threadGroupById(knownGroupId)) return false;
  collapseOtherThreadGroupsAfterCreate(knownGroupId);
  return true;
}

function upsertExternalThreadGroup(folderName: string, folderPath: string) {
  const normalizedPath = normalizeExternalFolderPath(folderPath);
  const existing = externalThreadGroupByPath(folderPath);
  if (existing) {
    const now = new Date().toISOString();
    const index = threadGroups.findIndex((group) => group.id === existing.id);
    const nextGroup = {
      ...existing,
      name: folderName || existing.name,
      externalPath: folderPath,
      updatedAt: now,
    };
    if (index >= 0) threadGroups[index] = nextGroup;
    threadGroupWorkspaceById[nextGroup.id] = folderPath;
    return nextGroup;
  }
  const now = new Date().toISOString();
  const groupId = safeId("thread-group");
  const group: ThreadGroup = {
    id: groupId,
    name: folderName || folderNameFromPath(folderPath),
    createdAt: now,
    updatedAt: now,
    workspaceSlug: groupId,
    externalPath: folderPath,
  };
  threadGroups.unshift(group);
  threadGroupWorkspaceById[group.id] = folderPath;
  collapseOtherThreadGroupsAfterCreate(group.id);
  return group;
}

function externalThreadGroupByPath(folderPath: string) {
  const normalizedPath = normalizeExternalFolderPath(folderPath);
  if (!normalizedPath) return null;
  return (
    threadGroups.find((group) => normalizeExternalFolderPath(group.externalPath || "") === normalizedPath) ?? null
  );
}

type ThreadGroupImportTarget =
  | "new-thread"
  | "auto-task"
  | "set-dialog"
  | "thread-menu";

function threadGroupImportTargetFromButton(button: HTMLButtonElement): ThreadGroupImportTarget | null {
  const target = button.dataset.threadGroupImportTarget;
  return target === "new-thread" ||
    target === "auto-task" ||
    target === "set-dialog" ||
    target === "thread-menu"
    ? target
    : null;
}

function prepareThreadGroupImportTarget(target: ThreadGroupImportTarget) {
  if (target === "auto-task") updateAutoTaskDraftFromForm();
  state.threadGroupCreateFolder = null;
  state.threadGroupMenu = null;
  if (target === "new-thread") state.newThreadGroupPickerOpen = false;
  if (target === "thread-menu") state.threadMenu = null;
  if (target === "auto-task") state.autoTaskPicker = null;
  if (target === "set-dialog" && state.threadGroupSetDialog) {
    state.threadGroupSetDialog = { ...state.threadGroupSetDialog, dropdownOpen: false, error: null };
  }
  state.profileMenuOpen = false;
  state.skillSortMenuOpen = false;
}

function openThreadGroupCreateFolderDialog(
  target: ThreadGroupImportTarget,
  options: { threadId?: string | null } = {},
) {
  prepareThreadGroupImportTarget(target);
  state.threadGroupCreateFolder = {
    target,
    threadId: options.threadId ?? null,
    name: "",
    saving: false,
    error: null,
  };
  render();
}

function cancelThreadGroupCreateFolderDialog() {
  const target = state.threadGroupCreateFolder?.target ?? null;
  state.threadGroupCreateFolder = null;
  if (target === "set-dialog" && state.threadGroupSetDialog) {
    state.threadGroupSetDialog = { ...state.threadGroupSetDialog, dropdownOpen: true, error: null };
  }
  render();
}

async function submitThreadGroupCreateFolderDialog() {
  const dialog = state.threadGroupCreateFolder;
  if (!dialog) return;
  const name = dialog.name.trim();
  if (!name) {
    state.threadGroupCreateFolder = { ...dialog, error: "请填写文件夹名" };
    render();
    return;
  }
  if (!api.createThreadGroupFolder) {
    state.threadGroupCreateFolder = { ...dialog, error: "当前版本暂不支持新建文件夹" };
    render();
    return;
  }
  state.threadGroupCreateFolder = { ...dialog, name, saving: true, error: null };
  render();
  try {
    const result = await api.createThreadGroupFolder({ name });
    const folderPath = firstString(result?.path);
    if (!folderPath) throw new Error("新建文件夹失败");
    const folderName = firstString(result?.name)?.trim() || name;
    const target = dialog.target;
    state.threadGroupCreateFolder = null;
    await importThreadGroupFolderPath(folderPath, folderName, target, {
      successToast: "增加分组成功！",
      threadId: dialog.threadId,
    });
  } catch (error) {
    state.threadGroupCreateFolder = { ...dialog, name, saving: false, error: errorMessage(error) };
    render();
  }
}

async function importThreadGroupFolder(target: ThreadGroupImportTarget) {
  if (!api.pickThreadGroupFolder) {
    showToast("当前版本暂不支持选择文件夹", 2400);
    return;
  }
  try {
    const result = await api.pickThreadGroupFolder();
    if (result?.canceled) return;
    const folderPath = firstString(result?.path);
    if (!folderPath) return;
    const folderName = firstString(result?.name)?.trim() || folderNameFromPath(folderPath);
    await importThreadGroupFolderPath(folderPath, folderName, target, { successToast: "导入文件夹分组成功！" });
  } catch (error) {
    showToast(`导入文件夹失败：${errorMessage(error)}`, 4000);
    render();
  }
}

async function importThreadGroupFolderPath(
  folderPath: string,
  folderName: string | null | undefined,
  target: ThreadGroupImportTarget,
  options: { successToast?: string; threadId?: string | null } = {},
) {
  const displayName = firstString(folderName)?.trim() || folderNameFromPath(folderPath);
  if (target === "new-thread") {
    selectNewThreadGroupFolder(folderPath, displayName);
    return;
  }
  if (target === "auto-task") {
    selectAutoTaskThreadGroupFolder(folderPath, displayName);
    return;
  }
  const group = upsertExternalThreadGroup(displayName, folderPath);
  if (target === "thread-menu") {
    const targetThread = threadById(options.threadId);
    if (targetThread) {
      rememberThreadWorkspace(targetThread.id, threadWorkspaceCwd(targetThread.id));
      threadGroupByThreadId[targetThread.id] = group.id;
    }
  }
  if (target === "set-dialog" && state.threadGroupSetDialog) {
    state.threadGroupSetDialog = {
      ...state.threadGroupSetDialog,
      selectedGroupId: group.id,
      dropdownOpen: true,
      error: null,
    };
  }
  saveThreadPreferences();
  if (syncAutoTaskThreadGroupMappings()) void persistAutoTaskItems();
  await syncThreadGroupWorkspaces({ renderAfter: false });
  await refreshSkills({ cwd: folderPath, forceReload: true, reason: "thread-group-folder-import" }).catch((error) => {
    console.warn("Failed to refresh imported folder skills", error);
  });
  showToast(options.successToast || "导入文件夹分组成功！", 2200);
  render();
}

function selectNewThreadGroupFolder(folderPath: string, folderName?: string | null) {
  const composerThreadId = currentComposerThreadId();
  const existed = Boolean(externalThreadGroupByPath(folderPath));
  const group = upsertExternalThreadGroup(folderName || folderNameFromPath(folderPath), folderPath);
  selectComposerThreadGroup(composerThreadId, group.id);
  showToast(existed ? "已选择分组，发送任务后会话将归入该分组" : "已创建空分组，发送任务后会话将归入该分组", 2400);
}

function selectAutoTaskThreadGroupFolder(folderPath: string, folderName?: string | null) {
  const existing = externalThreadGroupByPath(folderPath);
  if (existing) {
    state.autoTaskDraft = {
      ...state.autoTaskDraft,
      groupId: existing.id,
      importFolderPath: null,
      importFolderName: null,
      error: null,
    };
  } else {
    state.autoTaskDraft = {
      ...state.autoTaskDraft,
      groupId: DEFAULT_THREAD_GROUP_ID,
      importFolderPath: folderPath,
      importFolderName: folderName || folderNameFromPath(folderPath),
      error: null,
    };
  }
  state.autoTaskPicker = null;
  showToast("已选择分组，创建自动任务后生效", 2200);
  render();
}

function expandableThreadGroupId(threadId: string | null | undefined) {
  if (!threadId) return null;
  const explicitGroupId = threadGroupByThreadId[threadId];
  if (explicitGroupId) return knownThreadGroupId(explicitGroupId);
  const thread = threadById(threadId);
  if (thread && !isTopLevelConversationThread(thread) && isDefaultAssignableThread(thread)) return DEFAULT_THREAD_GROUP_ID;
  return null;
}

function revealThreadGroupForComposerSend(threadId: string | null | undefined) {
  return focusThreadGroupInConversationList(expandableThreadGroupId(threadId));
}

function canCommitNewThreadGroupForSend(threadId: string) {
  // The pending user bubble is inserted before preparation finishes, so the
  // thread is no longer logically empty here. A local blank id still proves
  // that this is the first send before the real Codex thread is created.
  return isLocalBlankThreadId(threadId) || isBlankNewThread(threadId) || providerDraftThreadIds.has(threadId);
}

function commitSelectedNewThreadGroupForSend(threadId: string, selectedGroupId: string) {
  return commitActiveNewThreadGroupForSend(threadId, selectedGroupId);
}

function commitActiveNewThreadGroupForSend(threadId: string, selectedGroupId: string) {
  if (!canCommitNewThreadGroupForSend(threadId)) return null;
  const groupId = selectableThreadGroupId(selectedGroupId);
  const group = threadGroupById(groupId);
  if (!group) return null;
  if (isDefaultThreadGroup(groupId) && !providerDraftThreadIds.has(threadId)) return null;
  threadGroupByThreadId[threadId] = group.id;
  rememberThreadWorkspace(threadId, workspaceForGroupId(group.id));
  saveThreadPreferences();
  return group;
}

function selectComposerThreadGroup(threadId: string | null | undefined, groupId: string) {
  const id = firstString(threadId);
  const group = threadGroupById(groupId);
  if (!id || !group || !providerFromThreadId(id)) return selectActiveNewThreadGroup(groupId);
  if (providerDraftThreadIds.has(id)) state.activeNewThreadGroupId = group.id;
  threadGroupByThreadId[id] = group.id;
  rememberThreadWorkspace(id, workspaceForGroupId(group.id));
  state.newThreadGroupPickerOpen = false;
  saveThreadPreferences();
  void syncThreadGroupWorkspaces({ renderAfter: false });
  void refreshSkills({
    cwd: workspaceForGroupId(group.id),
    forceReload: true,
    reason: "provider-thread-group-switch",
    renderAfter: false,
  }).finally(render);
  render();
  return id;
}

function selectActiveNewThreadGroup(groupId: string) {
  const group = threadGroupById(groupId);
  if (!group) return null;
  state.activeNewThreadGroupId = group.id;
  state.newThreadGroupPickerOpen = false;
  const topLevelBlankThreadId = ensureTopLevelBlankThreadForList();
  const blankThread = currentBlankThread();
  if (blankThread && isDefaultThreadGroup(group.id)) {
    threadGroupByThreadId[blankThread.id] = group.id;
    rememberThreadWorkspace(blankThread.id, workspaceForGroupId(group.id));
  }
  saveThreadPreferences();
  void syncThreadGroupWorkspaces({ renderAfter: false });
  void refreshSkills({ cwd: workspaceForGroupId(group.id), forceReload: true, reason: "thread-group-switch", renderAfter: false }).finally(render);
  render();
  return topLevelBlankThreadId;
}

function pinThreadGroup(groupId: string) {
  const index = threadGroups.findIndex((item) => item.id === groupId);
  if (index < 0) return;
  const now = new Date().toISOString();
  const pinned = !threadGroups[index].pinned;
  threadGroups[index] = {
    ...threadGroups[index],
    pinned,
    pinnedAt: pinned ? now : undefined,
    updatedAt: now,
  };
  state.threadGroupMenu = null;
  saveThreadPreferences();
  showToast(pinned ? "已置顶分组" : "已取消置顶分组", 1800);
  render();
}

function toggleThreadGroupCollapsed(groupId: string) {
  if (!threadGroupById(groupId)) return;
  if (collapsedThreadGroupIds.has(groupId)) collapsedThreadGroupIds.delete(groupId);
  else {
    collapsedThreadGroupIds.add(groupId);
    expandedConversationProjectIds.delete(groupId);
  }
  saveThreadPreferences();
  render();
}

async function toggleThreadPin(threadId: string) {
  const target = threadById(threadId);
  if (!target) return;
  const pinned = !isThreadPinnedByPreference(threadId, Boolean(target.pinned));
  setThreadPinPreference(threadId, pinned);
  state.threads = sortThreadsForList(state.threads.map((thread) =>
      thread.id === threadId ? { ...thread, pinned } : thread));
  saveThreadPreferences();
  render();
  queueThreadPinPreferenceSync(threadId, pinned);
}

function queueThreadPinPreferenceSync(threadId: string, pinned: boolean) {
  const target = threadById(threadId);
  if (!canSyncThreadPinPreference(target)) return;
  pendingThreadPinPreferenceSyncs.set(threadId, pinned);
  if (!activeThreadPinPreferenceSyncs.has(threadId)) void flushThreadPinPreferenceSync(threadId);
}

function canSyncThreadPinPreference(thread: ConversationSummary | null | undefined) {
  if (!api.patchConversationPreferences || !thread?.id) return false;
  if (thread.thread_kind === "local_codex") return false;
  if (isBlankNewThread(thread.id) || isLocalBlankThreadId(thread.id)) return false;
  if (isChannelThread(thread) || channelIdFromThreadId(thread.id)) return false;
  if (isAutoTaskThread(thread) || autoTaskIdFromThreadId(thread.id)) return false;
  if (isProviderThread(thread) || providerFromThreadId(thread.id)) return false;
  return !thread.id.startsWith("local-");
}

async function flushThreadPinPreferenceSync(threadId: string) {
  if (!api.patchConversationPreferences || activeThreadPinPreferenceSyncs.has(threadId)) return;
  activeThreadPinPreferenceSyncs.add(threadId);
  try {
    while (pendingThreadPinPreferenceSyncs.has(threadId)) {
      const pinned = Boolean(pendingThreadPinPreferenceSyncs.get(threadId));
      pendingThreadPinPreferenceSyncs.delete(threadId);
      await api.patchConversationPreferences({ conversationId: threadId, pinned });
    }
  } catch (error) {
    if (isConversationNotFoundSyncError(error)) return;
    showToast(`会话置顶已在本地生效，云端同步失败：${errorMessage(error)}`, 4000);
  } finally {
    activeThreadPinPreferenceSyncs.delete(threadId);
    if (pendingThreadPinPreferenceSyncs.has(threadId)) void flushThreadPinPreferenceSync(threadId);
  }
}

function isConversationNotFoundSyncError(error: unknown) {
  const message = errorMessage(error).toLowerCase();
  return (
    message.includes("conversation not found") || message.includes("http 404")
  );
}

async function deleteAutoTask(taskId: string, options: { threadId?: string | null; showToast?: boolean } = {}) {
  const task = state.autoTaskItems.find((item) => item.id === taskId);
  if (!task) return false;
  const threadIds = new Set<string>();
  const addThreadId = (value: string | null | undefined) => {
    if (value) threadIds.add(value);
  };
  addThreadId(options.threadId);
  addThreadId(autoTaskThreadId(task.id));
  addThreadId(task.threadId);
  addThreadId(ensureAutoTaskThreadId(task));
  const wasCurrent = Boolean(state.currentThreadId && threadIds.has(state.currentThreadId));
  const fallback = filteredThreads().find((thread) => !threadIds.has(thread.id)) ?? null;

  state.threadDelete = null;
  state.autoTaskMenuTaskId = null;
  state.autoTaskItems = state.autoTaskItems.filter((item) => item.id !== task.id);
  if (state.selectedAutoTaskId === task.id) state.selectedAutoTaskId = null;
  for (const threadId of threadIds) {
    groupBlankThreadIds.delete(threadId);
    hiddenThreadIds.delete(threadId);
    pinnedThreadIds.delete(threadId);
    unpinnedThreadIds.delete(threadId);
    forgetThreadNameOverride(threadId);
    forgetThreadMarker(threadId);
    clearUnviewedFinalResult(threadId);
    delete threadGroupByThreadId[threadId];
    forgetThreadWorkspace(threadId);
    clearRememberedChatThreadSelection(threadId);
    delete state.itemOrder[threadId];
    delete state.items[threadId];
    delete state.threadRoles[threadId];
    delete state.members[threadId];
    delete state.tasks[threadId];
    forgetThreadContextUsage(threadId);
    forgetComposerDraft(threadId);
    forgetThreadModelSettings(threadId);
  }
  if (wasCurrent) {
    state.currentThreadId = null;
    state.activeTurnId = null;
    restoreComposerDraftForThread(null);
  }
  syncAutoTaskThreadSummaries();
  saveThreadPreferences();
  saveAutoTaskItemsLocal();
  if (options.showToast !== false) showToast(`自动任务「${task.name}」已删除`, 2600);
  render();

  await persistAutoTaskItems();
  if (wasCurrent && fallback) {
    void selectThread(fallback.id);
  } else if (wasCurrent) {
    void startNewThread();
  } else {
    render();
  }
  return true;
}

async function deleteThread(threadId: string) {
  const target = threadById(threadId);
  if (!target) return;
  if (isLocalGroupChatThread(target)) {
    if (localGroupChatBusyThreadIds.has(threadId)) {
      state.threadDelete = null;
      showToast("群成员仍在回应，请等待本轮结束后再删除群聊", 3200);
      render();
      return;
    }
    const fallback =
      filteredThreads().find((thread) => thread.id !== threadId) ?? null;
    const wasCurrent = state.currentThreadId === threadId;
    state.threadDelete = null;
    const localGroup = localGroupChatRecord(threadId);
    if (localGroup) forgetLocalGroupChatHaoloThreads(localGroup);
    delete localGroupChatRecords[threadId];
    localGroupChatMemberQueries.delete(threadId);
    if (localGroupChatMemberMenu?.threadId === threadId) {
      localGroupChatMemberMenu = null;
    }
    if (localGroupChatMemberDialog?.threadId === threadId) {
      localGroupChatMemberDialog = null;
    }
    if (localGroupChatInfoEditor?.threadId === threadId) {
      localGroupChatInfoEditor = null;
    }
    hiddenThreadIds.delete(threadId);
    pinnedThreadIds.delete(threadId);
    unpinnedThreadIds.delete(threadId);
    delete threadGroupByThreadId[threadId];
    forgetThreadWorkspace(threadId);
    clearRememberedChatThreadSelection(threadId);
    state.threads = state.threads.filter((thread) => thread.id !== threadId);
    delete state.itemOrder[threadId];
    delete state.items[threadId];
    delete state.threadRoles[threadId];
    delete state.members[threadId];
    delete state.tasks[threadId];
    forgetComposerDraft(threadId);
    saveLocalGroupChatRecords();
    saveThreadPreferences();
    if (wasCurrent && fallback) {
      void selectThread(fallback.id);
    } else if (wasCurrent) {
      void startNewThread();
    } else {
      render();
    }
    return;
  }
  if (isThreadContinuationCreationActive(threadId)) {
    state.threadDelete = null;
    showToast("正在创建续接任务，完成后再删除原任务", 3200);
    render();
    return;
  }
  if (isAutoTaskThread(target) || autoTaskIdFromThreadId(threadId)) {
    const task = taskFromThreadId(threadId);
    if (task && (await deleteAutoTask(task.id, { threadId }))) return;
    const fallback = filteredThreads().find((thread) => thread.id !== threadId) ?? null;
    const wasCurrent = state.currentThreadId === threadId;
    state.threadDelete = null;
    hideUnavailableThread(threadId, true);
    if (wasCurrent && fallback) {
      void selectThread(fallback.id);
    } else if (wasCurrent) {
      void startNewThread();
    } else {
      render();
    }
    return;
  }
  const provider = providerFromThreadId(threadId);
  const fallback = filteredThreads().find((thread) => thread.id !== threadId) ?? null;
  const wasCurrent = state.currentThreadId === threadId;
  const wasWechatConnectionThread = isWechatConnectionThread(target) || isWechatConnectionThreadId(threadId);
  const wasFeishuConnectionThread = isFeishuConnectionThread(target) || isFeishuConnectionThreadId(threadId);
  state.threadDelete = null;
  forgetDeletedThreadContinuation(threadId);
  clearThreadHistoryLocally(threadId);
  if (wasWechatConnectionThread) resetDeletedWechatChannelThread(threadId);
  if (wasFeishuConnectionThread) resetDeletedFeishuChannelThread(threadId);
  hideUnavailableThread(threadId, true);

  if (wasCurrent && fallback) {
    void selectThread(fallback.id);
  } else if (wasCurrent) {
    void startNewThread();
  } else {
    render();
  }

  if (provider) {
    saveProviderChatThreads();
    return;
  }

  try {
    await api.archiveThread?.({ threadId });
  } catch {
    // Local removal is persisted even if the Codex archive request is unavailable.
  }
}

function currentThread() {
  const thread = threadById(state.currentThreadId);
  if (thread) return thread;
  const task = taskFromThreadId(state.currentThreadId);
  return task ? autoTaskThreadSummary(task) : null;
}

function currentMessages() {
  const threadId = state.currentThreadId;
  if (!threadId) return [];
  return messagesForThread(threadId);
}

async function cancelLoginRestore() {
  if (state.login.step !== "restore" && !isAuthenticatedWorkspaceLoading()) return;
  startupAuthSeq += 1;
  const baseUrl = state.auth.baseUrl || state.login.baseUrl;
  resetAuthenticatedWorkspace();
  revokeLoginAvatarPreview();
  state.auth.checked = true;
  state.auth.authenticated = false;
  state.auth.profile = null;
  state.login = {
    ...state.login,
    baseUrl,
    identifier: "",
    channel: "",
    primaryIdentifier: "",
    primaryChannel: "",
    secondaryRequiredChannel: "",
    verificationStage: "primary",
    step: "identifier",
    mode: "unknown",
    code: "",
    challenge: null,
    registrationToken: "",
    counter: 0,
    resendReadyAt: null,
    busy: null,
    error: null,
  };
  loginModeCheckSeq += 1;
  state.loading = false;
  state.serverReady = false;
  setDesktopWindowMode("login");
  render();
  try {
    const session = await api.logout();
    applyAuthSession(session, baseUrl);
  } catch (error) {
    state.auth.checked = true;
    state.auth.authenticated = false;
    state.auth.profile = null;
    state.login.error = errorMessage(error);
  } finally {
    if (!state.auth.authenticated) render();
  }
}

function messagesForThread(threadId: string) {
  ensureThreadState(threadId);
  ensureVisibleInsufficientQuotaAgentMessage(threadId);
  const messages = state.itemOrder[threadId]
    .filter((id) => !shouldHideChatItem(state.items[threadId][id]))
    .map((id) => itemToMessage(threadId, id, state.items[threadId][id]))
    .filter(hasRenderableMessageContent);
  const visibleMessages = withPendingChannelAgentReply(threadId, dedupeRenderedOptimisticUserMessages(dedupeExternalChannelInternalPromptEchoes(threadId, messages)));
  const orderedMessages = preserveLiveConversationSupplementMessageOrder(threadId, visibleMessages);
  const messagesWithWorkflowRelay = withWorkflowRelayMessages(threadId, orderedMessages);
  const collapsedMessages = localGroupChatRecord(threadId)
    ? messagesWithWorkflowRelay
    : withCollapsedTurnResults(threadId, messagesWithWorkflowRelay);
  return withThinkingMessage(threadId, collapsedMessages);
}

function isFinalAgentTurnResultMessage(threadId: string, message: Message, messages: Message[]) {
  if (isRenderedUserSideMessage(message) || isThinkingMessage(message) || isMediaGenerationMessage(message)) return false;
  if (message.kind !== "agent_text") return false;
  const item = state.items[threadId]?.[message.id];
  if (item?.type === "channelMessage") return isSearchableChannelAgentMessage(message, item);
  if (!isTurnResultOutputMessage(threadId, message)) return false;
  const messageIndex = messages.findIndex((candidate) => candidate.id === message.id);
  if (messageIndex < 0) return false;
  const group = turnResultGroups(threadId, messages).find((candidate) => candidate.outputIndexes.includes(messageIndex));
  return Boolean(group && group.outputIndexes.at(-1) === messageIndex);
}

function isSearchableChannelAgentMessage(message: Message, item: CodexItem) {
  if (message.kind !== "agent_text") return false;
  if (isExternalChannelStatusOutputMessage(message, item)) return false;
  if (isChannelAgentProgressMessage(item)) return false;
  return Boolean((message.text || "").trim() || message.attachments?.length);
}

function threadHistoryJumpHighlightTargetForMessages(threadId: string): MessageSearchHighlightTarget | null {
  if (state.activeView !== "chat" || state.currentThreadId !== threadId) return null;
  const target = activeThreadHistoryJumpHighlight;
  if (!target || target.threadId !== threadId || target.expiresAt <= Date.now() || !target.keyword.trim()) return null;
  return { messageId: target.messageId, keyword: target.keyword };
}

function searchableConversationMessageText(text: string) {
  return stripAttachmentMetadataText(String(text || ""))
    .replace(/\r\n/g, "\n")
    .replace(/[ \t]+/g, " ")
    .trim();
}

function renderHighlightedSearchText(text: string, keyword: string) {
  const normalizedKeyword = normalizedSearchText(keyword);
  if (!normalizedKeyword) return escapeHtml(text);
  const normalizedText = normalizedSearchText(text);
  let cursor = 0;
  let output = "";
  while (cursor < text.length) {
    const index = normalizedText.indexOf(normalizedKeyword, cursor);
    if (index < 0) break;
    output += escapeHtml(text.slice(cursor, index));
    const end = index + keyword.length;
    output += `<strong class="search-highlight">${escapeHtml(text.slice(index, end))}</strong>`;
    cursor = end;
  }
  return output + escapeHtml(text.slice(cursor));
}

function normalizedSearchText(value: unknown) {
  return String(value ?? "").trim().toLocaleLowerCase();
}

function dedupeExternalChannelInternalPromptEchoes(threadId: string, messages: Message[]) {
  if (!isExternalChannelAgentThreadId(threadId)) return messages;
  const attachmentOnlyKeys = new Set<string>();
  const textOnlyMessages = new Set<string>();
  return messages.filter((message) => {
    if (!isRenderedUserSideMessage(message)) return true;
    const text = stripAttachmentMetadataText(message.text || "").trim();
    const attachmentKeys = (message.attachments || []).map(attachmentIdentity).filter(Boolean);
    if (
      text &&
      attachmentKeys.length &&
      !isExternalChannelBridgeUserMessageId(message.id) &&
      textOnlyMessages.has(text) &&
      attachmentKeys.every((key) => attachmentOnlyKeys.has(key))
    ) {
      return false;
    }
    if (!text && attachmentKeys.length) attachmentKeys.forEach((key) => attachmentOnlyKeys.add(key));
    if (text && !attachmentKeys.length) textOnlyMessages.add(text);
    return true;
  });
}

function isExternalChannelBridgeUserMessageId(id: string | null | undefined) {
  const value = String(id || "");
  return (
    value.startsWith("wechat-user-") || value.startsWith("feishu-user-") || value.startsWith("telegram-user-")
  );
}

function withCollapsedTurnResults(threadId: string, messages: Message[]) {
  const groups = turnResultGroups(threadId, messages);
  if (!groups.length) return messages;
  const hiddenIndexes = new Set<number>();
  const decorated = [...messages];
  for (const [groupIndex, group] of groups.entries()) {
    if (!isTurnResultGroupComplete(threadId, group.turnKey, groupIndex === groups.length - 1)) continue;
    const finalIndex = group.outputIndexes[group.outputIndexes.length - 1];
    const collapsedIndexes = turnResultProcessIndexes(messages, finalIndex);
    if (!collapsedIndexes.length) continue;
    const key = turnResultStateKey(threadId, group.turnKey);
    const expanded = state.resultProcessExpanded[key] === true;
    decorated[finalIndex] = {
      ...decorated[finalIndex],
      turnResult: {
        key,
        elapsedLabel: turnResultElapsedLabel(threadId, group.turnKey, group.outputIndexes, messages),
        status: turnResultDisplayStatus(threadId, group.turnKey, group.outputIndexes, messages),
        expanded,
        collapsedCount: collapsedIndexes.length,
      },
    } as MessageUiMeta;
    if (!expanded) {
      collapsedIndexes.forEach((index) => hiddenIndexes.add(index));
    }
  }
  return hiddenIndexes.size ? decorated.filter((_, index) => !hiddenIndexes.has(index)) : decorated;
}

function turnResultProcessIndexes(messages: Message[], finalIndex: number) {
  let firstProcessIndex = 0;
  for (let index = finalIndex - 1; index >= 0; index -= 1) {
    if (!isRenderedUserSideMessage(messages[index])) continue;
    firstProcessIndex = index + 1;
    break;
  }
  return messages
    .slice(firstProcessIndex, finalIndex)
    .map((_, offset) => firstProcessIndex + offset)
    .filter((index) => !isRenderedUserSideMessage(messages[index]));
}

function isTurnResultGroupComplete(threadId: string, turnKey: string, isLatestGroup: boolean) {
  if (isLatestGroup && tradingExpertThinkingStateByThreadId.has(threadId)) return false;
  const turnId = turnIdFromResultKey(turnKey);
  if (turnId && hasGptPlanProcessForInteraction(threadId, turnId)) {
    const finalItem = (state.itemOrder[threadId] || [])
      .map((itemId) => state.items[threadId]?.[itemId])
      .find((item) => (
        itemTurnId(item) === turnId
        && agentMessagePhase(item) === "final_answer"
      ));
    return questionAnswerStreamState(finalItem)?.status === "completed";
  }
  if (turnId) return !(activeTurnIdForThread(threadId) === turnId && isThreadBusy(threadId));
  return !(isLatestGroup && isThreadBusy(threadId));
}

function turnResultGroups(threadId: string, messages: Message[]) {
  const groups = new Map<string, { turnKey: string; outputIndexes: number[] }>();
  let fallbackTurnIndex = 0;
  messages.forEach((message, index) => {
    if (isRenderedUserSideMessage(message)) {
      fallbackTurnIndex += 1;
      return;
    }
    if (!isTurnResultOutputMessage(threadId, message)) return;
    const item = state.items[threadId]?.[message.id];
    const turnId = itemTurnId(item);
    const turnKey = turnId ? `turn:${turnId}` : `after-user:${fallbackTurnIndex}`;
    const group = groups.get(turnKey) || { turnKey, outputIndexes: [] };
    group.outputIndexes.push(index);
    groups.set(turnKey, group);
  });
  return [...groups.values()];
}

function isTurnResultOutputMessage(threadId: string, message: Message) {
  if (isRenderedUserSideMessage(message) || isThinkingMessage(message) || isMediaGenerationMessage(message)) return false;
  if (message.kind !== "agent_text") return false;
  const item = state.items[threadId]?.[message.id];
  if (isLocalStatusThreadItem(firstString(message.id, item?.id) || "", item)) return false;
  if (isExternalChannelStatusOutputMessage(message, item)) return false;
  return (
    item?.type === "agentMessage" && Boolean((message.text || "").trim() || message.attachments?.length)
  );
}

function isExternalChannelStatusOutputMessage(message: Message, item?: CodexItem) {
  const id = firstString(message.id, item?.id) || "";
  if (
    id.startsWith("wechat-channel-connected-") ||
    id.startsWith("wechat-channel-disconnected-") ||
    id.startsWith("feishu-channel-connected-") ||
    id.startsWith("feishu-channel-disconnected-") ||
    id.startsWith("telegram-channel-connected-") ||
    id.startsWith("telegram-channel-disconnected-")
  ) {
    return true;
  }
  const text = firstString(message.text, item ? itemText(item) : "")?.trim() || "";
  return (
    text === WECHAT_CHANNEL_WELCOME_TEXT ||
    text === WECHAT_CHANNEL_DISCONNECT_REPLY_TEXT ||
    isFeishuChannelWelcomeText(text) ||
    text === FEISHU_CHANNEL_DISCONNECT_REPLY_TEXT ||
    isTelegramChannelWelcomeText(text) ||
    text === TELEGRAM_CHANNEL_DISCONNECT_REPLY_TEXT
  );
}

function turnResultStateKey(threadId: string, turnKey: string) {
  return `${threadId}:${turnKey}`;
}

function turnIdFromResultKey(turnKey: string) {
  return turnKey.startsWith("turn:") ? turnKey.slice(5) : null;
}

function rememberTurnResultStatus(
  threadId: string | null | undefined,
  turnId: string | null | undefined,
  status: string | null | undefined,
) {
  const normalizedThreadId = firstString(threadId);
  const normalizedTurnId = firstString(turnId);
  const normalizedStatus = firstString(status)?.toLowerCase();
  if (!normalizedThreadId || !normalizedTurnId || !normalizedStatus) return;
  for (const itemId of state.itemOrder[normalizedThreadId] || []) {
    const item = state.items[normalizedThreadId]?.[itemId];
    if (item && itemTurnId(item) === normalizedTurnId) item.__youleTurnStatus = normalizedStatus;
  }
}

function cachedConsumptionStatusForTurn(threadId: string, turnId: string | null) {
  if (!turnId) return null;
  const records = consumptionPayload(state.consumption.records);
  const items = Array.isArray(records?.items) ? records.items : [];
  const record = items.find((item: any) => {
    const recordTurnId = firstString(item?.interaction_id, item?.interactionId, item?.turn_id, item?.turnId);
    const recordThreadIds = [
      firstString(item?.conversation_id, item?.conversationId, item?.thread_id, item?.threadId),
      firstString(item?.child_conversation_id, item?.childConversationId),
      firstString(item?.desktop_thread_id, item?.desktopThreadId),
    ];
    return recordTurnId === turnId && recordThreadIds.includes(threadId);
  });
  return record ? firstString(record?.status) : null;
}

function normalizedTurnResultStatus(value: unknown) {
  return String(value || "").replace(/[^a-z0-9]/gi, "").toLowerCase();
}

function turnResultDisplayStatus(threadId: string, turnKey: string, indexes: number[], messages: Message[]): "handled" | "pending" {
  const turnId = turnIdFromResultKey(turnKey);
  const items = indexes
    .map((index) => state.items[threadId]?.[messages[index].id])
    .filter((item): item is CodexItem => Boolean(item));
  const phases = items
    .filter((item) => item.type === "agentMessage")
    .map((item) => agentMessagePhase(item))
    .filter(Boolean);
  // A terminal transport event does not turn progress commentary into a
  // deliverable. Keep the group pending until a final answer is present.
  if (phases.length && !phases.includes("final_answer")) return "pending";
  const consumptionStatus = cachedConsumptionStatusForTurn(threadId, turnId);
  if (consumptionStatus) return consumptionStatus === "pending" ? "pending" : "handled";
  if (turnId && interruptedCodexTurnIds.has(turnId)) return "pending";
  const turnStatuses = items
    .map((item) => normalizedTurnResultStatus(item.__youleTurnStatus))
    .filter(Boolean);
  if (turnStatuses.some((status) => ["completed", "complete", "success", "succeeded"].includes(status))) {
    return "handled";
  }
  if (turnStatuses.length) return "pending";
  return "handled";
}

function turnResultElapsedLabel(threadId: string, turnKey: string, indexes: number[], messages: Message[]) {
  const turnId = turnIdFromResultKey(turnKey);
  const timing = turnId ? turnTiming(threadId, turnId) : null;
  const elapsedIndexes = new Set(indexes);
  const finalIndex = indexes.length ? Math.max(...indexes) : -1;
  if (finalIndex >= 0) {
    turnResultProcessIndexes(messages, finalIndex).forEach((index) => elapsedIndexes.add(index));
  }
  const items = [...elapsedIndexes]
    .map((index) => state.items[threadId]?.[messages[index]?.id])
    .filter((item): item is CodexItem => Boolean(item));
  const itemStart = minFinite(items.map(turnItemStartMs));
  const itemEnd = maxFinite(items.map(turnItemEndMs));
  const sortStart = minFinite(items.map(itemSortTime));
  const sortEnd = maxFinite(items.map(itemSortTime));
  const running = Boolean(turnId && activeTurnIdForThread(threadId) === turnId && isThreadBusy(threadId));
  let startMs = timing?.startedAtMs ?? itemStart ?? sortStart ?? (running ? Date.now() : null);
  const endMs = running ? Date.now() : (timing?.completedAtMs ?? itemEnd ?? sortEnd ?? startMs ?? Date.now());
  if (!running && finalIndex >= 0 && (startMs == null || endMs <= startMs)) {
    const previousUserStart = previousTurnResultUserStartMs(threadId, messages, finalIndex);
    if (previousUserStart != null && previousUserStart < endMs) startMs = previousUserStart;
  }
  return formatElapsedDuration(startMs == null ? 0 : Math.max(0, endMs - startMs));
}

function previousTurnResultUserStartMs(threadId: string, messages: Message[], beforeIndex: number) {
  for (let index = beforeIndex - 1; index >= 0; index -= 1) {
    if (!isRenderedUserSideMessage(messages[index])) continue;
    const item = state.items[threadId]?.[messages[index].id];
    return item ? (turnItemStartMs(item) ?? itemSortTime(item)) : null;
  }
  return null;
}

function activeThinkingElapsedLabel(threadId: string) {
  const tradingExpertThinking = tradingExpertThinkingStateByThreadId.get(threadId);
  if (tradingExpertThinking) {
    return formatElapsedDuration(Math.max(0, Date.now() - tradingExpertThinking.startedAtMs));
  }
  const activeTurnId = activeTurnIdForThread(threadId);
  const timing = (activeTurnId ? turnTiming(threadId, activeTurnId) : null) ?? turnTiming(threadId, null);
  const startMs = timing?.startedAtMs ?? null;
  return startMs == null ? null : formatElapsedDuration(Math.max(0, Date.now() - startMs));
}

function turnItemStartMs(item: CodexItem) {
  return sortTimeFromValues((item as any).__youleTurnStartedAt, item.createdAt, item.created_at);
}

function turnItemEndMs(item: CodexItem) {
  return sortTimeFromValues((item as any).__youleTurnCompletedAt, item.updatedAt, item.updated_at, item.createdAt, item.created_at);
}

function minFinite(values: Array<number | null>) {
  const finite = values.filter((value): value is number => value != null && Number.isFinite(value));
  return finite.length ? Math.min(...finite) : null;
}

function maxFinite(values: Array<number | null>) {
  const finite = values.filter((value): value is number => value != null && Number.isFinite(value));
  return finite.length ? Math.max(...finite) : null;
}

function dedupeRenderedOptimisticUserMessages(messages: Message[]) {
  // A content key identifies a possible transport echo, not a message across
  // the lifetime of the thread. Restrict fallback deduplication to adjacent
  // user rows so intentionally repeated prompts after an assistant response
  // remain separate turns. Canonical upserts already remove their matching
  // optimistic item by id/content before this rendering fallback is needed.
  return dedupeAdjacentRenderedUserMessages(messages);
}

function activeCodexThinkingStage(threadId: string): ThinkingStagePresentation {
  const activeTurnId = activeTurnIdForThread(threadId);
  if (!activeTurnId) {
    return {
      key: "preparing",
      label: "正在准备请求",
      detail: "正在整理本轮上下文并提交",
    };
  }

  const activeItems = (state.itemOrder[threadId] || [])
    .map((id) => state.items[threadId]?.[id])
    .filter((item): item is CodexItem => Boolean(item))
    .filter((item) => itemTurnId(item) === activeTurnId)
    .filter((item) => !isCodexUserMessageItem(item) && !isContextCompactionItem(item));
  const latestItem = activeItems.at(-1);
  if (!latestItem) {
    return {
      key: "waiting",
      label: "等待模型响应",
      detail: "请求已提交，正在等待首个模型事件",
    };
  }
  if (latestItem.type === "agentMessage") {
    return {
      key: "generating",
      label: "正在生成回复",
      detail: "模型已开始生成可见内容",
    };
  }
  if (latestItem.type === "reasoning") {
    return {
      key: "reasoning",
      label: "模型正在推理",
      detail: "已收到模型事件，正在分析任务",
    };
  }
  if (latestItem.type === "plan") {
    return {
      key: "planning",
      label: "正在规划任务",
      detail: "正在整理任务步骤和执行顺序",
    };
  }
  return {
    key: "executing",
    label: "智能体正在执行",
    detail: "正在调用工具或处理执行结果",
  };
}

function dedupeAdjacentRenderedUserMessages(messages: Message[]) {
  const deduped: Message[] = [];
  let previousUserKey = "";
  for (const message of messages) {
    if (!isRenderedUserSideMessage(message)) {
      deduped.push(message);
      previousUserKey = "";
      continue;
    }
    const key = renderedUserMessageDedupKey(message);
    const previous = deduped.at(-1);
    if (key && key === previousUserKey && previous && isRenderedUserSideMessage(previous)) {
      if (isWechatOptimisticUserItemId(previous.id)) {
        continue;
      }
      if (isWechatOptimisticUserItemId(message.id)) {
        deduped[deduped.length - 1] = message;
      } else if (isOptimisticUserItemId(previous.id) && !isOptimisticUserItemId(message.id)) {
        deduped[deduped.length - 1] = message;
      }
      continue;
    }
    deduped.push(message);
    previousUserKey = key;
  }
  return deduped;
}

function isRenderedUserSideMessage(message: Message) {
  return (
    message.role === "user" || message.kind === "user_text" || message.align_right === true
  );
}

function preserveLiveConversationSupplementMessageOrder(threadId: string, messages: Message[]) {
  if (!liveConversationSupplementOrderById.size || !messages.length) return messages;
  let next = messages;
  let changed = false;

  for (const [supplementId, snapshot] of liveConversationSupplementOrderById) {
    if (snapshot.threadId !== threadId) continue;
    const supplementIndex = next.findIndex((message) => conversationSupplementIdFromMessage(message) === supplementId);
    if (supplementIndex <= 0) continue;
    const supplementMessage = next[supplementIndex];
    const targetTurnId = firstString(itemTurnId(state.items[threadId]?.[supplementMessage.id]), snapshot.turnId);

    const before = next.slice(0, supplementIndex);
    const moved: Message[] = [];
    const keptBefore: Message[] = [];
    for (const message of before) {
      if (shouldMoveAfterLiveConversationSupplement(threadId, message, snapshot, targetTurnId)) {
        moved.push(message);
      } else {
        keptBefore.push(message);
      }
    }
    if (!moved.length) continue;
    next = [...keptBefore, next[supplementIndex], ...moved, ...next.slice(supplementIndex + 1)];
    changed = true;
  }

  return changed ? next : messages;
}

function shouldMoveAfterLiveConversationSupplement(
  threadId: string,
  message: Message,
  snapshot: ConversationSupplementOrderSnapshot,
  targetTurnId: string | null,
) {
  if (message.kind !== "agent_text") return false;
  if (isRenderedUserSideMessage(message) || isThinkingMessage(message)) return false;
  if (!isConversationSupplementTargetTurnMessage(targetTurnId, itemTurnId(state.items[threadId]?.[message.id]))) return false;
  if (snapshot.beforeMessageIds.has(message.id)) return false;
  const signature = liveConversationSupplementMessageSignature(message);
  return Boolean(signature && !snapshot.beforeMessageSignatures.has(signature));
}

function renderedUserMessageDedupKey(message: Message) {
  const text = stripAttachmentMetadataText(message.text || "").trim();
  const attachments = (message.attachments || []).map(attachmentIdentity).filter(Boolean).sort().join("\n");
  return text || attachments ? `${text}\n${attachments}` : "";
}

function withPendingChannelAgentReply(threadId: string, messages: Message[]) {
  const channelId = channelIdFromThreadId(threadId);
  if (!channelId || state.currentThreadId !== threadId) return messages;
  const pending = pendingChannelAgentReplies.get(channelId);
  const latest = pending ? Array.from(pending.values()).at(-1) : null;
  if (!latest) return messages;
  const senderLabel = desktopAgentPendingSenderLabel(channelId);
  if (latest.generationType && !hasMediaResult(messages, latest.generationType)) {
    return [
      ...messages,
      {
        id: `channel-media-generation-${channelId}-${latest.requestMessageId}-${latest.generationType}`,
        conversation_id: threadId,
        kind: "media_generation" as const,
        role: "ceo_assistant",
        sender_label: senderLabel,
        text: null,
        generationType: latest.generationType,
      } as MediaGenerationMessage,
    ];
  }
  return messages;
}

function desktopAgentPendingSenderLabel(channelId: string) {
  const target = desktopAgentTargetParticipant(channelId);
  const name = target ? channelParticipantName(target) : null;
  return contactAgentDisplayName(name || "对方");
}

function scrollAttachmentRail(direction: "left" | "right") {
  const rail = root.querySelector<HTMLElement>(".pending-attachments");
  if (!rail) return;
  const distance = Math.max(rail.clientWidth * 0.72, 180);
  rail.scrollBy({
    left: direction === "left" ? -distance : distance,
    behavior: "smooth",
  });
  window.setTimeout(updateAttachmentScrollControls, 220);
}

function updateAttachmentScrollControls() {
  const rail = root.querySelector<HTMLElement>(".pending-attachments");
  const leftButton = root.querySelector<HTMLButtonElement>('[data-attachment-scroll="left"]');
  const rightButton = root.querySelector<HTMLButtonElement>('[data-attachment-scroll="right"]');
  if (!rail || !leftButton || !rightButton) return;
  const maxScrollLeft = Math.max(0, rail.scrollWidth - rail.clientWidth);
  leftButton.hidden = rail.scrollLeft <= 1;
  rightButton.hidden = rail.scrollLeft >= maxScrollLeft - 1;
}

function persistedSubagentStatusEntriesForParent(
  parentThreadId: string,
  preferredTurnId: string | null,
  allowLegacyFallback: boolean,
) {
  const associated = [...subagentActivityByThreadId.entries()].filter(
    ([childThreadId, activity]) =>
      childThreadId !== parentThreadId &&
      activity.parentThreadId === parentThreadId,
  );
  const selectedThreadIds = new Set(
    selectPersistedSubagentThreadIds(
      associated.map(([threadId, activity]) => ({
        threadId,
        parentTurnId: activity.parentTurnId,
        startedAtMs: activity.startedAtMs,
        completedAtMs: activity.completedAtMs,
      })),
      preferredTurnId,
      allowLegacyFallback,
    ),
  );
  const selected = associated.filter(([threadId]) => selectedThreadIds.has(threadId));

  return selected.map(([threadId, activity]) =>
    persistedSubagentStatusEntry({
      threadId,
      task: activity.task,
      busy: activity.busy,
      failed: activity.failed,
    }),
  );
}

function activeSubagentUiEntries(threadId: string): SubagentUiEntry[] {
  if (isMultiModelClusterThread(threadId)) return [];
  const order = state.itemOrder[threadId] || [];
  const activeTurnId = activeTurnIdForThread(threadId);
  const latestUserIndex = order.reduce(
    (latest, id, index) => isUserSideThreadItem(state.items[threadId]?.[id]) ? index : latest,
    -1,
  );
  const processItems = order
    .map((id, index) => ({ item: state.items[threadId]?.[id], index }))
    .filter(({ item }) => isSubagentProcessItem(item))
    .filter(({ item, index }) => {
      const turnId = itemTurnId(item);
      return activeTurnId ? turnId === activeTurnId || (!turnId && index > latestUserIndex) : index > latestUserIndex;
    })
    .map(({ item }) => item as CodexItem);
  const processEntries = buildSubagentStatusEntries(processItems)
    .filter((agent) => shouldShowSubagentStatusEntry({
      parentThreadId: threadId,
      childThreadId: agent.threadId,
      confirmedParentThreadId: subagentActivityByThreadId.get(agent.threadId)?.parentThreadId,
      isKnownInternal: internalSubagentThreadIds.has(agent.threadId),
      isListedTopLevel: Boolean(threadById(agent.threadId)),
    }));
  const latestThreadTurnId =
    activeTurnId ||
    [...order]
      .slice(latestUserIndex + 1)
      .reverse()
      .map((id) => itemTurnId(state.items[threadId]?.[id]))
      .find(Boolean) ||
    null;
  const persistedEntries = persistedSubagentStatusEntriesForParent(
    threadId,
    latestThreadTurnId,
    processEntries.length === 0,
  );
  const entries = [...processEntries];
  const visibleThreadIds = new Set(entries.map((entry) => entry.threadId));
  for (const entry of persistedEntries) {
    if (visibleThreadIds.has(entry.threadId)) continue;
    entries.push(entry);
    visibleThreadIds.add(entry.threadId);
  }
  return entries
    .map((agent) => applySubagentActivityLifecycle(agent, subagentActivityByThreadId.get(agent.threadId)))
    .map((agent, index) => {
      const latestSourceItem = [...processItems]
        .reverse()
        .find((item) => subagentThreadIdsFromItem(item).includes(agent.threadId));
      const activity = subagentActivityByThreadId.get(agent.threadId);
      const activityTimestamp = activity?.completedAtMs ?? activity?.startedAtMs;
      return {
        ...agent,
        name: SUBAGENT_PERSONA_NAMES[index % SUBAGENT_PERSONA_NAMES.length],
        profession: subagentProfessionForTask(agent.task, index),
        avatarUrl: SUBAGENT_AVATAR_URLS[index % SUBAGENT_AVATAR_URLS.length],
        outputTime: formatThreadTime(
          firstString(
            latestSourceItem?.createdAt,
            latestSourceItem?.created_at,
            latestSourceItem?.__youleFirstSeenAt,
            activityTimestamp ? new Date(activityTimestamp).toISOString() : null,
          ),
        ),
      };
    });
}

function withWorkflowRelayMessages(threadId: string, messages: Message[]) {
  if (!isMultiModelClusterThread(threadId)) return messages;
  const run = workflowRunsByThreadId.get(threadId);
  if (!run || !multiModelClusterMembersJoined(run)) return messages;
  const entries = workflowRelayEntries(run);
  if (!entries.length) return messages;
  const relayMessages = entries.map((entry): MessageUiMeta => {
    const modelProvider = entry.nodeKind === "model" ? providerFromValue(entry.provider) : null;
    const modelMeta = modelProvider ? PROVIDER_CHAT_META[modelProvider] : null;
    const senderLabel =
      entry.nodeKind === "root"
        ? "Haolo"
        : entry.nodeKind === "agent"
          ? "Haolo子Agent"
          : entry.nodeKind === "context"
            ? "本地材料"
            : modelMeta?.name || entry.model || entry.nodeTitle;
    return {
      id: entry.id,
      conversation_id: threadId,
      kind: "agent_text",
      role: "ceo_assistant",
      provider: modelProvider || undefined,
      sender_label: senderLabel,
      avatar_url: modelMeta?.avatarUrl || APP_AVATAR_URL,
      time: entry.time ? formatThreadTime(entry.time) : null,
      text: [entry.summary, entry.task, ...entry.handoffTargets.map((target) => `@${target.mention} ${target.instruction}`)]
        .filter(Boolean)
        .join("\n"),
      workflowRelay: entry,
    };
  });
  let insertionIndex = messages.length;
  for (let index = messages.length - 1; index >= 0; index -= 1) {
    if (isRenderedUserSideMessage(messages[index])) {
      insertionIndex = index + 1;
      break;
    }
  }
  return [
    ...messages.slice(0, insertionIndex),
    ...relayMessages,
    ...messages.slice(insertionIndex),
  ];
}

function withThinkingMessage(threadId: string, messages: Message[]) {
  const visible = messages.filter((message) => !isThinkingNoiseMessage(message));
  if (state.currentThreadId !== threadId) return visible;
  if (localGroupChatRecord(threadId)) {
    return withLocalGroupChatThinkingMessages(threadId, visible);
  }
  const tradingExpertThinking = tradingExpertThinkingStateByThreadId.get(threadId);
  if (tradingExpertThinking) {
    const thinkingStage = tradingExpertThinkingStage(
      tradingExpertThinking.phase,
      tradingExpertThinking.reasoningSummary,
      tradingExpertThinking.message,
    );
    return [
      ...visible,
      {
        id: `thinking-${threadId}`,
        conversation_id: threadId,
        kind: "interaction",
        role: "ceo_assistant",
        thinkingElapsedLabel: activeThinkingElapsedLabel(threadId),
        thinkingStage,
        text: thinkingStage.label,
      } as MessageUiMeta,
    ];
  }
  const busy = isThreadBusy(threadId);
  if (!busy) return visible;
  if (hasActiveContextCompaction(threadId)) return visible;
  if (hasActiveVideoGenerationState(threadId)) return visible;
  if (hasActiveFinalAnswerMessage(threadId)) return visible;
  const questionAnswerProgress = latestQuestionAnswerProgressForThread(threadId);
  if (
    isGptPlanQuestionAnswerProgress(questionAnswerProgress)
    && hasGptPlanVisibleOutputForInteraction(
      threadId,
      questionAnswerProgress!.interactionId,
    )
  ) return visible;
  if (visible.some((message) => questionAnswerProgressFromMessage(message)?.status === "running")) return visible;
  if (isMultiModelClusterThread(threadId)) {
    const run = workflowRunsByThreadId.get(threadId);
    if (!multiModelClusterMembersJoined(run)) return visible;
    if (workflowRelayEntries(run as WorkflowCanvasRun).length) return visible;
  }
  const subagents = activeSubagentUiEntries(threadId);
  const thinkingStage = activeCodexThinkingStage(threadId);
  const thinkingMessage: MessageUiMeta = {
    id: `thinking-${threadId}`,
    conversation_id: threadId,
    kind: "interaction",
    role: inferActiveThinkingRole(threadId),
    provider: effectiveProviderForThread(threadId) || undefined,
    thinkingElapsedLabel: activeThinkingElapsedLabel(threadId),
    subagents,
    text: thinkingStage.label,
  };
  return [...visible, thinkingMessage];
}

function withLocalGroupChatThinkingMessages(
  threadId: string,
  messages: Message[],
) {
  const run = localGroupChatRunsByThreadId.get(threadId);
  const record = localGroupChatRecord(threadId);
  if (!run || run.stopRequested || !record) return messages;
  const thinkingMessages = Array.from(run.pendingMembers.values())
    .filter((pending) => {
      if (!pending.interactionId) return true;
      const streamItem = state.items[threadId]?.[
        questionAnswerStreamItemId(pending.interactionId)
      ];
      return !streamItem || !itemText(streamItem).trim();
    })
    .map((pending): MessageUiMeta => {
      const member =
        localGroupChatMember(record, pending.member.selectionId)
        || pending.member;
      const presentation = localGroupChatMemberPresentation(member);
      return {
        id: `thinking-${threadId}-${run.id}-${member.selectionId}`,
        conversation_id: threadId,
        kind: "interaction",
        role: "ceo_assistant",
        sender_label: presentation.name,
        avatar_url: presentation.avatarUrl || undefined,
        localGroupThinkingMemberId: member.selectionId,
        text: "正在思考",
      };
    });
  return [...messages, ...thinkingMessages];
}

function hasActiveVideoGenerationState(threadId: string) {
  return (state.itemOrder[threadId] || []).some((id) => {
    const item = state.items[threadId]?.[id];
    return item?.kind === "media_generation" && item?.generationType === "video";
  });
}

function hasActiveContextCompaction(threadId: string) {
  const status = state.threadContextUsage[threadId]?.compactionStatus;
  if (status === "requesting" || status === "compacting") return true;
  if (contextCompactionPromises.has(threadId)) return true;
  return (state.itemOrder[threadId] || []).some((id) => {
    const item = state.items[threadId]?.[id];
    if (!isContextCompactionItem(item)) return false;
    const itemStatus = contextCompactionUiStatusFromItem(item as CodexItem);
    return itemStatus === "requesting" || itemStatus === "compacting";
  });
}

function hasActiveFinalAnswerMessage(threadId: string) {
  const workflowRun = activeWorkflowRunForThread(threadId);
  const activeResponseId = activeThinkingResponseId({
    providerBusy: isProviderThreadBusy(threadId),
    providerInteractionId: activeProviderInteractionByThreadId.get(threadId),
    codexBusy: activeCodexThreadIds.has(threadId),
    codexTurnId: activeTurnIdForThread(threadId),
    workflowRunId: workflowRun?.id,
  });
  if (!activeResponseId) return false;
  return (state.itemOrder[threadId] || []).some((id) => {
    const item = state.items[threadId]?.[id];
    return isFinalAnswerForThinkingResponse(activeResponseId, {
      responseId: itemTurnId(item),
      isFinalAnswer: isFinalAnswerAgentItem(item),
      hasRenderableContent: Boolean(
        itemText(item).trim()
        || itemAttachments(item).length
        || messageActionsFromItem(item)?.length
      ),
    });
  });
}

function isFinalAnswerAgentItem(item: CodexItem | undefined) {
  if (!item || item.type !== "agentMessage") return false;
  return agentMessagePhase(item) === "final_answer";
}

function isThinkingNoiseMessage(message: Message) {
  if (isContextCompactionMessage(message)) return false;
  const text = (message.text || "").trim();
  return (
    message.id.startsWith("channel-thinking-") || message.kind === "interaction" || text === "Thinking..." || text === "正在思考" || text === "模型正在推理"
  );
}

function hasRenderableMessageContent(message: Message) {
  if (message.kind === "agent_card") return true;
  const questionAnswerProgress = questionAnswerProgressFromMessage(message);
  if (questionAnswerProgress) {
    return shouldRenderQuestionAnswerProgressMessage(message);
  }
  if (isThinkingMessage(message)) return true;
  if (isContextCompactionMessage(message)) return true;
  if (isMediaGenerationMessage(message)) return true;
  if ((message.text || "").trim()) return true;
  if (message.attachments?.length) return true;
  if (message.images?.length) return true;
  if (message.actions?.length) return true;
  if ((message as MessageUiMeta).threadReferencePreviews?.length) return true;
  return false;
}

function shouldRenderQuestionAnswerProgressMessage(message: Message) {
  const progress = questionAnswerProgressFromMessage(message);
  if (progress?.status !== "running") return false;
  if (isGptPlanQuestionAnswerProgress(progress)) return false;
  const streamItem = state.items[message.conversation_id]?.[
    questionAnswerStreamItemId(progress.interactionId)
  ];
  return !streamItem || !itemText(streamItem).trim();
}

function isGptPlanQuestionAnswerProgress(
  progress: QuestionAnswerProgressRun | null | undefined,
) {
  return (
    progress?.provider === "codex"
    && /^gpt(?:-|$)/i.test(firstString(progress.model) || "")
    && !localGroupChatRecord(progress.threadId)
  );
}

function inferActiveThinkingRole(threadId: string): RoleKey {
  const items = state.itemOrder[threadId]?.map((id) => state.items[threadId][id]).filter(Boolean) ?? [];
  for (let index = items.length - 1; index >= 0; index -= 1) {
    const role = inferItemRole(threadId, items[index]);
    if (role !== "user") return role;
  }
  return "ceo_assistant";
}

function shouldHideChatItem(item: CodexItem | undefined) {
  if (!item) return false;
  const record = item as Record<string, unknown>;
  if (
    firstString(record.__youleVideoGenerationActor) &&
    firstString(record.__youleVideoGenerationInteractionId)
  ) return true;
  if (isThreadContinuationInternalText(itemText(item))) return true;
  if ((item as Record<string, unknown>).__youleContextWindowRecoveryReplay === true) return true;
  if ((item as Record<string, unknown>).__youleLocalProxyRecoveryReplay === true) return true;
  if ((item as Record<string, unknown>).__youleHiddenExternalChannelAgentPrompt === true) return true;
  if (isHiddenRoleItem(item)) return true;
  if (isAttachmentMetadataOnlyUserMessage(item) && !itemAttachments(item).length) return true;
  if (isSubagentProcessItem(item)) return true;
  if (isInternalProcessItem(item)) return true;
  if (item.type === "system" && !itemHasDisplayAttachments(item)) return true;
  const text = itemText(item);
  if (text.includes(AUTOMATIC_TURN_RECOVERY_MARKER)) return true;
  return isNoisyReconnectError(text) || isMissingRolloutError(text);
}

function isHiddenRoleItem(item: CodexItem) {
  return Boolean(explicitHiddenAgentRole(item) || hiddenSenderLabelFromItem(item));
}

function hiddenSenderLabelFromItem(item: CodexItem) {
  const record = item as Record<string, unknown>;
  if (providerFromValue(record.provider)) return false;
  const agent = record.agent && typeof record.agent === "object" ? (record.agent as Record<string, unknown>) : null;
  const label = firstString(
    record.sender_label,
    record.senderLabel,
    record.agent_name,
    record.agentName,
    agent?.name,
    agent?.display_name,
    agent?.displayName,
  );
  return Boolean(label && isHiddenRoleLabel(label));
}

function isChannelAgentProgressMessage(item: CodexItem | ChannelMessage) {
  if ((item as any).type && (item as any).type !== "channelMessage") return false;
  if (!isChannelAgentSender(firstString((item as any).sender_type, (item as any).senderType), item)) return false;
  const payload = channelMessagePayload(item);
  const status = firstString(payload.task_status, payload.taskStatus, payload.status);
  const text = (firstString((item as any).text) || "").trim();
  if (status === "running" || status === "waiting_approval") return true;
  return /^还在处理中[，,。]|^正在处理[，,。]|暂时还没好/.test(text);
}

function isAttachmentMetadataOnlyUserMessage(item: CodexItem) {
  if (item.type !== "userMessage") return false;
  const text = itemText(item);
  return Boolean(text.trim()) && stripAttachmentMetadataText(text) === "";
}

function isInternalProcessItem(item: CodexItem) {
  return (
    item.type === "commandExecution" || item.type === "reasoning" || item.type === "plan"
  );
}

function itemHasDisplayAttachments(item: CodexItem) {
  return Array.isArray(item.attachments) && item.attachments.length > 0;
}

function isMissingRolloutError(text: string) {
  return text.toLowerCase().includes("no rollout found for thread id");
}

function isNoisyReconnectError(text: string) {
  const normalized = text.trim().toLowerCase();
  if (!normalized.startsWith("error:")) return false;
  return (
    normalized.includes("responsestreamdisconnected") ||
    normalized.includes("route /openai/responses not found") ||
    normalized.includes("/openai/responses not found") ||
    (normalized.includes("reconnecting") && normalized.includes("willretry"))
  );
}

function messageActionsFromItem(item: CodexItem) {
  const isTradingPreferenceBinanceInvitation = item.type === "agentMessage"
    && assistantVisibleText(itemText(item)).trim() === TRADING_PREFERENCE_BINANCE_INVITATION;
  const binanceAlreadyConnected = isTradingPreferenceBinanceInvitation
    && state.binanceAccount.status?.bound === true;
  const rawActions = (item as { actions?: unknown }).actions;
  const actions = (Array.isArray(rawActions) ? rawActions : [])
    .map((raw): MessageAction | null => {
      if (!raw || typeof raw !== "object") return null;
      const record = raw as Record<string, unknown>;
      const label = firstString(record.label, record.title, record.name);
      if (!label) return null;
      return {
        id: firstString(record.id, record.action_id, record.actionId, record.kind) || undefined,
        kind: firstString(record.kind, record.type) || undefined,
        label,
        text: firstString(record.text, record.message, record.prompt) || undefined,
        conversation_id: firstString(record.conversation_id, record.conversationId, record.thread_id, record.threadId) || undefined,
        destination: firstString(record.destination) || undefined,
        alert_id: firstString(record.alert_id, record.alertId) || undefined,
      };
    })
    .filter((action): action is MessageAction => Boolean(
      action
      && !(binanceAlreadyConnected && action.destination === "binance-account")
    ));
  if (actions.length) return actions;
  if (isTradingPreferenceBinanceInvitation && !binanceAlreadyConnected) {
    return [{
      id: "connect-binance-account",
      kind: "navigate",
      label: "连接币安",
      destination: "binance-account",
    }];
  }
  return undefined;
}

function tradingPreferenceBinanceVisibleText(item: CodexItem) {
  const text = assistantVisibleText(itemText(item));
  return item.type === "agentMessage"
    && state.binanceAccount.status?.bound === true
    && text.trim() === TRADING_PREFERENCE_BINANCE_INVITATION
      ? TRADING_PREFERENCE_BINANCE_CONNECTED
      : text;
}

function itemToMessage(threadId: string, id: string, item: CodexItem): Message {
  const localGroupMemberEvent = localGroupChatMemberEventFromItem(item);
  if (localGroupMemberEvent) {
    return {
      id,
      conversation_id: threadId,
      kind: "agent_text",
      role: "ceo_assistant",
      time: formatThreadTime(item.created_at || item.createdAt),
      text: localGroupChatMemberEventText(localGroupMemberEvent),
      localGroupMemberEvent,
    } as MessageUiMeta;
  }
  const questionAnswerProgress = questionAnswerProgressFromItem(item);
  if (questionAnswerProgress) {
    const meta = PROVIDER_CHAT_META[questionAnswerProgress.provider];
    return {
      id,
      conversation_id: threadId,
      kind: "agent_text",
      role: meta.role,
      provider: questionAnswerProgress.provider,
      sender_label: meta.name,
      avatar_url: meta.avatarUrl,
      time: formatThreadTime(item.created_at || item.createdAt),
      text: null,
      questionAnswerProgress,
    } as MessageUiMeta;
  }
  const mediaGenerationType =
    item.kind === "media_generation" && (item.generationType === "image" || item.generationType === "video")
      ? item.generationType
      : null;
  if (mediaGenerationType) {
    return {
      id,
      conversation_id: threadId,
      kind: "media_generation",
      role: inferItemRole(threadId, item),
      provider: providerFromValue((item as { provider?: unknown }).provider) || providerFromThreadId(threadId) || undefined,
      sender_label: firstString(item.sender_label),
      align_right: item.align_right === true,
      time: formatThreadTime(item.created_at || item.createdAt),
      text: itemText(item),
      generationType: mediaGenerationType,
    } as MediaGenerationMessage;
  }
  if (item.type === "channelMessage") {
    const senderType = firstString((item as any).sender_type, (item as any).senderType) || "user";
    const senderUserId = firstString((item as any).sender_user_id, (item as any).senderUserId);
    const fromChannelAgent = isChannelAgentSender(senderType, item);
    const sourceUserId = channelMessageSourceUserId(item);
    const effectiveSenderUserId = fromChannelAgent ? sourceUserId || senderUserId : senderUserId;
    const fromCurrentUser =
      effectiveSenderUserId && state.auth.profile?.id ? effectiveSenderUserId === state.auth.profile.id : id.startsWith("local-channel-");
    const senderLabel = channelSenderLabel(threadId, senderUserId, senderType, item);
    const fromCurrentHuman = fromCurrentUser && !fromChannelAgent;
    const channelQuotePreview = fromCurrentHuman ? quotePreviewFromComposerQuote(composerQuoteFromChannelPayload(channelMessagePayload(item))) : null;
    const channelMessage = {
      id,
      conversation_id: threadId,
      kind: fromCurrentHuman ? "user_text" : "agent_text",
      role: fromCurrentHuman ? "user" : "ceo_assistant",
      sender_type: senderType,
      sender_label: senderLabel,
      avatar_url: fromCurrentHuman ? null : directChannelThreadAvatarUrl(threadId),
      align_right: Boolean(fromCurrentUser),
      time: formatThreadTime((item as any).created_at || (item as any).createdAt),
      text: fromCurrentHuman ? itemText(item) : assistantVisibleText(itemText(item)),
      attachments: itemAttachments(item),
      quotePreview: channelQuotePreview,
    } as MessageUiMeta;
    return withLocalSendStatus(
      channelMessage,
      item,
    );
  }
  if (item.type === "userMessage") {
    const display = userMessageDisplayParts(item);
    const userMessage = {
      id,
      conversation_id: threadId,
      kind: "user_text",
      role: "user",
      time: formatThreadTime((item as any).created_at || (item as any).createdAt),
      text: display.text,
      attachments: itemAttachments(item),
      quotePreview: display.quote,
      threadReferencePreviews: display.threadReferences,
    } as MessageUiMeta;
    return withLocalSendStatus(
      userMessage,
      item,
    );
  }
  if (isContextCompactionItem(item)) {
    const status = contextCompactionUiStatusFromItem(item);
    return {
      id,
      conversation_id: threadId,
      kind: "interaction",
      role: "ceo_assistant",
      time: formatThreadTime(item.created_at || item.createdAt),
      text: null,
      contextCompaction: {
        status,
        error: contextCompactionUiErrorFromItem(item),
        elapsedLabel:
          status === "requesting" || status === "compacting"
            ? contextCompactionElapsedLabel(threadId, item)
            : null,
      },
    } as MessageUiMeta;
  }
  if (item.type === "commandExecution") {
    return {
      id,
      conversation_id: threadId,
      kind: "agent_card",
      role: inferItemRole(threadId, item),
      text: null,
      card: {
        icon: "doc",
        title: String(item.command || "Command"),
        tag: String(item.status || "queued"),
        tag_status: item.status === "completed" ? "done" : "running",
        items: [String(item.aggregatedOutput || "等待输出...")],
        progress: item.status === "completed" ? 100 : 45,
      },
    };
  }
  if (item.type === "system" && itemHasDisplayAttachments(item)) {
    return {
      id,
      conversation_id: threadId,
      kind: "agent_text",
      role: inferItemRole(threadId, item),
      text: "",
      attachments: itemAttachments(item),
    };
  }
  return {
    id,
    conversation_id: threadId,
    kind: item.type === "system" ? "system" : item.type === "reasoning" ? "interaction" : "agent_text",
    role: inferItemRole(threadId, item),
    provider: providerFromValue((item as { provider?: unknown }).provider) || providerFromThreadId(threadId) || undefined,
    sender_label: firstString(item.sender_label),
    avatar_url: firstString(item.avatar_url, item.avatarUrl, item.avatar_image, item.avatarImage),
    localGroupMemberId: firstString(
      (item as CodexItem & { __youleLocalGroupMemberId?: string })
        .__youleLocalGroupMemberId,
    ),
    align_right: item.align_right === true,
    time: formatThreadTime(item.created_at || item.createdAt),
    text: tradingPreferenceBinanceVisibleText(item),
    attachments: item.type === "agentMessage" ? itemAttachments(item) : undefined,
    actions: messageActionsFromItem(item),
    videoGenerationActor:
      item.__youleVideoGenerationActor === "haolo" ||
      item.__youleVideoGenerationActor === "video-expert"
        ? item.__youleVideoGenerationActor
        : null,
    executionPlanPresentation:
      item.__youleExecutionPlanPresentation === "execution-plan" ||
      item.__youleExecutionPlanPresentation === "plain"
        ? item.__youleExecutionPlanPresentation
        : null,
  } as MessageUiMeta;
}

function withLocalSendStatus<T extends Message>(message: T, item: CodexItem): T {
  const status = localSendStatusFromRecord(item);
  const record = message as MessageUiMeta & Record<string, unknown>;
  const supplement = conversationSupplementMetaFromRecord(item);
  if (supplement) {
    record.conversationSupplement = supplement;
    rememberConversationSupplementItem(message.conversation_id, message.id, supplement.id);
  }
  if (!status) return message;
  record.__youleLocalSendStatus = status;
  const error = firstString((item as Record<string, unknown>).__youleLocalSendError, (item as Record<string, unknown>).localSendError);
  if (error) record.__youleLocalSendError = error;
  return message;
}

function itemText(item: CodexItem) {
  if (item.type === "channelMessage") {
    return String(item.text || "");
  }
  if (isCodexUserMessageItem(item)) {
    return rawUserMessageText(item);
  }
  if (item.type === "agentMessage") {
    return String(item.text || "");
  }
  if (item.type === "reasoning") {
    return (
      [...(item.summary || []), item.contentText || ""].filter(Boolean).join("\n") || "模型正在推理"
    );
  }
  if (item.type === "commandExecution") {
    return [item.command, item.status, item.aggregatedOutput].filter(Boolean).join("\n");
  }
  return String(item.text || "");
}

function sanitizeIncomingThreadItem(item: CodexItem, threadId?: string | null) {
  item = sanitizeProcessItemText(item);
  if (!isCodexUserMessageItem(item)) return item;
  const rawText = rawUserMessageText(item);
  const hideExternalPrompt = consumeHiddenExternalChannelAgentPrompt(threadId, rawText);
  const hideContextRecoveryReplay = isContextWindowRecoveryReplayText(rawText);
  const hideLocalProxyRecoveryReplay = isLocalProxyRecoveryReplayText(rawText);
  const supplementId = conversationSupplementIdFromSteerText(rawText);
  const sanitized = sanitizeUserMessageItem(item);
  const supplementFields = supplementId ? conversationSupplementFieldsFromState(supplementId) : null;
  const hiddenFields = {
    ...(hideExternalPrompt ? { __youleHiddenExternalChannelAgentPrompt: true } : {}),
    ...(hideContextRecoveryReplay ? { __youleContextWindowRecoveryReplay: true } : {}),
    ...(hideLocalProxyRecoveryReplay ? { __youleLocalProxyRecoveryReplay: true } : {}),
  };
  if (supplementFields) return { ...sanitized, ...supplementFields, ...hiddenFields };
  return hideExternalPrompt || hideContextRecoveryReplay || hideLocalProxyRecoveryReplay
    ? { ...sanitized, ...hiddenFields }
    : sanitized;
}

function sanitizeProcessItemText(item: CodexItem): CodexItem {
  if (item.type === "commandExecution") {
    if (item.aggregatedOutput == null) return item;
    const aggregatedOutput = boundedProcessText(item.aggregatedOutput);
    return aggregatedOutput === item.aggregatedOutput ? item : { ...item, aggregatedOutput };
  }
  if (item.type !== "reasoning") return item;

  let next = item;
  if (item.contentText != null) {
    const contentText = boundedProcessText(item.contentText);
    if (contentText !== item.contentText) next = { ...next, contentText };
  }
  if (Array.isArray(item.summary)) {
    const summaryText = item.summary.map((part) => String(part || "")).filter(Boolean).join("\n");
    const boundedSummaryText = boundedProcessText(summaryText);
    if (boundedSummaryText !== summaryText) next = { ...next, summary: [boundedSummaryText] };
  }
  return next;
}

function sanitizeUserMessageItem(item: CodexItem): CodexItem {
  const rawContentText = rawUserMessageText(item);
  const rawTopLevelText = firstString(item.text, (item as any).message, (item as any).contentText, (item as any).content_text) || "";
  const textSources = uniqueStrings([rawContentText, rawTopLevelText]);
  const attachments = dedupeMessageAttachments(
    [
      ...rawThreadItemAttachments(item),
      ...textSources.flatMap((text) => extractAttachmentsFromText(text)),
    ].filter(isUserMessageDisplayAttachment),
  );
  const cleanText = cleanVisibleMessageText(rawContentText || rawTopLevelText);
  const firstPart = Array.isArray(item.content) && item.content.length ? item.content[0] : {};
  const firstPartWithoutPath = { ...firstPart };
  delete firstPartWithoutPath.url;
  delete firstPartWithoutPath.path;
  return {
    ...item,
    type: "userMessage",
    text: cleanText,
    content: [{ ...firstPartWithoutPath, text: cleanText, attachments }],
    attachments,
  };
}

function rememberHiddenExternalChannelAgentPrompt(threadId: string | null | undefined, text: string) {
  if (!isExternalChannelAgentThreadId(threadId)) return;
  const key = hiddenExternalChannelAgentPromptKey(text);
  if (!key) return;
  let keys = hiddenExternalChannelAgentPromptKeys.get(threadId!);
  if (!keys) {
    keys = new Set<string>();
    hiddenExternalChannelAgentPromptKeys.set(threadId!, keys);
  }
  keys.add(key);
  while (keys.size > 30) {
    const oldest = keys.values().next().value;
    if (!oldest) break;
    keys.delete(oldest);
  }
}

function consumeHiddenExternalChannelAgentPrompt(threadId: string | null | undefined, text: string) {
  if (!isExternalChannelAgentThreadId(threadId)) return false;
  const key = hiddenExternalChannelAgentPromptKey(text);
  const keys = key ? hiddenExternalChannelAgentPromptKeys.get(threadId!) : null;
  if (!keys?.has(key)) return false;
  keys.delete(key);
  if (!keys.size) hiddenExternalChannelAgentPromptKeys.delete(threadId!);
  return true;
}

function hiddenExternalChannelAgentPromptKey(text: string) {
  return String(text || "").replace(/\r\n/g, "\n").trim();
}

function isExternalChannelAgentThreadId(threadId: string | null | undefined) {
  return (
    isWechatConnectionThreadId(threadId) || isFeishuConnectionThreadId(threadId) || isTelegramConnectionThreadId(threadId)
  );
}

function isCodexUserMessageItem(item: CodexItem) {
  if (!item || item.type === "channelMessage") return false;
  const record = item as Record<string, unknown>;
  const type = firstString(item.type, record.message_type, record.messageType);
  const kind = firstString(record.kind, record.message_kind, record.messageKind);
  const role = firstString(record.role, record.author_role, record.authorRole, record.sender_role, record.senderRole);
  return (
    type === "userMessage" || type === "user_message" || kind === "user_text" || role === "user" || record.align_right === true
  );
}

function rawUserMessageText(item: CodexItem) {
  const record = item as Record<string, unknown>;
  const content = record.content;
  const contentText =
    typeof content === "string"
      ? content
      : Array.isArray(content)
        ? content
            .map((part) => {
              if (typeof part === "string") return part;
              if (!part || typeof part !== "object") return "";
              const partRecord = part as Record<string, unknown>;
              return (
                firstString(partRecord.text, partRecord.content, partRecord.message, partRecord.url, partRecord.path) || ""
              );
            })
            .filter(Boolean)
            .join("\n")
        : "";
  return (
    contentText || firstString(item.text, record.message, record.contentText, record.content_text, record.value) || ""
  );
}

function rawThreadItemAttachments(item: CodexItem) {
  const content = Array.isArray(item.content) ? item.content : [];
  return [
    ...(Array.isArray(item.attachments) ? item.attachments : []),
    ...content.flatMap((part) =>
      Array.isArray(part.attachments) ? part.attachments : []),
  ];
}

function uniqueStrings(values: string[]) {
  const seen = new Set<string>();
  return values.filter((value) => {
    const text = String(value || "");
    if (!text || seen.has(text)) return false;
    seen.add(text);
    return true;
  });
}

function isUserMessageDisplayAttachment(attachment: MessageAttachment) {
  const name = firstString(attachment.name);
  if (isInternalMemoryAttachmentName(name)) return false;
  return hasUserMessageAttachmentLocator(attachment);
}

function isInternalMemoryAttachmentName(name: unknown) {
  return looksLikeConversationMemoryTitle(name);
}

function looksLikeConversationMemoryTitle(name: unknown) {
  const text = String(name || "").trim();
  return /^(?:\d{4}[/-]\d{1,2}[/-]\d{1,2}|\d{4}年\d{1,2}月\d{1,2}日)\s+\d{1,2}:\d{2}(?::\d{2})?\s*[|｜]/u.test(text);
}

function hasUserMessageAttachmentLocator(attachment: MessageAttachment) {
  const record = attachment as unknown as Record<string, unknown>;
  return Boolean(
    firstString(
      attachment.url,
      attachment.object_key,
      record.objectKey,
      record.material_id,
      record.materialId,
      record.previewUrl,
      record.local_path,
      record.localPath,
      record.file_path,
      record.filePath,
      record.path,
    ),
  );
}

function userMessageDisplayText(item: CodexItem) {
  return userMessageDisplayParts(item).text;
}

function cleanVisibleMessageText(text: string) {
  return normalizeHaoloDisplayText(stripAttachmentMetadataText(stripInternalTurnGroupMemoryText(text)));
}

function normalizeHaoloDisplayText(text: string) {
  return String(text || "").replace(/\u5c0f\u5499/g, "\u5c0f\u54af");
}

function assistantVisibleText(text: string) {
  return redactVideoGenerationCompletionMetadata(cleanVisibleMessageText(text));
}

function stripInternalTurnGroupMemoryText(text: string) {
  let cleanText = stripHaoloInternalMessageBlocks(String(text || ""));
  const leakedMarker = cleanText.match(/\bhaolo(?:[_\s-]*internal)(?:[_\s-]*(?:turn|tu)[\w.-]*)/i);
  if (leakedMarker && leakedMarker.index != null) {
    return cleanText.slice(0, leakedMarker.index).trim();
  }
  return cleanText.trim();
}

function stripHaoloInternalMessageBlocks(text: string) {
  let cleanText = String(text || "");
  for (let guard = 0; guard < 20; guard += 1) {
    let changed = false;
    for (const [startMarker, endMarker] of HAOLO_INTERNAL_MESSAGE_BLOCKS) {
      const start = cleanText.indexOf(startMarker);
      if (start < 0) continue;
      const end = cleanText.indexOf(endMarker, start + startMarker.length);
      cleanText =
        end >= 0
          ? `${cleanText.slice(0, start)}${cleanText.slice(end + endMarker.length)}`
          : cleanText.slice(0, start);
      changed = true;
    }
    if (!changed) break;
  }
  return stripTrailingInternalBlockStartPrefix(cleanText);
}

function stripTrailingInternalBlockStartPrefix(text: string) {
  let cleanText = String(text || "");
  for (const [startMarker] of HAOLO_INTERNAL_MESSAGE_BLOCKS) {
    for (let length = startMarker.length - 1; length >= 7; length -= 1) {
      const prefix = startMarker.slice(0, length);
      if (cleanText.endsWith(prefix)) {
        cleanText = cleanText.slice(0, -length);
        break;
      }
    }
  }
  return cleanText;
}

function extractSupplementResolutionBlocks(text: string) {
  const blocks: string[] = [];
  const value = String(text || "");
  let searchFrom = 0;
  while (searchFrom < value.length) {
    const start = value.indexOf(SUPPLEMENT_RESOLUTION_START, searchFrom);
    if (start < 0) break;
    const contentStart = start + SUPPLEMENT_RESOLUTION_START.length;
    const end = value.indexOf(SUPPLEMENT_RESOLUTION_END, contentStart);
    if (end < 0) break;
    blocks.push(value.slice(contentStart, end).trim());
    searchFrom = end + SUPPLEMENT_RESOLUTION_END.length;
  }
  return blocks;
}

function parseSupplementResolutionBlock(block: string) {
  let parsed: Record<string, unknown>;
  try {
    parsed = JSON.parse(block) as Record<string, unknown>;
  } catch {
    return null;
  }
  const supplementId = firstString(parsed.id, parsed.supplementId, parsed.supplement_id);
  if (!supplementId) return null;
  const rawStatus = firstString(parsed.status, parsed.result, parsed.state);
  const applied = parsed.applied === true || rawStatus === "applied" || rawStatus === "accepted";
  const notApplied = parsed.applied === false || rawStatus === "not_applied" || rawStatus === "notApplied" || rawStatus === "ineffective";
  const status: ConversationSupplementStatus | null = notApplied ? "ineffective" : applied ? "accepted" : null;
  if (!status) return null;
  return {
    supplementId,
    status,
    reason: firstString(parsed.reason, parsed.message, parsed.detail) || (notApplied ? SUPPLEMENT_INEFFECTIVE_LABEL : null),
  };
}

function applySupplementResolutionBlocks(threadId: string | null | undefined, turnId: string | null | undefined, text: string) {
  if (!threadId) return;
  for (const block of extractSupplementResolutionBlocks(text)) {
    const resolution = parseSupplementResolutionBlock(block);
    if (!resolution) continue;
    const supplementId = resolution.supplementId;
    const key = `${threadId}:${turnId || "latest"}:${supplementId}:${stableUiHash(block)}`;
    if (appliedSupplementResolutionKeys.has(key)) continue;
    appliedSupplementResolutionKeys.add(key);
    setConversationSupplementStatus(supplementId, resolution.status, { reason: resolution.reason });
  }
}

type ConversationSupplementHistoryTarget = {
  itemId: string;
  supplementId: string;
};

function restoreConversationSupplementStatusesFromHistory(threadId: string) {
  ensureThreadState(threadId);
  const order = state.itemOrder[threadId] || [];
  const targetsByTurnAndId = new Map<string, ConversationSupplementHistoryTarget>();
  const targetsById = new Map<string, ConversationSupplementHistoryTarget[]>();
  for (const itemId of order) {
    const item = state.items[threadId]?.[itemId];
    const supplementId = conversationSupplementIdFromRecord(item);
    if (!item || !supplementId) continue;
    rememberConversationSupplementItem(threadId, itemId, supplementId);
    const target = { itemId, supplementId };
    const turnId = itemTurnId(item);
    if (turnId) targetsByTurnAndId.set(conversationSupplementHistoryTargetKey(turnId, supplementId), target);
    const matches = targetsById.get(supplementId) || [];
    matches.push(target);
    targetsById.set(supplementId, matches);
  }
  for (const itemId of order) {
    const item = state.items[threadId]?.[itemId];
    if (!item || item.type !== "agentMessage") continue;
    const turnId = itemTurnId(item);
    const rawText = firstString((item as Record<string, unknown>).__youleRawAgentText, item.text, (item as Record<string, unknown>).contentText) || "";
    for (const block of extractSupplementResolutionBlocks(rawText)) {
      const resolution = parseSupplementResolutionBlock(block);
      if (!resolution) continue;
      const target =
        (turnId ? targetsByTurnAndId.get(conversationSupplementHistoryTargetKey(turnId, resolution.supplementId)) : null) ||
        uniqueConversationSupplementHistoryTarget(targetsById.get(resolution.supplementId));
      if (!target) continue;
      setConversationSupplementItemStatus(threadId, target.itemId, target.supplementId, resolution.status, { reason: resolution.reason });
    }
  }
}

function conversationSupplementHistoryTargetKey(turnId: string, supplementId: string) {
  return `${turnId}:${supplementId}`;
}

function uniqueConversationSupplementHistoryTarget(targets: ConversationSupplementHistoryTarget[] | null | undefined) {
  return targets?.length === 1 ? targets[0] : null;
}

function stripAttachmentMetadataText(text: string) {
  const cleanText = stripInternalTurnGroupMemoryText(text);
  const marker = attachmentMetadataMarkerMatch(cleanText);
  if (!marker || marker.index == null) return cleanText.trim();
  const block = cleanText.slice(marker.index);
  if (!isAttachmentMetadataBlock(block)) return cleanText.trim();
  if (isInternalAttachmentOnlyPrompt(cleanText)) return "";
  return cleanText.slice(0, marker.index).trim();
}

function attachmentMetadataMarkerMatch(text: string) {
  return text.match(/(?:^|\n\n)(?:附件[:：]|附件信息（仅供理解与后续处理，不要直接复述）[:：])\s*\n/u);
}

function isInternalAttachmentOnlyPrompt(text: string) {
  return (
    text.startsWith("用户只发送了附件，没有输入文字说明。") &&
    text.includes("不要在回复中列出、复述、嵌入这些附件") &&
    Boolean(attachmentMetadataMarkerMatch(text))
  );
}

function isAttachmentMetadataBlock(text: string) {
  return /\b(object_key|url|preview_url|previewUrl|download_url|downloadUrl|local_path|localPath|file_path|filePath|path|material_id):/u.test(text);
}

function itemAttachments(item: CodexItem): MessageAttachment[] {
  const attachments = [
    ...(Array.isArray(item.attachments) ? item.attachments : []),
    ...(Array.isArray(item.content) ? item.content : []).flatMap((part) =>
      Array.isArray(part.attachments) ? part.attachments : []),
    ...extractAttachmentsFromText(itemText(item)),
  ];
  const visibleAttachments = isCodexUserMessageItem(item) ? attachments.filter(isUserMessageDisplayAttachment) : attachments;
  return dedupeMessageAttachments(visibleAttachments.filter((attachment) => Boolean(attachment?.name || attachment?.url || attachment?.object_key)));
}

function extractAttachmentsFromText(text: string): MessageAttachment[] {
  const cleanText = stripInternalTurnGroupMemoryText(text);
  const marker = attachmentMetadataMarkerMatch(cleanText);
  if (!marker || marker.index == null) return [];
  const block = cleanText.slice(marker.index + marker[0].length);
  const attachments: MessageAttachment[] = [];
  let attachmentListStarted = false;
  for (const line of block.split(/\r?\n/)) {
    const trimmed = line.trim();
    // Media creation inserts an attachment-reference explanation between the
    // "附件：" marker and the actual attachment rows. Scan past that preamble,
    // then keep the attachment list contiguous once its first valid row starts.
    if (!attachmentListStarted && (!trimmed || !trimmed.startsWith("-"))) continue;
    if (attachmentListStarted && (!trimmed || !trimmed.startsWith("-"))) break;
    if (looksLikeConversationMemoryTitle(trimmed.replace(/^-\s*/, ""))) break;
    const attachment = parseAttachmentLine(trimmed);
    if (!attachment) {
      if (attachmentListStarted) break;
      continue;
    }
    attachmentListStarted = true;
    attachments.push(attachment);
  }
  return attachments;
}

function attachmentDisplayNameParts(displayName: string) {
  const mediaReference = displayName.match(
    /^((?:图片|视频|音频|文件夹|文件)\d+)（(.+)）$/u,
  );
  return {
    name: mediaReference?.[2]?.trim() || displayName,
    mediaReferenceLabel: mediaReference?.[1]?.trim() || null,
  };
}

function parseAttachmentLine(line: string): MessageAttachment | null {
  const match = line.match(/^-\s+(.+?)(?:\s+\((.*)\))?$/);
  if (!match) return null;
  const displayName = match[1]?.trim();
  if (!displayName) return null;
  const { name, mediaReferenceLabel } =
    attachmentDisplayNameParts(displayName);
  const meta = match[2] || "";
  if (!isAttachmentMetadataBlock(meta)) return null;
  const objectKey = cleanAttachmentMetaReference(attachmentMetaValue(meta, "object_key")) || null;
  const rawUrl = cleanAttachmentMetaReference(attachmentMetaValue(meta, "url"));
  const rawPreviewUrl = cleanAttachmentMetaReference(attachmentMetaValue(meta, "preview_url") || attachmentMetaValue(meta, "previewUrl"));
  const rawDownloadUrl = cleanAttachmentMetaReference(attachmentMetaValue(meta, "download_url") || attachmentMetaValue(meta, "downloadUrl"));
  const rawLocalPath = cleanAttachmentMetaReference(
    attachmentMetaValue(meta, "local_path") ||
      attachmentMetaValue(meta, "localPath") ||
      attachmentMetaValue(meta, "file_path") ||
      attachmentMetaValue(meta, "filePath") ||
      attachmentMetaValue(meta, "path"),
  );
  const rawPreviewReference = firstString(rawPreviewUrl, rawDownloadUrl);
  const url = rawUrl
    ? isRemoteLikeUrlReference(rawUrl)
      ? rawUrl
      : localPathPreviewUrl(rawUrl)
    : rawPreviewReference
      ? isRemoteLikeUrlReference(rawPreviewReference)
        ? rawPreviewReference
        : localPathPreviewUrl(rawPreviewReference)
      : null;
  const localPath = rawLocalPath
    ? localPathPreviewUrl(rawLocalPath)
    : rawUrl && !isRemoteLikeUrlReference(rawUrl)
      ? localPathPreviewUrl(rawUrl)
      : rawPreviewReference && !isRemoteLikeUrlReference(rawPreviewReference)
        ? localPathPreviewUrl(rawPreviewReference)
      : null;
  if (!objectKey && !url && !localPath) return null;
  const mime = firstString(
    attachmentMetaValue(meta, "mime"),
    attachmentMetaValue(meta, "mime_type"),
    attachmentMetaValue(meta, "mimeType"),
    attachmentMetaValue(meta, "content_type"),
    attachmentMetaValue(meta, "contentType"),
  );
  const size = numericValue(
    attachmentMetaValue(meta, "size") ||
      attachmentMetaValue(meta, "size_bytes") ||
      attachmentMetaValue(meta, "sizeBytes") ||
      attachmentMetaValue(meta, "file_size") ||
      attachmentMetaValue(meta, "fileSize"),
  );
  return {
    name,
    mime: mime || generatedFileMimeFromPath(name || url || localPath || objectKey || ""),
    size: size ?? null,
    object_key: objectKey,
    url,
    local_path: localPath,
    path: localPath,
    media_reference_label: mediaReferenceLabel,
    preview_url: rawPreviewUrl ? isRemoteLikeUrlReference(rawPreviewUrl) ? rawPreviewUrl : localPathPreviewUrl(rawPreviewUrl)
      : null,
    download_url: rawDownloadUrl ? isRemoteLikeUrlReference(rawDownloadUrl) ? rawDownloadUrl : localPathPreviewUrl(rawDownloadUrl)
      : null,
  };
}

function attachmentMetaValue(meta: string, key: string) {
  const escapedKey = key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const keys =
    "object_key|objectKey|url|preview_url|previewUrl|download_url|downloadUrl|local_path|localPath|file_path|filePath|path|material_id|materialId|size|size_bytes|sizeBytes|file_size|fileSize|mime|mime_type|mimeType|content_type|contentType";
  const match = meta.match(new RegExp(`(?:^|,\\s*)${escapedKey}:\\s*([\\s\\S]*?)(?=,\\s*(?:${keys}):|$)`, "u"));
  return match?.[1]?.trim() || null;
}

function cleanAttachmentMetaReference(value: string | null) {
  return value ? cleanGeneratedPathReference(value) : "";
}

function inferItemRole(threadId: string, item?: CodexItem): RoleKey {
  const explicitRole = explicitAgentRole(item);
  if (explicitRole) return explicitRole;
  if (item?.type === "system") return "ceo_assistant";
  if (item?.type === "commandExecution" || item?.type === "reasoning" || item?.type === "agentMessage") {
    return (
      state.threadRoles[threadId] ?? inferRoleFromText(threadContextText(threadId, item)) ?? "ceo_assistant"
    );
  }
  return (
    inferRoleFromText(item ? itemText(item) : "") ?? state.threadRoles[threadId] ?? inferRoleFromText(threadContextText(threadId, item)) ?? "ceo_assistant"
  );
}

function explicitAgentRole(item?: CodexItem) {
  if (!item) return null;
  const record = item as Record<string, unknown>;
  const agent = record.agent && typeof record.agent === "object" ? (record.agent as Record<string, unknown>) : null;
  const candidates = [record.role, record.agent_id, record.agentId, record.runner, agent?.id, agent?.role];
  for (const candidate of candidates) {
    const role = normalizeRole(candidate);
    if (role && role !== "user") return role;
  }
  return null;
}

function explicitHiddenAgentRole(item?: CodexItem) {
  if (!item) return null;
  const record = item as Record<string, unknown>;
  const agent = record.agent && typeof record.agent === "object" ? (record.agent as Record<string, unknown>) : null;
  const candidates = [record.role, record.agent_id, record.agentId, record.runner, agent?.id, agent?.role];
  return candidates.find(isHiddenRoleKey) || null;
}

function isHiddenRoleKey(value: unknown) {
  return typeof value === "string" && HIDDEN_ROLE_KEYS.has(value);
}

function normalizeRole(value: unknown): RoleKey | null {
  if (typeof value !== "string" || !ROLE_KEY_SET.has(value as RoleKey)) return null;
  const role = value as RoleKey;
  return visibleRole(role);
}

function threadContextText(threadId: string, item?: CodexItem) {
  const thread = state.threads.find((entry) => entry.id === threadId);
  const parts = [thread?.name, thread?.preview, item ? itemText(item) : ""];
  const recentIds = (state.itemOrder[threadId] || []).slice(-8);
  for (const id of recentIds) {
    const recent = state.items[threadId]?.[id];
    if (!recent || recent === item || recent.type === "reasoning" || recent.type === "commandExecution") continue;
    parts.push(itemText(recent));
  }
  return parts.filter(Boolean).join("\n").toLowerCase();
}

function threadUserIntentText(threadId: string) {
  const thread = state.threads.find((entry) => entry.id === threadId);
  const parts = [thread?.name, thread?.preview];
  for (const id of state.itemOrder[threadId] || []) {
    const item = state.items[threadId]?.[id];
    if (item?.type === "userMessage") {
      parts.push(userMessageDisplayText(item));
    }
  }
  return parts.filter(Boolean).join("\n").toLowerCase();
}

function inferRoleFromText(text: string): RoleKey | null {
  const compact = text.replace(/\s+/g, "");
  for (const rule of ROLE_INFERENCE_RULES) {
    if (!VISIBLE_ROLE_KEYS.has(rule.role)) continue;
    if (rule.keywords.some((keyword) => compact.includes(keyword.toLowerCase()))) return rule.role;
  }
  return null;
}

function syncThreadMembersForRole(threadId: string, role: RoleKey) {
  if (providerFromThreadId(threadId)) {
    ensureThreadState(threadId);
    return;
  }
  const roles = SPECIALIST_MEMBER_ROLES[role];
  if (!roles) return;
  const current = state.members[threadId] ?? fallbackMembers("main_session");
  state.members[threadId] = visibleAgentMembers(roles.map((id) => current.find((member) => member.id === id) ?? { id, status: "idle" }));
}

function loadDesktopAgentThreadStore(): DesktopAgentThreadStore {
  try {
    const raw = localStorage.getItem(DESKTOP_AGENT_THREADS_STORAGE_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return {};
    const store: DesktopAgentThreadStore = {};
    for (const [key, value] of Object.entries(parsed)) {
      if (!key || !value || typeof value !== "object" || Array.isArray(value)) continue;
      const threadId = firstString((value as any).threadId, (value as any).thread_id);
      if (!threadId) continue;
      store[key] = {
        threadId,
        updatedAt: firstString((value as any).updatedAt, (value as any).updated_at) || new Date().toISOString(),
      };
    }
    return store;
  } catch {
    return {};
  }
}

function saveDesktopAgentThreadStore() {
  try {
    localStorage.setItem(DESKTOP_AGENT_THREADS_STORAGE_KEY, JSON.stringify(desktopAgentThreadStore));
  } catch {
    // Persisting hidden desktop agent context threads is best effort.
  }
}

function rememberDesktopAgentThread(key: string, threadId: string) {
  desktopAgentThreadStore[key] = {
    threadId,
    updatedAt: new Date().toISOString(),
  };
  saveDesktopAgentThreadStore();
}

function loadThreadAssistantPreviewStore(): Record<string, string> {
  try {
    const raw = localStorage.getItem(THREAD_ASSISTANT_PREVIEWS_STORAGE_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return {};
    const store: Record<string, string> = {};
    for (const [threadId, preview] of Object.entries(parsed)) {
      if (typeof preview !== "string") continue;
      const text = firstPreviewSentence(preview);
      if (threadId && text) store[threadId] = text;
    }
    return store;
  } catch {
    return {};
  }
}

function rememberThreadAssistantPreview(threadId: string, preview: string) {
  const text = firstPreviewSentence(preview);
  if (!threadId || !text || threadAssistantPreviewStore[threadId] === text) return;
  threadAssistantPreviewStore[threadId] = text;
  scheduleThreadAssistantPreviewSave();
}

function scheduleThreadAssistantPreviewSave() {
  if (threadAssistantPreviewSaveTimer != null) {
    window.clearTimeout(threadAssistantPreviewSaveTimer);
  }
  threadAssistantPreviewSaveTimer = window.setTimeout(() => {
    threadAssistantPreviewSaveTimer = null;
    saveThreadAssistantPreviewStore();
  }, 300);
}

function saveThreadAssistantPreviewStore() {
  try {
    const visibleThreadIds = new Set(state.threads.map((thread) => thread.id));
    const entries = Object.entries(threadAssistantPreviewStore)
      .filter(([threadId, preview]) => visibleThreadIds.has(threadId) && Boolean(preview.trim()))
      .slice(-120);
    localStorage.setItem(THREAD_ASSISTANT_PREVIEWS_STORAGE_KEY, JSON.stringify(Object.fromEntries(entries)));
  } catch {
    // Persisting list previews is best effort.
  }
}

function isDesktopAgentThreadId(threadId: string | null | undefined) {
  if (!threadId) return false;
  return Object.values(desktopAgentThreadStore).some((record) => record.threadId === threadId);
}

function hideDesktopAgentInternalThread(threadId: string | null | undefined) {
  if (!threadId) return;
  dropThreadAuxiliaryState(threadId);
  hiddenThreadIds.add(threadId);
  groupBlankThreadIds.delete(threadId);
  pinnedThreadIds.delete(threadId);
  unpinnedThreadIds.delete(threadId);
  forgetThreadNameOverride(threadId);
  forgetThreadMarker(threadId);
  forgetThreadWorkspace(threadId);
  clearUnviewedFinalResult(threadId);
  saveThreadPreferences();
  state.threads = state.threads.filter((thread) => thread.id !== threadId);
  delete state.itemOrder[threadId];
  delete state.items[threadId];
  delete state.threadRoles[threadId];
  delete state.members[threadId];
  delete state.tasks[threadId];
  forgetComposerDraft(threadId);
  if (state.blankThreadId === threadId) state.blankThreadId = null;
  clearRememberedChatThreadSelection(threadId);
  if (state.currentThreadId === threadId) {
    state.currentThreadId = null;
    restoreComposerDraftForThread(null);
  }
}

function isDesktopAgentInternalThread(thread: ConversationSummary | null | undefined) {
  if (!thread) return false;
  if (isDesktopAgentThreadId(thread.id)) return true;
  const text = `${thread.name || ""}\n${thread.preview || ""}`;
  return (
    text.includes("你正在代表当前用户的桌面智能体") ||
    text.includes("你正在代表当前桌面端的本地 Agent")
  );
}

