function setMembersWorking(threadId: string | null | undefined, working: boolean) {
  if (!threadId) return;
  ensureThreadState(threadId);
  const activeRole = inferItemRole(threadId);
  syncThreadMembersForRole(threadId, activeRole);
  state.members[threadId] = state.members[threadId].map((member, index) => ({
    ...member,
    status: working && (member.id === activeRole || (activeRole === "ceo_assistant" && index === 0)) ? "working" : "idle",
  }));
}

function pickActiveTask(tasks: TaskSummary[]) {
  return tasks.find((task) => task.status === "running") ?? tasks[0] ?? null;
}

function mergeThreads(current: ConversationSummary[], incoming: ConversationSummary[]) {
  return sortThreadsForList(mergeThreadsWithoutSorting(current, incoming));
}

function mergeThreadsWithoutSorting(current: ConversationSummary[], incoming: ConversationSummary[]) {
  const merged = [...current];
  for (const item of incoming) {
    const index = merged.findIndex((thread) => thread.id === item.id);
    if (index === -1) merged.push(item);
    else merged[index] = mergeThreadSummary(merged[index], item);
  }
  return merged;
}

function mergeThreadSummary(existing: ConversationSummary, incoming: ConversationSummary): ConversationSummary {
  const next = { ...existing, ...incoming };
  if (!incoming.model && existing.model) {
    next.model = existing.model;
    next.reasoning_effort = existing.reasoning_effort;
    next.service_tier = existing.service_tier;
  }
  if (isFallbackThreadText(incoming.name, incoming.id) && hasMeaningfulThreadText(existing.name, existing.id)) {
    next.name = existing.name;
  }
  const assistantPreviewThread = usesAssistantThreadPreview(next);
  if (!assistantPreviewThread && isFallbackThreadText(incoming.preview, incoming.id) && hasMeaningfulThreadText(existing.preview, existing.id)) {
    next.preview = existing.preview;
  }
  const assistantPreview = latestThreadAssistantPreviewText(next.id) || (assistantPreviewThread ? threadAssistantPreviewStore[next.id] || "" : "");
  if (assistantPreview) {
    next.preview = assistantPreview;
  } else if (assistantPreviewThread) {
    next.preview = "";
  }
  if (!incoming.last_message_at && existing.last_message_at) {
    next.last_message_at = existing.last_message_at;
  }
  if (!incoming.preview_time && existing.preview_time) {
    next.preview_time = existing.preview_time;
  }
  if (shouldUseEmptyThreadTitle(next.id, next.name, next.preview)) {
    next.name = "";
  }
  return withThreadDisplayPreferences(next);
}

function hasMeaningfulThreadText(value: string | null | undefined, threadId: string) {
  const text = value?.trim();
  return Boolean(text && text !== NEW_THREAD_TITLE && !isThreadIdDisplay(text, threadId));
}

function isFallbackThreadText(value: string | null | undefined, threadId: string) {
  const text = value?.trim();
  return (
    !text || text === NEW_THREAD_TITLE || isThreadIdDisplay(text, threadId)
  );
}

function sortThreadsForList(threads: ConversationSummary[]) {
  return threads.map((thread) => applyThreadPinPreference(withThreadDisplayPreferences(thread))).sort((a, b) => {
    const pinnedDelta = Number(Boolean(b.pinned)) - Number(Boolean(a.pinned));
    if (pinnedDelta) return pinnedDelta;
    if (a.pinned && b.pinned) {
      const continuationDelta = comparePinnedThreadContinuationOrder(a, b);
      if (continuationDelta) return continuationDelta;
    }
    const fixedRankDelta = fixedTopLevelThreadSortRank(a) - fixedTopLevelThreadSortRank(b);
    if (fixedRankDelta) return fixedRankDelta;
    const timeDelta = threadSortTime(b) - threadSortTime(a);
    if (timeDelta) return timeDelta;
    return 0;
  });
}

function comparePinnedThreadContinuationOrder(a: ConversationSummary, b: ConversationSummary) {
  const aContinuation = continuationRecordForTarget(a.id);
  const bContinuation = continuationRecordForTarget(b.id);
  const continuationDelta = Number(Boolean(aContinuation)) - Number(Boolean(bContinuation));
  if (continuationDelta) return continuationDelta;
  if (!aContinuation || !bContinuation) return 0;
  return (
    threadContinuationCompletedSortTime(aContinuation) - threadContinuationCompletedSortTime(bContinuation)
  );
}

function threadContinuationCompletedSortTime(record: ThreadContinuationRecord) {
  const value = Date.parse(record.completedAt || record.triggeredAt);
  return Number.isFinite(value) ? value : 0;
}

function fixedTopLevelThreadSortRank(thread: ConversationSummary) {
  if (isBlankNewThread(thread.id)) return 0;
  const channelRank = externalChannelConnectionThreadRank(thread);
  if (channelRank != null) return channelRank + 1;
  if (isVideoExpertThread(thread)) return EXTERNAL_CHANNEL_THREAD_ORDER.length + 1;
  return 1000;
}

function threadSortTime(thread: ConversationSummary) {
  return (
    parseTime(thread.last_message_at) || parseThreadPreviewTime(thread.preview_time)
  );
}

function parseThreadPreviewTime(value?: string | null) {
  if (!value) return 0;
  const text = value.trim();
  let match = text.match(/^(\d{1,2}):(\d{2})$/);
  const date = new Date();
  if (match) {
    date.setHours(Number(match[1]), Number(match[2]), 0, 0);
    return date.getTime();
  }
  match = text.match(/^\u6628\u5929\s+(\d{1,2}):(\d{2})$/);
  if (match) {
    date.setDate(date.getDate() - 1);
    date.setHours(Number(match[1]), Number(match[2]), 0, 0);
    return date.getTime();
  }
  match = text.match(/^(\d{1,2})\/(\d{1,2})\s+(\d{1,2}):(\d{2})$/);
  if (!match) return 0;
  date.setMonth(Number(match[1]) - 1, Number(match[2]));
  date.setHours(Number(match[3]), Number(match[4]), 0, 0);
  return date.getTime();
}

function localGroupChatAvatarTone(
  value: unknown,
): LocalGroupChatMember["avatarTone"] {
  return value === "orange" ||
    value === "blue" ||
    value === "black" ||
    value === "violet" ||
    value === "green" ||
    value === "person"
    ? value
    : "blue";
}

function loadLocalGroupChatRecords(): Record<string, LocalGroupChatRecord> {
  try {
    const raw = localStorage.getItem(LOCAL_GROUP_CHATS_STORAGE_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    const records = Array.isArray(parsed)
      ? parsed
      : parsed && typeof parsed === "object"
        ? Object.values(parsed)
        : [];
    const normalized: Record<string, LocalGroupChatRecord> = {};
    records.forEach((value) => {
      if (!value || typeof value !== "object") return;
      const source = value as Record<string, unknown>;
      const id = firstString(source.id);
      if (!id || !id.startsWith("local-group-chat:")) return;
      const members = (Array.isArray(source.members) ? source.members : [])
        .map((memberValue): LocalGroupChatMember | null => {
          if (!memberValue || typeof memberValue !== "object") return null;
          const member = memberValue as Record<string, unknown>;
          const selectionId = firstString(member.selectionId);
          const name = firstString(member.name);
          if (!selectionId || !name) return null;
          const section =
            member.section === "agents" ||
            member.section === "models" ||
            member.section === "contacts"
              ? member.section
              : "models";
          return {
            selectionId,
            name,
            profileName:
              firstString(member.profileName) ||
              name,
            section,
            avatarLabel:
              firstString(member.avatarLabel) ||
              name.slice(0, 1).toUpperCase(),
            avatarTone: localGroupChatAvatarTone(member.avatarTone),
            avatarUrl: firstString(member.avatarUrl),
            muted: member.muted === true,
          };
        })
        .filter((member): member is LocalGroupChatMember => Boolean(member));
      if (!members.length) return;
      const uniqueMembers = members.filter(
        (member, index) =>
          members.findIndex(
            (candidate) => candidate.selectionId === member.selectionId,
          ) === index,
      );
      const createdAt =
        firstString(source.createdAt) || new Date().toISOString();
      normalized[id] = {
        id,
        name: firstString(source.name) || localGroupChatName(uniqueMembers),
        createdAt,
        updatedAt: firstString(source.updatedAt) || createdAt,
        members,
        panelExpanded: source.panelExpanded !== false,
        announcement:
          typeof source.announcement === "string"
            ? source.announcement
            : "欢迎加入智能体协作群聊，成员可以在这里共同讨论并推进任务。",
        note:
          typeof source.note === "string"
            ? source.note
            : "群聊成员信息展示数据，后续可继续补充和调整。",
        nickname: typeof source.nickname === "string" ? source.nickname : "",
        preview: firstString(source.preview) || "",
        messages: (Array.isArray(source.messages) ? source.messages : [])
          .filter(
            (item): item is CodexItem =>
              Boolean(
                item &&
                  typeof item === "object" &&
                  firstString((item as CodexItem).id),
              ),
          )
          .map((item) => ({ ...item })),
      };
    });
    return normalized;
  } catch {
    return {};
  }
}

function saveLocalGroupChatRecords() {
  try {
    localStorage.setItem(
      LOCAL_GROUP_CHATS_STORAGE_KEY,
      JSON.stringify(Object.values(localGroupChatRecords)),
    );
  } catch {
    // Local group chat persistence is best effort.
  }
}

function loadThreadPreferences(): ThreadPreferences {
  try {
    const raw = localStorage.getItem(THREAD_PREFS_STORAGE_KEY);
    if (!raw) return emptyThreadPreferences();
    const parsed = JSON.parse(raw) as Partial<ThreadPreferences>;
    const groups = Array.isArray(parsed.groups)
      ? parsed.groups
          .map(normalizeThreadGroup)
          .filter((group): group is ThreadGroup => Boolean(group))
      : [];
    const recentMigration = migrateLegacyRecentThreadGroupPreferences(
      groups,
      parsed.threadGroups,
      normalizePersistedThreadModes(parsed.threadModes),
      {
        defaultGroupId: DEFAULT_THREAD_GROUP_ID,
        defaultGroupName: DEFAULT_THREAD_GROUP_NAME,
        legacyTradingGroupName: TRADING_EXPERT_NAME,
        isVolatileThreadId: isLocalBlankThreadId,
      },
    );
    const { recentAliasIds, threadModes: normalizedThreadModes } = recentMigration;
    const defaultGroupPreference = groups.find((group) => recentAliasIds.has(group.id));
    const normalizedGroups = [
      {
        id: DEFAULT_THREAD_GROUP_ID,
        name: DEFAULT_THREAD_GROUP_NAME,
        createdAt: defaultGroupPreference?.createdAt || new Date().toISOString(),
        updatedAt: defaultGroupPreference?.updatedAt,
        pinned: Boolean(defaultGroupPreference?.pinned),
        pinnedAt: defaultGroupPreference?.pinnedAt,
        workspaceSlug: DEFAULT_THREAD_GROUP_WORKSPACE_SLUG,
        externalPath: null,
      },
      ...groups.filter((group) => !recentAliasIds.has(group.id)),
    ];
    const knownGroupIds = new Set(normalizedGroups.map((group) => group.id));
    return {
      taskAnchorRuleVersion: TASK_ANCHOR_RULE_VERSION,
      hidden: Array.isArray(parsed.hidden) ? parsed.hidden.filter((id): id is string => typeof id === "string" && !isLocalBlankThreadId(id)) : [],
      pinned: Array.isArray(parsed.pinned) ? parsed.pinned.filter((id): id is string => typeof id === "string" && !isLocalBlankThreadId(id)) : [],
      unpinned: Array.isArray(parsed.unpinned) ? parsed.unpinned.filter((id): id is string => typeof id === "string" && !isLocalBlankThreadId(id)) : [],
      attachmentOnly: Array.isArray(parsed.attachmentOnly) ? parsed.attachmentOnly.filter((id): id is string => typeof id === "string" && !isLocalBlankThreadId(id)) : [],
      clearedBefore:
        parsed.clearedBefore && typeof parsed.clearedBefore === "object"
          ? Object.fromEntries(
              Object.entries(parsed.clearedBefore).filter(
                (entry): entry is [string, string] =>
                  typeof entry[0] === "string" && typeof entry[1] === "string" && Boolean(entry[0] && !isLocalBlankThreadId(entry[0]) && entry[1]),
              ),
            )
          : {},
      threadNames:
        parsed.threadNames && typeof parsed.threadNames === "object"
          ? Object.fromEntries(
              Object.entries(parsed.threadNames).filter(
                (entry): entry is [string, string] =>
                  typeof entry[0] === "string" &&
                  typeof entry[1] === "string" &&
                  Boolean(entry[0] && !isLocalBlankThreadId(entry[0]) && entry[1].trim()),
              ),
            )
          : {},
      threadTaskAnchors:
        parsed.taskAnchorRuleVersion === TASK_ANCHOR_RULE_VERSION && parsed.threadTaskAnchors && typeof parsed.threadTaskAnchors === "object"
          ? Object.fromEntries(
              Object.entries(parsed.threadTaskAnchors)
                .map(([threadId, anchor]) => [threadId, normalizeTaskAnchorText(firstString(anchor))] as [string, string])
                .filter(([threadId, anchor]) => Boolean(threadId && !isLocalBlankThreadId(threadId) && anchor)),
            )
          : {},
      threadMarkers:
        parsed.threadMarkers && typeof parsed.threadMarkers === "object"
          ? Object.fromEntries(
              Object.entries(parsed.threadMarkers)
                .map(([threadId, marker]) => [threadId, normalizeThreadMarkerText(firstString(marker))] as [string, string])
                .filter(([threadId, marker]) => Boolean(threadId && !isLocalBlankThreadId(threadId) && marker)),
            )
          : {},
      unviewedFinalResults:
        parsed.unviewedFinalResults && typeof parsed.unviewedFinalResults === "object"
          ? Object.fromEntries(
              Object.entries(parsed.unviewedFinalResults).filter(
                (entry): entry is [string, string] =>
                  typeof entry[0] === "string" && typeof entry[1] === "string" && Boolean(entry[0] && !isLocalBlankThreadId(entry[0]) && entry[1]),
              ),
            )
          : {},
      groups: normalizedGroups,
      threadGroups:
        parsed.threadGroups && typeof parsed.threadGroups === "object"
          ? Object.fromEntries(
              Object.entries(parsed.threadGroups).filter(
                (entry): entry is [string, string] =>
                  typeof entry[0] === "string" &&
                  typeof entry[1] === "string" &&
                  Boolean(entry[0] && !isLocalBlankThreadId(entry[0]) && (knownGroupIds.has(entry[1]) || recentAliasIds.has(entry[1]))),
              ).map(([threadId, groupId]) => [threadId, recentAliasIds.has(groupId) ? DEFAULT_THREAD_GROUP_ID : groupId]),
            )
          : {},
      threadWorkspaces:
        parsed.threadWorkspaces && typeof parsed.threadWorkspaces === "object"
          ? Object.fromEntries(
              Object.entries(parsed.threadWorkspaces).filter(
                (entry): entry is [string, string] =>
                  typeof entry[0] === "string" && typeof entry[1] === "string" && Boolean(entry[0] && !isLocalBlankThreadId(entry[0]) && entry[1].trim()),
              ),
            )
          : {},
      threadModels: normalizePersistedThreadModels(parsed.threadModels),
      threadModelSelections: normalizePersistedThreadModels(parsed.threadModelSelections),
      threadImageModels: normalizePersistedThreadImageModels(parsed.threadImageModels),
      threadImageSizes: normalizePersistedThreadImageSizes(parsed.threadImageSizes),
      threadModes: normalizedThreadModes,
      tradingExpertThreads: Array.isArray(parsed.tradingExpertThreads)
        ? parsed.tradingExpertThreads.filter((id): id is string => typeof id === "string" && Boolean(id) && !isLocalBlankThreadId(id))
        : [],
      clusterModes: normalizePersistedClusterModes(parsed.clusterModes),
      threadLastAssistantProviders: normalizePersistedThreadLastAssistantProviders(parsed.threadLastAssistantProviders),
      threadContinuations: normalizePersistedThreadContinuations(parsed.threadContinuations),
      collapsedGroups: Array.isArray(parsed.collapsedGroups)
        ? parsed.collapsedGroups.filter((id): id is string => typeof id === "string" && knownGroupIds.has(id))
        : [],
      newThreadGroupId:
        typeof parsed.newThreadGroupId === "string" && knownGroupIds.has(parsed.newThreadGroupId)
          ? parsed.newThreadGroupId
          : DEFAULT_THREAD_GROUP_ID,
    };
  } catch {
    return emptyThreadPreferences();
  }
}

function emptyThreadPreferences(): ThreadPreferences {
  const now = new Date().toISOString();
  return {
    taskAnchorRuleVersion: TASK_ANCHOR_RULE_VERSION,
    hidden: [],
    pinned: [],
    unpinned: [],
    attachmentOnly: [],
    clearedBefore: {},
    threadNames: {},
    threadTaskAnchors: {},
    threadMarkers: {},
    unviewedFinalResults: {},
    groups: [
      {
        id: DEFAULT_THREAD_GROUP_ID,
        name: DEFAULT_THREAD_GROUP_NAME,
        createdAt: now,
        updatedAt: now,
        workspaceSlug: DEFAULT_THREAD_GROUP_WORKSPACE_SLUG,
        externalPath: null,
      },
    ],
    threadGroups: {},
    threadWorkspaces: {},
    threadModels: {},
    threadModelSelections: {},
    threadImageModels: {},
    threadImageSizes: {},
    threadModes: {},
    tradingExpertThreads: [],
    clusterModes: {},
    threadLastAssistantProviders: {},
    threadContinuations: {},
    collapsedGroups: [],
    newThreadGroupId: DEFAULT_THREAD_GROUP_ID,
  };
}

function normalizePersistedThreadModels(value: unknown): Record<string, ThreadModelSettings> {
  if (!value || typeof value !== "object") return {};
  const normalized: Record<string, ThreadModelSettings> = {};
  for (const [threadId, rawSettings] of Object.entries(value as Record<string, unknown>)) {
    const settings = normalizeThreadModelSettings(rawSettings);
    if (!threadId || isLocalBlankThreadId(threadId) || !settings) continue;
    normalized[threadId] = settings;
  }
  return normalized;
}

function normalizePersistedThreadImageModels(value: unknown): Record<string, string> {
  if (!value || typeof value !== "object") return {};
  const normalized: Record<string, string> = {};
  for (const [threadId, rawModel] of Object.entries(value as Record<string, unknown>)) {
    const model = safeImageGenerationModelId(rawModel);
    if (!threadId || isLocalBlankThreadId(threadId) || !model) continue;
    normalized[threadId] = model;
  }
  return normalized;
}

function normalizePersistedThreadImageSizes(value: unknown): Record<string, string> {
  if (!value || typeof value !== "object") return {};
  const normalized: Record<string, string> = {};
  for (const [threadId, rawSize] of Object.entries(
    value as Record<string, unknown>,
  )) {
    const size = normalizeImageGenerationSize(rawSize);
    if (!threadId || isLocalBlankThreadId(threadId) || !size) continue;
    normalized[threadId] = size;
  }
  return normalized;
}

function normalizePersistedThreadLastAssistantProviders(value: unknown): Record<string, ProviderChatProvider> {
  if (!value || typeof value !== "object") return {};
  const normalized: Record<string, ProviderChatProvider> = {};
  for (const [threadId, rawProvider] of Object.entries(value as Record<string, unknown>)) {
    const provider = providerFromValue(rawProvider);
    if (!threadId || isLocalBlankThreadId(threadId) || !provider) continue;
    normalized[threadId] = provider;
  }
  return normalized;
}

function normalizePersistedThreadModes(value: unknown): Record<string, NewThreadMode> {
  if (!value || typeof value !== "object") return {};
  return Object.fromEntries(
    Object.entries(value as Record<string, unknown>)
      .filter(([threadId, mode]) => Boolean(
        threadId
        && !isLocalBlankThreadId(threadId)
        && (
          mode === "execution"
          || mode === "multi-agent"
          || mode === "image-generation"
          || mode === "video-generation"
        )
      ))
      .map(([threadId, mode]) => [
        threadId,
        mode === "multi-agent" ? "execution" : mode,
      ] as [string, NewThreadMode]),
  );
}

function normalizePersistedClusterModes(value: unknown): Record<string, ClusterModeVariant> {
  void value;
  return {};
}

function normalizePersistedThreadContinuations(value: unknown): Record<string, ThreadContinuationRecord> {
  if (!value || typeof value !== "object") return {};
  const normalized: Record<string, ThreadContinuationRecord> = {};
  for (const [sourceKey, rawValue] of Object.entries(value as Record<string, unknown>)) {
    if (!rawValue || typeof rawValue !== "object" || Array.isArray(rawValue)) continue;
    const raw = rawValue as Partial<ThreadContinuationRecord>;
    const sourceThreadId = firstString(raw.sourceThreadId, sourceKey);
    if (!sourceThreadId || isLocalBlankThreadId(sourceThreadId)) continue;
    const rawStatus = firstString(raw.status);
    if (!rawStatus || !["awaiting_answer", "preparing", "ready", "creating", "completed", "failed"].includes(rawStatus)) continue;
    const status: ThreadContinuationStatus = rawStatus === "completed"
      ? "completed"
      : rawStatus === "ready"
        ? "ready"
      : rawStatus === "failed" || rawStatus === "creating" || rawStatus === "preparing"
        ? "failed"
        : "awaiting_answer";
    const continuationThreadId = firstString(raw.continuationThreadId);
    if (status === "completed" && !continuationThreadId) continue;
    const copiedMessages = Array.isArray(raw.copiedMessages)
      ? raw.copiedMessages
          .map((message): ThreadContinuationCopiedMessage | null => {
            if (!message || typeof message !== "object") return null;
            const record = message as Partial<ThreadContinuationCopiedMessage>;
            const text = String(record.text || "").replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g, "").trim();
            if (!text) return null;
            return {
              role: record.role === "assistant" ? "assistant" : "user",
              text: text.slice(0, 1_000_000),
              summarized: record.summarized === true,
            };
          })
          .filter((message): message is ThreadContinuationCopiedMessage => Boolean(message))
          .slice(-2)
      : [];
    const operationId = firstString(raw.operationId) || createThreadContinuationOperationId();
    normalized[operationId] = {
      version: 1,
      operationId,
      sourceThreadId,
      sourceDeleted: raw.sourceDeleted === true,
      continuationThreadId: continuationThreadId || null,
      sourceTitle: firstString(raw.sourceTitle) || "原任务",
      continuationTitle: firstString(raw.continuationTitle),
      status,
      triggeredAt: firstString(raw.triggeredAt) || new Date().toISOString(),
      completedAt: firstString(raw.completedAt),
      answerTurnId: firstString(raw.answerTurnId),
      anchorMessageId: firstString(raw.anchorMessageId),
      olderSummary: String(raw.olderSummary || "").slice(0, 1_000_000),
      copiedMessages,
      originalTokens: numericValue(raw.originalTokens),
      budgetTokens: numericValue(raw.budgetTokens),
      needsNewOperation: raw.needsNewOperation === true || status === "failed",
      error: status === "failed" ? firstString(raw.error) || "上次续接未完成，请重试" : null,
    };
  }
  return normalized;
}

function normalizeThreadGroup(value: unknown): ThreadGroup | null {
  if (!value || typeof value !== "object") return null;
  const record = value as Partial<ThreadGroup>;
  const id = firstString(record.id);
  const name = firstString(record.name)?.trim();
  if (!id || !name) return null;
  const workspaceSlug = isDefaultThreadGroup(id) ? DEFAULT_THREAD_GROUP_WORKSPACE_SLUG : firstString(record.workspaceSlug) || id;
  const externalPath = isDefaultThreadGroup(id) ? null : firstString(record.externalPath, (record as any).external_path) || null;
  return {
    id,
    name,
    createdAt: firstString(record.createdAt) || new Date().toISOString(),
    updatedAt: firstString(record.updatedAt) || undefined,
    pinned: Boolean(record.pinned),
    pinnedAt: firstString(record.pinnedAt) || undefined,
    workspaceSlug,
    externalPath,
  };
}

function saveThreadPreferences() {
  ensureDefaultThreadGroup();
  const knownGroupIds = new Set(threadGroups.map((group) => group.id));
  const preferences: ThreadPreferences = {
    taskAnchorRuleVersion: TASK_ANCHOR_RULE_VERSION,
    hidden: [...hiddenThreadIds].filter(shouldPersistThreadPreferenceId),
    pinned: [...pinnedThreadIds].filter(shouldPersistThreadPreferenceId),
    unpinned: [...unpinnedThreadIds].filter(shouldPersistThreadPreferenceId),
    attachmentOnly: [...attachmentOnlyThreadIds].filter(shouldPersistThreadPreferenceId),
    clearedBefore: Object.fromEntries(Object.entries(threadHistoryClearedBefore).filter(([threadId, timestamp]) => Boolean(shouldPersistThreadPreferenceId(threadId) && timestamp))),
    threadNames: Object.fromEntries(
      Object.entries(threadNameOverrides).filter(([threadId, name]) => Boolean(shouldPersistThreadPreferenceId(threadId) && name.trim())),
    ),
    threadTaskAnchors: Object.fromEntries(
      Object.entries(threadTaskAnchors)
        .map(([threadId, anchor]) => [threadId, normalizeTaskAnchorText(anchor)] as [string, string])
        .filter(([threadId, anchor]) => Boolean(shouldPersistThreadPreferenceId(threadId) && anchor)),
    ),
    threadMarkers: Object.fromEntries(
      Object.entries(threadMarkers)
        .map(([threadId, marker]) => [threadId, normalizeThreadMarkerText(marker)] as [string, string])
        .filter(([threadId, marker]) => Boolean(shouldPersistThreadPreferenceId(threadId) && !hiddenThreadIds.has(threadId) && marker)),
    ),
    unviewedFinalResults: Object.fromEntries(
      Object.entries(unviewedFinalResultThreadIds).filter(([threadId, timestamp]) => Boolean(shouldPersistThreadPreferenceId(threadId) && timestamp)),
    ),
    groups: threadGroups.map((group) => ({ ...group })),
    threadGroups: Object.fromEntries(
      Object.entries(threadGroupByThreadId).filter(([threadId, groupId]) => Boolean(shouldPersistThreadPreferenceId(threadId) && knownGroupIds.has(groupId))),
    ),
    threadWorkspaces: Object.fromEntries(
      Object.entries(threadWorkspaceByThreadId).filter(
        ([threadId, cwd]) => Boolean(shouldPersistThreadPreferenceId(threadId) && cwd),
      ),
    ),
    threadModels: Object.fromEntries(
      Object.entries(threadModelSettingsByThreadId).filter(
        ([threadId, settings]) => Boolean(
          shouldPersistThreadPreferenceId(threadId) &&
            !hiddenThreadIds.has(threadId) &&
            normalizeThreadModelSettings(settings),
        ),
      ),
    ),
    threadModelSelections: Object.fromEntries(
      Object.entries(threadModelSelectionsByThreadId).filter(
        ([threadId, settings]) => Boolean(
          shouldPersistThreadPreferenceId(threadId) &&
            !hiddenThreadIds.has(threadId) &&
            normalizeThreadModelSettings(settings),
        ),
      ),
    ),
    threadImageModels: Object.fromEntries(
      [...imageGenerationModelByThreadId].filter(
        ([threadId, model]) =>
          shouldPersistThreadPreferenceId(threadId) &&
          !hiddenThreadIds.has(threadId) &&
          Boolean(safeImageGenerationModelId(model)),
      ),
    ),
    threadImageSizes: Object.fromEntries(
      [...imageGenerationSizeByThreadId].filter(
        ([threadId, size]) =>
          shouldPersistThreadPreferenceId(threadId) &&
          !hiddenThreadIds.has(threadId) &&
          Boolean(normalizeImageGenerationSize(size)),
      ),
    ),
    threadModes: Object.fromEntries(
      [...newThreadModeByThreadId].filter(
        ([threadId, mode]) =>
          shouldPersistThreadPreferenceId(threadId) &&
          !hiddenThreadIds.has(threadId) &&
          (mode === "execution" ||
            mode === "image-generation" ||
            mode === "video-generation"),
      ),
    ),
    tradingExpertThreads: [...tradingExpertThreadIds].filter(
      (threadId) => shouldPersistThreadPreferenceId(threadId) && !hiddenThreadIds.has(threadId),
    ),
    clusterModes: {},
    threadLastAssistantProviders: Object.fromEntries(
      [...threadLastAssistantProviderByThreadId].filter(
        ([threadId, provider]) =>
          shouldPersistThreadPreferenceId(threadId) &&
          !hiddenThreadIds.has(threadId) &&
          Boolean(PROVIDER_CHAT_META[provider]),
      ),
    ),
    threadContinuations: Object.fromEntries(
      Object.entries(threadContinuationByOperationId).filter(
        ([operationId, record]) => Boolean(
          operationId === record?.operationId &&
            shouldPersistThreadPreferenceId(record?.sourceThreadId) &&
            latestThreadContinuationRecordForSource(record.sourceThreadId)?.operationId === operationId,
        ),
      ).map(([operationId, record]) => [
        operationId,
        {
          ...record,
          // The canonical handoff body lives in the main-process transaction
          // file. Keep localStorage limited to small linkage/state metadata so
          // repeated continuations cannot exhaust the shared preferences quota.
          olderSummary: "",
          copiedMessages: [],
        },
      ]),
    ),
    collapsedGroups: [...collapsedThreadGroupIds].filter((groupId) => knownGroupIds.has(groupId)),
    newThreadGroupId: knownGroupIds.has(state.activeNewThreadGroupId) ? state.activeNewThreadGroupId : DEFAULT_THREAD_GROUP_ID,
  };
  try {
    localStorage.setItem(THREAD_PREFS_STORAGE_KEY, JSON.stringify(preferences));
    return true;
  } catch {
    return false;
  }
}

function shouldPersistThreadPreferenceId(threadId: string | null | undefined) {
  return Boolean(
    threadId &&
    !internalSubagentThreadIds.has(threadId) &&
    !isLocalBlankThreadId(threadId) &&
    !isBlankNewThread(threadId) &&
    !groupBlankThreadIds.has(threadId),
  );
}

