function renderContactInlineLevel(contact: ContactProfile) {
  const level = renderContactLevel(contact, "small");
  return level ? `<span class="contact-search-level">${level}</span>` : "";
}

function renderContactLevel(contact: ContactProfile, size: "small" | "large") {
  const summary = contactLevelSummary(contact);
  if (summary && summary.enabled !== false && summary.locked !== true) {
    const icons = normalizeLevelIcons(summary.icons, summary.level);
    if (icons.length) {
      return `
        <span class="contact-level-icons ${size}" aria-label="${escapeAttr(profileLevelAriaLabel(summary, icons))}">
          ${icons.map(renderProfileLevelIcon).join("")}
        </span>
      `;
    }
  }
  const badgeHtml = renderContactLevelBadges(contact.levelLabel);
  return badgeHtml || escapeHtml(contactLevelText(contact) || "");
}

function contactLevelSummary(contact: ContactProfile): LevelSummary | null {
  const value = contact.level;
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  return value as LevelSummary;
}

function contactLevelText(contact: ContactProfile) {
  return typeof contact.level === "string" || typeof contact.level === "number" ? String(contact.level) : null;
}

function renderContactLevelBadges(value: string | null | undefined) {
  const badges = String(value || "")
    .split(/\s+/)
    .map((item) => item.trim())
    .filter(Boolean);
  if (!badges.length) return "";
  return `<span class="contact-level-badges">${badges.map((badge) => `<span>${escapeHtml(badge)}</span>`).join("")}</span>`;
}

function normalizeContactLevel(...values: unknown[]): ContactProfile["level"] {
  for (const value of values) {
    const summary = normalizeContactLevelSummary(value);
    if (summary) return summary;
    const number = numericValue(value);
    if (number != null && (typeof value === "number" || (typeof value === "string" && /^[0-9]+(?:\.[0-9]+)?$/.test(value.trim())))) {
      return { level: Math.max(0, Math.floor(number)), icons: [] };
    }
    if (typeof value === "string" && value.trim()) return value.trim();
  }
  return null;
}

function normalizeContactLevelSummary(value: unknown): LevelSummary | null {
  const record = plainRecord(value);
  if (!record) return null;
  const icons = normalizeLevelIconList(
    record.icons ??
      record.level_icons ??
      record.levelIcons ??
      record.icon_list ??
      record.iconList ??
      record.level_icon ??
      record.levelIcon,
  );
  const level = numericValue(
    record.level ??
      record.level_value ??
      record.levelValue ??
      record.current_level ??
      record.currentLevel ??
      record.member_level ??
      record.memberLevel ??
      record.rank_level ??
      record.rankLevel,
  );
  if (!icons.length && level == null) return null;
  return {
    enabled: firstBoolean(record.enabled, record.is_enabled, record.isEnabled) ?? undefined,
    locked: firstBoolean(record.locked, record.is_locked, record.isLocked) ?? undefined,
    lock_reason: firstString(record.lock_reason, record.lockReason),
    level: level == null ? null : Math.max(0, Math.floor(level)),
    icons,
    current_progress: numericValue(record.current_progress ?? record.currentProgress) ?? undefined,
    required_progress: numericValue(record.required_progress ?? record.requiredProgress) ?? undefined,
    today_activity: numericValue(record.today_activity ?? record.todayActivity) ?? undefined,
    today_activity_cap: numericValue(record.today_activity_cap ?? record.todayActivityCap) ?? undefined,
    online_reward_claimed: firstBoolean(record.online_reward_claimed, record.onlineRewardClaimed) ?? undefined,
    task_reward_count: numericValue(record.task_reward_count ?? record.taskRewardCount) ?? undefined,
    task_reward_cap: numericValue(record.task_reward_cap ?? record.taskRewardCap) ?? undefined,
    is_member_accelerated: firstBoolean(record.is_member_accelerated, record.isMemberAccelerated) ?? undefined,
  };
}

function normalizeLevelIconList(value: unknown): LevelIcon[] {
  const icons: LevelIcon[] = [];
  if (Array.isArray(value)) {
    for (const item of value) {
      if (typeof item === "string") {
        const type = normalizeLevelIconType(item);
        if (type) icons.push({ type, count: 1 });
        continue;
      }
      const record = plainRecord(item);
      if (!record) continue;
      const type = normalizeLevelIconType(record.type ?? record.icon ?? record.name ?? record.key);
      if (!type) continue;
      const count = Math.max(1, Math.floor(numericValue(record.count ?? record.num ?? record.quantity ?? record.value) ?? 1));
      icons.push({ type, count });
    }
    return icons;
  }
  const record = plainRecord(value);
  if (!record) return icons;
  for (const [key, rawCount] of Object.entries(record)) {
    const type = normalizeLevelIconType(key);
    if (!type) continue;
    const count = Math.max(0, Math.floor(numericValue(rawCount) ?? 0));
    if (count > 0) icons.push({ type, count });
  }
  return icons;
}

function normalizeLevelIconType(value: unknown): LevelIconType | null {
  if (typeof value !== "string") return null;
  const type = value.trim().replace(/-/g, "_");
  return isLevelIconType(type) ? type : null;
}

function plainRecord(value: unknown): Record<string, unknown> | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  return value as Record<string, unknown>;
}

function renderProfileLevelIcon(icon: LevelIcon) {
  const src = LEVEL_ICON_URL[icon.type];
  const label = levelIconLabel(icon.type);
  return Array.from(
    { length: icon.count },
    () =>
      `<img src="${escapeAttr(src)}" alt="${escapeAttr(label)}" title="${escapeAttr(label)}" data-level-icon="${escapeAttr(icon.type)}" />`,
  ).join("");
}

function currentProfileLevelSummary(): LevelSummary | null {
  const value = state.auth.profile?.level;
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  return value as LevelSummary;
}

function normalizeLevelIcons(value: unknown, fallbackLevel?: unknown): LevelIcon[] {
  const weights: Record<LevelIconType, number> = {
    egg: 1,
    egg_cat: 4,
    cat: 16,
    cat_king: 64,
  };
  const order: LevelIconType[] = ["cat_king", "cat", "egg_cat", "egg"];
  let total = 0;
  if (Array.isArray(value)) {
    for (const item of value) {
      if (!item || typeof item !== "object") continue;
      const type = (item as { type?: unknown }).type;
      if (!isLevelIconType(type)) continue;
      const count = Math.max(0, Math.floor(numericValue((item as { count?: unknown }).count) ?? 0));
      total += weights[type] * count;
    }
  }
  if (total <= 0) {
    total = Math.max(0, Math.floor(numericValue(fallbackLevel) ?? 0));
  }
  const icons: LevelIcon[] = [];
  for (const type of order) {
    const count = Math.floor(total / weights[type]);
    if (count > 0) icons.push({ type, count });
    total %= weights[type];
  }
  return icons;
}

function isLevelIconType(value: unknown): value is LevelIconType {
  return (
    value === "egg" || value === "egg_cat" || value === "cat" || value === "cat_king"
  );
}

function levelIconLabel(type: LevelIconType) {
  if (type === "egg") return "蛋";
  if (type === "egg_cat") return "蛋猫";
  if (type === "cat") return "猫";
  return "猫王";
}

function profileLevelAriaLabel(summary: LevelSummary, icons: LevelIcon[]) {
  const label = summary.level != null ? `Lv${summary.level}` : "等级";
  const iconText = icons.map((icon) => `${levelIconLabel(icon.type)}${icon.count}`).join(" ");
  return `${label} ${iconText}`.trim();
}

function currentProfileBalance() {
  const profile = state.auth.profile as Record<string, unknown> | null;
  const durablePoints = numericValue(
    profile?.balance_points ?? profile?.balancePoints ??
      profile?.real_balance ?? profile?.realBalance ??
      profile?.balance_tokens ?? profile?.balanceTokens,
  );
  if (durablePoints != null) {
    return formatProfileBalancePoints(durablePoints) ?? "--";
  }
  return "--";
}

type MembershipPlanId = "free" | "trial" | "basic" | "pro" | "flagship";

type MembershipPlanDisplay = {
  id: MembershipPlanId;
  label: "WEB3免费" | "体验版" | "基础版" | "专业版" | "旗舰版";
  subscribed: boolean;
};

function currentMembershipPlan(): MembershipPlanDisplay {
  const profile = state.auth.profile as Record<string, unknown> | null;
  const membership = activeMembershipEntitlement(profile);
  if (!membership.active) return { id: "free", label: "WEB3免费", subscribed: false };
  if (membership.planId === "trial") {
    return { id: "trial", label: "体验版", subscribed: true };
  }
  if (membership.planId === "basic") {
    return { id: "basic", label: "基础版", subscribed: true };
  }
  if (membership.planId === "pro" || membership.planId === "professional") {
    return { id: "pro", label: "专业版", subscribed: true };
  }
  if (membership.planId === "flagship") {
    return { id: "flagship", label: "旗舰版", subscribed: true };
  }
  return { id: "free", label: "WEB3免费", subscribed: false };
}

function renderMembershipBadge(context: "titlebar" | "profile" | "consumption", plan = currentMembershipPlan()) {
  const kind = plan.subscribed ? "member" : "experience";
  const className = `membership-badge membership-badge-${kind} ${context}-membership-badge`;
  if (context === "profile" || context === "consumption") {
    if (!plan.subscribed) {
      return `<button type="button" class="${className}" data-membership-plan="${plan.id}" data-action="profile-quota" aria-label="当前套餐：${plan.label}，查看充值方案" title="查看充值方案">${plan.label}</button>`;
    }
    return `<span class="${className}" data-membership-plan="${plan.id}" aria-label="当前套餐：${plan.label}">${plan.label}</span>`;
  }
  return `<span class="${className}" data-membership-plan="${plan.id}" aria-label="订阅套餐：${plan.label}">${plan.label}</span>`;
}

function renderProfileSubscriptionBalance() {
  const { balance, refreshAt, refreshLabel } = currentSubscriptionBalanceDisplay();
  return `
    <div class="profile-subscription-row">
      <div class="profile-subscription-label">
        <span>订阅余额</span>
      </div>
      <strong>
        <b>${escapeHtml(balance)}</b>
        ${refreshLabel ? `<time datetime="${escapeAttr(refreshAt || "")}">${escapeHtml(refreshLabel)}</time>` : ""}
      </strong>
    </div>
  `;
}

function currentSubscriptionBalanceDisplay() {
  const profile = state.auth.profile as Record<string, unknown> | null;
  const activeMembership = plainRecord(profile?.active_membership ?? profile?.activeMembership);
  const rawBalance = numericValue(profile?.subscription_balance ?? profile?.subscriptionBalance);
  const balance = rawBalance == null ? "--" : formatSubscriptionTokenAmount(rawBalance);
  const refreshAt = firstString(
    profile?.subscription_balance_refresh_at,
    profile?.subscriptionBalanceRefreshAt,
    activeMembership?.next_credit_at,
    activeMembership?.nextCreditAt,
    activeMembership?.refresh_at,
    activeMembership?.refreshAt,
  );
  const refreshLabel = formatSubscriptionRefreshDate(refreshAt);
  return {
    balance,
    refreshAt,
    refreshLabel,
  };
}

function formatSubscriptionTokenAmount(value: number) {
  return value.toLocaleString(appLanguageLocale(state.settings.language), {
    minimumFractionDigits: Number.isInteger(value) ? 0 : 2,
    maximumFractionDigits: 2,
  });
}

function formatSubscriptionRefreshDate(value: string | null) {
  if (!value) return "";
  const date = new Date(value);
  if (!Number.isFinite(date.getTime())) return "";
  return new Intl.DateTimeFormat(appLanguageLocale(state.settings.language), {
    month: state.settings.language === "en" ? "short" : "numeric",
    day: "numeric",
  }).format(date);
}

