function loadCachedLoginIdentity(): CachedLoginIdentity | null {
  try {
    const raw = localStorage.getItem(LAST_LOGIN_IDENTITY_STORAGE_KEY);
    if (!raw) return null;
    const value = JSON.parse(raw) as Partial<CachedLoginIdentity>;
    const name = typeof value?.name === "string" ? value.name.trim() : "";
    const avatarUrl = typeof value?.avatarUrl === "string" ? value.avatarUrl.trim() : "";
    if (!name && !avatarUrl) return null;
    return {
      name,
      avatarUrl,
      updatedAt: typeof value?.updatedAt === "string" ? value.updatedAt : "",
    };
  } catch {
    return null;
  }
}

function persistLastLoginIdentity(profile: AuthProfile) {
  const identity: CachedLoginIdentity = {
    name: authProfileDisplayName(profile),
    avatarUrl: authProfileAvatarUrl(profile) || "",
    updatedAt: new Date().toISOString(),
  };
  if (!identity.name && !identity.avatarUrl) return;
  cachedLoginIdentity = identity;
  try {
    localStorage.setItem(LAST_LOGIN_IDENTITY_STORAGE_KEY, JSON.stringify(identity));
  } catch {
    // 登录不应因为头像/名称缓存失败而中断。
  }
}

