function currentSkillsScrollElement() {
  if (state.marketplace.detailDialogOpen) {
    return root.querySelector<HTMLElement>(".skill-detail-dialog");
  }
  if (state.marketplace.selectedSkillId) {
    return (
      root.querySelector<HTMLElement>(".skill-detail-content") ?? root.querySelector<HTMLElement>(".skill-detail-page")
    );
  }
  return root.querySelector<HTMLElement>(".skills-plaza-page");
}

function currentWorkflowScrollState(): AgentPanelScrollState | null {
  const chatWorkflowVisible = state.activeView === "chat" && !state.rightCollapsed && !state.chatPreview;
  if (!chatWorkflowVisible) return null;
  const clusterScroller = root.querySelector<HTMLElement>(".cluster-workflow-viewport");
  if (clusterScroller) {
    return {
      surface: "cluster",
      key: workflowScrollKey(),
      viewportTransform: workflowCanvasViewportTransformForViewport(clusterScroller),
    };
  }
  const scroller = root.querySelector<HTMLElement>(".workflow");
  if (!scroller) return null;
  return {
    surface: "timeline",
    key: workflowScrollKey(),
    scrollTop: scroller.scrollTop,
    scrollLeft: scroller.scrollLeft,
    nearBottom: isWorkflowScrollerNearBottom(scroller),
  };
}

function restoreWorkflowScrollTop(previous: AgentPanelScrollState | null) {
  const chatWorkflowVisible = state.activeView === "chat" && !state.rightCollapsed && !state.chatPreview;
  if (!chatWorkflowVisible) return;
  if (previous?.surface === "cluster") {
    if (previous.key !== workflowScrollKey()) return;
    const restoreClusterViewport = () => {
      const viewport = root.querySelector<HTMLElement>(".cluster-workflow-viewport");
      if (!viewport || !previous.viewportTransform || previous.key !== workflowScrollKey()) return;
      applyWorkflowCanvasViewportTransform(viewport, previous.viewportTransform);
      scheduleWorkflowComposerConnector();
    };
    restoreClusterViewport();
    window.requestAnimationFrame(restoreClusterViewport);
    window.setTimeout(restoreClusterViewport, 0);
    window.setTimeout(restoreClusterViewport, 120);
    return;
  }
  const restore = () => {
    const scroller = root.querySelector<HTMLElement>(".workflow");
    if (!scroller) return;
    const nextKey = workflowScrollKey();
    const shouldFollowBottom = !previous || previous.key !== nextKey || previous.nearBottom;
    const previousScrollTop = previous?.scrollTop ?? 0;
    if (shouldFollowBottom) {
      scroller.scrollTop = scroller.scrollHeight;
      updateWorkflowScrollBottomButton(scroller);
      return;
    }
    const maxScrollTop = Math.max(0, scroller.scrollHeight - scroller.clientHeight);
    scroller.scrollTop = Math.min(previousScrollTop, maxScrollTop);
    updateWorkflowScrollBottomButton(scroller);
  };
  restore();
  window.requestAnimationFrame(restore);
  window.setTimeout(restore, 120);
}

function libraryScrollKey() {
  return state.activeView === "materials"
    ? `materials:${state.materialsCategory}:${state.materialsSearch}`
    : `results:${state.resultsCategory}:${state.resultsSearch}:${state.resultsGroupFilter}:${state.resultsTimeSort}`;
}

function conversationListScrollKey() {
  return "chat";
}

function contactsListScrollKey() {
  return state.contactsSearch.trim();
}

function skillsPlazaScrollKey() {
  const detailMode = state.marketplace.detailDialogOpen ? "dialog" : state.marketplace.selectedSkillId ? "detail" : "list";
  return `${state.skillsPlazaTab}:${detailMode}:${state.marketplace.selectedSkillId || "list"}:${state.marketplace.mySkillsOnly ? "mine" : "market"}:${state.skillCategory}:${state.skillSearch}`;
}

function isMessageScrollerNearBottom() {
  const scroller = root.querySelector<HTMLDivElement>("#messageScroller");
  if (!scroller) return true;
  return (
    scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight < 96
  );
}

function isWorkflowScrollerNearBottom(scroller: HTMLElement) {
  return (
    scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight < 96
  );
}

function workflowScrollKey() {
  return state.currentThreadId || "empty";
}

function messageScrollSignature(threadId: string | null) {
  if (!threadId) return null;
  if (isThreadSwitchLoadingState(threadId)) return `${threadId}:loading`;
  const order = state.itemOrder[threadId] || [];
  const lastId = order.at(-1) || "";
  const lastItem = lastId ? state.items[threadId]?.[lastId] : null;
  const lastText = lastItem ? itemText(lastItem) : "";
  return `${threadId}:${order.length}:${lastId}:${lastText.length}:${isThreadBusy(threadId) ? 1 : 0}`;
}

function scrollWorkflowToLatestStep() {
  if (state.rightCollapsed || state.activeView !== "chat" || state.chatPreview) return;
  window.requestAnimationFrame(() => {
    const workflow = root.querySelector<HTMLElement>(".workflow");
    if (!workflow) return;
    workflow.scrollTop = workflow.scrollHeight;
    updateWorkflowScrollBottomButton(workflow);
  });
}

function valueOfInput(selector: string) {
  return (
    root.querySelector<HTMLInputElement | HTMLTextAreaElement>(selector)?.value.trim() ?? ""
  );
}

function valueOfSelect(selector: string) {
  return root.querySelector<HTMLSelectElement>(selector)?.value ?? "";
}

function safeId(prefix: string) {
  return `${prefix}-${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

function decodeMaybeBase64(value: string) {
  try {
    return atob(value);
  } catch {
    return value;
  }
}

function escapeHtml(value: unknown) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function escapeAttr(value: unknown) {
  return escapeHtml(value);
}

function errorMessage(error: unknown) {
  if (error instanceof Error) return cleanIpcError(error.message);
  return String(error);
}

function isAuthSessionExpiredError(error: unknown) {
  return /(?:YOULE_AUTH_EXPIRED|SESSION_REVOKED|session\s+(?:has\s+been\s+)?revoked)/i.test(errorMessage(error));
}

function cleanIpcError(message: string) {
  const cleaned = message
    .replace(/^Error invoking remote method '[^']+':\s*/i, "")
    .replace(/^Error:\s*/i, "")
    .replace(/^BinanceAccountError:\s*/i, "")
    .replace(/^YouleHttpError:\s*/i, "");
  if (/^(?:Upstream rate limit exceeded|HTTP 429)/i.test(cleaned)) {
    return "模型上游当前限流，请稍后重试";
  }
  return cleaned;
}
